pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for typical items
    // (likely unusable) are heavily penalized.
    if post_residual > 0 {
        let dead_threshold = 20.0f64;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 6.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits relative to residual (small waste ratio).
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 15.0;
    }

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        // Mild reward if next item can still fit in leftover space.
        score -= 5.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leftover that next item cannot use (dead space for lookahead).
        score += 8.0;
    }

    // New-bin candidate: make it moderately attractive only when current bins
    // would leave very poor fits (large dead space).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 45.0 + open_bins_count as f64 * 0.5;
        // If best alternative would leave big dead space, new bin becomes better.
        if post_residual > 0 && (bin_residual - item_size) as f64 >= 0.0 {
            // A fresh bin leaves bin_capacity - item_size residual; compare via
            // mean residual pressure: if mean residual is small (bins nearly full),
            // opening new bin is natural.
            if mean_residual < 15.0 {
                score -= 20.0;
            }
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Slight preference for fuller bins overall (mean residual coupling):
    // bins whose residual is below mean are more "committed", favor them.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1)
    // are dead space; anything below a "usable gap" threshold is heavily penalized.
    let min_item = 1u32;
    if post_residual < min_item && post_residual > 0 {
        score += 1000.0; // pure dead space
    }
    // Small gaps that likely cannot host future items (typical sizes 10..80,
    // unknown distribution so be conservative): penalize gaps < 10 strongly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Medium gaps (< 25) are semi-risky: mild penalty proportional to gap smallness.
    if post_residual >= 10 && post_residual < 25 {
        score += 8.0 * (25.0 - post_residual as f64);
    }

    // Reward tight fits (exact fill is ideal).
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: penalize spreading across many bins; encourage filling
    // existing bins when the count grows.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins whose residual is below the mean (consolidate fullness).
    score += ((bin_residual as f64) - mean_residual) * 0.3;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.35 };
        // Baseline new-bin score anchored to mean residual; opening a fresh bin
        // should lose only against bins leaving large dead space.
        score = bin_capacity as f64 * 0.9 * desperation + open_bins_count as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead-space pressure scales with how many bins are already open.
    let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    if post_residual > 0 && post_residual < 20 {
        score += 40.0 * open_pressure;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate: only attractive when it enables a good future fit
    // or when open bins would leave large dead space.
    if bin_residual == bin_capacity {
        // Slight bias against opening new bins early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 5.0;
        }
    }

    // Prefer bins with below-average residual (tighter packing).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small for the smallest item (1..100, min ~1)
    // Treat post_residual < 10 as near-dead; scale penalty nonlinearly.
    if post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual < 20 {
        score += 15.0 * (20.0 - post_residual as f64);
    }

    // Reward tight fits (small post_residual relative to bin_residual)
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 40.0 * fill_ratio * fill_ratio;
    }

    // Open bins pressure: discourage adding load to a bin when many bins are open
    // and this bin is already well-filled — prefer consolidating.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits into post_residual, reward leaving that gap
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // gap won't hold next item; penalize proportionally
        score += 0.3 * post_residual as f64;
    }

    // Mild early-stream preference to open bins and build a diverse residual pool
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: prefer it when few fitting bins or residual pool is fragmented
        score = 100.0 - 30.0 * progress - 5.0 * (fitting_bins_count as f64);
        if fitting_bins_count == 0 {
            score -= 200.0; // must open
        }
        if next_item_size > 0 && next_item_size > bin_capacity - item_size.min(bin_capacity) {
            score -= 20.0;
        }
    } else if mean_residual > 0.0 {
        // Prefer bins below mean residual (less-filled bins absorb the item)
        let dev = (bin_residual as f64 - mean_residual) / mean_residual;
        score += 5.0 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items
    // (residual below ~half the smallest plausible item is nearly useless).
    if post_residual < 25 {
        score += 6.0 * (25.0 - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many fitting bins: competition is high, slightly deprioritize mediocre fits.
    if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64 - 2.0);
    }

    // Lookahead: if next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // Next item won't fit here; penalize proportionally to wasted capacity.
            score += 3.0 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // Global state: if mean residual is high, prefer filling existing bins
    // rather than leaving slack everywhere.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (mean_residual / bin_capacity as f64) * (0.5 + progress);

    // Early in stream: mild bonus for keeping bins balanced (avoid fragmenting).
    if progress < 0.25 && post_residual >= 40 {
        score -= 2.0;
    }

    // Late in stream: prefer consolidating into fewest bins.
    if progress > 0.75 && bin_residual < bin_capacity {
        score -= 3.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 8.0 + 4.0 * (open_bins_count as f64).ln() };
        score += pressure;
        // Opening a new bin is fine if the item is large and would leave awkward residue.
        if item_size >= 60 && post_residual < 20 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item fits exactly-ish: strong reward
            score -= (20.0 - gap.min(20.0)) * 8.0;
        } else {
            // next item would not fit here; penalize proportionally to wasted potential
            score += gap * 0.5;
        }
    }

    // Tightness reward: small post_residual is good, but avoid tiny dead space (<10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead-space penalty
    }

    // Prefer bins with larger residual relative to mean (keep tight bins for tight fits)
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are very full
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        if avg_fill > 0.7 {
            score -= 30.0; // existing bins nearly full, opening is fine
        } else {
            score += 40.0; // discourage premature new bin
        }
    }

    // Early in stream: be pickier about residual quality
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // smallest plausible item (1..=10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight fit reward: the smaller the item is relative to the gap, the better.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 15.0;

    // Lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + next_item_size as f64 * 0.2;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap too small for the next item -> mild dead-space penalty.
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many open bins.
    score += open_bins_count as f64 * 0.8;

    // Prefer bins with residuals close to the mean (balanced packing).
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    // New-bin candidate: baseline slightly above a decent fit, but attractive
    // when all fits would create heavy dead space (handled via penalties above).
    if bin_residual == bin_capacity {
        score = 55.0 + step_index as f64 / (total_items.max(1) as f64) * 10.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical future items (1..=20) are unusable dead space; penalize hard.
    if post_residual > 0 && post_residual < 20 {
        score += 40.0 + (20 - post_residual) as f64 * 2.0;
    } else if post_residual == 0 {
        // Perfect fit is ideal: strong reward.
        score -= 60.0;
    } else if post_residual >= 20 && post_residual <= 35 {
        // Moderately tight residual: mild reward for compact packing.
        score -= 5.0;
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 25.0;

    // Open-bins pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening a new bin is cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += pressure * 0.8 * (0.5 + 0.5 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when no open bin offers a
    // good fit (large post_residual elsewhere) or when the next item is large.
    if bin_residual == bin_capacity {
        score = 55.0 + post_residual as f64;
        // If the next item is big, a fresh bin is more valuable.
        score -= next_item_size as f64 * 0.3;
        // Late in the stream, avoid opening bins that will barely be used.
        score += progress * 15.0;
        // If an existing bin gives a near-perfect fit, discourage new bin.
        if post_residual < 10 && bin_residual != bin_capacity {
            score += 100.0;
        }
    }

    // Lookahead coupling: reward leaving residual that can host next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to ever be useful are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 50.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Penalize gaps that can't fit the known next item (wasted for lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Reward tight fits relative to item size.
    score -= 30.0 * (item_size as f64 / bin_capacity as f64);

    // Pressure on number of open bins: prefer filling existing bins when many are open.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Align with mean residual: prefer bins below mean residual (tighter bins).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., this empty bin scores low when item barely fits elsewhere).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, offset when many bins are open
        // and current fits are poor (large post_residual elsewhere).
        score = 60.0 + 1.5 * open_bins_count as f64 - 0.2 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0; // new bin can host the pair
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chain fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            // Next item fits, leaving more dead space: mild reward proportional to leftover.
            score -= 100.0 - (post_residual - next_item_size) as f64;
        }
        // If next item cannot fit post-residual, penalize proportional to how
        // "wasted" the residual is relative to the next item size.
        else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Penalize residuals that are too small to hold the smallest possible item (1),
    // i.e. dead space, scaled by item size placed.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is chosen only when open-bin scores are bad.
        score += 120.0;
        // Fewer open bins -> opening is cheaper.
        score -= open_bins_count as f64 * 2.0;
        // Late in the stream, prefer reusing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 60.0;
        // If next item is large, a fresh bin is more valuable.
        score -= next_item_size as f64 * 0.3;
    }

    // Compare against mean residual: bins with residual far from item_size
    // (poor fit) get penalized; tight fits get rewarded.
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += fit_gap * 0.3;
    score -= (mean_residual - bin_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, 12) are "unusable" gaps
    // (items are >= 1, but small gaps waste capacity almost surely).
    if post_residual > 0 && post_residual < 12 {
        score += 40.0 + 3.0 * (12.0 - post_residual as f64);
    }

    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward bins whose residual is close to item_size (tight fit),
    // penalize loose fits leaving large slack relative to item size.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 25.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += 1.5 * open_bins_count as f64 * (1.0 - tightness.clamp(0.0, 1.0));

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, but relax the penalty
    // when the current item would leave a large awkward residual in all bins
    // or when the next item is large and a fresh bin is more useful.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 20.0;
        if post_residual >= 12 {
            new_bin_penalty -= 8.0;
        }
        if next_item_size > 0 && next_item_size as f64 >= mean_residual {
            new_bin_penalty -= 12.0;
        }
        if fitting_bins_count == 0 {
            new_bin_penalty = 0.0;
        }
        score += new_bin_penalty;
    }

    // Lookahead: if next item exactly matches this bin's post_residual,
    // strongly favor placing here (chain packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }

    // Mild preference to fill older bins early in the stream.
    score += 5.0 * (1.0 - step_index as f64 / total_items.max(1) as f64) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small post-residual is good, but only if it's "usable dead space"
    // Penalize residuals that are too small to be useful (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // 2-step lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // perfect chain match
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to tightness of the chain fit
            let chain_waste = post_residual as f64 - next_item_size as f64;
            score -= 200.0 - 3.0 * chain_waste;
        } else {
            // next item won't fit here: penalize slightly, worse for large overshoot
            let overshoot = next_item_size as f64 - post_residual as f64;
            score += 0.5 * overshoot.min(50.0);
        }
    }

    // Relative to mean residual: prefer bins that are already more filled
    // (residual below mean) so we consolidate waste
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = (mean_residual - residual_f) / mean_residual;
        score -= 30.0 * rel; // lower residual than mean -> better
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a
    // perfect lookahead chain or existing bins are badly fragmented
    if bin_residual == bin_capacity {
        let mut new_bin_score = bin_capacity as f64 + 60.0; // base penalty for opening new bin
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_score -= 100.0;
        }
        // if many open bins with large mean residual, opening a fresh bin is fine
        if mean_residual > 40.0 {
            new_bin_score -= 20.0;
        }
        score = score.min(new_bin_score) + (score - new_bin_score).max(0.0) * 0.0;
        score = new_bin_score;
        // allow new bin to win only if no existing bin is a great fit:
        // compare against typical good existing-bin scores (~post_residual small)
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 40.0;
        }
    }

    // Slight preference to fill older bins as stream progresses (reduce spread)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: small gaps (<10, or too small for next item) are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }
    // Reward exact or near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward using tight bins when few bins fit the item (last chance).
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many open bins.
    score += (open_bins_count as f64) * 0.5;

    // Prefer bins whose residual is below mean residual (tighter bins first).
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Reward leaving room for the lookahead item when possible.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Early in the stream, be more willing to open new bins (better packing later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 5.0 - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize residuals too small to hold even the smallest plausible item (1..10).
    if post_residual < 5 {
        score += 30.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = (post_residual as f64) / (item_size.max(1) as f64);
    score += 12.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open bins pressure: many open bins -> discourage spreading, prefer filling existing bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(0.0) / 10.0);
    score += 0.8 * pressure;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless post_residual is dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual >= 10 {
            score -= 10.0;
        }
    }

    // New-bin candidate: make empty bin attractive only when no open bin offers
    // a good fit (i.e., this item would leave a large dead gap in every open bin).
    if bin_residual == bin_capacity {
        // Baseline neutral score; opening new bin is favored if open bins have poor fits.
        score = bin_capacity as f64 * 0.5;
        // If the item is large relative to residual patterns, new bin is fine.
        if item_size >= 60 {
            score -= 10.0;
        }
        // Early stream: opening bins cheaply is fine.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
        // Many open bins with slack -> discourage another bin.
        if mean_residual > 30.0 && open_bins_count > 2 {
            score += 25.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 5 {
            score -= 15.0;
        } else {
            score -= 3.0;
        }
    }
    // Penalize if next item would be blocked by the resulting residual.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size.min(20) {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post-residual more than linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize large dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable gap
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty for wasting residual
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity or open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // Prefer new bin when item is big, bins are fragmented, or late in stream.
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
        score += 20.0 * fragmentation;
        score += 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative
        }
    } else {
        // Mild pressure to consolidate: fewer open bins is better.
        score += open_bins_count as f64 * 0.5;
        // Prefer bins whose residual deviates favorably from the mean
        // (use tighter-than-average bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    // Time-horizon coupling: early in the stream, be conservative (keep bins
    // flexible); late, squeeze hard.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * tightness;
    score += 4.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot hold the next item
    // (or any plausible future item) are "dead space" -> heavy penalty.
    if post_residual > 0 {
        let unusable = next_item_size > 0 && post_residual < next_item_size;
        let tiny_gap = post_residual < 10; // below minimum item size
        if unusable { score += 45.0; }
        if tiny_gap { score += 60.0; }
        // smooth penalty growing as residual shrinks into dead zone
        let r = post_residual as f64;
        score += 25.0 * (-r / 15.0).exp();
    } else {
        // perfect fit: strong reward
        score -= 80.0;
    }

    // Reward when this placement leaves room for the lookahead item (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + 10.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer tight fits.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 4.0;

    // New-bin candidate: baseline cost of opening a fresh bin, modulated by
    // how badly the item fits existing bins and how large the item is.
    if bin_residual == bin_capacity {
        let base = 55.0 + 0.3 * item_size as f64;
        // If no existing bin fits well (post_residual tiny or dead), opening is fine.
        score = base + pressure * 2.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin can chain with next item
        }
    } else {
        // Prefer bins whose residual is closest to item (tight fit bonus).
        let tightness = (bin_residual - item_size) as f64;
        score -= 12.0 * (1.0 - tightness / bin_capacity as f64);
    }

    // Late in stream: consolidate, avoid fragmentation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 8.0 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes w.r.t. common item sizes
    let pr = post_residual;
    // Reward residuals that are "perfect" (zero or in a reusable harmonic class)
    if pr == 0 {
        score -= 60.0;
    } else {
        // Penalize dead space in awkward classes (pr < 10 unusable since min item 1)
        if pr < 10 {
            score += (10 - pr) as f64 * 2.0;
        }
        // Harmonic divisibility: reward residuals divisible by small item classes
        let harmony = if pr % 10 == 0 { 8.0 }
            else if pr % 5 == 0 { 5.0 }
            else if pr % 3 == 0 { 3.0 }
            else if pr % 2 == 0 { 1.5 }
            else { 0.0 };
        score -= harmony;

        // Fraction-of-capacity thresholds on post_residual
        let frac = pr as f64 / bin_capacity as f64;
        if frac < 0.05 {
            score += 12.0; // nearly full, fine
        } else if frac < 0.15 {
            score -= 6.0;  // tight but reusable
        } else if frac < 0.35 {
            score += 2.0;
        } else {
            score -= 4.0 * (1.0 - frac); // large residual is flexible
        }
    }

    // Lookahead coupling: if next item fits post_residual, big reward
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 25.0 + (pr - next_item_size) as f64 * 0.3;
            // exact match is golden
            if next_item_size == pr {
                score -= 30.0;
            }
        } else {
            // next item cannot follow here: mild penalty scaled by gap
            score += ((next_item_size - pr) as f64).min(40.0) * 0.4;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }
    // Many fitting bins: prefer the tightest (post_residual already encodes this),
    // but add small penalty to avoid scattering across many bins
    if fitting_bins_count > 3 {
        score += 1.5;
    }

    // New-bin candidate handling: only prefer opening a new bin when current
    // placements would create bad dead space and stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New bin baseline: neutral-ish, worse than good fits, better than terrible ones
        score = 55.0 + 20.0 * progress - (open_bins_count as f64) * 0.5;
        // If item is huge, a fresh bin wastes less
        if item_size > bin_capacity * 3 / 4 {
            score -= 15.0;
        }
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's a good squeeze
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f) * 0.15;
    } else {
        score += (res_f - mean_residual) * 0.05;
    }

    // Mild preference to fill older/bins in dense regimes
    score -= (open_bins_count.min(20) as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot hold the next item (lookahead waste).
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            score += 6.0 * (next_item_size - post_residual) as f64;
        } else {
            // Reward residuals that still fit the next item.
            score -= 3.0;
        }
        // Perfect chain: residual exactly fits next item.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many fitting bins: prefer the fullest (small residual) — already via post_residual,
    // but add pressure when many bins compete.
    if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Penalize placing into bins far below mean residual (poor consolidation),
    // reward bins at or above mean residual (they are already well-filled).
    if post_residual as f64 > mean_residual + 0.5 {
        score += 0.05 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.05 * (mean_residual - post_residual as f64);
    }

    // Time horizon: early in stream, be frugal with open bins (favor consolidation);
    // late in stream, less concern about bin count, favor any reasonable fit.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * (1.0 - progress) * tightness;

    // Many open bins: discourage opening new bins / spreading items.
    if open_bins_count > 4 {
        score += 0.3 * open_bins_count as f64 * (1.0 - tightness);
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 25.0 + 10.0 * desperation + (1.0 - progress) * 8.0;
        // If next item is huge, a fresh bin's large residual is valuable.
        if next_item_size > bin_capacity / 2 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are unusable for future items (min size 1..100 unknown,
    // but gaps < ~10 are almost always dead). Penalize superlinearly.
    if post_residual > 0 && post_residual <= 10 {
        score += (11 - post_residual as i32) as f64 * 25.0;
    }
    // Medium gaps (11..=25) are risky too.
    if post_residual > 10 && post_residual <= 25 {
        score += (25.5 - post_residual as f64) * 2.0;
    }

    // Reward tight fits (perfect or near-perful packing).
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead: bonus if the next item fits exactly into the resulting gap.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0;
        } else if next_item_size < post_residual {
            let gap_after_next = post_residual - next_item_size;
            if gap_after_next <= 10 {
                score -= 30.0 - gap_after_next as f64;
            }
        } else {
            // Next item won't fit here: slight penalty proportional to wasted lookahead potential.
            score += 5.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins; encourage consolidation.
    score += open_bins_count as f64 * 3.0;

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Mean residual coupling: if this bin is much emptier than average, it's a good host.
    score -= (bin_residual as f64 - mean_residual) * 0.5;

    // New-bin candidate handling: allow opening a new bin when all existing fits are poor.
    // Empty bin has post_residual = capacity - item_size (large), so it naturally scores well
    // unless an open bin gives a tight fit. Add mild preference against proliferation early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(10) {
        score += 60.0; // dead space that likely can never be used
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit, zero waste
    } else if post_residual <= 20 {
        score += 15.0; // risky small gap
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: discourage proliferation of bins when alternatives exist.
    if bin_residual != bin_capacity {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    } else {
        // New-bin candidate: only attractive when nothing fits well.
        let poor_fit_everywhere = fitting_bins_count == 0
            || (mean_residual < item_size as f64 * 0.6);
        if poor_fit_everywhere {
            score -= 55.0;
        } else {
            score += 45.0; // prefer existing bins over opening new ones
        }
    }

    // Lookahead: if next item could use the post residual, reward leaving it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0; // exact match for lookahead
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            score += 8.0; // next item won't fit in leftover
        }
    }

    // Late in the stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - fill_ratio);

    // Mild alignment with mean residual: prefer bins close to the average state.
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: small post_residual classes are gold.
    // Class 0: post_residual == 0 (perfect fit) -> huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Integer-division thresholds on post_residual: bins that leave a
        // leftover usable by small items (<=10) are much preferred.
        let pr = post_residual;
        if pr <= 10 {
            score -= 200.0;
        } else if pr <= 20 {
            score -= 80.0;
        } else if pr <= 30 {
            score -= 30.0;
        }
        // Modulo arithmetic: leftover that is a multiple of common small sizes
        // (10, 20, 25, 50) is more likely to be filled later.
        if pr % 10 == 0 { score -= 15.0; }
        if pr % 25 == 0 { score -= 10.0; }
        if pr % 50 == 0 { score -= 12.0; }
    }

    // Coupling with lookahead: reward leftovers that exactly fit next item,
    // penalize leftovers just barely too small for next_item_size (dead space).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
        // Harmonic pairing: post_residual + next_item_size near capacity is good.
        let combo = post_residual as f64 + next_item_size as f64;
        if combo <= bin_capacity as f64 {
            score -= (bin_capacity as f64 - combo) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Prefer fuller bins over emptier ones (mean-residual anchoring).
    score += (bin_capacity as f64 - bin_residual as f64) * 0.0; // baseline kept
    score -= (mean_residual - post_residual as f64) * 0.2;

    // New-bin candidate handling: only prefer a fresh bin when all open bins
    // would leave large dead space or open_bins_count is low.
    if bin_residual == bin_capacity {
        // Penalty baseline for opening a new bin; relaxed late in stream
        // when many bins are open and mean residual is fragmented.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 60.0
            - progress * 20.0
            - (open_bins_count as f64 * 2.0);
        if fitting_bins_count == 0 { new_bin_score -= 100.0; }
        // If next item is large and current item is small, fresh bin helps.
        if next_item_size > bin_capacity / 2 && item_size <= 20 {
            new_bin_score -= 30.0;
        }
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
