    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: does the next item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain potential: reward proportional to how well next item also packs.
            score -= 10.0 + 0.05 * (post_residual - next_item_size) as f64;
        } else {
            // Post-residual unusable by next item -> mild penalty scaled by gap.
            score += 0.06 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer any bin, especially tightest.
        score -= 8.0;
    }

    // Global state: many open bins -> favor filling existing bins (consolidation).
    let pressure = open_bins_count as f64 / 8.0;
    if bin_residual < bin_capacity {
        score -= 3.0 * pressure;
    }

    // Mean-residual coupling: if this bin is below mean residual (tighter than average),
    // prefer it when the stream is late; earlier, keep looser bins flexible.
    let t = step_index as f64 / (total_items.max(1) as f64);
    let dev = mean_residual - bin_residual as f64;
    score += dev * (0.5 - t) * 0.3 - dev * t * 0.2;

    // New-bin candidate logic: opening a new bin is attractive early or when
    // item fits poorly everywhere; discourage new bins when a decent fit exists.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 0.55 * bin_capacity as f64;
        let early = t < 0.25;
        if poor_fit || early || open_bins_count == 0 {
            score -= 18.0 + 10.0 * pressure * (1.0 - t);
        } else {
            score += 10.0 + 15.0 * (1.0 - t);
        }
    }

    // Small structural bonus for using bins with residual close to item size.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste_ratio * waste_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
