pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward bins whose residual can still host the lookahead item after placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            // Gap too small for the next item: penalize proportionally to wasted potential.
            score += 8.0 * post_residual as f64 / 10.0;
        }
    }

    // Tightness reward: prefer bins where the item fills a large fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: discourage opening new bins / spreading items when many bins are open.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.5 * open_bins_count as f64;
    } else {
        score -= 1.5 * open_bins_count as f64;
    }

    // Last-chance bin: strongly prefer using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Slight preference for bins already below mean residual (consolidate waste).
    if bin_residual != bin_capacity {
        score += 0.3 * (mean_residual - bin_residual as f64);
    }

    // Mild stream-progression pressure: later in the stream, prefer reusing bins more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let ni = next_item_size as f64;
        if next_item_size <= post_residual {
            // Slack after hosting the next item: smaller leftover is better.
            let leftover_after_next = pr - ni;
            score -= 300.0 - 2.0 * leftover_after_next;
        } else {
            // Next item won't fit here: penalize wasted residual relative to mean.
            let waste = pr - mean_residual.max(pr);
            score += 50.0 + 0.5 * (ni - pr);
            let _ = waste;
        }
    }

    // Penalize creating tiny unusable dead space (fits nothing typical).
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: mildly discourage opening a new bin unless residuals
    // across open bins are already tight (mean residual low).
    if bin_residual == bin_capacity {
        score += 80.0 + 0.3 * mean_residual;
    }

    // Late in the stream, consolidate more aggressively into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 100.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Prefer bins tighter than the mean (best-fit bias vs mean_residual).
    score += 0.2 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early in the stream, be conservative; later, pack tighter.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tightness = 1.0 + 2.0 * progress; // grows 1.0 -> 3.0

    // Penalize wasted residual quadratically, scaled by stream tightness.
    score += tightness * (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Lookahead: bonus if the next item fits into the post-residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 + 0.2 * (post_residual - next_item_size) as f64;
        } else {
            // Dead space from next item's perspective; penalize when residual is stranded.
            let gap = (next_item_size - post_residual) as f64;
            if gap < 20.0 {
                score += 0.5 * gap;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Global pressure: many open bins with large mean residual -> prefer filling existing bins.
    let pressure = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    score -= 3.0 * pressure.min(20.0);

    // New-bin candidate handling: only attractive when no good existing option exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin decays with progress (later = more willing to open).
        score = 55.0 - 25.0 * progress;
        // If current bin would leave a stranded tiny residual, opening a new bin is fine.
        if bin_residual >= item_size && post_residual > 0 && post_residual < 10 && fitting_bins_count > 1 {
            score -= 10.0;
        }
        // With lookahead: new bin is good if next item also fits alongside.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear coupling: small residuals are exponentially valuable late in the stream.
    let tightness = 1.0 - pr / cap; // 0 = empty, 1 = perfectly full
    score -= 8.0 * tightness.powi(3) * (0.5 + 0.5 * progress);

    // Dead-space penalty: residuals too small for the smallest plausible item.
    let dead = (pr / cap).powi(2);
    score += 12.0 * dead * (1.0 - progress);

    // Lookahead: reward if next item fits snugly in the post residual.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            let snug = 1.0 - (pr - n) / cap;
            score -= 6.0 * snug * snug;
        } else {
            score += 4.0 * (n - pr) / cap;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Discard fragmentation across many open bins; encourage consolidation.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    // Pull toward mean residual to keep bin load balanced.
    score += 0.15 * (pr - mean_residual).abs();

    // Mild bias against opening a brand-new bin when one exists that fits.
    if bin_residual == bin_capacity && open_bins_count > 0 && fitting_bins_count > 0 {
        score += 5.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are more likely to be sealed later.
    let residue_class = post_residual % 10;
    let div_class = post_residual / 10;

    // Reward tight fits strongly: post_residual 0 is perfect.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 40.0 + (10 - post_residual) as f64 * 3.0;
    } else {
        // Penalize dead space that no item (min size 1, typical >= 10) can use.
        if post_residual < 10 {
            // unreachable given above, kept for safety
            score -= 20.0;
        } else if post_residual < 20 {
            score += 5.0;
        } else if post_residual < 30 {
            score += 15.0;
        } else {
            score += 25.0 + div_class as f64;
        }
        // Modulo bonus: residues divisible by 5 pair well with common item sizes.
        if residue_class == 0 {
            score -= 8.0;
        } else if residue_class == 5 {
            score -= 4.0;
        } else {
            score += residue_class as f64 * 0.5;
        }
    }

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 20.0 - slack as f64;
            } else {
                score += slack as f64 * 0.3;
            }
        } else {
            // Next item cannot follow here; slight penalty for wasting the slot.
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive late in the stream or when
    // mean residual across open bins is already large (fragmented state).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        // Prefer reusing open bins early; allow fresh bins when existing ones are fragmented.
        score = 150.0 - fragmentation * 120.0 + progress * 30.0 - (open_bins_count as f64) * 2.0;
    } else {
        // Mild pressure toward bins below mean residual (consolidate emptier bins).
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        }
    }

    // Slight preference for bins with larger residual when item is large.
    if item_size > bin_capacity / 2 {
        score -= (bin_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=12) are heavily penalized.
    if post_residual >= 1 && post_residual <= 12 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 15.0; // semi-dead space: only large items (>20) can use it
    }

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // extra reward if next item fits snugly (waste bounded)
        if post_residual - next_item_size <= 12 {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // penalize leaving a gap that fails the next item but is too small for anything
        if post_residual < next_item_size && post_residual < 25 {
            score += 10.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    // (avoid opening a new bin), unless it creates dead space.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual <= 12 {
            score += 40.0; // dead space worse than new bin
        } else {
            score -= 35.0;
        }
    }

    // Open-bin pressure: mildly discourage proliferation of open bins,
    // slightly stronger early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.5 - 0.5 * progress);

    // New-bin candidate: make it attractive only when it avoids dead space;
    // baseline keeps it competitive with mediocre fits.
    if bin_residual == bin_capacity {
        score -= 5.0;
    }

    // Nudge toward bins with residuals close to the mean (consolidation of slack).
    score += (post_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

