    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // next item fits here: reward proportionally to how tightly it fills
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 100.0 * fill_ratio;
        } else {
            // next item cannot use post_residual: penalize dead space
            let waste_ratio = post_residual as f64 / bin_capacity as f64;
            score += 50.0 * waste_ratio;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when open bins exist and fit is decent
    if bin_residual == bin_capacity && open_bins_count > 0 && next_item_size > 0 {
        score += 80.0;
    }

    // Late in the stream, tighten packing (avoid leftover fragmentation)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post-residual), with non-linear sharpening.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 18.0 * fit_ratio * fit_ratio;

    // Reward filling a bin nearly full.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual < 10 {
        score -= 6.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let leftover = post_residual - next_item_size;
            score -= 10.0 - 0.35 * leftover as f64;
        } else {
            // Dead space that next item cannot use: penalize proportionally.
            score += 0.25 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 14.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let pressure = open_bins_count as f64 / (1.0 + step_index as f64);
        // Penalize opening new bins normally...
        score += 20.0;
        // ...but discount the penalty when residuals are large/wasted and stream is early.
        score -= 18.0 * fragmentation * (1.0 - step_index as f64 / total_items.max(1) as f64);
        score -= pressure.min(4.0);
        // Never open a new bin if a perfect fit exists elsewhere.
        if post_residual == 0 { score += 100.0; }
    }

    // Prefer placing items into already-open bins with small residuals relative to mean
    // (consolidate waste into few bins).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.15 * dev; // bins with below-mean residual get lower score (favored)
    }

    // Late in the stream: be extra conservative with residual waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits (small post_residual), non-linearly.
    let mut score = pr * (1.0 + 0.02 * (pr / cap) * (pr / cap) * 100.0 / cap);

    // Polynomial coupling: as the stream progresses, tolerate larger residuals less.
    let tightness = 1.0 - pr / cap; // 1 = perfect fit
    score -= 30.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Reward bins whose residual matches the next item's need.
    let nr = next_item_size as f64;
    if nr > 0.0 {
        let match_quality = 1.0 - (pr - nr).abs() / cap;
        score -= 25.0 * match_quality * match_quality * match_quality;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - progress * 0.3);
    }

    // Penalize fragmenting bins relative to fleet average residual.
    let mr = mean_residual.max(0.0);
    let frag = ((pr - mr) / cap).max(-1.0);
    score += 10.0 * frag * frag;

    // Mildly discourage scattering across too many open bins late in the stream.
    score += 0.05 * open_bins_count as f64 * progress;

    // Small nudge toward filling existing bins rather than opening new ones.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) and small residues
    // that match common item sizes are valuable dead-space sinks.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit: best possible outcome
    } else {
        // Classify post_residual by divisibility into useful chunks
        // (items are 1..100, so residues divisible by 10, 5, or 25 are
        // more likely to be reusable by future items).
        let mut bonus = 0.0;
        if pr % 10 == 0 { bonus += 8.0; }
        if pr % 25 == 0 { bonus += 6.0; }
        if pr % 5 == 0 { bonus += 3.0; }
        if pr % 20 == 0 { bonus += 2.0; }
        // Small residues are low-value dead space; large residues keep options.
        if pr <= 10 { bonus -= 6.0; }
        else if pr <= 20 { bonus -= 3.0; }
        score -= bonus;

        // Integer-division threshold: residue in a "mid band" (30..60) is
        // still attractive since many item sizes land there.
        let band = pr / 20; // 0..5
        score -= match band {
            0 => 2.0,
            1 => 5.0,
            2 => 6.0,
            3 => 4.0,
            _ => 0.0,
        } as f64;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly reward; if next item fits at all, mild reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            score -= 15.0;
        } else {
            // next item cannot use this residue: penalize proportionally
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // crowded choice: prefer tighter fits, slight penalty to spread
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    // Only attractive when the item is large relative to capacity or
    // existing bins fit poorly (high mean residual mismatch).
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        let mean_waste = (mean_residual - item_size as f64).max(0.0);
        // Base cost of opening a new bin, discounted for big items.
        score = 60.0 + 40.0 * (1.0 - tightness) - 0.2 * mean_waste;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // room for the lookahead item too
        }
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no future item (min size 1..100 unknown,
    // but typical small items) can use are wasted; penalize hard when gap is small
    // and would block future placements.
    if post_residual > 0 {
        if post_residual <= 10 {
            // Unusable sliver: worst outcome for a placement.
            score += 40.0;
        } else if post_residual < item_size {
            // Gap smaller than the item itself: potentially dead space.
            score += 12.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Tight-fit reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill * fill;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor consolidating.
    score += 0.35 * open_bins_count as f64;

    // New-bin candidate: only attractive when current bin fit is poor and the
    // next item is large (fresh bin preserves full residual for it).
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 0.0 && (post_residual as f64) <= 10.0;
        let next_large = next_item_size as f64 > 0.6 * bin_capacity as f64;
        if poor_fit || next_large {
            score -= 15.0;
        } else {
            // Default: strongly discourage opening a new bin when open bins fit fine.
            score += 25.0;
        }
    }

    // Lookahead coupling: if the resulting residual can host the next item, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Stream progression: late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - fill);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead: perfect match for the next item is excellent ---
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;

        // Perfect or near-perfect fit for the next item: strong reward.
        if diff <= 3.0 {
            score -= 60.0 - 10.0 * diff;
        } else if diff <= 12.0 {
            // Graduated reward proportional to closeness of the 2-step match.
            score -= 30.0 * (1.0 - diff / 12.0);
        }

        // Penalize residuals that are slightly too small for the next item
        // (dead space that blocks the natural follow-up placement).
        if post_residual < next_item_size {
            let gap = next - post_residual as f64;
            if gap <= 10.0 {
                score += 8.0 * (1.0 - gap / 10.0); // frustrating near-miss
            }
        }

        // If this bin cannot take the next item but others might, mild penalty
        // for creating a bin that is stranded relative to the stream.
        if post_residual < next_item_size && post_residual > 0 {
            score += 5.0;
        }
    } else {
        // Last item: any placement is fine; prefer the tightest fit.
        score -= 20.0;
    }

    // --- Tightness of the current fit (classic best-fit component) ---
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 25.0 * tightness;

    // --- Compare post_residual against the mean residual of open bins ---
    // Leaving a residual far below the mean means this bin becomes "junk space".
    let pr = post_residual as f64;
    if pr > 0.0 {
        if pr < mean_residual {
            score -= 10.0 * (1.0 - pr / mean_residual.max(1.0)); // tighter than average: good
        } else {
            score += 6.0 * ((pr - mean_residual) / bin_capacity as f64); // looser than average: mild penalty
        }
    }

    // --- Dead-space penalty: small unusable leftovers (1..=9) are wasted ---
    if pr >= 1 && pr <= 9 {
        score += 18.0 - 1.5 * pr as f64;
    }

    // --- Last-chance bin: if this is the only bin that fits, strongly prefer it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit badly.
        // Baseline cost of a fresh bin: it keeps full flexibility for the future.
        let mut new_bin_score = 55.0; // intrinsic cost of consuming a fresh bin
        if next_item_size > 0 {
            // A fresh bin perfectly fits any next item; reward flexibility.
            new_bin_score -= 15.0;
        }
        // If few bins fit the item, opening a new bin is relatively better.
        if fitting_bins_count <= 2 {
            new_bin_score -= 20.0;
        }
        // Late in the stream, avoid proliferating bins with leftover space.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score += 30.0 * progress;
        // If open bins are already crowded on average, a new bin is fine.
        new_bin_score -= 5.0 * (mean_residual / bin_capacity as f64);
        score = new_bin_score + 0.001 * pr;
    }

    // --- Mild pressure against over-opening bins when many are already open ---
    score += 0.5 * open_bins_count as f64 * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Penalize dead space that nothing can use (min item size 1).
    if post_residual > 0 && post_residual < item_size {
        score += 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: opening a new bin is only attractive when the item is
    // large (would leave big unusable residue in existing bins) or when existing
    // residuals are small / poorly matched.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        // Lookahead: if next item is large, keep current bins' residuals flexible.
        let lookahead_pressure = if next_item_size > 0 {
            (next_item_size as f64 / bin_capacity as f64).powf(1.5) * 10.0
        } else {
            0.0
        };
        // Opening new bins early is cheap; late, prefer consolidation.
        score += 18.0 + 14.0 * progress + 0.6 * (open_bins_count as f64);
        // If item almost fills a fresh bin, opening is fine.
        score -= 0.25 * (item_size as f64);
        // If mean residual is small, existing bins are nearly full anyway -> new bin ok.
        score -= 0.08 * mean_residual;
        score += lookahead_pressure * (1.0 - progress);
    } else {
        // Using existing bins: reward when post-residual can still fit the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 2.0;
        }
        // Slight preference for bins with residual close to item (min waste).
        let waste_ratio = (bin_residual - item_size) as f64 / bin_residual as f64;
        score += 3.0 * waste_ratio;
        // Coupling with global state: when many bins are open and mean residual is high,
        // encourage filling the emptiest-feeling bins (large residual) to consolidate.
        score -= 0.02 * mean_residual * (open_bins_count as f64).sqrt();
    }

    // Time horizon: early in stream, be slightly exploratory (favor new bins less);
    // late, strongly consolidate.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits via non-linear polynomial of normalized post-residual.
    let mut score = norm_pr * norm_pr * (2.0 + 3.0 * norm_pr) * cap;

    // Smooth stream-progress coupling: late in the stream, penalize loose residuals more.
    score += 12.0 * progress * norm_pr * norm_pr * cap;

    // Dead-space penalty: residuals too small for typical items (below min item size 1..100 heuristic floor).
    let dead = (norm_pr - 0.05).max(0.0) * (0.25 - norm_pr).max(0.0);
    score += 40.0 * dead * (1.0 + 2.0 * progress);

    // Last-chance bonus: strongly favor using the only fitting bin to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: if next item fits into post-residual, reward this placement smoothly.
    let nxs = next_item_size as f64;
    if nxs > 0.0 && nxs <= pr {
        let slack = (pr - nxs) / cap;
        score -= 8.0 * (1.0 - slack * slack) * (1.0 + progress);
    } else if nxs > 0.0 {
        score += 4.0 * (nxs - pr) / cap;
    }

    // Mild penalty for spreading across many open bins when mean residual is high.
    score += 0.02 * (open_bins_count as f64) * (mean_residual / cap).max(0.0);

    // New-bin candidate: neutral baseline with slight early-stream preference.
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.3 * progress) - (fitting_bins_count == 0) as i32 as f64 * 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class logic: partition capacity into 4 quartile classes
    let item_class = (item_size * 4 / bin_capacity.max(1)).min(3);
    let res_class = (bin_residual * 4 / bin_capacity.max(1)).min(3);
    let post_class = (post_residual * 4 / bin_capacity.max(1)).min(3);

    // Reward class match between item and the residual it consumes
    if item_class == res_class {
        score -= 3.0;
    }

    // Reward small unusable-looking post_residuals (near-perfect fits)
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0;
    }
    // Penalize dead space: residual too small for the smallest plausible item
    if post_residual >= 1 && post_residual < 10 {
        score -= 2.0;
    }
    if post_residual >= 10 && post_residual < item_size.min(10) {
        score += 4.0; // awkward leftover band
    }

    // Modulo-style threshold: post_residual divisible bands
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 2.5; // clean harmonic leftover, reusable by classed items
    }
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 1.0;
    }

    // Lookahead (k=2): reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_class = (next_item_size * 4 / bin_capacity.max(1)).min(3);
            score -= 4.0;
            if next_class == post_class {
                score -= 2.0; // next item harmonically matches the leftover
            }
        } else {
            // leftover too small for the next item: mild penalty proportional to gap
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score += 18.0; // default: prefer existing bins
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: must open
        } else if fitting_bins_count == 1 {
            score -= 10.0; // only one poor alternative
        }
        if item_size > bin_capacity * 3 / 4 {
            score -= 12.0; // large items deserve fresh bins
        }
        if open_bins_count > 8 {
            score -= 3.0; // many open bins: consolidation pressure lower
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Mean-residual coupling: prefer bins below the mean residual (tighter bins)
    score -= 0.08 * (mean_residual - post_residual as f64);

    // Stream progression: tighten packing as the stream advances
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += t * 3.0 * (post_residual as f64 / bin_capacity.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot host the smallest
    // plausible item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 6.0 * post_residual as f64; // dead space band penalty
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fit is extremely desirable.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer
    // filling existing bins; few open bins -> opening new bins is cheaper.
    score += 0.8 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits in the post-residual, reward this
    // placement for enabling a chained fit.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item would leave this bin's residual dead anyway, slight penalty.
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Mean residual coupling: bins far below the mean residual are already
    // "holey"; prefer placing into bins with residual near/below mean.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // New-bin candidate (empty bin): base cost that grows with stream
    // progress and open-bin count, so late in the stream we consolidate.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.9
            + 1.5 * open_bins_count as f64
            + 20.0 * (step_index as f64 / (total_items.max(1) as f64));
        // But if no open bin fits well, allow the new bin.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // If the only fitting bin is a poor fit (large dead space) and the
        // item + next item would fit nicely in a fresh bin, open it.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity && fitting_bins_count == 1 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step match: post_residual equals the next item's size -> perfect chain.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post-residual can host the next item (partial reuse potential).
    if next_item_size > 0 && post_residual >= next_item_size {
        // Reward proportional to how snugly the next item fits afterwards.
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 - slack * 0.3;
    }

    // Penalize dead space: post-residual too small for the next item but nonzero.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // Compare against mean residual across open bins: prefer bins whose
    // post-residual sits near the mean (keeps options balanced).
    let pr = post_residual as f64;
    let dev = (pr - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent fitting bins exist; but if the
    // new bin would keep post_residual very large (fresh 100-residual),
    // that is attractive only when current bins would leave tiny fragments.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty that shrinks when open bins
        // are crowded (low mean residual means few good fits remain).
        let crowding = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 30.0 - 25.0 * (1.0 - crowding);
        // If the next item is large, a fresh bin preserves flexibility.
        if next_item_size > 0 && next_item_size > item_size {
            score -= 8.0;
        }
    }

    // Late in the stream, close out bins: penalize spreading across many bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 {
        score += open_bins_count as f64 * 0.5;
    }

    // Small preference for tighter fits overall.
    score += (item_size as f64 / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio through the stream (dynamic time horizon).
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    // Tight-fit reward: prefer bins where the item fills a large fraction
    // of the residual capacity (post_residual already encodes this, but
    // amplify it non-linearly).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 4.0 * fill_ratio * fill_ratio;

    // Lookahead coupling (k=2): reward placements whose leftover can still
    // host the next item; penalize dead space that blocks it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Fragmentation penalty: tiny unusable slivers are wasted capacity.
    if post_residual < 10 {
        score += 6.0;
    } else if post_residual < 20 {
        score += 2.5;
    }

    // Last-chance bonus: if this is the only bin that fits, using it avoids
    // opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: be pickier about slack usage.
        score += 0.5 * (fitting_bins_count as f64 - 2.0);
    }

    // Global state: mildly prefer bins with above-average residual
    // (they are more likely to absorb future items).
    score -= 0.05 * mean_residual;
    score += 0.03 * (post_residual as f64 - mean_residual);

    // New-bin candidate handling: penalize opening a fresh bin, but relax
    // the penalty as the stream progresses (fewer future items to place,
    // so consolidating into fresh space is less harmful) and when the new
    // bin's post_residual is small relative to the average residual
    // (i.e. the item nearly fills a whole bin).
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 14.0 - 6.0 * progress;
        if (post_residual as f64) < mean_residual * 0.6 {
            new_bin_penalty -= 6.0;
        }
        if open_bins_count == 0 {
            new_bin_penalty = 0.0;
        }
        score += new_bin_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post-residual and its non-linear polynomial coupling with progress
    let x = pr / cap;                       // fraction of capacity left after placement
    let x2 = x * x;
    let x3 = x2 * x;
    let p2 = progress * progress;

    // Base: post-residual, with smooth polynomial shaping
    let mut score = pr * (1.0 + 0.35 * p2) + 12.0 * x2 * (0.5 + progress) - 8.0 * x3;

    // Penalize dead space when lookahead cannot use it (smooth sigmoid-like gate)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let waste = (pr - nx).max(0.0) as f64;
        let gate = 1.0 / (1.0 + (-(waste / (0.25 * cap)) * (waste / (0.25 * cap))) as f64);
        score += 6.0 * waste * (0.3 + 0.7 * gate) * (0.5 + progress);
    } else {
        // Last item: strongly prefer tight fill
        score -= 15.0 * (1.0 - x);
    }

    // Last-chance bin bonus (avoid opening new bins)
    if fitting_bins_count == 1 {
        score -= 10.0 + 10.0 * progress;
    }

    // Mild preference for bins with residuals near the mean (balance load)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (1.0 - progress);

    // Slight penalty for spreading across many bins early
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    // Reward tight fits smoothly
    score -= 5.0 * (item_size as f64 / cap) * (1.0 - x);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that are "nice"
    // sizes (multiples of 10 or small enough to be near-dead).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is king
    } else if pr % 10 == 0 {
        score -= 12.0; // decile residual: likely reusable by future items
    } else if pr < 10 {
        score += 20.0; // dead space
    } else {
        // penalize awkward residuals, worse when far from a decile class
        let off = (pr % 10) as f64;
        score += 2.0 + off * 0.8;
    }

    // Integer-division threshold: does the residual still hold a "half bin"?
    if pr >= bin_capacity / 2 {
        score -= 8.0;
    } else if pr >= bin_capacity / 4 {
        score -= 2.0;
    } else {
        score += 6.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual,
    // penalize if next item is close but misses (wasted opportunity).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 55.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            if slack % 10 == 0 { score -= 10.0; } else { score += slack as f64 * 0.3; }
        } else {
            let miss = next_item_size - pr;
            score += miss as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (large item relative to mean residual).
    if bin_residual == bin_capacity {
        let tight = mean_residual < item_size as f64 * 1.15;
        if tight { score -= 18.0; } else { score += 15.0; }
    }

    // Stream progression: late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.15;

    // Many open bins: encourage consolidation by penalizing spreading.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to fit even the smallest item (size 1..)
    // are pure waste; penalize sharply in the "unusable gap" zone.
    if post_residual > 0 {
        // gap below typical small item threshold is dead space
        let dead_threshold = 10.0f64.min(post_residual as f64);
        let deadness = 1.0 - (post_residual as f64 / 20.0).min(1.0);
        score += deadness * 30.0 * (1.0 - dead_threshold / 10.0).max(0.0) * 10.0;
        // smooth extra penalty for very small gaps
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 4.0;
        }
    } else {
        // perfect fill: strong reward
        score -= 100.0;
    }

    // Reward tight fits (small post_residual relative to item size)
    let tightness = 1.0 - (post_residual as f64 / (item_size.max(1) as f64 + 1.0));
    score -= tightness * 15.0;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins already open
    if bin_residual == bin_capacity {
        // candidate is a brand-new bin
        let pressure = open_bins_count as f64 * 2.0;
        score += pressure;
        // opening a new bin is fine if lookahead item is large and residual of others is small
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 25.0;
        }
        // early in stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 20.0;
    } else {
        // mild bonus for keeping bins consolidated
        score -= 2.0;
        // if the next item fits exactly in the post residual, reward heavily
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // Penalize bins whose residual deviates badly from mean (fragmentation signal)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to zero is best.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.3;

    // Aggressive 2-step lookahead: strongly reward if next item fits post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slack left after hypothetically placing next item; smaller slack = better chain.
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - chain_slack / bin_capacity as f64);
        } else {
            // Next item won't chain; penalize proportionally to leftover dead space.
            score += 10.0 + (post_residual as f64 / bin_capacity as f64) * 15.0;
        }
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (tighter bins)
    // so loose bins stay available for future awkward items.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.2;
    } else {
        score += (residual_f - mean_residual) * 0.1;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0
            && open_bins_count > 0
            && (bin_residual - item_size).min(100) >= 0;
        // Penalize opening a new bin mildly; escalate when many bins are open.
        score += 20.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && item_size >= 60 {
            // Large item with lookahead: fresh bin can be reasonable.
            score -= 25.0;
        }
    }

    // Mild stream-progression pressure: later in stream, prefer consolidating.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space < ~10 is nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score -= 12.0;
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual, strongly reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if nx <= pr {
            let gap = pr - nx;
            if gap < 5.0 {
                score -= 20.0;
            } else {
                score -= 8.0 * (nx / pr);
            }
        } else {
            // next item won't fit here; mild penalty proportional to overshoot
            score += 0.05 * (nx - pr);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins (keep options open);
    // late in the stream, consolidate into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    score += new_bin * (30.0 - 40.0 * progress);

    // Bin-count pressure: many open bins -> discourage new bins, encourage filling.
    score += new_bin * (open_bins_count as f64).sqrt() * 5.0;

    // Mean-residual coupling: if this bin's residual is far below mean, it's an outlier bin;
    // prefer placing items there to normalize residuals.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= 0.15 * dev;
    } else {
        score += 0.05 * (-dev);
    }

    // Penalize leaving very large post_residual when item is small relative to bin (waste potential).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score += (1.0 - fill_ratio) * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 20.0 * poly;

    // Tight fits are rewarded, especially late in the stream
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Penalize dead space that next item cannot use
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += 8.0 * (ni - pr) / cap;
        } else {
            score -= 4.0 * (1.0 - ((pr - ni) / cap));
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Slight bias toward consolidating residual mass when many bins are open
    score += 2.0 * (pr - mean_residual) / cap;

    // Discourage opening new bins early unless the fit is perfect
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress) + 12.0 * norm_pr * (1.0 - norm_pr);
        if post_residual == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse when it falls into
    // "unusable" residue classes (small non-recoverable slivers).
    let post = post_residual as f64;
    if post > 0.0 {
        // Penalize slivers that no realistic item (>=1) can use well:
        if post < 10.0 {
            score += 40.0 * (10.0 - post) / 10.0;
        }
        // Harmonic reward: usable residual gets a discount proportional to
        // 1/(1+post), favoring bins whose remainder matches common item sizes.
        score -= 12.0 / (1.0 + post);
    } else {
        // Perfect fit: strongly reward closing a bin exactly.
        score -= 60.0;
    }

    // Modulo / integer-division thresholds on post_residual relative to
    // capacity fractions.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual == 0 {
        score -= 0.0; // already rewarded above
    } else if post_residual <= quarter {
        // Small residual class: risky dead space unless it's exactly usable.
        score += 15.0;
    } else if post_residual <= half {
        // Mid class: decent, mild reward.
        score -= 8.0;
    } else {
        // Large residual class: bin stays flexible, reward.
        score -= 20.0;
    }

    // Lookahead: if the next item fits the post residual, big reward
    // (chained packing). Harmonic classes: next item divides residual evenly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 25.0;
            if slack == 0 {
                score -= 30.0; // perfect chain
            } else if slack < 10 {
                score += 10.0; // creates sliver after chain
            }
            // modulo harmony: residual divisible by next item
            if slack % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
        } else {
            // Next item won't fit here; mild penalty for tight coupling.
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // Many candidates: prefer tighter fits, so penalize loosely.
        score += 3.0 * (fitting_bins_count.min(8) as f64);
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive late in the stream or when
        // current bin would leave a bad sliver. Base cost of a new bin:
        score += 55.0;
        // But if placing here would create tiny dead space, new bin wins.
        if post_residual > 0 && post_residual < 10 {
            score -= 45.0;
        }
        // Late stream: fewer future items, prefer filling existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // Many open bins already: discourage proliferation.
        score += 4.0 * (open_bins_count.min(20) as f64);
    }

    // Tight-fit bonus: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Mean residual coupling: placing into a bin below mean residual
    // (i.e., tighter than average) balances the pool.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space: residuals too small to be useful (below min item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: strongly favor bins where the next item also fits the leftover.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (post_residual as f64 - next_item_size as f64).min(20.0) * 0.5;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here; penalize slightly more if leftover is dead space.
        score += 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, discourage wasting it unless fit is tight.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Open bins pressure: with many open bins, prefer consolidating into existing bins
    // (penalize opening new bins); with few open bins, new bins are cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + progress);
    if bin_residual == bin_capacity {
        score += pressure * 2.5;
    } else {
        score -= pressure * 0.15;
    }

    // Prefer bins with residual below mean (tighter bins), gently.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Mild tightness bonus: fraction of bin used by this placement.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize leftover after two placements
            let two_step_left = post_residual - next_item_size;
            score += two_step_left as f64 * 0.8;
        } else {
            // next item won't fit here: penalize large unusable residual
            score += (post_residual as f64) * 0.3;
        }
    }

    // Prefer tight fits relative to mean residual
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 50.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // New-bin candidate: penalize so we only open when nothing else fits well
    if bin_residual == bin_capacity {
        score += 150.0 + (open_bins_count as f64) * 2.0;
        // But if lookahead suggests next item pairs well with a fresh full bin, ease penalty
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 60.0;
        }
    }

    // Mild preference for filling bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += mean_residual * 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post-residual relative to capacity)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 30.0;

    // Penalize dead space: post_residual too small to be useful for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item can fit into post_residual (chain packing)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + (next_item_size as f64 / 100.0) * 10.0;
        } else {
            score += 8.0;
        }
        // Bonus if post_residual leaves a perfect slot for the next item
        if post_residual > 0 && post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // When many bins are open, prefer consolidation into existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 2.0 * (0.5 + progress);

    // Global state: penalize bins far from the mean residual (fragmentation control)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Early phase: allow opening new bins more freely; late phase: pack tightly
    score += (1.0 - progress) * 5.0 - progress * 5.0;

    // New-bin candidate adjustment: only open new bin when existing fit is poor
    if bin_residual == bin_capacity {
        score -= 12.0 - progress * 10.0;
    }

    // Prefer bins whose residual is just above item size (minimal waste)
    let slack = (bin_residual - item_size) as f64;
    score += (slack / bin_capacity as f64).powi(3) * 40.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = norm_pr * (1.0 + 0.6 * p2 + 0.4 * p3);

    score += 12.0 * coupling;

    // Penalize large dead space more than linearly (quadratic in normalized residual)
    score += 6.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) especially early
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * (1.0 - progress);

    // Lookahead: favor bins whose residual accommodates the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 5.0 * (1.0 - slack) * (0.4 + 0.6 * progress);
        } else {
            score += 4.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate: penalize mildly so it is chosen only for poor fits
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress;
    }

    // Slight preference for bins with small residuals among many open bins
    score += 0.02 * open_bins_count as f64 * norm_pr;

    // Mean residual alignment: prefer bins near the mean
    let dev = (pr - mean_residual).abs() / cap;
    score += 3.0 * dev * (0.5 + p2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: which capacity fraction band does post_residual fall in
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap;

    // Class penalties: residuals in awkward bands (just above big item sizes) are dead space
    // Bands keyed to typical item sizes: (0,10], (10,20], (20,40], (40,60], (60,80], (80,100]
    let class = post_residual / 20; // integer division harmonic class 0..5
    let class_penalty: f64 = match class {
        0 => -30.0, // tiny residual: excellent, near-perfect fill
        1 => 10.0,  // 20..40: moderate dead space
        2 => 20.0,  // 40..60
        3 => 25.0,  // 60..80
        4 => 15.0,  // 80..100: large residual still usable
        _ => 0.0,
    };
    score += class_penalty;

    // Exact-fit harmonic: post_residual divisible by common item granularity gets reward
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        if next_item_size == post_residual {
            score -= 40.0;
        } else {
            // harmonic class of the leftover after the lookahead item
            let l2 = post_residual - next_item_size;
            score -= 12.0 - (l2 as f64) * 0.15;
        }
    } else if next_item_size > post_residual {
        // next item won't fit here: penalize leaving residual in a band next item can't use
        score += (next_item_size - post_residual) as f64 * 0.25;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets baseline penalty so we prefer open bins
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 35.0
            - 0.1 * open_bins_count as f64
            - (step_index as f64 / (total_items.max(1) as f64)) * 5.0;
        // but if no open bin fits well (post_residual large elsewhere), new bin may win
        if next_item_size > 0 && next_item_size == item_size {
            score -= 10.0; // pairing identical items in fresh bin
        }
    }

    // Mean-residual alignment: prefer bins whose residual stays near the mean (balanced packing)
    score += ((post_residual as f64 - mean_residual).abs()) * 0.1;

    // Progress modulation: late in stream, tighten up (waste less)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..10) are pure waste.
    if post_residual < 10 {
        score += 200.0 * (10.0 - post_residual as f64);
    }

    // Penalize moderately small gaps that are unlikely to fit typical future items.
    if post_residual > 0 && post_residual < 25 {
        score += 30.0 * (25.0 - post_residual as f64) / 25.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 80.0 * fill * fill;

    // Reward exact or near-exact closure of a bin.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless dead space is catastrophic).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Open-bin pressure: when many bins are open, favor filling existing ones;
    // when few are open, opening a new bin is cheaper.
    score += 8.0 * open_bins_count as f64;

    // Lookahead: if the next item fits into the post-residual, reward keeping
    // that gap; if not, penalize leaving a gap that blocks the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 40.0;
        } else if post_residual > 0 {
            score += 15.0 * (1.0 - (next_item_size - post_residual) as f64 / 100.0);
        }
    }

    // Mean residual coupling: prefer bins whose residual is close to the mean
    // (keeps a balanced pool of usable gaps) — avoid extremes.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // New-bin candidate handling: an empty bin is a neutral fallback with
    // maximum residual; give it a mild penalty so it only wins when open bins
    // would create dead space, and scale with stream progression.
    if bin_residual == bin_capacity {
        score += 60.0 + 40.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual exactly
    // matches the next item size (perfect 2-step fill).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if post >= next {
            let slack = post - next;
            // Reward tight 2-step matches: score drops as slack shrinks.
            score -= (1.0 - slack / 100.0) * 12.0;
            // Exact match: huge bonus.
            if slack == 0.0 {
                score -= 25.0;
            }
        } else if post > 0.0 {
            // Next item cannot fit here; penalize leaving dead space the
            // lookahead cannot use.
            let dead = post / 100.0;
            score += dead * 10.0;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    let diff = post_residual as f64 - mean_residual;
    score += diff * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Penalize large post-residuals overall (waste minimization), nonlinearly.
    let p = post_residual as f64 / bin_capacity as f64;
    score += p * p * 8.0;

    // Early in the stream, be more willing to open new bins (keep residuals
    // large for future flexibility); later, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, or when open bins are poor fits.
        score -= 6.0 * (1.0 - progress);
        score -= (open_bins_count as f64).min(10.0) * 0.3;
        // If the item leaves a huge residual in a fresh bin, that's fine early.
    } else {
        // Late in stream, penalize placements leaving big residuals in open bins.
        score += progress * 4.0;
    }

    // Perfect closure bonus: item exactly fills the bin.
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small leftover space.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: reward if next item fits the post residual exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // next item won't fit here: mild penalty proportional to wasted potential
        score += 6.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: prefer existing bins unless fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = post_residual as f64 > 40.0;
        let no_alternative = fitting_bins_count == 0;
        // Opening a new bin is cheap early or when alternatives are bad.
        let open_bonus = if no_alternative || poor_fit {
            -15.0 - 20.0 * (1.0 - progress)
        } else {
            50.0 + open_bins_count as f64 * 2.0
        };
        score += open_bonus;
    } else {
        // Favor bins whose residual is below mean (consolidate emptier space usage).
        let dev = bin_residual as f64 - mean_residual;
        score += 0.15 * dev;
    }

    // Mild preference for fuller bins as stream progresses.
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 8.0 * fill * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with progress
    let pr = post_residual as f64;
    let pr_n = pr / bin_capacity as f64;
    let poly = pr_n * pr_n * (1.0 + 2.0 * progress) + 0.5 * pr_n * progress * progress;

    // Penalize large post residuals more as the stream progresses (dead space matters later)
    score += 8.0 * poly;

    // Smooth reward for tight fits: quadratic decay of reward with residual
    let tightness = 1.0 - pr_n;
    score -= 6.0 * tightness * tightness * (1.0 + progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // New-bin candidate handling: penalize opening a new bin, more so early on
    if bin_residual == bin_capacity {
        let open_scale = (open_bins_count as f64 + 1.0).ln();
        score += 12.0 * open_scale * (1.0 - 0.5 * progress);
    } else {
        // Reward using existing bins, scaled by how many are open
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Lookahead coupling: if the next item fits the post-residual exactly-ish, reward
    if next_item_size > 0 && post_residual > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let fit_bonus = (-diff / 20.0) * (-diff / 20.0);
        score -= 5.0 * fit_bonus;
    }

    // Mean residual coupling: prefer bins whose residual deviates smoothly from the mean
    let dev = pr - mean_residual;
    score += 0.3 * dev * dev / (bin_capacity as f64);

    // Small smooth progress tilt to prefer filling older bins as stream advances
    score -= 1.5 * progress * (1.0 - pr_n);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic classes of post_residual (capacity fractions) ----
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarters = post_residual / (bin_capacity / 4);   // 0,1,2,3 classes
    let tenths = post_residual / (bin_capacity / 10);    // fine classes

    // Penalize dead space: residuals in awkward classes (1..9 units, 11..19, etc.)
    let awkward = (1..=9).contains(&post_residual)
        || (11..=19).contains(&post_residual)
        || (21..=24).contains(&post_residual);
    if awkward { score += 18.0; }

    // Reward residuals that are harmonic multiples (perfect fills / reusable classes)
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual % 10 == 0 && post_residual <= bin_capacity / 2 {
        score -= 22.0; // round-class residual, highly reusable
    } else if post_residual % 5 == 0 {
        score -= 8.0;
    }

    // Quarter-class logic: favor bins whose post_residual lands on a clean quarter
    score -= match quarters {
        0 => 15.0,
        1 => 5.0,
        2 => 2.0,
        _ => 0.0,
    };

    // ---- Lookahead coupling: does next_item_size fit the post_residual class? ----
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward if next item lands in the same harmonic class as the residual
            let class_match = (post_residual / 10) == (next_item_size / 10)
                || post_residual % 10 == next_item_size % 10;
            if class_match {
                score -= 25.0;
            } else {
                score -= 6.0;
            }
            // Extra reward if next item exactly consumes the residual
            if next_item_size == post_residual { score -= 30.0; }
        } else {
            // Next item won't fit here: penalize leaving large stranded residuals
            score += (pr / cap) * 20.0;
        }
    }

    // ---- Last-chance bin: strongly prefer using it to avoid a new bin ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Baseline cost of opening a fresh bin
        score = cap * 0.55;
        // Open a new bin if current open bins are fragmented (high mean residual spread)
        if mean_residual > cap * 0.35 && open_bins_count > 3 {
            score -= 12.0;
        }
        // Late in the stream, prefer consolidating into open bins
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.7 {
            score += 10.0;
        }
        // Don't open a new bin when a decent fit exists
        if post_residual <= bin_capacity / 5 {
            score += 25.0;
        }
    }

    // ---- Tightness preference: prefer bins that will be nearly full ----
    let fill = 1.0 - (pr / cap);
    score -= fill * fill * 10.0;

    // Slight preference for bins with residuals below the mean (consolidate fullness)
    score += ((mean_residual - pr) / cap).clamp(-1.0, 1.0) * 6.0;

    // Modulo-3 coupling between item class and residual class (harmonic pairing)
    if (item_size % 3) == (post_residual % 3) && post_residual > 0 {
        score -= 4.0;
    }

    // Tiny tenths-class tiebreaker
    score -= (tenths as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to be useful later are costly.
    // Treat gaps below the minimum item size as total waste.
    if post_residual < 10 {
        score += 60.0 + (10.0 - post_residual as f64) * 8.0;
    } else if post_residual <= 25 {
        // Small-but-usable gaps: moderately penalize to prefer larger leftovers
        // unless the fit is very tight.
        score += 12.0;
    }

    // Reward tight fits: fraction of bin filled by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 40.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer packing into existing bins,
    // disfavor opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: add pressure so it only wins when fits are bad.
        score += 30.0 + pressure * 2.0;
    } else {
        score -= pressure * 0.5;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 15.0;
    }
    // If next item nearly fits (small top-up needed), mild bonus.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size && (post_residual as u32) + 10 >= next_item_size {
        score += 5.0;
    }

    // Prefer bins whose residual deviates favorably from mean (below-mean residual
    // means this bin is already tight; using it keeps mean residuals high).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-match: next item fits with small slack left
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 500.0 / (1.0 + slack);
    }
    // Next item does NOT fit after this placement: penalize proportionally
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 200.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
    }

    // Penalize post_residual far above mean residual (wasteful big gap)
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when decent open bins exist
    if bin_residual == bin_capacity {
        score += 50.0 + 0.3 * open_bins_count as f64;
    }

    // Prefer tight fills overall
    score -= 0.3 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1), used as a dynamic time horizon.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base preference: tight fits (small post_residual) are good.
    // Amplify tightness reward as the stream progresses (less room for error later).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * (0.5 + progress);

    // Dead-space penalty: if the leftover cannot fit the NEXT item, this residual
    // is likely wasted. Penalize proportionally to how close post_residual is
    // to being unusable (just below next_item_size).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Leftover is reusable by the lookahead: reward a bit.
            score -= 3.0;
            // Extra reward if lookahead nearly fills the leftover perfectly.
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space: leftover too small for the next item.
            let deadness = 1.0 - (post_residual as f64 / next_item_size as f64);
            score += 10.0 * deadness;
        }
    }

    // Penalize dumping a small item into a large residual (wasteful),
    // scaled by how big the residual was relative to the item.
    let waste_ratio = item_size as f64 / bin_residual as f64;
    if waste_ratio < 0.5 {
        score += 8.0 * (0.5 - waste_ratio);
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global congestion: many open bins with large mean residual means we
    // should consolidate into existing bins rather than fragment.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 4.0 * (mean_residual / bin_capacity as f64);
    }

    // Early stream: be more willing to open new bins (favor tight fits less
    // aggressively so a fresh bin can win when fits are poor).
    if progress < 0.2 && bin_residual == bin_capacity {
        score -= 2.0;
    }

    // New-bin candidate guard: an empty bin has maximal post_residual already,
    // but discourage choosing it when a decent fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Penalize the fresh bin unless its post_residual is genuinely the best
        // (i.e., item nearly fills a whole bin).
        if post_residual as f64 > bin_capacity as f64 * 0.25 {
            score += 6.0 + 10.0 * progress;
        }
    }

    // Exact fill bonus: perfect packing is always ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let item = item_size as f64;

    let mut score = pr;

    // Quadratic penalty on large post-residuals: dead space grows super-linearly.
    score += 0.35 * (pr / cap) * (pr / cap) * cap;

    // Smooth coupling: as the stream progresses, tight fits become more valuable.
    let tightness = 1.0 - pr / cap; // 1 = perfect fit
    score -= 12.0 * tightness * (1.0 + progress);

    // Cubic interaction between progress and residual waste.
    score += 6.0 * (pr / cap) * (pr / cap) * (pr / cap) * cap * (0.5 + progress);

    // Prefer bins whose residual is close to the item (smooth Gaussian-like fit term).
    let diff = (bin_residual as f64 - item) / cap;
    score += 8.0 * diff * diff;

    // Lookahead: reward leaving room for the next item (smooth kernel).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (pr - n) / cap;
        score -= 6.0 * (-gap * gap * 8.0).exp();
    }

    // Last-chance bonus: if this is the only fitting bin, encourage using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild pressure against proliferating bins late in the stream.
    score += 0.02 * (open_bins_count as f64) * (0.3 + progress);

    // New-bin candidate: keep it neutral-to-slightly-early, penalize late.
    if bin_residual == bin_capacity {
        score += 4.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class decomposition of post_residual ---
    // Classify leftover space into residue classes modulo 10.
    let pr = post_residual;
    let residue_class = pr % 10;          // harmonic class of the leftover
    let dead_class = pr / 10;             // integer-division "dead zone" tier

    // Dead-space penalty: leftover that no future item (min size 1, typical >=10)
    // can use. Residue class 0 (perfectly divisible) is ideal; small nonzero
    // residues under 10 are the most dangerous "unusable slivers" when the
    // stream granularity is coarse.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Sliver penalty grows with stream progress (late stream => less chance to fill slivers).
    let sliver = (10 - residue_class.min(10)) as f64;
    score += 0.35 * sliver * (0.5 + progress);

    // Dead-zone tier penalty: quantized buckets of unusable space.
    score += 1.5 * dead_class as f64 * dead_class as f64 * 0.1;

    // --- Tightness reward: exact or near-exact fits ---
    if pr == 0 {
        score -= 60.0;                    // perfect fit: close the bin
    } else if residue_class == 0 {
        score -= 6.0;                     // leftover lies on the harmonic grid
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits here too: strong reward, scaled by how much it consumes.
            let consumed = next_item_size as f64 / pr.max(1) as f64;
            score -= 8.0 + 12.0 * consumed;
        } else {
            // Next item cannot follow into this leftover: penalize proportionally
            // to how badly the harmonic classes mismatch.
            let gap = (next_item_size - pr) as f64;
            score += 0.08 * gap;
            // Mismatch of residue classes => structural dead space ahead.
            if (next_item_size % 10) != residue_class {
                score += 2.0;
            }
        }
    }

    // --- Last-chance bin before opening a new one ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: its "post_residual" is capacity - item, which already
        // looks attractive; counteract so we only open when existing fits are poor.
        score += 18.0;
        // Opening is more attractive early (long horizon to fill it) and when
        // existing bins are tightly packed (mean_residual small).
        score -= 10.0 * (1.0 - progress);
        score += 0.05 * mean_residual;
        // If item is large, a fresh bin wastes little; ease the penalty.
        score -= 0.1 * item_size as f64;
    } else {
        // Mild congestion bonus: spreading load over open bins when many exist.
        score -= 0.02 * open_bins_count as f64;
        // Favor bins whose residual is harmonically aligned with the item.
        if (bin_residual % 10) == (item_size % 10) {
            score -= 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (min size 1)
    // are wasted; penalize heavily when post_residual is small but nonzero.
    if post_residual > 0 {
        // dead space zone: post_residual smaller than a typical item
        let dead_threshold = 20.0;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 3.0;
        }
    }

    // Reward tight fits (exact or near-exact fills).
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // discourage opening new bins when open_bins_count is already large.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: make the empty bin attractive only when
    // existing bins would leave large dead space.
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin, grows with stream progress
        // and number of open bins (packing pressure).
        score = 55.0 + open_bins_count as f64 * 2.0;
        // early in the stream, opening new bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 20.0;
        // if next item is large, a fresh bin is more valuable
        score -= next_item_size as f64 * 0.15;
        // if mean residual across open bins is high, no need for a new bin
        score += mean_residual * 0.3;
    }

    // Lookahead coupling: if the next item fits into this bin's post_residual,
    // reward the placement (chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        // extra reward if it fits almost exactly
        let chain_gap = post_residual - next_item_size;
        if chain_gap < 10 {
            score -= 10.0;
        }
    }
    // Penalize if next item is large and would NOT fit here after placement
    // (this bin becomes dead space for the lookahead).
    if next_item_size > post_residual && post_residual > 0 && (post_residual as f64) < 20.0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward when the next item fits exactly into the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let gap = (pr - nxt).abs();
        if nxt <= pr {
            // Next item fits: reward proportional to tightness of the match.
            score -= 3.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item does not fit: mild penalty scaled by overflow amount.
            score += 0.5 * (gap / bin_capacity as f64);
        }
    }

    // Penalize post_residuals that are small but nonzero (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Prefer bins with residual below mean residual (tight packing).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Early in the stream, be slightly more willing to open bins to build a good spread.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus penalty for too many open bins.
        score = bin_capacity as f64 - 2.0 * (1.0 - progress) + 1.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tightest fit (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score += (1.0 - fit_ratio) * 20.0;

    // Reward placements where the next item also fits the remaining space (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Penalize leaving a gap the next item cannot use.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // Last item: just minimize leftover.
        score += 5.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well (or this item would waste a lot of space elsewhere).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline penalty for opening a bin; reduced when few fitting bins exist.
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (fitting_bins_count as f64) };
        score = bin_capacity as f64 - 40.0 * scarcity;
        if fitting_bins_count == 1 {
            // Last-chance bin exists: strongly discourage opening a new bin.
            score += 60.0;
        }
        // Early in stream, opening bins is cheaper (build a portfolio).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    } else if fitting_bins_count == 1 {
        // This bin is the only one that fits: strongly favor using it.
        score -= 30.0;
    }

    // Prefer bins whose residual deviates from the mean (consolidate big gaps,
    // keep uniform bins intact for small future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= dev * 0.2;

    // Mild pressure to reduce number of open bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * progress * 0.5;

    // Discard near-empty leftover space less harshly if item is large.
    if item_size > bin_capacity / 2 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: penalize post_residual non-linearly (wasted space grows quadratically).
    let mut score = norm_post * norm_post * cap;

    // Smooth coupling: late in the stream, tight fits matter more.
    let tightness = 1.0 + progress * progress;
    score += tightness * norm_post * 10.0;

    // Reward large items filling large fractions of the bin (good utilization).
    score -= norm_item * norm_item * 20.0;

    // Lookahead: if next item fits in post_residual, reward this placement smoothly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_frac = (next_item_size as f64) / (post as f64 + 1.0);
        score -= 15.0 * fit_frac * (1.0 - fit_frac) * 4.0;
    }

    // Last-chance bonus: only one bin fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_post);
    }

    // Penalize scattering when many bins are open (fragmentation pressure).
    score += (open_bins_count as f64).ln() * norm_post * 5.0;

    // Pull toward mean residual state: prefer bins whose post residual aligns with mean.
    let dev = (post - mean_residual) / cap;
    score += dev * dev * 8.0;

    // New-bin candidate: make it mildly attractive early, less so late.
    if bin_residual == bin_capacity {
        score = cap * 0.5 - progress * cap * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residue modulo 10 defines how
    // "usable" the leftover space is for typical item sizes.
    let class = (post_residual % 10) as f64;
    // Residues that are multiples of 10 are highly reusable (harmonic class 0).
    if post_residual % 10 == 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    } else {
        // Awkward residues (1,3,7,9 style remainders) create dead space.
        score += 2.0 + class * 0.3;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Integer-division thresholds: post_residual bucketed by quarters of capacity.
    let quarter = bin_capacity / 4;
    if post_residual < quarter {
        score += 8.0; // tiny leftover = nearly wasted bin
    } else if post_residual < 2 * quarter {
        score -= 2.0;
    } else if post_residual < 3 * quarter {
        score -= 4.0;
    } else {
        score += 3.0; // large leftover means we barely used the bin
    }

    // Lookahead coupling: reward when next item fits the post-residual exactly
    // or within a harmonic class.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let nxt_left = post_residual - next_item_size;
            if nxt_left % 10 == 0 {
                score -= 10.0;
            } else if nxt_left % 5 == 0 {
                score -= 5.0;
            } else {
                score += (nxt_left % 10) as f64 * 0.5;
            }
        } else {
            // Next item cannot use leftover: mild penalty scaled by mismatch.
            score += ((next_item_size - post_residual) % 10) as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., many bins compete but fit is poor) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64;
        // Penalize opening new bins mildly; reduce penalty if current fit is bad.
        let fit_quality = (post_residual as f64 / cap) * 40.0;
        score = score - 15.0 + fit_quality * 0.5 - crowding * 0.3 - progress * 5.0;
        // An empty bin has full flexibility: reward its harmonic cleanliness.
        score -= 5.0;
    }

    // Tie-breaker: prefer bins whose residual is close to the mean residual
    // (keeps the bin profile balanced).
    score += (mean_residual - post_residual as f64).abs() * 0.15;

    // Small nudge toward tighter fits (smaller post_residual) overall.
    score += post_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: small unusable gaps (1..=10) are heavily penalized,
    // since nothing in the size range can ever fill them.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    }
    // Moderate dead space: unlikely to fit typical items, penalized softly.
    if post_residual > 10 && post_residual <= 20 {
        score += 12.0;
    }

    // Reward near-perfect fills (tight packing).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid wasting it on a bad fit,
    // but strongly prefer using it over opening a new bin when the fit is decent.
    if fitting_bins_count == 1 {
        score -= 25.0;
        if post_residual > 30 {
            score += 20.0; // poor fit into the only bin -> still somewhat penalized
        }
    }

    // Open bins pressure: with many open bins, discourage spreading; favor filling existing bins.
    let open_pressure = open_bins_count as f64;
    score += open_pressure * 1.5 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 15.0;
    }
    // If next item would leave the bin stranded, slight penalty.
    if next_item_size > 0 && next_item_size <= post_residual && (post_residual - next_item_size as u32) <= 10 && (post_residual - next_item_size as u32) > 0 {
        score += 10.0;
    }

    // New-bin candidate handling: only attractive when open bins are numerous and residuals scattered.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + open_pressure * 2.0 + mean_residual * 0.5 - progress * 5.0;
    }

    // Mean residual coupling: when mean residual is high, prefer placements that reduce variance
    // (i.e., bins far from the mean get a nudge toward selection).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= dev * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strong reward when the next item fills this bin's post-residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        // Prefer bins where next item leaves minimal secondary residual.
        score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        // Perfect two-item completion (post_residual == next_item_size) is ideal.
        if gap == 0.0 {
            score -= 60.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize dead space, worse for large leftovers.
        score += 0.5 * post_residual as f64;
        // If next item could have fit before placement, this placement may have spoiled the chain.
        if next_item_size <= bin_residual {
            score += 5.0;
        }
    }

    // Reward tight fits relative to current residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio * fit_ratio;

    // Compare post_residual against mean residual: leaving less than average is good.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer consolidating into fewer bins when many are open.
    score += 0.05 * open_bins_count as f64;

    // Early in the stream, be slightly more willing to pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * (1.0 - progress) * fit_ratio;

    // New-bin candidate handling: default cost of opening a new bin.
    if bin_residual == bin_capacity {
        // A new bin is attractive if the item is large (would leave tiny residual elsewhere)
        // or if no good lookahead pairing exists in existing bins.
        score = bin_capacity as f64 - item_size as f64;
        if fitting_bins_count <= 1 {
            // Must open a new bin anyway (or last chance): make it the natural choice.
            score -= 40.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            // Room for the next item in a fresh bin: good.
            score -= 15.0 * (1.0 - ((bin_capacity - item_size - next_item_size) as f64) / bin_capacity as f64);
        }
        // Discourage opening new bins when a decent fit exists elsewhere.
        if fitting_bins_count > 1 && item_size <= 50 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Penalize dead space that is too small to be useful later
    // (items are 1..=100, so residual < ~10 is nearly dead).
    if post_residual > 0 && post_residual < 12 {
        score += 25.0;
    }

    // Lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size as u32 {
            score -= 10.0 + 0.25 * next_item_size as f64;
        } else {
            score += 6.0;
        }
        // If next item would exactly fill this bin after current placement, big bonus.
        if post_residual == next_item_size as u32 {
            score -= 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Crowding: with many open bins, discourage spreading; prefer consolidating.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let crowd = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += 0.15 * crowd;

    // Mean residual coupling: if this bin's residual is far below mean, it is
    // already "worn" — prefer filling it rather than richer bins.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= 0.08 * dev;
    } else {
        score += 0.05 * (-dev);
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit, or when the item is large and open bins would waste space.
    if bin_residual == bin_capacity {
        // Base penalty so empty bins lose to good fits.
        score += 30.0;
        // Large items benefit from a fresh bin if open bins would leave tiny scraps.
        if item_size > bin_capacity / 2 && post_residual < 20 {
            score -= 35.0;
        }
        // Late in the stream, opening bins is cheaper than fragmenting many bins.
        if progress > 0.7 && open_bins_count > 3 {
            score -= 12.0;
        }
    }

    // Mild preference for bins whose residual is close to the item (best-fit flavor).
    let gap = (bin_residual as i64 - item_size as i64).abs() as f64;
    score += 0.05 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let nxt = next_item_size as f64;

    // Base: reward tight fits (small post_residual) with mild non-linear shaping.
    let mut score = pr * (1.0 + 0.15 * (pr / cap) * (pr / cap));

    // Smooth polynomial coupling of fill ratio with stream progress:
    // later in the stream, prefer bins that are already well-filled.
    let fill = 1.0 - (br / cap);
    score -= 6.0 * fill * fill * (0.5 + progress);

    // Dead-space penalty: post_residual too small to ever be useful is bad,
    // but so is wasteful large residual when item is small. Smooth U-shape.
    let x = pr / cap;
    score += 4.0 * x * (1.0 - x) * (1.0 - x);

    // Lookahead: reward residuals that can host the next item (smooth kernel).
    if nxt > 0.0 {
        let d = (pr - nxt) / cap;
        score -= 3.0 * (-8.0 * d * d).exp();
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: default slightly worse than a good fit, but becomes
    // attractive when existing bins would create large unusable residuals.
    if bin_residual == bin_capacity {
        score = cap * 0.6 + 0.2 * pr - 5.0 * progress * progress;
        // discourage hoarding too many open bins early
        score += 0.05 * open_bins_count as f64;
    }

    // Mild penalty for opening spread across many bins vs mean residual alignment
    score += 0.1 * ((pr - mean_residual) / cap).abs() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space (quantized in units of 10).
    let class = (post_residual / 10) as f64;

    // Reward small post_residual strongly (non-linear tightness bonus).
    score -= (cap - post_residual as f64) / cap * 12.0;

    // Penalize "dead space": leftover that is small but likely unusable
    // (below the minimum plausible item size band, i.e. class 0..2).
    if post_residual < 10 {
        score += 25.0; // nearly-full bin is great, but tiny leftover is fine
    } else if post_residual <= 20 {
        score += 6.0;  // awkward sliver: hard to fill later
    } else if post_residual >= 90 {
        score += 15.0; // bin left almost empty -> wasted open bin
    }

    // Modulo-10 harmonic coupling: leftover divisible by 10 pairs well
    // with item sizes divisible by 10 (classic instance structure).
    if post_residual % 10 == 0 && item_size % 10 == 0 {
        score -= 4.0;
    }
    // Odd leftover after odd item: still potentially pairable.
    if post_residual % 2 == 1 && next_item_size % 2 == 1 && next_item_size > 0 && next_item_size <= post_residual {
        score -= 2.5;
    }

    // Lookahead: strongly reward bins whose post_residual fits next item exactly.
    if next_item_size > 0 && next_item_size <= post_residual {
        if next_item_size == post_residual {
            score -= 20.0; // perfect two-item closure
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        score += 3.0; // this bin likely closes; slight penalty vs. leaving room
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Prefer filling bins whose residual is below the mean (consolidate waste).
    score -= (mean_residual - post_residual as f64).clamp(-50.0, 50.0) * 0.15;

    // New-bin candidate: penalize opening a bin unless current item is large
    // and no good fit exists; empty-bin residual == capacity.
    if bin_residual == bin_capacity {
        score += cap * 0.55
            + (item_size as f64) * 0.3
            + (open_bins_count as f64) * 0.5;
        if item_size >= 50 && fitting_bins_count == 0 {
            score -= cap * 0.6;
        }
        // Early stream: opening bins is cheap; late stream: consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    } else if post_residual == 0 {
        // Perfect fill is strongly rewarded.
        score -= 40.0;
    }

    // Dead space that cannot fit the lookahead item is extra bad.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 12.0;
    } else if next_item_size > 0 && post_residual >= next_item_size as f64 {
        // Reserve space that exactly accommodates the next item.
        score -= 8.0;
    }

    // Open bins pressure: penalize spreading across many bins slightly,
    // but reward using an existing bin when few fitting bins remain.
    score += 0.35 * open_bins_count as f64;
    if fitting_bins_count == 1 {
        // Last chance bin: strongly favor using it over opening a new bin.
        score -= 25.0;
    }

    // New-bin candidate: make it moderately attractive only when the fit is poor
    // or no good alternative exists (handled via the above penalties on dead space).
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    // Tight fit reward: the closer the item fills the bin, the better.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Late in the stream, prefer consolidating into tight fits even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fill_ratio;

    // Mean residual coupling: if average residual is small, tighten more.
    if (post_residual as f64) > mean_residual {
        score += 4.0;
    } else {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

