        // Perfect 2-step chain: post_residual == next_item_size -> strong bonus
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // leftover larger than next item: next item can still fit here later,
            // scale bonus by closeness of the match
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // leftover smaller than next item: dead space unless tiny
            score += 10.0 + diff * 0.3;
        }
        // If next item fits exactly into current residual (place item leaving perfect slot)
        if bin_residual == next_item_size && post_residual == 0 {
