        // Last item: strongly prefer zero post_residual
        score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Penalize creating unusable dead space (< minimum plausible item size 1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // Relative to mean residual: bins with residual below mean are tighter -> prefer them
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin, unless it enables a perfect lookahead chain
    if bin_residual == bin_capacity {
        let base_penalty = 45.0 + 2.0 * open_bins_count as f64;
        let lookahead_bonus = if next_item_size > 0 {
            if bin_residual >= item_size + next_item_size { 25.0 } else { 0.0 }
        } else {
            0.0
        };
        score += base_penalty - lookahead_bonus;
    }

    // Mild stream-progression pressure: later in stream, prefer using existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (dead space suppression).
    let tightness = (bin_residual - item_size) as f64;
    score -= 12.0 * (-tightness / 8.0).exp() * 8.0;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Penalize placing small items into large-residual bins (waste of space).
    let waste = (item_size as f64) / (bin_residual as f64).max(1.0);
    score += 10.0 * (1.0 - waste);

    // Lookahead: if the next item would fit exactly in the post residual,
    // reward this placement (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 4.0;
        } else {
            // Next item won't fit here; mild penalty proportional to leftover.
            score += 0.05 * post_residual as f64;
        }
    }

    // Time horizon: early in the stream, be more willing to open bins
    // (new-bin candidate competitive); late in the stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base score near post_residual (= capacity),
        // discounted by progress so late stream discourages new bins.
        score -= 20.0 * (1.0 - progress);
        // If no existing bin fits well, new bin is attractive.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Global state coupling: many open bins with high mean residual ->
    // encourage filling existing bins rather than spreading.
    if open_bins_count > 3 && mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= 3.0 * (mean_residual / 100.0);
    }

    // Mild penalty for leaving residuals in the awkward zone (1..=9),
    // which are nearly unusable for items >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: quadratic penalty on leftover space (dead space hurts superlinearly)
    let mut score = post * (1.0 + post / cap);

    // Smooth stream-progress coupling: later in the stream, tolerate less leftover
    score += post * progress * 0.8;

    // Reward near-perfect fits smoothly (small post_residual gets extra discount)
    let tightness = 1.0 - post / cap; // 1.0 = perfect fit
    score -= tightness * tightness * item_size as f64 * 0.5;

    // Last-chance bin: strong bonus to use it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 10.0 * tightness;
    }

    // New-bin candidate: penalize opening a new bin unless existing fit is poor
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * (1.0 - item_size as f64 / cap);
        // Opening a new bin is more attractive when many bins are already open
        // and mean residual is high (fragmentation) — smooth coupling
        score -= (open_bins_count as f64).ln().max(0.0) * 3.0;
        score -= (mean_residual / cap - 0.5).max(0.0) * 20.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post >= n {
            let gap = post - n;
            // Smoothly reward when next item fits snugly after this placement
            score -= 8.0 * (1.0 - gap / cap).max(0.0);
        } else {
            // Penalize blocking the next item
            score += 6.0 * (n - post) / cap;
        }
    }

    // Mild penalty when bin is an outlier vs mean residual (avoid fragmentation)
    score += ((bin_residual as f64 - mean_residual) / cap).abs() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: bins whose leftover falls into
    // "large" classes (can still host mid/large items) are valuable; bins whose
    // leftover is a tiny sliver are dead space.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Class index via integer division thresholds (capacity = 100 => classes of 10)
    let class = post_residual / 10; // 0..=10
    match class {
        0 => score += 30.0,                 // unusable sliver (0..9)
        1 => score += 12.0,                 // very poor leftover (10..19)
        2 => score += 4.0,                  // poor (20..29)
        3 | 4 => score -= 3.0,              // decent (30..49)
        5 | 6 => score -= 8.0,              // good (50..69)
        7 | 8 => score -= 5.0,              // half-full (70..89)
        _ => score += 2.0,                  // nearly empty: better to open/use elsewhere
    }

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead harmony: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic pairing: reward, more so when the pairing is tight.
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize if post residual is a "trap"
            // (large enough to tempt but too small for the actual next item).
            if post_residual >= 10 && post_residual < next_item_size {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no open bin harmonizes
    // (i.e., current bin is a fresh candidate too) or stream is early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Fresh bin: neutral base, but discourage when open bins have plenty of room.
        score += 10.0 + 25.0 * (mean_residual / bin_capacity as f64);
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer fuller bins relative to the fleet average.
    score -= 5.0 * (1.0 - (bin_residual as f64 / mean_residual.max(1.0))).clamp(-1.0, 1.0);

    // Modulo harmonic bonus: residuals that are multiples of 5 pair well with
    // item sizes drawn from a 10-grid.
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0, 10) are almost unusable
    // since items are >= 1 but small gaps rarely match future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    }

    // Perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits relative to residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Penalize wasting a large bin on a small item.
    score += 0.1 * (post_residual as f64 - item_size as f64).abs();

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // the empty new-bin candidate has residual == capacity, so add a
    // fixed opening cost that grows with open_bins_count.
    if bin_residual == bin_capacity {
        score += 12.0 + 1.5 * open_bins_count as f64;
    } else {
        score -= 0.5 * open_bins_count as f64;
    }

    // Prefer bins below the mean residual (more roomy bins used first
    // keeps tight bins available for small items).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Lookahead: if the next item fits exactly into the post residual,
    // this placement sets up a chain; reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score += 10.0;
        }
    }

    // Late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect two-step match: item now + next item exactly fills the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }

    // If the next item fits into the post-residual, mildly reward (keeps chain going).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + 0.3 * (post_residual - next_item_size) as f64;
    }

    // Penalize dead space smaller than the next item (unusable for lookahead).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 60.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Penalize tiny post-residuals that waste capacity (dead space trap).
    if post_residual < 10 {
        score += 40.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += 0.4 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: prefer it only when item is large and no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0
            - 0.2 * item_size as f64
            + 25.0 * (1.0 - progress)
            + if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 15.0 };
        if fitting_bins_count > 1 {
            score += 50.0; // other bins exist; opening new bin is wasteful
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;

    // Base: prefer minimal post residual (best-fit core).
    let mut score = post;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0 + (5.0 - post) * 10.0;
    }

    // Penalize dead space relative to capacity, nonlinearly.
    let waste_frac = post / cap;
    score += waste_frac * waste_frac * 120.0;

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = post - nxt;
            score -= 30.0 - slack * 0.5; // prefer exact next-fit
        } else {
            // next item can't use this bin's leftover: mild penalty proportional to gap
            score += ((nxt - post) / cap).min(1.0) * 10.0;
        }
        // If next item is huge and this bin is the only fitting one, keep it available
        if nxt > post && nxt > bin_residual as f64 * 0.9 && post > 0.0 {
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: empty bin gets an exploration cost that grows
    // with stream progress and number of open bins, but shrinks when the item is large.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let openness = (open_bins_count as f64).ln().max(0.0);
        score += 25.0 + progress * 45.0 + openness * 6.0 - item * 0.25;
        // Exception: item too large to combine with anything -> new bin is fine
        if item > 0.5 * cap {
            score -= 20.0;
        }
    }

    // Global state coupling: if mean residual across open bins is high, we have
    // slack everywhere; slightly discourage adding to already-loose bins.
    if !is_new_bin {
        let rel = (residual - mean_residual) / cap;
        score += rel * 15.0;
    }

    // Early stream: encourage keeping bins tidy (moderate waste penalty boost).
    if progress < 0.25 {
        score += waste_frac * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64 / cap;
    let pr2 = pr * pr;
    let pr3 = pr2 * pr;
    let prog2 = progress * progress;

    // Later in the stream, dead space becomes costlier: amplify residual penalty
    // with a smooth cubic-in-progress, quadratic-in-residual interaction.
    score += (pr2 * 12.0) * (0.5 + prog2 * 1.5);

    // Reward tight fits (small post_residual) increasingly as stream advances.
    score -= (1.0 - pr3) * 8.0 * (0.3 + progress);

    // Penalize bins whose residual is far from the mean residual (smooth coupling).
    let dev = (post_residual as f64 - mean_residual) / cap;
    score += dev * dev * 20.0;

    // Last-chance bin: strong smooth reward to avoid opening new bins late.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: favor bins leaving room for the next item (smooth term).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        let g = gap.abs() / cap;
        score -= (1.0 - g * g) * 6.0;
    } else {
        // Near the end, prefer filling bins as tightly as possible.
        score += pr3 * 10.0;
    }

    // Mild preference to reuse existing bins rather than open new ones,
    // decaying as the number of open bins grows (smooth saturation).
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Harmonic classes: classify post_residual by integer division into dead-space classes.
    // Post-residuals below the minimum plausible item size (use 10 as a floor guess but
    // handle 1..100 via capacity fractions) are partially dead; small slivers are bad
    // only if the next item cannot use them.
    let class = post_residual / 10; // harmonic class of dead space (0..10)
    match class {
        0 => score += 18.0,          // unusable sliver (1..10)
        1 => score += 6.0,           // small (10..20): fits only tiny items
        2 | 3 => score += 2.0,       // mid classes
        4 | 5 => score -= 2.0,       // comfortable half-bin-ish
        _ => score -= 4.0,           // large residual, plenty of room
    }

    // Next-item lookahead: penalize if next item cannot fit into post_residual.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // dead end for lookahead item
            let gap = (next_item_size - post_residual) as f64;
            score += 3.0 + gap * 0.4;
        } else {
            // next item fits: reward, especially if it nearly fills the remainder
            let fill = (post_residual - next_item_size) as f64;
            score -= 4.0 - fill * 0.08;
        }
    } else {
        // last item: prefer filling existing bins, avoid opening new bins
        score += 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin when decent open bins exist,
    // but allow it when current bins would leave bad dead space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_penalty = 8.0 + 10.0 * (1.0 - progress);
        score += open_penalty;
        // opening is more attractive when mean residual across open bins is small
        score -= (mean_residual / bin_capacity as f64) * 6.0;
    }

    // Prefer bins whose residual is below the mean (consolidate fullness).
    let mean_gap = (bin_residual as f64) - mean_residual;
    score += mean_gap * 0.05;

    // Modulo arithmetic on post_residual: residuals congruent to 0 mod item-ish
    // granularity (25 = quarter capacity) are naturally reusable.
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps harder than large ones.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny dead space is nearly worthless
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0; // small gap: only useful for tiny items
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit is heavily rewarded
    }

    // Reward leaving space exactly matching the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Penalize if post_residual can't fit the lookahead item but is close to it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Open bins pressure: with many open bins, favor filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress) * 0.3;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: make it unattractive unless residuals of open bins are tiny.
    if bin_residual == bin_capacity {
        score += 35.0 + mean_residual * 0.2;
    }

    // Mild tie-break: prefer bins whose residual is close to mean (balanced usage).
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead: reward post_residual that closely matches next item ---
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for the next item is strongly rewarded.
        score -= 40.0 * (1.0 - gap / (bin_capacity as f64));
        // Bonus if the next item fits exactly or nearly.
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Dead space that the next item cannot use: penalize proportionally.
            score += 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Last item: just minimize waste.
        score += 0.05 * post_residual as f64;
    }

    // --- Prefer tight fits relative to mean residual of open bins ---
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.30 * (mean_residual - pr);
    } else {
        score += 0.10 * (pr - mean_residual);
    }

    // --- Last-chance bin: strongly favor using it to avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if existing residuals are badly fragmented
        // and the item is large relative to typical residual space.
        let fragmentation = mean_residual / (bin_capacity as f64);
        let large_item = item_size as f64 / bin_capacity as f64;
        if fragmentation < 0.35 || large_item > 0.7 {
            score -= 18.0; // open a fresh bin
        } else {
            score += 20.0; // prefer existing bins
        }
        // Never open a new bin if this is the last chance in an existing bin.
        if fitting_bins_count == 1 {
            score += 60.0;
        }
    }

    // --- Mild late-stream pressure: consolidate as stream ends ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - pr / bin_capacity as f64);

    // Small tie-break: prefer bins with less residual overall.
    score += 0.01 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual)
    score -= (post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        } else {
            // Reward bins whose leftover fits the lookahead item
            score -= 3.0;
        }
    } else {
        // Last item: just minimize waste
        score -= 5.0;
    }

    // Last-chance bin bonus: only bin that fits -> strong reward to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Prefer new bin when current bins are very fragmented (high mean residual)
        let fragmentation = mean_residual / bin_capacity as f64;
        score = bin_capacity as f64 - fragmentation * 6.0;
        if fitting_bins_count <= 1 {
            score -= 4.0; // no good alternative, opening new bin is fine
        }
        if post_residual == 0 {
            score = 1e9; // cannot happen for empty bin, guard
        }
    }

    // Time-horizon modulation: early in stream, be conservative about residuals;
    // late in stream, favor filling bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0;
    score += (1.0 - progress) * (post_residual as f64) * 0.15;

    // Many open bins: encourage consolidation into existing bins
    if open_bins_count > 4 {
        score -= (open_bins_count as f64).ln() * 1.5;
    }

    // Discourage leaving residuals in awkward zones (e.g., just below common item sizes)
    for bad in [10u32, 20, 30, 50] {
        if post_residual > 0 && post_residual < bad && bin_residual >= bad {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Base: prefer low post-residual, with smooth non-linear shaping.
    let mut score = pr + 0.35 * pr * pr / cap;

    // Smooth polynomial coupling of fill with stream progress:
    // early on, mild fill bonus; late, aggressive consolidation.
    let w = 0.5 + 1.5 * progress * progress;
    score -= w * fill * fill * cap;

    // Dead-space penalty: residuals too small to be useful later.
    let small = (cap * 0.2 - pr).max(0.0) / cap;
    score += 12.0 * small * small;

    // Mean residual interaction: prefer bins near (below) the mean residual,
    // smooth quadratic divergence penalty.
    score += 0.08 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // Lookahead coupling: reward leaving room for the next item smoothly.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (pr - ns).max(0.0);
        score -= 6.0 * (1.0 - gap / cap) * (ns / cap);
        // penalize leaving a residual just barely too small for next item
        let miss = (ns - pr).max(0.0) / cap;
        score += 10.0 * miss * miss;
    }

    // Last-chance bin: smooth urgency bonus.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate: penalize slightly, scaled by available fitting bins.
    if bin_residual == bin_capacity {
        score += 8.0 + 3.0 * fitting_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue classes modulo 10 (capacity fractions)
    let class = post_residual % 10;
    // Dead-space penalty grows for awkward small remainders
    let dead_penalty: f64 = match class {
        0 => -20.0,               // perfect fill
        1..=3 => 25.0,            // nearly unusable slivers
        4..=6 => 5.0,             // marginal
        7..=9 => -8.0,            // large enough for typical small items
        _ => 0.0,
    };
    score += dead_penalty;

    // Integer-division threshold: post_residual bucketed by fifths of capacity
    let fifth = bin_capacity / 5;
    let bucket = post_residual / fifth;
    score += match bucket {
        0 => -15.0, // residual < 20: excellent
        1 => 0.0,
        2 => 3.0,
        3 => 8.0,
        _ => 12.0,  // mostly empty bin used for a small item
    };

    // Lookahead coupling: does next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic pair: next_item_size class matches post_residual class
            let pair_res = (post_residual - next_item_size) % 10;
            let pair_bonus: f64 = if pair_res == 0 {
                -30.0
            } else if pair_res <= 3 {
                10.0
            } else {
                -6.0
            };
            score += pair_bonus - 10.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize slightly more if this bin was the only option
            score += if fitting_bins_count == 1 { 18.0 } else { 6.0 };
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: neutral-ish base, encourage only when current bins are fragmented
    if bin_residual == bin_capacity {
        score = 55.0 - 10.0 * mean_residual / bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin
        }
        // late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Mild pressure against bin sprawl
    score += 1.5 * open_bins_count as f64;

    // Tight-fit reward: item fills most of the bin
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.8 {
        score -= 20.0 * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, or below typical
    // small-item size) are heavily penalized since nothing can fill them.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 100.0 * (dead_threshold - post_residual as f64);
    }

    // Penalize residuals too small for the lookahead item (creates stranded space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0 * (next_item_size as f64 - post_residual as f64);
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can also host the next item (good chaining).
        score -= 3.0;
    }

    // Perfect-fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing bins;
    // with few open bins, tolerate opening new ones less reluctantly.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += pressure * 0.5;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bin would leave large waste
    // relative to a fresh bin's flexibility.
    if bin_residual == bin_capacity {
        let waste = (post_residual as f64) - mean_residual;
        score += waste * 0.3;
        score += open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Strong penalty for large leftover dead space (quadratic).
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Aggressive 2-step lookahead: reward when post_residual matches next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 220.0 / (1.0 + gap);
        // Exact match for the next item is highly desirable.
        if post_residual == next_item_size {
            score -= 300.0;
        }
        // Penalize leaving space too small for the next item (dead space).
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: just minimize residual.
        score += 0.5 * post_residual as f64;
    }

    // Compare against mean residual: bins with residual below mean are tighter, prefer them.
    score += 0.8 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when current bin fit is poor.
    if bin_residual == bin_capacity {
        score += 80.0 + 40.0 * progress;
    }

    // Late in the stream, consolidate more aggressively.
    score -= 30.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect pairing: next item exactly fills the bin.
            if post_residual == next_item_size {
                score -= 30.0;
            } else {
                score -= 8.0;
            }
        } else {
            // Next item won't fit here; mild penalty proportional to leftover.
            score += 0.05 * post_residual as f64;
        }
    } else {
        // Last item in stream: just minimize post_residual.
        score -= 10.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer
    // filling existing bins rather than opening new ones.
    let pressure = mean_residual / bin_capacity as f64;
    if bin_residual < bin_capacity {
        score -= 5.0 * pressure;
    } else {
        // New-bin candidate: penalize when open bins are mostly empty (high mean
        // residual means existing bins still have room to absorb future items).
        score += 10.0 * pressure;
        // Early in the stream, opening a bin is cheap; late, it is costly.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * t;
        // Few open bins -> new bin less harmful.
        score -= 2.0 * open_bins_count as f64;
    }

    // Slight preference for bins with residual close to item_size (perfect fit shaping).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.02 * fit_gap;

    // Encourage balanced residual distribution: prefer bins whose residual
    // is near the mean residual (avoid fragmenting one bin while others stay full).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = norm_pr * norm_pr * (1.0 - t) + norm_pr * t * t;
    score += poly * cap * 0.5;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (1.0 + t) * 10.0;

    // Penalize near-mean residuals (avoiding mediocre fits)
    let dev = (pr - mean_residual).abs() / cap;
    score += dev * dev * 8.0;

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + t);
    }

    // Lookahead coupling: reward leaving room for next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = if pr >= nxt && nxt <= cap { 1.0 } else { 0.0 };
        let gap = (pr - nxt).abs() / cap;
        score -= fit_next * (1.0 - gap) * (1.0 - gap) * 12.0;
        score += (1.0 - fit_next) * 6.0 * t;
    }

    // Mild penalty for opening new bins early
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - t) + 3.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the post-residual: small remainders are "dead space"
    // classes; reward placements that land in low-waste classes.
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;
    if post_residual <= quarter {
        score -= 40.0;
    } else if post_residual <= third {
        score -= 20.0;
    } else if post_residual <= half {
        score -= 8.0;
    } else {
        // Large leftover: penalize unless the next item can use it.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        } else {
            score += 12.0;
        }
    }

    // Lookahead pairing: exact chain fit is excellent.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 500.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Fractional leftover after the hypothetical second placement.
        let post2 = post_residual - next_item_size;
        if post2 <= quarter {
            score -= 25.0;
        } else if post2 <= half {
            score -= 5.0;
        } else {
            score += 6.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here: mild penalty for wasting the slot.
        score += 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate (empty bin): only attractive when existing bins fit
    // poorly. Base cost of opening a bin, discounted late in the stream when
    // future items can still fill it.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 70.0 - 30.0 * progress;
        // If item is large (harmonic class > half), a fresh bin is natural.
        if item_size > half {
            score -= 25.0;
        }
        // If next item is also large, opening fresh may be good.
        if next_item_size > half && item_size + next_item_size > bin_capacity {
            score -= 20.0;
        }
    }

    // Prefer bins whose residual is close to the item (tight fits) relative
    // to the mean residual across open bins.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;
    if (bin_residual as f64) < mean_residual - 10.0 {
        score -= 10.0; // favor fuller-than-average bins
    }

    // Modulo arithmetic on post_residual: remainders that divide capacity
    // evenly are reusable classes.
    if post_residual > 0 && bin_capacity % post_residual == 0 {
        score -= 10.0;
    }

    // Slight preference for fewer open bins when many are open.
    score += 0.5 * open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item are "dead". Penalize them hard.
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Reward very tight fits (item nearly fills the bin).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Last-chance pressure: if this is the only bin that fits, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer reusing existing bins
    // over opening new ones; make the new-bin candidate less attractive.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 2.0 + progress * 10.0;
    }

    // Coupling with mean residual: if this bin's residual is far below the
    // mean, it is already well-packed; favor filling it further.
    score -= (mean_residual - bin_residual as f64).max(0.0) * 0.5;

    // Lookahead: if the next item fits into the post residual, bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post residual can't host the next item: mild penalty scaled by gap.
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (no dead space).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits the post residual exactly or closely.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = (post_residual as i64 - next_item_size as i64) as f64;
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
            if post_residual == next_item_size {
                score -= 500.0;
            }
        } else {
            // Next item cannot use this bin's leftover: penalize dead space.
            score += 40.0;
        }
    }

    // Penalize large post residual relative to mean residual (wasteful bin).
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Penalize opening a new bin when open bins exist and fit is decent.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && next_item_size > 0 {
            // New bin only attractive if item is large and would leave tiny waste elsewhere.
            score += 200.0 - 1.5 * item_size as f64;
            // If next item is small, keep bins consolidated.
            if next_item_size < 30 {
                score += 80.0;
            }
        } else if open_bins_count == 0 {
            score -= 300.0;
        }
    }

    // Small bonus for tight fits (post residual small).
    score -= 0.8 * (bin_capacity as f64 - post_residual as f64).min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base preference: tightest fit wins (best-fit core)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Reward exact / near-perfect fits strongly
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Penalize creating dead space that nothing can use (min item ~1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; mildly penalize wasting large residuals
            let wasted = (post_residual as f64).min(next_item_size as f64);
            score += 0.05 * wasted;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic: opening a new bin is expensive; only attractive
    // when existing fits are poor (large post_residual) or many bins are open.
    if bin_residual == bin_capacity {
        // new bin: base cost + scaling with open bins and progress
        let mut new_bin_score = 55.0 + 2.0 * open_bins_count as f64 + 10.0 * progress;
        // If the next item is large, a fresh bin keeps big capacity available
        if next_item_size >= 50 {
            new_bin_score -= 12.0;
        }
        // If mean residual across open bins is small, existing bins are full-ish,
        // so a new bin is more acceptable
        new_bin_score -= (mean_residual / bin_capacity as f64) * 10.0;
        score += new_bin_score;
    } else {
        // Existing bin: mild bonus when bin is already partially filled
        let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 5.0 * fill;
        // Slight penalty if residual is much larger than typical item sizes
        if bin_residual > 60 {
            score += 3.0;
        }
    }

    // Global pressure: many open bins with large mean residual -> consolidate,
    // penalize spreading into low-fill bins
    if open_bins_count > 3 && mean_residual > 30.0 && bin_residual == bin_capacity {
        score += 15.0;
    }

    // Early stream: be slightly more willing to open bins (build diversity)
    if progress < 0.2 && bin_residual == bin_capacity {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    let base = pr
        - 12.0 * (1.0 - progress) * pr_norm * pr_norm
        + 30.0 * progress * pr_norm * pr_norm * pr_norm;

    let mut score = base;

    // Dead-space penalty: residuals too small to ever be useful grow cost quadratically.
    let dead = 1.0 - pr_norm;
    score += 8.0 * dead * dead * (1.0 + progress);

    // Lookahead coupling: reward leaving room for the next item smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit = (pr - nx).max(0.0);
        let match_term = 1.0 - ((pr - nx) / cap).abs();
        score -= 10.0 * match_term.max(0.0) * (1.0 - progress) * (fit / cap);
        // Penalize if next item cannot fit in post residual.
        if pr < nx {
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    } else {
        // Spread load: prefer bins among many fitting candidates with tighter fit.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0) * pr_norm;
    }

    // Prefer bins with residual below mean (tight packing) via smooth term.
    score += 0.05 * (pr - mean_residual) * (0.5 + progress);

    // Slight preference for reusing open bins over opening new ones early.
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - progress) * (open_bins_count as f64).sqrt().max(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes relative to capacity
    let pr = post_residual;
    let cap = bin_capacity as f64;
    let frac = pr as f64 / cap;

    // Perfect fit: huge reward
    if pr == 0 {
        score -= 1000.0;
    }

    // Dead-space classes: residuals that are hard to fill (small leftovers)
    if pr > 0 && pr < 10 {
        score += 40.0; // unusable sliver
    } else if pr >= 10 && pr < 20 {
        score += 15.0;
    } else if pr >= 20 && pr < 40 {
        score += 5.0;
    } else if pr >= 40 && pr < 60 {
        score -= 8.0; // comfortable usable band
    }

    // Modulo-10 harmonic classes (items 1..100, often multiples of 10)
    let m = pr % 10;
    if m == 0 {
        score -= 6.0; // aligned residual
    } else if m <= 3 {
        score += 6.0; // awkward remainder
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 120.0;
        } else if next_item_size < pr {
            // how well does next item harmonically divide the residual
            let slack = pr - next_item_size;
            if slack % 10 == 0 {
                score -= 12.0;
            }
            score += (slack as f64) * 0.5;
        } else {
            // next item cannot use this residual: penalize proportionally
            score += (next_item_size as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a bin unless residuals elsewhere are terrible
    if bin_residual == bin_capacity {
        let pressure = mean_residual.min(cap);
        score = cap - 30.0 + pressure * 0.4;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // new bin is fine if it can host next item too
            score -= 5.0;
        }
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Fractional capacity coupling: prefer leaving residual near common item sizes
    if frac > 0.1 && frac < 0.5 {
        score -= frac * 10.0;
    }

    // Stream progression: late in stream, tighten packing (favor fuller bins)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual - post_residual) as f64 * 0.3;

    // Many open bins: discourage spreading; favor bins below mean residual
    if open_bins_count > 3 {
        if (post_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    // A gap is "dead" if it is too small to hold even the smallest plausible item,
    // or too small for the lookahead item when it would otherwise fit nowhere else.
    if post_residual > 0 {
        let min_item = 1u32;
        if post_residual < min_item {
            score += 1000.0; // impossible residual (should not happen, but guard)
        }
        // Non-linear dead-space penalty: gaps below ~15% of capacity are wasteful.
        let frac = post_residual as f64 / bin_capacity as f64;
        if frac < 0.15 {
            score += (0.15 - frac) * 400.0;
        }
        // If the gap cannot fit the next item, it is likely dead weight.
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            // Reward leaving exactly enough room for the lookahead item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        }
    }

    // Perfect fit bonus: tightly packing is ideal.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Reward tight fits relative to capacity.
        score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Open-bin pressure: prefer filling existing bins when many are open,
    // but only if the fit is decent; discourage spreading across many bins.
    let open_pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += open_pressure * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity or no good fit exists (post_residual == bin_capacity here).
    if bin_residual == bin_capacity {
        // Baseline score equals full residual; add a mild penalty so that decent
        // existing fits win, but remove penalty when item is large (poor-fit risk).
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 80.0;
        score += 15.0 - large_item_bonus;
    }

    // Slight preference for bins whose residual deviates from mean residual:
    // matching the mean suggests a "typical" fill state that generalizes well.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Mild stream-progression term: later in the stream, be more conservative
    // about opening bins (favor existing bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small post_residual is already good; amplify).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 60.0 * (1.0 - fit_ratio).powi(3);

    // Aggressive 2-step lookahead: if next item exactly fills post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // perfect chain placement
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this residual: penalize dead space more strongly
            let excess = (next_item_size - post_residual) as f64;
            score += 10.0 + 0.2 * excess;
        }
    }

    // Compare residual against mean residual across open bins: prefer bins with
    // tighter (smaller) residuals to consolidate load.
    score += 0.5 * (bin_residual as f64 - mean_residual).max(0.0);
    score -= 0.2 * (mean_residual - bin_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item leaves
    // terrible residual and no good chain exists.
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 80.0; // fresh bin perfectly chains with next item
        }
        if fitting_bins_count == 0 {
            score -= 35.0; // no alternative anyway
        }
    }

    // Early in the stream, be slightly more willing to open bins for flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer small post_residual, superlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Dead-space penalty: residual too small to host typical future items.
    if post_residual > 0 && post_residual < item_size.min(60) {
        score += 0.5 * (post_residual as f64);
    }

    // Lookahead coupling: if next item fits the post-residual, reward; else penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / 100.0);
        } else {
            // Waste created relative to what the next item needs.
            let waste = (post_residual + next_item_size as u32).saturating_sub(bin_capacity) as f64;
            score += 0.3 * waste;
            // If this is the only fitting bin, harsh penalty for stranding the next item.
            if fitting_bins_count == 1 && post_residual < next_item_size {
                score += 25.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the sole bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when existing
    // residuals are large (poor fits) or many bins are already open and fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = open_bins_count as f64 * mean_residual / bin_capacity as f64;
        // Penalize new bins early / when open bins are roomy and few.
        score += 45.0 + 8.0 * (open_bins_count as f64).ln().max(0.0);
        // Discount the penalty when fragmentation is high (open bins nearly full).
        score -= 40.0 * (fragmentation / (1.0 + fragmentation));
        // Late in the stream, mildly discourage new bins to consolidate.
        score += 10.0 * progress;
    }

    // Mild penalty for scattering into bins far below mean residual (keep roomy bins coherent).
    if bin_residual > mean_residual + 20.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize wasted space, scaled non-linearly by post_residual
    let mut score = post * (1.0 + 0.8 * (post / cap).powi(2));

    // Smooth interaction: large post_residual becomes more costly as stream progresses
    score += 12.0 * (post / cap) * progress * (1.0 - progress * 0.5);

    // Reward tight fits: subtract for small post_residual with smooth kernel
    let tight = 1.0 - (post / cap).powi(3);
    score -= 10.0 * tight * item_size as f64 / cap;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits the post residual, reward this placement
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post {
            score -= 8.0 * (1.0 - (next / post)) * (1.0 - progress);
        } else {
            score += 3.0 * ((next - post) / cap);
        }
    }

    // Discourage opening new bins when many bins are open with room
    if bin_residual == bin_capacity {
        let mean_fit = mean_residual / cap;
        score += 6.0 * mean_fit * (1.0 - progress) + 2.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse in certain residue classes.
    // Residuals in [1..9] are nearly useless; class them by capacity fractions.
    let cap_frac = (bin_capacity as f64) / 8.0; // 12.5 for C=100
    let dead_zone = if post_residual > 0 && (post_residual as f64) < cap_frac * 0.8 {
        1.0
    } else {
        0.0
    };
    score += dead_zone * 18.0;

    // Modulo-arithmetic penalty: residual that can't fit common small items (<=10) is dead.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit reward
    }

    // Integer-division thresholds: how many "unit chunks" of 10 remain.
    let chunks = post_residual / 10;
    score -= (chunks as f64) * 4.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate: only attractive when current bin would leave bad dead space
    // or when open bins are already crowded.
    if bin_residual == bin_capacity {
        // new bin baseline: score = full capacity; penalize mildly, discount when many bins open
        score = bin_capacity as f64 * 0.9 + (open_bins_count as f64) * 0.5;
        // if placing here leaves an awkward residual in the existing bin, new bin looks better
        if dead_zone > 0.0 {
            score -= 12.0;
        }
        // lookahead: if next item is large, a fresh bin is valuable
        if next_item_size > 0 && (next_item_size as f64) > cap_frac * 4.0 {
            score -= 10.0;
        }
        // early in stream, opening bins is cheap
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 8.0;
    }

    // Prefer bins whose residual is close to item size (tight fit) via harmonic ratio.
    if bin_residual > 0 {
        let fit_ratio = (item_size as f64) / (bin_residual as f64);
        if fit_ratio > 0.85 {
            score -= 10.0 * fit_ratio;
        }
    }

    // Coupling with mean residual: avoid draining below-average bins too fast.
    if (bin_residual as f64) < mean_residual {
        score += 3.0;
    } else {
        score -= 2.0;
    }

    // Lookahead synergy: if next item fits post_residual exactly-ish, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 5 {
            score -= 15.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 6.0; // next item can't use leftover; dead space likely
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for typical items are wasted.
    if post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual <= 20 {
        score += 15.0; // risky small gap
    } else if post_residual <= 35 {
        score += 4.0;
    } else {
        // Larger usable gaps are mildly rewarded
        score -= 2.0;
    }

    // Reward tight fits (low post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 12.0 * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones, avoid new bins
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 8.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open
        score += 20.0 + 40.0 * pressure;
    } else {
        score -= 10.0 * pressure;
    }

    // Lookahead: if next item fits into post_residual, this placement is attractive
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item would be blocked by remaining gap, slight penalty
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Early in the stream, be a bit more willing to open bins (spread items)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    // Prefer bins whose residual deviates favorably from the mean (fill the fullest bins)
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but penalize exact-fit waste
    // only when it strands a huge dead space relative to what future items need.

    if next_item_size > 0 {
        // Aggressive 2-step lookahead: reward when next item fits the post-residual
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // Exact match for the next item is the best outcome
            if gap == 0.0 {
                score -= 40.0;
            } else {
                // Reward proportional to how close next_item_size is to post_residual
                let closeness = 1.0 - gap / (post_residual as f64).max(1.0);
                score -= 30.0 * closeness * closeness;
            }
        } else {
            // Next item cannot fit in this bin's remainder: penalize leftover dead space
            // scaled by how big the stranded gap is relative to next item
            let stranded = (next_item_size - post_residual) as f64;
            score += 0.25 * stranded;
        }

        // If this bin is the last chance to fit the current item, strongly favor using it
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 25.0;
        }

        // Penalize opening a new bin when an existing bin has a good lookahead match
        if bin_residual == bin_capacity {
            // New bin: neutral-ish baseline; penalize slightly so only good reasons open it
            score += 12.0;
            // But if no open bin can fit the item, new bin must win
            if fitting_bins_count == 0 {
                score -= 1000.0;
            }
            // If next item is large relative to capacity, a fresh bin gives flexibility
            if (next_item_size as f64) > 0.5 * bin_capacity as f64 {
                score -= 8.0;
            }
        }
    } else {
        // Last item: just minimize waste
        score -= 10.0;
    }

    // Coupling with mean residual: bins with residual far below mean are "tighter"
    // candidates; placing into a below-mean-residual bin consolidates space.
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 0.15 * (mean_residual - res_f);
    } else {
        score += 0.10 * (res_f - mean_residual);
    }

    // Late in the stream, prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress;

    // Slight preference for bins with more occupants implied by low residual
    score -= 0.05 * (bin_capacity as f64 - res_f);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (waste minimization)
    score -= (item_size as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Penalize dead space that is too small to be useful later
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // next item won't fit here; penalize large leftover slightly
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer filling existing bins
    let pressure = (open_bins_count as f64).ln() * mean_residual / bin_capacity as f64;
    score += pressure * 3.0;

    // Time horizon: early in stream, be more exploratory (favor new bins less penalized);
    // late in stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 12.0;
    score += (1.0 - progress) * 4.0;

    // Prefer bins whose residual is close to mean residual (balance load)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // New-bin candidate: penalize mildly so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 20.0 + (fitting_bins_count as f64) * 5.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: post residual, with non-linear polynomial coupling to stream progress.
    // Early on, prefer tight fills (low post_residual strongly rewarded);
    // later, slightly tolerate slack since future items are fewer.
    let mut score = post * (1.0 + 0.6 * progress * norm_post);

    // Quadratic penalty on large residuals, modulated by progress.
    score += 12.0 * norm_post * norm_post * (0.5 + 0.5 * (1.0 - progress));

    // Reward near-perfect fits more aggressively (smooth via polynomial).
    score -= 8.0 * (1.0 - norm_post).powi(3);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let snug = 1.0 - ((post - nxt) / cap).abs();
            score -= 6.0 * snug * (1.0 - 0.5 * progress);
        } else {
            // Penalize creating residual that even the next item can't use.
            score += 3.0 * norm_post;
        }
    }

    // Slight preference for consolidating into bins with low mean residual
    // (filling "wasted" bins first), smoothly scaled by open bins count.
    let mean_norm = mean_residual / cap;
    score += 2.0 * (mean_norm - norm_post).max(-1.0).min(1.0) * (open_bins_count as f64).ln().max(0.0);

    // Mild penalty for opening new bins early in the stream.
    if bin_residual == bin_capacity {
        score += 4.0 * (1.0 - progress) + 2.0 * norm_post;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into residue classes mod 10
    let r = post_residual % 10;
    // Dead-space classes: leftovers of 1..9 that are hard to fill get penalized
    let dead = match r {
        0 => 0.0,           // perfectly harmonious leftover (multiple of 10)
        1..=3 => 12.0,      // tiny slivers are nearly unusable
        4..=6 => 6.0,       // mid slivers
        7..=9 => 3.0,       // larger slivers can still host small items
        _ => 0.0,
    };
    score += dead;

    // Integer-division tier of post_residual: coarser capacity fractions
    let tier = post_residual / 25; // 0,1,2,3,4 quarters
    score += (4 - tier) as f64 * 4.0;

    // Perfect fit bonus: leftover exactly zero is ideal
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: does the leftover harmonically match the next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits here: reward, especially if leftover then is harmonious
            let post2 = post_residual - next_item_size;
            if post2 % 10 == 0 { score -= 18.0; }
            if post2 == 0 { score -= 30.0; }
            score -= 8.0;
        } else {
            // next item cannot use this bin's leftover: penalize big leftovers
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor
    if bin_residual == bin_capacity {
        // baseline cost of opening a bin
        score += 35.0;
        // if mean residual is small, opening fresh is reasonable
        score -= (mean_residual * 0.6).min(30.0);
        if next_item_size > 0 && next_item_size > mean_residual {
            score -= 10.0;
        }
    }

    // Stream progression: late in the stream, tighten up, avoid waste
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.25;

    // Slight preference for bins below mean residual (balancing)
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual is "dead" if it's too small for the smallest plausible item.
    let min_item = 1.0f64;
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward post_residual that exactly matches the next item (lookahead pairing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize if post_residual is just barely below the next item (near-miss dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let pressure = open_bins_count as f64 * 0.8;
    if bin_residual != bin_capacity {
        score -= pressure * (item_size as f64 / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when the item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        // Neutral base; add penalty scaled by how many bins could fit the item.
        score += 10.0 + fitting_bins_count as f64 * 5.0;
        // But if mean residual across open bins is tiny (all bins nearly full),
        // opening a new bin is reasonable: reduce the penalty.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 12.0;
        }
        // If next item is large and current item is small, prefer a fresh bin slightly.
        if next_item_size > 0 && next_item_size > item_size * 2 && item_size < 30 {
            score -= 8.0;
        }
    }

    // Mild tie-break toward tighter fits overall.
    score += (post_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect fits (post_residual == 0)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the NEXT item exactly fills the new residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits: reward proportionally to how well it uses the leftover
            let usage = next_item_size as f64 / post_residual as f64;
            score -= 300.0 * usage;
        } else {
            // next item cannot fit here: penalize small dead space that blocks it
            score += 150.0 * (1.0 - (post_residual as f64 / next_item_size as f64));
        }
    }

    // Prefer bins with residual below mean (tight bins) when the fit is good
    if (post_residual as f64) < mean_residual {
        score -= 50.0;
    } else {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 400.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is huge or stream is late
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 200.0 + 300.0 * (1.0 - big_item) - 100.0 * progress;
        // but if next item is small, a fresh bin is fine
        if next_item_size > 0 && (next_item_size as f64) < 0.3 * bin_capacity as f64 {
            score -= 150.0;
        }
    }

    // Mild penalty for wasting large residuals on small items
    score += 0.5 * (post_residual as f64 - item_size as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
