pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress and occupancy ratios
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = item_size as f64 / cap;                    // fraction of bin consumed by this item
    let post_frac = post_residual as f64 / cap;           // leftover fraction after placement
    let pre_frac = bin_residual as f64 / cap;             // leftover fraction before placement

    // Smooth polynomial coupling: reward tight fits quadratically.
    // Tight fit => small post_frac, so -fill^2 * (1 - post_frac) rewards dense packing.
    score -= 24.0 * fill * fill * (1.0 - post_frac);

    // Dead-space penalty grows with stream progress: late in the stream,
    // small leftovers are increasingly costly (less chance to be used).
    let dead = post_frac * post_frac;
    score += 30.0 * dead * (0.4 + 0.6 * progress);

    // Cubic interaction: strongly penalize mid-range leftovers (worst usable space)
    // as progress advances; smooth, no piecewise constants.
    score += 12.0 * post_frac * (1.0 - post_frac) * (1.0 - post_frac) * progress;

    // Mean-residual coupling: placing into a bin that leaves residual near the
    // mean residual of open bins is smoothly penalized (fragmentation alignment).
    let mean_frac = (mean_residual / cap).clamp(0.0, 1.0);
    let diff = post_frac - mean_frac;
    score += 6.0 * diff * diff;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin, scaled by how well the item actually fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0 * (1.0 - post_frac);
    }

    // Lookahead coupling: if the next item fits into the post residual, reward
    // this placement smoothly; otherwise add a mild penalty.
    if next_item_size > 0 {
        let next_frac = next_item_size as f64 / cap;
        if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_frac - next_frac)) * (1.0 - progress);
        } else {
            let gap = (next_item_size - post_residual) as f64 / cap;
            score += 8.0 * gap * (1.0 - post_frac);
        }
    }

    // New-bin candidate handling: an empty bin has pre_frac == 1.0. It should only
    // win when open bins fit poorly — penalize it progressively with occupancy
    // of the item and number of fitting alternatives.
    if (pre_frac - 1.0).abs() < 1e-9 {
        let alt = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        score += 14.0 + 6.0 * (alt.ln() + 1.0) + 20.0 * (1.0 - fill) * (1.0 - progress);
        // Late in the stream, opening fresh bins is relatively cheaper.
        score -= 10.0 * progress;
    }

    // Mild preference for bins with smaller initial residual (best-fit flavor),
    // smoothly weighted.
    score += 4.0 * pre_frac * (1.0 - fill);

    // Open-bins pressure: with many open bins, slightly prefer consolidating
    // into existing ones rather than spreading.
    score += (open_bins_count as f64).ln().max(0.0) * 1.5 * post_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit classes are golden.
    let pr = post_residual;
    if pr == 0 {
        score -= 100.0; // perfect fit
    } else if pr <= 5 {
        score -= 40.0;
    } else if pr <= 10 {
        score -= 20.0;
    } else {
        // modulo classes: residuals divisible by small harmonics are reusable
        if pr % 10 == 0 {
            score -= 10.0;
        } else if pr % 5 == 0 {
            score -= 5.0;
        }
        // dead-space penalty grows for awkward residues
        if pr < 10 {
            score += 25.0; // unusable sliver
        }
    }

    // Lookahead coupling: can next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 15.0;
        } else {
            // next item won't fit here; penalize large wasted residuals less if small
            let waste = pr as f64;
            score += waste * 0.1;
        }
        // next item fits exactly into post_residual -> strong reward
        if next_item_size == pr {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize mildly, but allow if item is huge relative to residual
    if bin_residual == bin_capacity {
        score += 20.0;
        // opening new bin is good for very large items with no tight fit available
        if item_size >= 70 && !(fitting_bins_count > 0 && post_residual <= 10) {
            score -= 45.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && item_size >= 60 {
            score -= 10.0;
        }
    }

    // Progress-based tightening: late in stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64) * 0.3 * progress;

    // Prefer bins with below-mean residual (denser bins first)
    let diff = (bin_residual as f64) - mean_residual;
    score += diff * 0.15;

    // Many open bins: encourage consolidation into existing bins
    if open_bins_count > 8 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (1.0 - (post_residual as f64) / 10.0) + 15.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 8.0;
    }

    // Reward tight fits (perfect fill strongly favored).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 5.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, favor this bin.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= post_residual + 10 {
        // next item would create dead space here; slight penalty
        score += 5.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make opening a new bin costly unless the current item
    // is large relative to residuals and fits poorly elsewhere.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 3.0;
        let waste = (bin_capacity - item_size) as f64;
        score += 25.0 + pressure + waste * 0.2;
        // Allow new bin when item is big and would leave a bad gap in any bin.
        if item_size >= 60 && post_residual <= 10 {
            score -= 45.0;
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first).
    score += ((bin_residual as f64) - mean_residual) * 0.3;

    // Slight late-stream tightening: as stream progresses, avoid sloppy placements.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: perfect match with next item is a huge reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score += 0.6 * diff;
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize leaving residual that is too small for the next item (dead space).
        if post_residual < next_item_size && post_residual > 0 {
            score += 12.0;
        }
    } else {
        // Last item: minimize residual strictly.
        score += 5.0;
    }

    // Reward tight fits relative to bin capacity.
    score -= 0.8 * (item_size as f64 / bin_capacity as f64) * 20.0;

    // Penalize bins whose residual is far below the mean (they are already tight;
    // prefer consuming slack from bins with large residuals).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin is a good home.
    if bin_residual == bin_capacity {
        let slack_pressure = mean_residual / bin_capacity as f64;
        score += 40.0 * slack_pressure + 8.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // a fresh bin can host the next item too
        }
    }

    // Mild late-stream conservatism: keep bins tight as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits (small post_residual relative to capacity).
    score -= 12.0 * (1.0 - post / cap);

    // Penalize dead space that is too small for typical items.
    if post > 0.0 && post < 10.0 {
        score += 8.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let slack = post - next_item_size as f64;
        score -= 10.0 * (1.0 - slack / cap);
    }
    // If next item cannot fit here, mild penalty for wasting the lookahead slot.
    if next_item_size > post_residual {
        score += 3.0;
    }

    // Last-chance bin: strongly avoid opening a new bin when only this one fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Time horizon: early in stream, be conservative (prefer new bins for large items);
    // late in stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 6.0;

    // Global state: many open bins with high mean residual -> encourage consolidation.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 2.0 * (mean_residual - item_size as f64) / cap;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and no good fits exist elsewhere.
    if bin_residual == bin_capacity {
        score += 14.0;
        if item_size as f64 > 0.6 * cap && (fitting_bins_count == 0 || mean_residual < item_size as f64) {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let prn = pr / c; // normalized post residual in [0,1]
    let p2 = progress * progress;
    let p3 = p2 * progress;

    // Smoothly increasing penalty on large residuals as the stream progresses:
    // early on, wasted space is cheap; late in the stream it is costly.
    let poly = 1.0 + 2.5 * progress + 4.0 * p2 + 3.0 * p3;
    score += 18.0 * prn * prn * poly;

    // Interaction: residual relative to mean residual of open bins.
    // A bin with much larger residual than average is a good host; penalize
    // bins whose residual is already tight relative to the fleet average.
    let dev = pr - mean_residual;
    score -= 0.6 * dev * (1.0 + progress);

    // Reward near-perfect fits with a smooth quadratic trough at pr == 0.
    score -= 25.0 * (1.0 - prn) * (1.0 - prn) * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // over opening a new bin (smooth exponential falloff with residual).
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - prn);
    }

    // Lookahead coupling: if the next item fits the post residual exactly,
    // reward; if post residual is just barely too small for the next item,
    // mildly penalize (dead space trap).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            let fit_quality = 1.0 - (pr - n) / c;
            score -= 10.0 * fit_quality * fit_quality;
        } else {
            let miss = (n - pr) / c;
            score += 8.0 * miss * miss;
        }
    }

    // Mild penalty when many bins are open and residual is large: encourage
    // consolidation rather than spreading.
    let ob = open_bins_count as f64;
    score += 0.02 * ob * prn * prn * c;

    // New-bin candidate (empty bin): keep it attractive only when residuals
    // across open bins are tight or item is large.
    if bin_residual == bin_capacity {
        let tight = (mean_residual / c).powi(2);
        score += 15.0 * (1.0 - tight) - 0.5 * item_size as f64 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into capacity fractions.
    let pr = post_residual;
    let class = if pr == 0 { 0 }
        else if pr <= bin_capacity / 8 { 1 }
        else if pr <= bin_capacity / 4 { 2 }
        else if pr <= bin_capacity / 2 { 3 }
        else { 4 };

    // Reward tight fits strongly (non-linear in class).
    score -= match class {
        0 => 30.0,
        1 => 18.0,
        2 => 10.0,
        3 => 3.0,
        _ => 0.0,
    };

    // Modulo-style bonus: leftover that is a "nice" residue (divisible by common item sizes)
    // is more likely reusable by future items.
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        else if pr % 5 == 0 { score -= 3.0; }
        if pr >= 10 && pr <= 80 { score -= 2.0; } // reusable by any item
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / cap);
        if pr == next_item_size { score -= 15.0; }
    } else if next_item_size > pr && pr > 0 {
        // dead space relative to lookahead
        score += (next_item_size - pr) as f64 * 0.25;
    }

    // Last fitting bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: penalize unless current fit is poor or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0;
        if item_size as f64 > 0.6 * cap { score -= 15.0; } // big items deserve fresh bins
        if fitting_bins_count == 0 { score -= 40.0; }
        if progress < 0.2 { score -= 5.0; }
        if open_bins_count == 0 { score -= 50.0; }
    }

    // Slight preference to fill bins below mean residual (balance avoidance of many half-full bins).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.05 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for typical future items are worthless.
    // If post_residual cannot accommodate even a minimal item, it is pure dead space -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Penalize "awkward" gaps: residual that is small relative to the smallest plausible item
    // but still nonzero. Use a non-linear dead-space curve on post_residual.
    let dead_space = if post_residual == 0 { 0.0 } else {
        let r = post_residual as f64;
        // gaps below ~25 are unlikely to be filled by future items; penalize quadratically
        if r < 25.0 { 60.0 * (25.0 - r) / 25.0 * (25.0 - r) / 25.0 } else { 0.0 }
    };
    score += dead_space;

    // Reward tight fits (post_residual near 0 but still valid placement).
    if post_residual == 0 {
        score -= 200.0; // perfect fill
    }

    // Open-bins pressure: when many bins are open, strongly prefer using an existing bin
    // over opening new ones. Penalize the new-bin candidate (bin_residual == bin_capacity)
    // proportionally to open_bins_count.
    let is_new_bin_candidate = bin_residual == bin_capacity;
    if is_new_bin_candidate {
        score += 40.0 + 12.0 * open_bins_count as f64;
    } else {
        // Mild reward for reusing existing bins, scaled by pressure.
        score -= (2.0 + 0.5 * open_bins_count as f64).min(15.0);
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin unless fit is awful.
    if fitting_bins_count == 1 && !is_new_bin_candidate {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 100.0;
        } else if gap < 10.0 {
            score -= 40.0;
        }
    }
    // If next item cannot fit in post_residual, the leftover is likely dead space.
    if next_item_size > post_residual && post_residual > 0 {
        score += 15.0;
    }

    // Stream progression: early in the stream, be more willing to open bins (future flexibility);
    // later, consolidate to avoid leftover open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if is_new_bin_candidate {
        score -= 20.0 * (1.0 - progress);
    }

    // Mean residual coupling: if this bin's residual is far below the mean, it is an outlier
    // small gap; penalize slightly to keep bin residuals homogeneous and usable.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual - 15.0 {
        score += 0.5 * (mean_residual - residual_f);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect match with lookahead item: strongly reward.
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let nis = next_item_size as f64;
        let diff = (pr - nis).abs();
        // Exact fit for next item -> near-perfect bin.
        if diff == 0.0 {
            score -= 60.0;
        } else if diff <= 10.0 {
            score -= 60.0 * (1.0 - diff / 10.0);
        } else {
            // Too-large leftover is dead space unless it can still fit typical items.
            score += (diff - 10.0).min(80.0) * 0.35;
        }
        // Reward leaving room that comfortably exceeds next item (usable slack).
        if pr >= nis && pr - nis <= 30.0 {
            score -= 8.0;
        }
    } else {
        // Last item: just minimize leftover.
        score += 0.0;
    }

    // Zero residual is ideal: waste nothing.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Small unusable residue (1..9) is dead space: penalize.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Compare against mean residual across open bins:
    // prefer bins whose residual is already tight (below average).
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.25;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.15;
    }

    // Last-chance bin: if this is the only fitting bin, using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): prefer it only when open bins would be badly fragmented.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; grows with how many bins are already open.
        let mut new_bin_score = 55.0 + 1.5 * open_bins_count as f64;
        // If lookahead item is large relative to capacity, fresh bin is attractive.
        if next_item_size as f64 > 0.6 * bin_capacity as f64 {
            new_bin_score -= 15.0;
        }
        // Early in stream: cheaper to open bins.
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.3 {
            new_bin_score -= 10.0;
        }
        // If this bin's placement would leave terrible residue, new bin looks better.
        if post_residual > 0 && post_residual < 10 {
            new_bin_score -= 30.0;
        }
        score = score.min(new_bin_score);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Reward placements where the lookahead item also fits the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 10.0 * (next_item_size as f64 / 100.0);
        } else {
            // Penalize leaving a dead space smaller than the next item.
            score += 8.0 * (1.0 - post_residual as f64 / (next_item_size as f64).max(1.0));
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins with small residuals exist,
    // but allow it when residuals are large (poor fits everywhere).
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // If mean residual is small, open bins are nearly full -> new bin is fine.
        score += 10.0 * pressure;
        // Early in stream, prefer consolidating; later, opening new bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
        // More open bins -> slight penalty for adding yet another.
        score += 0.5 * open_bins_count as f64;
    } else {
        // Using an existing bin reduces bin count pressure: small reward.
        score -= 3.0;
    }

    // Slight preference for bins below the mean residual (balance loads).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;

    // Base: prefer filling bins tightly (small post_residual).
    let mut score = post;

    // Non-linear dead-space penalty: very small post_residual is great,
    // but moderately small leftovers that nothing can use are bad.
    // Smooth coupling via squared normalized post_residual.
    let norm_post = post / cap;
    score += 18.0 * norm_post * norm_post * (1.0 - progress);

    // Perfect-fit reward: smooth, strongest when post_residual is tiny.
    let perfect = 1.0 - (post / cap).min(1.0);
    score -= 12.0 * perfect * perfect * perfect;

    // Lookahead coupling: reward if next item fits into post_residual,
    // penalize if post_residual is just barely too small for next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 8.0 * (1.0 - slack) * (1.0 - progress);
        } else {
            let miss = (nxt - post) / cap;
            score += 6.0 * miss * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize opening a new bin unless existing bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap;
        score = cap * 0.6 + 25.0 * (1.0 - crowding) + 15.0 * progress;
        // Allow new bin when it would leave a large usable residual for future big items.
        score -= 5.0 * (item / cap);
    } else {
        // Slight preference for bins whose residual deviates from the mean
        // (consolidate space in similar bins).
        let dev = (post - mean_residual).abs() / cap;
        score += 3.0 * dev * dev;
    }

    // Mild stream-progress coupling: later in stream, be greedier about tight fits.
    score *= 1.0 + 0.15 * progress * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Fill-ratio quadratic reward: strongly favor bins that become nearly full.
    let fill = 1.0 - pr / cap;
    score -= 40.0 * fill * fill;

    // Perfect closure bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Harmonic classes on post_residual via modulo arithmetic:
    // residual classes mod (capacity/4) get different treatments.
    let quarter = bin_capacity / 4;
    let q = quarter as f64;
    if post_residual > 0 {
        let cls = (post_residual % quarter) as f64 / q; // 0..1 within class
        match post_residual / quarter {
            0 => score -= 8.0 * (1.0 - cls),          // tiny leftovers: mild extra reward
            1 => score += 3.0 * cls,                   // awkward mid-small class: slight penalty
            2 => score -= 4.0 * (1.0 - cls),           // mid class: mild reward
            _ => score += 2.0 * cls,                   // large residual: slight penalty
        }
        // Integer-division threshold: residual divisible by common item sizes is reusable.
        if post_residual % 10 == 0 && post_residual > 0 {
            score -= 5.0;
        }
        if post_residual % 25 == 0 && post_residual > 0 {
            score -= 4.0;
        }
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / cap);
        } else if post_residual > 0 {
            score += 6.0; // dead space relative to lookahead
        }
    }

    // Last-chance bin: if this is the only open bin that fits, use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate penalty: discourage opening a new bin when fits exist,
    // scaled by item size (large items justify new bins more).
    if bin_residual == bin_capacity {
        score += 20.0 + 0.3 * item_size as f64;
    }

    // Stream progression: later in the stream, consolidation matters more.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * t * fill;

    // Mild pull toward bins with below-average residual (balance avoidance of waste).
    score += 0.1 * (mean_residual - pr).max(-20.0).min(20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the minimum plausible future item (<= 10) are pure waste.
    let min_future: u32 = 10;
    if post_residual < min_future && post_residual > 0 {
        // Unusable sliver: penalize heavily, proportional to how dead it is.
        score += 40.0 + (min_future - post_residual) as f64 * 8.0;
    } else {
        // Usable residual: reward tight fits (small post_residual) more than
        // linearly, mimicking best-fit with a convex preference.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 12.0 * tightness * tightness;
    }

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward residual that can host the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.25 * (next_item_size as f64);
        } else if post_residual > 0 {
            // Residual too small for the known next item: mild dead-space penalty.
            score += 5.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // bins with large residuals (consolidate), and discourage opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += 0.05 * pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: opening a new bin wastes the mean residual of all
    // open bins; penalize proportionally, but relax late in the stream when
    // consolidation gains are exhausted.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 15.0 + 0.15 * mean_residual + 2.0 * (open_bins_count as f64);
        score += new_bin_penalty * (1.0 - 0.3 * progress);
        // A new bin is attractive only for large items that leave big usable
        // residuals relative to typical needs.
        score -= 0.1 * (item_size as f64);
    }

    // Slight preference for bins whose residual is close to the item
    // (minimizes fragmentation across the fleet).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.03 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when the next item fits exactly
    // into the post-residual, penalize dead space smaller than next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 500.0; // next item fills this bin perfectly
        } else if (post_residual as u32) >= next_item_size {
            // next item fits: reward proportional to how snugly
            score -= 60.0 * (1.0 - (post_residual as f64 - nxt) / bin_capacity as f64);
        } else {
            // dead space: next item cannot use it -> penalize
            let dead = post_residual as f64;
            score += 40.0 * (dead / bin_capacity as f64) * (1.0 + dead / nxt);
        }
    }

    // Tightness relative to mean residual across open bins.
    let tight = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= 25.0 * tight; // prefer fuller-than-average bins

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // base cost of opening a bin, reduced late in the stream
        score += 300.0 - 50.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 20.0 * (1.0 - next_item_size as f64 / bin_capacity as f64);
        }
        let _ = pressure;
    }

    // Prefer bins whose residual is close to the item (snug fit).
    score += 0.5 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose residual is nearly consumed.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize creating tiny unusable dead space (dead space < 10 is wasted).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly-ish in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here anyway; slight penalty for wasting large residual.
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits the item, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only allow opening a new bin when the item is large
    // relative to the residual pattern or no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base cost of a new bin: it starts with full residual, so subtract a bit to
        // normalize, but add an opening cost so open bins are preferred when fit is decent.
        score -= 20.0;
        score += 30.0 + 10.0 * progress;
        // If many open bins already, opening a new one is less disruptive to spread.
        score -= (open_bins_count.min(20) as f64) * 0.5;
        // If the item is huge (near capacity), a fresh bin is natural.
        if item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
        // If mean residual across open bins is small (they're all nearly full), new bin is fine.
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
    } else {
        // Prefer bins whose residual is close to the mean (balanced packing) mildly.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Mild late-stream consolidation: as the stream progresses, favor filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: penalize wasted space quadratically
    let mut score = x * x * cap;

    // Smooth non-linear coupling with stream progress:
    // early on, prefer compacting (low post_residual); later, tolerate spreading.
    let w = 1.0 + 2.0 * progress * progress;
    score *= w;

    // Reward tight fits via cubic smooth term (small x strongly rewarded)
    score -= (1.0 - x).powi(3) * item_size as f64 * (1.0 - 0.5 * progress);

    // Dead-space penalty: residual too small for typical next items
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let unusable = (nx - pr).max(0.0);
        score += (unusable / cap) * nx * (0.5 + progress);
        // Reward leaving room for the next item (smooth sigmoid-like)
        let fit_next = pr / nx;
        score -= (fit_next / (1.0 + fit_next)) * 8.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // Mild penalty when many bins open and this placement wastes mean residual
    score += 0.05 * (open_bins_count as f64) * (pr - mean_residual).abs() / cap;

    // New-bin candidate: keep neutral-ish, penalize slightly when open bins are empty-ish
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * progress * (1.0 - 1.0 / (1.0 + open_bins_count as f64));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into coarse buckets.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class 1: tiny leftover (<=10) -> excellent packing, reward strongly.
    if post_residual <= 10 {
        score -= 30.0;
    } else if post_residual <= 20 {
        score -= 12.0;
    } else if post_residual <= 40 {
        score += 8.0;
    } else {
        score += 20.0;
    }

    // Modulo arithmetic on post_residual: leftovers that are multiples of common
    // small item sizes (harmonic divisors) are more likely reusable later.
    if post_residual > 0 {
        let mut reusable = 0.0;
        for d in [10u32, 20, 25, 50] {
            if post_residual % d == 0 && post_residual >= d {
                reusable += 6.0;
            }
        }
        score -= reusable;
    }

    // Lookahead: reward if the next item exactly fits the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // partial fit potential: reward proportional to how much of next item fills leftover
            let fill = next_item_size as f64 / post as f64;
            score -= 10.0 * fill;
        } else {
            // next item cannot use the leftover at all: penalize dead space more
            score += 5.0 + (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should be chosen only when the fit
    // in existing bins is poor. Give the fresh bin a moderate default score.
    if bin_residual == bin_capacity {
        score = 0.5 * cap - 0.5 * (item_size as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
        if fitting_bins_count == 1 {
            score += 30.0; // discourage abandoning the only fitting bin
        }
    }

    // Tightness coupling: bins whose residual is close to the item are better.
    let tightness = 1.0 - (post as f64 / cap).abs() * 0.5;
    score *= tightness;

    // Progress-aware scaling: early in the stream, prefer flexibility
    // (larger residuals); late in the stream, squeeze tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post as f64) * 0.1;

    // Mean residual context: if open bins are generally loose, penalize adding
    // another loose bin; if they are tight, reward tight fits even more.
    score += 0.2 * (mean_residual - post).abs().signum() * (mean_residual - post).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the smallest plausible item, here bounded by next_item_size
    // when known) are heavily penalized.
    let min_useful = if next_item_size > 0 { next_item_size.min(10).max(1) } else { 1 };
    if post_residual < min_useful {
        // Perfect fill: reward strongly.
        score -= 40.0;
    } else if post_residual < 10 {
        // Unusable micro-gap: penalize hard.
        score += 25.0 + (10.0 - post_residual as f64) * 3.0;
    }

    // Tightness reward: the smaller post_residual relative to capacity, the better.
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * 15.0;

    // Reward exact/near-exact fits relative to the incoming item.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 3 {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item can use the leftover space, reward;
    // if it cannot, penalize the dead space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + (post_residual as f64 - next_item_size as f64).min(10.0);
        } else {
            score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.4;
        }
    }

    // Open-bin pressure: discourage spreading across many bins; encourage
    // filling existing bins when several are open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (i.e., already well-filled bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate handling: an empty bin is only attractive when no open
    // bin offers a decent fit (post_residual would be large and wasteful there).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with stream progression.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 45.0 + progress * 25.0 + open_bins_count as f64 * 2.0;
        // If the item is large, a fresh bin leaves a big residual — acceptable.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
        // If the next item is small, a fresh bin is more flexible.
        if next_item_size > 0 && next_item_size < 20 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but penalize tiny dead space
    // that is too small to ever be useful (below the minimum item size 1... use
    // a soft threshold relative to capacity).
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 25.0; // nearly-full bin is fine, but avoid exact-dead unless needed
    }

    // 2-step lookahead: reward when post_residual exactly/nearly matches next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match => strong reward
        score -= 30.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        if diff == 0.0 {
            score -= 40.0; // exact chaining bonus
        }
        // Penalize leaving residual that no future item of plausible size fits
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0;
        }
    } else {
        // Last item: strongly prefer fullest packing
        score -= 20.0;
    }

    // Relative to mean residual: prefer bins that deviate toward fullness
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Neutral-ish baseline; slightly penalize so tight fits in open bins win
        score += 5.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 10.0; // fresh bin gives good lookahead room
        }
    }

    // Mild stream-progression pressure: consolidate late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight penalty for proliferating open bins
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual (non-linear).
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += 60.0 * tight * tight;

    // Reward near-perfect fills.
    if post_residual <= 2 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead (k=2): if the next item fits exactly or well in post_residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let la_fit = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - la_fit / (bin_capacity as f64));
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Dead space that next item cannot use: mild penalty, worse late in stream.
        let t = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * t;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no open bin
    // fits well, or the stream is early and future capacity is valuable.
    if bin_residual == bin_capacity {
        let t = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base cost of a fresh bin grows as the stream progresses (consolidate late).
        score += 30.0 + 60.0 * t;
        // If many bins can fit, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            score += 25.0 * (fitting_bins_count as f64 - 1.0);
        }
        // If only this (new) bin can fit the item, opening is necessary: discount.
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
        // Early in the stream, a fresh bin is cheaper (room for future items).
        score -= 40.0 * (1.0 - t);
        // If mean residual of open bins is large, open bins are underused; avoid new bin.
        score += 0.3 * mean_residual;
    }

    // Global pressure: many open bins with low mean residual -> prefer consolidation.
    if open_bins_count > 2 && bin_residual != bin_capacity {
        let pressure = (mean_residual - post_residual as f64).abs();
        score += 0.05 * pressure * (open_bins_count as f64);
    }

    // Prefer bins whose residual is close to item_size (good fit ratio).
    let fit_ratio = (item_size as f64) / (bin_residual as f64);
    if fit_ratio > 0.8 {
        score -= 12.0 * (fit_ratio - 0.8);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual
    let pr = post_residual as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling: penalize small-but-nonzero dead space more
    // as the stream progresses (wasted space becomes costlier later).
    let dead_penalty = (pr * (1.0 - pr)) * (1.0 + progress * 3.0);
    score += dead_penalty * bin_capacity as f64 * 0.5;

    // Reward tight fits (small post_residual) with a smooth quadratic discount
    score -= (1.0 - pr) * (1.0 - pr) * 10.0;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, reward
    if next_item_size > 0 {
        let diff = (post_residual as f64 - next_item_size as f64).abs();
        score -= 8.0 * (-diff / 10.0).exp();
    }

    // Penalize bins whose residual deviates from the mean residual (fragmentation signal)
    let dev = post_residual as f64 - mean_residual;
    score += dev.abs() * (0.1 + 0.3 * progress);

    // Slight preference for consolidating into fewer bins early on
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    // New-bin candidate: make it moderately attractive only when it yields a
    // perfect fit for a large item (post_residual == 0 handled naturally by pr).
    if bin_residual == bin_capacity {
        // base penalty for opening a new bin, softened by a good future use
        score += 6.0;
        if next_item_size as f64 >= 0.7 * bin_capacity as f64 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftover modulo 10 buckets.
    let leftover_class = post_residual % 10;
    // Perfect-fit reward: leftovers that are multiples of 10 are reusable by
    // common item sizes (10..80 in decade steps).
    score -= match leftover_class {
        0 => 12.0,
        5 => 4.0,
        _ => 0.0,
    };

    // Penalize very small dead space (< 10 unusable) more strongly.
    if post_residual < 10 {
        score += 25.0;
    }

    // Integer-division threshold on post_residual: how many "average" future
    // items could still fit? Fewer usable slots => worse bin.
    let slots = (post_residual / 20) as f64;
    score -= 6.0 * slots;

    // Harmonic coupling between post_residual and next_item_size:
    // reward when the next item fits exactly into the post residual class.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 10.0 * (1.0 - gap as f64 / bin_capacity as f64);
            if gap % 10 == 0 {
                score -= 5.0; // chained harmonic fit
            }
        } else {
            score += 3.0; // next item can't reuse this bin
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: neutral-ish baseline, opened only when
    // open bins score badly. Slightly discourage early in the stream when
    // few bins are open, encourage late when mean residual is low.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.5;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress);
        score -= 8.0 * (mean_residual / bin_capacity as f64);
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild tie-break: prefer fuller bins (smaller residual) via fraction.
    score += (bin_residual as f64 / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100 range,
    // but small gaps < ~15 are nearly unusable) are heavily penalized.
    if post_residual > 0 && post_residual < 15 {
        score += 60.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    } else {
        // Reward tight fits nonlinearly: fraction of bin filled.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= 40.0 * fill_ratio * fill_ratio;
    }

    // Penalize gaps that cannot fit the lookahead item but could have if slightly larger.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward gaps that exactly accommodate the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation into existing bins
    // (penalize the new-bin candidate implicitly by rewarding existing bins).
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual != bin_capacity {
        score -= 5.0 + 3.0 * pressure;
    } else {
        // New-bin candidate: mild base penalty scaled by open-bin count.
        score += 10.0 + 4.0 * pressure;
    }

    // Slight preference for bins whose residual is near the mean (balance load).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    // Early in the stream, be more willing to open bins (keeps flexibility later).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
