pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 8.0;

    // Penalize dead space: post_residual too small for any future item (min size 1... but typical small items).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // unusable sliver
    } else if post_residual >= 10 {
        // Check whether the next item fits into the post residual: reward chain packing.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0;
        } else if next_item_size > 0 {
            score += 2.0;
        }
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor fits.
    if bin_residual == bin_capacity {
        let waste_existing = (mean_residual - item_size as f64).max(0.0);
        // If existing bins waste a lot, opening fresh is fine; otherwise penalize.
        score += 25.0 - 1.5 * waste_existing;
        // Early in stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
        // Few open bins -> new bin more acceptable.
        score -= open_bins_count as f64 * 0.5;
    }

    // Slight preference for bins with residual close to mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer tight fits (quadratic in post_residual)
    let mut score = pr * (1.0 + norm_pr * norm_pr);

    // Stream-progress coupling: late in stream, squeeze bins harder (penalize residual more)
    score *= 1.0 + 0.8 * progress * norm_pr;

    // Reward near-full utilization with smooth cubic term
    score -= 6.0 * (1.0 - norm_pr).powi(3) * (0.5 + 0.5 * progress);

    // Dead-space penalty: residual too small to fit typical future items
    let small_threshold = 0.12;
    if norm_pr > 0.0 && norm_pr < small_threshold {
        score += 8.0 * (small_threshold - norm_pr) / small_threshold;
    }

    // Lookahead coupling: bonus if next item fits the post residual exactly-ish
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = 1.0 - ((pr - nxt) / cap).abs();
            score -= 3.0 * fit_quality * fit_quality;
        } else {
            // next item won't fit here: mild penalty proportional to gap
            score += 1.5 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate: neutral-ish score so it's chosen only when open bins are bad
    if bin_residual == bin_capacity {
        score = cap * (1.0 + 0.5 * progress) - 3.0 * (1.0 - norm_item);
        // discourage opening new bins when a good fit exists elsewhere
        if fitting_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 4.0 + 6.0 * (mean_residual - item_size as f64) / cap;
        }
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // Mean-residual alignment: prefer bins whose residual is close to item needs
    score += 0.5 * ((mean_residual - item_size as f64) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Residuals in [0..10] are near-perfect fits; multiples of 10 pair well
    // with typical item sizes; odd/prime-ish residuals are dead space.
    let pr = post_residual;
    let class_penalty: f64 = if pr == 0 {
        -30.0 // perfect closure
    } else if pr <= 10 {
        -18.0
    } else if pr % 10 == 0 {
        -10.0
    } else if pr % 5 == 0 {
        -4.0
    } else if pr % 2 == 0 {
        2.0
    } else {
        8.0 // odd residual: likely dead space
    };
    score += class_penalty;

    // Fractional capacity coupling: how much of the bin the item consumes.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill * fill; // reward large fills

    // Lookahead harmony: does post_residual exactly accommodate next item?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0; // perfect chain
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 3.0; // this bin can't chain
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is bad
    // and there are no other options.
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 { next_item_size as f64 } else { 0.0 };
        score += 25.0
            - 8.0 * fill
            - (fitting_bins_count as f64).min(3.0) * 4.0
            - 0.02 * open_bins_count as f64
            + 0.05 * pressure;
    }

    // Stream progression: early on, be slightly greedy with tight fits;
    // later, favor consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - fill);

    // Mean-residual coupling: if open bins are already slack, prefer
    // placements that don't add more slack spread.
    score += 0.1 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (non-linear quadratic blow-up).
    let dead_threshold = 10.0_f64.min(bin_capacity as f64 * 0.12);
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64).powi(2) * 4.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: penalize placements into bins when many bins are open,
    // encouraging consolidation into fewer bins.
    score += open_bins_count as f64 * 1.5;

    // Reward filling bins that are already well utilized (small residual).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Lookahead: if the next item fits exactly into the post-residual,
    // reward this placement strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Mild reward if next item can still fit after this placement.
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // New-bin candidate handling: make it attractive only when the current
    // fit is poor (large post_residual) or no good alternative exists.
    if bin_residual == bin_capacity {
        // Base penalty so new bins aren't opened carelessly.
        score += 30.0;
        // But if placing here would waste a lot of space in an existing bin,
        // opening a fresh bin becomes competitive.
        let waste = post_residual as f64;
        if waste > bin_capacity as f64 * 0.5 {
            score -= (waste - bin_capacity as f64 * 0.5) * 1.2;
        }
        // If many bins are already open, discourage yet another new bin.
        score += open_bins_count as f64 * 2.0;
    }

    // Mild stream-progression term: later in the stream, tighten up
    // (prefer tighter fits as we approach the end).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect wrap reward
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 30.0; // next item exactly fills remaining space
        } else if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leftover dead space more
            score += 8.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Penalize large unusable residuals relative to mean
    if post_residual as f64 > mean_residual {
        score += 0.6 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strong incentive to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild penalty for opening a new bin when open bins exist and fit
    if bin_residual == bin_capacity && open_bins_count > 0 && fitting_bins_count > 0 {
        score += 20.0;
        if next_item_size == 0 || next_item_size > bin_capacity {
            score -= 25.0; // no lookahead value: prefer new bin
        }
    }

    // Late-stream: tighten packing, avoid fragmentation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.1 * post_residual as f64;

    // Small residual bonus (tight fit)
    if post_residual <= 10 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly preferred: reward small post_residual non-linearly.
    let pr = post_residual as f64;
    score -= 60.0 * (-pr / 12.0).exp();

    // Penalize dead space that no plausible item could use later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / 30.0);
        } else {
            // next item cannot use the leftover: mild penalty proportional to waste
            score += 0.15 * (next_item_size.min(post_residual + next_item_size) as f64);
        }
    } else {
        // Last item: minimize leftover waste aggressively.
        score -= 30.0 * (1.0 - pr / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Global pressure: many open bins -> prefer filling existing ones.
    let pressure = (open_bins_count as f64 / (1.0 + total_items as f64)).min(1.0);
    score += pressure * 10.0 * (1.0 - item_size as f64 / bin_capacity as f64);

    // Mean-residual coupling: bin far below mean residual wastes capacity.
    score += 0.2 * (mean_residual - bin_residual as f64).abs();

    // Time horizon: early in the stream, keep bins flexible (avoid over-tight packing);
    // late in the stream, pack tightly.
    let t = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - t) * 0.3 * pr;      // early: penalize leftover mildly
    score -= t * 0.5 * pr;              // late: reward using space now

    // New-bin candidate: only attractive when nothing fits well or stream is early.
    if bin_residual == bin_capacity {
        let poor_fit = (fitting_bins_count == 0)
            || (fitting_bins_count <= 1 && post_residual < 20)
            || (open_bins_count == 0);
        if poor_fit {
            score -= 55.0; // open a new bin rather than force a bad fit
        } else {
            score += 70.0 + 0.4 * pr; // discourage opening bins when fits exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mean_r = mean_residual.max(0.0);

    // Base: post residual, with smooth non-linear dead-space penalty.
    // Small post_residual is good; but near-zero residual is wasted space.
    let mut score = pr;

    // Smooth polynomial coupling: penalize mid-range residual (hard to fill later),
    // reward large residuals (flexible) and very small ones (near-full bins).
    let x = pr / cap; // normalized post residual in [0,1]
    let bump = 4.0 * x * (1.0 - x); // peaks at x=0.5 (awkward dead space)
    score += 12.0 * bump * bump;

    // Stream progress coupling: later in the stream, prefer tighter fits more strongly.
    score += progress * 10.0 * x * x;

    // Fit quality with lookahead: if next item fits in post residual, reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 6.0 + 8.0 * (1.0 - (pr - nxt) / cap);
        } else {
            // Next item won't fit here: penalize proportionally to leftover gap.
            score += 4.0 * (pr / cap);
        }
    }

    // Last-chance bonus: only one bin fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Relative tightness vs mean residual: placing into a below-mean bin balances load.
    score += 0.05 * (mean_r - pr);

    // New-bin candidate: residual == capacity. Make it unattractive unless
    // the item fits poorly everywhere (handled by last-chance / fit terms),
    // with a smooth penalty scaled by how much space would be left empty.
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * x * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins.
    score += 0.3 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction band it lands in.
    let quarter = bin_capacity / 4; // 25
    let eighth = bin_capacity / 8;  // 12

    // Dead-space penalty via integer-division classes on post_residual.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual < 10 {
        score -= 25.0; // near-perfect: dead space below smallest item
    } else if post_residual / eighth == 0 {
        score -= 10.0; // <12: hard to reuse
    } else if post_residual / quarter == 0 {
        // 12..25: awkward class
        score += 5.0;
    } else if post_residual / quarter == 1 {
        // 25..50: moderately reusable
        score -= 4.0;
    } else {
        // 50..100: very reusable
        score -= 8.0;
    }

    // Modulo coupling: does post_residual align with next item size?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here: strong reward, scaled by tightness.
            let tight = (post_residual - next_item_size) as f64;
            score -= 20.0 - tight * 0.3;
            if (post_residual - next_item_size) < 10 {
                score -= 8.0; // chain of near-perfect fits
            }
        } else {
            score += 6.0; // next item won't fit: risk of stranded residual
        }
        // Harmonic residue: next_item mod quarter as fit-quality proxy
        let m = next_item_size % quarter;
        if m == 0 {
            score -= 5.0; // next item is a clean fraction of capacity
        } else if m > quarter - 10 {
            score += 3.0; // next item leaves awkward remainder
        }
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive for big items or late stream with many bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 > bin_capacity as f64 * 0.6;
        if big_item || open_bins_count == 0 {
            score -= 15.0;
        } else {
            // Penalize opening new bins when good reuse is plausible.
            score += 25.0 + 30.0 * (1.0 - progress);
            if mean_residual >= item_size as f64 + 10.0 {
                score += 20.0; // open bins have plenty of room; don't open new
            }
        }
    }

    // Mild preference for tighter existing bins as stream progresses.
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= tightness * 10.0 * (step_index as f64 / total_items.max(1) as f64);

    // Mean-residual coupling: if this bin is far below mean residual, it's a good squeeze target.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100)
    // are pure waste; penalize heavily, especially the 1..=9 zone.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }
    if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 50.0;
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Dead space relative to capacity: small leftover fractions are bad.
    let post_frac = post_residual as f64 / bin_capacity as f64;
    if post_frac > 0.0 && post_frac < 0.15 {
        score += 25.0 * (0.15 - post_frac) / 0.15;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins rather than opening new ones.
    score += open_bins_count as f64 * 1.5;

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item is large and this bin can't hold both, mildly discourage.
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and current open bins are crowded (low mean residual).
    if bin_residual == bin_capacity {
        let crowd = mean_residual / bin_capacity as f64;
        let pressure = (open_bins_count as f64 / 8.0).min(1.0);
        score += 35.0 - 25.0 * crowd - 20.0 * pressure;
        if item_size > 60 {
            score -= 10.0;
        }
    }

    // Early stream: slight preference to fill few bins well.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

