    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Next item could still fit here afterwards.
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit after placement: penalize wasted potential.
        score += 10.0;
    }

    // Small post-residual means tight packing (classic best-fit bias).
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 15.0 * tightness * tightness;

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / cap);

    // Slight penalty for very many open bins to encourage consolidation.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items
    // (residual below ~half the smallest plausible item is nearly useless).
    if post_residual < 25 {
        score += 6.0 * (25.0 - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many fitting bins: competition is high, slightly deprioritize mediocre fits.
    if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64 - 2.0);
    }

    // Lookahead: if next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // Next item won't fit here; penalize proportionally to wasted capacity.
            score += 3.0 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // Global state: if mean residual is high, prefer filling existing bins
    // rather than leaving slack everywhere.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (mean_residual / bin_capacity as f64) * (0.5 + progress);

    // Early in stream: mild bonus for keeping bins balanced (avoid fragmenting).
    if progress < 0.25 && post_residual >= 40 {
        score -= 2.0;
    }

    // Late in stream: prefer consolidating into fewest bins.
    if progress > 0.75 && bin_residual < bin_capacity {
        score -= 3.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 8.0 + 4.0 * (open_bins_count as f64).ln() };
        score += pressure;
        // Opening a new bin is fine if the item is large and would leave awkward residue.
        if item_size >= 60 && post_residual < 20 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a non-linear
    // polynomial coupling that punishes mid-range waste progressively.
    let mut score = post * (1.0 + 0.9 * post / cap) + 6.0 * (post / cap).powi(3) * cap;

    // Smooth interaction with stream progress: later in the stream,
    // tightness matters more (less room to consolidate waste).
    score *= 1.0 + 0.6 * progress * (1.0 - post / cap);

    // Penalize residuals too small for the lookahead item (dead space),
    // with a smooth quadratic ramp rather than a hard threshold.
    if next_item_size > 0 {
        let waste = (next_item_size as f64 - post).max(0.0);
        score += 2.5 * (waste / cap).powi(2) * cap;
        // Reward residuals that exactly or nearly fit the next item.
        let near = (post - next_item_size as f64).abs();
        score -= 4.0 * (1.0 - (near / cap).min(1.0)).powi(3);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a bin is attractive early in the
    // stream or when few bins are open; increasingly costly later on.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(1.0);
        score = cap * (0.55 + 0.9 * progress) + 3.0 * openness * progress;
        if next_item_size > 0 {
            score -= (next_item_size as f64 / cap).powi(2) * 12.0 * (1.0 - progress);
        }
    }

    // Mild pull toward bins with residuals close to the current mean
    // (keeps residual distribution balanced, smooth coupling).
    score += 0.15 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Harmonic classes: classify post_residual into dead-space bands via
    // integer division thresholds (capacity fractions).
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.0 && frac < 0.10 {
        score += 25.0; // unusable sliver
    } else if frac < 0.25 {
        score += 8.0;  // only fits tiny items
    } else if frac < 0.5 {
        score -= 2.0;
    }

    // Modulo arithmetic: residuals matching common item-size classes
    // (multiples of 10) are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 + 0.15 * slack;
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 4.0;
            }
        } else {
            score += 10.0 + 0.1 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: avoid wasting the only fitting bin on a bad fit,
    // but favor it on a good fit.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer filling bins when many are open; prefer new bin when few open
    // and mean residual is high elsewhere.
    if bin_residual == bin_capacity {
        score -= 3.0 + 0.02 * open_bins_count as f64;
        if mean_residual > 30.0 && post_residual > 40 {
            score += 5.0;
        }
    } else {
        score -= 0.05 * mean_residual.min(50.0);
    }

    // Late in the stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual == 0) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
