    // filling existing bins (penalize the new-bin candidate).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 + 0.5 * progress);
    if bin_residual == bin_capacity {
        score += 20.0 + pressure * 2.0;
    } else {
        score += pressure * 0.15;
    }

    // Lookahead: if the next item fits exactly into the resulting residual,
    // reward this placement strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 12.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // residual unusable by the known next item -> mild penalty
            score += 6.0;
        }
    }

    // Prefer bins below the mean residual (they get "cleaned up" first),
    // keeping large residuals available for large future items.
    score += (mean_residual - bin_residual as f64).max(-30.0).min(30.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fit (low post_residual).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item fits; the slack after both placements matters
            let double_slack = post_residual - next_item_size;
            score -= 50.0 - (double_slack as f64).min(50.0);
        } else {
            // next item cannot fit here: penalize leaving a gap that
            // is too small for the next item (dead space)
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Compare post_residual relative to mean residual: prefer bins whose
    // residual becomes close to (or below) the mean — tightening dense bins.
    let dev = post_residual as f64 - mean_residual;
    score += 0.2 * dev;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Mild pressure to fill existing bins when many are open.
    score += 0.5 * open_bins_count as f64;

    // Late in the stream, be more conservative about opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when
        // the next item could instead use remaining capacity elsewhere.
        let mut new_bin_penalty = 30.0 + 120.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_residual {
            new_bin_penalty += 0.4 * (bin_residual - next_item_size) as f64;
        }
        score += new_bin_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;

    // Base: prefer tight fits (small post_residual), normalized
    let mut score = post / cap;

    // Non-linear polynomial coupling: tight fits are exponentially rewarded as stream progresses
    let tightness = 1.0 - post / cap;
    score -= 2.5 * tightness * tightness * (0.5 + progress);

    // Penalize large dead space quadratically (unusable fragments)
    let dead = post / cap;
    score += 1.8 * dead * dead;

    // Perfect fit bonus (cubic smooth term)
    if post_residual == 0 {
        score -= 1.5;
    }

    // Lookahead coupling: reward if post_residual can still host the next item exactly or well
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64 / cap;
            // smooth reward: next item fits, better if snugly
            score -= 1.2 * (1.0 - slack) * (1.0 - slack) * (1.0 - progress);
        } else {
            // post_residual too small for next item: penalize proportionally to waste
            let waste = nxt / cap;
            score += 0.8 * waste * (1.0 + dead);
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 1.0 + 0.5 * (item_size as f64 / cap);
    }

    // Compare against mean residual: using a bin far below mean residual wastes the "fatter" bins
    let dev = (res - mean_residual) / cap;
    score += 0.6 * dev * dev * dev;

    // New-bin candidate handling: empty bin should only win when open bins are nearly full or fragmented
    if bin_residual == bin_capacity {
        let mean_full = 1.0 - mean_residual / cap;
        // penalize opening new bin normally
        score += 1.0;
        // but relax penalty late in stream or when open bins are nearly exhausted
        score -= 0.9 * mean_full * mean_full + 0.4 * progress;
        // if no open bin really fits well, new bin becomes attractive
        if fitting_bins_count == 0 {
            score -= 2.0;
        }
    }

    // Mild penalty for proliferating open bins when stream is early
    score += 0.02 * (open_bins_count as f64) * (1.0 - progress) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual modulo capacity quarters.
    let quarter = bin_capacity / 4;
    let class = post_residual % quarter.max(1);
    // Reward residuals that land in "harmonically useful" classes (divisible by small ints).
    if post_residual % 10 == 0 { score -= 6.0; }
    if post_residual % 5 == 0 { score -= 3.0; }
    if post_residual % 25 == 0 { score -= 4.0; }
    if class == 0 { score -= 5.0; }

    // Integer-division thresholds on post_residual: dead space bands.
    let dead = post_residual / quarter.max(1);
    score += dead as f64 * 2.0; // larger coarse band => more waste

    // Tight fit bonus (post_residual in lowest class).
    if post_residual < 10 { score -= 15.0; }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.4;
        } else {
            score += (next_item_size as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly; allow only when open bins are poor fits.
    if bin_residual == bin_capacity {
        let poor = mean_residual < item_size as f64 * 0.5;
        score += if poor { 5.0 } else { 25.0 };
    }

    // Stream progression: later in stream, prefer consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold any
    // plausible future item are the worst outcome. Penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward very tight fits (small but usable leftover).
    if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 - slack.min(15.0);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Next item cannot use this gap -> dead space likely.
        score += 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64 / (1.0 + mean_residual / 10.0)) * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; only attractive when
        // existing fits would create dead space (handled by penalties above).
        score += 45.0 + pressure * 5.0;
    } else {
        score -= pressure.min(10.0);
    }

    // Mild preference for bins with larger residuals being used for big items
    // (keep small residuals for small items).
    let residual_ratio = bin_residual as f64 / bin_capacity as f64;
    let item_ratio = item_size as f64 / bin_capacity as f64;
    score += (residual_ratio - item_ratio).abs() * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match with next item size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        // Perfect fit for the next item: strong reward.
        if diff < 0.5 {
            score -= 60.0;
        } else if next <= post_residual as f64 {
            // Next item still fits after this placement: mild reward scaled by slack.
            score -= 15.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize wasted post_residual.
            score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Prefer bins tighter than the mean residual (good fits).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize new-bin candidate unless item is large relative to capacity
    // and no good existing fit exists (post_residual small means good fit).
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 30.0 - 20.0 * large_item;
        // More open bins already: discourage opening yet another.
        score += 2.0 * open_bins_count as f64;
    }

    // Slight stream-progression pressure to consolidate early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that cannot be filled by the next item
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
        // Reward leaving exactly the space the next item needs
        if post_residual == next_item_size {
            score -= 15.0;
        }
        // Reward leaving room for the next item
        if post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Pressure from many open bins: prefer consolidating into existing bins
    let open_frac = (open_bins_count as f64) / ((total_items as f64).max(1.0));
    score += 30.0 * open_frac * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: later in the stream, waste hurts more
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Compare residual to mean residual: bins with less residual than average
    // are more "committed"; placing there keeps large gaps elsewhere available
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 45.0 - 30.0 * large_item;
        // If nothing else fits well, opening a new bin is fine
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Small bonus for filling bins that are nearly full already
    if post_residual <= 10 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Smooth non-linear fit quality: reward small post_residual via inverse coupling
    let fit_ratio = post / cap;
    score -= 30.0 * (1.0 - fit_ratio).powi(2) * (1.0 - fit_ratio);

    // Polynomial coupling of post_residual with stream progress:
    // late in the stream, tighter packing matters more (dead space penalty grows)
    let dead_space_curve = (post / cap).powi(3);
    score += 60.0 * dead_space_curve * (0.5 + 2.0 * progress);

    // Reward nearly-exact fills with smooth term
    let exactness = 1.0 - (post / cap);
    score -= 25.0 * exactness.powi(4) * (1.0 + progress);

    // Lookahead: if next item fits smoothly in the post residual, bonus
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let nxt_fit = (post - nxt) / cap;
            score -= 20.0 * (1.0 - nxt_fit).powi(3);
        } else {
            score += 10.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly early, more strongly when many open bins exist
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64 + 20.0 * progress;
    }

    // Mild alignment with mean residual: prefer bins below mean residual (tighter bins first)
    score += 0.15 * (mean_residual - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual (capacity fractions) ---
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class bins by capacity fraction: quarters of the bin.
    let quarter = cap / 4.0;
    let class = (pr / quarter).floor(); // 0..4
    match class as u32 {
        0 => score -= 6.0,             // residual < 25%: near-perfect packing
        1 => score -= 2.0,             // residual 25-50%: good
        2 => score += 1.5,             // residual 50-75%: mediocre
        _ => score += 4.0,             // residual > 75%: wasteful placement
    }

    // Modulo arithmetic: residual in [1..=10] is prime dead space
    if post_residual > 0 && post_residual % 10 != 0 && post_residual <= 10 {
        score += 5.0;
    }
    // Exact zero residual is ideal
    if post_residual == 0 {
        score -= 10.0;
    }
    // Harmonic alignment: residual divisible by 25 (quarter multiples) is reusable
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        // Perfect chained fit: next item exactly fills the residual
        if (next_item_size as u32) == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how snugly
            let snug = 1.0 - (pr - nxt) / cap;
            score -= 4.0 * snug;
        } else {
            // Next item won't fit here: penalize leaving a residual
            // that is smaller than the next item (dead space)
            let dead = 1.0 - pr / nxt.max(1.0);
            score += 3.0 * dead;
        }
        // Harmonic threshold: next item in "large class" (>50) makes
        // small residuals here less valuable
        if next_item_size > bin_capacity / 2 && post_residual < next_item_size {
            score += 2.5;
        }
    }

    // --- Last-chance bin dynamics ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // This is the only bin that fits: strongly prefer using it
        // over opening a new bin, unless the fit is terrible.
        let fit_quality = pr / cap;
        if fit_quality < 0.25 {
            score -= 15.0;
        } else {
            score -= 5.0;
        }
    }

    // --- New-bin candidate logic ---
    if bin_residual == bin_capacity {
        // New empty bin: score = residual after placing item here.
        // Favor it when item is large (poor fit candidates elsewhere)
        // or when no existing bin fits well.
        let item_frac = item_size as f64 / cap;
        if item_frac > 0.5 {
            score -= 8.0; // large items deserve fresh bins
        }
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
        // Slight penalty to prefer reusing existing bins on ties
        score += 1.0;
    }

    // --- Stream progression and congestion ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    // Late in the stream, waste matters more (fewer future chances to reuse)
    score += 2.0 * progress * (pr / cap);

    // Penalize spreading across too many open bins with slack
    let slack = (mean_residual - pr) / cap;
    if slack > 0.5 {
        score += 1.5;
    }
    if open_bins_count > 8 && bin_residual != bin_capacity {
        score -= 1.0; // consolidate into existing bins when many are open
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum plausible item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing a bin completely.
        score -= 30.0;
    } else {
        // Non-linear coupling: penalize mid-range gaps that few future items
        // can fill; a residual near capacity is fine (still roomy).
        let r = post_residual as f64;
        score += 0.15 * (r - 50.0).abs() * (r / bin_capacity as f64);
    }

    // Reward fitting the next item too (lookahead pairing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize if this placement leaves a gap the next item *just barely*
    // misses, creating stranded space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new
    // ones; the new-bin candidate gets penalized progressively.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.5 * open_bins_count as f64;
        // But if mean residual across open bins is tiny, a fresh bin is fine.
        if mean_residual < 8.0 {
            score -= 20.0;
        }
    } else {
        // Slight reward for using existing bins when bin count is high.
        score -= 0.4 * open_bins_count as f64;
    }

    // Early in the stream, be more willing to open bins (build diverse
    // residuals); late in the stream, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 6.0 * (1.0 - progress);
    } else {
        score += 4.0 * progress;
    }

    // Mild tie-break: prefer bins whose residual is close to item_size.
    score += 0.05 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: penalize wasted space quadratically.
    let wasted = post_residual as f64;
