    // 2-step lookahead: strongly reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if post_residual >= next_item_size {
            // Next item fits: reward tight chaining.
            score -= 18.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item does not fit: penalize residual too small to be useful.
            score += 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Compare post_residual to mean residual: avoid leaving outliers of dead space.
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let tight_fit_exists = next_item_size > 0 && post_residual >= next_item_size;
        if !tight_fit_exists {
            score -= 3.0;
        } else {
