        }
    }

    // Early in stream: be slightly more willing to open bins for flexibility.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 6.0 * (1.0 - progress);
    }

    // Many open bins: favor consolidating into existing bins.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward small post_residual relative to bin capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 0.5 * tightness * (bin_residual as f64 - item_size as f64);

    // Lookahead: if the next item fits the post-residual exactly or well, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Post-residual too small for next item: penalize dead space.
        score += 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Penalize opening new bins when open bins have plenty of residual capacity.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 6.0;
        }
    } else {
        // Reward filling bins that are already partially used when global residual is high.
        score -= 0.05 * mean_residual.min(50.0);
    }

    // Time horizon: early in the stream, be conservative (prefer spreading); late, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (1.0 - tightness);

    // Exact fit celebration.
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 6.0; // small dead space is fine
    } else if post_residual < 20 {
        score += 1.0; // awkward gap zone
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;

    // Base: penalize residual, scaled by stream progress (dead space matters more later)
    let mut score = r * (1.0 + 2.0 * progress * progress);

    // Non-linear coupling: quadratic residual with progress-modulated curvature
    score += 3.0 * r * r * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= (1.0 - r) * (1.0 - r) * (0.5 + 1.5 * progress) * norm_item;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 2.0 + 3.0 * progress;
    }

    // Lookahead: penalize if post_residual can't fit next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / bin_capacity as f64;
        if r < nxt {
            score += 1.5 * (nxt - r) * (1.0 + progress);
        } else {
            score -= 0.5 * r * nxt;
        }
    }

    // Penalize proliferation of open bins with large mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64 - r).abs();

    // New-bin candidate: mild penalty so it only wins when open bins are truly bad
    if bin_residual == bin_capacity {
        score += 1.0 + 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo 10 define
    // "usable" classes (residues divisible by common small item sizes
    // are more likely to be filled later).
    let residue = post_residual % 10;
    let harmonic_bonus: f64 = match residue {
        0 => -12.0, // perfectly divisible -> highly reusable
        5 => -8.0,  // half-class -> often fillable
        2 | 4 | 6 | 8 => -4.0, // even class -> moderately reusable
        1 | 3 | 7 | 9 => 3.0,  // odd prime-ish class -> dead-space risk
        _ => 0.0,
    };
    score += harmonic_bonus;

    // Integer-division thresholds: how many "typical slots" fit in the
    // post residual (slots of size 10, the minimum item size).
    let slots10 = post_residual / 10;
    score -= (slots10 as f64) * 2.0;

    // Penalize post-residuals that sit in awkward mid-range bands
    // (too small for medium items, too big to ignore).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // near-dead sliver
    } else if post_residual >= 10 && post_residual <= 20 {
        score -= 6.0; // sweet band for small items
    } else if post_residual > 60 && post_residual < 70 {
        score += 4.0; // awkward band
    }

    // Lookahead coupling: if the next item fits exactly into the
    // post-residual, strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            score -= 10.0 - (leftover as f64) * 0.3;
        } else {
            // next item cannot follow here: mild penalty scaled by gap
            score += ((next_item_size - post_residual) as f64) * 0.2;
        }
    }

    // Last-chance logic: if this is the only bin that fits, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 14.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the
    // current item is large and mean residual across open bins is low.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mean_fit = mean_residual / bin_capacity as f64;
        if item_size as f64 > mean_residual {
            score -= 8.0 + 10.0 * (1.0 - mean_fit) * progress;
        } else {
            score += 10.0 + 5.0 * mean_fit;
        }
    }

    // Slight preference to keep the number of open bins bounded.
    score += (open_bins_count as f64) * 0.15;

    // Reward tight fits explicitly.
    score += (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    // A gap is "dead" if it is too small for even the smallest plausible item.
    let min_gap = 1.0;
    if (post_residual as f64) < min_gap * 10.0 {
        score += 500.0; // tiny unusable sliver -> very bad
    }

    // Penalize dead space relative to the smallest possible next item.
    // If post_residual < next_item_size (and next item exists), this gap is likely unusable.
    if next_item_size > 0 && post_residual < next_item_size {
        // Dead space for the lookahead item: penalize proportionally to how close it is to wasted.
        score += 120.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0));
    }

    // Reward tight fits: post_residual near 0 is excellent.
    if post_residual == 0 {
        score -= 200.0; // perfect fill
    } else {
        // Smooth reward for small residuals (quadratic decay of tightness bonus).
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 60.0 * tightness * tightness;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening yet another bin.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open_bins_count grows.
        score += 25.0 * (open_bins_count as f64).sqrt();
        // Also penalize new bins late in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * progress;
        // A new bin is more acceptable if mean residual across open bins is small
        // (existing bins are nearly full).
        score -= (mean_residual / bin_capacity as f64).max(0.0) * 40.0;
    } else {
        // Mild reward for using existing bins when open bins are numerous.
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins whose residual is close to the item (minimal slack before placement).
    let pre_slack = (bin_residual as f64) - (item_size as f64);
    score += 0.15 * pre_slack;

    // Lookahead synergy: if placing here leaves a gap that exactly fits the next item, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: neutral baseline.
    if bin_residual == bin_capacity {
        return 105.0 - 0.15 * open_bins_count as f64;
    }

    let next = next_item_size as f64;

    // Perfect 2-step match: post residual exactly fits next item.
    if next > 0.0 && (post_residual as f64 - next).abs() < 0.5 {
        score -= 40.0;
    }

    // Post residual too small for next item => dead space penalty.
    if next > 0.0 && (post_residual as f64) < next {
        score += 12.0 + 0.5 * (next - post_residual as f64);
    }

    // Post residual leaves a large awkward gap relative to mean residual.
    if post_residual as f64 > mean_residual + 20.0 {
        score += 0.3 * (post_residual as f64 - mean_residual);
    }

    // Very tight fit: wasted space minimized.
    if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Slight preference for reusing bins when many are open.
    score -= 0.05 * open_bins_count as f64;

    // Early in stream: be pickier about tight fits (future flexibility).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 {
        score += 0.1 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residual too small for any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 4.0; // next item won't fit here; bin becomes dead-ish
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Time horizon: early in stream, be pickier about residual waste; late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0 * (post_residual as f64 / bin_capacity as f64);
    score -= progress * 3.0 * tightness;

    // Prefer fuller bins relative to the fleet average residual.
    score -= 2.5 * ((bin_residual as f64) - mean_residual) / bin_capacity as f64;

    // Slight preference for existing bins over opening new ones, scaled by fleet size.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64;
    } else {
        score -= 1.0;
    }

    // Discourage fragmenting many open bins when few fit.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;

    // Core: quadratic penalty on leftover space (dead space is quadratic waste).
    let mut score = norm_post * norm_post * cap;

    // Smooth cubic correction: mildly amplify penalty for mid-range leftovers
    // (worst dead space), soften for near-perfect fits.
    score += 0.6 * cap * norm_post * norm_post * (1.0 - norm_post);

    // Tight-fit reward: subtract proportional to how fully the bin is used,
    // with a non-linear (sigmoid-like) boost as fill fraction approaches 1.
    let fill = item / bin_residual.max(1) as f64;
    let tight = 1.0 / (1.0 + (1.0 - fill).exp() * 8.0);
    score -= 12.0 * tight * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin (scaled by stream progress).
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead coupling: reward leaving a residual that can still host the next item,
    // penalize residuals that are too small for it but nonzero (fragmentation).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            // good: next item may fit here; reward proportionally to slack
            score -= 6.0 * (1.0 - (post - nxt) / cap);
        } else if post > 0 {
            // bad: creates unusable sliver relative to next item
            score += 8.0 * (1.0 - post / nxt.max(1.0));
        }
    }

    // Diversify across open bins: with many open bins, prefer bins with below-mean
    // residual (balance), smoothly coupled.
    let mean_norm = mean_residual / cap;
    score += 4.0 * (norm_post - mean_norm) * (open_bins_count as f64).ln().max(1.0);

    // Early stream: slight preference to fill existing bins densely to keep
    // future flexibility; late stream: aggressive consolidation.
    score -= 5.0 * progress * (1.0 - norm_post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: small post_residual strongly favored
    score -= 60.0 * (1.0 - post_residual as f64 / cap).powi(3);

    // Harmonic class of post_residual: dead space classes
    // Residuals that cannot host small items (<=10) are dead space -> penalize
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect closure reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Modulo classes on post_residual (harmonic buckets of size 10)
    let bucket = (post_residual / 10) % 4;
    score -= match bucket {
        0 => 12.0, // residual divisible by 10: reusable class
        1 => 0.0,
        2 => 6.0,
        _ => 3.0,
    };

    // Lookahead compatibility: does post_residual still fit next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // reward proportional to leftover-after-next slack tightness
            let slack = post_residual - next_item_size;
            score -= 20.0 * (1.0 - slack as f64 / cap);
        } else {
            // next item won't fit here after placement: penalize proportionally
            score += 15.0 * (next_item_size as f64 - post_residual as f64) / cap;
        }
        // modulo harmony between post_residual and next_item_size
        if next_item_size % 10 == post_residual % 10 && post_residual >= next_item_size {
            score -= 8.0;
        }
    } else {
        // last item: prefer closing bins completely
        score += 5.0 * post_residual as f64 / cap;
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish baseline, slightly penalized unless current
    // fits are very poor (large post_residual after placement)
    if bin_residual == bin_capacity {
        score = cap * 0.55 + 10.0 * (item_size as f64 / cap);
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 20.0;
        }
    }

    // Stream progression: late in stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / cap);

    // Many open bins: prefer consolidating into existing bins
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / cap);

    // Deviation from mean residual: prefer bins near the mean (balanced packing)
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1..100,
    // but practically small) can use are pure waste. Penalize tiny gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual < 20 && post_residual > 0 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill: best possible outcome
    }

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open bins pressure: many open bins -> prefer consolidating into existing bins
    // and penalize opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when existing bins are crowded/fragmented
        score += 30.0 + 8.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 20.0; // open bins exist that could fit; new bin is worse
        }
        // Late in the stream, avoid new bins even more
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    } else {
        // Existing bin: mild bonus proportional to fragmentation pressure
        score -= 2.0 * open_bins_count.min(20) as f64;
    }

    // Lookahead: if next item fits in post_residual, this placement is great
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item would NOT fit here anyway, small gap doesn't matter as much
    if next_item_size > post_residual && post_residual > 0 {
        score -= 5.0;
    }

    // Prefer bins below mean residual (fills emptier bins, keeps tight bins free)
    if bin_residual < bin_capacity {
        score += 0.1 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Post residual can still host the next item: reward closeness of the match.
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + slack / 10.0);
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to wasted potential.
        let miss = (next_item_size - post_residual) as f64;
        score += miss.min(40.0) * 0.5;
    }

    // Tight fits (small dead space) are good in general.
    let dead = post_residual as f64;
    if dead < 10.0 {
        score -= 15.0;
    }

    // Compare against mean residual: prefer consuming bins with above-average residual
    // (keeps tight bins tight, spreads usage evenly).
    let avg = mean_residual.max(0.0);
    if (bin_residual as f64) > avg {
        score -= ((bin_residual as f64) - avg) * 0.3;
    } else {
        score += (avg - (bin_residual as f64)) * 0.3;
    }

    // Last-chance bin: strongly prefer filling it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Discourage opening new bins early in the stream when open bins could fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 12.0 + 20.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // new bin still fine if it perfectly hosts the next item too
        }
    }

    // Late in the stream, minimize dead space more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += dead * 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
