    // Penalize dead space that cannot hold a typical future item.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dead = post_residual as f64;
    if dead < 10.0 {
        score -= 15.0; // near-perfect fill is excellent
    } else {
        // dead space penalty grows as stream progresses (less time to reuse it)
        score += (dead / 20.0).powi(2) * (0.5 + 2.0 * progress);
    }

    // Lookahead: reward bins whose post_residual fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
