        } else {
            score += 6.0; // creates a bin the next item cannot use
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 25.0 + 0.1 * item_size as f64;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when existing residuals are large and the item is big.
    if bin_residual == bin_capacity {
        let spread = mean_residual - post_residual as f64;
        let openness = open_bins_count as f64;
        // Penalize new bins early / when many bins are open with slack.
        score += 30.0 + 2.0 * openness - 0.2 * item_size as f64;
        if mean_residual > 1.5 * item_size as f64 {
            score += 20.0; // plenty of slack elsewhere; don't open a bin
        }
        if openness < 1.5 {
            score -= 35.0; // no open bins to compete with
        }
        let _ = spread;
    }

    // Mild preference for filling bins that are already partially full
    // (consolidation), scaled by global mean residual.
    score -= 0.05 * (bin_capacity - bin_residual) as f64 * (mean_residual / bin_capacity as f64);

    // Small late-stream consolidation bias.
    score += progress * (post_residual as f64 / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = pr * pr / cap            // quadratic waste term
             + pr * (1.0 - t)           // early stream: penalize residual more (save space for future)
             + pr * t * t;              // late stream: quadratic coupling

    // Reward tight fits (small post_residual) with smooth exponential discount
    let tight_bonus = -40.0 * (-pr / 12.0).exp();

    // Lookahead coupling: penalize if next item cannot use the post residual
    let lookahead_pen = if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        8.0 * (gap / cap) * (1.0 + t)
    } else {
        0.0
    };

    // Last-chance bin: strong reward to use it rather than open a new one
    let last_chance = if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        -25.0
    } else {
        0.0
    };

    // New-bin candidate: neutral baseline, slightly worse than a good fit
    let new_bin_pen = if bin_residual == bin_capacity { 5.0 + 10.0 * t } else { 0.0 };

    // Deviation from mean residual: discourage creating outliers
    let dev_pen = 0.5 * (pr - mean_residual).abs() / cap;

    let mut score = poly + dev_pen + lookahead_pen + new_bin_pen
                  + tight_bonus + last_chance
                  + 0.01 * open_bins_count as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: small post_residual classes are gold.
    // Class 0: post_residual == 0 (perfect fit) -> huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Integer-division thresholds on post_residual: bins that leave a
        // leftover usable by small items (<=10) are much preferred.
        let pr = post_residual;
        if pr <= 10 {
            score -= 200.0;
        } else if pr <= 20 {
            score -= 80.0;
        } else if pr <= 30 {
            score -= 30.0;
        }
        // Modulo arithmetic: leftover that is a multiple of common small sizes
        // (10, 20, 25, 50) is more likely to be filled later.
        if pr % 10 == 0 { score -= 15.0; }
        if pr % 25 == 0 { score -= 10.0; }
        if pr % 50 == 0 { score -= 12.0; }
    }

    // Coupling with lookahead: reward leftovers that exactly fit next item,
    // penalize leftovers just barely too small for next_item_size (dead space).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
        // Harmonic pairing: post_residual + next_item_size near capacity is good.
        let combo = post_residual as f64 + next_item_size as f64;
        if combo <= bin_capacity as f64 {
            score -= (bin_capacity as f64 - combo) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Prefer fuller bins over emptier ones (mean-residual anchoring).
    score += (bin_capacity as f64 - bin_residual as f64) * 0.0; // baseline kept
    score -= (mean_residual - post_residual as f64) * 0.2;

    // New-bin candidate handling: only prefer a fresh bin when all open bins
    // would leave large dead space or open_bins_count is low.
    if bin_residual == bin_capacity {
        // Penalty baseline for opening a new bin; relaxed late in stream
        // when many bins are open and mean residual is fragmented.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 60.0
            - progress * 20.0
            - (open_bins_count as f64 * 2.0);
        if fitting_bins_count == 0 { new_bin_score -= 100.0; }
        // If next item is large and current item is small, fresh bin helps.
        if next_item_size > bin_capacity / 2 && item_size <= 20 {
            new_bin_score -= 30.0;
        }
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical future items are wasted.
    let dead_threshold = 30.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 2.5;
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward fits that leave room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * (post_residual as f64 - next_item_size as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Residual too small for the next item: mild penalty, stronger if in dead zone.
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin when pressure is low,
    // reward it when many bins are open and mean residual is fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 - 20.0 * progress;
        if open_bins_count > 4 && mean_residual > 40.0 {
            score -= 30.0; // many half-empty bins: consolidation is bad, but avoid hoarding
        }
        if mean_residual < 25.0 {
            score -= 15.0; // existing bins are tight, a fresh bin is fine
        }
    } else {
        // Mild pressure to fill already-open bins rather than proliferate.
        score -= 0.4 * open_bins_count as f64;
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual - item_size) as f64;
    score += 0.3 * tightness;

    // Penalize leaving residuals in the awkward 20..35 band (hard to fill later).
    if post_residual >= 20 && post_residual <= 35 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small post-residual is good, but only if it's "usable dead space"
    // Penalize residuals that are too small to be useful (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // 2-step lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // perfect chain match
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to tightness of the chain fit
            let chain_waste = post_residual as f64 - next_item_size as f64;
            score -= 200.0 - 3.0 * chain_waste;
        } else {
            // next item won't fit here: penalize slightly, worse for large overshoot
            let overshoot = next_item_size as f64 - post_residual as f64;
            score += 0.5 * overshoot.min(50.0);
        }
    }

    // Relative to mean residual: prefer bins that are already more filled
    // (residual below mean) so we consolidate waste
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = (mean_residual - residual_f) / mean_residual;
        score -= 30.0 * rel; // lower residual than mean -> better
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a
    // perfect lookahead chain or existing bins are badly fragmented
    if bin_residual == bin_capacity {
        let mut new_bin_score = bin_capacity as f64 + 60.0; // base penalty for opening new bin
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_score -= 100.0;
        }
        // if many open bins with large mean residual, opening a fresh bin is fine
        if mean_residual > 40.0 {
            new_bin_score -= 20.0;
        }
        score = score.min(new_bin_score) + (score - new_bin_score).max(0.0) * 0.0;
        score = new_bin_score;
        // allow new bin to win only if no existing bin is a great fit:
        // compare against typical good existing-bin scores (~post_residual small)
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 40.0;
        }
    }

    // Slight preference to fill older bins as stream progresses (reduce spread)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: squash the effective dead space.
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 35.0 * tightness * tightness;

    // Penalize leaving residuals that are too small to be useful later
    // (dead space below the minimum conceivable item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item exactly fills the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 18.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use the leftover: leftover is likely dead.
            score += 8.0 * (post_residual as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    score -= 6.0 * ((bin_residual as f64 / cap) * (open_bins_count as f64).ln().max(1.0));

    // Global balance: penalize bins whose residual deviates from mean residual
    // toward being unusually empty (encourages uniform filling).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: early in the stream, be more willing to open/spread;
    // late in the stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    // New empty bin candidate: neutral-ish base; only chosen when fits are bad.
    if bin_residual == bin_capacity {
        score = cap * 0.9 + 10.0 * (1.0 - progress);
        // If no open bin fits well, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear penalty on wasted residual (quadratic coupling), softened late in stream
    score += 0.35 * (pr / cap) * (pr / cap) * cap * (1.0 - 0.4 * progress);

    // Reward tight fits: small post_residual relative to item size
    let tightness = 1.0 - pr / cap;
    score -= 12.0 * tightness * tightness * (item_size as f64 / cap);

    // Lookahead: reward if next item can use the post residual (smooth kernel)
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        let kernel = (-diff * diff / (2.0 * 25.0 * 25.0)).exp();
        score -= 18.0 * kernel;
        // penalize if post residual is awkwardly between next item size and unusable
        let awkward = (pr / cap) * (1.0 - kernel);
        score += 8.0 * awkward;
    }

    // Last-chance bin: strongly favor using it to avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // Many open bins with high mean residual: discourage spreading
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap) * (1.0 - progress);

    // New-bin candidate: neutral baseline, slightly favored early, penalized late
    if bin_residual == bin_capacity {
        score = 25.0 - 20.0 * progress + 0.3 * mean_residual * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose post_residual falls into
    // "small residue" classes (hard to fill later) are penalized; residues that
    // align with typical item sizes are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional capacity class of the leftover
    let frac = pr / cap;
    if frac < 0.05 {
        // near-perfect fit: strong reward
        score -= 30.0;
    } else if frac < 0.12 {
        score -= 15.0;
    } else if frac < 0.25 {
        score -= 5.0;
    } else if frac < 0.5 {
        score += 3.0;
    } else {
        score += 8.0;
    }

    // Integer-division threshold classes on post_residual (harmonic bands of 10)
    let band = post_residual / 10;
    match band {
        0 => score -= 12.0,           // 0..9 : almost sealed
        1 => score -= 6.0,            // 10..19
        2 => score -= 2.0,            // 20..29
        3 => score += 0.0,
        4 => score += 2.0,
        5 => score += 4.0,
        6 => score += 6.0,
        7 => score += 8.0,
        8 => score += 10.0,
        9 => score += 12.0,
        _ => score += 14.0,
    }

    // Lookahead coupling: does the next item fit into the post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // reward proportional to how snugly the next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
            // harmonic match: next item size band equals residual band
            if (next_item_size / 10) == band {
                score -= 6.0;
            }
        } else {
            // next item cannot use this leftover -> dead space risk
            score += 5.0 * (next_item_size as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        let bad_fit = frac > 0.35;
        score += if bad_fit { -20.0 } else { 40.0 + open_bins_count as f64 };
    }

    // Prefer fuller bins relative to the fleet mean residual
    score -= 0.5 * (mean_residual - pr).max(-cap).min(cap) / 10.0;

    // Mild consolidation pressure as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot hold the next item
    // (or any plausible future item) are "dead space" -> heavy penalty.
    if post_residual > 0 {
        let unusable = next_item_size > 0 && post_residual < next_item_size;
        let tiny_gap = post_residual < 10; // below minimum item size
        if unusable { score += 45.0; }
        if tiny_gap { score += 60.0; }
        // smooth penalty growing as residual shrinks into dead zone
        let r = post_residual as f64;
        score += 25.0 * (-r / 15.0).exp();
    } else {
        // perfect fit: strong reward
        score -= 80.0;
    }

    // Reward when this placement leaves room for the lookahead item (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + 10.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer tight fits.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 4.0;

    // New-bin candidate: baseline cost of opening a fresh bin, modulated by
    // how badly the item fits existing bins and how large the item is.
    if bin_residual == bin_capacity {
        let base = 55.0 + 0.3 * item_size as f64;
        // If no existing bin fits well (post_residual tiny or dead), opening is fine.
        score = base + pressure * 2.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin can chain with next item
        }
    } else {
        // Prefer bins whose residual is closest to item (tight fit bonus).
        let tightness = (bin_residual - item_size) as f64;
        score -= 12.0 * (1.0 - tightness / bin_capacity as f64);
    }

    // Late in stream: consolidate, avoid fragmentation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 8.0 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // cannot fit next item; penalize dead space
        score += 0.25 * post_residual as f64;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize small unusable residuals (< min item size 1..100, use 10 as typical)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last chance: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New bin candidate: only attractive if no good fit exists
    if bin_residual == bin_capacity {
        score += 40.0 + mean_residual * 0.5;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Compare residual to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Late stream: encourage tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize low post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit a typical next item.
    if post_residual > 0 && (next_item_size == 0 || post_residual < next_item_size) {
        score += 12.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && next_item_size > bin_residual {
        // Next item needs a fresh bin anyway; prefer consuming this bin's space.
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when many open bins have large residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_pressure = mean_residual / bin_capacity as f64;
        score += 20.0 + 30.0 * (1.0 - progress) + 15.0 * waste_pressure + open_bins_count as f64;
    }

    // Mild penalty for bins far from mean residual (fragmentation avoidance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling: post_residual weighted by stream progress.
    // Later in the stream, dead space is punished more aggressively (higher powers).
    let progress_weight = 0.5 + 1.5 * progress;
    let mut score = pr * progress_weight + x * x * cap * progress;

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * fit_ratio * 20.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward if the next item fits the post-residual (chaining).
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let chain = next_item_size as f64 / cap;
        score -= 10.0 * chain * (1.0 - progress);
    }

    // Penalize opening a new bin when many bins already fit the item poorly.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus discount if few fitting bins exist.
        score += 15.0 - 5.0 * (fitting_bins_count as f64).ln().max(0.0);
        // Late stream: discourage proliferation of open bins.
        score += 0.3 * open_bins_count as f64 * (0.5 + progress);
    }

    // Mild alignment with mean residual: prefer bins whose post-residual stays near the mean.
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues near capacity fractions are
    // "usable" classes; odd/dead residues are penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class by integer division into capacity octants (harmonic classes 1/8..)
    let octant = (post_residual * 8) / bin_capacity; // 0..7
    // Reward residuals that are small but still reusable by common item sizes
    match octant {
        0 => score -= 12.0,          // near-perfect fit, excellent
        1 => score -= 4.0,           // good
        2 => score += 1.0,
        3 => score += 3.0,           // mid dead zone
        4 => score += 4.0,
        5 => score += 3.0,
        6 => score -= 2.0,           // large residual, still flexible
        _ => score -= 6.0,           // nearly empty bin, keep flexible
    }

    // Modulo-10 class: residuals divisible by 10 pair well with 10..80 items
    let m10 = post_residual % 10;
    if m10 == 0 {
        score -= 6.0;
    } else if m10 == 5 {
        score += 1.5;
    } else {
        score += m10 as f64 * 0.6; // ragged residual penalty
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap);
        } else {
            // next item cannot follow here; slight penalty proportional to overshoot class
            let over = next_item_size - post_residual;
            score += (over % 20) as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        // penalize opening a bin when open bins have plenty of room
        score += 18.0 * pressure.max(0.0);
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: new bin is fine
        }
        // late in stream, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score += 0.5 * (pr - mean_residual).max(0.0);

    // Mild penalty for many open bins: encourage filling existing ones
    score += (open_bins_count as f64).sqrt() * 0.8;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never fit even the
    // smallest future item (<= 10) are pure waste; penalize them hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        // Small unusable-ish gap: penalize proportionally to how close it is
        // to being a dead zone.
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits (post_residual small relative to bin_residual).
    let fit_ratio = if bin_residual > 0 {
        item_size as f64 / bin_residual as f64
    } else {
        0.0
    };
    score -= fit_ratio * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new
    // bins (penalize the empty-bin candidate implicitly via residual logic,
    // but also add pressure scaled by open bin count for wasteful fits).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.4 * (0.5 + 0.5 * progress);

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is already fragmented; prefer filling fragmented bins first.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.6;
    } else {
        score += (res - mean_residual) * 0.3;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward
    // this placement strongly (creates a perfect pair).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 15.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Next item won't fit here; slight penalty if gap becomes dead.
            if post_residual < 10 {
                score += 20.0;
            }
        }
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Only attractive when no good fit exists among open bins, i.e. when the
    // current fit is very loose. Penalize the empty bin otherwise.
    if bin_residual == bin_capacity {
        if fit_ratio < 0.7 && !(fitting_bins_count == 1) {
            score += 35.0;
        } else {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 30.0 * tightness;

    // Aggressive 2-step lookahead: reward if next item fits the post residual exactly/well
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_fit = (next_item_size as f64) / (post_residual as f64).max(1.0);
            score -= 40.0 * next_fit;
            // Perfect chain: post_residual exactly equals next item
            if next_item_size == post_residual {
                score -= 25.0;
            }
        } else {
            // Next item won't fit here; penalize leaving large unusable gaps
            let gap = (post_residual as f64) / (bin_capacity as f64);
            score += 20.0 * gap;
        }
    } else {
        // Last item: prefer filling as much as possible
        score += 5.0 * (post_residual as f64) / (bin_capacity as f64);
    }

    // Compare post_residual to mean residual across open bins
    let dev = (post_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 15.0 * dev;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize mildly so we only open when open bins fit badly,
    // but allow it late in the stream or when nothing fits well.
    if bin_residual == bin_capacity {
        let bad_fit = fitting_bins_count == 0
            || (next_item_size > 0 && post_residual < next_item_size && post_residual > 0);
        if bad_fit {
            score -= 10.0;
        } else {
            score += 45.0;
        }
    }

    // Stream progression: as stream advances, slightly prefer consolidating into fewer bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (open_bins_count as f64).ln().max(0.0) / (1.0 + mean_residual / 50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where item nearly fills residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that no future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item cannot use this residual: mild penalty if residual is small
            if post_residual < 15 {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer bins below mean residual (poorer bins absorb item, preserving richer bins).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Time horizon: early on, be conservative about fragmentation; late, just pack tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.2 * progress;

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 35.0;
        // If item is large, opening fresh may be fine.
        if item_size as f64 / bin_capacity as f64 > 0.6 {
            score -= 25.0;
        }
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score += 0.05 * open_bins_count as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual (0..1)
    let pr_norm = post_residual as f64 / bin_capacity as f64;

    // Smooth polynomial coupling: dead space matters more as stream progresses
    let coupling = pr_norm * pr_norm * (0.5 + 2.0 * progress);
    score += 20.0 * coupling;

    // Reward tight fits (small post_residual), amplified late in the stream
    let tightness = 1.0 - pr_norm;
    score -= 10.0 * tightness * tightness * (0.5 + progress);

    // Lookahead: reward if next item fits the post residual smoothly
    if next_item_size > 0 && post_residual > 0 {
        let fits_next = (next_item_size as f64) <= post_residual as f64;
        let gap = ((post_residual as f64) - (next_item_size as f64)).abs() / bin_capacity as f64;
        if fits_next {
            score -= 8.0 * (1.0 - gap) * (0.5 + progress);
        } else {
            score += 6.0 * gap * (0.5 + progress);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize spreading across too many open bins when residuals are large
    let mean_norm = mean_residual / bin_capacity as f64;
    score += 0.5 * open_bins_count as f64 * (1.0 - mean_norm);

    // New-bin candidate: make it moderately attractive only when existing bins fit poorly
    if bin_residual == bin_capacity {
        score = 30.0 + pr_norm * 0.0 + 0.3 * open_bins_count as f64;
        if fitting_bins_count == 1 {
            // an existing bin is a last chance; discourage new bin strongly
            score += 40.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin useful for upcoming larger item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, with harmonic (1/post) refinement
    let pr = post_residual as f64;
    if post_residual == 0 {
        score = -50.0; // perfect fit is always best
    } else {
        score = pr + 20.0 / pr;
    }

    // Harmonic class of post_residual: residue classes mod capacity fractions
    let cap = bin_capacity as f64;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let eighth = bin_capacity / 8;

    // Penalize post_residual in "awkward" classes: small nonzero residues that
    // few future items can fill (items are 1..100, but small residues waste bins)
    if post_residual > 0 && post_residual < eighth {
        score += 25.0; // dead space class
    } else if post_residual >= eighth && post_residual < quarter {
        score += 10.0;
    } else if post_residual > half {
        score += 5.0 * (post_residual as f64 - half as f64) / half as f64;
    }

    // Reward post_residual that is a "harmonic divisor" of capacity:
    // residue divisible by 25 or 20 pairs well with common item sizes
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            // penalize leaving another awkward residue for the step after next
            if nxt_post < eighth && nxt_post > 0 {
                score += 12.0;
            } else {
                score -= 6.0 * (1.0 - nxt_post as f64 / cap);
            }
        } else {
            // next item won't fit here; slight penalty proportional to mismatch
            score += 3.0 + 0.1 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: only attractive when open bins are very full
    // (mean residual low) or stream is early and few bins are open
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let openness = open_bins_count as f64;
        // penalty grows with number of open bins and stream progress
        score = mean_residual + 10.0 + 8.0 * openness * (0.3 + 0.7 * progress);
        // if mean residual across open bins is large, opening new bin is bad
        score += 0.5 * mean_residual;
        // exception: if even the best fit would leave tiny dead space and
        // next item is large, opening fresh bin can win
        if next_item_size > half as u32 && pr < eighth && pr > 0 {
            score -= 30.0;
        }
    }

    // Mild tie-breaking by tightness of current fit
    score += 0.01 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (items >= 1, but practically >= 10) are pure waste.
    // Penalize post_residual in the "unusable gap" band [1, 9] heavily.
    if post_residual >= 1 && post_residual <= 9 {
        score += 40.0; // dead space: worst outcome, nothing can ever fill it
    }

    // Perfect fit reward: zero residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Moderate residual is usable; slight reward proportional to how well
    // the next item could slot in (lookahead k=2).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits here: strong reward for chain packing
            score -= 12.0 * (next_item_size as f64 / 100.0);
        } else if post_residual > 0 {
            // gap left behind that next item cannot use: soft penalty
            score += 6.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing bins
    // (tighter fits) over spreading; with few open bins, new bins are cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 8.0;

    // Deviation from mean residual: prefer bins whose residual is close to
    // the item need (tight packing) rather than outliers.
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Early in the stream, slightly favor opening bins to build a diverse
    // residual portfolio; late in the stream, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when
        // decent fitting bins exist.
        score += 10.0 + 25.0 * progress;
        if fitting_bins_count >= 1 {
            score += 8.0 * (fitting_bins_count as f64).min(5.0);
        }
    } else {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with a mild quadratic penalty
    // on wasted space so that very loose fits are strongly discouraged.
    let waste = post_residual as f64;
    score += 0.02 * waste * waste / bin_capacity as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the
    // next item size exactly or nearly (chain-fill bonus).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let gap = (post_residual as f64 - nxt).abs();
            // Perfect chain fit: big subtraction.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
            // Extra bonus when the next item fills the bin almost exactly.
            if gap <= 5.0 {
                score -= 25.0;
            }
        } else {
            // Post-residual cannot host next item: penalize proportionally to
            // how close it came (near-miss dead space is worst).
            let miss = nxt - post_residual as f64;
            score += 8.0 * (1.0 - miss / nxt.max(1.0));
        }
    } else {
        // Last item: pure tight fit, no future to plan for.
        score -= 20.0;
    }

    // Compare post_residual relative to mean residual across open bins:
    // leaving less than the mean residual is good (compact bins).
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.15 * mean_gap;

    // Last-chance bin: if this is the only bin that fits, strongly favor using
    // it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): penalize so we only open new bins when
    // no decent fit exists among open bins.
    if bin_residual == bin_capacity {
        score += 60.0;
        // But if the item is large relative to capacity and no lookahead chain
        // is possible, opening fresh is less bad.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 35.0;
        }
        // If next item is large too, a fresh bin can host a good pair.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Early in the stream, be slightly more willing to spread items (more bins
    // with flexible residuals); late, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - waste / bin_capacity as f64);

    // Slight penalty for accumulating too many open bins.
    score += 0.5 * open_bins_count as f64 * (waste / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that cannot hold the next item (lookahead coupling)
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else {
            score -= 0.3 * (next_item_size - post_residual).min(10) as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize opening new bins when decent fits exist; allow it when bin is crowded state
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 30.0 + 25.0 * (1.0 - progress) + 2.0 * crowd;
        // allow new bin if item is large relative to mean residual (poor fit everywhere)
        score -= (item_size as f64 - mean_residual).max(0.0) * 0.8;
    }

    // Mild preference for bins with below-average residual (consolidate fullness)
    score += 0.25 * (bin_residual as f64 - mean_residual).max(0.0);

    // Encourage filling bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: prefer tight fits mildly (quadratic in normalized residual).
    // Late in stream: strongly penalize large residuals (wasted capacity matters more).
    let norm_res = pr / cap; // in [0,1]
    let early_w = (1.0 - progress).powi(2);
    let late_w = progress.powi(2);
    score += early_w * 2.0 * norm_res * norm_res * cap;
    score += late_w * 6.0 * norm_res * norm_res * cap;

    // Reward filling bins nearly perfectly: cubic bonus for small post_residual.
    score -= (1.0 - norm_res).powi(3) * 12.0;

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt).abs();
        score -= 10.0 * (1.0 - diff / cap).powi(2);
        // Penalize leaving residual that can't fit the next item when this bin is a last chance.
        if pr < nxt && fitting_bins_count == 1 {
            score += 8.0 * (1.0 - pr / cap);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many open bins with low mean residual: prefer consolidating into tighter bins.
    let open_f = open_bins_count as f64;
    score += 0.5 * open_f * (pr / cap - mean_residual / cap).abs();

    // Mild penalty for opening new bins early in the stream.
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 0.3 * open_f;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by capacity fractions.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post = post_residual;

    // Penalize dead space that no plausible item (1..=80) can use well.
    if post > 0 {
        if post < eighth {
            score += 40.0; // tiny unusable sliver
        } else if post < quarter {
            score += 12.0;
        } else if post < bin_capacity / 2 {
            score += 4.0;
        }
        // Modulo-based harmony: residuals that are multiples of common item sizes
        // (10, 20, 25, 50) are more reusable.
        if post % 10 == 0 { score -= 6.0; }
        if post % 25 == 0 { score -= 4.0; }
        if post % 50 == 0 { score -= 3.0; }
    }

    // Lookahead coupling: if the next item fits the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 30.0; // perfect pair
        } else if next_item_size <= post {
            let slack = (post - next_item_size) as f64;
            score -= 15.0 - slack * 0.3; // good chaining, decay with leftover
        } else {
            // next item won't fit here; mild penalty scaled by how far off
            score += ((next_item_size - post) as f64).min(30.0) * 0.2;
        }
    } else {
        // Last item: prefer tightest fill overall.
        score -= (bin_residual - item_size) as f64 * 0.5;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: opening a fresh bin should only win when fit is poor.
    // Baseline: an empty bin has post_residual = capacity - item_size, already
    // scored; add a mild penalty so existing bins with decent fit win, but
    // reward opening when current bins are fragmented (high mean residual spread).
    if bin_residual == bin_capacity {
        score += 10.0;
        if mean_residual < cap * 0.25 && open_bins_count > 0 {
            // open bins are nearly full; a new bin is fine
            score -= 15.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
    }

    // Mild global pressure: many open bins -> favor consolidating into existing ones.
    score += (open_bins_count as f64) * 0.15;

    // Slight preference for tighter fits overall.
    score += (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small for the smallest item (1..100, min ~1)
    // Treat post_residual < 10 as near-dead; scale penalty nonlinearly.
    if post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual < 20 {
        score += 15.0 * (20.0 - post_residual as f64);
    }

    // Reward tight fits (small post_residual relative to bin_residual)
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 40.0 * fill_ratio * fill_ratio;
    }

    // Open bins pressure: discourage adding load to a bin when many bins are open
    // and this bin is already well-filled — prefer consolidating.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits into post_residual, reward leaving that gap
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // gap won't hold next item; penalize proportionally
        score += 0.3 * post_residual as f64;
    }

    // Mild early-stream preference to open bins and build a diverse residual pool
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: prefer it when few fitting bins or residual pool is fragmented
        score = 100.0 - 30.0 * progress - 5.0 * (fitting_bins_count as f64);
        if fitting_bins_count == 0 {
            score -= 200.0; // must open
        }
        if next_item_size > 0 && next_item_size > bin_capacity - item_size.min(bin_capacity) {
            score -= 20.0;
        }
    } else if mean_residual > 0.0 {
        // Prefer bins below mean residual (less-filled bins absorb the item)
        let dev = (bin_residual as f64 - mean_residual) / mean_residual;
        score += 5.0 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: penalize opening a fresh bin unless it is the only option.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 + 40.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 200.0; // forced: no open bin fits
        }
        return score;
    }

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 150.0;
    }

    // Post-residual can still accommodate the next item: reward tighter fits.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Dead space: post_residual smaller than next item (and not zero) is wasted.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Perfect closure: item fills the bin exactly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Prefer bins whose residual is far from the mean (deviant, well-used bins).
    let dev = (post_residual as f64 - mean_residual).abs();
    score -= 0.3 * dev;

    // Mild preference for bins that are already fairly full.
    score -= 0.2 * (bin_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let npr = pr / cap;
    let fit = fitting_bins_count as f64;
    // smooth non-linear coupling of residual waste with stream progress
    score += 40.0 * npr * npr * (0.5 + 0.5 * progress);
    score -= 12.0 * (1.0 - npr) * (1.0 - npr) * progress * (1.0 - progress);
    // penalize near-full residual when a next item exists that could use it
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        score -= 8.0 * (gap / cap) * (gap / cap);
        score += 5.0 * (1.0 - (pr / cap).min(1.0)) * progress;
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }
    // prefer bins tighter than mean residual, smoothly
    score += 0.5 * (pr - mean_residual) * (1.0 - progress);
    // slight preference against opening new bins late in the stream
    score += 3.0 * progress * (open_bins_count as f64).sqrt();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "reusable class" (multiples of small divisors) are more valuable.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    if pr > 0 {
        // Reusability bonus: leftover divisible by common small sizes.
        let mut reuse_bonus = 0.0;
        for d in [10u32, 20, 25, 50].iter() {
            if pr % d == 0 {
                reuse_bonus += 6.0;
            }
        }
        if pr % 5 == 0 {
            reuse_bonus += 2.0;
        }
        score -= reuse_bonus;

        // Penalize dead space in awkward classes (prime-ish / large odd gaps).
        if pr > 40 && pr % 10 != 0 {
            score += (pr as f64 - 40.0) * 0.4;
        }
    } else {
        // Perfect fill is best possible.
        score -= 100.0;
    }

    // Tight fit reward: relative fill fraction.
    let fill_frac = item_size as f64 / cap;
    score -= fill_frac * 25.0;

    // Lookahead coupling: does the leftover accommodate the next item's class?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain-friendly: leftover can host next item.
            score -= 8.0;
            if post_residual == next_item_size {
                score -= 12.0; // exact chain: two perfect fills
            }
        } else {
            // Leftover too small for next item: dead space risk.
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    } else {
        // Last item: prefer exact closure, residual value irrelevant.
        score *= 0.1;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open
    // bins would leave terrible residue and we don't have too many open.
    if bin_residual == bin_capacity {
        score += 10.0; // mild default penalty for opening new bins
        if open_bins_count == 0 {
            score -= 60.0; // must open when nothing is open
        }
        if fitting_bins_count > 0 {
            // Extra deterrent if decent fits exist.
            score += mean_residual.min(cap) * 0.2;
        }
        // Late in stream, opening new bins is wasteful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Mild preference to fill bins below mean residual (balance consolidation).
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are unusable for future items (min size 1..100 unknown,
    // but gaps < ~10 are almost always dead). Penalize superlinearly.
    if post_residual > 0 && post_residual <= 10 {
        score += (11 - post_residual as i32) as f64 * 25.0;
    }
    // Medium gaps (11..=25) are risky too.
    if post_residual > 10 && post_residual <= 25 {
        score += (25.5 - post_residual as f64) * 2.0;
    }

    // Reward tight fits (perfect or near-perful packing).
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead: bonus if the next item fits exactly into the resulting gap.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0;
        } else if next_item_size < post_residual {
            let gap_after_next = post_residual - next_item_size;
            if gap_after_next <= 10 {
                score -= 30.0 - gap_after_next as f64;
            }
        } else {
            // Next item won't fit here: slight penalty proportional to wasted lookahead potential.
            score += 5.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins; encourage consolidation.
    score += open_bins_count as f64 * 3.0;

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Mean residual coupling: if this bin is much emptier than average, it's a good host.
    score -= (bin_residual as f64 - mean_residual) * 0.5;

    // New-bin candidate handling: allow opening a new bin when all existing fits are poor.
    // Empty bin has post_residual = capacity - item_size (large), so it naturally scores well
    // unless an open bin gives a tight fit. Add mild preference against proliferation early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }
    // Near match: next item fits tightly in the remaining space.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item does NOT fit here: penalize proportionally to how badly it misses.
    if next_item_size > 0 && next_item_size > post_residual {
        let miss = (next_item_size - post_residual) as f64;
        score += 10.0 * (miss / 100.0).min(1.0);
    }

    // Penalize residuals far above mean (wasted space relative to fleet average).
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Reward tight fits: small post_residual relative to capacity.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer consolidating into fewer bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 / (open_bins_count.max(1) as f64).sqrt();

    // New-bin candidate: only attractive if no open bin fits reasonably.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.1;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Dead-space penalty: superlinear waste, scaled by how much room remains globally.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 6.0 * dead * dead;

    // Lookahead: reward if next item fits exactly into post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize leaving mid-range gaps
            let gap = post_residual as f64;
            if gap > 0.0 && gap < next_item_size as f64 {
                score += 0.15 * gap;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Crowding: many open bins -> consolidate into existing bins.
    score += 0.8 * open_bins_count as f64;

    // Mean-residual coupling: if open bins are slack on average, prefer tight fits.
    score += 0.3 * (mean_residual - post_residual as f64);

    // Time horizon: early on, keep bins openable (favor new bins slightly);
    // late in stream, avoid opening new bins.
    if is_new_bin {
        score += 40.0 * (1.0 - progress);
        // opening a new bin only worth it if item is large relative to residual alternatives
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
    } else {
        score -= 12.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let base = pr * (1.0 + 0.35 * progress * norm_pr * norm_pr);

    // Smooth penalty for large dead space, scaled by progress
    let dead = 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    let tight_bonus = -8.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.4 + 0.6 * progress);

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    let last_chance = if fitting_bins_count == 1 { -15.0 * (1.0 + progress) } else { 0.0 };

    // Lookahead: reward if next item can fit into the post residual
    let lookahead = if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits = (pr >= nx) as i32 as f64;
        let waste_gap = ((pr - nx) / cap).max(0.0);
        fits * (6.0 - 4.0 * waste_gap) - 3.0 * (1.0 - fits) * waste_gap
    } else {
        0.0
    };

    // Mild penalty for spreading across many open bins when residuals are high
    let spread = 0.4 * open_bins_count as f64 * mean_residual / (cap * 10.0);

    base + dead + tight_bonus + last_chance + lookahead + spread
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual is a "nice" fraction
    // of capacity (e.g. exactly cap/2, cap/3, cap/4) are more reusable.
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    if post_residual == 0 {
        score -= 60.0; // perfect closure is always best
    } else if post_residual == half {
        score -= 25.0;
    } else if post_residual == third {
        score -= 18.0;
    } else if post_residual == quarter {
        score -= 12.0;
    } else if post_residual == eighth {
        score -= 6.0;
    }

    // Modulo arithmetic: residuals divisible by small integers pack better
    // against typical item sizes (gcd-friendly chunks).
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    if post_residual % 5 == 0 {
        score -= 3.0;
    }
    if post_residual % 4 == 0 {
        score -= 2.0;
    }
    // Penalize awkward prime-ish / odd residuals
    if post_residual % 2 == 1 && post_residual < 20 {
        score += 6.0;
    }

    // Lookahead coupling: does post_residual match the next item exactly or in
    // an integer-division-friendly way?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect follow-up fit
        } else if post_residual >= next_item_size {
            let div = post_residual / next_item_size;
            if div >= 2 {
                score -= 10.0 + 4.0 * div as f64; // multiple future fits
            } else {
                score -= 6.0; // at least one future fit
            }
            // Harmonic match: next item divides post_residual evenly
            if post_residual % next_item_size == 0 {
                score -= 8.0;
            }
        } else {
            // next item cannot use this residual: dead-space risk grows
            // when residual is small and odd-shaped.
            let frac = post_residual as f64 / cap;
            if frac < 0.25 {
                score += 10.0 + 20.0 * (0.25 - frac);
            }
        }
    }

    // Last-chance bin: strongly reward using it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // current item leaves a very clean residual or no bin fits well.
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: modest penalty so decent fits in open
        // bins win, but very fragmented open bins lose.
        score = 30.0
            - 0.15 * mean_residual
            + if post_residual % 10 == 0 { 0.0 } else { 5.0 }
            + if next_item_size > 0 && next_item_size <= post_residual { -10.0 } else { 0.0 };
        // early in the stream, fresh bins are cheaper to open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Tight-fit bonus: item fills most of the bin
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.9 {
        score -= 20.0;
    } else if fill > 0.75 {
        score -= 10.0;
    }

    // Penalize leaving many open bins with large residuals while fragmentation
    // is high (mean residual far from typical useful sizes).
    if open_bins_count > 3 && post_residual as f64 > mean_residual + cap * 0.2 {
        score += 4.0;
    }

    // Small absolute residual is good (bin nearly full)
    score -= 0.05 * (cap - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible item (<= ~10) are pure waste; penalize hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 15 {
        score += 25.0;
    } else if post_residual <= 25 {
        score += 8.0;
    } else if post_residual <= 40 {
        score -= 4.0; // mid-range gap is still reusable
    }

    // Perfect / near-perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 3 {
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement heavily (chaining good fits).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / 100.0);
    }
    // Penalize leaving a gap that just barely fails to fit the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 15.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones and
    // discourage opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // New empty bin candidate: make it moderately attractive only when the
    // item is large relative to residuals and fits are scarce; otherwise
    // discourage spreading across bins.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 25.0 - 45.0 * scarcity - 20.0 * big_item + 10.0 * open_bins_count as f64;
        // Late in the stream, opening a fresh bin for a big item is fine.
        score -= 15.0 * progress * big_item;
    }

    // Slight preference for bins whose residual is above the mean
    // (keeps a spread of usable gaps rather than many tight ones).
    score += 0.15 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (best-fit core).
    score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match => big reward.
        if diff == 0.0 {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Next item fits: reward proportional to closeness.
            score -= 20.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leaving residual that traps us.
            score += 5.0 + diff / 10.0;
        }
    }

    // Compare post_residual relative to mean residual across open bins.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 0.5 {
            score -= 8.0 * (0.5 - rel); // tighter than average: good
        } else {
            score += 4.0 * (rel - 0.5); // looser than average: mild penalty
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.6;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            // Existing last-chance bin: only open new bin if its residual is small (bad fit).
            score -= 10.0;
        }
        // Later in the stream, be more conservative about opening bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    }

    // Mild penalty for very small dead space that is unlikely reusable.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
