pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = (1.0 - progress) * norm_pr.powi(2) + progress * norm_pr.powi(3);
    score += 40.0 * poly;

    // Reward tight fits more as stream progresses
    score -= (1.0 - norm_item) * (1.0 + 2.0 * progress) * 10.0;

    // Penalize creating residual that can't hold the lookahead item
    if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        score += 15.0 * (1.0 - progress);
    }
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0 * norm_pr;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Prefer bins with residual near mean (balance), smooth interaction
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev * (0.5 + progress);

    // Mild penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 5.0 + 3.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: quantize into capacity fractions.
    let post = post_residual as f64;
    let frac = post / cap; // 0.0 (perfect fit) .. 1.0 (empty bin)

    // Reward near-perfect fits strongly (non-linear).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 12.0;
    } else if post_residual <= 30 {
        score -= 4.0;
    }

    // Penalize residuals that no plausible item can fill:
    // dead space = residual smaller than the smallest item class.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Harmonic coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // exact chained fit
        } else if next_item_size < post_residual {
            // smoother residual after chaining: reward proportionally
            let chained = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - chained / cap);
        } else {
            // next item cannot follow here: penalize if this placement strands space
            score += 0.3 * post;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when open bins are badly fragmented
    // (item fits poorly everywhere). Compare fit quality vs mean residual.
    if bin_residual == bin_capacity {
        let fit_quality = (bin_residual - item_size) as f64 / cap;
        let fragmentation = if mean_residual > 0.0 { (mean_residual - (bin_residual - item_size) as f64).abs() / mean_residual.max(1.0) } else { 1.0 };
        // Opening a new bin costs ~1 bin; only worth it if existing bins waste a lot.
        score = 100.0 - 25.0 * fragmentation + 20.0 * fit_quality;
        if open_bins_count == 0 {
            score -= 100.0; // must open when nothing is open
        }
    } else {
        // Slight preference for bins already below mean residual (consolidation).
        score += 0.15 * ((mean_residual - (bin_residual - item_size) as f64).max(0.0));
    }

    // Late-stream consolidation: fewer bins preferred as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (open_bins_count as f64).ln().max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual < item_size {
        // gap cannot fit the current item stream sizes; penalize small gaps harder
        let gap = post_residual as f64;
        if gap < 10.0 {
            score += 60.0 * (10.0 - gap) / 10.0; // tiny dead space is worst
        } else {
            score += 15.0;
        }
    }

    // Reward tight fits (small post_residual) nonlinearly.
    score -= 40.0 * (-post_residual as f64 / 20.0).exp();

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        let lookahead_bonus = if next_item_size > 0 && next_item_size as f64 <= post_residual as f64 { 0.0 } else { 10.0 };
        score += 25.0 + pressure * 1.5 + lookahead_bonus;
        // late in stream, prefer filling existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    } else {
        // favor bins whose residual is close to the item (minimize waste)
        let slack = (bin_residual as f64 - item_size as f64).abs();
        score += slack * 0.3;
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    }

    // Mild alignment with mean residual: prefer bins below mean residual (tighter).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: neutral baseline, penalize opening unless existing bins fit poorly.
    if bin_residual == bin_capacity {
        let mut nb = 55.0;
        if fitting_bins_count > 0 {
            nb += 10.0;
        }
        return nb;
    }

    // Aggressive 2-step lookahead: reward near-perfect match between post_residual and next_item_size.
    if next_item_size > 0 {
        let diff = if post_residual >= next_item_size {
            (post_residual - next_item_size) as f64
        } else {
            (next_item_size - post_residual) as f64 * 2.5
        };
        score -= 30.0 / (1.0 + diff * 0.15);

        // Perfect chain: next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Next item fits with small slack -> strong reward.
        if post_residual >= next_item_size && post_residual - next_item_size <= 5 {
            score -= 15.0;
        }
        // Next item would NOT fit here anyway; mild bonus for leaving large usable space.
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 40.0;
    }

    // Reward bins with residual below mean (consolidating waste).
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize creating dead space that likely fits no future item (sizes >= 1).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Prefer filling bins tighter relative to capacity as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64 / bin_capacity as f64) * (5.0 + 10.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: perfect fill is heavily favored.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space nonlinearly; small residuals are much worse than large ones.
        let dead = post_residual as f64;
        score += (dead * dead) / (bin_capacity as f64 * 0.25);
    }

    // Lookahead: if the next item can fit into the post-residual, reward this bin;
    // otherwise penalize leaving a residual that is useless for the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // Wasted residual relative to next item's needs
            let waste = (post_residual as f64 - (next_item_size as f64 - post_residual as f64).max(0.0)).max(0.0);
            score += waste * 0.05;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + item_size as f64 * 0.2;
    }

    // New-bin candidate handling: opening a new bin is expensive when open bins exist
    // and the item fits reasonably well elsewhere. Penalize the empty-bin candidate,
    // but allow it when the item is large (hard to place later) or few bins fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = (open_bins_count as f64).ln().max(1.0);
        let mut new_bin_penalty = 40.0 + openness * 10.0;
        // Late in the stream, prefer closing out existing bins.
        new_bin_penalty *= 1.0 + progress;
        // Large items are risky to squeeze into partial bins.
        if item_size > 60 {
            new_bin_penalty *= 0.4;
        }
        if fitting_bins_count <= 1 {
            new_bin_penalty *= 0.5;
        }
        score += new_bin_penalty;
    }

    // Mild global pressure: when mean residual across open bins is high,
    // encourage consolidating into bins with larger residuals.
    if bin_residual != bin_capacity {
        score -= (bin_residual as f64 - mean_residual) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64 / cap;
    // Smooth polynomial coupling: post-residual penalty grows non-linearly with stream progress
    let prog_term = progress * progress * (1.0 - progress);
    score += 18.0 * pr * pr * (0.5 + progress);
    score -= 12.0 * prog_term * (1.0 - pr);
    // Penalize dead space near unusable range, smoothly
    let dead = ((pr - 0.2).max(0.0) * (0.35 - pr).max(0.0)).max(0.0);
    score += 25.0 * dead;
    // Reward tight fits
    score -= 10.0 * (1.0 - pr) * (1.0 - pr) * (1.0 - progress);
    // Lookahead: reward residual that can host next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fits = (pr - nx).max(0.0);
        score -= 8.0 * fits / (1.0 + nx);
    }
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - pr);
    }
    // Mean residual divergence penalty
    score += 0.5 * (post_residual as f64 - mean_residual).abs() / cap;
    // Mild pressure to consolidate when many bins open
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residues modulo small divisors
    // capture "dead space classes" (residuals like 1..9 are nearly unusable).
    let r = post_residual;
    let class_penalty: f64 = if r == 0 {
        -40.0 // perfect fit: strongly reward
    } else if r < 10 {
        30.0 + (10 - r) as f64 * 2.0 // tiny dead space is worthless
    } else if r % 10 == 0 {
        -12.0 // residual aligned to decade: reusable by typical items
    } else if r % 5 == 0 {
        -6.0
    } else {
        ((r % 5) as f64) * 1.5 // misaligned residue penalty
    };
    score += class_penalty;

    // Integer-division threshold: can the lookahead item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= r {
            // Coupling: reward residuals that leave room for the next item,
            // scaled by how tightly the next item will nest (harmonic pairing).
            let tightness = 1.0 - (r - next_item_size) as f64 / bin_capacity as f64;
            score -= 10.0 + 15.0 * tightness;
        } else {
            // Residual cannot host the next item: penalize proportionally to waste.
            score += 6.0 + (next_item_size - r) as f64 * 0.1;
        }
        // Harmonic pair check: item + next exactly filling a capacity fraction.
        let s = item_size + next_item_size;
        if s == bin_capacity {
            score -= 25.0;
        } else if bin_capacity % s == 0 && s <= bin_capacity {
            score -= 8.0; // splits capacity into equal harmonic parts
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 14.0;
    }

    // New-bin candidate: penalize opening fresh bins unless current fit is bad
    // and stream is early (many items remain to exploit a fresh bin).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let base = 18.0 + 25.0 * (1.0 - progress);
        // Attractive if item leaves a "harmonic" residual in a fresh bin.
        let fresh_bonus = if r == 0 { -30.0 } else if r % 10 == 0 { -10.0 } else { 0.0 };
        score += base + fresh_bonus;
    }

    // Prefer bins whose residual deviates favorably from the fleet mean:
    // packing into below-mean-residual bins consolidates fragmentation.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Slight preference for fewer open bins overall (encourage consolidation).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never be used again
    // (below the minimum item size) are heavily penalized.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual <= 15 {
        score += 18.0;
    } else if post_residual <= 25 {
        score += 6.0;
    } else {
        // Larger usable gaps are mildly rewarded relative to raw residual.
        score -= 4.0;
    }

    // Reward very tight fits (small post_residual relative to item size).
    let fit_ratio = if item_size > 0 { post_residual as f64 / item_size as f64 } else { 1.0 };
    if fit_ratio <= 0.05 {
        score -= 30.0;
    } else if fit_ratio <= 0.15 {
        score -= 15.0;
    } else if fit_ratio <= 0.35 {
        score -= 5.0;
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual < 10 {
            score -= 10.0; // still better than wasting a fresh bin
        }
    }

    // Pressure from many open bins: prefer consolidating when bins are numerous.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.3 + 0.4 * progress);

    // Prefer bins whose residual is below the mean (i.e., filling the emptier-feeling
    // bins first keeps a few large-residual bins available for big items).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Lookahead: if the next item would fit exactly in the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 25.0;
        } else if gap < 10 {
            score -= 10.0;
        }
    }

    // New-bin candidate: neutral baseline; only chosen when all open bins
    // have poor fits (their scores pushed above this level).
    if bin_residual == bin_capacity {
        score += 25.0;
        // Early in the stream, opening bins is cheaper; later, avoid it.
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 40.0;

    // 2-step lookahead: reward if next item fits the post residual well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_waste = post_residual - next_item_size;
        // Perfect 2-step match (post_residual == next_item_size) is ideal.
        let match_ratio = next_item_size as f64 / post_residual as f64;
        score -= match_ratio * 35.0;
        // Penalize leftover after next item too.
        score += (next_waste as f64) * 0.25;
    } else if next_item_size > 0 {
        // Next item won't fit here; mild penalty unless this is a near-perfect fit now.
        score += 8.0;
    }

    // Reward exact fills (post_residual == 0).
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Compare against mean residual: bins with less residual than average
    // are more "loaded"; prefer filling the emptier bins only if fit is good.
    let diff = bin_residual as f64 - mean_residual;
    score += diff * 0.15;

    // New-bin candidate handling: empty bin should only win when no open bin
    // fits well. Penalize opening new bins mildly, more when many bins are open.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 20.0 + open_pressure * 6.0 + progress * 10.0;
        // If next item is large, a fresh bin is more attractive.
        if next_item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Small bonus for spreading load when many bins are open and this bin
    // would otherwise become dead space (post_residual < 10 but > 0).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let it = item_size as f64;
    let mut score = pr;

    // Strong reward for tight fits (small post_residual).
    score -= 10.0 * (-(pr / 12.0)).exp();

    // Prefer bins that are already more filled than the fleet average.
    let diff = mean_residual - bin_residual as f64;
    score += 2.0 * diff.signum() * ((diff.abs() / cap).min(1.0));

    // Lookahead coupling with next item (k=2).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            // Next item can use the leftover: keep this bin attractive.
            score -= 4.0 * (1.0 - nxt / cap);
        } else {
            // Leftover is dead space for the upcoming item: mild penalty.
            score += 2.0 * (1.0 - pr / cap);
        }
    }

    // Last-chance bin: strongly avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate (empty bin).
    if bin_residual == bin_capacity {
        // Baseline: residual after placing item into a fresh bin.
        score = it;
        // Opening a bin is cheap early (few bins open), expensive later.
        score += 0.5 * (open_bins_count as f64).sqrt();
        // If the next item also fits the fresh bin's remainder, opening is better.
        if next_item_size > 0 && (next_item_size as f64) <= pr {
            score -= 3.0;
        }
        // Never abandon the only bin that can fit the item.
        if fitting_bins_count == 1 {
            score += 15.0;
        }
    }

    // Slight drift toward conservatism as the stream progresses.
    score += (step_index as f64) / (total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fits (penalize large residuals more, super-linearly).
    // Late: mild tolerance for residuals since stream tail is short.
    let tightness = 1.0 + 2.0 * (1.0 - progress) * (1.0 - progress);
    score += tightness * (pr * pr) / cap;

    // Reward small post_residual cubically (very tight fits are excellent).
    score -= (1.0 - pr / cap).powi(3) * 10.0;

    // Perfect/near-perfect fill reward.
    if pr == 0 {
        score -= 50.0;
    } else if pr <= 5.0 {
        score -= 20.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= (1.0 - diff / cap).powi(2) * 8.0;
        // Penalize post_residual that is too small to ever fit typical items.
        if pr < next_item_size as f64 {
            score += 0.5 * (next_item_size as f64 - pr);
        }
    }

    // Coupling with mean residual across open bins: prefer bins below mean residual
    // (keep large spaces for larger future items) via smooth quadratic term.
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;
    score += 3.0 * dev; // prefer tighter-than-average bins

    // New-bin candidate handling: penalize opening a new bin, more so late in stream
    // or when other bins fit.
    if bin_residual == bin_capacity {
        let mut penalty = 12.0;
        if fitting_bins_count > 0 {
            penalty += 10.0 * (fitting_bins_count as f64).ln();
        }
        penalty += 10.0 * (1.0 - progress);
        // If next item is large, a fresh bin is more attractive.
        if next_item_size > 0 && next_item_size as f64 > 0.5 * cap {
            penalty -= 8.0;
        }
        score += penalty;
    }

    // Mild preference to spread load when many bins are open (balance residuals).
    score += 0.3 * (open_bins_count as f64).sqrt() * (1.0 - (pr / cap));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect closure (harmonic class 0 mod capacity fraction).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward bins whose post-residual can host the lookahead item (coupling k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.6 * next_item_size as f64;
        // Extra bonus for near-exact lookahead fit (harmonic class match).
        let diff = post_residual - next_item_size;
        if diff <= 5 {
            score -= 12.0;
        }
    } else if next_item_size > 0 {
        // Penalize residues that strand the lookahead item in a dead class.
        score += 0.25 * next_item_size as f64;
    }

    // Dead-space penalty: residues in (0, 10) are unusable (min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 3.0 * (10 - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.3 * open_bins_count as f64;

    // Pull toward bins with residuals below the mean (tighter bins first).
    score += 0.4 * ((post_residual as f64) - mean_residual);

    // New-bin candidate: only attractive if no open bin offers a good fit.
    if bin_residual == bin_capacity {
        let base = 0.75 * bin_capacity as f64;
        if fitting_bins_count == 0 {
            score = base - 40.0; // forced new bin
        } else if fitting_bins_count == 1 {
            score = base + 50.0; // keep the last-chance bin alive
        } else {
            score = base + 15.0 * (fitting_bins_count as f64).ln();
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical future items are nearly worthless. Penalize tiny gaps hard.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 3.0 }
                   else if post_residual < 20 { 2.0 }
                   else if post_residual < 30 { 1.0 }
                   else { 0.0 };
        score += dead * (post_residual as f64) * 0.5;
    } else {
        // Perfect fill is ideal.
        score -= 50.0;
    }

    // Reward placements that leave a gap still usable by the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.1 * post_residual as f64;
        } else if post_residual > 0 {
            // Gap is dead relative to the next item.
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage scattering across many open bins
    // unless the fit is good (post_residual already encodes fit quality).
    score += 0.4 * open_bins_count as f64;

    // Favor bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual - item_size) as f64;
    score += 0.3 * tightness;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score = 120.0 + 0.4 * open_bins_count as f64 - (mean_residual / bin_capacity as f64) * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits aggressively.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 350.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leaving medium dead space
            let dead = post_residual as f64;
            if dead >= next_item_size as f64 * 0.5 && dead < next_item_size as f64 {
                score += 40.0;
            }
        }
    }

    // Compare against mean residual: prefer bins whose residual is being consumed
    // relative to the fleet average (tighter-than-average bins get priority).
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (res - mean_residual) * 0.5;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin unless the item is large relative to capacity
    // or all existing fits are poor (high post_residual).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let frac = item_size as f64 / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut penalty = 60.0 + 40.0 * (1.0 - frac);
        if next_item_size > 0 && next_item_size >= post_residual {
            penalty -= 30.0; // empty bin guarantees next-item fit
        }
        if open_bins_count == 0 {
            penalty = -500.0; // must open first bin
        }
        penalty += 30.0 * progress;
        score += penalty;
    }

    // Mild preference for consolidating into fewer bins early on.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item's typical size
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            let waste = (post_residual as f64).min(next_item_size as f64);
            score += 0.6 * waste;
        } else if post_residual >= next_item_size {
            // reward bins that can still host the lookahead item
            score -= 5.0;
        }
    } else {
        // last item: strongly prefer tightest fit
        score -= 100.0 * tightness;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Many fitting bins: prefer the one that preserves flexibility (larger post_residual)
    if fitting_bins_count > 2 {
        score += 0.15 * (fitting_bins_count as f64 - 2.0) * (post_residual as f64 / bin_capacity as f64) * 10.0;
    }

    // Time horizon: early in stream, favor keeping residuals balanced; late, favor tight packing
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64 - mean_residual) * 0.3;
    score -= (1.0 - progress) * 10.0 * (1.0 - (mean_residual / bin_capacity as f64)).abs();

    // Penalize opening new bins when good open bins exist
    if bin_residual == bin_capacity {
        let new_bin_penalty = 25.0 + 0.5 * open_bins_count as f64 + 20.0 * (1.0 - progress);
        score += new_bin_penalty;
        // But if item is huge and no tight fit exists, opening is fine
        if item_size as f64 >= 0.7 * bin_capacity as f64 && fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mild preference for bins whose residual is close to the item (best-fit style)
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * fit_gap;

    // Discourage leaving residuals in the awkward 1..=10 dead zone
    if post_residual >= 1 && post_residual <= 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear (quadratic/cubic) shaping.
    let mut score = pr
        + 0.8 * cap * norm_pr * norm_pr
        + 0.3 * cap * norm_pr * norm_pr * norm_pr;

    // Smooth interaction of waste with stream progress: late in the stream,
    // dead space matters more (fewer future chances to fill it).
    let late_waste = (pr * pr) / cap;
    score += 1.5 * progress * late_waste;

    // Reward tight fits: subtract a smooth function of item_size/bin_capacity.
    let fit_ratio = item_size as f64 / cap;
    score -= 12.0 * fit_ratio * fit_ratio * (1.0 - progress * 0.5);

    // Penalize bins whose residual deviates from the mean residual (smooth coupling).
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev * cap;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * progress;
    }

    // Lookahead coupling: if the next item could fit into post_residual,
    // reward leaving that exact space (smooth gaussian-like term).
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let gap = (pr - next_item_size as f64) / cap;
        score -= 8.0 * (-gap * gap * 20.0).exp();
    } else if next_item_size > 0 {
        // Smooth penalty when the next item cannot fit the leftover space.
        let excess = (next_item_size as f64 - pr) / cap;
        score += 6.0 * (1.0 - (-excess * excess * 10.0).exp());
    }

    // Mild penalty for opening a new bin when many bins are open.
    if bin_residual == bin_capacity {
        score += 5.0 + 3.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo 10 define "usable" classes.
    let r = post_residual % 10;
    // Dead-space penalty: residual 1..9 is nearly unusable (items >= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }
    // Reward perfectly "harmonic" residuals: multiples of 10 are future-friendly.
    if r == 0 && post_residual > 0 {
        score -= 6.0;
    } else if r >= 1 && r <= 4 {
        score += (5 - r as f64) * 2.0; // small awkward remainder
    } else if r >= 6 && r <= 9 {
        score -= (r as f64 - 5.0) * 1.5; // large leftover half is reusable
    }

    // Integer-division threshold: post_residual / 10 buckets.
    let bucket = post_residual / 10;
    score -= bucket as f64 * 1.2;

    // Lookahead coupling: does post_residual harmonically fit next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward exact or near-exact next fit (harmonic pairing)
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 15.0;
            } else if gap < 10 {
                score -= 5.0;
            }
            // Reward if next_item_size divides post_residual nicely
            if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 {
                score -= 4.0;
            }
        } else {
            // Next item cannot use this residual: mild penalty scaled by waste
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when item is huge or stream early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fill_frac = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is good for very large items (little waste elsewhere)
        score -= fill_frac * 30.0;
        // Discourage proliferation of open bins mid-stream
        score += (open_bins_count as f64) * 3.0;
        // Early stream: new bins are cheap; late stream: prefer consolidation
        score -= (1.0 - progress) * 10.0;
        // Compare against mean residual: if open bins are full-ish, new bin ok
        score -= (bin_capacity as f64 - mean_residual).max(0.0) * 0.2;
    }

    // Prefer tighter bins generally: penalize by relative waste
    let waste = (post_residual as f64) / bin_capacity as f64;
    score += waste * 10.0;

    // Tie-break: exact fill is ideal
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Coupling: dead space hurts more when many bins are open (pressure to consolidate).
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64).max(1.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 3.0;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Prefer bins tighter than the mean residual (better fill).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: keep it neutral-slightly-high so we only open when fits are poor.
    if bin_residual == bin_capacity {
        score += 25.0;
        if post_residual < 20 {
            score += 20.0; // opening a bin for a huge item leaving tiny gap is fine actually; invert
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Two-step lookahead: reward residuals that exactly fit the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            score -= 0.5 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Dead space relative to the next item: penalize proportionally.
            score += 0.6 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Penalize small unusable residuals (dead space) nonlinearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 4.0;
    }

    // Compare against mean residual: prefer bins that are tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last chance: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when existing fits are poor or none exist.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a new bin
        } else {
            // Discourage opening a new bin when open bins can fit,
            // unless the item is large and would leave a tiny residual.
            let waste = (bin_capacity - item_size) as f64;
            if waste < 15.0 {
                score -= 50.0;
            } else {
                score += 120.0;
            }
        }
    }

    // Mild encouragement to fill older bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (small dead space).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Penalize leaving awkward dead space that few item sizes can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // small-but-usable gap is still decent
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 5.0; // awkward mid-range gap
    }

    // Lookahead: reward if the next item fits exactly in the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item won't fit here; mildly penalize creating a dead-end
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when the
    // item fits poorly in existing bins (large post_residual waste avoided)
    // or the stream is early and there is room to consolidate later.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early in stream: new bins are cheap-ish; late: prefer filling open bins.
        score += 18.0 + 30.0 * progress;
        // If many open bins already, discourage spreading further.
        score += open_bins_count as f64 * 1.5;
        // If the mean residual across open bins is large, prefer using them.
        score += mean_residual * 0.4;
        // Perfect-fit item into a fresh bin is great (full bin utilization).
        if item_size == bin_capacity {
            score -= 100.0;
        }
    }

    // Mild preference for filling bins that are already relatively full.
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fullness * 6.0;

    // Deterrent against creating residual equal to tiny unusable slivers (1-3).
    if post_residual >= 1 && post_residual <= 3 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Smooth non-linear coupling: quadratic post-residual scaled by progress
    let pr_norm = pr / cap;
    score += progress * 8.0 * pr_norm * pr_norm * cap;

    // Reward tight fits (small post residual) more strongly later in the stream
    score -= (1.0 - progress) * 6.0 * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Penalize bins whose residual deviates strongly from mean residual (smooth coupling)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev * (0.5 + progress);

    // Last-chance bonus: smooth sigmoid-like reward when this bin is the only fitting one
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - pr_norm);
    }

    // Lookahead: reward leaving room for the next item (smooth quadratic deficit penalty)
    if next_item_size > 0 {
        let deficit = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 5.0 * deficit * deficit;
    }

    // Mild penalty for spreading across many open bins, growing with progress
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: classify leftover space into capacity fractions.
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Dead-space penalty: tiny leftovers (< 10% of capacity) are nearly useless.
    if frac < 0.1 {
        score += 60.0 * (0.1 - frac) * 10.0;
    }

    // Reward exact-ish fits: post_residual divisible into small harmonic classes.
    if post_residual == 0 {
        score -= 100.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual % 10 == 0 {
        score -= 15.0; // residual re-usable by harmonic-size items (10,20,...)
    } else if post_residual % 5 == 0 {
        score -= 8.0;
    }

    // Modulo coupling: does the next item divide into the post-residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits here afterwards: strong reward, weighted by fit tightness.
        let tight = (post_residual - next_item_size) as f64;
        score -= 50.0 - tight.min(50.0);
        // Harmonic bonus if next_item_size is a divisor-class of post_residual
        if post_residual % next_item_size == 0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit after this placement: penalize slightly.
        score += 12.0;
    }

    // Last-chance bin: only one fitting bin; avoid opening a new bin for a decent fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when the fit here is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 0.55 * cap + 0.1 * open_bins_count as f64;
        // Attractive if current item leaves a harmonically useful residual in a fresh bin.
        if item_size % 10 == 0 {
            score += 5.0;
        }
        // Late in stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // If mean residual across open bins is large, opening new bins is wasteful.
        score += 0.4 * mean_residual;
    }

    // Prefer tighter existing bins slightly: small residual before placement is good.
    score += 0.15 * (bin_residual as f64 - item_size as f64).signum() * (bin_residual as f64 / cap);

    // Prefer bins that are fuller already (small residual relative to capacity).
    score += 20.0 * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
