    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64);
    score += 8.0 * pressure;

    // Penalize leaving residual far below mean (fragmenting a typical bin).
    if (mean_residual - post_residual as f64).abs() > 25.0 {
        score += 10.0;
    }

    // Slight preference for tight fits relative to item size.
    score -= (item_size as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Penalize proximity mismatch: near-misses are worse than far misses
        if post_residual >= next_item_size {
            // item could still be followed by next item: mild penalty proportional to gap
            score += 0.15 * gap;
        } else {
            // post_residual cannot fit next item: dead space penalty
            score += 0.35 * gap;
        }
    } else {
        // Last item: just minimize post residual (handled by base score)
    }

    // Small unusable leftovers are dead space: harsh penalty when post_residual is tiny but nonzero
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Relative to mean residual: bins tighter than average are more valuable to fill now
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Early in stream: slightly discourage opening new bins (prefer packing into existing)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when few bins are open or early in stream
        score += 30.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // If no existing bin fits well, opening a new bin is fine: handled by comparison
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items
    // (unusable sliver), but forgive exact fits.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // strongly favor this bin (chain placement).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // next item fits but leaves more waste afterwards: mild bonus
            let after = post_residual - next_item_size;
            score -= 8.0 * (1.0 - after as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: slight penalty for trapping space
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Many open bins: encourage filling existing bins rather than spreading.
    let openness = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    score += 10.0 * openness * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin is below the mean residual
    // (already well-filled), prefer it; if above mean, penalize slightly.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.15 * diff;

    // Time horizon: early in the stream, be conservative (mild penalty on
    // very tight fits to keep flexibility); late in the stream, squeeze hard.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * tightness;

    // New-bin candidate: make empty bins unattractive unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 45.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: post-residual, with smooth polynomial coupling to stream progress.
    // Later in the stream, waste matters more -> stronger penalty on large residuals.
    let mut score = pr * (1.0 + 0.8 * progress * progress) + 12.0 * progress * x * x;

    // Reward tight fits (small post_residual) with a smooth quadratic bonus.
    score -= 20.0 * (1.0 - x) * (1.0 - x) * (1.0 - progress);

    // Penalize residual that cannot fit the lookahead item (smooth hinge).
    let nx = next_item_size as f64;
    if nx > 0.0 {
        let gap = nx - pr;
        if gap > 0.0 {
            score += 2.5 * gap * gap / cap;
        } else {
            score -= 1.5 * (-gap) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild penalty proportional to crowding of open bins vs mean residual.
    score += 0.05 * (open_bins_count as f64) * (mean_residual - pr).abs() / cap;

    // New-bin candidate: neutral-ish baseline so it wins only over poor fits.
    if bin_residual == bin_capacity {
        score = 55.0 + 40.0 * progress + 0.5 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual (mod-10 classes over capacity 100) ---
    let pr = post_residual as i64;
    let cls = pr % 10;
    // Dead-space penalty: residuals that are "hard to fill" (small but nonzero classes)
    if pr > 0 && pr < 10 {
        score += 12.0; // unusable sliver
    } else if cls != 0 {
        score += (cls as f64) * 0.35; // mild penalty for non-aligned residual
    } else if pr == 0 {
        score -= 25.0; // perfect closure reward
    }

    // --- Integer-division thresholds on post_residual ---
    let quarter = bin_capacity / 4;          // 25
    let half = bin_capacity / 2;             // 50
    if pr >= half {
        score -= 6.0;                        // roomy bin, keep it attractive
    } else if pr >= quarter && pr < half {
        score += 1.5;                        // mid zone, neutral-ish
    } else if pr > 0 {
        score += 4.0;                        // tight zone
    }

    // --- Lookahead coupling (k=2): does next item fit the post residual? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic residue match: next item divides nicely into post space
            let m = post_residual % next_item_size.max(1);
            let bonus = if m == 0 { 14.0 } else { 7.0 };
            score -= bonus;
            score -= (next_item_size as f64) * 0.08; // bigger next item = better fill now
        } else {
            score += 3.0; // next item won't fit here; slight penalty
            // but if next item fits a *fresh* bin exactly, avoid wasting this bin's space
            if next_item_size == bin_capacity {
                score += 5.0;
            }
        }
    } else {
        // last item: strongly prefer exact closure or minimal waste
        score = post_residual as f64 * 2.0;
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 9.0; // only bin that fits: avoid opening a new bin
    } else if fitting_bins_count > 3 {
        score += 1.0; // plenty of alternatives, be pickier
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Fresh bin: attractive when current open bins are crowded or mean residual is low
        let pressure = mean_residual / bin_capacity as f64;
        score = (bin_capacity - item_size) as f64; // waste of a fresh bin for this item
        score -= pressure * 20.0;                  // more open-bin pressure -> more willing to open
        if open_bins_count == 0 {
            score -= 100.0;                        // must open first bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 4.0;                          // fresh bin can also host the next item
        }
        if fitting_bins_count == 0 {
            score -= 50.0;                         // nothing fits otherwise
        }
    }

    // --- Stream progression: early on, consolidate; late, allow more slack ---
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= t * 2.0;                              // slight bias shift over time
    if t < 0.25 && post_residual < quarter {
        score += 3.0;                              // early: discourage tight residuals
    }

    // --- Open-bin count modulation: discourage bin sprawl ---
    if open_bins_count > 6 {
        score -= (open_bins_count as f64).ln() * 1.2;
    }

    // --- Mean residual coupling: prefer bins close to the mean (balanced packing) ---
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // (or for the lookahead item) are wasted capacity -> heavy penalty.
    let dead_threshold = if next_item_size > 0 && next_item_size <= 10 { 10 } else { 10 };
    if post_residual < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual) as f64;
    } else {
        // Reward residuals that can still accommodate a future item,
        // scaled by how large the gap is (usable slack).
        score -= 0.5 * post_residual as f64;
    }

    // Lookahead coupling: strongly prefer bins whose post_residual fits the
    // next item exactly or well; penalize bins that leave the next item stranded.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
            // bonus for tight chained fit
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 10.0 * (10 - gap) as f64;
            }
        } else if post_residual > 0 {
            // next item can't use this gap: it becomes dead space
            score += 8.0 * post_residual as f64;
        }
    }

    // Open-bin pressure: discourage spreading across many bins; with few
    // open bins, filling existing ones is cheap and preferred.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.3 * open_bins_count as f64 * (0.5 + progress);

    // Last-chance bonus: if this is the only bin that fits, strongly favor
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
        if post_residual < dead_threshold {
            score += 20.0; // still penalize creating dead space
        }
    }

    // New-bin candidate: make empty bins moderately attractive only when
    // existing fits are bad (mean residual small => open bins are nearly full).
    if bin_residual == bin_capacity {
        score += 10.0 + 0.2 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: new bin is fine
        }
    }

    // Mild preference for bins tighter than average (best-fit flavor).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match: next item can still fit into post residual (chainable bin).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot follow: dead space penalty grows with wasted space.
        let waste = (next_item_size - post_residual) as f64;
        score += 0.8 * waste;
    }

    // Compare post_residual against mean residual: avoid making bin outliers.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let dev = (pr - mean_residual) / cap;
    if dev > 0.0 {
        score += 30.0 * dev; // much emptier than average -> wasteful
    } else {
        score += 10.0 * dev; // tighter than average -> slightly favored
    }

    // Last chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current item leaves a clean,
    // reusable residual (e.g. post_residual large enough for typical items)
    // or when no open bin fits well.
    if bin_residual == bin_capacity {
        let new_bin_bonus = if post_residual >= 50.0 { 15.0 } else { 0.0 };
        score += 70.0 - new_bin_bonus;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 35.0; // fresh bin can host the next item too
        }
    }

    // Late in stream: consolidate harder, discourage new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (pr / cap);

    // Mild preference for bins that end near-perfectly full.
    let fill_ratio = (bin_residual - post_residual) as f64 / item_size.max(1) as f64;
    score -= 5.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
