    // Fragmentation pressure: when many bins are open, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let openness = open_bins_count as f64 / total_items.max(1) as f64;
    score -= (fitting_bins_count as f64) * 2.0 * (0.5 + progress);
    score += openness * 10.0;

    // Global residual coupling: if this bin is far drier than the mean, using it
    // consolidates space; if wetter than mean, penalize slightly.
    let delta = mean_residual - bin_residual as f64;
    score += 0.15 * delta;

    // New-bin candidate logic: only attractive when no existing bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let best_possible = if fitting_bins_count > 1 { 1.0 } else { 0.0 };
        // Base new-bin penalty grows as stream progresses (avoid bin explosion).
        score += 35.0 + 40.0 * progress - 25.0 * best_possible;
        // If the item is large relative to capacity, a fresh bin is natural.
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Dead-space penalty grows as stream progresses (late dead space is costlier)
    score += 40.0 * progress * norm_pr * norm_pr;

    // Perfect/near-perfect fit reward (smooth trough near zero residual)
    score -= 25.0 * (-pr / 12.0).exp();

    // Lookahead coupling: reward residuals that can host the next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = ((pr - nxt) / cap).powf(2.0);
            score -= 15.0 * (1.0 - slack) * (1.0 - progress);
        } else {
            let gap = (nxt - pr) / cap;
            score += 10.0 * gap * gap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0 * (1.0 - 0.3 * progress);
    }

    // Mild penalty when this bin's residual deviates from mean (keep bins homogeneous)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Slight preference for reusing bins over opening new ones as bins accumulate
    if bin_residual == bin_capacity {
        score += 3.0 + 0.2 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse in certain residue classes
    let pr = post_residual;
    if pr > 0 {
        // tiny dead space (<=5) is excellent: near-perfect fit
        if pr <= 5 {
            score -= 40.0;
        } else if pr <= 10 {
            score -= 15.0;
        } else if pr <= 20 {
            score += 5.0;
        } else {
            score += 10.0;
        }
        // modulo-10 harmonic classes: residuals that are multiples of 10 pair well
        // with future items (typical size granularity), so reward them
        if pr % 10 == 0 {
            score -= 8.0;
        } else if pr % 10 <= 2 {
            score -= 3.0;
        } else if pr % 10 >= 8 {
            score += 4.0;
        }
    } else {
        // exact fill: perfect
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0;
        } else if next_item_size < pr && pr - next_item_size <= 5 {
            score -= 25.0;
        } else if next_item_size > pr {
            // next item won't fit here regardless; mild penalty for wasting slot
            score += 6.0;
        }
        // integer-division class of next item vs remaining space
        let nxt_class = next_item_size / 20; // 0..4 coarse class
        let res_class = pr / 20;
        if nxt_class == res_class && pr >= next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when current fit is bad
    if bin_residual == bin_capacity {
        // base new-bin score: neutral-ish, adjusted by stream progress
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 45.0 + 15.0 * progress;
        if item_size >= 70 {
            // large items: a fresh bin is often fine
            score -= 10.0;
        }
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 5.0;
        }
    }

    // crowding: many open bins -> prefer consolidating into existing bins
    score += 0.3 * open_bins_count as f64;

    // deviation from mean residual: bins far below mean are better consolidation targets
    score -= 0.2 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Zero residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to bin capacity.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio;

    // Open-bin pressure: discourage spreading across many bins,
    // but only mildly, so tight fits still win.
    score += 0.35 * open_bins_count as f64;

    // Last chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Lookahead: if the next item can use the post-residual exactly, reward it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 8.0; // residual too small for next item: dead space risk
        }
    }

    // New-bin candidate: penalize opening a new bin when open bins exist,
    // scaled by stream progression (late stream: consolidate more).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
        // But if current bin would leave bad dead space, opening new is fine.
        if post_residual > 0 && post_residual < 10 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: bonus for small post_residual (perfect fit gets big reward).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 25.0;
    } else {
        // Penalize dead space that is too small for typical future items.
        score += (post_residual as f64 / bin_capacity as f64) * 30.0;
    }

    // 2-step lookahead: if the next item exactly fits the post-residual, strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Gap cannot hold the next item: penalize proportionally to wasted gap.
            let waste = (post_residual as f64) / (next_item_size as f64);
            score += waste * 15.0;
        }
    }

    // Compare against mean residual: bins below mean residual are "tight" and
    // should be consumed first to consolidate space.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: make it expensive so it is chosen only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 60.0;
        // Early in the stream, opening bins is cheaper; late, very expensive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize tiny unusable dead space (fragmentation)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: reward if next item can chain into this bin's post-residual
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            // waste potential: post_residual too small for next item
            score += 0.05 * (post_residual as f64).min(20.0);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current fit is poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // neutral-ish baseline; opening bins early is costly
        score += 20.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size && item_size >= 60 {
            score -= 30.0; // big item now, big item next: fresh bin is good
        }
    }

    // Prefer bins below mean residual (keeps residuals balanced)
    score += 0.08 * (bin_residual as f64 - mean_residual);

    // Early in stream: be slightly conservative about filling bins tightly
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: reward tight fits (low post_residual) via smooth polynomial shaping.
    let mut score = post * post / cap + post;

    // Non-linear coupling: as the stream progresses, tight fits matter more
    // (less future to amortize dead space); early on, keep bins flexible.
    let tightness_bias = norm_post * norm_post * (1.0 - norm_post);
    score += (1.0 - progress) * 40.0 * tightness_bias * cap * 0.1;
    score -= progress * 12.0 * (1.0 - norm_post) * (1.0 - norm_post);

    // Lookahead coupling: if the next item fits the post-residual, reward this bin.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let fit_quality = 1.0 - ((post_residual - next_item_size) as f64 / cap);
        score -= 15.0 * fit_quality * (0.5 + 0.5 * progress);
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize dead space more as stream ends.
        score += 8.0 * norm_post * (0.3 + 0.7 * progress);
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: penalize mildly so it is chosen only when
    // open bins would create large dead space; penalty decays with progress
    // and with how full the average open bin is.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64).ln() / (1.0 + (mean_residual / cap).max(0.0));
        score += 35.0 + 10.0 * (1.0 - progress) + 5.0 * crowding;
    }

    // Mild preference for bins deviating from mean residual (balance load).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "harmonic"
    // with typical small items (divisible by common item classes).
    let pr = post_residual as u32;
    if pr > 0 {
        // Dead-space penalty: residuals in awkward zones get punished.
        let awkward = if pr <= 10 { 3.0 } else if pr <= 20 { 1.5 } else if pr <= 40 { 0.5 } else { 0.0 };
        score += awkward;

        // Reward residuals that are exact multiples of common item classes (10, 20, 25, 50)
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 4.0; }
        if pr % 50 == 0 { score -= 3.0; }

        // Perfect closure: residual equals zero is ideal but handled by base; near-perfect fits
        if pr <= 5 { score -= 8.0; }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size < post_residual {
            // next item fits; penalize leftover of that hypothetical placement
            let after2 = post_residual - next_item_size;
            score += (after2 as f64) * 0.3;
            if after2 % 10 == 0 { score -= 3.0; }
        } else {
            // next item won't fit here; mildly penalize small residuals that trap us
            score += 2.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Prefer tighter bins: tie-break by how full the bin already is (capacity fraction)
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * 5.0;

    // Late in stream, be more aggressive about closing bins tightly
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (post_residual as f64) * 0.2;

    // Avoid spreading across too many open bins when mean residual is large
    if (post_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let base = 40.0 + (post_residual as f64);
        if fitting_bins_count == 0 { return -5.0; }
        return base;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward tight fits (item consumes most of the residual).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Open-bin pressure: with many bins open, prefer reusing existing bins.
    let open_pressure = open_bins_count as f64 / (total_items as f64).max(1.0);
    if bin_residual != bin_capacity {
        score -= 10.0 + 50.0 * open_pressure;
    } else {
        // New-bin candidate: penalize opening a new bin unless it enables a
        // much better future packing (lookahead fits the fresh capacity well).
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 25.0 + 40.0 * open_pressure;
            // If next item is large, a fresh bin is more attractive.
            if next_item_size > item_size {
                score -= 10.0;
            }
        } else {
            score += 50.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Mean residual coupling: bins far below mean residual are less attractive
    // (their space is more valuable for future items); tight bins favored.
    if bin_residual != bin_capacity {
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
    }

    // Lookahead synergy: if next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // If next item cannot fit post-residual and post-residual is small, penalize.
    if next_item_size > post_residual && post_residual < 10 {
        score += 10.0;
    }

    // Mild stream progression: later in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly matches the next item size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward when the next item fits perfectly into the leftover space.
        score -= (bin_capacity as f64) / (1.0 + diff);
        // Extra bonus for an exact match.
        if diff == 0.0 {
            score -= 30.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit in the leftover: penalize dead space,
        // especially when it is small and unusable.
        let dead = post_residual as f64;
        if dead < next_item_size as f64 {
            score += (next_item_size as f64 - dead) * 0.5;
        }
    }

    // Penalize bins that deviate strongly from the mean residual
    // (avoid creating extreme outliers).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 55.0;
        // More open bins -> prefer reusing one; make new bin less attractive.
        score += open_bins_count as f64 * 2.0;
    }

    // Slight preference for tighter bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post-residual (tight fits).
    let mut score = post;

    // Strong reward for near-perfect fits (post_residual close to 0).
    score -= (1.0 - post / cap).powi(6) * 30.0;

    // Lookahead (k=2): reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 8.0 + 6.0 * (1.0 - (post - nxt) / cap);
        } else {
            // Post-residual too small for the next item: mild penalty scaled by dead space.
            score += 3.0 * (post / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // unless the fit is terrible (large post-residual = wasted space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
        score += 10.0 * (post / cap);
    }

    // Prefer bins already below mean residual (consolidate slack).
    score += 0.3 * (mean_residual - post);

    // Early in the stream: encourage opening/using bins flexibly; later: tighten packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin, but less when the item is large
    // (large items into a fresh bin leave a useful big residual for future items)
    // or when the current fit would be very wasteful.
    if bin_residual == bin_capacity {
        let waste_penalty = if post > 0.0 { post / cap } else { 0.0 };
        let large_item_bonus = (item / cap) * 10.0;
        score = cap as f64 * 1.05 + waste_penalty * 5.0 - large_item_bonus;
        // Late in stream, opening new bins is more costly.
        score += 5.0 * progress;
        // If no other bin fits well, allow the new bin.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual (larger leftover = better fit)
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress.
    // Early on, prefer filling bins tightly (penalize large residual);
    // later, residual becomes more valuable as flexibility matters.
    let progress_coupling = norm_pr * (norm_pr - 1.0) * (progress - 0.5) * 40.0;
    score += progress_coupling;

    // Cubic term: strongly reward near-perfect fits (post_residual near 0),
    // smoothly modulated by progress.
    let cubic = (1.0 - norm_pr).powi(3) * (1.0 - progress) * 15.0;
    score -= cubic;

    // Penalize dead space that cannot fit the next item (smooth quadratic).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            let deficit = (nxt - pr) / cap;
            score += deficit * deficit * 60.0;
        } else {
            // Reward leaving exactly enough room for next item (chaining).
            let slack = (pr - nxt) / cap;
            score -= (1.0 - slack).max(0.0) * 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild pressure against spreading across too many open bins.
    score += open_bins_count as f64 * 0.3;

    // Slight preference for bins below mean residual (balance residuals).
    score += (mean_residual - pr) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, penalize dead space quadratically.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / cap;

    // Harmonic class of post_residual: residuals that are "usable" sizes
    // (multiples of common item classes) are worth keeping, others penalized.
    let usable = |r: u32| -> bool {
        r == 0 || r % 10 == 0 || r % 15 == 0 || r % 20 == 0 || r % 25 == 0
    };
    if !usable(post_residual) {
        score += 12.0; // dead-space residue class penalty
    } else if post_residual == 0 {
        score -= 25.0; // perfect closure
    }

    // Integer-division thresholds on post_residual: small leftovers are traps.
    let q = post_residual / 10;
    match q {
        0 => score += 18.0,                 // 0..9: unusable sliver (unless 0 handled above)
        1 => score += 10.0,                 // 10..19: only tiny items fit
        2 => score += 4.0,                  // 20..29
        3 | 4 => score -= 3.0,              // 30..49: comfortable zone
        _ => score -= 1.0,                  // >=50: spacious
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual class.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // next item closes this bin perfectly
        } else if next_item_size < post_residual {
            // Harmonic alignment: next item leaves a clean residue class again.
            let nr = post_residual - next_item_size;
            if usable(nr) {
                score -= 8.0;
            } else {
                score += 3.0;
            }
            if nr < 10 {
                score += 6.0; // next placement would create a sliver
            }
        } else {
            score += 5.0; // next item cannot use this bin anyway
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 3 {
        score += 1.5 * (fitting_bins_count as f64 - 3.0);
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 0.6
            + (mean_residual / cap) * 10.0
            + (step_index as f64 / (total_items.max(1) as f64)) * 5.0;
        // Empty bin starts with post_residual == capacity; keep it moderately
        // attractive so it wins only when open bins are fragmented.
        score += 8.0 - pressure.min(20.0);
    }

    // Mean-residual coupling: if this bin is far below mean residual, it is
    // already fragmented; deprioritize slightly.
    let dev = mean_residual - pr;
    if dev > 0.0 {
        score += 0.05 * dev;
    } else {
        score -= 0.02 * (-dev);
    }

    // Progress-aware tightening: later in the stream, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.25 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (1..=5) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 5 {
        score += 60.0 * (5.0 - post_residual as f64);
    }
    // Perfect fit: zero residual is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to item size (relative waste measure).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Penalize leaving a gap that cannot fit the lookahead item but is
    // large enough to be "wasted potential".
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward a residual that exactly accommodates the next item (chained fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items;
    // with few open bins, opening a new one is cheaper.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already fragmented -> slight penalty; using it consolidates waste.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score += 0.3 * (mean_residual - residual_f);
    } else {
        score -= 0.3 * (residual_f - mean_residual);
    }

    // New-bin candidate: an empty bin is a fallback; make it mildly attractive
    // only when the current fit is bad, otherwise keep items in open bins.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.8 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 150.0 / (1.0 + diff);
        // Exact match for the next item is excellent.
        if post_residual == next_item_size {
            score -= 400.0;
        }
        // Penalize leaving residual too small for the next item (dead space).
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual against mean residual: prefer bins pushed toward the mean
    // (balanced packing), mildly.
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large relative
    // to capacity or few bins fit the item.
    if bin_residual == bin_capacity {
        score += 120.0;
        let ratio = item_size as f64 / bin_capacity as f64;
        score -= 150.0 * ratio;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 40.0; // large item stream: fresh bin useful
        }
    }

    // Late in the stream, consolidate: prefer existing bins over new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 30.0 * progress;
    }

    // Mild penalty for very small leftovers that nothing (min size 1..100) can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the waste relative to capacity, the better.
    let tightness = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for the smallest possible item (1..100 range),
    // scaled by how "stuck" the residual is.
    if post_residual > 0 && post_residual < item_size.min(bin_capacity / 2) {
        score += 0.6 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // reward heavily (perfect chain); if next item cannot fit, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 0.35 * (post_residual - next_item_size) as f64;
        } else {
            score += 0.25 * (next_item_size - post_residual) as f64;
        }
    }

    // Global state coupling: when many bins are open and mean residual is high,
    // discourage opening new bins / spreading items thin.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to existing slack in the system.
        score += (open_bins_count as f64) * (mean_residual / bin_capacity as f64).max(0.0) * 12.0;
        // Early in the stream, opening bins is cheap; late, it is expensive.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // If no bin fits (fitting_bins_count == 0 among open bins), opening is fine.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        // Filling an existing bin reduces open-bin pressure; reward slightly more
        // when many bins are open.
        score -= 0.15 * open_bins_count as f64;
        // Prefer bins with residual below mean residual (consolidate slack).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 1.5;
        }
    }

    // Nonlinear residual penalty: waste beyond half-capacity is very bad.
    if post_residual > bin_capacity / 2 {
        score += 0.4 * (post_residual - bin_capacity / 2) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (small post_residual), with smooth non-linear shaping
    let mut score = pr as f64;

    // Non-linear coupling of post residual with stream progress:
    // early on, larger residuals are tolerable; late in the stream, dead space is penalized harder.
    let dead_space_penalty = x * x * (1.0 + 2.0 * progress) + x * x * x * (1.0 + 3.0 * progress);
    score += 20.0 * dead_space_penalty;

    // Smooth reward when post residual matches the next item's needs (lookahead coupling)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let diff = (pr - n) / cap;
        // quadratic coupling: penalize mismatch smoothly, reward near-exact fits
        score += 15.0 * diff * diff * cap - 10.0 * (-diff * diff * 40.0).exp() * cap * 0.1;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - x);
    } else {
        // mild crowding penalty proportional to number of alternatives, smoothed
        score += 2.0 * ((fitting_bins_count as f64).ln() + 1.0) * x;
    }

    // Coupling with mean residual: avoid leaving this bin far from the fleet average
    let mean_dev = (pr - mean_residual) / cap;
    score += 8.0 * mean_dev * mean_dev * cap;

    // Smooth preference for filling bins tighter as more bins are open
    score += (open_bins_count as f64).ln().max(0.0) * x * 5.0;

    // New-bin candidate: neutral-ish baseline with smooth decay of appeal over time
    if bin_residual == bin_capacity {
        score = cap * (1.0 + 0.5 * progress) - 10.0 * (1.0 - x);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.18;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (1..=12) are heavily penalized.
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 25.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Residual too small for next item: mild penalty scaled by gap size.
        score += 0.5 * (next_item_size as f64 - post_residual as f64).min(20.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless it creates dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual <= 12 {
            score += 20.0; // still penalize dead space here
        } else {
            score -= 30.0;
        }
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // encourage consolidation when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when pressure is high.
        score += 40.0 + pressure * 3.0;
    } else {
        score -= pressure.min(25.0) * 0.5;
    }

    // Prefer bins whose residual is close to the item (tight fit relative to mean).
    if bin_residual as f64 > mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact/near-exact fits (small dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: reward when the next item fits the
    // post-residual (chain packing), penalize when it almost fits but not quite.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains perfectly or well into this bin.
            let slack_after_next = post_residual - next_item_size;
            score -= 30.0 + slack_after_next as f64 * 0.5;
        } else {
            // Next item will not fit here: leftover may become dead space.
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 10.0 {
                score += 15.0 + miss; // near miss: wasteful split
            } else {
                score += 5.0;
            }
        }
    }

    // Relative to mean residual: prefer bins with less residual than average
    // (fill the emptiest-feeling bins first when fit is comparable).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity or current bins are nearly full on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mean_frac = mean_residual / bin_capacity as f64;
        // Open new bin if item is big or open bins are quite full.
        let open_bonus = if item_frac > 0.5 || mean_frac < 0.2 { -20.0 } else { 60.0 + 40.0 * (1.0 - progress) };
        score += open_bonus;
    }

    // Late in the stream, be extra frugal: tighten preference for tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit is nearly free.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize dead space that no future item can plausibly fill.
    // Smallest item is ~1 in this interface; treat gaps < 10 as likely dead.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last chance: strongly prefer using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // Next item won't fit here; slight penalty for stranding space.
            score += 3.0;
        }
    }

    // Time horizon: early in the stream, be more willing to spread items
    // across bins (keep residuals flexible); late, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0 * tightness;
    score += (1.0 - progress) * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> prefer filling
    // existing bins rather than opening new ones.
    if open_bins_count > 0 {
        let openness = mean_residual / bin_capacity as f64;
        score -= openness * 5.0;
        if open_bins_count > 8 {
            score -= 2.0;
        }
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 18.0;
        // But if current bin would leave a big awkward gap and many bins exist,
        // opening fresh can win.
        if post_residual > 0 && post_residual < 15 {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post-residual, with smooth non-linear (quadratic) shaping.
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Polynomial coupling of post_residual with stream progress:
    // later in the stream, compact fills matter more.
    let coupling = 1.0 + 1.5 * progress * (1.0 - progress * 0.5);
    score *= coupling;

    // Reward tight fits (small post_residual) with a cubic bonus.
    score -= 12.0 * (1.0 - norm_post) * (1.0 - norm_post) * (1.0 - norm_post) * norm_item;

    // Penalize dead space relative to mean residual across open bins.
    score += 0.4 * (post - mean_residual) * norm_post;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_post);
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 4.0 * (next_item_size as f64 / cap);
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.15 * open_bins_count as f64 * norm_post;

    // New-bin candidate: prefer opening a new bin only when existing fits are poor.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new_bin {
        score += 10.0 + 20.0 * (1.0 - norm_item) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // ---- Dead-space penalty: residual that no realistic item (>=1) can use well ----
    // Very small residuals are wasted space; penalize quadratically below threshold 12.
    if post_residual < 12 {
        score += (12.0 - pr) * (12.0 - pr) * 1.5;
    }

    // ---- Harmonic class of post_residual (mod-10 alignment) ----
    // Residuals that are multiples of 10 are "harmonic" with the classic item
    // size grid (10..80), so leftover space is more likely reusable later.
    let harmonic = post_residual % 10 == 0 && post_residual > 0;
    if harmonic {
        score -= 6.0;
    } else {
        // Off-grid residuals: penalize by distance to nearest multiple of 10.
        let d = (pr % 10.0).min(10.0 - pr % 10.0);
        score += d * 0.8;
    }

    // Integer-division threshold classes on post_residual:
    // class 0: 0-9 (dead), class 1: 10-24 (small-item zone),
    // class 2: 25-49 (mid zone), class 3: 50+ (flexible zone).
    let class = post_residual / 25;
    match class {
        0 => score += 10.0,
        1 => score += 3.0,
        2 => score -= 2.0,
        _ => score -= 4.0,
    }

    // ---- Lookahead coupling (k=2) ----
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // Next item cannot use this leftover: dead space confirmed.
            score += (next_item_size - post_residual) as f64 * 0.35;
        } else if next_item_size == post_residual {
            // Perfect two-item closure: strong reward.
            score -= 15.0;
        } else {
            // Next item fits partially; reward proportional to how much it consumes.
            let consumed = next_item_size as f64 / pr.max(1.0);
            score -= consumed * 8.0;
        }
    }

    // ---- Last-chance bin: if this is the only fitting bin, strongly prefer it ----
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // ---- New-bin candidate handling ----
    if is_new_bin {
        // Opening a new bin is good only for large items (they need a fresh bin
        // anyway) or when all open bins are nearly full.
        let item_frac = item_size as f64 / cap;
        let tightness = 1.0 - mean_residual / cap; // high = bins nearly full
        if item_frac > 0.5 || (fitting_bins_count == 0) {
            score -= 25.0;
        } else if item_frac > 0.35 {
            score -= tightness * 12.0;
        } else {
            // Small item into a fresh bin wastes capacity: penalize.
            score += (0.5 - item_frac) * 40.0 + (1.0 - tightness) * 10.0;
        }
        // Mild preference to reuse existing bins when many are open.
        score += open_bins_count as f64 * 0.5;
    }

    // ---- Mean-residual context: prefer bins whose leftover tracks the mean ----
    score += (pr - mean_residual).abs() * 0.15;

    // ---- Stream progression: late in the stream, consolidate aggressively ----
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + progress * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead-space penalty: small nonzero gaps are nearly unusable (items >= 1
    // but typical sizes are large). Penalize gaps below a "useful" threshold
    // quadratically, scaled by how full the bin already is.
    let useful_gap = 20.0;
    if post > 0.0 && post < useful_gap {
        let deadness = (useful_gap - post) / useful_gap; // 0..1
        score += deadness * deadness * 30.0;
    }

    // Reward using bins that are already fairly full (tight packing),
    // based on fill ratio.
    let fill_ratio = (bin_residual as f64) / cap;
    score -= (1.0 - fill_ratio) * 8.0;

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (chain fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: discourage opening new bins when many bins are open
    // and mean residual is large (spread load).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = open_bins_count as f64 * (mean_residual / cap);
        score += 5.0 + pressure * 10.0;
        // But if no existing bin fits well (large dead space elsewhere), allow new bin.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Late-stream tightening: as the stream progresses, prefer zero-waste more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chain fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            // Next item fits, leaving more dead space: mild reward proportional to leftover.
            score -= 100.0 - (post_residual - next_item_size) as f64;
        }
        // If next item cannot fit post-residual, penalize proportional to how
        // "wasted" the residual is relative to the next item size.
        else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Penalize residuals that are too small to hold the smallest possible item (1),
    // i.e. dead space, scaled by item size placed.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is chosen only when open-bin scores are bad.
        score += 120.0;
        // Fewer open bins -> opening is cheaper.
        score -= open_bins_count as f64 * 2.0;
        // Late in the stream, prefer reusing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 60.0;
        // If next item is large, a fresh bin is more valuable.
        score -= next_item_size as f64 * 0.3;
    }

    // Compare against mean residual: bins with residual far from item_size
    // (poor fit) get penalized; tight fits get rewarded.
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += fit_gap * 0.3;
    score -= (mean_residual - bin_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small to hold the smallest plausible item.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 50.0;
    }
    // Penalize residuals that can't fit the lookahead item (wasted pair potential).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.35 * (next_item_size as f64 - post_residual as f64);
    }
    // Reward residual that exactly accommodates the next item (perfect chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 8.0;
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0;
    }

    // Prefer filling bins with larger residual when many bins are open (consolidation).
    score += 0.05 * (open_bins_count as f64) * ((bin_residual as f64) / (bin_capacity as f64));

    // Time-varying horizon: early on, favor keeping residuals flexible; late, favor tight packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress * ((bin_residual as f64) / (bin_capacity as f64));

    // Discourage deviation from the mean residual to keep the bin population balanced.
    score += 0.08 * ((bin_residual as f64) - mean_residual).abs();

    // New-bin candidate: mild penalty so we only open a new bin when fits are truly poor.
    if bin_residual == bin_capacity {
        score += 4.0 + 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_frac = post / cap;

    // Base: prefer small post residual, with non-linear (quadratic) shaping.
    let mut score = post * (1.0 + 0.6 * post_frac * post_frac);

    // Smooth coupling: as the stream progresses, penalize large leftover space more
    // (less future opportunity to reuse it), scaled by dead-space fraction.
    score += 18.0 * post_frac * post_frac * progress * (1.0 + progress);

    // Reward tight fits more strongly later in the stream.
    let tightness = 1.0 - post_frac;
    score -= 12.0 * tightness * tightness * tightness * (0.5 + progress);

    // Last-chance bin bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + progress);
    }

    // Lookahead: if next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let match_frac = nxt / post.max(1.0);
            score -= 15.0 * match_frac * match_frac;
        } else {
            // Post residual too small for next item: penalize dead space mildly.
            score += 6.0 * post_frac * (1.0 - post_frac);
        }
    }

    // Prefer bins with residual near the mean (keeps bin portfolio balanced),
    // with a smooth quadratic deviation penalty.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Mildly discourage spreading across many open bins early.
    score += (open_bins_count as f64) * 0.05 * (1.0 - progress);

    // New-bin candidate: make it attractive only when no open bin fits well.
    let is_new_bin = (bin_residual as u64 == bin_capacity as u64) && bin_capacity > 0;
    if is_new_bin {
        score += 10.0 + 20.0 * (1.0 - post_frac) * progress;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // residue classes mod 10 (typical item granularity) and mod capacity fractions.
    let r10 = post_residual % 10;
    let r25 = post_residual % 25;
    let r50 = post_residual % 50;

    // Penalize leftovers that fall into "dead space" classes:
    // small nonzero remainders (1..9) are hard to fill later.
    if post_residual > 0 && r10 != 0 {
        score += (10 - r10) as f64 * 0.6;
    }
    // Leftovers in (0,25) exclusive that are not multiples of 10 are worst.
    if post_residual > 0 && post_residual < 25 && post_residual % 10 != 0 {
        score += 8.0;
    }
    // Multiples of 25 or 50 are harmonic-friendly leftovers: reward them.
    if r25 == 0 && post_residual > 0 {
        score -= 5.0;
    }
    if r50 == 0 && post_residual > 0 {
        score -= 5.0;
    }
    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Integer-division threshold on post_residual: leftovers <= 10 are nearly dead.
    let dead_class = post_residual / 10; // 0 => dead zone
    if post_residual > 0 && dead_class == 0 {
        score += 12.0;
    }

    // Lookahead: if next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_left = post_residual - next_item_size;
        if next_left == 0 {
            score -= 20.0;
        } else {
            score -= (next_item_size as f64) * 0.3;
            if next_left % 10 == 0 {
                score -= 4.0;
            }
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // This bin becomes unusable for the next item: penalize mildly.
        score += 6.0;
    }

    // Last chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the item is large
    // relative to residual and open bins are mostly full (low mean residual).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = mean_residual / bin_capacity as f64;
        // Prefer new bin if existing bins are tight and item is big.
        let new_bin_bonus = 20.0
            + (item_size as f64) * 0.25
            + progress * 10.0
            - tight * 30.0;
        score += new_bin_bonus;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative anyway
        }
    }

    // Mild pressure to consolidate: fewer open bins is better.
    score += (open_bins_count as f64) * 0.15;

    // Slight preference for filling fuller bins (lower residual before placement).
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item + 9 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly-ish, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 25.0;
        } else if slack <= 10 {
            score -= 10.0;
        } else {
            score += slack as f64 * 0.2;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot use this gap: dead space pressure
        score += post_residual as f64 * 0.3;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 2.0;
        // early stream: be a bit more willing to open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
    } else {
        score -= 5.0;
    }

    // Mild preference for bins below mean residual (balance load).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small post residual is already the base, sharpen it).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual <= 15 {
        score -= 5.0;
    }

    // Aggressive 2-step lookahead: if next item fits the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 25.0;
            } else if slack <= 30 {
                score -= 10.0;
            } else {
                score -= 2.0;
            }
        } else {
            // Next item cannot use the leftover; penalize dead space proportionally.
            score += (next_item_size.min(post_residual) as f64) * 0.05;
        }
    }

    // Relative-to-mean coupling: bins tighter than mean are precious, use them well.
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let ratio = res_f / mean_residual;
        if ratio < 0.7 {
            score -= 8.0; // tight bin: prefer consuming it
        } else if ratio > 1.4 {
            score += 4.0; // loose bin: keep it flexible
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Early in stream: keep bins roomy for future flexibility.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (post_residual as f64) * 0.1;

    // Many open bins: encourage closing out small-residual bins.
    if open_bins_count > 8 {
        score += (post_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (wasted-space shaping)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to hold typical items
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 25.0; // near-unusable sliver
        } else if dead < 20.0 {
            score += 8.0 * (20.0 - dead) / 10.0;
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item won't fit here; slight penalty for wasting residual
            score += 3.0;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure)
    let fill_frac = (bin_residual as f64) / (bin_capacity as f64);
    score += 5.0 * fill_frac * (open_bins_count as f64).sqrt();

    // Drift toward mean residual: prefer bins with residual near/below mean
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Time horizon: late in the stream, be more conservative (favor tight fits more)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * tightness;

    // New-bin candidate: only attractive when current bin fit is poor
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 15.0;
        // but if the item would leave a bad residual in any existing bin, open a new bin
        if post_residual < 10 && post_residual > 0 {
            score -= 40.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // late stream: prefer packing into existing bins
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills (low post_residual); later, tolerate
    // larger residuals since open bins are cheap to top up.
    let progress_weight = 0.35 * (1.0 - progress) * progress * 4.0;
    score += progress_weight * post * norm_post;

    // Smooth penalty on very small dead space (wasted capacity) using a
    // quartic bump centered near zero residual.
    let tiny = norm_post;
    score += 8.0 * (1.0 - tiny) * (1.0 - tiny) * (1.0 - tiny) * (1.0 - tiny);

    // Reward filling a bin almost perfectly, scaled by how many alternatives exist.
    if fitting_bins_count > 1 {
        score -= 3.0 * (1.0 - norm_post) * (1.0 - norm_post);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    }

    // Lookahead: penalize leaving a residual that barely fails to fit the next item,
    // reward residuals that accommodate it smoothly.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post as f64 >= n {
            score -= 2.5 * (n / cap) * (1.0 - (post as f64 - n) / cap);
        } else {
            score += 1.5 * (n - post as f64) / cap * (1.0 + progress);
        }
    }

    // Mild penalty for spreading across many open bins; smooth in open_bins_count.
    let ob = open_bins_count as f64;
    score += 0.15 * (ob * ob) / (ob + 4.0);

    // Coupling with mean residual: prefer bins below mean residual (tighter bins).
    score += 0.05 * (mean_residual - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions
    let post_mod = post_residual % 25;
    // Penalize residuals that fall into "dead" classes: small but nonzero leftovers
    if post_residual > 0 {
        if post_mod < 10 {
            score += (10 - post_mod) as f64 * 1.5; // awkward slivers (1..9)
        } else if post_mod <= 20 {
            score -= 2.0; // useful mid-class residuals
        }
    } else {
        score -= 15.0; // perfect closure
    }

    // Integer-division threshold: large post_residual chunks are reusable
    let chunk = post_residual / 25;
    score -= chunk as f64 * 4.0;

    // Lookahead coupling: harmonic class of next item vs post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_class = next_item_size % 25;
            // reward if next item's class aligns with post residual class
            if next_item_size == post_residual {
                score -= 20.0;
            } else if (post_residual as i64 - next_item_size as i64).abs() as u32 % 25 == 0 {
                score -= 8.0;
            } else {
                score -= 3.0 + (next_class as f64) * 0.1;
            }
        } else {
            // next item cannot use leftover: penalize proportional to wasted potential
            score += ((next_item_size - post_residual) as f64) * 0.3;
        }
    }

    // Last chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: opening fresh bins is only good when existing
    // bins are nearly full or the item is huge relative to residuals
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let residual_gap = (mean_residual - item_size as f64).max(0.0);
        // penalize new bins more when many bins are open and mean residual is large
        score += 18.0 + open_bins_count as f64 * 1.2 + residual_gap * 0.5 - progress * 6.0;
        // but a big item alone in a fresh bin is fine
        if item_size >= 70 {
            score -= 10.0;
        }
    }

    // Prefer tighter fits overall: closeness of item to residual
    score += (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size are pure waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // impossible overflow guard
    }

    // Penalize small unusable gaps superlinearly: residuals in [1,15] are dead space
    // for most distributions, but exact fits (0) are perfect.
    let pr = post_residual as f64;
    if pr > 0.0 && pr <= 15.0 {
        score += (16.0 - pr) * 3.0; // smaller dead gap => worse (wasted capacity)
    }

    // Reward tight fits strongly.
    if pr == 0.0 {
        score -= 200.0;
    } else if pr <= 5.0 {
        score -= 50.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation (higher score for
    // opening new bins happens implicitly via new-bin candidate scoring below).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.5 * (0.5 + progress);

    // New-bin candidate: empty bin has huge residual; make it attractive only when
    // the fit into open bins would leave bad dead space or nothing fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin.
        score = bin_capacity as f64 * 0.9 + open_bins_count as f64 * 2.0;
        // If current bin would leave a good residual, discourage new bin.
        if post_residual <= bin_capacity && post_residual >= 20.0 {
            score += 100.0;
        }
        // Lookahead: if next item could pair with this item in a fresh bin, favor it.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 40.0;
        }
        // Late in stream, opening new bins is less costly than dead space.
        score -= progress * 20.0;
    }

    // Lookahead synergy: placing item so next item still fits well.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += (next_item_size as f64 - pr).min(20.0) * 0.5;
    }

    // Mean-residual coupling: when mean residual is high, prefer using fuller bins.
    score += (mean_residual - pr) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly matches the next item (perfect chain fit).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for next item -> strong reward.
        if diff == 0.0 {
            score -= 25.0;
        } else if (post_residual as i64) >= (next_item_size as i64) {
            // Next item still fits here afterwards: mild reward scaled by closeness.
            score -= 6.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize small dead space more strongly.
            let dead = post_residual as f64;
            if dead > 0.0 {
                score += 8.0 * (1.0 - dead / bin_capacity as f64);
            }
        }
    }

    // Penalize leaving very small unusable slivers (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    score -= 4.0 * (item_size as f64 / bin_capacity as f64) * (1.0 - post_residual as f64 / bin_residual.max(1) as f64);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when residuals
    // across open bins are already large (poor fits everywhere) and the item
    // is large enough to justify it.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap > 0.0 {
            // Open bins have poor room on average; opening a new bin is attractive.
            score -= 10.0 + 5.0 * (mean_gap / bin_capacity as f64) + 3.0 * progress;
        } else {
            // Open bins fit reasonably well; discourage opening a new bin.
            score += 20.0;
        }
    }

    // Mild pressure toward consolidating into bins below mean residual
    // (pack into emptier-feeling bins when many bins are open).
    if open_bins_count > 2 {
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        } else {
            score += 1.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize opening a new bin when the item fits an existing one,
    // unless the fit is very tight elsewhere or the new bin is genuinely useful.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 1000.0;
        // Reward opening a new bin only if no existing bin fits (last resort)
        if fitting_bins_count == 0 {
            score -= 1000.0;
        } else if fitting_bins_count == 1 {
            // If the single fitting bin leaves a very awkward residual, allow new bin
            let alt_post = bin_residual as f64 - item_size as f64; // placeholder, not used
            let _ = alt_post;
            score -= 400.0;
        }
        // Late in the stream, prefer consolidating into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 200.0;
    }

    // Reward tight fits: low post_residual is good (already baseline), but
    // give a bonus when post_residual is small enough to be "dead space free"
    let pr = post_residual as f64;
    if pr <= 10.0 {
        score -= 30.0; // near-perfect fill
    } else if pr < 20.0 {
        score -= 15.0;
    }

    // Penalize leaving residuals that no plausible item can use later.
    // Items are >= 1, but typical items are sizable; residuals < 10 are dead.
    if pr > 0.0 && pr < 10.0 {
        score += 40.0; // dead space penalty
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this placement is excellent; if next item would fit but leaves more waste,
    // slightly penalize.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            // next item fits in leftover: reward proportional to tightness
            score -= 20.0 * (1.0 - (pr - ni) / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty scaled by overflow amount
            score += 5.0 * ((ni - pr) / bin_capacity as f64).min(1.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 150.0;
    }

    // Global state: many open bins with high mean residual -> consolidate.
    if open_bins_count > 4 {
        // prefer bins whose residual is below mean (tighter bins) to preserve
        // large residual bins for larger future items
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        } else {
            score += 5.0;
        }
    }

    // Prefer filling bins that are already partially used over nearly-full ones
    // when waste would be equivalent: slight bonus for larger current residual
    // usage (bin_residual small means bin is well used).
    score += (bin_residual as f64) * 0.05;

    // Time-horizon coupling: early in the stream, keep bins flexible (avoid
    // tiny residuals); late in the stream, squeeze as much as possible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 {
        score += pr * 0.10; // penalize waste more early (keeps flexibility)
    } else if progress > 0.7 {
        score -= pr * 0.05; // reward tight packing late
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, tolerate leftover space (many items left to fill it);
    // late in the stream, penalize waste more strongly (quadratic ramp).
    let waste_weight = 0.5 + 1.5 * progress * progress;
    score += waste_weight * (pr * pr) / cap;

    // Reward tight fits: small post_residual relative to capacity gets a smooth discount.
    let tightness = 1.0 - pr / cap;
    score -= (tightness * tightness) * cap * 0.6;

    // Lookahead coupling: if next item can use the post_residual, reward this bin;
    // smooth interaction term between leftover and next item size.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            let usability = 1.0 - (pr - ni) / cap;
            score -= 12.0 * usability;
        } else {
            // next item cannot fit: leftover likely dead space, penalize smoothly
            let deadness = (ni - pr) / cap;
            score += 10.0 * deadness * (1.0 + progress);
        }
    }

    // Last chance: if this is the only fitting bin, avoid opening a new bin
    // (penalize alternatives via subtracting a bonus here).
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty when bin's residual is far from the mean residual across bins,
    // favoring balanced residual distributions (smooth coupling).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: make empty bins moderately attractive only when
    // current item is large and post_residual of placement would be tiny,
    // or late in the stream; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        let new_bin_bonus = 15.0 * item_frac * item_frac + 10.0 * progress;
        score = cap - new_bin_bonus + pr * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual super-linearly.
    if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 15 {
        score -= 25.0 + (15 - post_residual) as f64 * 1.5;
    }

    // Harmonic classes: classify post_residual by capacity fraction bands.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.10 {
        score -= 15.0; // near-perfect packing class
    } else if frac < 0.25 {
        score += 5.0;  // mildly wasteful class
    } else if frac < 0.50 {
        score += 12.0; // half-empty class
    } else {
        score += 20.0; // more than half wasted
    }

    // Integer-division thresholds: dead space that no plausible item (min size 10)
    // can ever fill is pure loss.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Harmonic coupling with next item: reward if next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Penalize leftovers that the known next item cannot use.
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    } else {
        // Last item: finishing a bin is free; unused space no longer matters.
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: baseline preference; only chosen when open bins score badly.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 0.5;
        // Prefer opening a fresh bin for very large items that would leave bad residue.
        if item_size >= 70 {
            score -= 20.0;
        }
    }

    // Stream progression: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Mild pull toward bins with below-average residual (keep others flexible).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any future item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual < 20 {
        score += 25.0; // very risky gap
    } else if post_residual < 30 {
        score += 8.0; // moderate risk
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: penalize spreading across many bins
    score += open_bins_count as f64 * 1.5;

    // Prefer bins tighter than the average residual (good consolidation)
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Lookahead: if next item fits exactly in the post residual, reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use leftover -> dead space unless post_residual tiny
        if post_residual >= 10 {
            score += 10.0;
        }
    }

    // New-bin candidate handling: only attractive when item barely fits
    // nowhere else or would create severe dead space.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin
        score += 35.0;
        // If this bin is the only option, opening a new bin is fine
        if fitting_bins_count == 1 {
            score -= 45.0;
        }
        // Late in stream, discourage opening extra bins
        let progress = step_index as f64 / total_items as f64;
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: reward minimal dead space aggressively.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 300.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // this is a chained perfect sequence -> strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Next item fits too; penalize leftover after hypothetical second placement
            let second_left = post_residual - next_item_size;
            score -= 120.0 - (second_left as f64).min(120.0);
        } else {
            // Next item cannot use the residual: penalize proportionally to waste
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Compare post_residual to mean residual: leaving space below average
    // creates fragmented small residuals -> penalty.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += 0.4 * (mean_residual - pr);
    } else {
        score -= 0.2 * (pr - mean_residual).min(50.0);
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: prefer it only when item is large and no open bin fits well.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin anyway
        } else if tightness > 0.7 && post_residual < 30 {
            score -= 60.0;
        } else {
            score += 150.0; // discourage wasting fresh bins on small items
        }
    }

    // Slight preference for filling bins more fully as stream progresses.
    score -= 0.1 * (item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let residual = bin_residual as f64;
    let fill_ratio = item_size as f64 / residual.max(1.0);
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize leaving awkward dead space (small but nonzero post_residual).
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 15.0; // tiny unusable slivers are wasteful
    }
    if pr == 0.0 {
        score -= 25.0; // perfect closure
    }

    // Lookahead: reward if the next item fits exactly-ish into the post residual.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let next_fit = 1.0 - ((pr - next_item_size as f64).abs()) / bin_capacity as f64;
        score -= 30.0 * next_fit;
    }
    // Penalize if next item is stranded by a large leftover it cannot use.
    if next_item_size > 0 && (next_item_size as u32) > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item is large
    // relative to capacity or all open bins would leave big dead space.
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / bin_capacity as f64;
        let pressure = (open_bins_count as f64).ln().max(1.0);
        let mean_waste = (mean_residual - item_size as f64).max(0.0);
        score += 35.0 - 30.0 * size_frac - 5.0 * pressure - 0.1 * mean_waste;
        // Late in the stream, be more conservative about new bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
    }

    // Mild preference for using bins below average residual (consolidate fullness).
    if bin_residual != bin_capacity {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = pr_norm * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);
    let mut score = pr * (1.0 + 2.0 * progress * (1.0 - progress) * 4.0);

    // Reward tight fits more strongly as the stream progresses.
    score -= (cap - pr) * 0.15 * (0.5 + progress);

    // Penalize dead space quadratically when residuals are small.
    if pr_norm < 0.25 {
        score += (0.25 - pr_norm) * (0.25 - pr_norm) * 40.0;
    }

    // Interact polynomial residual shape with mean residual state.
    score += poly * (mean_residual - pr) * 0.5;

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: favor bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= next_item_size as f64 * 0.3;
    } else if next_item_size > 0 {
        score += (next_item_size as f64 - pr) * 0.2;
    }

    // New-bin candidate: make it moderately attractive early, less later.
    if bin_residual == bin_capacity {
        score = cap * (0.9 - 0.5 * progress) - item_size as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse capacity-fraction buckets
    let item_class = item_size / 10;
    let next_class = next_item_size / 10;

    // Perfect-fit reward: harmonic classes that tile the capacity exactly
    let perfect_pair = (item_size + next_item_size) == bin_capacity;
    if perfect_pair {
        score -= 25.0;
    }

    // Reward when next item exactly fills the post residual (exact tiling)
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }

    // Penalize dead space that no future item class can plausibly fill:
    // dead space smaller than the smallest class (10) is wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // Modulo-arithmetic dead-space penalty: post_residual whose residue class
    // matches few item sizes is harder to fill. Penalize small odd residues.
    let residue = post_residual % 10;
    if residue > 0 && residue < 5 {
        score += (5 - residue) as f64 * 4.0;
    }

    // Reward leaving residuals in friendly classes (multiples of 5/10)
    if post_residual % 10 == 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is large
    // or the stream is early and we can amortize the bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let amortization = 100.0 * (1.0 - progress);
        score += 15.0 - item_size as f64 * 0.3 + amortization * 0.2;
        // Big items start fresh bins cheaply
        if item_class >= 7 {
            score -= 10.0;
        }
    }

    // Prefer tight fits: closeness of item to residual
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 12.0;

    // Lookahead coupling: if next item fits into post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 + (post_residual - next_item_size).min(20) as f64 * 0.5;
    }

    // Mean residual balancing: prefer bins near the mean residual to keep
    // the bin portfolio homogeneous (easier future packing)
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    // Slight pressure to consolidate when many bins are open
    if open_bins_count > 8 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable
    // for future items (sizes >= 1), so penalize them heavily.
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 14.0;
    } else if post_residual > 12 && post_residual <= 25 {
        score += (25.0 - post_residual as f64) * 4.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and encourage consolidating into existing bins.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 25.0 + pressure;
        // But if no existing bin fits well (large dead space would result
        // elsewhere), a fresh bin is fine: soften penalty.
        if post_residual == bin_capacity {
            score -= 10.0;
        }
    } else {
        // Existing bin: small consolidation bonus scaling with open bins.
        score -= pressure * 0.5;
    }

    // Lookahead coupling: if the next item can use this bin's post-residual,
    // reward leaving exactly that much space.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 15.0;
        } else if post_residual > 0 && post_residual < next_item_size && post_residual <= 12 {
            score += 20.0; // dead space relative to the known next item
        }
    }

    // Late in the stream, prefer tighter packing to avoid trailing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild preference for bins already below mean residual (balancing).
    if (bin_residual as f64) < mean_residual && bin_residual < bin_capacity {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post-residual).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tight * tight;

    // Penalize dead space that no future item can plausibly fill.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // unusable sliver under minimum item size
    }

    // Lookahead coupling: reward bins whose post-residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0; // perfect follow-up fit
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 5.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 2.0 * (miss / bin_capacity as f64);
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Slight preference for fuller bins relative to the fleet average.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Progress-aware pressure: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * tight;

    // Discard fragmentation when many bins are open: prefer filling existing ones.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make an empty bin attractive only when it enables a
    // perfect pairing with the lookahead item and existing bins fit poorly.
    if bin_residual == bin_capacity {
        let base = 30.0 + 0.3 * open_bins_count as f64;
        let discount = if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            0.0
        } else {
            10.0
        };
        score += base + discount;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear decay of post-residual usefulness: small residuals are wasted space
    let x = pr / cap;
    score += 30.0 * x * x * (1.0 - progress);

    // Reward tight fits (small post_residual relative to capacity)
    score -= (1.0 - x) * (1.0 - x) * 15.0;

    // Last-chance bonus: strongly prefer filling the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 30.0 * progress;
    }

    // Lookahead coupling: reward residuals that can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let fit_quality = (pr - nxt) / cap;
            score -= 20.0 * (1.0 - fit_quality * fit_quality);
        } else {
            score += 8.0 * (1.0 - pr / nxt);
        }
    }

    // Prefer bins with residual below mean residual (better consolidation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev.abs().sqrt();

    // New-bin candidate: penalize mildly, more when open bins are few or stream is early
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) + 5.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: reward residuals that are "friendly" sizes (divisible by 10 or 25)
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        60.0 // perfect fill
    } else if pr % 50 == 0 {
        40.0
    } else if pr % 25 == 0 {
        25.0
    } else if pr % 10 == 0 {
        15.0
    } else if pr % 5 == 0 {
        8.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Tight fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / cap;
    if fill_ratio > 0.7 {
        score -= 20.0 * fill_ratio;
    } else if fill_ratio > 0.5 {
        score -= 8.0 * fill_ratio;
    }

    // Dead space penalty: small unusable residual
    if pr > 0 && pr < 10 {
        score += 35.0; // dead space below min item size
    } else if pr > 0 && pr < 20 {
        score += 12.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Lookahead: if next item fits exactly or well into post_residual, reward leaving it
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0; // perfect chain
        } else if next_item_size <= pr {
            score -= 10.0 * (next_item_size as f64 / pr.max(1) as f64);
        } else {
            // next item won't fit here; slight penalty for leaving large gap unused
            score += 5.0;
        }
    }

    // New-bin candidate handling: empty bin gets a mild opening cost so we prefer
    // existing bins unless they fit poorly
    if bin_residual == bin_capacity {
        score += 18.0 + 0.05 * open_bins_count as f64;
    }

    // Prefer bins with lower residual than the mean (consolidate fullness)
    let res_frac = post_residual as f64 / cap;
    let mean_frac = mean_residual / cap;
    score += 10.0 * (res_frac - mean_frac);

    // Stream progression: later in stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - res_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small for the smallest
    // possible future item are pure waste. Penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin completely.
        score -= 40.0;
    } else {
        // Usable gap: mildly reward leaving room for the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        // Reward tight fits (small usable gap) proportionally.
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // this is a great chain placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    // If next item cannot fit in post residual but this bin could have
    // held it better than alternatives, mild penalty for stranding it.
    if next_item_size > post_residual && next_item_size > 0 && post_residual < 15 {
        score += 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual < 10 {
            score += 15.0; // ...but not if it creates dead space.
        }
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (new-bin candidate gets penalized) and encourage consolidating.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of a fresh bin plus pressure.
        score += 5.0 + 3.0 * open_bins_count as f64;
        // Late in the stream, opening a new bin is less risky.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
        // If no open bin leaves a usable gap, opening a new bin is fine.
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
        // Reserve-space logic: if next item needs a fresh bin anyway,
        // opening now is neutral-to-good.
        if next_item_size > 0 && next_item_size > mean_residual {
            score -= 6.0;
        }
    } else {
        // Mild reward for filling existing bins when many are open.
        score -= 0.5 * open_bins_count as f64;
    }

    // Prefer bins whose residual is close to the item (best-fit core),
    // scaled by how tight the fit is.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 12.0 * tightness;

    // Early stream: keep bins flexible (avoid tiny residuals early).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 20 && progress < 0.3 {
        score += 8.0 * (1.0 - progress / 0.3);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - diff / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item cannot fit here: penalize dead space creation
        score += 25.0 + post_residual as f64 * 0.2;
    }

    // Perfect fit bonus (item exactly fills bin)
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize small unusable residuals (< typical minimum item size 10)
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // Compare residual against mean residual: prefer tighter-than-average bins
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when it enables a good 2-step chain
    if bin_residual == bin_capacity {
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score += 8.0; // keep slightly worse than a good existing fit
        } else {
            score += 45.0; // discourage opening new bins unnecessarily
        }
    }

    // Late in stream: be more conservative, prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: prefer consolidating into tighter fills
    if open_bins_count > 4 {
        score -= 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill * fill;

    // Lookahead: if the next item exactly or nearly fits the post residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: mild penalty proportional to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 3.0 * (over / 100.0).min(1.0);
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize creating tiny dead space that nothing (min item 1..100) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // New-bin candidate handling: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        let avg_fit = mean_residual / bin_capacity as f64;
        // Prefer opening a new bin when existing bins are very full (small mean residual)
        // or when there are no fitting bins at all.
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let tightness = 1.0 - avg_fit; // high when bins are nearly full
        let penalty = 55.0
            - 30.0 * tightness
            - 45.0 * desperation
            - 5.0 * (crowd / (crowd + 4.0));
        score += penalty.max(-10.0);
        // Early in the stream, opening bins is cheaper (future items can fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    } else {
        // Slight preference for bins with residual far from mean (diversify residual pool)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 2.0 * (dev / bin_capacity as f64).min(1.0);
    }

    // Late-stream consolidation: favor reusing existing bins more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (bin_residual < bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Base: prefer tight fits, with a smooth non-linear penalty on dead space
    let mut score = pr * (1.0 + 0.35 * fill * fill);

    // Non-linear coupling of post_residual with stream progress:
    // later in the stream, dead space matters more (quartic growth)
    score += pr * pr / cap * (0.2 + 1.3 * progress * progress * progress * progress);

    // Smooth interaction: item size vs progress (large items early are cheap to place)
    score -= it * (1.0 - progress) * 0.15;

    // Lookahead: reward bins whose residual can still host the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = pr - ni;
        if gap >= 0.0 {
            score -= 6.0 * (1.0 - (gap / cap).powi(2));
        } else {
            score += 3.0 + 0.05 * (-gap);
        }
    }

    // Last-chance bin: strong smooth bonus to avoid opening a new bin needlessly
    if fitting_bins_count == 1 {
        score -= 10.0 + 8.0 * progress;
    }

    // Crowd control: many open bins -> favor consolidation via mean residual coupling
    let crowd = open_bins_count as f64 / (1.0 + open_bins_count as f64);
    score += crowd * (pr - mean_residual).abs() * 0.08;

    // New-bin candidate: penalize mildly so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let mut score = pr as f64;

    // New-bin candidate: penalize so it only wins when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += cap * 0.6;
    }

    // Tight-fit rewards (harmonic tiers on post_residual).
    if pr == 0 {
        score -= 45.0;
    } else if pr <= 5 {
        score -= 22.0;
    } else if pr <= 10 {
        score -= 12.0;
    } else if pr <= 20 {
        score -= 5.0;
    }

    // Modulo-10 harmonic classes: multiples of 10 leave reusable slots.
    score -= match pr % 10 {
        0 => 9.0,
        1..=3 => 3.0,
        4..=7 => 0.0,
        _ => 2.0,
    };

    // Lookahead: does the next item fit into the leftover space?
    if next_item_size > 0 {
        if (next_item_size as u32) <= pr {
            score -= 14.0;
            // exact two-item closure is ideal
            if next_item_size as u32 == pr {
                score -= 10.0;
            }
        } else {
            // leftover too small for next item: dead-space penalty scaled by gap
            score += (next_item_size as u32 - pr) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 28.0;
    }

    // Penalize dumping tiny items into large-residual bins (waste of capacity).
    if (item_size as f64) < (bin_residual as f64) * 0.3 && bin_residual != bin_capacity {
        score += 10.0;
    }

    // Tiny unfixable slivers are dead space.
    if pr > 0 && pr < 8 {
        score += 6.0;
    }

    // Mean-residual coupling: prefer bins near the mean (balanced packing).
    score += ((pr as f64 - mean_residual).abs()) * 0.05;

    // Mild stream-phase scaling to stay adaptive over long streams.
    let phase = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * phase;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: small gaps (<10, or too small for next item) are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }
    // Reward exact or near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward using tight bins when few bins fit the item (last chance).
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many open bins.
    score += (open_bins_count as f64) * 0.5;

    // Prefer bins whose residual is below mean residual (tighter bins first).
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Reward leaving room for the lookahead item when possible.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Early in the stream, be more willing to open new bins (better packing later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 5.0 - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: this bin can host the next item exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item also fits in this bin after placement: strong reward,
    // scaled by how snug the chain becomes.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - chain_slack * 0.35;
    }

    // Dead space: post_residual too small for the next item (typical sizes 10..80)
    // and too small for the smallest possible item -> penalize wasted capacity.
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 25.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Can't chain next item, but residual may still be useful later.
        score += (post_residual as f64).max(0.0) * 0.05;
    }

    // Compare against mean residual: prefer bins tighter than average
    // (best-fit flavor) unless it creates dead space.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.15;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: mildly penalize opening a new bin early in the stream,
    // but allow it when open bins are all very tight (high mean fit pressure).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = if mean_residual > 0.0 { (item_size as f64 / mean_residual).min(2.0) } else { 2.0 };
        score += 12.0 + progress * 8.0 - (pressure - 1.0) * 20.0;
    }

    // Slight preference to fill nearly-full bins completely.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 {
        let dead = (post_residual as f64) / cap;
        if post_residual < 10 {
            score += 25.0 * (10.0 - post_residual as f64);
        } else if dead < 0.25 {
            score += 12.0 * (0.25 - dead);
        }
    }

    // Lookahead: strongly reward bins whose post_residual fits the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 / (1.0 + slack);
        } else {
            // next item won't fit here; slight penalty for wasting the gap
            score += 6.0;
        }
    }

    // Last-chance bin: if only this bin fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Crowding: when many bins are open, prefer filling existing ones over opening new.
    let crowding = (open_bins_count as f64).ln() + 1.0;
    score += 3.0 / crowding;

    // Mean residual coupling: if this bin's residual deviates favorably from mean, reward.
    let resid = bin_residual as f64;
    score -= 0.15 * (resid - mean_residual);

    // Time horizon: early in stream, be more selective (penalize mediocre fits);
    // late in stream, just pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 8.0 * tightness * (1.0 - tightness);

    // New-bin candidate: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative, must open
        } else if post_residual as f64 > cap * 0.5 {
            score -= 20.0; // big item, fresh bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = pr * (1.0 + 0.8 * pr_norm * pr_norm);

    // Smooth polynomial coupling of post-residual with stream progress:
    // later in the stream, tighter packing matters more
    let progress_coupling = 1.0 + progress * (1.0 - progress) * 2.0;
    score += 12.0 * pr_norm * pr_norm * fit_ratio * progress_coupling;

    // Reward near-perfect fits smoothly (post_residual near zero)
    score -= 25.0 * (1.0 - pr_norm).powi(6) * fit_ratio;

    // Penalize leaving residuals that likely become dead space:
    // smooth interaction with next item lookahead
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        let gap_norm = gap / cap;
        score += 10.0 * gap_norm * (1.0 - gap_norm) * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 18.0 + 15.0 * (1.0 - fit_ratio);
    }

    // Mild penalty for bins already crowded relative to fleet mean
    score += 3.0 * (mean_residual - bin_residual as f64) / cap;

    // Slight preference to keep number of open bins bounded early on
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate (empty bin): its naturally large post_residual already
    // scores high; add smooth extra resistance that decays with progress
    let is_new = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new {
        score += 20.0 * (1.0 - progress) + 6.0 * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor minimal waste.
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 40.0 * tight * tight;

    // Harmonic class logic: partition post_residual into modulo-10 classes.
    // Residuals that are multiples of 10 are "clean" and reusable by typical item sizes.
    let pr = post_residual;
    let class = pr % 10;
    if class == 0 {
        score -= 6.0; // clean residual class: very reusable
    } else if class >= 5 {
        score += 3.0 + 0.5 * class as f64; // awkward dead space
    } else {
        score += 1.5 * class as f64;
    }

    // Integer-division thresholds: residual usable by common size bands.
    let usable = pr / 10; // number of 10-sized slots left
    score -= 2.0 * usable as f64;

    // Lookahead: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / cap);
        if pr % next_item_size.max(1) == 0 {
            score -= 5.0; // perfect harmonic divisor fit
        }
    }
    // Next item cannot fit here: penalize slightly to prefer bins that chain.
    if next_item_size > 0 && next_item_size > pr {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Prefer filling bins whose residual is already small relative to mean.
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 3.0 * (res_f - mean_residual) / cap;
    }

    // New-bin candidate: make it unattractive unless residual is huge and current
    // fit is terrible. Base penalty keeps open bins preferred.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Late in the stream, opening a fresh bin is slightly cheaper to allow
        // (long-run consolidation matters less).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
        // If item is large relative to capacity and no good fit exists, allow it.
        if item_size as f64 > 0.7 * cap {
            score -= 20.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (post_residual below ~10 is a "gap")
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Mild penalty for medium gaps that few items can use
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward perfect fits
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward fits that leave room for the next item (lookahead k=2)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open bins pressure: penalize placements into bins when many bins are open,
    // but less so if this is the last fitting bin (avoid opening a new bin unnecessarily)
    if fitting_bins_count == 1 {
        score -= 20.0;
    }
    score += (open_bins_count as f64) * 0.5;

    // Tightness reward: prefer filling bins that are already mostly full
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * 10.0;

    // Prefer bins with residual below mean residual (tighter than average)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // New-bin candidate handling: only open a new bin when the item is large
    // relative to a fresh bin and no tight fit exists
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size > 60 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 20.0 * tightness;

    // Aggressive 2-step lookahead: if next item exactly fills post_residual, strongly reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize proportionally to leftover waste after both placements
            let two_step_waste = post_residual - next_item_size;
            score += 0.4 * two_step_waste as f64;
            score -= 10.0 * (1.0 - two_step_waste as f64 / post_residual as f64);
        } else {
            // next item does not fit here: penalize more as post_residual approaches next_item_size
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(30.0);
        }
    }

    // Compare against mean residual: prefer bins whose residual deviates usefully
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize creating small unusable dead space (below minimum item size 1..100 heuristics)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Mild penalty for opening a new bin when many bins are already open
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64;
    }

    // Progression: later in stream, prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize large post_residual dead space, especially if no future item can use it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0 + 0.15 * (next_item_size - post_residual) as f64;
        } else {
            // Reward bins whose residual matches the lookahead item well.
            let lookahead_waste = (post_residual - next_item_size) as f64;
            score -= 6.0 / (1.0 + lookahead_waste);
        }
    } else {
        // Last item: strongly prefer minimal post_residual.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of all open bins.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin when plenty of fitting bins exist.
        score += 12.0 + 2.0 * (fitting_bins_count as f64);
        // As the stream progresses, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        // If open bins have lots of residual space, discourage new bins.
        score += 0.05 * mean_residual * (open_bins_count as f64).sqrt();
        // If the item barely fits in any open bin (large item, small residuals), allow new bin.
        let best_possible = mean_residual - item_size as f64;
        if best_possible < 0.0 {
            score -= 40.0;
        }
    } else {
        // Mild penalty for using bins with big residuals when many bins are open (fragmentation control).
        let residual_gap = bin_residual as f64 - mean_residual;
        if residual_gap > 0.0 {
            score += 0.03 * residual_gap;
        }
        // Slight preference for filling bins that are closer to full (reduce bin count pressure).
        let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 5.0 * fill;
    }

    // Small penalty tied to open bin count: discourage spreading across many bins.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Base: prefer tight fits, with a non-linear penalty on residual
    let mut score = pr * (1.0 + 0.05 * fill * fill);

    // Smooth polynomial coupling of residual with stream progress:
    // early on, leftover space matters less; late in the stream, dead space is costly
    let late = progress * progress;
    score += 12.0 * late * pr / cap * (pr / cap);

    // Reward near-exact fits with a smooth bump around zero residual
    score -= 30.0 * (-(pr * pr) / 50.0).exp();

    // Lookahead: if the next item fits the post-residual, reward this placement smoothly
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = pr - nxt;
        if gap >= 0.0 {
            score -= 15.0 * (-(gap * gap) / 200.0).exp();
        } else {
            score += 8.0 * (-gap / cap);
        }
    }

    // Last-chance bin: strong smooth reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins when residuals are large
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap);

    // Penalize opening a new bin when existing bins fit well
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 10.0 + 20.0 * (1.0 - it / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by integer division into bands.
    let band = post_residual / 10; // 0..=10
    // Dead-space penalty grows superlinearly for small unusable residuals (<10)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }
    // Sweet spots: residuals that many common item sizes can still fill.
    // Favor post_residual in {0, 10, 20, 25, 30, 40, 50, 60, 70, 80, 90}
    let harmonics: [u32; 11] = [0, 10, 20, 25, 30, 40, 50, 60, 70, 80, 90];
    if harmonics.contains(&post_residual) {
        score -= 12.0;
    }
    // Modulo arithmetic: residuals divisible by 10 are "friendly"
    if post_residual % 10 == 0 {
        score -= 4.0;
    } else if post_residual % 5 == 0 {
        score -= 2.0;
    } else {
        // awkward residual classes
        score += 3.0;
    }

    // Lookahead coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect follow-up fill
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            // reward if the double placement leaves a harmonic residual
            if nxt_post % 10 == 0 || nxt_post == 0 {
                score -= 8.0;
            } else {
                score += (nxt_post % 5) as f64;
            }
        } else {
            // next item cannot use this bin's remainder; penalize small leftovers
            if post_residual < next_item_size && post_residual > 0 {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so we prefer
    // reusing open bins unless they leave bad dead space.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.05 * open_bins_count as f64;
    }

    // Prefer tight packs relative to mean residual of open bins.
    score += 0.15 * (mean_residual - post_residual as f64).abs();

    // Early in the stream, allow more bins to spread future flexibility.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.3 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64;
    }
    // Zero residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to bin residual (fill ratio of placement).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Open-bin pressure: many open bins -> discourage spreading, prefer reuse.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate: penalize opening a new bin unless the item is
    // large enough that reuse would create bad dead space elsewhere.
    if bin_residual == bin_capacity {
        score += 35.0;
        if item_size > 70 {
            score -= 45.0;
        }
        if item_size <= 30 {
            score += 20.0;
        }
    }

    // Lookahead coupling: if next item fits the post_residual well, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Late in stream, mild pressure to close bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact/near-exact fits (minimal dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0 + (5 - post_residual) as f64 * 20.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can host next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: post_residual exactly matches next item -> huge reward.
            if post_residual == next_item_size {
                score -= 500.0;
            } else {
                // Reward proportional to how tightly the next item fits afterwards.
                let chain_slack = (post_residual - next_item_size) as f64;
                score -= 150.0 - chain_slack * 0.5;
            }
        } else {
            // Penalize leaving a gap too small for the next item (likely dead space).
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 1.5;
        }
    }

    // Compare post_residual against mean residual across open bins.
    // Prefer bins whose post_residual is below mean (tight packing) unless it's a new bin.
    if bin_residual != bin_capacity {
        let mean_gap = mean_residual - post_residual as f64;
        if mean_gap > 0.0 {
            score -= mean_gap * 0.8;
        } else {
            score += (-mean_gap) * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is large
    // and would leave a useful residual for future items.
    if bin_residual == bin_capacity {
        score += 250.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 100.0;
        }
        // Late in the stream, opening new bins is less costly (no future to amortize).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 150.0;
    }

    // Mild penalty for very large residual waste in existing bins.
    if post_residual > 50 && bin_residual != bin_capacity {
        score += (post_residual - 50) as f64 * 0.6;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
