    // Compare with mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate handling: only attractive when no good existing option
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty so we prefer using open bins when reasonably tight
        score += 40.0;
        // as stream progresses, opening new bins becomes less attractive
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 30.0;
        // if many bins are open, discourage spreading
        score += open_bins_count as f64 * 1.5;
        // if the only alternative is poor, allow new bin (fitting_bins_count==1 handled above)
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Early stream: encourage consolidation by slightly penalizing many open bins
    score += open_bins_count as f64 * 0.3;

    // Time-horizon coupling: later in stream, prioritize minimizing immediate waste
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post-residual, modulated by stream progress.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth interaction: residual waste matters more late in the stream.
    score += 12.0 * progress * norm_pr * (1.0 - norm_pr);

    // Tight fits reward: subtract for small post_residual relative to capacity.
    score -= 20.0 * (1.0 - norm_pr).powi(3) * (1.0 - 0.5 * progress);

    // Dead-space penalty: post-residual too small for typical next items.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 15.0 * (nx - pr) / cap;
        } else {
            score -= 6.0 * (1.0 - ((pr - nx) / cap)).abs().min(1.0) * (1.0 - progress);
        }
    }

    // Last-chance bonus: only fitting bin gets preference.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize mildly so it wins only for very poor fits.
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * progress + 0.15 * open_bins_count as f64;
    } else {
        // Slight preference toward bins with below-mean residual (consolidate waste).
        score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: small dead space is fine, mid-range waste is bad
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: near-perfect fit (post_residual <= 5) -> strong reward
    if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    } else if post_residual <= 30 {
        // mid-range: dead space that few items can fill (items 31..50 rare-ish)
        score += 12.0;
    } else if post_residual <= 50 {
        score += 25.0;
    }

    // Integer-division thresholds: post_residual / 10 class
    let class = post_residual / 10;
    score -= (class % 3) as f64 * 3.0; // harmonic wobble across decade classes

    // Modulo logic: residuals that are multiples of common item sizes are reusable
    if post_residual >= 10 {
        if post_residual % 10 == 0 { score -= 10.0; }
        if post_residual % 20 == 0 { score -= 6.0; }
        if post_residual % 5 == 0 { score -= 2.0; }
    }

    // Next-item lookahead: reward if next item fits the post_residual well
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap <= 5 {
            score -= 35.0; // chain a perfect follow-up fit
        } else if gap <= 15 {
            score -= 15.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual {
        // next item cannot use leftover: penalize proportionally to leftover size
        score += pr * 0.15;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when open bins are all crowded
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap_f; // low mean residual => bins full
        if pressure < 0.25 && open_bins_count > 0 {
            score -= 20.0; // everything crowded, allow a fresh bin
        } else {
            score += 40.0 + (open_bins_count as f64) * 2.0; // prefer existing bins
        }
    }

    // Slight preference for tighter bins overall (below mean residual)
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    }

    // Late-stream consolidation: as stream progresses, avoid leaving big residuals
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += pr * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that can never fit a minimum item are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    } else if post_residual > 0 {
        // Graded penalty for small gaps that few future items can use.
        if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 30 {
            score += 10.0;
        }
    }

    // Reward tight fits (low post_residual relative to item size).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item cannot fit in post_residual but would fit an empty bin, slight penalty.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 5.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity, so this doesn't affect it).
    if bin_residual == bin_capacity {
        score += 8.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer bins whose residual is below average (consolidating small gaps).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= 0.3 * diff;
    }

    // Stream progression: late in the stream, be more conservative about new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Near match: next item fits with small waste
    else if next_item_size > 0 && next_item_size <= post_residual {
        let waste = (post_residual - next_item_size) as f64;
        score -= 20.0 - 0.5 * waste;
    }
    // Next item won't fit in leftover: penalize proportionally to dead space
    else if next_item_size > 0 {
        score += 5.0 + 0.3 * (next_item_size as f64 - post_residual as f64);
    }

    // Reward tight fits relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness;

    // Penalize leaving residuals below typical minimum item size (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Compare against mean residual: bins with residual near mean are neutral,
    // large-residual bins preferred (they waste less potential)
    score -= 0.2 * ((bin_residual as f64) - mean_residual);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 10.0 * (mean_residual / bin_capacity as f64) - 5.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
    }

    // Mild preference for consolidating among many open bins
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared waste penalty scaled by capacity.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.3 * next_item_size as f64;
        } else {
            // Penalize leaving residual too small for the next item (dead space risk).
            score += 10.0 + 0.2 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    // or the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 > 4.0 + 10.0 * progress;
        let poor_fit = (item_size as f64 / bin_capacity as f64) < 0.5;
        score += if crowded || poor_fit { 5.0 } else { 120.0 };
        // New bin has full residual; damp its natural residual advantage.
        score += 30.0;
    }

    // Global state coupling: favor bins with residual below mean (tighter bins first).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Time horizon: later in the stream, consolidate harder (penalize large residuals more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64 / bin_capacity as f64) * 25.0;

    // Slight penalty for large items into nearly full bins is implicit; reward
    // placing large items early into roomy bins.
    score -= 0.1 * item_size as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Quadratic dead-space penalty, amplified late in the stream
    let frac = post / cap;
    score += 18.0 * frac * frac * (0.4 + 0.6 * progress);

    // Reward tight fits (small post_residual relative to item)
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= 14.0 * tightness * (1.0 - progress * 0.5);

    // Last-chance bonus: only one fitting bin -> strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Lookahead: penalize if next item fits worse after placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 6.0 * (nxt - post) / cap;
        } else {
            score -= 4.0 * (post - nxt) / cap;
        }
    }

    // Prefer bins below mean residual (keeps residual spread balanced)
    score += 3.0 * ((post - mean_residual) / cap);

    // New-bin candidate: mildly penalize opening new bins early, allow late
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) - 2.0 * progress;
    }

    // Smooth cubic stream coupling
    score += 5.0 * progress * progress * progress * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class logic on post_residual ---
    // Class A: perfect / near-perfect fit (post_residual in {0}) -> strong reward
    if post_residual == 0 {
        score -= 40.0;
    }
    // Class B: dead space (1..=9) unusable for typical items -> heavy penalty
    if post_residual >= 1 && post_residual <= 9 {
        score += 25.0;
    }
    // Class C: harmonic residue classes of capacity fractions.
    // post_residual divisible by 20 (i.e. 20/40/60/80) keeps clean fraction slots.
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 12.0;
    } else if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    // Class D: awkward mid-band (11..=19) -> mild penalty
    if post_residual >= 11 && post_residual <= 19 {
        score += 8.0;
    }

    // --- Lookahead coupling: does the next item fit into post_residual? ---
    if next_item_size > 0 && post_residual >= next_item_size {
        // Reward leaving room for the known next item; tighter leftover is better.
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 - 0.1 * slack;
        // Extra harmonic bonus if next item exactly consumes a class boundary
        if (post_residual - next_item_size) % 10 == 0 {
            score -= 5.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit in the leftover: penalize proportionally to wasted potential
        score += 0.15 * (next_item_size as f64).min(30.0);
    }

    // --- Last-chance bin: only open bin that can fit -> reward strongly ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // --- Crowding pressure: many open bins -> favor consolidation ---
    score += 0.5 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // --- Mean residual coupling: prefer bins with residual below mean (tighter bins) ---
    score += 0.3 * (mean_residual - bin_residual as f64);

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: leftover capacity is the score.
        score = (bin_capacity - item_size) as f64;
        // Early in the stream, new bins are cheap; later, expensive.
        score *= 1.0 + 1.5 * progress;
        // If multiple bins fit, discourage opening a new one.
        if fitting_bins_count >= 2 {
            score += 20.0;
        }
        // If it's the last chance and the fit is decent, mildly discourage new bin.
        if fitting_bins_count == 1 && item_size <= bin_residual {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver -> strong penalty
    }
    // Perfect fit gets a big reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Non-linear waste penalty: waste grows superlinearly in the mid gap range.
    let waste = post_residual as f64;
    score += 0.35 * (waste / 10.0).powi(2);

    // Last chance: if this is the only bin that fits, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current fit is poor or open bins are crowded.
    if bin_residual == bin_capacity {
        score += 15.0; // base cost of opening a new bin
        // Prefer new bin when the item leaves a bad gap in any existing bin
        // and the next item could pair with the leftover.
        if post_residual > 0 && post_residual < 10 {
            score -= 20.0;
        }
        // If next item pairs exactly with this item in a fresh bin, encourage new bin.
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 35.0;
        }
        // Discourage hoarding many open bins with plenty of space.
        if open_bins_count as f64 > mean_residual / 5.0 {
            score += 10.0;
        }
    } else {
        // Existing bin: reward if the leftover post_residual matches the next item size.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 20.0;
        }
        // Penalize leaving a gap the next item cannot use.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 12.0;
        }
    }

    // Open-bin pressure: mild reward for using existing bins as they accumulate.
    score -= (open_bins_count as f64).min(20.0) * 0.3;

    // Late in the stream, tighten up: avoid spreading across bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (waste / 50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: reward leaving exactly zero residual.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward residuals that exactly fit the next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < 0.5 {
            score -= 500.0;
        } else if post_residual as u32 >= next_item_size {
            // Next item still fits here: mild bonus proportional to closeness.
            score -= 50.0 * (1.0 - (post_residual as f64 - next) / bin_capacity as f64);
        } else {
            // Next item cannot use this residual: penalize dead space.
            score += 0.5 * post_residual as f64;
        }
    }

    // Relative residual vs mean residual: prefer bins tighter than average.
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a brand-new bin when decent open bins exist,
    // unless the item is large relative to residual (poor fit everywhere).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_penalty = 50.0 + 100.0 * (1.0 - progress);
        score += open_penalty + open_bins_count as f64;
        // Allow new bin when fit is very tight anyway (large item).
        if (item_size as f64) > 0.7 * bin_capacity as f64 {
            score -= 120.0;
        }
    }

    // Small nudge toward filling larger residuals with bigger items.
    score += 0.1 * (item_size as f64) * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fills (small post_residual is already the base).
    let tight_fit_bonus = if post_residual == 0 {
        60.0
    } else if post_residual <= 10 {
        25.0
    } else if post_residual <= 20 {
        10.0
    } else {
        0.0
    };
    score -= tight_fit_bonus;

    // Penalize creating dead space that is too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size as f64 {
            score -= 8.0 + 0.15 * (next_item_size as f64);
        } else if post_residual > 0 {
            score += 6.0; // leftover likely wasted relative to lookahead
        }
        // Perfect two-item chain: item + next fills bin exactly.
        if item_size as f64 + next_item_size as f64 == bin_residual as f64 {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer bins with below-average residual (consolidate fullness).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Mild penalty for spreading across many open bins.
    score += 0.4 * open_bins_count as f64;

    // New-bin candidate handling: opening a fresh bin is attractive early in the
    // stream or when the item fits poorly everywhere / next item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (post_residual as f64 / bin_capacity as f64) > 0.5;
        let big_next = (next_item_size as f64) >= 0.6 * bin_capacity as f64;
        if (poor_fit || big_next) && step_index > 0 {
            score -= 12.0 + 20.0 * (1.0 - progress);
        } else {
            score += 10.0; // discourage opening bins casually
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, scaled smoothly by stream progress
    let mut score = pr * (1.0 + 0.5 * progress * pr_norm);

    // Non-linear coupling: penalize large post residuals more as stream progresses
    score += 40.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits (small post residual) with smooth decay
    score -= 25.0 * (-pr / 20.0).exp();

    // Perfect-fill bonus (post_residual == 0)
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: penalize if post residual can't fit next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (1.0 - pr_norm) * (nx / 100.0);
        } else {
            score += 10.0 * (nx / 100.0) * (1.0 + progress);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress * 0.5);
    }

    // Many open bins: mild penalty to avoid bin proliferation
    score += open_bins_count as f64 * 0.5 * pr_norm;

    // Mean residual coupling: prefer bins deviating below mean residual (tighter)
    score += 3.0 * (mean_residual - pr).max(-50.0).min(50.0) / 100.0;

    // New-bin candidate: penalize opening a new bin unless residuals are all small
    if bin_residual == bin_capacity {
        let new_bin_bias = 15.0 + 60.0 * (1.0 - progress) + (mean_residual / cap) * 40.0;
        score += new_bin_bias;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are nearly closed -> reward tight packing.
    let residue_class = post_residual / 10; // classes: 0..=9 (0 = tightest)
    score -= (9 - residue_class) as f64 * 4.0;

    // Integer-division thresholds on post_residual vs next_item_size:
    // reward bins where the lookahead item can also be nested exactly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            let pair_waste = post_residual - next_item_size;
            if pair_waste < 10 {
                score -= 15.0; // near-perfect two-item nesting
            }
        } else {
            score += 8.0; // next item cannot reuse this bin's leftover
        }
        // Modulo coupling: leftover that is a multiple of the next item
        // leaves a harmonically clean remainder.
        if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
            score -= 6.0;
        }
    } else {
        // Last item: prefer zero waste strongly.
        score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin before opening a new one: strong bonus to avoid sprawl.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New empty bin candidate: only attractive when the current bin would
    // leave a large, awkward dead zone (residue class >= 6) or when the
    // item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let awkward = residue_class >= 6;
        if awkward {
            score -= 18.0; // opening fresh bin beats leaving big dead space
        } else {
            score += 25.0; // keep using existing harmonically-tight bins
        }
    }

    // Progress-aware tightening: late in the stream, waste is costlier.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.5;

    // Penalize bins far from the mean residual state (keeps bin family coherent).
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Small bonus for large items filling big chunks of the bin.
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill: strongly reward completely closed bins.
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual < 10 {
        // Strict dead-space avoidance: a gap smaller than the minimum item
        // size is permanently unusable -> penalize it as wasted capacity.
        score += 8.0;
    }

    // If the leftover gap can't accommodate the lookahead item (nor the
    // smallest possible item), the bin is likely to strand space: penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Last-chance bin: if this is the only open bin that fits, prefer using
    // it over opening a new bin (bin-count pressure).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize proportional to how many bins are already
    // open, plus a base reluctance, so existing bins are preferred unless
    // they would create bad dead space.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        // If the next item is large, a fresh bin is slightly more attractive
        // (it preserves big contiguous space for big items).
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0;
        }
    }

    // Coupling with mean residual: mildly favor bins whose resulting residual
    // sits below the current mean (tighter-than-average packing).
    let gap = mean_residual - post_residual as f64;
    if gap > 0.0 {
        score += gap * 0.1;
    }

    // Stream-progression pressure: late in the stream, closing bins tightly
    // matters more; slightly amplify dead-space penalties near the end.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if post_residual > 0 && post_residual < 10 {
            score += 6.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Tight fit reward: penalize large post_residual relative to capacity
        score += (post_residual as f64 / bin_capacity as f64) * 50.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            score -= 100.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize wasted post_residual
            score += 30.0;
        }
    } else {
        // last item: prefer minimal post_residual
        score += post_residual as f64 * 2.0;
    }

    // Mean residual coupling: prefer bins with residual below mean (tighter bins)
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_capacity != bin_residual {
        score -= 500.0;
    }

    // Late stream: prefer filling existing bins rather than opening new ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 40.0;
    } else {
        // New-bin candidate: mild penalty so it's chosen only when fits are bad
        score += 60.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize creating unusable dead space (post_residual too small for typical future items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: bonus if next item fits exactly in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain fit
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty proportional to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 0.15 * over;
        }
    } else {
        // last item: prefer filling bins as fully as possible
        score -= 10.0 * tightness;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Time horizon: early in the stream, keep residuals flexible (penalize very tight fits slightly);
    // late in the stream, prioritize consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.3 {
        score += 6.0 * (post_residual as f64 / bin_capacity as f64) * (0.3 - progress) * 10.0;
    } else {
        score -= 8.0 * progress;
    }

    // Global state: many open bins with high mean residual -> encourage consolidation into this bin.
    if open_bins_count > 2 && mean_residual > (item_size as f64) {
        score -= 5.0 * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when it beats consolidation; penalize mildly by default,
    // more so when other bins can fit the item.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * fitting_bins_count as f64;
        // Opening a new bin is fine early when next item is large and residuals are fragmented.
        if next_item_size >= 50 && mean_residual < 30.0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual

    let mut score = post;

    // Non-linear coupling of post residual with stream progress:
    // early on, keep flexibility (penalize tiny residuals more); late, tolerate them.
    let poly = 3.0 * x * x - 2.0 * x * x * x; // smoothstep in [0,1]
    score += (1.0 - poly) * (cap * 0.15) * (1.0 - progress);

    // Penalize dead space quadratically as it becomes unusable relative to typical item size
    let dead = post - item_size as f64;
    if dead > 0.0 {
        score += 0.08 * dead * dead / cap;
    }

    // Reward tight fits
    score -= 10.0 * (1.0 - x) * (1.0 - x);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: prefer leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 8.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 6.0;
        }
    }

    // Mild pressure against spreading across too many bins
    score += 0.5 * open_bins_count as f64 * progress;

    // Prefer bins with residuals near the mean (balanced packing)
    score += 0.3 * (post - mean_residual).abs();

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 30.0 - 40.0 * progress;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo small integers
    // classify "dead space" quality. Small post_residual that is a
    // multiple of common item sizes is reusable; odd tiny residues are dead.
    let pr = post_residual;
    if pr > 0 {
        // Reusable residue classes (multiples of 10/20/25/50 keep usable)
        if pr % 10 == 0 { score -= 3.0; }
        if pr % 20 == 0 { score -= 2.0; }
        if pr % 25 == 0 { score -= 1.5; }
        if pr % 50 == 0 { score -= 2.0; }
        // Odd tiny residues are dead space
        if pr < 10 && pr % 2 == 1 { score += 6.0; }
        if pr < 5 { score += 8.0; }
        // Perfect fit reward
        if pr == 0 { score -= 25.0; }
    }

    // Lookahead coupling: does the residue fit the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 4.0 + (pr - next_item_size) as f64 * 0.05;
        } else if pr > 0 {
            score += 2.0; // next item won't fit here
        }
        // Harmonic pairing: post_residual + next item near capacity
        let pair = pr + next_item_size;
        if pair == bin_capacity { score -= 10.0; }
    }

    // Last-chance bin: strongly favor using it before opening new
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize mildly so we prefer existing bins,
    // but allow opening when all open bins would leave bad residue.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.85 + 2.0;
        // Late in stream, prefer consolidation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 4.0;
        if open_bins_count > 8 { score += 2.0; }
    }

    // Tight-fit bonus via capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.05 { score -= 5.0; }
    if frac > 0.9 { score += 3.0; } // nearly empty placement wastes bin

    // Spread penalty: avoid diverging far from mean residual
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (unusable for typical items) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit is ideal.
        score -= 40.0;
    }

    // Reward filling most of the bin (post_residual small relative to capacity).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another one.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 18.0 + 2.5 * open_bins_count as f64;
    } else {
        score -= 1.5 * open_bins_count as f64;
    }

    // Prefer bins whose residual is close to the mean (keeps bin states balanced),
    // unless the fit is very tight.
    let dev = (bin_residual as f64 - mean_residual).abs();
    if post_residual >= 10 {
        score += 0.3 * dev;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 20.0;
    }
    // Penalize leaving a gap that the next item barely misses (wasted opportunity).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // Late in the stream, consolidate: prefer existing bins even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if !new_bin {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: post_residual close to 0 is already favored by the base term.

    // 2-step lookahead: if the NEXT item fits exactly into the post residual,
    // this bin is a perfect chain match -> strong reward.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // Next item fits well (leaves small slack again) -> moderate reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_leftover = post_residual - next_item_size;
        score -= (20.0_f64).min(next_leftover as f64 * 0.5);
    }
    // Next item does NOT fit in the post residual: penalize wasted chain potential,
    // scaled by how much residual would be stranded.
    if next_item_size > 0 && next_item_size > post_residual {
        score += (post_residual as f64) * 0.3;
    }

    // Penalize large stranded residuals relative to the mean residual across open bins:
    // a bin whose post_residual is far above the mean leaves below-average usable space.
    score += ((post_residual as f64) - mean_residual).max(0.0) * 0.2;

    // Last-chance bin (only one fitting bin): strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: only attractive when the item is large relative to capacity
    // or when few bins fit the item; otherwise discourage proliferation of open bins.
    if bin_residual == bin_capacity {
        let load_ratio = item_size as f64 / bin_capacity as f64;
        score += 30.0; // base penalty for opening a new bin
        score -= load_ratio * 45.0; // large items justify new bins
        if fitting_bins_count > 2 {
            score += 20.0; // plenty of alternatives -> keep new bin closed
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.max(1) {
            score -= 15.0; // next item is big; a fresh bin gives flexibility
        }
    }

    // Late in the stream, tighten packing: prefer tight fits even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 0.0 + progress * ((bin_capacity - post_residual) as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize dead space that cannot fit the next item (lookahead k=2)
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0 + 0.15 * (post_residual as f64);
        }
        // Reward if next item fits exactly into the post residual
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when the fit here is poor
    let is_new_bin = bin_residual == bin_capacity && bin_capacity >= item_size;
    if is_new_bin {
        // Base penalty so new bins are not opened frivolously
        score += 15.0;
        // But if the item leaves a very awkward residual in existing bins, new bin becomes attractive
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            score -= 12.0;
        }
        // Late in the stream, consolidate more aggressively
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Global state coupling: many open bins with high mean residual -> prefer filling existing bins
    if open_bins_count > 3 {
        let fill_pressure = mean_residual / bin_capacity as f64;
        score -= 5.0 * fill_pressure;
    }

    // Mild penalty for leaving residuals in the "hard to fill" band (just above typical small items)
    if post_residual > 50 && post_residual < 70 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tightness = 1.0 - pr / cap; // how full bin becomes

    let mut score = pr;

    // Reward tight fits (small post_residual) with a non-linear bonus
    score -= 40.0 * tightness.powi(3);

    // Penalize dead space: mid-range residuals are worst; smooth quadratic coupling with progress
    let dead = (pr / cap - 0.5).powi(2);
    score += 30.0 * dead * (0.5 + progress);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - pr / cap) * (1.0 + progress);
    } else if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 6.0 * (pr / cap);
    }

    // Discard near-empty new bins unless open bins are crowded
    let is_new = bin_residual == bin_capacity;
    if is_new {
        score += 8.0 + 5.0 * (1.0 - (open_bins_count as f64 / (open_bins_count as f64 + 3.0)));
    } else {
        score -= 3.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    // Mean-residual coupling: prefer bins whose resulting residual is below mean (consolidation)
    score += 4.0 * ((pr - mean_residual) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post-residual (integer division thresholds) ----
    // Class 0: perfect fit (post_residual == 0) -> strongest reward.
    // Class 1: tiny dead space (<=5) -> still excellent.
    // Class 2: medium sliver (<=15) -> good, may pair with small items.
    // Class 3: large leftover (>15) -> penalize, it wastes capacity.
    let cls = if post_residual == 0 { 0 } else if post_residual <= 5 { 1 } else if post_residual <= 15 { 2 } else { 3 };
    match cls {
        0 => score -= 25.0,
        1 => score -= 15.0,
        2 => score -= 5.0,
        _ => { score += 4.0 + (post_residual as f64 - 15.0) * 0.15; }
    }

    // ---- Coupling: post_residual vs next_item_size (k=2 lookahead) ----
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect match for the next item: extremely desirable.
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // Bin can still host the next item: reward proportionally to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here: penalize dead space relative to gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.20 * gap.min(50.0);
        }
    }

    // ---- Last-chance bin: only fitting bin before opening a new one ----
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Fresh bin: baseline is its empty residual; attractive only when the
        // item is large (would leave little usable space anyway) or when open
        // bins are already crowded.
        score = bin_capacity as f64 - 20.0;
        if item_size >= 70 { score -= 15.0; }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity { score -= 6.0; }
        if open_bins_count == 0 { score -= 40.0; }
        // Late in the stream, prefer consolidating into open bins less strongly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * (1.0 - progress);
    }

    // ---- Modulo-arithmetic harmony: residual classes that sum to capacity ----
    // Favor bins whose current residual is congruent to a "friendly" class
    // (multiples of 10 divide capacity harmonically, easing future packing).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    // Penalize awkward odd residuals that rarely pair with integer item sizes.
    if post_residual % 2 == 1 && post_residual > 0 {
        score += 2.0;
    }

    // ---- Mean-residual context: prefer bins below mean (tighter bins) ----
    let dev = mean_residual - post_residual as f64;
    score += 0.10 * dev.clamp(-40.0, 40.0);

    // ---- Congestion scaling: many open bins -> consolidate more aggressively ----
    score += 0.30 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 35 {
        score += 6.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Last-chance bin: strongly prefer filling it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 12.0 + 4.0 * open_bins_count as f64;
    }

    // Lookahead coupling: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item cannot fit in post residual but could fit elsewhere, mild penalty.
    if next_item_size > post_residual && next_item_size > 0 && next_item_size <= bin_capacity {
        score += 3.0;
    }

    // Early stream: be slightly more conservative about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.15 * (1.0 - progress);

    // Deviation from mean residual: prefer bins whose residual is close to item need.
    score += (bin_residual as f64 - item_size as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-perfect lookahead: next item fits with small leftover.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = (post_residual - next_item_size) as f64;
        score -= 300.0 - leftover * 2.0;
    }
    // Next item does NOT fit this residual: penalize dead space, worse if tiny.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 50.0 + (next_item_size - post_residual) as f64;
    }

    // Penalize tiny unusable residuals (dead space) nonlinearly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 5.0;
    }

    // Reward tight fits relative to the bin: small post_residual overall.
    score -= (bin_capacity - post_residual) as f64 * 0.5;

    // Relative to mean residual: prefer bins with less residual than average.
    score += (mean_residual - post_residual as f64) * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Slight preference for existing bins over opening new ones.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    // Late in stream: be more conservative, prefer filling bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness;

    // Penalize creating dead space: post_residual too small to fit anything useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // next item won't fit here; mild penalty proportional to waste
            score += 2.0 * (next_item_size as f64 - post_residual as f64) / 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Global state coupling: with many open bins, prefer filling existing ones
    // (penalize new-bin candidate which has bin_residual == bin_capacity).
    let open_bonus = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        score += 5.0 + open_bonus * 3.0;
        // Opening a new bin is acceptable early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 4.0 * (1.0 - progress);
    } else {
        score -= open_bonus * 1.5;
    }

    // Prefer bins with residual below mean residual (more filled bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    // Time horizon: late in the stream, be more aggressive about tight packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Strong quadratic penalty on waste, amplified late in the stream.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 6.0 * waste * waste * (0.5 + progress) * (bin_capacity as f64);

    // Reward near-perfect fits (small post_residual) with a smooth bump.
    let tight = (post_residual as f64 / bin_capacity as f64).exp();
    score -= 12.0 * (1.0 - tight) * (1.0 + progress);

    // Penalize bins whose residual deviates from the mean residual (fragmentation control).
    let dev = (bin_residual as f64 - mean_residual).abs() / bin_capacity as f64;
    score += 3.0 * dev * dev * bin_capacity as f64;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 8.0 * progress;
    }

    // Lookahead coupling: reward leaving space the next item can use,
    // penalize residuals that are useless for the upcoming item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            let gap = (post_residual as f64 - nx) / bin_capacity as f64;
            score -= 5.0 * (-gap * 10.0).exp();
        } else {
            let unusable = (nx - post_residual as f64) / bin_capacity as f64;
            score += 4.0 * unusable * bin_capacity as f64 * (0.3 + 0.7 * progress);
        }
    }

    // Mild penalty for spreading across many open bins late in the stream.
    score += 0.15 * open_bins_count as f64 * (0.2 + progress);

    // New-bin candidate: prefer opening a new bin only when it beats
    // genuinely poor fits — make the empty bin mildly attractive early,
    // costly late.
    if bin_residual == bin_capacity {
        score += 2.0 + 10.0 * progress;
        if post_residual == bin_capacity {
            score -= 1.5 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: small post_residual is good, but avoid exact-zero traps
    // that strand a bin when a slightly larger item could have used it.
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 12.0;
    } else if post_residual <= 5 {
        score -= 9.0;
    } else if post_residual <= 10 {
        score -= 6.0;
    } else {
        score += pr * 0.35;
    }

    // Harmonic class of post_residual: residual buckets by capacity fraction.
    // Residuals in [0,10] are "prime slots" (fit many future small items);
    // residuals in (10,25] are awkward mid-dead-space; (25,50] recoverable.
    let frac = pr / bin_capacity as f64;
    if frac > 0.10 && frac <= 0.25 {
        score += 8.0; // awkward dead zone
    } else if frac > 0.25 && frac <= 0.50 {
        score += 3.0;
    } else if frac > 0.50 {
        score += 1.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // strongly reward; if next item barely misses, penalize.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 10.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / 30.0).max(0.0);
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 3.0 * (1.0 - miss / 30.0).max(0.0);
        }
        // Harmonic divisibility: residual that is a multiple of common small
        // item sizes (10,20,25,50) is more reusable.
        if post_residual > 0 {
            let r = post_residual;
            if r % 10 == 0 || r % 25 == 0 {
                score -= 2.5;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer fullest bins (small bin_residual) among many open bins.
    score += (bin_residual as f64) * 0.15;
    score += mean_residual * 0.05 * (open_bins_count as f64).sqrt().min(4.0);

    // Late in the stream, consolidation matters more: penalize leaving any
    // residual when few items remain.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.85 {
        score += pr * 0.5;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else {
            (mean_residual - item_size as f64).abs()
        };
        score += 25.0 + desperation * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    let next_size = if next_item_size == 0 { 0 } else { next_item_size };
    let dead = post_residual > 0 && post_residual < 10 && next_size > post_residual;
    if dead {
        score += 40.0;
    }
    // Gap too small for the lookahead item but not yet "dead" (could still fit
    // some future item): moderate penalty proportional to wasted capacity.
    if post_residual < next_size && post_residual > 0 {
        score += 8.0 + 0.25 * post_residual as f64;
    }

    // Reward tight fits: the less leftover, the better (beyond base post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than fragmenting further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.8 * open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate: penalize unless current bins are crowded or the
    // placement would create severe dead space.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < item_size as f64 * 0.5;
        let would_waste = post_residual < 10 && next_size > post_residual;
        if !crowded && !would_waste {
            score += 35.0 + 2.0 * open_bins_count as f64;
        } else if crowded {
            score -= 10.0;
        }
    }

    // Slight preference for bins below mean residual (balancing large gaps).
    if (bin_residual as f64) > mean_residual {
        score += 3.0;
    }

    // Lookahead synergy: leftover space exactly fitting next item is great.
    if next_size > 0 && post_residual == next_size {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        // Perfect match: post_residual equals next item size -> strong reward.
        if post_residual == next_item_size {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Next item still fits here: reward proportionally to how well it fills.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * fill;
        } else {
            // Next item cannot use the leftover space: penalize dead space.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste;
        }
        // Coupling with mean residual: prefer bins whose post_residual
        // sits near the mean (keeps residuals homogeneous, easier future matches).
        let dev = (post_residual as f64 - mean_residual).abs();
        score += 0.12 * dev;
    } else {
        // Last item: minimize leftover directly (already base score).
        score += 0.05 * post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: reserve it for large items or when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when stream is early
        // (more future items to fill it) or many bins already open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 60.0 + 40.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            // A new empty bin guarantees fitting the next item too.
            new_bin_score -= 20.0;
        }
        // If open bins are already quite full on average, new bin is reasonable.
        new_bin_score -= 0.3 * (bin_capacity as f64 - mean_residual);
        score = score.max(new_bin_score);
        score = new_bin_score;
    }

    // Slight preference for tighter fits among open bins.
    score += 0.05 * (bin_residual - item_size) as f64 / bin_capacity as f64 * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual non-linearly.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * tightness * 40.0;

    // Reward bins whose residual is exactly consumed well (near-perfect fit).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Lookahead: penalize leaving a residual that cannot fit the next item (dead space),
    // reward leaving a residual that exactly or nearly fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Dead space relative to next item
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
        // Reward residuals that could fit a typical mid-size future item
        if post_residual >= 10 && post_residual < next_item_size {
            score += 4.0;
        }
    } else {
        // Last item: strongly prefer filling an existing bin.
        score -= 20.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; penalize mildly,
    // but allow it when existing bins would waste a lot (large post_residual).
    if bin_residual == bin_capacity {
        let pressure = mean_residual / (bin_capacity as f64);
        // Open new bin when existing bins are fairly full and many are open.
        score = (bin_capacity as f64) * 0.55 - pressure * 20.0 + (open_bins_count as f64) * 0.5;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
        // If next item is large, a fresh bin is more attractive.
        score -= (next_item_size as f64) * 0.15;
    }

    // Mild penalty for spreading across too many open bins when mean residual is high.
    if open_bins_count > 4 && mean_residual > 30.0 {
        score += 2.0;
    }

    // Slight preference for fuller bins (smaller bin_residual).
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fill = 1.0 - pr / cap; // fraction of bin filled after placement

    // Base: prefer tight fits via non-linear penalty on post_residual
    let mut score = pr.powf(1.5) / cap;

    // Smooth polynomial coupling of fill ratio with stream progress:
    // late in the stream, compactness matters more (higher-order fill term)
    let compact_term = fill * fill * fill * (1.0 + progress * 2.0);
    score -= compact_term * cap * 0.5;

    // Penalize wasted residual that no future item likely uses, smoothly
    let waste = if next_item_size > 0 {
        let nx = next_item_size as f64;
        let slack = (pr - nx).max(0.0);
        slack * slack / cap
    } else {
        0.0
    };
    score += waste * (0.5 + progress);

    // Reward closing a bin exactly (post_residual ~ 0) more strongly as stream advances
    let exact = (1.0 - pr / cap).powi(8);
    score -= exact * (1.0 + progress * 3.0);

    // Last-chance bonus: only fitting bin; smooth reward scaled by progress
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.0 + 3.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin mildly, more when open bins exist and mean residual is high
    if bin_residual == bin_capacity {
        let mean_fill = 1.0 - mean_residual / cap;
        score += 1.5 + 0.1 * open_bins_count as f64 + mean_fill * 2.0 * (1.0 + progress);
        // but allow new bin if current item is huge and next item is large too
        score -= (item_size as f64 / cap) * (next_item_size as f64 / cap) * 2.0;
    }

    // Small smooth penalty for spreading items thin across many bins
    score += (open_bins_count as f64).powf(0.5) * 0.05 * (1.0 - fill);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space
    // in terms of the known item size granularity (items are 1..=100).
    let pr = post_residual as i64;

    // Penalize dead space that is too small for the smallest plausible item.
    if pr > 0 && pr < 10 {
        score += 40.0 - pr as f64 * 2.0; // tiny dead space is the worst outcome
    }

    // Reward residuals that are harmonic multiples of common size classes.
    // Residuals divisible by 10, 20, 25, 50 are more likely to be filled exactly.
    let harmony_bonus = {
        let mut h = 0.0;
        if pr % 10 == 0 { h += 6.0; }
        if pr % 20 == 0 { h += 4.0; }
        if pr % 25 == 0 { h += 4.0; }
        if pr % 50 == 0 { h += 5.0; }
        if pr == 0 { h += 25.0; } // perfect fit: best possible outcome
        h
    };
    score -= harmony_bonus;

    // Integer-division thresholds: residual bucket classes.
    // Buckets: (0], (0..=10], (10..=20], (20..=35], (35..=60], >60
    let bucket = |r: u32| -> u32 {
        if r == 0 { 0 } else if r <= 10 { 1 } else if r <= 20 { 2 } else if r <= 35 { 3 } else if r <= 60 { 4 } else { 5 }
    };
    let pre_bucket = bucket(bin_residual);
    let post_bucket = bucket(post_residual);
    if pre_bucket != post_bucket {
        // Crossing a harmonic threshold: leaving a small-class residual is bad,
        // leaving a large-class residual is fine.
        if post_bucket == 1 { score += 15.0; }
        else if post_bucket == 2 { score += 8.0; }
        else if post_bucket >= 4 { score -= 3.0; }
    }

    // Lookahead: if the next item fits exactly into the post residual, strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // Reward proportionally to how well next item slots in.
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 10.0 { score -= 12.0 - slack; }
        } else {
            // Next item cannot use the leftover: mild penalty for wasting space.
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0 + (bin_residual - item_size) as f64 * 0.05;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when existing bins fit poorly
        // (large post residuals everywhere) or when the fit here would be bad.
        let poor_fit = (post_residual as f64) > 0.0 && post_residual < 10;
        if poor_fit {
            score -= 35.0; // prefer a fresh bin over creating dead space
        } else {
            // Make the fresh bin slightly worse than a good existing fit,
            // but better than mediocre fits as the stream matures.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 12.0 + 8.0 * (1.0 - progress);
            // If many bins are open with big mean residual, prefer reusing them.
            score += (mean_residual / bin_capacity as f64) * 10.0;
            score += open_bins_count as f64 * 0.5;
        }
    }

    // Mild pressure to consolidate: prefer bins with below-mean residual
    // (tighter bins) when fits are otherwise comparable.
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are heavy penalties.
    let dead_zone = 12.0; // small gap unlikely to fit future items
    if (post_residual as f64) < dead_zone && post_residual > 0 {
        score += 40.0 * (dead_zone - post_residual as f64) / dead_zone;
    }

    // Reward near-perfect fits (residual close to zero but not dead).
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 25.0 * tightness * tightness;

    // Penalize leaving a gap that is just barely too small for the next item
    // (wasted capacity relative to lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        score += 8.0 + 0.3 * miss;
    }
    // Reward leaving a gap that exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // opening a new bin (full residual) is relatively cheaper.
    let pressure = (open_bins_count as f64).ln() + 1.0;
    score += 2.0 * pressure * (post_residual as f64 / cap);

    // New-bin candidate: neutral-ish baseline, only attractive when open bins
    // are heavily fragmented (high mean residual spread) or few bins fit.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score = cap * 0.55 + 0.2 * fragmentation - 5.0 * (fitting_bins_count as f64);
        // Late in the stream, avoid spawning bins unnecessarily.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    } else {
        // Mild attraction toward bins whose residual is close to the item
        // (best-fit core), scaled by global mean residual context.
        let fit_gap = (bin_residual as f64 - item_size as f64).abs();
        score += 0.1 * fit_gap;
        score -= 0.05 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (post_residual close to 0)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // 2-step lookahead: reward if next item exactly fits the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0; // perfect chaining
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how well it uses leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 120.0 * fill;
            // bonus if chain leaves another tiny residual
            let post2 = post_residual - next_item_size;
            if post2 <= 5 {
                score -= 80.0;
            }
        } else {
            // next item will NOT fit here: penalize dead space
            score += 40.0;
            if post_residual < next_item_size && post_residual < 10 {
                score += 30.0; // unusable sliver
            }
        }
    }

    // Penalize wasting a large residual on a small item when mean residual is small
    if post_residual as f64 > mean_residual * 1.5 && item_size < 40 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate: only attractive when current fit is poor
    if bin_residual == bin_capacity {
        if post_residual as f64 > mean_residual + 20.0 && next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 50.0; // opening a fresh bin is fine
        } else {
            score += 120.0; // discourage needless new bins
        }
    }

    // Late in stream: consolidate into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward filling bins snugly (small post_residual relative to capacity).
    let tight = post_residual as f64 / bin_capacity as f64;
    score += tight * tight * 40.0;

    // Lookahead: penalize if next item can't fit in the post residual (wasted synergy),
    // reward if it fits exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack_after_next / bin_capacity as f64);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Global state: many open bins -> prefer consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Mean residual coupling: if this bin's residual is far below mean, it's a "junk" bin —
    // prefer dumping items there to clean up.
    let this_residual = bin_residual as f64;
    if this_residual < mean_residual {
        score -= (mean_residual - this_residual) * 0.3;
    } else {
        score += (this_residual - mean_residual) * 0.15;
    }

    // New-bin candidate: only attractive early in the stream or when fit is terrible.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 / bin_capacity as f64;
        score += 30.0 + 60.0 * (1.0 - progress) - 50.0 * bad_fit;
    }

    // Late stream: penalize leaving large unusable gaps.
    score += progress * (post_residual as f64 / 100.0) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer tight fits, with non-linear (quadratic) dead-space growth.
    let mut score = pr + 0.35 * (pr * pr) / cap;

    // Smooth stream-progress coupling: late in the stream, residual waste
    // matters more (fewer chances to recover), so amplify the penalty.
    let late = progress * progress;
    score += late * 12.0 * (pr / cap);

    // Dead-space penalty if residual cannot fit the next item (smooth via ratio).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).max(0.0) / cap;
        let gap_frac = gap / (nxt / cap).max(1e-6);
        score += 8.0 * gap_frac * gap_frac * (pr / cap);

        // Reward bins where the next item also fits (chaining good fits).
        if nxt <= pr {
            score -= 6.0 * (1.0 - pr / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild preference toward using fuller bins (higher mean residual context).
    score -= (mean_residual / cap) * 3.0;

    // Penalize spreading across too many open bins slightly.
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: neutral-ish baseline so it wins only when open bins
    // would create large dead space.
    if bin_residual == bin_capacity {
        score = 0.5 * cap + 0.2 * pr;
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if (item_size as f64 + nxt) <= cap {
                score -= 10.0;
            }
        }
        if fitting_bins_count == 1 {
            score += 20.0; // don't open a new bin when an existing one is last chance
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 create "dead-space classes".
    // Small residues that are unlikely to host future items (1..9) are penalized;
    // residues that are multiples of 10 are rewarded (likely to fit future items).
    let r = post_residual % 10;
    if post_residual > 0 {
        if r == 0 {
            score -= 12.0; // perfectly harmonic residual
        } else if r <= 2 {
            score += 18.0; // nearly-full dead space, hard to reuse
        } else if r <= 5 {
            score += 8.0;
        } else {
            score -= 3.0;
        }
    }

    // Integer-division thresholds: can the next item fit exactly in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0; // lookahead item fits here: strong reward
            let slack = post_residual - next_item_size;
            if slack % 10 == 0 {
                score -= 10.0; // exact harmonic packing after lookahead
            }
        } else if next_item_size <= post_residual + 5 {
            score += 10.0; // near miss: this bin will be almost closed
        }
    } else {
        // Last item: prefer tightest closure
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when current bin would leave
    // a bad harmonic class or the item fits the empty bin with a clean residue.
    if bin_residual == bin_capacity {
        let new_post = bin_capacity - item_size;
        if new_post % 10 == 0 {
            score -= 8.0; // clean split favors fresh bin
        } else {
            score += 6.0;
        }
        // Early in stream, opening bins is cheap; late, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0 - 5.0;
    }

    // Mean-residual coupling: if this bin's residual is far below mean, it's tight — reward.
    let dev = mean_residual - post_residual as f64;
    score += 0.15 * dev;

    // Many open bins: encourage filling existing ones rather than spreading.
    score += 0.5 * open_bins_count as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical future items are wasted.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < item_size.min(bin_capacity / 2) {
        score += 12.0 + 0.25 * post_residual as f64;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 3 {
        score -= 8.0;
    }

    // Reward tight fits relative to residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // next item won't fit here: penalize leaving moderate gaps
            score += 0.10 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or residual is large.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * mean_residual / bin_capacity as f64;
        score += 30.0 - 8.0 * pressure;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin can serve the next item too
        }
    }

    // Open-bin pressure: mild penalty for accumulating many open bins.
    score += 0.5 * open_bins_count as f64;

    // Mean residual coupling: prefer bins far from mean (keeps diversity of gap sizes).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.5 * dev;

    // Late in stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let leftover2 = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - leftover2 / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize wasted lookahead space.
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
        // Perfect 2-item fill bonus.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Compare residual against mean residual of open bins.
    score += 0.35 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Penalize new-bin candidate slightly so it's only chosen when open bins are poor.
    if bin_residual == bin_capacity {
        score += 3.0 + 0.1 * open_bins_count as f64;
    }

    // Late in the stream: consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 3.0 * tightness * tightness * (item_size as f64);

    // Penalize dead space: small unusable leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    } else if post_residual == 0 {
        score -= 10.0; // perfect fill
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 5.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            // next item won't fit here; slightly penalize leaving big gaps
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit here would be terrible.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        let poor_fit = (item_size as f64) / (bin_capacity as f64) > 0.9;
        if poor_fit || fitting_bins_count == 0 {
            score -= 25.0;
        } else {
            score += 8.0 + 2.0 * crowded;
        }
    }

    // Time horizon: early in stream, be more selective (penalize waste);
    // late in stream, just fill bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 0.3 * post_residual as f64;

    // Mild preference for bins with below-mean residual (balance fragmentation).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Penalize scattering across many open bins when residuals are large.
    if open_bins_count > 4 {
        score += 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: penalize leftover space, with non-linear (quadratic/cubic) shaping
    let mut score = x * (1.0 + 1.5 * x * (1.0 - x));

    // Tight fit reward: subtract strongly when post_residual is small
    score -= 6.0 * (1.0 - x) * (1.0 - x) * (1.0 - x);

    // Dead-space zone: residuals just above the smallest possible next item are wasteful
    let dead = ((x - 0.35) * (x - 0.35)) * 4.0;
    score += dead;

    // Lookahead coupling: reward leaving exactly enough room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let match_term = (x - nx).abs();
        score -= 5.0 * (1.0 - match_term) * (1.0 - match_term) * (1.0 - progress);
        // penalize leaving a residual slightly below next item (unusable for it)
        if x < nx {
            score += 3.0 * (nx - x);
        }
    }

    // Stream progress: as stream advances, prefer tighter packing (amplify tight-fit reward)
    score -= 3.0 * progress * (1.0 - x);

    // Mean residual coupling: bins far from the mean residual get a smooth penalty
    let dev = (pr - mean_residual) / cap;
    score += 1.2 * dev * dev;

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a very tight schedule
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * progress;
        // opening a new bin is attractive if the item is large relative to capacity
        score -= 4.0 * (item_size as f64 / cap);
    }

    // Fragmentation penalty for many open bins
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual: residue modulo 10 ---
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let residue = (post_residual % 10) as f64;

    // Perfect fits (post_residual == 0) are golden: reward heavily.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize small nonzero residues: they create near-dead space.
        // residue 1..3 => almost unusable for items >= 10 in original spec,
        // but sizes 1..100 allowed => weight by residue size.
        score += residue * 1.5;

        // Harmonic bucket on post_residual via integer division thresholds.
        // Class 0: pr <= 10  -> dead zone, strong penalty
        // Class 1: pr <= 20  -> poor
        // Class 2: pr <= 35  -> marginal
        // Class 3: pr > 35   -> reusable
        if pr <= 10.0 {
            score += 25.0;
        } else if pr <= 20.0 {
            score += 10.0;
        } else if pr <= 35.0 {
            score += 3.0;
        } else {
            // Reward leaving large reusable space, mildly damped.
            score -= 2.0;
        }
    }

    // --- Lookahead coupling: does post_residual still fit next_item_size? ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt && pr > 0.0 {
            // Next item can still fit here: reward proportional to slack.
            score -= 6.0 + (pr - nxt) * 0.05;
        } else if pr > 0.0 && nxt - pr <= 5.0 {
            // Near-miss: post-residual just misses next item -> dead-ish space.
            score += 8.0;
        }
        // If next item exactly fills post_residual, huge reward.
        if next_item_size == post_residual {
            score -= 40.0;
        }
    }

    // --- Last-chance bonus: only fitting bin, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline cost plus scaling with how full the
        // fleet already is (many open bins => prefer packing into them).
        score = cap * 0.55 + open_bins_count as f64 * 2.0;
        // Late in the stream, opening bins is less attractive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // If current bin would leave a perfect fit for the next item,
        // never open a new bin.
        if next_item_size > 0 && post_residual == 0 {
            score += 100.0;
        }
        if fitting_bins_count == 1 {
            score += 50.0; // don't abandon the only fitting bin
        }
    }

    // --- Mild normalization toward mean residual state ---
    score -= (mean_residual - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit any
    // plausible future item (size >= 1, but practically small gaps below the
    // minimum item size of the stream) are wasted capacity. Penalize them hard.
    // A residual of 0 is perfect (exact fit) — reward it.
    if post_residual == 0 {
        score -= 25.0;
    } else {
        // Dead space: gap too small for the next item or generally tiny.
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
        // Very small unusable gaps (<= 10) are effectively dead space.
        if post_residual <= 10 {
            score += 20.0;
        } else if post_residual <= 20 {
            score += 8.0;
        }
    }

    // Mild best-fit pressure: prefer tighter fits overall.
    score += (post_residual as f64) / bin_capacity as f64 * 5.0;

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new bins
    // (penalize the empty-bin candidate implicitly via residual being max) and
    // encourage consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (2.0 + 3.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more heavily when open-bin count is high.
        score += 10.0 + pressure;
    } else {
        score -= pressure * 0.5;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Mean residual coupling: prefer bins whose residual is near the mean
    // (keeps the bin pool homogeneous and flexible).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: exact match of post_residual with next_item_size is ideal.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);

        // If post_residual can also fit the next item, mild bonus proportional to tightness.
        if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        }
    }

    // Reward tight fits relative to mean residual (small post_residual below mean is good).
    score -= 6.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Penalize creating tiny unusable dead space (< 10, or smaller than any plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bin would leave large waste
    // and many bins are already open.
    if bin_residual == bin_capacity {
        score += 15.0;
        if post_residual as f64 > mean_residual + 0.5 * bin_capacity as f64 {
            score -= 10.0;
        }
        if open_bins_count > 8 {
            score += 5.0 * (open_bins_count as f64 / 10.0);
        }
    }

    // Slight late-stream conservatism: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (post_residual near 0).
    let tightness = 1.0 - (post_residual as f64) / bin_capacity as f64;
    score -= 30.0 * tightness * tightness;

    // Penalize creating dead space that nothing can use later:
    // smallest possible item is 1, so residual < 1 is pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers are wasted capacity
    }

    // Lookahead: bonus if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect two-item chain
        } else if post_residual >= next_item_size {
            score -= 10.0 * (post_residual as f64 - next_item_size as f64).min(20.0) / 20.0;
        } else {
            // next item cannot fit here; mild penalty proportional to gap
            score += 5.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // When many bins are open, prefer filling existing ones over opening new.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when there are already many open bins
        // or when the mean residual is high (existing bins have plenty of room).
        score += 15.0
            + 2.0 * open_bins_count as f64
            + 0.5 * mean_residual.max(0.0);
        // Early in the stream, opening new bins is cheaper (future flexibility).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    } else {
        // Mild preference for bins with residual close to mean (balance workload).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Slight preference for fuller bins overall (best-fit flavor).
    score += 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: post-residual, mildly warped by progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Non-linear coupling: penalize large residuals more as stream progresses
    let norm_pr = pr / cap;
    score += cap * 0.8 * progress * norm_pr * norm_pr;

    // Reward tight fits (small post_residual) with smooth term
    score -= 12.0 * (-pr / 15.0).exp() * (1.0 + progress);

    // Penalize dead space in the awkward zone (smooth bump around mid residuals)
    score += 10.0 * (-(norm_pr - 0.5) * (norm_pr - 0.5) / 0.05).exp();

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: if next item fits into post_residual, reward; else penalize
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 8.0 * (1.0 - nx / cap) * (1.0 - progress * 0.5);
        } else {
            score += 6.0 * (nx / cap) * (0.5 + progress);
        }
    }

    // New-bin candidate: prefer keeping it closed early, allow opening later or when mean residual is low
    if bin_residual == bin_capacity {
        score = cap * (1.2 - 0.4 * progress) + 10.0 * (mean_residual / cap) * (1.0 - progress);
        if fitting_bins_count == 1 {
            score += 40.0; // strongly discourage abandoning last-chance bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual (integer division thresholds) ---
    // Class 0: perfect fit (0 residual) -> strong reward
    // Class 1..=10: tiny dead space -> mild reward
    // Larger classes: penalize proportionally to residual magnitude
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    } else {
        // modulo classes on residual: residuals divisible by 10 are "cleaner"
        let class = post_residual % 10;
        if class == 0 {
            score -= 3.0;
        } else if class > 5 {
            score += 2.0;
        }
        // non-linear penalty on large residual
        score += (pr / cap) * (pr / cap) * 12.0;
    }

    // --- Lookahead coupling: does post_residual accommodate next item? ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            // residual is "usable" for the next item: reward, more if snug
            let snug = (post_residual - next_item_size) as f64;
            score -= 6.0 - (snug / cap) * 6.0;
        } else {
            // residual too small for next item: penalize dead space
            score += 4.0;
            // harmonic threshold: residual below half of next item is nearly dead
            if (post_residual as f64) < nxt * 0.5 {
                score += 3.0;
            }
        }
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // --- Prefer filling bins when many are open (keep bin count down) ---
    let openness = (open_bins_count as f64) / (1.0 + (total_items as f64) * 0.05);
    score += openness * 2.0;

    // --- Mean residual coupling: placing in a bin below mean residual
    // concentrates waste in one place (good); above mean spreads it (bad) ---
    let mean_gap = pr - mean_residual;
    score += mean_gap * 0.3;

    // --- Fraction-of-capacity classes for the item itself ---
    let frac = item_size as f64 / cap;
    if frac > 0.8 {
        score -= 5.0; // big item: pack it anywhere it fits
    } else if frac < 0.2 {
        score += 1.0; // tiny item: avoid wasting a good residual on it
    }

    // --- Progress-based tuning: early on be greedy with new bins, later consolidate ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost, reduced late in the stream
        score = 40.0 + 20.0 * (1.0 - progress) - 5.0 * (1.0 - frac);
    } else {
        score -= 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Medium gaps (10..20) are only usable by small items; mild penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Reward tight fits (perfect or near-perfect packing).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize spreading when many bins are open.
    score += (open_bins_count as f64) * 1.5;

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }
    // If next item cannot fit in post residual but would fit elsewhere, slight penalty
    // only when the residual becomes dead space.
    if next_item_size > post_residual && post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean (tighter bins).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate: keep it neutral-to-slightly-attractive only when few bins fit.
    if bin_residual == bin_capacity {
        if fitting_bins_count <= 1 {
            score -= 5.0;
        } else {
            score += 20.0 + (open_bins_count as f64);
        }
    }

    // Early-stream exploration: slightly favor reusing bins early.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (wasted space below 10 is nearly dead anyway).
    if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 15 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: strongly favor bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // slack that still accommodates the next item is good; reward proportionally
            score -= 15.0 + 0.3 * (next_item_size as f64);
            // extra reward if the pair nearly fills the bin
            if post_residual - next_item_size <= 10 {
                score -= 20.0;
            }
        } else {
            // leftover can't fit next item: penalize dead space, scaled by how close it was
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
            if post_residual < 10 {
                score += 10.0; // tiny unusable sliver
            }
        }
    }

    // Compare against mean residual across open bins: prefer bins with less residual
    // (tighter bins get filled first), but only mildly.
    score += 0.2 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize so we only open new bins when open bins are truly bad.
    if bin_residual == bin_capacity {
        score += 55.0;
        // early in the stream, opening bins is cheaper
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
    }

    // Slight preference to fill bins with larger residual when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residual too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: reward if next item fits in the post residual (chain packing)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64) / 100.0;
        } else {
            // penalize residual that is unusable for the next item
            score += 3.0 * (1.0 - (post_residual as f64) / (next_item_size.max(1) as f64));
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Many open bins: prefer filling existing ones rather than opening new
    if open_bins_count > 2 {
        score -= 0.5 * (open_bins_count as f64).ln();
    }

    // Prefer bins whose residual is close to the mean residual (balance)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: early in stream, be pickier about tight fits; later, just fill anything
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 4.0 * tightness;
    score += progress * 0.02 * (post_residual as f64);

    // New-bin candidate: make it unattractive unless existing residuals are all poor
    if bin_residual == bin_capacity {
        let base = 55.0 - 20.0 * progress;
        // if no open bin fits well, opening new is fine
        score = base + (item_size as f64) * 0.1;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 5.0; // pair next two items in fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (0.5 + 0.5 * progress) - pr_norm * (1.0 - progress) * 0.5;
    score += 30.0 * poly;

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * (5.0 + 15.0 * progress);

    // Penalize dead space relative to mean residual across open bins
    score += 0.15 * (pr - mean_residual).abs();

    // Last-chance bonus: strongly favor this bin if it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 8.0 + 12.0 * progress;
    }

    // Lookahead: reward leaving space for the next item, penalize near-misses
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 3.0 * (1.0 - (nx / pr.max(1.0) - 0.5) * (nx / pr.max(1.0) - 0.5));
        } else {
            score += 2.0 * ((nx - pr) / cap);
        }
    }

    // Mild penalty for spreading across too many open bins early
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near multiples of small
    // denominators (cap/2, cap/4, cap/5) are "usable" dead space for common sizes.
    let pr = post_residual as u32;
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    let fifth = bin_capacity / 5;

    // Reward residuals that are harmonic anchors (0, 25, 20, 50, 75...)
    if pr == 0 {
        score -= 40.0; // perfect fit
    } else if pr % half == 0 {
        score -= 15.0;
    } else if pr % quarter == 0 {
        score -= 10.0;
    } else if pr % fifth == 0 {
        score -= 8.0;
    }

    // Integer-division thresholds on post_residual: small fragments are dead space
    if pr > 0 && pr < 10 {
        score += 25.0; // unusable sliver (min item is small)
    } else if pr < quarter {
        score += 12.0;
    }

    // Lookahead coupling: does post_residual exactly admit next_item_size?
    if next_item_size > 0 {
        if pr >= next_item_size && (pr % next_item_size.max(1) == 0) {
            score -= 12.0; // chain fit: next item fills remainder harmonically
        } else if pr > 0 && pr < next_item_size {
            score += 10.0; // next item won't fit here
        }
        // modulo-class match between post_residual and next item
        let class = |x: u32| x % quarter;
        if next_item_size > 0 && pr >= next_item_size && class(pr) == class(next_item_size) {
            score -= 6.0;
        }
    }

    // Capacity-fraction fill ratio: reward bins filled past 50%, penalize shallow fills
    let fill = 1.0 - post_residual as f64 / cap;
    if fill >= 0.5 {
        score -= 8.0 * fill;
    } else {
        score += 6.0 * (0.5 - fill);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 4 {
        score += 3.0; // plenty of alternatives, be picky
    }

    // New-bin candidate: only attractive when open bins are congested / tight
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = mean_residual / cap;
        if congestion < 0.15 || open_bins_count == 0 {
            score -= 30.0; // open bins nearly full: open a fresh one
        } else {
            score += 35.0 + 20.0 * congestion; // discourage new bin when fits exist
        }
        let _ = progress;
    }

    // Mild preference for tighter bins overall (relative to mean residual)
    score += 0.05 * (mean_residual - post_residual as f64);

    // Small tie-breaker by item size (place big items into tightest bins first)
    score += 0.02 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    // A residual gap is "dead" if it cannot fit even the smallest plausible item.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // perfect fill, huge reward relative to others
    } else if post_residual <= 10 {
        // small gap: mostly dead space, but keep ordering by size
        score += 25.0;
    } else if post_residual < item_size && post_residual < 40 {
        // gap too small for a typical follow-up item: strong dead-space penalty
        score += 15.0 + (40 - post_residual) as f64 * 0.5;
    }

    // Reward tight fits: small post_residual relative to item size is good.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 8.0 * tightness;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 40.0;
        } else if slack <= 10 {
            score -= 12.0;
        } else {
            score -= 3.0;
        }
    }
    // If next item cannot fit in this residual, mildly penalize (dead space likely).
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 4.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, avoid opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity, so it gets this penalty).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 5.0 * (open_bins_count as f64) + 10.0 * (1.0 - progress);
        // But if the item would leave a tiny gap in every existing bin, new bin is fine:
        if post_residual <= 10 && fitting_bins_count == 0 {
            score -= 35.0;
        }
    } else {
        // Existing bins: mildly favor bins with residuals close to mean (balanced packing).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward if next item fits into the post residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // good chaining: subtract proportional to how snugly next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 - slack.min(80.0);
            if post_residual == next_item_size {
                score -= 200.0; // perfect 2-item packing
            }
        } else {
            // dead space: post residual too small for next item
            let dead = (post_residual as f64) / bin_capacity as f64;
            score += 120.0 * dead;
        }
    } else {
        // last item: prefer minimal post residual
        score += 0.0;
    }

    // Relative residual vs mean: prefer filling below-average-residual (fuller) bins
    score += (mean_residual - post_residual as f64) * 0.5;

    // Last chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large relative to capacity
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let mut new_bin_penalty = 100.0 * (1.0 - fill_ratio);
        // if item is huge and next item large too, opening fresh bin is fine
        if item_size >= 70 {
            new_bin_penalty -= 60.0;
        }
        if open_bins_count == 0 {
            new_bin_penalty -= 200.0;
        }
        score += new_bin_penalty.max(-250.0);
    }

    // Slight preference for bins with tighter residual overall (best-fit flavor)
    score += (bin_residual as f64) * 0.1;

    // Late-stream tightening: as stream progresses, be more aggressive at filling bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 50.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus as post_residual approaches 0.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize dead space the next item cannot use.
        let dead = (post_residual - next_item_size.min(post_residual)) as f64;
        score += 6.0 * (dead / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless residuals
    // across open bins are all large (i.e., existing bins are nearly full).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_usable = mean_residual / bin_capacity as f64;
        // Penalize new bins more when many bins are open with usable space.
        score += 40.0 + 10.0 * (open_bins_count as f64).ln().max(0.0);
        // Late in the stream, be more conservative about opening bins.
        score += 20.0 * progress;
        // If mean residual is small, new bin is more acceptable: reduce penalty.
        score -= 45.0 * (1.0 - avg_usable).max(0.0);
        // If no open bin fits well (post_residual large for others), soften slightly.
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
    }

    // Global state coupling: prefer bins below mean residual (consolidating
    // leftover space into fewer bins keeps larger residuals concentrated).
    if bin_residual != bin_capacity {
        let diff = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 8.0 * diff;
    }

    // Penalize leaving residual below the smallest plausible item (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with progress
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let coupling = pr_norm * pr_norm * (0.5 + progress) + pr_norm * progress * progress;
    score += 40.0 * coupling;

    // Penalize dead space relative to capacity, amplified late in the stream
    let dead = pr / cap;
    score += dead * dead * (1.0 + 3.0 * progress) * 20.0;

    // Reward tight fits (small post_residual) with smooth inverse
    score -= 30.0 / (1.0 + pr);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: bonus if next item fits the post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - pr / cap);
    } else if next_item_size > 0 {
        score += 8.0;
    }

    // Mean residual alignment: prefer bins close to the mean residual
    let dev = (mean_residual - pr).abs();
    score += 5.0 * dev / cap;

    // Mild penalty for many open bins, encouraging consolidation
    score += (open_bins_count as f64) * 0.5 * (1.0 - progress);

    // New-bin candidate: make it costly early, cheaper late
    if bin_residual == bin_capacity {
        score += 60.0 * (1.0 - progress) + 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small dead space" classes are penalized less if leftover is usable.
    let pr = post_residual;
    let class = match pr {
        0 => 0.0,
        1..=10 => 1.0,
        11..=20 => 2.0,
        21..=35 => 3.0,
        36..=50 => 4.0,
        51..=70 => 5.0,
        _ => 6.0,
    };
    score += class * 4.0;

    // Perfect fit reward.
    if pr == 0 {
        score -= 120.0;
    }

    // Lookahead: strongly reward if the next item fits exactly in post_residual,
    // reward if it fits at all, penalize wasted potential.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 90.0;
        } else if next_item_size < pr {
            score -= 25.0 + (pr - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot use leftover: dead space penalty scaled by
            // how much of the bin's capacity is wasted.
            let waste_frac = pr as f64 / cap;
            score += 30.0 * waste_frac * (next_item_size - pr) as f64 / cap;
        }
    }

    // Last chance: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: make it attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = cap * 0.85;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // Many open bins: discourage new bin.
        score += open_bins_count as f64 * 2.0;
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= bin_capacity / 2 {
            score -= 25.0;
        }
    }

    // Prefer tighter bins generally (small residual before placement).
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    // Mean residual coupling: if this bin's residual is far below mean,
    // it is a "tight" bin worth filling.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Strict dead-space avoidance ----
    // Dead space in the "unusable small gap" zone is the worst outcome.
    // Items 1..100, so a residual below ~10 can only be filled by tiny items.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable sliver: hard penalty.
            score += 60.0;
        } else if post_residual < 25 {
            // Only fillable by small items: strong penalty scaled by rarity pressure.
            score += 25.0;
        } else {
            // Usable gap: mild penalty, decreasing as gap grows (more fillable).
            score -= 5.0;
        }
    } else {
        // Perfect fill: big reward.
        score -= 80.0;
    }

    // ---- Tightness reward: favor bins where the item fills most of the residual ----
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio <= 1.0 {
            score -= 30.0 * fill_ratio;
        } else {
            // Should not happen (bin fits item), but guard.
            score += 100.0;
        }
    }

    // ---- Lookahead coupling (k=2) ----
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This placement leaves room for the next item: reward proportionally.
            let next_fit_ratio = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * next_fit_ratio;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Dead space relative to the known next item: penalize.
            score += 15.0;
        }
    }

    // ---- Open-bin pressure ----
    // Many open bins: prefer consolidating into existing bins (penalize new bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; only attractive when
        // no open bin offers a decent fit.
        score += 40.0 + 8.0 * open_pressure + 20.0 * progress;
    } else {
        // Existing bin: slight bonus when open-bin count is high (consolidation).
        score -= 4.0 * open_pressure;
    }

    // ---- Last-chance bin: if this is the only fitting bin, strongly prefer it ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // ---- Mean residual context ----
    // If this bin's residual is far below mean (already tight), prefer filling it.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= 0.5 * diff.min(50.0);
    } else {
        score += 0.3 * (-diff).min(50.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

