    // Compare residual against mean residual: prefer bins with less residual
    // (denser bins) when fitting, but avoid dumping into nearly-empty bins
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate handling: keep it attractive only when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        if open_bins_count > 0 && fragmentation < 0.35 {
            score -= 50.0; // open bins are too full/fragmented, new bin is fine
        } else {
            score += 250.0; // prefer packing into existing bins
        }
    }

    // Late in the stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

