}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: waste after placement, normalized.
    let mut score = pr / cap;

    // Quadratic penalty on waste: dead space grows super-linearly in cost.
    let waste_frac = pr / cap;
    score += 0.8 * waste_frac * waste_frac;

    // Reward tight fits: coupling of post_residual with item size (small post_residual + large item is ideal).
    let tightness = 1.0 - (pr / cap);
    score -= 0.6 * tightness * tightness * (it / cap);

    // Non-linear stream-progress coupling: early on, tolerate waste (bins may combine later);
    // late in the stream, waste is nearly permanent, so penalize more.
    let late_factor = 0.5 + 1.5 * progress * progress;
    score *= late_factor;

    // Lookahead coupling: if the next item exactly (or nearly) fills post_residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        let match_bonus = (-gap / cap).exp(); // smooth exponential match kernel
        score -= 1.2 * match_bonus;
