        if pr > 0.0 && pr < 10.0 {
            score += 2.0 * (10.0 - pr) / 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 1.5;
    }

    // New-bin candidate (empty bin): only attractive when the item is large or all fits are poor.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 2.0 - 1.5 * (it / cap);
        score += new_bin_penalty;
        // If mean residual across open bins is small, open bins are nearly full anyway.
        score -= 0.3 * (mean_residual / cap);
    }

    // Mild penalty for proliferating open bins when residuals are large (fragmentation).
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

