    let quarter = bin_capacity / 4;
    let post_class = post_residual % quarter.max(1);
    let next_class = if next_item_size > 0 { next_item_size % quarter.max(1) } else { 0 };

    // Reward when post-residual class matches the next item's class (harmonic resonance)
    if next_item_size > 0 {
        if post_class == next_class {
            score -= 6.0;
        } else if post_class < next_class {
            score += (next_class - post_class) as f64 * 0.3;
