        score -= 3.0;
    }

    // Integer-division thresholds on post_residual (capacity fractions)
    let post_frac = post_residual as f64 / cap;
    if post_frac < 0.1 {
        score -= 4.0; // nearly-full bin is excellent
    } else if post_frac > 0.5 {
        score += 2.0; // leaving more than half empty is wasteful
    }

    // Last-chance bin pressure
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate: penalize unless current bins are poor fits
    if bin_residual == bin_capacity {
        let base = 12.0 + (open_bins_count as f64) * 0.4;
        score += base;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mean-residual coupling: prefer bins deviating from mean when mean is high
    if mean_residual > cap * 0.5 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.2;
    } else {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= dev * 0.1;
    }

    // Stream progression: tighten packing late in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
