    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 600.0; // chain fit
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leftover dead space relative to next size
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Penalize creating tiny unusable residuals (below min item size ~1..keep general)
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        // base penalty so open bins are preferred unless fit is terrible
        score += 250.0;
        // more attractive late in stream / with many open bins? keep neutral
        if next_item_size > 0 && item_size >= 60 {
            score -= 100.0; // big items: fresh bin is fine
        }
    }

    // Prefer bins with below-mean residual (tighter packing, keeps fat bins for big items)
    let mean_gap = mean_residual - bin_residual as f64;
    score -= 0.3 * mean_gap;

    // Slight preference for reusing bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 50.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual relative to capacity.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 40.0 * tightness;

    // Penalize leaving awkward dead space (nonzero but too small for smallest items).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; mild penalty for wasting the lookahead slot
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when fits are poor or
    // open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let poor_fits = fitting_bins_count == 0
            || (mean_residual < item_size as f64 * 1.2 && post_residual < 20.0);
        if poor_fits {
            score -= 20.0 + 10.0 * progress;
        } else {
            // discourage opening new bins when reasonable fits exist
            score += 30.0 + mean_residual * 0.2;
        }
    }

    // Mild preference for filling fuller bins as stream progresses.
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * fill_ratio;

    // Spread pressure: with many open bins, prefer bins below mean residual
    // (balance), with few open bins prefer above-mean bins.
    if open_bins_count > 1 {
        let diff = (bin_residual as f64) - mean_residual;
        if open_bins_count > 8 {
            score += 0.15 * diff;
        } else {
            score -= 0.10 * diff;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth non-linear coupling: waste penalty grows super-linearly with residual,
    // modulated by stream progress.
    let poly = norm_pr * norm_pr * (1.0 + progress);
    score += 30.0 * poly;

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    score -= 20.0 * (1.0 - norm_pr) * (0.5 + progress);

    // Last-chance bin bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: penalize if next item cannot use the remaining space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 10.0 + (nxt - pr);
        }
    }

    // Prefer bins with below-average residual (keeps big spaces available).
    score += 5.0 * (mean_residual - pr) / cap;

    // Mild penalty for spreading across too many bins early.
    score += (open_bins_count as f64).sqrt() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of post_residual: reward residues that are
    // "useful" for future items, penalize dead-space classes.
    // Class bins by residue bucket via integer division on capacity.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid_class = post_residual / 10; // harmonic class 0..=10
    let class_bonus = match resid_class {
        0 => 6.0,          // perfect fit -> strongly favor
        1 => 3.0,          // tiny leftover, near-perfect
        2 => 1.0,
        3 => -0.5,
        4 => -1.0,
        5 => -1.5,         // half-empty: flexible, mildly favored
        6 => -1.0,
        7 => -0.5,
        8 => 0.5,          // awkward large gap
        9 => 1.5,          // nearly empty again: wasteful
        _ => 0.0,
    };
    score -= class_bonus;

    // ---- Modulo-structure coupling: post_residual divisible by common
    // item granularities is more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0;
    }
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 1.0;
    }

    // ---- Lookahead: if next item fits exactly into post_residual,
    // big reward; if next item fits, mild reward; if not, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 8.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / cap);
        } else {
            score += 1.5;
        }
    }

    // ---- Last-chance bin: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0 + 0.02 * (item_size as f64);
    }

    // ---- New-bin candidate handling: empty bin should only win when
    // current fit is poor. Penalize opening a new bin by default.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Late in the stream, be even more reluctant to open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 6.0 * progress;
    }

    // ---- Tightness reward: fraction of bin consumed by this item.
    let fill = item_size as f64 / cap;
    score -= 4.0 * fill;

    // ---- Prefer bins whose residual is already below mean (consolidate
    // small leftovers into fewer bins).
    if (bin_residual as f64) < mean_residual && bin_residual < bin_capacity {
        score -= 1.0;
    } else if (bin_residual as f64) > mean_residual + 20.0 {
        score += 1.0;
    }

    // ---- Many open bins: encourage filling existing ones harder.
    if open_bins_count > 3 {
        score -= 0.15 * open_bins_count as f64 * (1.0 - post / cap);
    }

    // ---- Threshold penalty: leaving residual in dead zone (41..59)
    // often wastes capacity for typical item sizes.
    if post_residual >= 41 && post_residual <= 59 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible
    // item are pure waste. Penalize sharply as post_residual approaches zero
    // (tight fits are great) but also penalize mid-range dead zones.
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 40.0; // perfect fit
    } else if post_residual < 10 {
        // Unusable sliver below the minimum item size (1..100 interface, but
        // small gaps rarely reusable): strong penalty.
        score += (10.0 - pr) * 6.0;
    } else if post_residual <= next_item_size as f64 && next_item_size > 0 {
        // Gap exactly reusable by the lookahead item: reward.
        score -= 25.0;
    } else {
        // Dead zone: gap too small for the next item but not tiny either.
        // Penalize proportionally to how "stranded" the gap is.
        if next_item_size > 0 && (post_residual as u32) < next_item_size {
            score += pr * 0.8;
        }
        // General mild penalty for leaving medium gaps.
        score += pr * 0.15;
    }

    // Tightness reward: fraction of the bin's residual consumed.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 20.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into a
    // new bin; with few open bins, tolerate new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins count.
        score = 100.0 + (open_bins_count as f64) * 4.0 + progress * 20.0;
        // If no open bin fits at all, new bin is the only option: make it cheap.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    } else {
        // Using an existing bin relieves open-bin pressure slightly.
        score -= (open_bins_count as f64).min(10.0) * 0.5;
    }

    // Mean residual coupling: prefer bins whose residual is near the mean
    // (balanced packing), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: next item fits with small leftover
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - slack * 0.8;
    }
    // Next item cannot fit: dead space penalty grows with leftover
    else if next_item_size > 0 {
        score += (post_residual as f64).powf(1.3) * 0.15;
    }

    // Reward tight fits relative to capacity
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= tightness * 25.0;

    // Compare against mean residual across open bins: placing into a bin
    // below mean residual balances the pool
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Penalize the new-bin candidate more when open bins can still serve
    if bin_residual == bin_capacity {
        score += 15.0 + 5.0 * (open_bins_count as f64).sqrt();
        if next_item_size > 0 && item_size == next_item_size {
            score -= 10.0;
        }
    }

    // Early stream: be slightly more conservative with open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: squared post-residual penalizes large dead space more.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: reward if next item can fit into the resulting residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + next_item_size as f64 * 0.3;
    }
    // Penalize if residual becomes too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer fuller bins over emptier ones when many bins are open.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0 * (open_bins_count as f64).ln().max(1.0);

    // Global pressure: when mean residual is high, avoid adding fragmentation.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Time horizon: early in stream, be more willing to open new bins;
    // late in stream, consolidate tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early, expensive late.
        score = 60.0 + progress * 40.0 - fill_ratio * 0.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        if fitting_bins_count <= 1 {
            score -= 55.0; // if no real alternative, new bin is fine
        }
    } else if progress > 0.8 {
        score += post_residual as f64 * 0.5; // late phase: minimize residual aggressively
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit bonus (strong)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward small post_residual non-linearly (waste avoidance)
    let pr = post_residual as f64;
    score -= (bin_capacity as f64 - pr).max(0.0) / bin_capacity as f64 * 20.0;

    // Penalize dead space: residual too small for future items (min size 1)
    let dead = (pr / bin_capacity as f64).powi(3);
    score += dead * 40.0;

    // Lookahead: penalize if post_residual cannot fit next item but could have
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            // residual still useful for next item -> mild reward
            score -= 5.0 * (1.0 - pr / bin_capacity as f64);
        } else if bin_residual as f64 >= nx {
            // we destroyed a fit for the next item -> penalty
            score += 15.0 + 10.0 * progress;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0 + 40.0 * progress;
    }

    // New-bin candidate: penalize early, allow when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        score += 30.0 - 50.0 * fragmentation * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 25.0; // discourage bypassing existing fits
        }
    }

    // Stream-progress coupling: later in stream, prefer tighter residual packing
    score -= progress * (bin_capacity as f64 - pr) * 0.5;

    // Coupling with mean residual: prefer bins deviating from mean toward emptier side
    score += 0.3 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo-10 classes define
    // "usable" leftover buckets. Residuals in low classes (0..=5 mod 10)
    // are near-dead space for items of size >= 10.
    let pr = post_residual as u32;
    let cls = pr % 10;
    let dead = if pr == 0 {
        0.0 // perfect fit: best possible
    } else if cls == 0 {
        2.0 // multiple of 10: still reusable
    } else if cls <= 5 {
        8.0 + (6 - cls) as f64 * 2.0 // tiny unusable slivers
    } else {
        3.0 // moderately reusable
    };
    score += dead * (1.0 + (pr as f64 / cap).powi(2));

    // Perfect / near-perfit rewards
    if pr == 0 {
        score -= 40.0;
    } else if pr <= 5 {
        score += 15.0; // guaranteed dead space for min item size
    }

    // Lookahead pairing: reward when next item fits exactly in post residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size < pr {
            let nxt = next_item_size as f64;
            let fill = nxt / pr as f64;
            score -= 25.0 * fill * fill;
            // harmonic class match: next item leaves multiple-of-10 residue
            let npr = pr - next_item_size;
            if npr % 10 == 0 {
                score -= 12.0;
            }
        } else {
            // next item cannot use this bin's leftover: penalize big leftovers
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when current fit is poor.
    if bin_residual == bin_capacity {
        // baseline: new bin has full capacity; make it competitive but
        // biased against when a decent fit exists in an open bin.
        score = cap * 0.62
            + if pr == 0 { 0.0 } else { 10.0 }
            + mean_residual * 0.15
            - (open_bins_count as f64).sqrt() * 2.0;
        if next_item_size >= bin_capacity as u32 - item_size && next_item_size > 0 {
            score -= 8.0; // next item is large, fresh bin useful
        }
    }

    // Tight fits (small post residual fraction) are generally good
    let tight = 1.0 - (pr as f64 / cap);
    score -= 10.0 * tight * tight;

    // Mild pressure to consolidate when many bins are open
    score += mean_residual * 0.05 - (open_bins_count as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item can ever use
    // (below the minimum plausible item size) are pure waste.
    if post_residual < 10 {
        score += 60.0; // tiny unusable sliver -> strong penalty
    } else if post_residual < 20 {
        score += 25.0; // very likely dead space
    } else if post_residual < 35 {
        score += 8.0;  // moderately risky gap
    } else {
        // usable gap: reward proportional to how well it matches a
        // plausible future item (tight but usable fits are good)
        score -= 10.0;
    }

    // Reward tight fits (small but usable post_residual)
    if post_residual >= 10 && post_residual <= 40 {
        score -= 2.5 * (40.0 - post_residual as f64) / 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a bin is cheap when few bins are
    // open, expensive when many are open (open_bins_count pressure).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 30.0 + 4.0 * open_bins_count as f64 + 20.0 * progress;
        // If the next item would fit in the residual created here, new bin is attractive
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 18.0;
        }
        if fitting_bins_count == 1 {
            score += 55.0; // don't abandon the only fitting bin
        }
    }

    // Lookahead: if the next item fits exactly in the post_residual,
    // reward this placement strongly (pairing effect).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 15.0;
        } else if post_residual < next_item_size && post_residual >= 10 {
            score += 5.0; // kills the bin for the next item
        }
    }

    // Slight preference for filling bins with large residuals already
    // (consolidate waste into few bins).
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward residuals that exactly match the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            // leftover after both items: penalize large dead space
            let after_two = post_residual - next_item_size;
            score -= 60.0 - (after_two as f64).min(60.0);
        } else {
            // next item can't follow here: penalize if residual is small but wasted
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Small residual is generally good (tight packing)
    if post_residual > 0 {
        score -= 40.0 / post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when current fit is poor
    if bin_residual == bin_capacity {
        // penalize new bin mildly; aggressive lookahead may still override
        score += 150.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 50.0;
        }
    }

    // Prefer bins tighter than the mean residual
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Prefer fuller bins early in the stream
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (best-fit core)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if the next item fits exactly into the post residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / 100.0);
        } else {
            // wasted post residual relative to next item
            score += 6.0 * (1.0 - (post_residual as f64 / bin_residual.max(1) as f64));
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: prefer open bins generally, but allow opening
    // a fresh bin when current residuals are fragmented (high mean residual spread)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Opening a new bin is attractive late in the stream or when mean residual is large
        let open_bias = 15.0 + 25.0 * progress + 0.15 * mean_residual - 0.1 * fragmentation;
        score += open_bias;
        // Never open a new bin for a tiny item early on
        if item_size < 30 && progress < 0.5 {
            score += 40.0;
        }
    } else {
        // Mild penalty for very full bins to keep some flexibility
        if post_residual < 5 {
            score += 3.0;
        }
        // Reward using bins whose residual deviates from mean (consolidation)
        score -= 0.05 * (mean_residual - bin_residual as f64).abs();
    }

    // Scale by number of open bins: many open bins -> encourage filling existing ones
    score -= 0.5 * open_bins_count as f64 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let base = pr as f64;

    // Smooth non-linear coupling: dead-space penalty grows quadratically for small residuals
    let dead = (1.0 - norm_pr).powi(2) * cap * 0.5;

    // Progress-scaled tightening: later in stream, prefer tighter fits
    let tight = norm_pr * (1.0 + 2.0 * progress * progress);

    // Lookahead: reward if next item fits the post residual (smooth gaussian-ish coupling)
    let look = if next_item_size > 0 {
        let d = (pr - next_item_size as f64) / cap;
        -8.0 * (-40.0 * d * d).exp()
    } else {
        0.0
    };

    // Last-chance bonus: only fitting bin -> strong reward
    let last = if fitting_bins_count == 1 { -6.0 } else { 0.0 };

    // Divergence from mean residual: smooth cubic penalty
    let dev = ((pr - mean_residual) / cap).powi(3) * 4.0;

    // Slight preference for consolidating when many bins open
    let crowd = open_bins_count as f64 * 0.02 * norm_pr;

    base + dead + tight + look + last + dev - crowd
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity fractions
    let pr = post_residual;
    let class = pr / 10; // decade class 0..10
    // Reward small post residuals strongly (perfect fits)
    match class {
        0 => score -= 40.0,                       // pr in 0..9: near-perfect fit
        1 => score -= 18.0,                       // small gap
        2 => score -= 6.0,
        3 => score -= 1.0,
        4 => score += 2.0,                        // awkward mid gap
        5 => score += 5.0,
        6 => score += 3.0,
        7 => score -= 2.0,                        // gap ~70 leaves room for small items
        8 => score -= 4.0,
        9 => score -= 1.0,
        _ => score -= 3.0,                        // near-full leftover class edge
    }

    // Fine modulo structure: reward post_residual divisible by common item granularities
    if pr > 0 {
        if pr % 10 == 0 { score -= 8.0; }
        else if pr % 5 == 0 { score -= 4.0; }
        if pr % 20 == 0 { score -= 5.0; }
    } else {
        score -= 60.0; // exact fill is best possible
    }

    // Lookahead coupling: does the leftover space fit the next item?
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (pr as u64) >= (next_item_size as u64) {
            // leftover usable by next item: reward proportionally
            score -= 10.0 + 12.0 * (1.0 - ((pr - next_item_size) as f64) / cap);
        } else {
            // leftover dead for next item: penalize large dead gaps
            score += 6.0 + 0.15 * (pr as f64);
        }
        // Harmonic pairing: item+next sums near capacity are great
        let pair = item_size as u64 + next_item_size as u64;
        if pair <= bin_capacity as u64 && (bin_capacity as u64 - pair) < 15 {
            score -= 9.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer fuller bins overall: tie-break toward below-mean residual
    score += 0.3 * (mean_residual - (post_residual as f64)).abs().signum()
        * (mean_residual - post_residual as f64);

    // Progress scaling: later in stream, be greedier about tight fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.2 * progress;

    // New-bin candidate: make empty bins unattractive unless no decent fit exists
    if bin_residual == bin_capacity {
        score += 55.0 + 0.25 * (open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: the smaller the post_residual, the better (beyond baseline).
    score -= 40.0 * (-post_residual as f64 / 20.0).exp();

    // Strict dead-space avoidance: post_residuals in [1, 12] are nearly unusable
    // dead space (item sizes >= 10 originally, but sizes 1..100 possible now).
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0 * (1.0 - post_residual as f64 / 12.0);
    }

    // Perfect fill is excellent.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize waste proportional to bin capacity used ratio.
    score += 0.3 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward heavily.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / post_residual as f64);
        } else {
            // Next item cannot use this residual anyway; slight penalty for large residual.
            score += 2.0;
        }
    }

    // Open-bins pressure: with many open bins, discourage spreading; prefer new bin
    // when residual is already large and fragmented.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 * (1.0 - progress) * 0.5;
    if mean_residual > 30.0 && post_residual > mean_residual {
        score += bin_pressure;
    }

    // New-bin candidate handling: an empty bin is a fresh resource; make it attractive
    // when current bin would leave big dead space or bins are fragmented.
    if bin_residual == bin_capacity {
        let dead_space_if_placed_here = post_residual;
        if dead_space_if_placed_here > 40.0 {
            score -= 20.0; // prefer fresh bin over creating huge residual
        }
        // Otherwise keep new bin slightly worse than a good existing fit.
        score += 8.0 - bin_pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (dead space minimization).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    }

    // Aggressive 2-step lookahead: reward when the next item exactly fills
    // the post residual, or fits snugly into it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0; // perfect chain: next item closes this bin exactly
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 5.0 {
                score -= 80.0;
            } else {
                score -= 30.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            // Next item cannot use the residual at all -> residual likely dead space.
            let unusable = (next_item_size - post_residual) as f64;
            score += 0.5 * unusable.min(50.0);
        }
    }

    // Compare against mean residual: placing into a bin whose residual is
    // below average preserves larger residuals elsewhere (best-fit bias).
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 5.0 * ((post_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity or few bins fit the item.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / fitting_bins_count as f64 };
        // Prefer new bin when item is big and no good existing option exists.
        score = bin_capacity as f64 - 100.0 * frac * pressure - 20.0 * pressure;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 40.0; // fresh bin can also host the next item
        }
    }

    // Slight stream-position regularization: early on, be a bit more willing
    // to open bins (uncertain future); late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * (1.0 - progress);

    // Mild penalty for proliferation of open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportional to how well the item fills the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize dead space that no future item (size <= 80) can use efficiently.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers
    } else if post_residual >= 10 && post_residual <= 80 {
        score -= 8.0; // usable residual is good
    }

    // Lookahead coupling: if the next item fits the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.3 * next_item_size as f64;
        } else {
            score += 6.0 * (next_item_size as f64 - post_residual as f64).min(40.0) / 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: discourage opening new ones; favor consolidating.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= (open_bins_count as f64).ln() * 3.0;
    }

    // Time horizon: early in stream, be more liberal with new bins (future flexibility);
    // late in stream, squeeze existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 12.0 * (1.0 - progress);
    } else {
        score -= 10.0 * progress * (1.0 - fill_ratio);
    }

    // Global state: high mean residual means slack exists; be pickier about placement.
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: how well the item fills the bin (1.0 = perfect fit)
    let tightness = 1.0 - (post_residual as f64 / cap);
    let tightness_sq = tightness * tightness;

    // Reward tight fits, amplified by stream progress (late items prefer compacting)
    score -= 12.0 * tightness_sq * (0.5 + progress);

    // Penalize dead space that no typical item can use: post_residual below smallest
    // useful size becomes waste; scale penalty non-linearly
    let waste = if post_residual < item_size { post_residual as f64 } else { 0.0 };
    score += 2.0 * (waste * waste) / cap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 6.0 * progress;
    }

    // Lookahead: reward leaving room for the next item (smooth coupling)
    if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap >= 0.0 {
            let fit_next = 1.0 - gap / cap;
            score -= 5.0 * fit_next * fit_next;
        } else {
            score += 1.5 * (-gap / cap);
        }
    }

    // New-bin candidate: prefer keeping it closed early; allow opening when
    // open bins are nearly full (mean residual low) or late in the stream
    if bin_residual == bin_capacity {
        let mean_pressure = 1.0 - (mean_residual / cap).max(0.0).min(1.0);
        let openness = (1.0 - progress) * 0.5 + mean_pressure * 0.5;
        score += 15.0 * openness + 0.5 * open_bins_count as f64;
    }

    // Mild penalty for spreading across many bins when residuals are large
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Harmonic class of the post residual: quantize into capacity/10 buckets.
    let class = (post_residual / 10).min(10) as f64;
    score += 3.0 * (class * (class - 1.0) as f64) * 0.1; // super-linear penalty on large residuals

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Reward residuals that are harmonic multiples (divisible by small units).
        if post_residual % 10 == 0 { score -= 6.0; }
        else if post_residual % 5 == 0 { score -= 3.0; }
        // Penalize odd, awkward residuals.
        if post_residual % 2 == 1 { score += 2.0; }
    }

    // Dead space: residual too small for the smallest plausible next item.
    if post_residual > 0 && next_item_size > 0 {
        if next_item_size > post_residual {
            score += 8.0; // cannot host lookahead item -> likely dead space
            score += 0.05 * (next_item_size - post_residual) as f64;
        } else {
            // If this bin can host the next item, reward leaving exactly a good remainder.
            let gap = post_residual - next_item_size;
            if gap == 0 { score -= 12.0; }
            else if gap <= 10 { score -= 6.0; }
            else { score += 0.03 * gap as f64; }
        }
    } else if post_residual > 0 && next_item_size == 0 {
        score += 2.0; // last item: mildly prefer fuller bins
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer bins below mean residual (fill emptier bins first keeps tight bins for tight items).
    score += 0.5 * (mean_residual - pr).max(-30.0).min(30.0);

    // Progress-based modulation: later in stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - pr / cap);

    // Many open bins: discourage spreading into new partials.
    if open_bins_count > 4 {
        score += 0.02 * open_bins_count as f64 * (pr / cap);
    }

    // New-bin candidate: only attractive when current item is large and no tight option exists.
    if bin_residual == bin_capacity {
        if item_size >= 70 {
            score -= 5.0;
        } else if next_item_size == 0 || post_residual < 15 {
            score -= 2.0;
        } else {
            score += 20.0; // prefer existing bins for small/medium items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
