    // New-bin candidate handling: only attractive when open bins are crowded
    // or this bin would leave a large, flexible residual.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, scaled by open-bin pressure.
        score += 300.0 + 40.0 * open_bins_count as f64;
        // A fresh bin is more attractive early in the stream and when
        // existing residuals are small (crowded bins).
        score -= 200.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        score -= mean_residual * 2.0;
        if item_size > 60 {
            // Large items fragment bins; prefer a fresh bin for them.
            score -= 150.0;
        }
    }

    // Open-bins pressure: mildly discourage stuffing already-tight bins
    // (keep some spread), scaled by how far below mean residual this bin is.
    score += 0.3 * (mean_residual - bin_residual as f64).abs();

    // Prefer fuller bins generally (small residual left = good packing).
    score += 0.1 * (bin_capacity as f64 - bin_residual as f64).max(0.0) * -1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
