    else if next_item_size > 0 && bin_residual >= next_item_size && post_residual < next_item_size {
        let waste = (post_residual as f64).max(1.0);
        score += 10.0 * (1.0 - waste / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many fitting bins: mild penalty to encourage consolidation elsewhere
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0);
    }

    // Prefer bins with residuals below the mean (fill fuller bins first)
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 12.0 * dev;

    // Time horizon: early in stream, be more selective (penalize loose fits);
    // late in stream, accept placements more readily to close bins out
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let horizon = 1.0 - 0.5 * progress;
    score *= 0.6 + 0.4 * horizon;

    // New-bin candidate: acceptable early (good for future flexibility),
    // discouraged late when we should exhaust open bins
    if bin_residual == bin_capacity {
        score = 55.0 * (1.0 - progress) + 45.0 + 8.0 * (open_bins_count as f64).sqrt();
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 6.0; // fresh bin keeps room for a follow-up
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let prn = pr / bin_capacity as f64; // normalized post residual in [0,1]
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;

    // Dead-space penalty: small non-zero post residual is bad; smooth polynomial.
    let dead = (1.0 - prn) * prn * (1.0 - prn); // peaks at prn=1/3
    score += 18.0 * dead * (0.4 + 0.6 * progress);

    // Perfect fit reward, smoothly scaled by progress.
    if post_residual == 0 {
        score -= 12.0 + 10.0 * progress;
    } else {
        score -= 6.0 * (1.0 - prn) * (1.0 + progress);
    }

    // Lookahead coupling: reward if next item fits the post residual (smoothly).
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_frac = next_item_size as f64 / post_residual as f64;
        score -= 8.0 * fit_frac * (1.0 - fit_frac + 0.25) * (0.5 + 0.5 * progress);
    } else if next_item_size > post_residual {
        score += 2.0 * progress * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bin bonus: strongly prefer using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild preference for bins tighter than average (fill fuller bins first).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Slight preference to reuse bins as open-bin count grows (contain sprawl).
    score += (open_bins_count as f64).ln().max(0.0) * 0.3 * prn;

    // New-bin candidate: penalize mildly early, allow late when residuals are poor.
    if bin_residual == bin_capacity {
        let avg_bad = mean_residual / bin_capacity as f64;
        score += 6.0 - 8.0 * progress * (1.0 - avg_bad);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as u32;
    let class = pr % (bin_capacity / 10).max(1); // decade class within capacity
    score -= class as f64 * 1.5;                 // reward small class values (tighter fills)

    // Integer division thresholds on post_residual: "dead space" bands.
    if pr <= bin_capacity / 10 {
        score -= 12.0; // near-perfect fit
    } else if pr <= bin_capacity / 4 {
        score -= 5.0;
    } else if pr > bin_capacity / 2 {
        score += 3.0; // more than half wasted after placement
    }

    // Harmonic coupling with lookahead item (k=2): if next item fits post residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 8.0 + (pr - next_item_size) as f64 * 0.05;
        } else {
            // penalize leaving residual that next item almost fits but not quite
            let gap = (next_item_size - pr) as f64;
            if gap < (bin_capacity / 10) as f64 {
                score += gap * 0.6;
            }
        }
        // harmonic class match: residual divisible into next item chunks
        if next_item_size > 0 && pr % next_item_size.max(1) == 0 {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-high unless current placement is terrible.
    if bin_residual == bin_capacity {
        score += 6.0;
        if post_residual > bin_capacity / 2 {
            score += 4.0;
        }
    }

    // Stream progression: early on, be conservative about fragmenting bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * post_residual as f64 * 0.1;

    // Mean residual coupling: penalize making this bin diverge from the mean residual.
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    // Many open bins: prefer consolidation, penalize adding to scattered space.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Gaps below ~15 are nearly unusable for typical items (sizes 1..100 unknown,
    // but tiny slivers waste capacity almost surely).
    if post_residual > 0 && post_residual < 15 {
        score += 60.0 * (1.0 - post_residual as f64 / 15.0);
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward high fill ratio (low post_residual relative to capacity) nonlinearly.
    let fill = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 10.0 * fill * fill;

    // Last-chance bin: placing here avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Open-bins pressure: many open bins -> prefer consolidation into existing bins,
    // penalize opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += pressure * 4.0;

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e., when mean residual is small relative to item size or the fit here is bad.
    if bin_residual == bin_capacity {
        // Baseline new-bin score; make it worse than a decent existing-bin fit.
        score += 12.0 + pressure * 2.0;
        if post_residual as f64 > mean_residual * 1.5 {
            score -= 10.0; // large empty bin can absorb future items
        }
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: new bin is right choice
        }
    }

    // Lookahead: if next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // dead space confirmed: next item cannot use it
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fits the post residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 150.0 - (post_residual - next_item_size) as f64;
        }
    }

    // Penalize creating dead space below minimum item size
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 80.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is poor
    if bin_residual == bin_capacity {
        let waste = (bin_residual - item_size) as f64;
        score += 200.0 + waste;
        if fitting_bins_count > 0 && post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
            score += 300.0; // existing bin leads to a chain: keep it
        }
    }

    // Prefer bins already tighter than average
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Late in the stream, consolidation matters more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Tightness: relative waste
        let tightness = post_residual as f64 / bin_capacity as f64;
        score += tightness * 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: does the next item fit in the post residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Good: next item can still go here; reward proportional fit quality
            let gap = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 30.0; // chain perfect fit
            }
        } else {
            // Next item won't fit here; penalize leaving medium dead space
            let dead = post_residual as f64;
            if dead > 0.0 && dead < next_item_size as f64 {
                score += 0.35 * dead;
            }
        }
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Prefer new bin early in stream or when open bins are fragmented / poor fits
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_frac = mean_residual / bin_capacity as f64;
        // Penalize new bin when existing bins have healthy residuals and few bins open
        let mut new_bin_score = 15.0 + progress * 20.0;
        if mean_frac > 0.35 {
            new_bin_score += 25.0 * (mean_frac - 0.35);
        }
        if open_bins_count == 0 {
            new_bin_score -= 100.0; // must open a bin
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 80.0; // no alternative
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_score -= 10.0; // fresh bin fits next item too
        }
        score = new_bin_score;
    }

    // Mild penalty for placing into bins with very large residual when many bins open
    // (encourages filling fragmented bins first)
    if bin_residual < bin_capacity {
        let res_frac = bin_residual as f64 / bin_capacity as f64;
        if res_frac > 0.5 && open_bins_count > 3 {
            score += 5.0 * (res_frac - 0.5);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Smooth polynomial coupling: dead space penalty grows super-linearly with progress.
    let x = post / cap;
    score += (x * x) * cap * (0.5 + 1.5 * progress);

    // Reward tight fits (small post_residual) more strongly later in the stream.
    score -= item_size as f64 * (0.2 + 0.8 * progress) * (1.0 - x);

    // Lookahead coupling: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 8.0 + 6.0 * progress;
    } else if next_item_size > 0 {
        // Penalize leaving residual that wastes capacity for the known next item.
        score += (post - next_item_size as f64).min(post) * 0.15 * (1.0 + progress);
    }

    // Last-chance bonus: sole fitting bin should be preferred over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 10.0 * progress;
    }

    // New-bin candidate: make empty bin mildly unattractive unless residuals are high.
    if bin_residual == bin_capacity {
        score += 6.0 + 20.0 * (1.0 - progress) + (mean_residual / cap).max(0.0) * 10.0;
    } else {
        // Slight preference for bins below mean residual (consolidating waste).
        score += (mean_residual - bin_residual as f64) * 0.05;
    }

    // Mild open-bin pressure to avoid bin sprawl early.
    score += open_bins_count as f64 * 0.02 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual classes mod 10 (since sizes 1..100, capacity 100)
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect-fit reward: post_residual exactly zero
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic class penalty: residuals that are multiples of 5 or 10 are
        // more likely reusable by future items drawn from wide distributions.
        let cls = post_residual % 10;
        if cls == 0 {
            score -= 40.0; // residual in {10,20,...} — highly reusable class
        } else if cls == 5 {
            score -= 20.0; // half-class — moderately reusable
        } else {
            score += (5 - cls.min(5 - cls).abs()) as f64 * 3.0; // odd classes penalized
        }
    }

    // Dead-space threshold via integer division: residual < 10 is nearly dead
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead coupling: reward residuals that exactly (or closely) fit next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 60.0 - (slack as f64).min(60.0) * 0.5;
            // harmonic match: next item divides residual evenly
            if post_residual % next_item_size == 0 && next_item_size > 0 {
                score -= 25.0;
            }
        } else {
            // next item won't fit here — penalize small leftovers more
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate handling: brand-new empty bin
    if bin_residual == bin_capacity {
        // Prefer a new bin when existing residuals are large (wasteful fits)
        // and item is large; otherwise penalize opening bins excessively.
        let openness = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / cap;
        if item_frac > 0.6 || mean_residual < item_size as f64 * 0.5 {
            score -= 80.0 * item_frac + 20.0 * openness;
        } else {
            score += 120.0 + 50.0 * (1.0 - openness);
        }
    }

    // Mild pressure toward tight bins when many bins are open
    score += (open_bins_count as f64).ln1p() * pr * 0.05;
    // Small nudge comparing residual to mean residual (prefer below-mean usage)
    score += (pr - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity.max(1) as f64;
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    if post_residual == 0 {
        // Perfect fit: strongly reward sealing the bin exactly.
        score -= 40.0;
    } else if post_residual < 10 {
        // Tiny unusable gap: penalize proportionally to how dead it is.
        score += 24.0 + (10.0 - post_residual as f64) * 2.0;
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt == pr {
            score -= 28.0; // next item seals this bin perfectly: chain placement
        } else if nxt <= pr {
            score -= 6.0; // next item also fits here: good residual utility
        }
    }

    let progress = step_index as f64 / (total_items.max(1) as f64);
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // --- Open-bins pressure: discourage proliferation ---
        score += 5.5 * open_bins_count as f64;
        score += 14.0 * (mean_residual / cap).clamp(0.0, 1.0);
        score += 8.0 * progress; // late in the stream, be conservative about new bins
        if open_bins_count == 0 {
            score -= 12.0; // nothing open yet: spreading is fine
        }
    } else {
        // --- Last-chance bonus: only fitting open bin before a new bin opens ---
        if fitting_bins_count == 1 {
            let usable = (post_residual as f64 / 20.0).min(1.0);
            score -= 6.0 + 16.0 * usable; // bigger bonus when leftover stays usable
        }
        // Consolidation: mildly favor bins tighter than the current mean residual.
        score += 0.05 * (bin_residual as f64 - mean_residual).clamp(-30.0, 30.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits, but penalize leftover slack after that hypothetical placement
            let slack_after_next = post_residual - next_item_size;
            score -= 100.0;
            score += slack_after_next as f64 * 0.5;
        } else {
            // next item won't fit here; penalize large dead space
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Penalize residual far below mean residual (wasteful bin selection)
    let mean_gap = mean_residual - post_residual as f64;
    if mean_gap > 0.0 {
        score += mean_gap * 0.2;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // New-bin candidate handling: only prefer fresh bin when nothing fits well
    if bin_residual == bin_capacity {
        // neutral-ish baseline plus penalty scaled by how many bins could fit item
        score += 50.0 + 20.0 * fitting_bins_count as f64;
    }

    // Late in stream, tighten packing (avoid opening bins unnecessarily)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already favored by base term.

    // Penalize large dead space relative to capacity with a nonlinear penalty.
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * dead_frac * dead_frac;

    // Lookahead: if the next item fits exactly into post_residual, strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item still fits, mild reward proportional to how well it fits
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize leaving awkward medium residuals
            let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
            if post_residual < next_item_size && post_residual < 10 {
                score -= 5.0; // tiny residual is fine (near-full bin)
            } else {
                score += 8.0 * (1.0 - gap / bin_capacity as f64);
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more so early in the stream and when few bins open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 + 25.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
    }

    // Global state coupling: prefer filling bins when many bins are open (reduce spread).
    if open_bins_count > 4 && bin_residual < bin_capacity {
        let spread = (mean_residual - bin_residual as f64).abs();
        score += 0.3 * spread;
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer bins whose residual is close to the mean residual (keep residuals uniform).
    if bin_residual < bin_capacity {
        score += 0.1 * (mean_residual - post_residual as f64).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: wasted space after placement
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Late in the stream, we tolerate large residuals less (dead space is costlier
    // since fewer chances remain to fill it).
    let pr_norm = pr / cap;
    let coupling = pr_norm * pr_norm * (1.0 - progress) * (progress * progress);
    score += 40.0 * coupling * cap;

    // Reward tight fits: quadratic bonus shrinking with post_residual
    let tight = (1.0 - pr_norm).max(0.0);
    score -= 25.0 * tight * tight * tight;

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - (pr - next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        // next item won't fit here: penalize leaving awkward residual
        score += 6.0 * pr_norm;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer bins with below-mean residual (more compact bins first)
    let mean_r = mean_residual / cap;
    score += 10.0 * (pr_norm - mean_r) * (pr_norm - mean_r);

    // New-bin candidate: make it attractive only when current open bins are crowded
    if bin_residual == bin_capacity {
        let crowd = (open_bins_count as f64).ln().max(1.0);
        score = 20.0 + crowd * 3.0 + 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely desirable.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class analysis (modulo arithmetic on residuals).
    let cap10 = bin_capacity / 10; // 10 classes for C=100
    let pr_class = (post_residual % 10) as f64;
    let ni_class = (next_item_size % 10) as f64;
    let pr_quot = (post_residual / 10) as f64;

    // If next item's harmonic class matches post_residual class, a
    // future pairing can zero out the residual: reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        if (ni_class - pr_class).abs() < 0.5 {
            score -= 12.0 + 2.0 * pr_quot;
        }
        // Next item leaves a small-class residue again (chainable fit).
        if (post_residual - next_item_size) % 10 == 0 {
            score -= 8.0;
        }
    }
    // Next item cannot fit here at all: this residual is likely dead space.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 6.0 + 0.5 * pr_class;
    }

    // Dead-space thresholds via integer division: residual too small for
    // the minimum item size (1..100 unknown, use small guard classes).
    if post_residual < 4 {
        score += 40.0; // unusable sliver
    } else if post_residual < 10 {
        score += 15.0;
    }

    // Capacity-fraction coupling: residual near half-capacity is flexible.
    let half = (bin_capacity / 2) as f64;
    let frac = ((post_residual as f64 - half).abs() / half).abs();
    score += 5.0 * frac;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin when decent fits exist,
    // unless open bins are highly fragmented (high mean residual).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 30.0 - fragmentation.min(30.0);
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Late-stream consolidation: as stream progresses, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual < 10 {
        score += 60.0; // creates a slot nothing can ever fill
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - (post_residual as f64) / 20.0);
    } else {
        // Larger residuals that remain reusable: reward them mildly (subtract).
        score -= 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 30.0; // chains a perfect/near-perfect fit
        } else {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && post_residual < next_item_size {
        // Next item cannot use this residual: penalize proportionally to wasted potential.
        score += 6.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bin pressure: penalize the new-bin candidate (bin_residual == bin_capacity)
    // so we prefer reusing existing bins unless the fit is truly terrible.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
    } else {
        // Reward consolidating into bins that are already open.
        score -= 0.5 * open_bins_count as f64;
    }

    // Coupling with mean residual: prefer bins that are tighter than average
    // (below-mean residual means the bin is well used; placing there keeps
    // loose bins available for awkward items).
    if bin_residual < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Early in the stream, be slightly more tolerant of spreading items out
    // (more future flexibility); late in the stream, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact / near-exact fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward when post_residual matches next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 150.0 / (1.0 + diff);
        // Perfect lookahead match: next item exactly fills remaining space
        if post_residual == next_item_size {
            score -= 500.0;
        }
        // Penalize leaving a residual that is unusable for the next item (dead space)
        if post_residual < next_item_size && post_residual > 0 {
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 60.0 * (1.0 - progress) * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Relative to mean residual: prefer bins whose residual is close to item (tight packing)
    let tightness = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * tightness;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 2.0 * open_bins_count as f64;

    // Slight preference for fuller bins
    score -= 0.5 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly favored: reward small post_residual nonlinearly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score -= (cap - pr).powi(2) / cap; // fuller placement -> bigger subtraction

    // Penalize residual that is too small to ever be useful again (dead space),
    // but only mildly since tight fits still matter.
    let min_useful = 10.0f64.min(cap);
    if pr > 0.0 && pr < min_useful {
        score += (min_useful - pr) * 2.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= item_size as f64 * 0.75;
    }

    // Lookahead (k=2): if the next item fits exactly in the post residual,
    // strongly prefer this bin to enable a perfect double fill.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - pr).abs() < 1e-9 {
            score -= 25.0;
        } else if nxt <= pr {
            // next item still fits after this placement -> mild reward
            score -= 5.0 * (nxt / (pr + 1.0));
        } else {
            // placing here makes next item not fit -> mild penalty
            score += 3.0 * ((nxt - pr) / cap);
        }
    }

    // Global state: many open bins with slack -> prefer reusing bins,
    // penalize opening new bins when mean residual is high.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: score it like a fresh bin with residual cap,
        // penalized by number of open bins and their average slack.
        score += open_bins_count as f64 * 4.0 + mean_residual * 0.6;
        // Early in stream, new bins are cheaper; late, expensive.
        score += (1.0 - progress) * 10.0;
        // If no existing bin fits well (post_residual large relative), allow new bin.
        if pr >= item_size as f64 {
            score -= 2.0;
        }
    } else {
        // Reusing an open bin reduces open-bin pressure: reward when many bins open.
        score -= open_bins_count as f64 * 1.5;
        // Reward bins whose residual is below mean (consolidating slack).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    // Dynamic time horizon: as stream progresses, favor tighter packing more.
    score -= progress * (cap - pr) * 0.3;

    // Small deterministic tie-break based on residual parity/magnitude.
    score += (post_residual % 3) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear penalty for awkward dead space.
    let mut score = pr + 40.0 * norm_pr * norm_pr * (1.0 - norm_pr);

    // Tight fits are good: reward small post_residual non-linearly.
    score -= 60.0 * (-pr / 12.0).exp();

    // Lookahead coupling: penalize if post_residual can't host next item smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score += 0.5 * gap;
        // smooth bonus if next item fits exactly-ish into the leftover
        score -= 25.0 * (-gap / 10.0).exp();
    }

    // Stream-progress coupling: later in stream, prefer filling existing bins
    // more aggressively (avoid opening new bins late).
    let late = progress * progress;
    score += late * 20.0 * norm_pr;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mean-residual coupling: if this bin is far from mean, smooth toward it.
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Mild penalty for opening new bins when many are open and sparse.
    if bin_residual == bin_capacity {
        score += 5.0 + 3.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "small"
    // residue classes (0..=9 mod 25) are dead space traps; penalize them.
    let cls = (post_residual % 25) as f64;
    score += (cls / 25.0) * 12.0;

    // Perfect closure bonus: post_residual exactly 0 is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Small post_residual (<= 10) that cannot host the smallest future item:
    // mild penalty unless it is exactly zero.
    if post_residual > 0 && post_residual <= 10 {
        score += 8.0;
    }

    // Lookahead: if next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // If next item fits inside post residual, mild reward scaled by tightness.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot fit here: penalize proportionally to how close it was.
    else if next_item_size > post_residual {
        let gap = (next_item_size - post_residual) as f64;
        score += 5.0 + gap / 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: discourage spreading; prefer filling existing bins tightly.
    score += (open_bins_count as f64) * 0.05 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a "tight" bin — reward using it up.
    let dev = mean_residual - post_residual as f64;
    score -= 0.1 * dev;

    // Capacity fraction thresholds: integer division of residual into quarters.
    let q = post_residual / (bin_capacity / 4);
    score += q as f64 * 3.0;

    // Progress: early in stream, be more conservative about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // (1) are pure waste. Penalize any post_residual below the smallest
    // plausible future item harder than proportionally.
    if post_residual < 10 {
        score += 60.0 - post_residual as f64 * 5.0;
    } else if post_residual < 20 {
        // small gap zone: likely unusable, penalize extra
        score += 12.0 - (post_residual as f64 - 10.0) * 0.8;
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Tightness relative to bin residual: favor bins where the item fills
    // a large fraction of the available space.
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 25.0 * fill_ratio * fill_ratio;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            let rem = post_residual - next_item_size;
            if rem < 10 {
                score -= 15.0;
            }
        } else {
            // next item cannot fit here; dead space confirmed if small
            if post_residual < next_item_size && post_residual < 15 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual
    // of every open bin. Penalize new-bin proportional to open bins count
    // and current mean residual, so we prefer existing bins unless they
    // would create severe dead space.
    if bin_residual == bin_capacity {
        score += 55.0 + 6.0 * open_bins_count as f64 + 0.5 * mean_residual;
    } else {
        // open-bins pressure: mild reward for consolidating into fewer bins
        score -= 2.0 * open_bins_count as f64;
    }

    // Late in the stream, be more conservative about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }

    // Penalize post_residual that is too small to fit the next item (dead space).
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += 0.8 * waste;
    }

    // Mild reward when post_residual can still accommodate the next item with slack.
    if next_item_size > 0 && post_residual > next_item_size {
        score -= 0.15 * ((post_residual - next_item_size) as f64).min(30.0);
    }

    // Compare post_residual against mean residual across open bins.
    score -= 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize creating very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Early in stream: prefer tighter fills; late: allow spreading.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= (1.0 - progress) * 2.0 * (100.0 - post_residual as f64) / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Penalize dead space that is too small to be useful later (below min item size 1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual <= 30 {
        score += 6.0; // awkward mid-range gap
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else {
            // next item won't fit here; slight penalty for stranding space
            score += 4.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when current bins have poor fits.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, decaying as stream progresses (less to lose later).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_cost = 30.0 * (1.0 - 0.3 * progress);
        // If many open bins with large mean residual, opening new bin is wasteful.
        new_bin_cost += 0.15 * mean_residual;
        // But if no existing bin fits well (item leaves big gap in any bin), relax cost.
        let gap_if_placed = post_residual;
        if gap_if_placed <= 15 {
            new_bin_cost += 20.0; // this placement would be fine; keep new bin expensive
        }
        score += new_bin_cost;
    } else {
        // Mild preference for fuller bins (best-fit style): lower residual gets priority.
        score += 0.1 * (bin_residual as f64 / bin_capacity as f64) * 10.0;
        // Encourage consolidation when too many bins are open.
        score += 0.05 * open_bins_count as f64;
    }

    // Time-horizon coupling: early on, be conservative about fragmenting bins.
    let horizon = step_index as f64 / (total_items.max(1) as f64);
    if horizon < 0.2 {
        score += 3.0 * (1.0 - horizon * 5.0) * (post_residual as f64 / bin_capacity as f64);
    }

    // Global balance: penalize bins far above mean residual (keeps residuals uniform).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Tightness: reward small post_residual non-linearly (quartic-ish decay)
    let tight = 1.0 - (post / cap);
    score -= 60.0 * tight * tight;

    // Dead-space penalty: post_residual too small for typical future items
    let dead = ((post - 10.0) / cap).max(0.0).min(1.0);
    score += 25.0 * (1.0 - dead) * dead * 4.0; // peaks at mid residuals

    // Lookahead: if next item fits exactly-ish in post_residual, reward strongly
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = post - next_item_size as f64;
        score -= 40.0 * (1.0 - diff / cap) * (1.0 - diff / cap);
    } else if next_item_size > post_residual {
        score += 8.0 + 10.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 55.0 + 30.0 * t;
    } else if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0);
    }

    // Stream-progress coupling: later in stream, prefer filling bins tighter
    score -= 20.0 * t * tight;
    score += 5.0 * t * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));

    // Mean-residual coupling: penalize deviating from mean residual
    score += 0.15 * (post - mean_residual).abs();

    // New-bin candidate: make it unattractive unless nothing else is reasonable
    if bin_residual == bin_capacity {
        score = post + 70.0 + 40.0 * (fitting_bins_count as f64) - 20.0 * t;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Class A: post_residual in [0,10) -> excellent fit, strong reward.
    if post_residual < 10 {
        score -= 60.0;
    }
    // Class B: post_residual in [10,20) -> good fit.
    else if post_residual < 20 {
        score -= 30.0;
    }
    // Class C: post_residual in [20,35) -> moderate.
    else if post_residual < 35 {
        score -= 10.0;
    }
    // Class D: post_residual in [35,60) -> wasteful dead zone.
    else if post_residual < 60 {
        score += 15.0;
    }
    // Class E: post_residual >= 60 -> near-empty bin used poorly.
    else {
        score += 30.0;
    }

    // Modulo arithmetic on post_residual: leftovers divisible by common item
    // granularities (10, 20, 25, 50) are reusable, reward them.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, huge reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / cap);
        } else {
            // Next item cannot use leftover: penalize proportionally.
            score += 10.0 * (1.0 - frac);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity or open bins are crowded.
    if bin_residual == bin_capacity {
        score += 25.0;
        if item_size > bin_capacity / 2 {
            score -= 30.0;
        }
        if open_bins_count > 8 {
            score -= 10.0;
        }
    }

    // Progress-scaled tie-break: later in stream, tighten packing (favor
    // small post_residual even more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += frac * 20.0 * (1.0 - progress) - frac * 5.0 * progress;

    // Mean-residual coupling: if this bin's post_residual deviates favorably
    // from the mean residual, reward it.
    score -= 0.3 * (mean_residual - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with non-linear penalty
    // for "dead space" gaps that are too small to be useful later.
    let pr = post_residual as f64;
    if post_residual > 0 {
        // Gap smaller than the minimum possible item is pure waste.
        if post_residual < 10 {
            score += 60.0 * (10.0 - pr);
        } else {
            // Quadratic dead-space penalty for small unusable gaps.
            score += 0.8 * pr * pr / 10.0;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            // Next item fits: mild reward proportional to how well it fills.
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use the gap: penalize proportionally to waste.
            score += 0.3 * pr;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening a new one is cheaper.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from existing open bins.
        score += 25.0 + 3.0 * pressure;
        // Late in the stream, slightly cheaper to open a new bin (cleaner packing).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * progress;
        // If next item is large, a fresh bin is attractive.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    } else {
        // Using an existing bin relieves open-bin pressure.
        score -= 1.5 * pressure.sqrt();
    }

    // Prefer bins whose residual is already below average (consolidate waste).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Exact-fit bonus: leaving (almost) nothing behind is ideal.
    if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post-residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        if slack <= 2 {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize dead space proportional to it.
        score += 0.15 * post_residual as f64;
    }

    // Compare against mean residual: bins with less residual than average
    // should be filled first (consolidate small leftovers).
    score -= 0.10 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly prefer using the only fitting bin to avoid
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: make the empty bin unattractive unless there are
    // no good existing fits (post_residual of a fresh bin is huge anyway,
    // but add an explicit penalty that decays as the stream matures).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 60.0 - 10.0 * progress;
        // If the item is large, a fresh bin is actually fine (few bins can hold it).
        if item_size >= bin_capacity / 2 {
            score -= 45.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0;
        }
    }

    // Mild pressure to close out nearly-full bins as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: fraction of bin filled by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Penalize dead space that cannot host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bonus if the leftover can exactly or nearly fit the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space penalty, stronger when leftover is small but unusable.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 25.0 * waste * waste;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Many open bins: discourage spreading; prefer compacting into existing bins.
    let pressure = (open_bins_count as f64 / (1.0 + step_index as f64)).min(1.0);
    score += 10.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins whose residual is below average
    // (consume the "driest" bins first), above-average residuals get penalized.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Time horizon: late in the stream, be more conservative with new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus late-stream penalty.
        score += 30.0 + 40.0 * progress;
        // If nothing else fits well, new bin becomes attractive when item is large.
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: prefer minimal post-residual, with quadratic penalty for waste
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Smooth non-linear coupling of waste with stream progress:
    // waste becomes increasingly costly as the stream matures
    let progress_coupling = (progress * std::f64::consts::PI).sin();
    score += 25.0 * norm_pr * norm_pr * progress_coupling;

    // Cubic interaction: large dead-space strongly penalized late in stream
    score += 15.0 * norm_pr * norm_pr * norm_pr * (1.0 + progress);

    // New-bin candidate: penalize opening a new bin, more so early/mid stream
    if bin_residual == bin_capacity {
        let new_bin_penalty = 30.0 + 60.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        score += new_bin_penalty;
    } else {
        // Reward filling existing bins proportionally to item size used
        let fill_ratio = item_size as f64 / cap;
        score -= 20.0 * fill_ratio * (1.0 - norm_pr);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits perfectly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size as f64 == pr {
            score -= 50.0;
        } else if (next_item_size as u32) <= post_residual {
            // next item fits: mild reward proportional to how snugly
            let snug = 1.0 - ((pr - next_item_size as f64) / cap);
            score -= 15.0 * snug;
        } else {
            // post_residual too small for next item: penalize proportionally
            let waste = (next_item_size as f64 - pr) / cap;
            score += 10.0 * waste * (0.5 + progress);
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.3 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Harmonic class of the post-residual: capacity mod classes.
    // Residuals that are "useless" (below smallest plausible item) are dead space.
    let dead = if post_residual < 10 { 40.0 } else if post_residual < 20 { 18.0 } else { 0.0 };
    score += dead;

    // Exact/near-exact fit reward (post_residual small relative to item).
    let fit_ratio = if bin_residual > 0 { item / bin_residual as f64 } else { 0.0 };
    score -= 25.0 * fit_ratio * fit_ratio;

    // Reward tight packing via integer-division threshold on post_residual.
    let class = post_residual / 10; // harmonic class 0..=10
    score -= 3.0 * (10 - class.min(10)) as f64;

    // Lookahead: bonus if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            score -= 12.0 * (1.0 - ((post_residual - next_item_size) as f64) / cap);
        } else {
            // next item cannot use this residual: mild penalty proportional to leftover
            score += 6.0 * (next_item_size as f64 - post) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Penalize opening a new bin when open bins exist and can fit the item well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 20.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 25.0;
        }
        // A new bin is attractive only if item leaves a very flexible residual.
        score -= 10.0 * (post / cap);
    }

    // Slight preference to balance residuals across bins.
    score += 0.15 * (post - mean_residual).abs();

    // Congestion: many open bins -> prefer filling existing ones.
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 2.0 * open_bins_count as f64 * (1.0 - post / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the next item are wasted.
    let nz = if next_item_size == 0 { 0 } else { next_item_size };
    if nz > 0 && post_residual < nz && post_residual > 0 {
        // Dead space that likely can never be used: strong penalty.
        score += 15.0 + (nz - post_residual) as f64 * 0.5;
        // Extra penalty if the gap is in the classic "unusable" band (1..10).
        if post_residual < 10 {
            score += 20.0;
        }
    } else if nz > 0 && post_residual >= nz {
        // Leaving room for the lookahead item is valuable.
        score -= 4.0;
        // Perfect two-item packing: residual exactly fits next item.
        if post_residual == nz {
            score -= 6.0;
        }
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 8.0;

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, be more willing to open a new one (its score is post_residual = C).
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Prefer bins with residuals below the mean (consolidate fragmented space).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate: neutral baseline adjusted by open-bin pressure so that
    // opening is chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score += 2.0 + (open_bins_count as f64) * 0.3;
    }

    // Mild stream-progression term: later in the stream, favor closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: bin becomes exactly full
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64); // tighter follow-up fit favored more
        } else {
            // next item cannot use leftover: penalize proportionally to wasted potential
            let waste = (next_item_size - post_residual) as f64;
            score += 10.0 * (waste / bin_capacity as f64);
        }
    } else {
        // Last item: prefer fullest packing (smallest post residual) — already base score.
    }

    // Relative-to-mean coupling: bins with residuals below mean are precious; penalize dumping into them
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += 0.5 * (mean_residual - pr);
    } else {
        score -= 0.3 * (pr - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no good lookahead fit exists
    if bin_residual == bin_capacity {
        score += 35.0; // default penalty so open bins are preferred
        if next_item_size > item_size && next_item_size > bin_capacity / 2 {
            score -= 45.0; // big item coming: fresh bin is attractive
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Dead-space penalty: very small unusable leftovers
    if pr > 0 && pr < 10 {
        score += 8.0;
    }

    // Slight stream-progression pressure: later in stream, tighten packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
