pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: post residual (tighter fit -> lower score)
    let mut score = pr;

    // Non-linear polynomial coupling: residual^2 scaled by capacity, modulated by progress
    let r_norm = pr / cap;
    score += 8.0 * r_norm * r_norm * (0.5 + progress);

    // Smooth progress interaction with residual (dead space penalized more late)
    score += 4.0 * r_norm * progress * progress;

    // Reward filling bins nearly exactly (smooth valley near pr == 0)
    score -= 6.0 * (1.0 - r_norm).powi(3);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: prefer only when current bin would leave large dead space
    if bin_residual == bin_capacity {
        score = cap - pr + 10.0 - 15.0 * (1.0 - r_norm).powi(2);
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 5.0;
    } else if next_item_size > 0 {
        score += 3.0 * (1.0 - pr / (next_item_size as f64)).abs();
    }

    // Mean residual coupling: avoid bins far below mean residual (fragmented bins)
    score += 2.0 * ((mean_residual - pr) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of bin wasted after placement

    // Penalize residuals that fall into "unusable" harmonic classes.
    // Classes: [0, 10) terrible, [10, 34) ok (fits small items), [34, 50) decent, [50, 100) fine.
    let cls = post_residual / 10; // integer division threshold class 0..10
    match cls {
        0 => score += 40.0,                      // dead space < 10: nearly unusable
        1 => score += 12.0,                      // 10..19
        2 => score += 4.0,                       // 20..29
        3 => score += 0.0,                       // 30..39 sweet spot
        4 => score -= 6.0,                       // 40..49 great
        _ => {}                                  // 50+: roomy bin, base score handles it
    }

    // Modulo coupling: reward when post_residual % 10 == 0 (perfect decimal alignment)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward (harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // pairability scaled by how close the next item fills the gap
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here: penalize proportional to leftover dead class
            score += 6.0 * frac;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer new bin only when all open fits are poor
    // (large post_residual waste) or stream is early with many bins already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // new bin gets a neutral-ish score that competes with bad fits
        score = cap * 0.75 + 20.0 * (1.0 - progress) - 0.5 * mean_residual;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // new bin can always take the next item too
            score -= 5.0;
        }
    }

    // Mild global pressure: when many bins are open, tighten packing (favor small post_residual).
    score += 0.05 * open_bins_count as f64 * frac;

    // Mean-residual coupling: prefer bins whose residual deviates below mean (tight bins first).
    score -= 0.3 * (mean_residual - post_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: nearly full bins are excellent.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Dead space penalty: small gaps that likely can't fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable dead space (min item size 10)
    }
    // Gap too small for the lookahead item: dead space for k=2.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    // Reward gaps that exactly fit the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Perfect-fit reward relative to residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open bins pressure: many open bins -> prefer filling existing ones,
    // penalize opening new bins.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= (open_bins_count as f64).sqrt() * 3.0;
    }

    // Mean residual coupling: bins deviating below mean residual are
    // already tight; prefer placing into bins with larger residuals.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Mild stream progression: early on, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress) * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly preferred: penalize large post-residual quadratically.
    let pr = post_residual as f64;
    score += 0.35 * pr * pr / bin_capacity as f64;

    // 2-step lookahead: if next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (post_residual as u32) == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it fills the remainder
            let two_step_waste = post_residual as f64 - n;
            score -= 30.0 - 0.5 * two_step_waste;
        } else {
            // next item won't fit here: penalize bins that strand space
            score += 0.25 * pr;
        }
    }

    // Reward leaving residuals comparable to the mean (keeps bins homogeneous),
    // penalize creating outliers below mean residual that become dead space.
    let dev = pr - mean_residual;
    if dev < 0.0 {
        score -= 0.4 * dev; // smaller than mean residual is good (tight packing)
    } else {
        score += 0.15 * dev;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when current bin leaves bad residue
    // and next item is large (needs fresh space).
    if bin_residual == bin_capacity {
        let base = 0.5 * bin_capacity as f64;
        score += base;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
        if pr < 20.0 {
            score -= 15.0; // fresh bin good if item nearly fills it
        }
        // late in stream, prefer reusing open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // many open bins -> discourage opening more
        score += 3.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize large dead space relative to capacity
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * waste_ratio * waste_ratio;
    }

    // Lookahead: reward if next item fits in the post residual (chaining)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward for near-exact two-item packing
            let gap = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Penalize leaving space that next item can't use
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = bin_capacity as f64 * 0.75;
        // More acceptable early in the stream or when few bins are open
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        score -= (open_bins_count as f64).ln() * 3.0;
        // If other bins fit, discourage new bin unless they are all poor fits
        if fitting_bins_count > 0 {
            let mean_gap = mean_residual - item_size as f64;
            if mean_gap > 25.0 {
                score += 20.0; // existing bins are roomy, use them
            } else {
                score += 5.0;  // existing fits are tight-ish; new bin mildly ok
            }
        }
    }

    // Slight preference for bins with residuals close to the item (tight fits)
    let tightness = 1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 8.0 * tightness;

    // Mild global pressure: when many bins are open, prefer consolidating
    score += (open_bins_count as f64) * 0.05 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let base = pr;
    let poly = norm_pr * norm_pr * (1.0 - progress) * cap
        + norm_pr * progress * progress * cap;

    let mut score = base + 0.35 * poly;

    // Smoothly penalize dead space as stream progresses
    score += progress * norm_pr * 12.0;

    // Reward tight fits smoothly
    let fit_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_frac * fit_frac;

    // Last-chance bonus (smooth)
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - progress) + 3.0;
    }

    // Lookahead: reward leaving room for next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score += 0.05 * gap;
        if pr >= nxt {
            score -= 2.0;
        }
    }

    // Mild pressure from mean residual
    score += 0.02 * (mean_residual - pr).abs();

    // New-bin candidate: keep it slightly unattractive unless residual is large
    if bin_residual == bin_capacity {
        score += 1.0 + 20.0 * (1.0 - progress) * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact / near / coarse classes via integer division.
    let class = post_residual / 10;              // coarse class (0..10)
    let exact = (post_residual % 10) == 0;       // "harmonic" residual aligning with capacity fractions

    // Reward harmonic residuals (multiples of 10): dead space in a harmonic class
    // is more likely to be reusable by future items.
    if exact {
        score -= 6.0;
    }

    // Non-linear penalty on dead space: small residuals are fine (near-tight fit),
    // mid residuals are the worst (unusable), large residuals are acceptable.
    let r = post_residual as f64;
    score += 0.35 * (r * 0.08).exp() * (r > 0.0) as i32 as f64;   // tiny residual bonus
    if class >= 2 && class <= 5 {
        score += 9.0;                                            // mid-class dead zone penalty
    }
    score += 0.02 * (r - 50.0) * (r - 50.0) / 100.0;             // quadratic dead-space cost

    // Tight fit reward: item fills bin almost completely.
    if post_residual <= 2 {
        score -= 15.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits exactly into the post residual,
    // this placement sets up a perfect chain.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // Next item cannot use this residual: penalize proportionally to waste.
            score += 0.05 * (next_item_size as f64 - r).min(40.0);
        }
        // Harmonic class match between residual and next item.
        if next_item_size / 10 == class && post_residual > 0 {
            score -= 4.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin offers a decent fit, or when we are early and bins are scarce.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        // Base cost of a fresh bin, discounted by scarcity and stream progress.
        score = 40.0 - 15.0 * scarcity - 10.0 * progress;
        // A new bin is attractive if the item is large (poor fit elsewhere likely).
        if item_size > bin_capacity * 3 / 4 {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    } else {
        // Mild preference for fuller bins among open candidates.
        score -= 0.03 * (bin_capacity - bin_residual) as f64;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already "cramped" — finishing it off is good.
    let dev = mean_residual - r;
    if dev > 0.0 {
        score -= 0.10 * dev.min(50.0);
    } else {
        score += 0.05 * (-dev).min(50.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (min item size 1..~10) are "dead space".
    let dead_threshold = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0; // heavy penalty for unusable slivers
    }
    // Zero residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Nonlinear penalty on mid-range dead space (wasted capacity).
    let waste = post_residual as f64;
    score += 0.15 * waste * waste / bin_capacity as f64;

    // Pressure from number of open bins: prefer filling existing bins
    // rather than spreading across many bins.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward;
    // if next item cannot fit in post-residual (and > 0), penalize slightly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 4.0;
        }
    }

    // Mean residual coupling: if this bin is far below the mean residual,
    // it is a "sparse" bin; filling it is less valuable than filling denser bins.
    let dev = mean_residual - post_residual as f64;
    score += 0.05 * dev;

    // Late in the stream, tighten packing (favor tight fits even more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match between post_residual
    // and the next item size (this bin becomes perfectly reusable).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: strong reward proportional to item size (bigger match = better).
        if diff == 0 {
            score -= 60.0 + item_size as f64 * 0.5;
        } else {
            // Graded reward: closer post_residual to next item => better.
            score -= (30.0 * (1.0 - diff / bin_capacity as f64)).max(0.0);
            // Penalize overshoot where next item cannot fit (dead space for next step).
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 0.6;
            }
        }
    } else {
        // Last item: prefer minimal final residual.
        score += 0.0;
    }

    // Compare post_residual against mean residual: leaving a bin far below mean
    // residual creates fragmentation; leaving it near/above mean is fine.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += 0.4 * (mean_residual - pr);
    } else {
        score -= 0.15 * (pr - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Dampen preference for nearly-empty open bins when many bins are open
    // (consolidation pressure), but keep new-bin candidate (residual == capacity)
    // neutral-to-slightly-penalized so we only open new bins on good cause.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.1 * open_bins_count as f64;
    }

    // Tight fits are always good: reward small post_residual non-linearly.
    if pr > 0 {
        score -= 10.0 * (1.0 - pr / bin_capacity as f64).powi(4);
    } else {
        // Perfectly closed bin: excellent.
        score -= 40.0;
    }

    // Early in the stream, be slightly more willing to open new bins (future flexibility).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize large dead space that is hard to reuse (below typical item sizes).
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // tiny dead space is excellent
    } else if post_residual >= 10 && post_residual <= 30 {
        score -= 6.0;  // usable residual
    } else {
        score += (post_residual as f64 - 30.0).max(0.0) * 0.15; // wasteful leftover
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit_everywhere = fitting_bins_count == 0
            || (fitting_bins_count == 1 && fit_ratio < 0.5);
        let big_next = next_item_size as f64 > post_residual as f64
            && next_item_size > 0;
        if poor_fit_everywhere || big_next {
            score -= 35.0;
        } else {
            score += 60.0; // keep using existing bins when they fit reasonably
        }
    }

    // Lookahead coupling: favor leaving room for the next item.
    if next_item_size > 0 {
        if post_residual as f64 >= next_item_size as f64 {
            score -= 8.0;
        } else if (post_residual as f64 - next_item_size as f64).abs() < 5.0 {
            score += 5.0;
        }
    }

    // Global state: with many open bins, consolidate; with few, be flexible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.8;
    score -= mean_residual * 0.2 * (1.0 - progress);

    // Late in the stream, tighten packing more aggressively.
    score += progress * 10.0 * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tight = 1.0 - (pr / cap);

    // Smooth polynomial coupling of post_residual with stream progress
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    score += 2.5 * pr * prog2 + 1.5 * pr * prog3;

    // Reward tight fits more strongly as the stream progresses (smooth ramp)
    score -= 6.0 * tight * (0.5 + 0.5 * progress);

    // Penalize dead space relative to mean residual across open bins
    score += 0.4 * (pr - mean_residual).abs();

    // Last-chance bin: strongly favor using it (smooth exponential-ish term)
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    }

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score -= 2.0 * (1.0 - gap / cap) * (1.0 - progress);
    }

    // Mild penalty for spreading across too many open bins late in the stream
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact fills are perfect.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Classify post_residual into harmonic classes via integer division.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f; // fraction of capacity left over

    // Penalize "dead" residuals that are too small to be useful for typical items.
    // Harmonic class: class 0 = residual < 10 (near dead), class 1 = <20, etc.
    let class = post_residual / 10; // 0..10
    score += match class {
        0 => 60.0,                       // nearly unusable sliver
        1 => 25.0,
        2 => 10.0,
        3 => 0.0,
        4 => -5.0,
        5 => -8.0,                        // ~half-empty bin is flexible
        6 => -4.0,
        7 => 2.0,
        8 => 6.0,
        9 => 10.0,
        _ => 0.0,
    };

    // Non-linear coupling: large leftover fraction with a small item is wasteful.
    score += 30.0 * frac * frac * (1.0 - (item_size as f64) / cap_f);

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Reward proportional to how well the next item fills the leftover.
            let fill = (next_item_size as f64) / post_f;
            score -= 80.0 * fill;
            // Harmonic class of the double leftover (residual after both items).
            let dbl = post_residual - next_item_size;
            let dclass = dbl / 10;
            score += match dclass {
                0 => 40.0,
                1 => 15.0,
                2 => 5.0,
                3 => -3.0,
                4 => -6.0,
                5 => -5.0,
                _ => 0.0,
            };
        } else {
            // Next item cannot use the leftover: mild penalty.
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin costs roughly one bin; make it worse than decent fits.
        score += 150.0;
        // But if current bin would leave a tiny dead space and a new bin is pristine,
        // opening can win: reduce penalty when post residual is in a bad class.
        if class == 0 {
            score -= 140.0;
        } else if class == 1 {
            score -= 40.0;
        }
        // More open bins => prefer packing into existing ones.
        score += 5.0 * (open_bins_count as f64).sqrt();
    }

    // Stream progression: early on, be slightly more willing to open bins (future unknown).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if is_new_bin {
        score -= 20.0 * (1.0 - progress);
    }

    // Mean residual context: if open bins are on average roomy, prefer spreading load.
    if !is_new_bin {
        score += 0.05 * (mean_residual - post_f).abs();
    }

    // Modulo harmonic tiebreakers on post_residual (divisibility structure).
    if post_residual % 25 == 0 || post_residual % 50 == 0 {
        score -= 6.0; // nicely divisible residuals pair well with common item sizes
    }
    if post_residual % 10 == 5 {
        score += 3.0; // odd half-tens are slightly awkward
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1..10)
    // are wasted capacity -> heavy penalty proportional to wasted space.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 25.0;
    }
    if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin.
        score -= 60.0;
    }

    // Penalize residuals that cannot fit the lookahead item if this bin would
    // otherwise be the only viable host (last-chance protection).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }
    // Reward leaving exactly enough room for the next item (chained fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure that grows with open bins
        // and stream progress; allow opening early or when nothing fits well.
        score = bin_capacity as f64 * 0.55 + open_bins_count as f64 * 8.0 + progress * 25.0;
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a bin anyway
        }
        // If some open bin would leave a near-perfect fit, discourage new bin.
        if post_residual == 0 { score -= 60.0; }
    } else {
        score += open_bins_count as f64 * 0.5;
        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
        // Prefer bins whose residual is close to the item (tight fits).
        let tightness = 1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64;
        score -= 10.0 * tightness;
        // Slight pull toward the mean residual to balance load across bins.
        score += (mean_residual - post_residual as f64).abs() * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to zero is good.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(6) * 40.0;

    // 2-step lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= (1.0 - gap / bin_capacity as f64).powi(4) * 60.0;
        // Perfect chain: post_residual == next_item_size
        if post_residual == next_item_size {
            score -= 50.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize dead space.
        score += 15.0;
        // Extra penalty if leftover is small and unusable (wasted capacity).
        if post_residual < 10 {
            score += 20.0;
        }
    }

    // Relative-to-mean residual coupling: bins with residual far below mean
    // are the "scrap" bins; prefer filling them (lower their score).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= dev * 30.0;

    // Last-chance bin: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin wastes existing residual.
    if bin_residual == bin_capacity {
        // Base new-bin score is full capacity; add cost that grows with
        // number of open bins and how much total residual is idle.
        score += 25.0 + (open_bins_count as f64) * 2.0;
        // But if no open bin fits well (post_residual large relative), allow opening.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // new bin can chain with next item
        }
    } else if post_residual >= 10 {
        // Placing into an open bin keeps residual usable; mild reward.
        score -= 5.0;
    }

    // Stream progression: early on, be more willing to open bins (spread items);
    // later, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_frac = item_size as f64 / bin_residual.max(1) as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = post;

    // Reward tight fits strongly (non-linear).
    score -= 30.0 * fit_frac * fit_frac;

    // Penalize large dead space, but less late in stream when bins are scarce.
    let dead_weight = 0.6 + 0.8 * t;
    if post > 0.0 {
        score += dead_weight * (post / cap).powi(3) * cap;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits in post residual.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 10.0 + 8.0 * (next_item_size as f64 / post);
    } else if next_item_size > 0 {
        // Penalize leaving residual that nothing useful can use.
        score += 4.0 * (post / cap);
    }

    // New-bin candidate: penalize opening bins, more when many bins open
    // or when a fitting bin exists with decent residual.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        score += 18.0 * pressure + 2.0 * (open_bins_count as f64).sqrt();
        // Late in stream, avoid opening new bins even more.
        score += 15.0 * t;
        // If mean residual is large, opening a new bin wastes existing space.
        score += 0.15 * mean_residual;
    }

    // Mild preference for bins below mean residual (balance load).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Normalize post_residual by capacity
    let pr = post_residual as f64 / bin_capacity as f64;

    // Non-linear penalty on very small (dead space) or awkward residuals,
    // coupled with stream progress: early on tolerate slack, later tighten.
    let dead = (1.0 - pr).max(0.0);
    score += 30.0 * (pr * (1.0 - pr)) * (1.0 - progress) * dead;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 25.0 * (1.0 - pr) * (1.0 - pr) * (0.5 + 0.5 * progress);

    // Lookahead coupling: reward if next item fits in post_residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 12.0 * snug * snug;
        } else {
            // penalize leaving residual that the next item cannot use at all
            score += 8.0 * (nx / bin_capacity as f64) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: make it costly unless open bins are badly fragmented
    if bin_residual == bin_capacity {
        score += 15.0 + 0.05 * open_bins_count as f64 * (1.0 - progress);
        // allow opening a new bin late in the stream when mean residual is tiny
        score -= 10.0 * (1.0 - mean_residual / bin_capacity as f64).max(0.0) * progress;
    }

    // Mild fragmentation penalty tied to mean residual deviation
    score += 3.0 * ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify dead space into usable bands.
    // Residuals in [0,10] are near-perfect; [10,25] still fit many items;
    // large residuals waste capacity only if nothing else fits the bin.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: extremely desirable
    } else if pr <= 10 {
        score -= 45.0;
    } else if pr <= 25 {
        score -= 25.0;
    } else if pr <= 50 {
        score -= 8.0;
    }
    // pr > 50: large leftover, keep base penalty (score stays high)

    // Harmonic / modulo structure: residuals that are multiples of common
    // item granularities (10, 20, 25) remain reusable.
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0) {
        score -= 6.0;
    }

    // Lookahead coupling: reward leaving exactly enough room for next item.
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 40.0;
        } else if pr >= next_item_size && pr - next_item_size <= 10 {
            score -= 18.0;
        } else if pr < next_item_size && pr >= 10 {
            // residual too small for next item: penalize proportionally
            score += 0.15 * (next_item_size - pr) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): post_residual = capacity - item_size.
    // Make it attractive only when it would leave a clean harmonic residual
    // (multiple of 10 or 25) and no existing bin is a decent fit.
    if bin_residual == bin_capacity {
        let clean = (post_residual % 10 == 0 || post_residual % 25 == 0) as f64;
        score -= 12.0 * clean;
        // discourage opening bins when many are already open with slack
        score += 0.4 * open_bins_count as f64;
        // discourage opening when mean residual across open bins is large
        score += 0.5 * mean_residual;
        // slightly favor opening early in the stream (more future items to use slack)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    } else {
        // Mild preference for keeping bins balanced with mean residual
        score += 0.05 * (bin_residual as f64 - mean_residual).abs();
    }

    // Fractional capacity coupling: reward fill ratio of the bin.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 15.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // smallest conceivable future item (<= 1..20) are "dead" — penalize hard.
    let dead_threshold = 20.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 2.5;
    }

    // Reward near-perfect fits strongly (post_residual close to 0 is ideal).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Coupling with open_bins_count pressure: when many bins are open, prefer
    // filling existing bins (penalize opening/using sparse bins less aggressively),
    // when few bins are open, consolidation is cheap.
    let bin_pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score += bin_pressure * 1.5;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit,
    // or the item would create heavy dead space elsewhere. Make new bins
    // moderately expensive by default.
    if bin_residual == bin_capacity {
        score += 55.0;
        // If lookahead item is large and would pair well with a fresh bin, soften.
        if next_item_size > 0 && next_item_size as f64 >= mean_residual {
            score -= 30.0;
        }
        // Early in the stream, opening bins is cheaper (builds a pool).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
    }

    // Lookahead synergy: if the next item fits exactly in post_residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space for the known next item: penalize.
        score += (post_residual as f64) * 0.8;
    }

    // Prefer bins whose residual is closest to the item (tight packing),
    // scaled by how average the bin is.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot follow here: penalize leftover dead space
            let dead = post_residual as f64;
            score += 0.15 * dead * dead / bin_capacity as f64;
        }
    }

    // Penalize deviation from mean residual (prefer balanced / extreme fits)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor
    if bin_residual == bin_capacity {
        score += 45.0;
        // But allow new bin if post_residual too small to be useful for next item
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 55.0;
        }
        // Late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Slight preference to fill bins with many occupants
    score -= 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tightness * tightness;

    // Strongly favor perfect or near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this placement sets up a chain fill — reward it heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 25.0;
        }
        // Penalize leaving residual that is awkwardly just below next item size
        // (dead space the next item cannot use).
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin when decent fits exist,
    // but allow it when residuals across open bins are fragmented (large mean
    // residual with many open bins suggests scattered space).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / (bin_capacity as f64);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening a new bin is cheap early (plenty of stream left to fill it),
        // expensive late.
        score += 25.0 - 20.0 * progress;
        // If existing bins are tightly packed, a new bin is more acceptable.
        score -= 30.0 * (1.0 - fragmentation);
        // Many open bins with large residuals: discourage adding another.
        if open_bins_count > 4 && fragmentation > 0.4 {
            score += 15.0;
        }
    } else {
        // Mild preference for filling bins that are already mostly full,
        // keeping many partially-filled bins available for future items.
        let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 10.0 * fill_ratio;
    }

    // Time-horizon adaptation: early in the stream, keep bins flexible
    // (penalize leaving tiny residuals); late, prioritize squeezing tight.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 {
        let flexibility_bonus = (post_residual as f64 / 10.0).min(4.0);
        score += (1.0 - progress) * 4.0 * flexibility_bonus;
    }

    // Penalize very large post-residuals that few item sizes can use.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 * (1.0 - progress); // small dead space worse early
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_fit = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Core: quadratic penalty on post_residual, modulated by stream progress.
    let mut score = pr * (1.0 + 2.0 * progress * (pr / cap));

    // Reward tight fits (small post_residual) with a smooth non-linear bonus.
    score -= 8.0 * (1.0 - norm_fit).powi(2) * (pr / cap).exp();

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let gap = pr - norm_next * cap;
        if gap >= 0.0 {
            score -= 5.0 * (gap / cap).exp() * (1.0 - progress);
        } else {
            score += 0.05 * gap.abs() * (1.0 + progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0 * (1.0 + progress);
    }

    // Crowd penalty: many open bins with slack -> prefer using fuller ones.
    let slack = (pr - mean_residual) / cap;
    score += 1.5 * slack * (open_bins_count as f64).ln().max(0.0) * (0.5 + progress);

    // Slight preference for keeping new-bin option open early in the stream.
    if bin_residual == bin_capacity {
        score += 2.0 * (1.0 - progress) - 1.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Class by quarter-capacity bands via integer division.
    let quarter = bin_capacity / 4;
    let post_class = post_residual / quarter; // 0..4
    match post_class {
        0 => score -= 30.0,                       // tiny leftover: near-perfect fit
        1 => score -= 10.0,                       // quarter left: usable for small items
        2 => score -= 4.0,                        // half left
        3 => score += 6.0,                        // 3/4 empty: wasteful placement
        _ => score += 14.0,                       // barely used the bin
    }

    // Modulo-10 residue class: leftovers divisible by 10 pair well with the
    // typical item granularity, so reward "round" residuals.
    let rem10 = post_residual % 10;
    score -= (10 - rem10) as f64 * 0.4 - 2.0;     // rem10==0 gets bonus, rem10==9 penalty

    // Exact-fill bonus via integer division threshold.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: does the leftover match the next item's class?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits here: reward proportionally to snugness
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 5.0; // chain of round residuals
            }
        } else {
            // leftover too small for next item: penalize dead space
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: prefer tighter bins to consolidate; few bins: be lenient.
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 6.0;

    // Deviation from mean residual: prefer bins below mean (tighter bins).
    score += ((post_residual as f64 - mean_residual) / bin_capacity as f64) * 8.0;

    // New-bin candidate: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin wastes (capacity - item) upfront; make it costly
        // unless the item is huge relative to capacity or no alternatives.
        score += 18.0
            - (item_size as f64 / bin_capacity as f64) * 30.0
            - if fitting_bins_count == 0 { 40.0 } else { 0.0 };
    }

    // Mild stream-progression drift: early on be conservative (keep bins open),
    // later accept tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.02 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical future items are heavily penalized (unusable gap).
    let dead_threshold: f64 = 15.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }
    if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 60.0;
    }

    // Reward tight fits relative to the bin's remaining space.
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 25.0;
    }

    // Open-bin pressure: discourage opening extra bins when many are open.
    score += open_bins_count as f64 * 3.0;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.3;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward this placement; if next item is large, penalize leaving small gaps.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Mild phase adjustment: early in the stream, be slightly more willing
    // to open bins; late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;
    score += mean_residual * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: item + next item exactly fill the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Next item fits into the post-residual: strong reward, scaled by tightness.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - 0.25 * slack;
    }
    // Next item cannot use the residual: penalize proportional dead space.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 0.5 * (post_residual as f64).powf(1.3);
    }

    // Tight fit reward: small post-residual is good (cubic in residual/capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 20.0 * (1.0 - tightness).powi(3);

    // Penalize residuals too small for the minimum conceivable item (dead space).
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Prefer bins below mean residual (using up emptier space first).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate: make it attractive only when no good fit exists;
    // otherwise discourage spreading across bins.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 30.0;
        } else {
            score += 10.0 + 2.0 * item_size as f64 * 0.1;
        }
    }

    // Early in stream: slightly encourage consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress) * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to item size)
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 0.6 * (bin_capacity as f64) / (1.0 + tightness);

    // Penalize post_residual that cannot host any plausible future item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space: too small for any item (min size 1..100, but small scraps waste)
    }

    // Lookahead: reward if next item fits into post_residual (chaining)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.15 * (next_item_size as f64);
        } else {
            // penalize leaving space the next item can't use if gap is small
            let gap = post_residual as f64 - next_item_size as f64;
            if gap < 0.0 && gap > -15.0 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else {
        // spread load when many bins fit: prefer bins with below-mean residual
        score += 0.5 * ((bin_residual as f64) - mean_residual);
    }

    // New-bin candidate handling: opening a bin is penalized, but less when
    // existing fits are poor (large post_residual) or late in stream.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fits = (post_residual as f64) / (bin_capacity as f64); // = 1.0 for new bin
        // baseline penalty for opening a new bin, softened if stream is early (room to fill)
        score += 30.0 - 20.0 * (1.0 - progress) - 10.0 * (open_bins_count as f64).min(10.0) / 10.0;
        // if item is huge, opening a fresh bin is fine
        if item_size > bin_capacity * 3 / 4 {
            score -= 15.0;
        }
        let _ = poor_fits;
    }

    // Mild penalty for high fragmentation across many open bins
    score += 0.05 * (open_bins_count as f64).powf(1.2) * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_frac = item_size as f64 / cap;
    let fill = 1.0 - fit_frac;

    // Smooth non-linear base: reward tight fits via cubic coupling of post_residual with fill fraction
    let mut score = pr * (1.0 + 0.8 * fill * fill) - 30.0 * fill * fill * fill;

    // Stream-progress coupling: later in the stream, penalize wasted residual more strongly
    let prog_term = progress * progress * pr * pr / cap;
    score += 0.35 * prog_term;

    // Interaction: post_residual * progress * fit_frac (smooth cubic coupling)
    score -= 12.0 * progress * fill * (1.0 - pr / cap);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer opening a new bin early or when residual would be dead space
    if bin_residual == bin_capacity {
        score = pr + 20.0 * (1.0 - progress) - 15.0 * fill;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Lookahead: if next item fits the post-residual, reward this placement smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (pr - nxt).max(0.0);
        score += 0.5 * fits_next - 10.0 * (1.0 - (nxt / cap).min(1.0)) * (pr >= nxt) as i32 as f64;
    }

    // Mild penalty for many open bins to encourage consolidation
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    // Mean-residual coupling: penalize deviating far from mean residual
    score += 0.1 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that sit in "useful" modular bands.
    // Residuals divisible by common small item sizes (10..=25) are reusable.
    let pr = post_residual;
    if pr > 0 {
        let mut reusable = 0.0;
        for d in 10..=25u32 {
            if pr % d == 0 {
                reusable += 1.0;
            }
        }
        score -= 6.0 * reusable;

        // Integer-division thresholds: residual >= 50 is half-full-usable, big bonus.
        if pr >= bin_capacity / 2 {
            score -= 12.0;
        } else if pr >= bin_capacity / 4 {
            score -= 5.0;
        } else if pr < 10 {
            // dead space: tiny residual unusable by any item
            score += 25.0;
        }
    } else {
        // Perfect closure — best possible outcome.
        score -= 60.0;
    }

    // Coupling with lookahead item: reward post_residual that exactly or nearly fits next item.
    if next_item_size > 0 && next_item_size <= pr {
        let gap = pr - next_item_size;
        if gap == 0 {
            score -= 40.0;
        } else if gap <= 5 {
            score -= 20.0;
        } else {
            score -= 10.0 * (1.0 - gap as f64 / cap);
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // next item cannot use this bin's remainder; penalize mildly if residual is mid-range
        if pr >= 10 && pr < 30 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it moderately attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        let base = 15.0 + 0.25 * mean_residual;
        score = score.max(base) + 10.0;
        // if many bins already open, discourage proliferation
        score += 2.0 * open_bins_count as f64;
    }

    // Progress modulation: late in the stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / cap);

    // Deviation from mean residual: prefer bins whose remainder tracks the fleet average (balance).
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space penalty: small unusable gaps are the enemy.
    // A post_residual that is too small for the smallest plausible item (1..=10)
    // is pure waste; penalize it heavily, scaled by how "trapped" it is.
    if post_residual < 10 {
        score += 45.0 * (10 - post_residual) as f64;
    } else if post_residual < 20 {
        // Marginal zone: gap usable only for tiny items; soft penalty.
        score += 12.0 * (20 - post_residual) as f64;
    }

    // Perfect-fit reward: subtract aggressively when the item nearly fills the bin.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Reward bins whose residual was already tight (high fill ratio).
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing ones; penalize the new-bin candidate and spread.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 4.0);
    if bin_residual == bin_capacity {
        // New bin candidate: heavily penalized unless nothing fits well.
        score += 25.0 + 8.0 * pressure;
    } else {
        score -= 3.0 * pressure;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if next item could use the leftover gap, reward
    // leaving exactly that much space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 5.0; // gap too small for the known next item
        }
        // Encourage leaving exactly the next item's size when possible.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Mild alignment with mean residual: bins below mean residual are
    // already tighter than average; slightly prefer them.
    score += 0.15 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
