        // Last-chance bin bonus: avoid opening a new bin if this is the only fit.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // Prefer bins with less residual among equally tight fits.
        score += 6.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    }

    // Mild pressure to consolidate when many bins are open.
    score -= 2.0 * (open_bins_count as f64).ln();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (0.5 + 1.5 * progress) + pr_norm * (1.0 - progress);

    let mut score = pr + poly * cap;

    // Reward tight fits (low post_residual) with smooth decay
    score -= 12.0 * (-pr_norm * 8.0).exp();

    // Penalize leaving residual that fits neither current nor next item poorly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score += 6.0 * (gap / cap) * (pr - nxt).signum().max(0.0);
        // Reward leaving exactly enough room for next item
        if pr >= nxt {
            score -= 10.0 * (1.0 - ((pr - nxt) / cap)).exp();
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild pressure to reuse open bins as many accumulate
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    // Deviation from mean residual: prefer bins near mean to balance load
    score += 0.3 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: make it moderately attractive only when progress is high
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.4 * progress) - 15.0 * progress;
        if fitting_bins_count == 1 {
            score += 40.0; // don't open new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: items sized 1..100, capacity 100.
    // Dead space is only valuable if a future item can land in it.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fill: strongly reward.
        score -= 1000.0;
    } else {
        // Class the residual by integer division into harmonic bands.
        // Band 0: pr in [1..10]  -> nearly dead space, penalize hard.
        // Band 1: pr in [11..25] -> only tiny items fit, penalize.
        // Band 2: pr in [26..50] -> medium items fit, mild penalty.
        // Band 3: pr in [51..100] -> flexible space, mild reward relative to size.
        let band = pr / 25; // 0..4
        match band {
            0 => score += 60.0 - (pr as f64) * 4.0, // small residual: worse for smaller pr
            1 => score += 20.0,
            2 => score += 5.0,
            _ => {}
        }
        // Modulo-10 harmonic subclass: residuals divisible by 10 align with
        // common item sizes; reward alignment.
        if pr % 10 == 0 {
            score -= 8.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Chain fit: reward proportionally to how tightly it chains.
            let chain_waste = (pr - next_item_size) as f64;
            score -= 30.0 - chain_waste * 0.3;
        } else {
            // Next item cannot follow here: slight penalty, worse the
            // closer the next item is to fitting (frustrated fit).
            let miss = (next_item_size - pr) as f64;
            score += miss.clamp(0.0, 20.0) * 0.8;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin should lose unless
    // the current item leaves a bad residual in every open bin.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: a fresh bin has residual 100 which is
        // maximally flexible, but costs a bin. Give it a mid-range score.
        score = 55.0;
        // Late in the stream, prefer consolidation into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 30.0;
        // Many open bins: discourage yet another one.
        score += open_bins_count as f64 * 1.5;
        // If the item fits poorly anywhere (large item leaving tiny residual),
        // a new bin becomes attractive: item_size close to capacity.
        if item_size >= 90 {
            score -= 25.0;
        }
        // If next item is large, a fresh bin is useful for it.
        if next_item_size >= 70 {
            score -= 15.0;
        }
    } else {
        // Mild bonus for keeping bins tightly packed when many bins are open.
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= tightness * 10.0;
        // Nudge toward bins whose residual is close to the mean residual
        // (keeps the pool homogeneous, easier future matching).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    }

    // Progression-aware mild scaling: early items, be greedy for tight fits;
    // later, slightly prefer perfect closures.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if pr == 0 {
        score -= progress * 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space zone: residuals of 1..=9 are nearly unusable for items >=10 (or >=1 here)
    // penalize them heavily; perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 9 {
        score += 40.0 + (9 - post_residual) as f64 * 2.0;
    } else if post_residual <= 19 {
        score += 10.0;
    }

    // Tight fit bonus relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // New-bin candidate handling: only attractive when no open bin fits well
    // or open-bin pressure is high.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
        let last_chance = fitting_bins_count <= 1;
        if last_chance {
            score += 100.0; // strongly prefer using the last fitting bin
        } else if pressure > 2.0 && post_residual > 60.0 {
            score -= 15.0; // many open bins: fresh bin with big residual is fine
        } else {
            score += 25.0;
        }
    }

    // Lookahead: favor bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // would strand dead space relative to lookahead
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 0.5;

    // Slight preference for bins already below mean residual (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else {
        // Penalize residual relative to mean residual: leaving more than average is wasteful
        score += (post_residual as f64 - mean_residual).max(0.0) * 0.8;
        // Reward residuals smaller than mean
        score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;
    }

    // 2-step lookahead: exact match of next item into post_residual is ideal
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if next <= post_residual as f64 {
            // next item fits: reward closeness to perfect chain
            score -= 120.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 400.0;
            }
        } else {
            // next item won't fit here: mild penalty scaled by overflow gap
            score += 0.5 * (next - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless current bin residual is small or item is large
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fill_ratio = item_size as f64 / cap;
        // prefer new bin when item is large and would leave big residual in existing bins
        let threshold = 0.75 - 0.15 * progress;
        if fill_ratio > threshold && post_residual as f64 > 0.4 * cap {
            score -= 250.0;
        } else {
            score += 300.0;
        }
    }

    // Slight preference to keep number of open bins manageable early on
    if open_bins_count > 8 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;

    let mut score = post;

    // Reward tight fits: quadratic bonus for small post-residual.
    score -= 2.5 * ((cap - post) / cap).powi(3) * cap * 0.1;

    // Penalize dead space that is too small to be useful for typical items.
    if post > 0.0 && post < 10.0 {
        score += 15.0;
    } else if post >= 10.0 && post <= 30.0 {
        // Sweet-spot residual: still usable by future small items.
        score -= 6.0;
    }

    // Lookahead: strongly reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = post - nxt;
            // Prefer exact two-item chains.
            score -= 8.0 * (1.0 - slack / cap);
        } else {
            // This bin cannot host the next item; mild penalty scaled by item size.
            score += 3.0 * (nxt / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: be pickier about wasteful placements.
        score += 1.5 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Global pressure: when many bins are open with high mean residual,
    // encourage consolidation into existing bins rather than spreading.
    if bin_residual != bin_capacity {
        let fill_ratio = 1.0 - residual / cap;
        score -= 4.0 * fill_ratio * (mean_residual / cap);
        // Time horizon: late in the stream, avoid opening new bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 5.0 * progress * fill_ratio;
    }

    // New-bin candidate handling: allow opening a fresh bin when the item is
    // large (poor fits elsewhere likely) or early when open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let large_item = item / cap;
        score -= 6.0 * large_item * (1.0 - progress);
        score += 4.0 * progress; // late stream: prefer existing bins
        if post > 50.0 {
            score += 5.0; // a fresh bin left over half-empty is wasteful
        }
    }

    // Mild noise-free tie-break via residual ordering.
    score += 0.01 * (residual - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with quadratic saturation so tiny
    // residuals are disproportionately rewarded (dead space matters more late).
    let mut score = norm_pr.powf(1.0 + 0.8 * progress);

    // Smooth non-linear coupling: post-residual vs stream progress.
    // Late in the stream, small residuals become valuable -> extra penalty
    // for large residuals, extra reward for small ones.
    let coupling = norm_pr * (1.0 - norm_pr) * (progress - 0.5);
    score += 6.0 * coupling;

    // Lookahead: reward bins whose post-residual still accommodates the next
    // item; penalize post-residuals that are "almost but not quite" usable.
    if next_item_size > 0 {
        let nxt = (next_item_size as f64).min(cap);
        let usable = if pr >= nxt { 1.0 } else { 0.0 };
        let near_miss = 1.0 - ((pr - nxt).abs() / (0.25 * cap)).clamp(0.0, 1.0);
        score -= 2.5 * usable * norm_pr * (1.0 - progress);
        score += 1.5 * near_miss * (1.0 - usable) * (1.0 - norm_pr);
    }

    // Tight fit reward: how well the item fills the current residual.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 3.0 * fill * fill * (1.0 - 0.5 * progress);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0 + 3.0 * (1.0 - norm_pr);
    }

    // New-bin candidate: penalize opening a new bin, more so when good
    // alternatives exist and the stream is early (future consolidation room).
    if bin_residual == bin_capacity {
        let alternatives = if fitting_bins_count > 1 { 1.0 } else { 0.0 };
        score += 4.0 + 6.0 * alternatives * (1.0 - 0.5 * progress);
        // A new bin is attractive if the item is large and the next item
        // would pair with it (smooth preference, not a hard rule).
        if next_item_size > 0 {
            let pair = (item_size as f64 + next_item_size as f64) / cap;
            score -= 4.0 * ((pair - 0.9).abs() / 0.5).clamp(0.0, 1.0);
        }
    }

    // Mild penalty tied to mean residual spread: avoid bins whose residual
    // deviates strongly from the fleet mean (keeps residuals homogeneous).
    score += 0.5 * ((pr - mean_residual) / cap).abs();

    // Slight preference for fewer open bins to encourage consolidation.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by capacity fraction / modulo structure
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class 0: perfect fit -> strong reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space classes: residuals that can never be filled by typical items
        // Items in [1,100]; residual classes via integer division thresholds.
        if post_residual < 10 {
            // tiny dead space, nearly useless
            score += 40.0;
        }
        // modulo arithmetic: residuals congruent to awkward classes mod common divisors
        let m = post_residual % 10;
        if m != 0 && post_residual < 25 {
            score += 15.0;
        }
        // integer-division class thresholds on post_residual
        let class = post_residual / 25; // 0..4
        score += class as f64 * 8.0;
    }

    // Reward tight fit relative to item size
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 30.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let next_fit = next_item_size as f64 / post;
            score -= next_fit * 60.0;
        } else {
            score += 25.0; // next item won't fit here
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening new bin unless terrible
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: neutral-ish baseline; open new bin only if all fits are bad
    if bin_residual == bin_capacity {
        // baseline score = full capacity; subtract small amount so it competes,
        // but bad fits into open bins (high post_residual penalties) will beat it
        score = cap * 0.85 - (item_size as f64) * 0.1;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 50.0;
        }
    }

    // Slight preference to keep fewer open bins when stream is early
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= (1.0 - progress) * 5.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins)
    if mean_residual > 0.0 {
        score += (post - mean_residual) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize residual that cannot fit the lookahead item but could have been useful.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }
    // Reward residuals that can accommodate the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }
    // Open-bin pressure: penalize spreading across many open bins.
    score += open_bins_count as f64 * 1.5;
    // Tight fit bonus: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 10.0;
    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }
    // New-bin candidate: keep it neutral-to-slightly-high unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 5.0 + mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact/near-exact matches with next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Tight match bonus: post_residual leaves room for the next item
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 1.5
                - diff * 0.8;
        } else {
            // post_residual too small for next item: penalize proportionally to wasted gap
            score += diff * 0.6;
        }
        // Perfect chaining: post_residual exactly equals next item size
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: prefer filling bins as tightly as possible
        score -= 10.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are "denser" — favor them
    let rel = post_residual as f64 - mean_residual;
    score += rel * 0.35;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when open bins could fit reasonably well
    if bin_residual == bin_capacity && bin_capacity >= item_size {
        let usable_open = if open_bins_count > 0 { open_bins_count } else { 1 };
        let waste = post_residual as f64;
        // New bin is attractive only if post_residual would be large AND lookahead fits
        let lookahead_bonus = if next_item_size > 0 && post_residual >= next_item_size {
            5.0
        } else {
            0.0
        };
        score = waste + 15.0 - lookahead_bonus
            + (usable_open as f64).min(5.0) * 2.0;
    }

    // Dead-space penalty: small unusable post-residuals (nonzero but < min item 1 handled
    // generically) — penalize any post_residual in a "hard to fill" band
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Slight stream-progression pressure: later in the stream, favor consolidation
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later (below min item size 1..100 unknown, assume >=10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual > 0 && post_residual < 25 {
        score += 12.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive if current
    // open bins are crowded or this is a last-chance mismatch.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so existing decent bins win.
        score += 55.0;
        // If many bins fit the item, definitely prefer them.
        if fitting_bins_count > 1 {
            score += 30.0;
        }
        // If only this new bin fits (no open bin can), it is forced.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Crowded state: many open bins with low mean residual -> new bin is fine.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if mean_residual < 20.0 && open_bins_count > 3 {
            score -= 25.0 * (1.0 - progress * 0.5);
        }
    } else {
        // Last-chance bin: strongly favor using it to avoid opening a bin.
        if fitting_bins_count == 1 {
            score -= 35.0;
        }
        // Reward filling bins that are already mostly full.
        let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 10.0 * fill;
    }

    // Lookahead: if the next item could exactly use this bin's post_residual,
    // leaving it is valuable; otherwise prefer consuming the space now.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if (next_item_size as i64 - post_residual as i64).abs() <= 5 {
            score -= 12.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            // dead space for the known next item
            score += 8.0;
        }
    } else {
        // Last item: exhaust bins aggressively.
        score -= 20.0;
    }

    // Global residual balance: prefer bins whose residual is near the mean
    // (keeps open bins homogeneous, easier future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Mild time pressure: late in the stream, consolidate into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: post-residual, smoothly warped by progress
    let mut score = r * (1.0 + 0.6 * progress * rn);

    // Non-linear coupling: penalize large residuals early, reward tight fits late
    score += 12.0 * progress * rn * rn * cap;

    // Tight-fit bonus: quadratic reward for small post-residual
    score -= (cap - r) * (cap - r) / cap * (1.2 - 0.5 * progress);

    // Dead-space penalty: residuals too small for typical future items
    let dead = (1.0 - (r / cap).powi(2)) * (r / 10.0).floor() * 0.5;
    score += dead * (1.0 - progress);

    // Lookahead: reward residuals that can fit the next item
    if next_item_size > 0 {
        let fits_next = if r >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= 8.0 * fits_next * (1.0 - progress) * (next_item_size as f64 / cap);
    }

    // Last-chance bin: strong preference to use it rather than open new
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.4 * progress);
    }

    // Crowding: discourage spreading when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * 0.8 * rn;

    // Mean-residual alignment: prefer bins near the mean residual (balanced packing)
    score += 0.3 * (r - mean_residual).abs();

    // New-bin candidate: mild penalty so it is chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo small moduli.
    let pr = post_residual;
    // Perfect-fit reward
    if pr == 0 {
        score -= 1000.0;
    }
    // Dead-space classes: tiny residuals are almost unusable (items >= 1..100,
    // but small leftovers below ~15 are poor unless they fit next item).
    if pr > 0 && pr < 10 {
        score += 40.0;
    }
    // Harmonic thresholds: residuals that are multiples of common item sizes
    // (e.g., 25, 50) are more reusable.
    if pr % 25 == 0 && pr > 0 {
        score -= 15.0;
    }
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 250.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
            // Harmonic bonus: post_residual - next leaves a harmonic class value
            let nr = pr - next_item_size;
            if nr % 20 == 0 { score -= 12.0; }
        } else {
            // next item cannot use this residual at all: slight penalty
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are large.
    if bin_residual == bin_capacity {
        score += 55.0;
        if mean_residual < item_size as f64 * 0.5 {
            score -= 30.0; // open bins are nearly full -> new bin reasonable
        }
    }

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.5;

    // Progress-dependent tightening: later in stream, prefer tight fits more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any future item are wasted.
    let min_item = 1.0f64;
    let pr = post_residual as f64;
    if pr > 0.0 && (pr as u32) < next_item_size {
        // Gap cannot host the lookahead item: penalize heavily.
        score += 60.0 * (1.0 - pr / (next_item_size.max(1) as f64));
    }
    if pr > 0.0 && pr < min_item {
        score += 100.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Reward tight fits (small post_residual relative to residual).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * tightness * tightness;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidation;
    // with few bins, opening a new one is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual deviates from mean (keep some bins tight, others flexible).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Favor bins that can still host the next item after placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins fit badly.
    if bin_residual == bin_capacity {
        score += 45.0 + 4.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect fits (post_residual == 0).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            // next item fits but leaves more waste; penalize proportionally to leftover waste.
            let waste_after_next = post_residual - next_item_size;
            score += waste_after_next as f64 * 1.5;
        } else {
            // next item does NOT fit here: this residual is likely dead space; penalize.
            score += (next_item_size - post_residual) as f64 * 2.0;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins with residual below the mean
    // (tighter bins get filled first, keeping roomier bins flexible).
    score += (mean_residual - bin_residual as f64) * 0.8;

    // Penalize very small residuals that are hard to fill (dead space risk),
    // unless they are zero (perfect fit already handled).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity equal to the item.
    // Only attractive when no open bin offers a good fit (post_residual small or exact).
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 120.0;
        // But if next item is large and current item leaves a large residual,
        // a fresh bin may pair well; soften slightly.
        if next_item_size >= 60 && post_residual >= 20 {
            score -= 40.0;
        }
        // Late in the stream, opening new bins is less costly (fewer future items to place).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 30.0;
    }

    // Mild penalty for many open bins already (encourage consolidation).
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (low post_residual) — already encoded above.

    // Lookahead reward: if the next item fits exactly into the post residual,
    // strongly favor this bin (chain placement).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Penalize leaving a residual that is too small for the next item
    // (dead space trap), scaled by how close it is to being useless.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let deadness = post_residual as f64 / next_item_size as f64;
        score += 6.0 * (1.0 - deadness);
    }

    // Perfect-fill bonus: exact fit is always great.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (residual == capacity): penalize opening a new bin
    // by default, but the penalty shrinks when open bins have fragmented
    // residuals (mean residual low relative to item) or when many bins are
    // already open and this item would leave a very tight fit elsewhere.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 18.0;
        // If mean residual across open bins is small, keeping bins tight is
        // hard; allow opening new bins more readily.
        new_bin_penalty -= 10.0 * (1.0 - mean_residual / bin_capacity as f64).max(0.0);
        // Early in stream, slightly prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_penalty += 6.0 * (1.0 - progress);
        // If only one bin fits and it's not this one, we already reward that
        // bin; keep new bin clearly worse.
        score += new_bin_penalty.max(2.0);
    }

    // Mild penalty for wasting space relative to mean residual state:
    // placing into a bin whose residual is far above the mean tends to
    // fragment the pool; prefer bins with residuals near the item size.
    let residual_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * residual_gap;

    // Slight preference to balance load across many open bins.
    if open_bins_count > 1 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Base: quadratic coupling of post_residual (waste grows super-linearly).
    let mut score = pr * (1.0 + 0.008 * pr);

    // Normalize post_residual against capacity and couple polynomially with progress.
    let prn = pr / cap;
    score += 20.0 * prn * prn * (1.0 + progress);

    // Lookahead coupling: reward residuals that can host the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = (pr - ni) / cap;
            score -= 6.0 * (1.0 - slack) * (1.0 - progress);
        } else {
            let gap = (ni - pr) / cap;
            score += 8.0 * gap * gap;
        }
    }

    // Penalize opening a new bin when existing bins can fit, more so late in stream.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0 + 10.0 * progress + (open_bins_count as f64).sqrt() * 2.0;
        if fitting_bins_count > 0 {
            score += 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid fragmentation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0 + 5.0 * progress;
    }

    // Mild attraction toward bins near the mean residual (balanced packing).
    score += 0.05 * ((bin_residual as f64) - mean_residual).abs();

    // Smooth progress term: early stream, tolerate slack; late stream, tighten.
    score += 5.0 * (1.0 - progress) * prn - 3.0 * progress * (1.0 - prn);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by integer division thresholds
    let post = post_residual as f64;
    let class = (post_residual / 10).min(9) as f64; // 0..9 harmonic class

    // Reward tight fits: post_residual in low classes is good
    score -= (9.0 - class) * 6.0;

    // Non-linear penalty for awkward dead space (post_residual just above 0 but too small for typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Modulo coupling: post_residual mod 10 near zero means divisible-friendly residual
    let m = post_residual % 10;
    if m == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // next item cannot fit here; mild penalty scaled by how much it misses
            let miss = (next_item_size - post_residual) as f64;
            score += 5.0 * (miss / cap).min(1.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity equal to residual left behind
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: prefer it only when existing bins fit poorly
        score = cap * 0.75;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative, must open
        }
        // Late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If mean residual across open bins is large, opening new bins is wasteful
        score += (mean_residual / cap).min(1.0) * 20.0;
        // Large items prefer fresh bins
        if item_size >= 50 {
            score -= 15.0;
        }
    }

    // Prefer filling bins that are already relatively full
    let fill = 1.0 - bin_residual as f64 / cap;
    score -= fill * 8.0;

    // Slight preference for keeping number of open bins moderate
    if open_bins_count > 8 && bin_residual < bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Non-linear penalty on moderate dead space (hard to fill later).
    if post_residual > 0 {
        let pr = post_residual as f64;
        score += 40.0 / pr; // tiny gaps hurt most
        if pr < 25.0 {
            score += (25.0 - pr) * 0.8;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward tight fits relative to bin_residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // and discourage opening new bins.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins and progress.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + pressure * 4.0 + progress * 20.0;
        // Allow a new bin only if no bin fits well (large dead space everywhere).
        if mean_residual < item_size as f64 + 5.0 {
            score -= 30.0;
        }
        // If item is large, opening a fresh bin is more acceptable.
        if item_size > 60 {
            score -= 10.0;
        }
    } else {
        // Reward using existing bins when many are open.
        score -= pressure * 0.5;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits into post_residual, bonus.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 20.0;
    }
    // Penalize leaving a gap just smaller than the next item (near-miss dead space).
    if next_item_size > 0 && post_residual >= next_item_size.saturating_sub(3) && post_residual < next_item_size {
        score += 25.0;
    }

    // Slight preference for bins below mean residual (balance).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small dead space relative to capacity).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly (or nearly) matches the next item's size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        let match_bonus = if gap == 0.0 {
            60.0
        } else if gap <= 10.0 {
            40.0 - 2.0 * gap
        } else {
            0.0
        };
        score -= match_bonus;

        // Penalize leaving a residual that neither fits the next item well
        // nor is large enough to remain useful.
        if post_residual > 0 && post_residual < next_item_size {
            score += 15.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // Last item: minimize leftover waste aggressively.
        score += 25.0 * fit_ratio;
    }

    // Compare against mean residual: bins already tighter than average are
    // preferred targets (consolidate fragmentation).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer reusing open bins unless the fit is poor.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.3 * open_bins_count as f64;
        // Opening a new bin is attractive if the item is large relative to
        // what open bins can absorb (poor fits everywhere).
        if fitting_bins_count > 0 && post_residual < 10 {
            score -= 25.0; // large item with near-perfect fill: fresh bin is fine
        }
    }

    // Mild stream-progression pressure: late in the stream, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot even hold the smallest plausible item (1..100 unknown, use next_item_size if known).
    let dead_threshold = if next_item_size > 0 { next_item_size } else { 1 };
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0; // fully dead space
    } else if post_residual > 0 {
        // Dead-space ratio relative to capacity: waste grows superlinearly.
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        score += 25.0 * waste_ratio * waste_ratio;
    }

    // Lookahead coupling: reward if the next item fits exactly into the post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // perfect chain
        } else if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize more if we leave a big unusable gap
            score += 6.0 * (post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; only attractive
    // when all open bins would leave large waste.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress and open-bin load.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_score = 55.0 + 20.0 * progress;

        // If existing bins fit poorly (mean residual much larger than item), a fresh bin may be better.
        let fit_gap = mean_residual - item_size as f64;
        if fit_gap > 0.0 {
            new_bin_score -= 10.0 * (fit_gap / bin_capacity as f64);
        } else {
            new_bin_score += 15.0; // open bins fit well; discourage new bin
        }

        // Many open bins with small residuals: prefer consolidating into them.
        new_bin_score += 2.0 * (open_bins_count as f64).sqrt();

        // A new empty bin perfectly fits any item: give a mild tightness credit.
        new_bin_score -= 12.0 * tightness * tightness;

        score = new_bin_score;
    }

    // Global residual pressure: when mean residual is small, waste is costlier.
    let pressure = 1.0 - mean_residual / bin_capacity as f64;
    score += 5.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Slight time decay: later in the stream, prefer minimizing immediate waste more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let t = progress;
    let poly = pr * pr * (0.5 + 0.5 * t) - pr * (1.0 - t) * 2.0;
    score += 0.01 * poly;

    // Penalize large post_residual more late in the stream
    score += (pr / bin_capacity as f64).powi(3) * (50.0 + 100.0 * t);

    // Reward tight fits
    score -= (item_size as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: reward leaving space for next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            score -= 10.0 * (1.0 - (post_residual as f64 - nxt) / bin_capacity as f64);
        } else {
            score += 5.0;
        }
    }

    // Mild penalty for spreading across many bins
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: keep it slightly unattractive unless fit is bad
    if bin_residual == bin_capacity {
        score += 15.0 - 20.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward small, well-structured residuals.
    let pr = post_residual as u32;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 5 {
        score -= 35.0;
    } else if pr <= 15 {
        score -= 15.0;
    } else {
        // penalize residuals in "dead zone" that few item sizes can reuse
        let dead = if pr < 10 { 1.0 } else { 0.0 };
        score += 10.0 * dead;
    }

    // Modulo structure: residuals that are multiples of common item sizes are reusable.
    let reusable = [10u32, 20, 25, 30, 40, 50];
    let mut bonus = 0.0;
    for &r in reusable.iter() {
        if pr >= r && pr % r == 0 {
            bonus += 6.0;
        }
        if next_item_size > 0 && pr >= next_item_size && pr % next_item_size == 0 && next_item_size >= 10 {
            bonus += 8.0;
        }
    }
    score -= bonus;

    // Exact lookahead fit: strongly favor placing item so next item fits too.
    if next_item_size > 0 && next_item_size <= pr {
        let tight = (pr - next_item_size) as f64;
        score -= 20.0 * (1.0 - tight / cap);
    } else if next_item_size > 0 {
        score += 12.0; // next item won't fit here; this bin likely closes
    }

    // Fractional capacity coupling: prefer filling a large fraction of the bin.
    let fill_frac = item_size as f64 / cap;
    score -= 25.0 * fill_frac * fill_frac;

    // Last-chance bin: if this is the only fitting bin, avoid forcing a bad fit.
    if fitting_bins_count == 1 && pr > 30 {
        score += 8.0;
    }

    // New-bin candidate: only attractive when current bin would leave a big awkward residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let awkward = if pr > 40 { 1.0 } else { 0.0 };
        score += 30.0 - 25.0 * awkward - 10.0 * progress;
    }

    // Mean residual context: penalize bins far above mean residual (poor relative fit).
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize small unusable gaps (dead space) much harder than large gaps.
    // A gap is "dead" if it's too small for the smallest plausible item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 40.0; // risky gap: only tiny items can use it
    }

    // Reward tight fits: fraction of residual consumed by the item
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Lookahead: if next item fits exactly into post_residual, strongly reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_tight = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - next_tight / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // next item won't fit here; penalize leaving stranded residual
        score += 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Pressure from many open bins: prefer filling existing bins over opening new ones
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize opening when many bins are open
        score += 50.0 + 8.0 * open_bins_count as f64;
        // but if no real bins fit, the new-bin call should win naturally
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
    } else {
        score -= 3.0 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins below mean residual (denser bins)
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Early stream: be slightly more tolerant of opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: bin becomes exactly full after next item
        } else if post_residual >= next_item_size {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * next_fit; // next item likely fits well here too
        } else {
            // next item cannot use the leftover; penalize dead space proportionally
            score += 0.4 * post_residual as f64;
        }
    }

    // Relative to mean residual: avoid wasting space when other bins are tighter.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive if item is large or no good fit exists.
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - fit_ratio);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Early in stream: slightly discourage hoarding many open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size > post_residual {
            // Dead space that the next item cannot use — mild penalty.
            score += 8.0;
        } else {
            // Next item fits: leave usable room, small reward proportional to leftover.
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decreasing as stream matures (amortization).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 55.0 - 15.0 * progress;
        // If many open bins have large mean residual, packing there is likely fine.
        new_bin_cost += (mean_residual - post_residual as f64).max(0.0) * 0.5;
        // If this bin is the only fitting option elsewhere, opening new bin is wasteful.
        if fitting_bins_count == 1 {
            new_bin_cost += 40.0;
        }
        score += new_bin_cost;
    } else {
        // Reward using bins that are already open (avoid bin proliferation).
        score -= 5.0;
        // Prefer bins with below-mean residual (filling emptier bins evenly vs. tightly):
        // favor bins tighter than average.
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 3.0;
        }
    }

    // Penalize leaving awkward mid-range dead space (hard to fill later).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Slight pressure to consolidate as the stream ends.
    let tail = if total_items > 0 && step_index + 1 >= total_items.saturating_sub(5) { 1.0 } else { 0.0 };
    score -= tail * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let poly = norm_pr * norm_pr * (1.0 + progress) + norm_pr * progress * progress;
    score += 40.0 * poly;

    // Reward tight fits, more strongly as the stream progresses.
    let tight = 1.0 - norm_pr;
    score -= 30.0 * tight * tight * (0.5 + progress);

    // Penalize large dead space relative to mean residual of open bins.
    if mean_residual > 0.0 {
        let ratio = pr / mean_residual;
        score += 10.0 * ratio * ratio * (1.0 - progress);
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 25.0 * (1.0 - slack * slack);
        } else {
            score += 15.0 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    // Mild penalty for proliferating bins late in the stream.
    score += (open_bins_count as f64).sqrt() * progress * 2.0;

    // New-bin candidate: keep it slightly unattractive unless residuals are tight.
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue classes mod 10 / mod 20.
    let pr = post_residual as i64;
    let cap = bin_capacity as f64;

    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Small dead space that is still "harmonically usable" (multiple of 10) is fine.
        let dead = post_residual;
        if dead % 10 == 0 {
            score -= 5.0 + (dead / 10) as f64; // divisible residuals are reusable
        } else {
            // awkward residue: penalize proportionally to how far from a class boundary
            let r = (dead % 10) as f64;
            score += 2.0 * (10.0 - r);
        }
    }

    // Coupling with next item (k=2 lookahead): if next item fits the post residual,
    // reward; if next item is just barely too big, penalize (near-miss creates waste).
    if next_item_size > 0 {
        if (next_item_size as i64) <= pr {
            score -= 8.0;
            // exact harmonic match of next item to post residual
            if (next_item_size as i64) == pr { score -= 20.0; }
        } else {
            let miss = next_item_size as i64 - pr;
            if miss <= 10 { score += 6.0 + miss as f64; }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.3 * open_bins_count as f64;
        if post_residual as f64 > cap * 0.5 && next_item_size as u32 <= item_size {
            score += 10.0; // fresh bin fine when item is small-ish
        }
    }

    // Prefer tighter fits relative to capacity fraction.
    score += (1.0 - (item_size as f64) / cap) * 4.0;

    // Early stream: be slightly more willing to spread items across bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 3.0;

    // Mean-residual coupling: if this bin's residual is far above mean, mildly discourage.
    score += 0.15 * ((post_residual as f64) - mean_residual).abs().min(30.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any leftover gap that is too small to hold
    // even the smallest future item (size >= 1..=10 typical) is waste.
    if post_residual > 0 && post_residual < 10 {
        // Unusable sliver: heavily penalize, scaled by how close to useless it is.
        score += (10 - post_residual) as f64 * 12.0;
    } else if post_residual == 0 {
        // Perfect fill is the best outcome.
        score -= 60.0;
    }

    // Reward tight fits: fraction of the bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 25.0;

    // Prefer bins whose residual is close to the item (minimal waste ratio).
    if bin_residual > 0 {
        let waste_ratio = post_residual as f64 / bin_residual as f64;
        score += waste_ratio * 20.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score += (10 - slack) as f64 * 6.0; // would create a new sliver
            } else {
                score -= 10.0;
            }
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.5;

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is justified only when existing fits are poor
        // (many open bins already, or the only alternative creates slivers).
        // Base cost of a fresh bin grows with the number of open bins.
        score = bin_capacity as f64 + pressure * 3.0;
        // Late in the stream, slightly discourage spawning extra bins.
        score += progress * 15.0;
        // If this is the last chance bin, opening a new bin is wasteful.
        if fitting_bins_count == 1 {
            score += 80.0;
        }
        return score;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Mild alignment with the average residual state: bins far below the
    // mean residual are already "loose"; prefer placing into bins whose
    // residual is near the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 8.0 * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 5.0 {
            score -= 15.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item can't follow here; mild penalty proportional to waste
        score += 1.5;
    }

    // Last chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // existing bins are crowded or the fit is terrible.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64).ln().max(0.5);
        let poor_fit = (item_size as f64 / bin_capacity as f64) < 0.5;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 25.0 + crowding * 6.0;
        if poor_fit {
            new_bin_score -= 10.0;
        }
        // Late in stream, prefer consolidating into open bins.
        new_bin_score += 10.0 * progress;
        // If mean residual across open bins is small, opening is justified.
        if mean_residual < item_size as f64 {
            new_bin_score -= 18.0;
        }
        score += new_bin_score;
    }

    // Prefer bins whose residual deviates favorably from mean (balanced packing).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Small bonus for filling bins completely as stream progresses.
    score -= 2.0 * tightness * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // smooth polynomial coupling of post_residual with stream progress
    let progress_weight = 0.5 + 1.5 * t * t;
    score *= progress_weight;

    // penalize large dead space non-linearly
    score += 8.0 * norm_pr * norm_pr * (1.0 + t);

    // reward tight fits (small post_residual relative to capacity)
    score -= (1.0 - norm_pr).powi(3) * 6.0;

    // last-chance bin: strongly favor
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 5.0 * (1.0 - t);
    } else if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 2.0 * t;
    }

    // discourage spreading across too many bins late in stream
    score += 0.4 * open_bins_count as f64 * t;

    // compare against mean residual: penalize leaving this bin far above mean
    score += 0.3 * (pr - mean_residual).abs();

    // new-bin candidate: mild penalty so it's chosen only when open bins are poor
    if bin_residual == bin_capacity {
        score += 4.0 + 3.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "capacity fraction band" it lands in.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let post = post_residual;

    // Dead-space penalty: residuals that are small but nonzero are nearly useless.
    if post > 0 && post < quarter {
        score += (quarter - post) as f64 * 0.9;
    }
    // Residuals in the "awkward middle" band (just over quarter) are semi-usable.
    if post >= quarter && post < half {
        score -= (post - quarter) as f64 * 0.35;
    }
    // Perfect or near-perfect fits are heavily rewarded.
    if post == 0 {
        score -= 60.0;
    } else if post <= 5 {
        score -= 25.0;
    }

    // Integer-division thresholds: reward leaving room divisible into common item chunks.
    if post >= 10 && post % 10 == 0 {
        score -= 8.0;
    }
    if post >= next_item_size && next_item_size > 0 {
        // This bin can also host the lookahead item: strong reward.
        score -= 12.0;
        // Extra reward if post_residual exactly matches next item (chained perfect fit).
        if post == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 && post > 0 {
        // Lookahead won't fit here: mild penalty proportional to wasted opportunity.
        score += (next_item_size.min(post)) as f64 * 0.15;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin gives a decent fit. Penalize the fresh bin unless the item is
    // large relative to residual space or fits are scarce.
    if bin_residual == bin_capacity {
        let base_penalty = 45.0;
        let scarcity_bonus = if fitting_bins_count == 0 { 100.0 } else { 0.0 };
        let big_item_bonus = if item_size as f64 > 0.7 * cap { 35.0 } else { 0.0 };
        let mean_gap = (mean_residual - item_size as f64).max(0.0);
        score = base_penalty - scarcity_bonus - big_item_bonus + mean_gap * 0.5
            + (open_bins_count as f64).min(10.0) * 2.0;
    }

    // Slight preference to fill earlier-opened bins as stream progresses.
    score += (step_index as f64 / (total_items.max(1) as f64)) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize residuals too small to hold even the smallest plausible item (1..10).
    if post_residual < 5 {
        score += 30.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = (post_residual as f64) / (item_size.max(1) as f64);
    score += 12.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open bins pressure: many open bins -> discourage spreading, prefer filling existing bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(0.0) / 10.0);
    score += 0.8 * pressure;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless post_residual is dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual >= 10 {
            score -= 10.0;
        }
    }

    // New-bin candidate: make empty bin attractive only when no open bin offers
    // a good fit (i.e., this item would leave a large dead gap in every open bin).
    if bin_residual == bin_capacity {
        // Baseline neutral score; opening new bin is favored if open bins have poor fits.
        score = bin_capacity as f64 * 0.5;
        // If the item is large relative to residual patterns, new bin is fine.
        if item_size >= 60 {
            score -= 10.0;
        }
        // Early stream: opening bins cheaply is fine.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
        // Many open bins with slack -> discourage another bin.
        if mean_residual > 30.0 && open_bins_count > 2 {
            score += 25.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 5 {
            score -= 15.0;
        } else {
            score -= 3.0;
        }
    }
    // Penalize if next item would be blocked by the resulting residual.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size.min(20) {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post residual exactly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // Next item fits: reward tight coupling (perfect match gets big bonus).
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 40.0;
            }
        } else {
            // Next item does not fit: penalize wasted space that blocks lookahead.
            score += 0.5 * (post_residual as f64 - (bin_capacity as f64 - nxt)).max(0.0);
        }
    }

    // Compare post_residual against mean residual: prefer leaving residuals near the mean
    // (balanced bins), penalize outliers creating dead space.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin when good open bins exist, unless residual would be tiny.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, discounted if current fit is poor.
        score += 20.0;
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score += 15.0; // extra penalty if an open bin would serve both items
        }
        // Late in the stream, be more conservative about opening bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Reward very tight fits (low post residual) nonlinearly.
    score -= 10.0 * (-post_residual as f64 / 20.0).exp();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual small).
    score -= (item_size as f64 / bin_capacity as f64) * 30.0;

    // Penalize waste relative to mean residual across open bins.
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.35;

    // Lookahead: if the next item fits exactly into the post_residual,
    // heavily reward this placement (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty proportional to leftover
            score += 3.0;
        }
    } else {
        // Last item: minimize leftover waste hard.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive
    // if the item is large or all existing fits would waste a lot.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_penalty = (mean_residual - post_residual as f64).max(0.0);
        // Base cost of opening a new bin, decaying as stream progresses.
        score += 18.0 - 8.0 * progress;
        // If placing in an existing bin would leave a very large residual
        // that no plausible future item can use, new bin looks better.
        if post_residual < 10 {
            score += 15.0; // item nearly fills a fresh bin: great
        }
        if waste_penalty > 40.0 {
            score -= 6.0; // existing bins are very full anyway
        }
        // Many open bins: discourage spreading further.
        score += open_bins_count as f64 * 0.4;
    }

    // Small dynamic time-horizon coupling: late in the stream, prefer
    // consolidating into fewest bins (favor fuller bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 10.0 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1]
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Smooth non-linear coupling: normalized post-residual raised to powers,
    // modulated by progress via sin/cos style smooth terms.
    let pr_norm = pr / cap; // in [0,1)
    let tight = 1.0 - pr_norm; // how "filled" the bin becomes

    // Reward tight fits, scaled by progress (later in stream, value tightness more)
    score -= 40.0 * tight * tight * (0.5 + 0.5 * progress);

    // Polynomial coupling of post_residual with progress:
    // mid-sized residuals are penalized quadratically (dead space), eased early on.
    let dead = pr_norm * (1.0 - pr_norm); // peaks at pr_norm = 0.5
    score += 30.0 * dead * dead * (1.0 - progress);

    // Smooth interaction: post_residual vs next item lookahead
    if next_item_size > 0 {
        let nx = (next_item_size as f64).min(cap) / cap;
        // If next item exactly matches post residual (smooth closeness), reward
        let match_term = 1.0 - (pr_norm - nx).abs();
        if match_term > 0.0 {
            score -= 25.0 * match_term * match_term * match_term;
        }
        // Penalize if post residual is a small unusable sliver relative to next item
        let sliver = (pr_norm - nx).max(0.0);
        score += 20.0 * sliver * sliver * (0.3 + 0.7 * progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0 + 20.0 * progress;
    } else if fitting_bins_count > 2 {
        // Plenty of alternatives: slight penalty to prefer best-fit discrimination
        score += 3.0 * ((fitting_bins_count as f64 - 2.0).min(5.0));
    }

    // Coupling with mean residual across open bins: prefer bins below mean residual
    // (fill the emptier bins first), smooth quadratic term.
    let mean_pr = mean_residual / cap;
    let diff = pr_norm - mean_pr;
    score += 12.0 * diff * diff - 6.0 * diff;

    // Open-bin count pressure: many open bins -> encourage consolidation into existing bins
    let open_pressure = (open_bins_count as f64 / (1.0 + open_bins_count as f64)) * (1.0 - pr_norm);
    score += 15.0 * open_pressure * (0.5 + 0.5 * progress);

    // New-bin candidate: penalize opening a fresh bin unless current bins would leave bad waste
    if bin_residual == bin_capacity {
        let waste_elsewhere = mean_residual / cap;
        score = 55.0
            + 30.0 * (1.0 - progress)
            + 40.0 * waste_elsewhere * waste_elsewhere
            - 25.0 * (fitting_bins_count as f64).min(4.0);
        // If lookahead fits well into a fresh bin, ease the penalty
        if next_item_size > 0 {
            let nx = (next_item_size as f64).min(cap) / cap;
            score -= 20.0 * (1.0 - nx) * (1.0 - nx) * progress;
        }
    }

    // Tiny smooth jitter-free regularizer
    score += 0.01 * (progress * std::f64::consts::PI).sin() * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward small post_residual (tight fit)
    score -= 2.0 * (1.0 - pr / cap).powi(3) * cap * 0.5;

    // Penalize residuals in "dead zones": too small for typical items (1..100 unknown,
    // but small residuals < 10 are nearly unusable)
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Harmonic classes: post_residual divisible by common item sizes is reusable
    for m in [10u32, 20, 25, 50] {
        if post_residual % m == 0 && post_residual > 0 {
            score -= 8.0;
            break;
        }
    }

    // Next-item lookahead: if next item fits in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 + (next_item_size as f64) * 0.1;
        } else {
            // waste potential: post_residual can't hold next item
            score += 3.0 * (1.0 - (next_item_size as f64 - pr).abs() / cap);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Many fitting bins: this placement is less critical, slight penalty for waste
    if fitting_bins_count > 3 {
        score += 2.0;
    }

    // Progress-based tuning: early stream, prefer consolidating into few bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * mean_residual * 0.05;

    // New-bin candidate: penalize opening a new bin unless residuals are all bad
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 35.0; // big items may warrant fresh bin
        }
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 28.0; // existing bins nearly full -> open new
        }
    }

    // Integer-division threshold coupling on item size classes
    let item_class = item_size / 25; // 0..3
    score -= item_class as f64 * 1.5 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps (< 10)
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    } else if post_residual == 0 {
        score -= 60.0; // perfect fit strongly rewarded
    }

    // Penalize moderate dead space relative to bin capacity
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * dead_frac * dead_frac;

    // Open-bin pressure: prefer filling existing bins over opening new ones
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    }
    // If next item would leave this bin's residual unusable, add mild penalty
    if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 10 && (post_residual - next_item_size) > 0 {
        score += 10.0;
    }

    // Mean residual coupling: prefer bins with residual below mean (tighter bins)
    score -= (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate: penalize opening a new bin unless existing fits are bad
    if bin_residual == bin_capacity {
        score += 35.0 + open_bins_count as f64 * 1.5;
        // Exception: if item is large and only poor fits exist, opening is fine
        if item_size > bin_capacity / 2 && fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Stream progression: slightly relax new-bin penalty late in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward exact/near-exact fits strongly.
    let perfect_fit = (post_residual as f64) / bin_capacity as f64;
    score -= 40.0 * (-perfect_fit * 30.0).exp();

    // Aggressive 2-step lookahead: if the next item fits exactly in the post residual,
    // this is a great chained placement.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item can chain into this bin: reward tight chaining.
            score -= 25.0 * (-lookahead_gap / 12.0).exp();
        } else {
            // Next item cannot fit here: mild penalty scaled by wasted potential.
            score += 8.0 * (1.0 - (-lookahead_gap / 20.0).exp());
        }
    }

    // Penalize residuals too small for typical future items (dead space).
    if post_residual < 10 {
        score -= 15.0; // near-perfect fill is excellent
    } else if post_residual < 30 {
        // small but nonzero residual: moderately risky
        score += 3.0 * (30.0 - post_residual as f64) / 20.0;
    }

    // Relative-to-mean coupling: prefer bins whose post residual stays near the
    // mean residual so the pool of open bins remains usable.
    score += 0.35 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.1 * item_size as f64;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open
    // bin fits well. Penalize the empty-bin candidate by default; relax the penalty
    // as the stream progresses and open bins accumulate fragmentation.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        let new_bin_penalty = 45.0 - 25.0 * progress - 30.0 * fragmentation;
        // If the current item is huge relative to capacity, a fresh bin is fine.
        let big_item_relief = if item_size as f64 > 0.6 * bin_capacity as f64 { 15.0 } else { 0.0 };
        score += (new_bin_penalty - big_item_relief).max(5.0);
    }

    // Mild penalty for spreading across many open bins: prefer consolidating.
    score += 0.05 * open_bins_count as f64;

    // Tie-break: slightly prefer bins with larger residual for big items.
    score -= 0.02 * item_size as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 20.0;

    // Penalize dead space relative to capacity.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += dead * dead * 30.0;

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post-residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + next_item_size as f64 * 0.1;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalize creating a gap too small for the next item (dead space).
        score += 8.0;
    }

    // Global state: many open bins -> prefer filling existing ones, penalize new bins.
    let new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if new_bin {
        score += 15.0 + open_bins_count as f64 * 2.0;
        // But if no existing bin fits well, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.25 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - post / cap; // fraction of bin used after placement

    // Base: prefer filling bins tightly (low post_residual).
    let mut score = post;

    // Non-linear dead-space penalty: small residuals are hard to reuse.
    let x = post / cap;
    score += 40.0 * (1.0 - x) * (1.0 - x) * x * (1.0 - x).exp();

    // Reward tight fits more strongly as the stream progresses.
    score -= 30.0 * fill * fill * (0.5 + progress);

    // Exact fit bonus (smooth, non-piecewise).
    score -= 50.0 * (-post as f64 / 5.0).exp();

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate (residual == capacity): penalize unless current bins are very full.
    let is_new = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new {
        score += 35.0 + 30.0 * (1.0 - progress) + 0.2 * mean_residual;
        // Allow opening new bin when existing bins would leave large dead space anyway.
        score -= 20.0 * (post / cap) * (post / cap);
    }

    // Lookahead: if next item fits exactly into resulting residual, reward.
    if next_item_size > 0 {
        let diff = (post - next_item_size as f64).abs();
        score -= 25.0 * (-diff / 8.0).exp();
    }

    // Mild pressure to consolidate into fewer bins.
    score += 0.05 * open_bins_count as f64 * (1.0 - fill);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the bin.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic class logic: partition residual space into capacity-fraction classes.
    // Residuals that fall into "usable" classes (>= 10, or multiples of common item
    // sizes) are less dead than odd tiny slivers.
    let class = post_residual / 10; // integer division class 0..10
    let class_penalty = match class {
        0 => 60.0,                   // unusable sliver (<10)
        1 => 15.0,                   // barely usable
        2 => 5.0,
        3 => 0.0,                    // sweet spot ~30-40
        4 => 0.0,
        5 => 2.0,
        6 => 6.0,
        7 => 12.0,
        8 => 20.0,
        9 => 30.0,
        _ => 0.0,                    // fresh bin (class 10)
    };
    score += class_penalty;

    // Modulo arithmetic: residual that is a multiple of small item sizes can pair
    // with future items cleanly.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: reward if next item fits exactly in the post-residual,
    // penalize if next item leaves another awkward sliver.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            let next_post = post_residual - next_item_size;
            score -= 10.0 * (1.0 - (next_post as f64) / (bin_capacity as f64));
            if next_post < 10 {
                score += 8.0; // creates a dead sliver
            }
        } else {
            // next item can't use this bin's remainder; slight penalty for wasted pairing
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual < 10 {
            score += 30.0; // but not if it strands a dead sliver
        }
    }

    // New-bin candidate handling: opening a new bin is expensive early, cheaper late.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score = 150.0 - 40.0 * progress;
        // Prefer a new bin if all open bins fit poorly (large mean residual waste).
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.min(bin_capacity) {
            score -= 10.0;
        }
    }

    // Mild pressure against hoarding many open bins with scattered residuals.
    score += 0.5 * open_bins_count as f64 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical items are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 45.0; // unusable sliver
        } else if post_residual < 20 {
            score += 18.0; // only fits tiny items
        } else if post_residual < 35 {
            score += 6.0; // marginal gap
        } else {
            score -= 8.0; // large usable gap is fine
        }
    } else {
        // Perfect fit: strongly reward.
        score -= 60.0;
    }

    // Reward tight fits overall (small post_residual relative to item size).
    score -= (item_size as f64) * 0.35;

    // Reward bins whose residual is close to the item (best-fit style).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score -= 12.0 / (1.0 + gap);

    // Open-bin pressure: discourage scattering into many bins.
    score += open_bins_count as f64 * 0.8;

    // Mean residual coupling: prefer placing into bins with residual near mean
    // (keeps bin states uniform); penalize outliers.
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive if
    // this item is large relative to the lookahead or nothing fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0 + open_bins_count as f64 * 2.0;
        // If item fills a fresh bin well and next item is large, opening is good.
        if item_size >= 70 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            // Next item cannot share this fresh bin anyway; slight relief.
            score -= 5.0;
        }
        // Early in stream, slightly cheaper to open bins (build inventory).
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score -= (1.0 - progress) * 8.0;
        }
    }

    // Lookahead: if the post_residual exactly accommodates the next item,
    // this placement is excellent.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_gap = post_residual - next_item_size;
        if next_gap < 10 {
            score -= 20.0;
        } else {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits (small post_residual is already good; amplify).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Aggressive 2-step lookahead: reward when next item fits perfectly in post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = next_item_size as f64 / post_residual as f64;
        score -= 25.0 * next_fit * next_fit;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leaving residual that the next item cannot use at all.
        let waste = (post_residual as f64 - (next_item_size as f64).min(post_residual as f64)) / bin_capacity as f64;
        score += 15.0 * waste;
    }

    // Compare against mean residual of open bins: prefer bins below mean residual (tighter packing).
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Many open bins: prefer consolidating into existing bins rather than opening new ones.
    score += 0.5 * open_bins_count as f64;

    // Late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * fit_ratio;

    // New-bin candidate: penalize unless item is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        let base_penalty = 60.0;
        let large_item_bonus = item_size as f64 / bin_capacity as f64;
        score += base_penalty * (1.0 - large_item_bonus * large_item_bonus);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements that leave little waste.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 30.0;

    // Perfect fit is nearly free.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize leaving a residual that is just barely too small for the next item (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance bin: if this is the only bin that fits, using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is costly; only attractive
    // when the item fits poorly everywhere else (large dead space would result).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (bin_capacity - item_size) as f64;
        score += 25.0 + 0.15 * open_bins_count as f64;
        // Late in the stream, be more conservative about opening bins.
        score += progress * 10.0;
        // If the item is large, a fresh bin is more acceptable.
        score -= item_size as f64 * 0.2;
        // If mean residual across open bins is small, existing bins are tight -> new bin ok.
        score -= (mean_residual - waste.abs().min(mean_residual)) * 0.1;
        if waste < 20.0 {
            score += 20.0; // would waste a lot of a fresh bin? no: small waste is good
            score -= 40.0;
        }
    }

    // Prefer bins whose residual is already small relative to the mean (consolidate waste).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Mild preference for using fewer total bins when many are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: quadratic penalty on wasted residual, scaled by stream progress
    let mut score = pr as f64 * (1.0 + 0.8 * progress) + 40.0 * x * x * (0.5 + progress);

    // Reward tight fits (non-linear coupling between post_residual and item_size)
    let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
    score -= 30.0 * (1.0 - tightness * tightness);

    // Lookahead: penalize if next item cannot use this bin's post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 12.0 * (1.0 - pr / cap) * (nxt / cap);
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    } else {
        score += 3.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Mild penalty when bin residual is far below mean residual (fragmentation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev - 2.0 * dev;

    // New-bin candidate: discourage unless residual is tiny / fit is terrible
    if bin_residual == bin_capacity {
        score += 35.0 - 10.0 * progress - 5.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small residuals are dead space.
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity wasted

    // Penalize unusable dead space: residual smaller than smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - frac) * 10.0;
    } else if post_residual <= 20 {
        score += 25.0 * (1.0 - frac);
    }

    // Modulo-class logic: residuals divisible by 10 pair well with typical item grids.
    let class = post_residual % 10;
    if class == 0 {
        score -= 8.0;
    } else if class <= 3 {
        score += 10.0; // awkward sliver class
    }

    // Integer-division thresholds: how many "medium" items (size ~20) still fit.
    let fits20 = post_residual / 20;
    score -= fits20 as f64 * 6.0;

    // Lookahead coupling: reward if next item fits the post residual well.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / cap);
        if slack == 0.0 {
            score -= 40.0; // perfect two-item chain
        }
    } else if next_item_size > post_residual {
        // next item cannot use leftover: leftover is more likely wasted
        score += 8.0 * frac;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Prefer bins with below-mean residual (fill emptier-of-space / tighter bins first).
    score -= (mean_residual - pr) * 0.3;

    // New-bin candidate handling: opening a new bin is only attractive when
    // item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count <= 1;
        if poor_fit {
            score -= 30.0; // allow opening fresh bin
        } else {
            score += 120.0 + 2.0 * open_bins_count as f64; // discourage wasting new bins
        }
    }

    // Slight progression term: late in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any item (1..100) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Semi-unusable gaps: small enough that only tiny items fit; taper penalty.
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Reward near-perfect fits (best-fit core, sharpened).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead synergy: if the next item fits exactly in the post residual,
    // this placement chains perfectly.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 12.0;
    }
    // If next item cannot fit here anyway, mild bonus for leaving large usable gap.
    if next_item_size > post_residual && post_residual >= 20 {
        score -= 4.0;
    }

    // Open-bin pressure: many open bins -> consolidate into existing ones,
    // discourage opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline at capacity, plus pressure penalty,
        // plus small early-stream allowance to seed bins.
        score = bin_capacity as f64 + pressure * 8.0 - (1.0 - progress) * 5.0;
    } else {
        // Existing bin: slight bonus relative to pressure so consolidation wins.
        score -= pressure * 1.5;
    }

    // Prefer bins tighter than the mean residual (fill emptier-of-space bins first).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness;

    // Exact fill is ideal
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chain fit: excellent, but only if post_residual isn't too small anyway
            let chain_gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - chain_gap / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leaving awkward medium gaps
            let gap = post_residual as f64;
            if gap > next_item_size as f64 * 0.5 {
                score += 0.3 * gap;
            }
        }
    }

    // Relative to mean residual: avoid wasting space in bins with large residuals
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        score += 8.0 * (rel - 1.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer bins that would otherwise stay idle
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // opening new bin costs ~one bin; make it unattractive unless post_residual (== capacity - item) is small
        score = 100.0 - 0.5 * (bin_capacity as f64 - post_residual as f64);
        if fitting_bins_count == 0 {
            score -= 200.0; // forced
        }
    }

    // Stream progression: late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    // Many open bins: favor filling existing ones over spreading
    score += 1.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = post;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post / cap);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: reward if next item fits in the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            // Excellent: chain two items; reward proportional to how well next fits
            let post2 = post - nxt;
            score -= 10.0 + 8.0 * (1.0 - post2 / cap);
            if post2 == 0.0 {
                score -= 15.0; // exact two-item chain
            }
        } else {
            // Penalize leaving residual that is too small for the known next item
            let gap = nxt - post;
            score += 0.15 * gap;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize bins whose residual deviates far from the mean residual
    // (keeps a portfolio of residual sizes for future flexibility)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Mild penalty for spreading across many open bins early on
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    // Late in the stream: consolidate aggressively, avoid opening new bins
    score += 20.0 * progress;

    // New empty bin candidate: neutral-ish baseline so it wins only when
    // all open bins would leave bad fits (large post_residual).
    if bin_residual == bin_capacity {
        score = cap - item          // baseline waste of a fresh bin
            + 5.0 * (1.0 - progress) // cheaper to open bins early
            + 0.05 * open_bins_count as f64
            - if next_item_size > 0 && next_item_size <= post_residual { 8.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Base: waste after placement
    let mut score = norm_pr * (1.0 + 0.5 * progress);

    // Smooth non-linear coupling: quadratic penalty on post_residual scaled by stream progress
    score += progress * norm_pr * norm_pr * 2.0;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= progress * (1.0 - norm_pr) * (1.0 - norm_pr) * 0.8;

    // Interaction with next item: reward residuals that could accommodate lookahead
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let gap = nxt - norm_pr;
        // smooth sigmoid-like reward when post_residual is close to next item size
        let closeness = 1.0 / (1.0 + gap * gap * 10.0);
        score -= closeness * 0.6 * (1.0 - progress);
        // penalize residual that is just barely too small for next item (dead space)
        if gap > 0.0 && gap < 0.15 {
            score += (0.15 - gap) * 2.0;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.5;
    }

    // New-bin candidate: mildly penalize early, allow late when fits are poor
    if bin_residual == bin_capacity {
        score += 0.9 * (1.0 - progress) - progress * fit_ratio * 0.5;
        score += norm_pr; // empty bin residual = capacity
    }

    // Penalize bins whose residual deviates strongly from mean (keeps residuals uniform)
    let dev = (pr - mean_residual) / cap;
    score += 0.3 * dev * dev;

    // Mild crowding penalty scaled by fit ratio
    score += open_bins_count as f64 * 0.01 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify dead space into buckets
    // (0 = perfect, small slivers, mid, large reusable chunks).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // capacity fraction of leftover

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes via integer division thresholds on post_residual:
    // class 0: 0..=5   (sliver, nearly dead) -> slight penalty beyond raw value
    // class 1: 6..=20  (usable by small items) -> reward
    // class 2: 21..=50 (mid) -> mild penalty
    // class 3: 51..=100 (half-bin or more, very reusable) -> reward
    let class = post_residual / 6; // harmonic modulus-ish bucketing
    match class {
        0 => { score += 5.0; }                    // sliver risk
        1 | 2 | 3 => { score -= 15.0; }           // good small leftover
        4..=8 => { score += 8.0; }                // awkward mid gap
        _ => { score -= 20.0; }                   // large reusable residual
    }

    // Modulo arithmetic on post_residual: multiples of 5/10 pair well with
    // typical item sizes drawn on integer grids.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 10.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: if next item fits the post-residual exactly or well,
    // strongly favor this bin (chaining).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // tighter next fit is better
            let gap = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - gap / cap);
        } else {
            // next item cannot use this leftover: leftover more likely dead
            score += 12.0 * frac;
        }
    }

    // Last-chance bin: if this is the only fitting bin, penalize opening a new
    // bin instead -> reward this bin heavily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when current bins would leave bad residue, otherwise
    // discourage spreading across bins.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, discounted early in the stream
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 40.0 + 30.0 * progress;
        // if many open bins already, opening another spreads capacity thin
        new_bin_cost += 2.0 * open_bins_count as f64;
        // if mean residual of open bins is large, we should use them instead
        new_bin_cost += 0.5 * mean_residual;
        // but if the item is large relative to capacity, fresh bin is fine
        new_bin_cost -= 0.3 * item_size as f64;
        score += new_bin_cost;
    }

    // Mild pressure to prefer fuller bins overall: compare residual to mean.
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Small tie-breaker by stream position for determinism/stability.
    score += 0.001 * (step_index as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 10.0;
    }

    // Reward tight fits: small post_residual relative to bin capacity.
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Open-bin pressure: penalize creating new bins when many are open.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 3.0 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (i.e., filling the emptier bins less, consolidating fills).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Lookahead: if the next item would fit in the post residual, reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Stream progression: later in the stream, be slightly more conservative
    // about spreading across bins (favor closing bins out).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strong reward for perfect 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Perfect match gets a big bonus; near matches decay quadratically
        if diff == 0.0 {
            score -= 120.0;
        } else {
            score -= 60.0 * (1.0 - diff / (diff + 10.0)).max(0.0);
        }
        // Penalize residuals that are too small for the next item (dead space)
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: just minimize wasted residual
        score += 0.2 * post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Prefer bins tighter than the mean residual (fill crowded bins first)
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Penalize leaving very small unusable residuals (dead space < 10)
    if post_residual < 10 {
        score += 25.0;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = post;

    // Superlinear penalty on dead space: small leftovers are fine, big ones are wasteful.
    let waste_frac = post / cap;
    score += waste_frac * waste_frac * waste_frac * 60.0;

    // Penalize bins whose residual far exceeds the item (loose fit wastes capacity).
    score += ((bin_residual as f64 - item) / cap) * 12.0;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Lookahead coupling: reward if the next item can also fit after this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 10.0 * (1.0 - nxt / cap);
        } else {
            score += 5.0;
        }
    }

    // Global state: many open bins with high mean residual -> encourage consolidation.
    if open_bins_count > 2 {
        score += (open_bins_count as f64).ln() * 2.0;
        if item > mean_residual {
            score += 6.0;
        }
    }

    // Mild time horizon coupling: later in the stream, prefer tighter packing.
    score += progress * 3.0;

    // New-bin candidate handling (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Baseline: opening a new bin is moderately expensive.
        score = cap * 0.9 + post;
        // If no open bin fits, opening a new bin is clearly right.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Large items benefit from a fresh bin (avoid fragmenting an old one badly).
        if item >= 0.5 * cap {
            score -= 15.0;
        }
        // Late in the stream, slightly discourage spawning extra bins.
        score += progress * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: raw wasted space after placement
    let mut score = post;

    // Non-linear polynomial waste penalty: dead space is quadratically worse
    let post_norm = post / cap;
    score += 40.0 * post_norm * post_norm;

    // Tight-fit reward: smooth cubic coupling of fill ratio
    let fill = item / cap;
    score -= 30.0 * fill * fill * fill;

    // Stream-progress coupling: later in the stream, waste hurts more (non-linear ramp)
    let prog2 = progress * progress;
    score += post * (0.5 + 1.5 * prog2);

    // Mean-residual interaction: if this bin is far below average residual,
    // using it consolidates space (favor); smooth sigmoid-like term
    let dev = (res - mean_residual) / cap;
    score -= 10.0 * dev / (1.0 + dev * dev);

    // Last-chance bin: if it's the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin, more so as stream progresses,
    // unless the item is large and would leave a very small residual elsewhere
    if bin_residual == bin_capacity {
        let newbin_penalty = 35.0 + 30.0 * progress + 0.2 * open_bins_count as f64;
        score += newbin_penalty;
        // But large items nearly filling a fresh bin are naturally good; small relief
        score -= 15.0 * fill * fill;
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 12.0 * (1.0 - (nxt / cap));
        } else {
            // next item won't fit here; slight penalty proportional to leftover
            score += 5.0 * post_norm;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose residual falls on
    // "coarse" boundaries (multiples of 10, 25, 50) remain reusable by
    // typical item sizes, so waste less there.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Harmonic divisibility bonuses on post_residual.
    if post_residual % 50 == 0 {
        score -= 25.0;
    } else if post_residual % 25 == 0 {
        score -= 15.0;
    } else if post_residual % 10 == 0 {
        score -= 10.0;
    } else if post_residual % 5 == 0 {
        score -= 4.0;
    }

    // Dead-space penalty: leftovers that no common size (10..80, and 1..100
    // in general) can use. Penalize residuals just below the smallest
    // plausible item size.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into the leftover,
    // this placement is part of a harmonic chain — reward it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            let chain_left = post_residual - next_item_size;
            score -= 30.0;
            if chain_left % 10 == 0 {
                score -= 15.0;
            }
        } else {
            // Next item cannot use this bin's leftover: mild penalty scaled
            // by how far off it is.
            score += ((next_item_size - post_residual) as f64) * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new one (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: opening a bin should only win when the current
    // placement would leave large awkward residue. Penalize new bins
    // mildly, more so when many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 80.0 + 40.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // But if item is large and leaves a clean harmonic residual, opening
        // can still win: reduce the penalty.
        if item_size >= 60 && post_residual % 25 == 0 {
            score -= 90.0;
        }
    }

    // Prefer bins whose residual deviates from the mean in the "tighter"
    // direction (best-fit bias relative to fleet state).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Slight preference for bins with larger residual being consumed when
    // the item is large (avoid fragmenting small bins).
    if item_size >= 50 {
        score -= (item_size as f64 - 50.0) * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Mid-range residuals (10..=20) are semi-dead: mildly penalized.
    if post_residual >= 10 && post_residual <= 20 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual that is still usable).
    if post_residual >= 10 {
        score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 55.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    }

    // Open-bin pressure: prefer bins that are already open over spreading out,
    // but relax pressure as stream progresses (consolidate early).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (2.0 - 1.5 * progress);

    // Mean residual coupling: avoid bins whose residual deviates far from mean
    // (keeps a portfolio of similarly-filled bins).
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // Penalize opening a new bin when an open bin gives a decent fit.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * item_size as f64;
        if fitting_bins_count > 0 {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Small post-residual is good; penalize dead space non-linearly
        let pr = post_residual as f64;
        score += 0.5 * (pr * pr) / bin_capacity as f64;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as i64 - next_item_size as i64) == 0 {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward proportional to tightness
            score -= 200.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize if we waste most of the residual
            score += 0.3 * pr;
        }
    }

    // Relative to mean residual: prefer bins with residual near/below mean (tight bins)
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Discourage opening a new bin when a good fit exists in an open bin
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin: baseline cost; only attractive if open bins are fragmented
        score = 100.0 + 0.5 * mean_residual - 50.0 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative
        }
    }

    // Slight stream-progression pressure: later in stream, prefer closing bins tightly
    if total_items > 0 {
        let t = step_index as f64 / total_items as f64;
        score += 10.0 * t * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: bins whose residual is close to the item size are great fits.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space after placement, especially if nothing known can use it.
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        let usable = if next_item_size > 0 && next_item_size <= post_residual { 1.0 } else { 0.35 };
        score += 25.0 * dead * dead * usable;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / 100.0);
        } else if next_item_size <= bin_residual && next_item_size > post_residual {
            // This placement would strand the next item relative to current residual.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when the
    // item fits terribly everywhere else (high post_residual elsewhere) or few bins fit.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowding = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
        // Base penalty keeps us preferring existing bins...
        let mut new_bin_score = 70.0 + crowding * 2.0;
        // ...but relax the penalty as the stream progresses and bins fragment.
        new_bin_score -= 40.0 * progress;
        // If the item is large relative to typical residual, new bin becomes attractive.
        new_bin_score -= (item_size as f64 - mean_residual).max(0.0) * 0.6;
        return new_bin_score;
    }

    // Mild preference for fuller bins early on (best-fit flavor), decaying with progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * (1.0 - bin_residual as f64 / bin_capacity as f64) * (1.0 - 0.5 * progress);

    // Slight penalty for spreading across many open bins when residuals are large.
    if bin_residual as f64 > mean_residual {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;
    // smooth non-linear coupling: dead-space penalty grows with stream progress
    let prn = pr / cap;
    score += 30.0 * t * prn * prn;
    score -= 40.0 * (1.0 - t) * prn * (1.0 - prn);
    // reward tight fits via item_size / bin_residual ratio
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill * fill;
    // lookahead coupling: bonus if next item fits post_residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 15.0 * (1.0 - t);
    } else if next_item_size > 0 {
        score += 10.0 * t * (next_item_size as f64 - pr) / cap;
    }
    // last-chance bin: strong reward
    if fitting_bins_count == 1 {
        score -= 35.0;
    }
    // penalize opening new bins when many are open with slack
    if bin_residual == bin_capacity {
        score += 20.0 + 5.0 * (open_bins_count as f64).sqrt() + mean_residual * 0.1;
    }
    // mean residual alignment: prefer bins near mean residual
    let dev = (pr - mean_residual).abs() / cap;
    score += 8.0 * dev * dev;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "slot band" does the leftover fall in?
    // Bands of size 10 (classic harmonic classes): 0, 1-10, 11-20, ... 91-100.
    let band = (post_residual + 9) / 10; // 1..=10, 0 when exact fit
    let band_penalty = match band {
        0 => -40.0,                 // perfect fit: excellent
        1 => -15.0,                 // tiny dead space, still great
        2 | 3 => 5.0,               // small-but-awkward leftover
        4 | 5 => 12.0,              // middle bands: mediocre
        6 | 7 => 20.0,              // large leftover: wasteful
        _ => 30.0,                  // nearly empty after placement: bad
    };
    score += band_penalty;

    // Integer-division thresholds: does post_residual still admit a future item
    // of a "harmonic class" (multiples of 10)? Reward usable leftovers.
    let usable = post_residual / 10; // number of full 10-slots left
    score -= 2.0 * usable as f64;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chain perfect fits).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            // modulo arithmetic: how close is post_residual to a multiple of next size
            let m = post_residual % next_item_size.max(1);
            let m = if m == 0 { 0 } else { next_item_size - m };
            score -= 10.0 - (m as f64);
        } else {
            // next item won't fit here: penalize leaving big residue that strands it
            score += (next_item_size - post_residual).min(30) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = cap * 0.55;
        // Prefer new bin when open bins would leave very fragmented residue.
        if fitting_bins_count >= 1 {
            let fragmentation = (mean_residual - (item_size as f64)).abs();
            score -= fragmentation * 0.4;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
        // If next item is large, a fresh bin is valuable.
        if next_item_size > 50 {
            score -= 8.0;
        }
    }

    // Mild tie-break: prefer bins whose residual is close to the mean (balance).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.05;

    // Small reward for using existing bins when many are open (contain sprawl).
    score += open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit is maximally rewarded.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward bins whose residual can still host the lookahead item after placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins,
    // but allow opening a new bin when current residuals are already fragmented.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable only if item is small relative to mean residual
        // or few bins are open; otherwise penalize.
        score += 20.0 + pressure * 4.0 - (item_size as f64 / 100.0) * 15.0;
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
        if progress > 0.8 {
            score += 5.0;
        }
    } else {
        // Existing bin: slight reward proportional to how well it's filled.
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // Mild preference for bins below mean residual (balancing load).
    score += 0.03 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits; smaller leftover is better
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit here; penalize leaving a gap that is too small to be useful
            if post_residual < 10 {
                score += 50.0;
            }
        }
    }

    // Compare post_residual to mean residual: prefer bins that end tighter than average
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty scaled by how well other bins could fit
        score += 300.0;
        if fitting_bins_count > 0 {
            score += 100.0;
        }
        // Early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 100.0 * (1.0 - progress);
        // If next item is large and this fresh bin could take it after, slight bonus
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on wasted space ratio.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_ratio * waste_ratio;

    // Reward near-perfect fits aggressively.
    if post_residual <= 3 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
        // Extra reward if next item fills the bin nearly exactly afterwards.
        let second_post = post_residual - next_item_size;
        if second_post <= 5 {
            score -= 15.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Leaving residue smaller than next item is dead space unless tiny.
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Many open bins with large mean residual: discourage spreading, favor consolidation.
    if open_bins_count > 3 {
        let pressure = mean_residual / bin_capacity as f64;
        score += 12.0 * pressure * ((open_bins_count as f64).ln());
    }

    // Prefer bins whose residual is close to the item (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * gap;

    // Time horizon: early in stream, opening new bins is cheap; later, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus early-stream discount.
        let new_bin_cost = 55.0 - 25.0 * (1.0 - progress);
        // Penalize new bin if existing bins fit reasonably well.
        if fitting_bins_count > 0 && post_residual as f64 > mean_residual * 0.5 {
            score = new_bin_cost + 20.0;
        } else {
            score = new_bin_cost;
        }
        // Late stream: opening new bins is expensive.
        score += 30.0 * progress;
    } else {
        // Slight bonus for filling existing bins as stream progresses.
        score -= 10.0 * progress * (item_size as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let mut score = post;

    // Non-linear waste penalty: post residual squared, normalized by capacity.
    score += (post * post) / (2.0 * cap);

    // Smooth interaction between residual and stream progress: late in the stream,
    // tight fits matter more, so penalize residual more strongly.
    let progress_coupling = post * (0.5 + progress * (1.0 - progress) * 4.0 * progress);
    score += 0.3 * progress_coupling;

    // Reward filling the bin deeply (low post residual relative to item size).
    let fill_ratio = item / cap;
    score -= 20.0 * fill_ratio * (1.0 - post / cap);

    // Penalize dead space that cannot fit the next item (smooth logistic coupling).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        let unusable = gap / (gap.abs() + 5.0); // smooth sign function in [-1, 1]
        score += 8.0 * unusable * (1.0 - progress);
        // Bonus if next item exactly continues filling this bin.
        if gap == 0.0 {
            score -= 15.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (smooth exponential decay in fitting count).
    if fitting_bins_count >= 1 {
        let urgency = 1.0 / (fitting_bins_count as f64);
        score -= 25.0 * urgency * (0.5 + 0.5 * progress);
    }

    // Mild penalty for spreading across many open bins; encourage consolidation
    // when mean residual is high (bins are all loose).
    let mean_gap = (mean_residual - post).abs();
    score += 0.05 * mean_gap * (open_bins_count as f64).ln().max(1.0);

    // Smooth preference for bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item) / cap;
    score += 10.0 * tightness * tightness;

    // New-bin candidate: empty bin has post == cap, the quadratic terms above
    // already penalize it, but add an explicit smooth barrier that shrinks as
    // the stream progresses (late stream: reuse bins more aggressively).
    let is_new = (bin_residual == bin_capacity) as f64;
    score += is_new * (30.0 * (1.0 - progress) + 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction band does it land in?
    let quarter = bin_capacity / 4;
    let post_class = match post_residual {
        0 => 0u32,                       // perfect fit — golden
        x if x < quarter => 1,           // small sliver — poor
        x if x < 2 * quarter => 2,       // quarter-class
        x if x < 3 * quarter => 3,       // half-class
        _ => 4,                          // large — nearly fresh bin
    };

    match post_class {
        0 => score -= 60.0,                          // exact fill: strongly reward
        1 => score += 25.0,                          // dead sliver: penalize
        2 => score -= 10.0,                          // quarter-class residual is reusable
        3 => score -= 5.0,
        _ => {}
    }

    // Integer-division harmonic of post_residual: reward residuals divisible into
    // common item-size classes (10,20,25,50 style granularity).
    let gran = if post_residual % 50 == 0 {
        3
    } else if post_residual % 25 == 0 {
        2
    } else if post_residual % 10 == 0 {
        1
    } else {
        0
    };
    score -= gran as f64 * 8.0;

    // Coupling with lookahead: if next item exactly fits post_residual, huge reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward by how "harmonically" it divides the residual
            if post_residual % next_item_size == 0 {
                score -= 20.0;
            } else {
                score -= (post_residual - next_item_size) as f64 / cap_f * 10.0;
            }
        } else {
            // next item cannot use this residual: penalize proportional to waste risk
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when open bins are crowded
    // (mean residual small) or this bin is a fresh-bin call competing with bad fits.
    if bin_residual == bin_capacity {
        score = cap_f - mean_residual * 0.5 + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 15.0; // big next item: fresh bin is valuable
        }
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    // Stream progression: early on, keep bins tighter (prefer filling); later, allow spread.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    // Mean-residual coupling: prefer bins whose residual deviates favorably from the mean.
    score += (post_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps too small for any item (1..=100 range,
    // but small gaps < 10 are almost surely dead) get a heavy penalty.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        // Small but potentially usable gap: moderate penalty, scaled by how "dead" it is
        // relative to the minimum plausible item size.
        score += (20.0 - post_residual as f64) * 2.5;
    }

    // Reward tight fits: fraction of residual consumed by the item.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: penalize spreading across many bins; encourage filling existing bins
    // when the count of open bins is already high.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.8;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when existing bins are fragmented.
        score += 45.0;
        score -= mean_residual * 0.3;
        // Late in the stream, prefer closing out existing bins instead of opening new ones.
        score += progress * 20.0;
        // If many bins already fit the item, opening a new one is wasteful.
        score += fitting_bins_count as f64 * 5.0;
    }

    // Lookahead coupling: if the next item would exactly use the post_residual,
    // strongly favor this placement (chains two items perfectly).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            // Next item fits but leaves another gap: mild reward proportional to fit quality.
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else if post_residual > 0 && next_item_size > post_residual {
            // Next item cannot use this gap: penalize creating a gap that blocks the lookahead.
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Prefer bins whose residual is below the mean (concentrate fullness).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: prefer tight fits
    score += 0.5 * (bin_residual as f64 - item_size as f64).abs().max(0.0);

    // Lookahead: reward if next item exactly fills post_residual (perfect chaining)
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.6 * diff;
        // Bonus when next item fits exactly into post_residual
        if post_residual == next_item_size {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        }
        // Penalize large dead space that no small future item can use
        if next_item_size > post_residual {
            score += 0.3 * post_residual as f64;
        }
    }

    // Relative to mean residual: prefer bins with residual close to item need
    score += 0.2 * (mean_residual - bin_residual as f64).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Late in stream: consolidate, avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.1 * post_residual as f64;

    // New-bin candidate: penalize opening a bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 8.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 5.0; // extra penalty if an open bin could chain with next item
        }
    }

    // Many open bins: favor filling existing ones harder
    score -= 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize time horizon
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward near-full packing (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Lookahead: if next item fits in post_residual, reward strongly
    if next_item_size > 0 && next_item_size <= post_residual {
        let coupling = (next_item_size as f64 / bin_capacity as f64).powf(0.5);
        score -= 6.0 * (1.0 - coupling) * (1.0 + t);
    } else if next_item_size > 0 {
        // Next item won't fit: penalize proportionally to wasted potential
        let gap = (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        score += 4.0 * gap.min(1.0);
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless open bins are nearly full
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 12.0 - 14.0 * avg_fill * pressure;
        // Early in stream, opening bins is cheaper
        score -= 6.0 * (1.0 - t);
    }

    // Penalize leaving residuals that are too small to be useful (dead space)
    if post_residual > 0 && post_residual < 12 {
        score += 5.0 * (1.0 - post_residual as f64 / 12.0);
    }

    // Prefer bins whose residual deviates from mean residual (consolidate slack)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild reward for reducing number of open bins' spread as stream progresses
    score -= (1.0 - t) * (bin_residual as f64 / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping.
    let mut score = pr;

    // Smooth polynomial coupling: residual penalty grows super-linearly
    // for small post-residuals (dead space), sub-linearly for large ones.
    let quad = norm_pr * norm_pr;
    let cube = quad * norm_pr;
    score -= 30.0 * quad;
    score += 12.0 * cube;

    // Stream-progress interaction: as the stream advances, prefer tighter
    // fits more aggressively (smooth coupling with normalized residual).
    score -= 25.0 * progress * (1.0 - quad);
    score += 15.0 * progress * cube;

    // Lookahead: reward leaving room for the next item (smooth kernel).
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let diff = (pr - ns) / cap;
        score -= 20.0 * (-4.0 * diff * diff); // Gaussian-like bonus when post_residual ~ next size
        // Penalize if next item cannot fit in this bin after placement.
        if ns > pr {
            score += 8.0 * progress;
        }
    }

    // Last-chance bin: strong reward to use the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Mean residual coupling: penalize bins far from the mean (smooth).
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: add a smooth offset that shrinks with progress
    // and with large item occupancy.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score += 5.0 + 25.0 * (1.0 - fill) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how it decomposes into typical small item slots
    let post = post_residual;
    let post_f = post as f64;

    // Class A: post_residual fits a "nice" fraction of capacity (multiples of 10/25/50)
    let harmonic = (post % 10 == 0) as f64 + (post % 25 == 0) as f64 + (post % 50 == 0) as f64;
    score -= 6.0 * harmonic;

    // Class B: dead-space zones — residuals in awkward bands are hard to fill
    let frac = post_f / cap_f;
    if frac > 0.0 && frac < 0.10 {
        score += 25.0; // nearly-full bin: fine, keep it
    } else if frac < 0.30 {
        score += 8.0; // small awkward gap
    } else if frac > 0.85 {
        score += 15.0; // huge leftover: wasteful placement
    }

    // Integer-division class: can post_residual hold another item of min plausible size?
    let slots = post / 10;
    score -= 2.0 * slots as f64;

    // Lookahead coupling: does next item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post {
            // exact / harmonic fit for the follower is gold
            if post == next_item_size {
                score -= 20.0;
            } else {
                score -= 5.0;
            }
        } else {
            score += 6.0;
        }
        // follower fits into a harmonic class multiple of residual
        if post >= next_item_size && (post - next_item_size) % 10 == 0 {
            score -= 4.0;
        }
    } else {
        // last item: prefer tightest fit, ignore future
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate (fresh empty bin): only attractive when current fit is bad
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // penalize opening new bins unless this placement would leave bad residue
        let bad_fit = (frac > 0.5 && frac < 0.85) as f64;
        score += 30.0 - 25.0 * bad_fit;
        // early stream: opening bins is cheaper; late stream: consolidate
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        score += 0.5 * open_bins_count as f64;
    }

    // Mild consolidation pressure via mean residual: bins below mean residual are preferred targets
    score -= 0.05 * (mean_residual - post_f);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: more open bins => prefer filling existing bins,
    // penalize opening yet another bin.
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        score += 15.0 + 3.0 * open_bins_count as f64;
        // A new bin is acceptable only if the item is large relative to capacity
        // and no bin fits well (post_residual here equals capacity - item_size).
        let fill = item_size as f64 / bin_capacity as f64;
        if fill > 0.7 {
            score -= 20.0 * fill;
        }
    } else {
        // Reward good utilization of existing bins.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 12.0 * tightness;
    }

    // Lookahead: if next item could use the post residual, reward leaving it.
    if next_item_size > 0 {
        if next_item_size <= post_residual && post_residual > 0 {
            score -= 8.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 5.0; // residual likely dead space for next item
        }
    }

    // Mean residual coupling: if this bin is far below mean residual,
    // it is already "wasted"; prefer bins closer to mean to balance.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Late in the stream, tighten up: discourage waste even more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but imperfectly: penalize leftover dead space
            // after the hypothetical second placement.
            let second_leftover = post_residual - next_item_size;
            score += 0.4 * second_leftover as f64;
            score -= 8.0;
        } else {
            // Next item does not fit here: mild penalty proportional to
            // the mismatch, discouraging stranding large next items.
            let mismatch = (next_item_size - post_residual) as f64;
            score += 0.15 * mismatch;
        }
    }

    // Compare post_residual against the mean residual across open bins:
    // leaving this bin below-average residual is good (consolidating waste).
    let diff = (post_residual as f64) - mean_residual;
    score += 0.25 * diff;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening new bins when open bins exist that fit reasonably well.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if it enables a perfect
        // two-item packing with the lookahead item.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 10.0; // discourage new bin when lookahead could pair elsewhere
        }
        score += 5.0 * (open_bins_count as f64).sqrt().min(5.0);
        // Late in the stream, prefer filling existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Small bonus for placing larger items early (large items are harder to place).
    score -= 0.05 * item_size as f64 * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tight * tight;

    // Penalize dead space that no future item (1..100) can use:
    // residuals below 10 are wasted unless nearly zero.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits exactly in the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // next item won't fit here; slight penalty proportional to overshoot
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Time horizon: early in the stream, prefer keeping residuals flexible
    // (penalize very small post_residuals less critical, but keep bins balanced);
    // late in the stream, prioritize tight packing aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * tight;

    // Global state coupling: many open bins with high mean residual ->
    // encourage filling existing bins rather than spreading.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score += 0.05 * mean_residual;
    }

    // Mild penalty for leaving a residual equal to a "hard" size (e.g. > 50)
    // early on, since few items are that large; encourage compact bins.
    if post_residual > 50 {
        score += 0.1 * (post_residual as f64 - 50.0);
    }

    // New-bin candidate: make opening a new bin costly unless the current
    // item is huge relative to all residuals (poor fit everywhere).
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 25.0; // stacking large items together in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth non-linear coupling: penalize residual quadratically as stream progresses
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) with a smooth saturating term
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Interaction between post_residual and mean residual: prefer bins deviating below mean
    let dev = (mean_residual - pr) / cap;
    score += 15.0 * dev * (1.0 - norm_pr);

    // Last-chance bonus: smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - norm_pr * norm_pr);
    }

    // Lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let waste = if pr < nx { nx - pr } else { 0.0 };
        score += 10.0 * (waste / cap) * (1.0 - norm_pr);
        // reward if next item fits exactly-ish into the resulting residual
        let fit_quality = 1.0 - ((pr - nx).abs() / cap);
        score -= 12.0 * fit_quality * fit_quality * norm_pr;
    }

    // Mild pressure to consolidate into fewer bins early
    score += 5.0 * (open_bins_count as f64 / (1.0 + total_items as f64)) * norm_pr;

    // New-bin candidate: make empty bins slightly less attractive unless residuals are poor
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * (1.0 - progress) - 10.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity-fraction buckets. Small leftovers (tight fits) are valuable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0.0 .. 1.0

    // Reward tight fits strongly (nonlinear in leftover fraction).
    if frac <= 0.05 {
        score -= 60.0; // near-perfect fit
    } else if frac <= 0.15 {
        score -= 40.0;
    } else if frac <= 0.30 {
        score -= 15.0;
    } else if frac <= 0.50 {
        score -= 5.0;
    } else {
        // Large dead space: penalize quadratically beyond half-empty.
        score += (frac - 0.5) * 90.0;
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Excellent: chain placement possible; reward more for tighter chains.
            let chain_tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 25.0 + 20.0 * chain_tightness;
        } else if next_item_size <= bin_residual {
            // Next item would have fit here before this placement: mild penalty
            // for destroying a future option.
            score += 8.0;
        }
        // Harmonic class check on next item vs post residual (modulo-style bucketing)
        let bucket = |v: u32| (v / 10) % 4; // harmonic class 0..3
        if next_item_size <= post_residual && bucket(next_item_size) == bucket(post_residual) {
            score -= 6.0; // same harmonic class: likely reusable remainder
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Penalize opening a new bin, scaled by how many
    // alternatives exist and how much mean slack is floating around.
    if bin_residual == bin_capacity {
        score += 35.0 + 3.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 25.0;
        }
        // Early in the stream, opening bins is cheaper (future flexibility).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Mean-residual context: if the average open bin already has lots of slack,
    // avoid adding another loose fit.
    if bin_residual < bin_capacity {
        if pr as f64 > mean_residual {
            score += 4.0;
        } else {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: small post_residuals that most items cannot use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Moderate dead space also penalized, scaled by how tight the gap is.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open bins pressure: when many bins are open, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.5 * (0.5 + progress);

    // Lookahead: if the next item fits the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }
    // If next item almost fits (small miss), slight penalty for creating near-dead space.
    if next_item_size > post_residual && post_residual > 0 && next_item_size - post_residual <= 5 {
        score += 5.0;
    }

    // New-bin candidate: make it moderately attractive only when current fit is bad.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward: near-zero post residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let pr = post_residual as f64;
        // Penalize dead space relative to capacity.
        score += (pr / cap) * 40.0;
        // Aggressive 2-step lookahead: reward if next item exactly fills post_residual.
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            let diff = (pr - nxt).abs();
            if diff <= 1.0 {
                score -= 300.0; // chained perfect fit
            } else if nxt <= pr {
                score -= 80.0 * (1.0 - diff / cap);
            } else {
                // next item cannot follow here: mild penalty proportional to overshoot
                score += 20.0 * ((nxt - pr) / cap);
            }
        }
    }

    // Compare bin tightness against mean residual: prefer bins tighter than average
    // when this bin's residual is small, penalize wasting large-residual bins on small items.
    let resid = bin_residual as f64;
    if resid > mean_residual + 1.0 {
        score += (resid - mean_residual) * 0.5;
    } else {
        score -= (mean_residual - resid) * 0.3;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        let waste = cap - item_size as f64;
        score += 150.0 + waste * 0.8;
        if fitting_bins_count == 0 {
            score -= 400.0; // must open new bin anyway
        }
    }

    // Early stream: be slightly conservative with open bins to keep flexibility.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on post-residual relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Creating dead space the next item cannot use: penalize proportionally.
        let waste = (next_item_size - post_residual) as f64;
        score += waste * 0.3;
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer fuller bins over emptier ones among open bins.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Late in the stream, consolidate: penalize opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when few bins fit or item is large.
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 20.0 - 35.0 * pressure - 25.0 * progress
            + (item_size as f64 / bin_capacity as f64) * 10.0;
    } else {
        score -= 15.0 * progress;
    }

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Smooth non-linear coupling: post_residual polynomial in progress
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let prog_sq = progress * progress;
    let prog_cu = prog_sq * progress;

    // Penalize large residuals more as stream progresses (waste grows costly)
    score += 30.0 * pr_norm * pr_norm * (0.5 + prog_cu);

    // Reward tight fits with smooth interaction
    let tightness = 1.0 - pr_norm;
    score -= 25.0 * tightness * tightness * (0.3 + 0.7 * prog_sq);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 18.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead coupling: if next item fits the post-residual smoothly, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = pr - nxt;
        if fit_gap >= 0.0 {
            let fg_norm = fit_gap / cap;
            score -= 12.0 * (1.0 - fg_norm) * (1.0 - fg_norm) * (0.5 + 0.5 * progress);
        } else {
            score += 6.0 * (-fit_gap / cap) * (1.0 - progress);
        }
    }

    // Mild penalty for spreading across many open bins
    score += 0.15 * open_bins_count as f64 * (0.5 + prog_sq);

    // Deviation from mean residual: prefer bins near mean for balance
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: penalize mildly unless residuals are poor
    if bin_residual == bin_capacity {
        let mean_pr = mean_residual / cap;
        score += 10.0 - 20.0 * mean_pr * mean_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by residue mod capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_residue = post_residual % (bin_capacity / 4);
    let residue_penalty = (post_residue as f64) * 0.35;
    score += residue_penalty;

    // Reward near-perfect fills: post_residual in tiny band gets big subtraction.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 2 {
        score -= 300.0;
    } else if post_residual <= 5 {
        score -= 150.0;
    }

    // Integer-division thresholds: post_residual buckets via division by 10.
    let bucket = post_residual / 10;
    score += (bucket as f64) * 2.0;

    // Harmonic coupling with next item: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let nxt = next_item_size as f64;
            // fraction of post_residual consumed by next item
            let frac = nxt / post;
            score -= 80.0 * frac;
            // modulo harmony: next_item_size divides post_residual evenly
            if post_residual % next_item_size == 0 {
                score -= 120.0;
            }
        } else {
            // next item cannot fit here: penalize leaving large unusable space
            score += 40.0;
        }
    } else {
        // last item: just minimize waste
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate (empty): penalize moderately so it's chosen only when open bins are bad.
    if bin_residual == bin_capacity {
        score += 150.0 + 0.5 * (open_bins_count as f64);
        // But if mean residual is small (open bins nearly full), new bin becomes attractive.
        score -= (cap - mean_residual).min(60.0);
    }

    // Stream progression: late in stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (1.0 - post / cap);

    // Penalize bins whose residual deviates far from mean (fragmentation spread).
    score += 0.2 * ((post - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A residual that can't fit even the smallest plausible item is dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        // Small gap that few item sizes can use: graded penalty.
        score += (25.0 - post_residual as f64) * 1.8;
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Open-bins pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a
    // much better future fit (lookahead check).
    if bin_residual == bin_capacity {
        score += 25.0;
        if next_item_size > 0 && next_item_size as f64 >= mean_residual {
            score -= 20.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Post-residual too small for the next item: mild dead-space penalty.
        score += (post_residual as f64) * 0.3;
    }

    // Tight-fit reward: item occupies a large fraction of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.85 {
        score -= 10.0 * fill_ratio;
    }

    // Late in the stream, prefer closing bins tightly (less fragmentation).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64) * 0.4;

    // Prefer bins with below-average residual (fill emptier bins first).
    if (bin_residual as f64) > mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 20.0;

    // 2-step lookahead: strongly reward bins whose post_residual can host next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-chain
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.15; // penalize leftover after hypothetical next placement
            if slack < 10.0 {
                score -= 15.0; // near-perfect chain
            }
        } else {
            score += 8.0; // next item won't fit here
        }
    }

    // Compare post_residual against mean residual: avoid creating below-average dead space.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins exist that fit reasonably well.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 30.0 + mean_residual * 0.1;
    }

    // Late in stream: prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (open_bins_count as f64).recip().min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) as f64 / bin_capacity as f64;
        let global_pressure = mean_residual / bin_capacity as f64;
        // Opening a bin is penalized more as stream progresses and bins are scarce.
        let time_factor = 0.5 + (step_index as f64 / total_items.max(1) as f64);
        score += 25.0 * time_factor - 10.0 * (1.0 - global_pressure);
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > 0 && next_item_size as f64 > poor_fit * bin_capacity as f64 {
            score -= 6.0;
        }
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // unless it's the last-chance bin.
    let dev = (bin_residual as f64 - mean_residual).abs();
    if fitting_bins_count > 1 {
        score += 0.15 * dev;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 7.0;
    }
    // If next item does NOT fit post_residual but is large, mildly prefer leaving it elsewhere.
    if next_item_size > post_residual as u32 && next_item_size > 50 {
        score += 2.0;
    }

    // Slight preference for using already-open bins when many are open (limit bin count growth).
    if bin_residual != bin_capacity {
        score -= 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear sharpening
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth progress coupling: later in stream, penalize large residuals more
    let progress_coupling = progress * progress;
    score += progress_coupling * pr * 0.5;

    // Reward tight fits via smooth sigmoid-like term on normalized fit ratio
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let tightness = fit_ratio * fit_ratio;
    score -= tightness * 12.0 * (1.0 - progress * 0.5);

    // Penalize dead space relative to mean residual (smooth quadratic divergence)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 8.0;

    // Last-chance bonus: only one fitting bin, avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Lookahead: if next item fits smoothly into post_residual, reward
    if next_item_size > 0 {
        let next_fits = (next_item_size as f64) <= pr;
        if next_fits {
            let slack = (pr - next_item_size as f64) / cap;
            score -= 6.0 * (1.0 - slack * slack);
        } else {
            score += (next_item_size as f64 - pr) * 0.05;
        }
    }

    // Mild pressure against bin proliferation as stream progresses
    score += (open_bins_count as f64).ln().max(0.0) * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of post_residual: residues mod 10. Residuals that are
    // small-but-nonzero are dead space; classify by divisibility.
    let r = post_residual;
    if r % 10 == 0 {
        // "Clean" residual: likely reusable by typical item sizes.
        score -= 8.0;
    } else if r % 5 == 0 {
        score -= 3.0;
    } else if r < 10 {
        // Tiny dead space (< 10, unusable since min size is 1..100 interface).
        // Penalize proportionally to how wasted it is relative to the item.
        score += 6.0 + (10 - r) as f64;
    }

    // Integer-division thresholds: does post_residual still admit the lookahead item?
    if next_item_size > 0 {
        if r >= next_item_size {
            // Chain potential: reward a residual that keeps the next item feasible,
            // especially when the leftover after the next item is again clean.
            let second = r - next_item_size;
            score -= 4.0;
            if second % 10 == 0 { score -= 3.0; }
            if second == 0 { score -= 20.0; }
        } else {
            // Bin becomes useless for the lookahead item: penalize.
            score += 5.0 + (next_item_size - r) as f64 * 0.25;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly awful.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: neutral baseline slightly below a mediocre fit so that
    // poor fits lose to opening a fresh bin, but good fits win over new bins.
    if bin_residual == bin_capacity {
        score = 25.0 - (item_size as f64 * 0.05);
        if next_item_size > 0 && item_size >= next_item_size {
            score -= 2.0; // big item into fresh bin is fine
        }
        return score;
    }

    // Mild stream-progression coupling: later in the stream, prefer tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.05;

    // Prefer bins with residual below mean (tighter bins), mild pull.
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fit is highly desirable
    }

    // Reward leaving room for the lookahead item (k=2 lookahead synergy).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0; // gap too small for next item: likely dead space
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 2.0;

    // Slight preference for bins with residuals below the mean (compact usage).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * -0.5;
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits (low dead space)
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let look = next_item_size as f64;
        let diff = (post_residual as f64 - look).abs();
        if diff == 0.0 {
            score -= 40.0; // next item fills this bin exactly
        } else if post_residual as f64 > look {
            score -= 20.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize proportionally to wasted lookahead
            score += 10.0 * (diff / bin_capacity as f64);
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when good open bins exist, unless item is large
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score += 15.0 * (1.0 - tightness);
        if next_item_size > 0 && (next_item_size as f64) > bin_capacity as f64 - item_size as f64 {
            score -= 10.0; // next item won't fit after this, new bin reasonable
        }
    }

    // Slight preference for using fewer open bins early in the stream
    if step_index < total_items / 2 {
        score += open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post-residual more than linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize large dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable gap
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty for wasting residual
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity or open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // Prefer new bin when item is big, bins are fragmented, or late in stream.
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
        score += 20.0 * fragmentation;
        score += 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative
        }
    } else {
        // Mild pressure to consolidate: fewer open bins is better.
        score += open_bins_count as f64 * 0.5;
        // Prefer bins whose residual deviates favorably from the mean
        // (use tighter-than-average bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    // Time-horizon coupling: early in the stream, be conservative (keep bins
    // flexible); late, squeeze hard.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * tightness;
    score += 4.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;

    let mut score = pr;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let coupling = pr_norm * pr_norm * (1.0 - t) + pr_norm * (1.0 - pr_norm) * t;
    score += 40.0 * coupling * cap * 0.01;

    // Penalize small dead space quadratically (unusable gaps)
    if pr > 0.0 {
        let dead = 1.0 - pr / (pr + item);
        score += 30.0 * dead * dead;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 15.0 * (nxt / cap);
        } else {
            score += 10.0 * ((nxt - pr) / cap).min(1.0);
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Slight preference for bins tighter than mean residual (best-fit flavor)
    score += 5.0 * ((bin_residual as f64 - mean_residual) / cap);

    // Late-stream consolidation: favor filling existing bins more aggressively
    score -= 20.0 * t * (1.0 - pr_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by large
    // power-of-two-friendly chunks (e.g. 25, 50) pair well with common sizes.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Penalize dead space more aggressively when it's small but unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Modulo structure: residuals in classes {0, 20, 25, 50} mod 100 are
    // "harmonic" — they leave room for typical item sizes.
    let harmonic = matches!(post_residual % 25, 0) || matches!(post_residual % 20, 0);
    if harmonic {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let nfrac = next_item_size as f64 / post_residual as f64;
            // Reward tight packing of the next item too.
            score -= 20.0 * nfrac;
            // Penalize if next item leaves another awkward sliver.
            let next_post = post_residual - next_item_size;
            if next_post > 0 && next_post < 10 {
                score += 15.0;
            }
        } else {
            // Next item won't fit here; mild penalty scaled by how much it misses.
            let miss = (next_item_size - post_residual) as f64;
            score += (miss / cap) * 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: opening a new bin should lose unless the current
    // fit is bad. Penalize the fresh bin by the mean residual of open bins
    // (waste already accumulated) plus a fixed opening cost.
    if bin_residual == bin_capacity {
        score += 18.0 + 0.15 * mean_residual;
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // But if many open bins exist and mean residual is small, new bin is fine.
        if open_bins_count > 4 && mean_residual < 15.0 {
            score -= 20.0;
        }
    }

    // Prefer filling bins with below-average residual (tighter bins first).
    if bin_residual != bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.1 * diff;
    }

    // Fractional coupling on capacity fractions: residuals in (50, 75] are
    // semi-harmonic (still fit most items), residuals below 25 are risky.
    if frac > 0.5 && frac <= 0.75 {
        score -= 5.0;
    } else if frac < 0.25 && frac > 0.0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "unusable" if it is smaller than the smallest plausible item (1..100 stream),
    // but practically we penalize gaps in the awkward 1..=15 range super-linearly.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap <= 15.0 {
            score += (16.0 - gap) * (16.0 - gap) * 4.0; // quadratic dead-space penalty
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits relative to bin capacity.
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * tightness;

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bins pressure: with many open bins, discourage opening another.
    // For a brand-new empty bin candidate, add a penalty that grows with open_bins_count.
    if bin_residual == bin_capacity {
        score += 20.0 + 6.0 * open_bins_count as f64;

        // But if no open bin fits well (large item, few fitting bins), allow new bin:
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit in the leftover: mild penalty for fragmenting.
            score += 8.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is near the mean
    // (balanced packing), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Slight progression effect: later in the stream, be more conservative
    // about wasting space (dead space costs more when few items remain).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

