            let follow_fit = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - follow_fit / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leaving a large unusable gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Coupling with mean residual: favor bins tighter than average (first-fit-decreasing flavor)
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > bin_capacity as f64 * 0.5
            || (next_item_size > 0 && post_residual < next_item_size && post_residual > 0);
        if poor_fit {
            score -= 15.0;
        } else {
            score += 30.0;
        }
    }

    // Late in stream: consolidate into open bins rather than opening new ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
