    // Mild bonus for a new empty bin only when it's early or item is huge.
    if bin_residual == bin_capacity {
        let big = item_size as f64 / bin_capacity as f64;
        if big > 0.8 || progress < 0.05 {
            score -= 3.0;
        } else {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: penalize wasted space quadratically
    let mut score = x * x * cap + pr;

    // Smooth stream-progress coupling: later in stream, waste is costlier
    score += 40.0 * progress * (1.0 - x) * (1.0 - x);

    // Tight-fit reward: smooth sigmoid-like bonus for small post residual
    let tight = (-x * 8.0).exp();
    score -= 25.0 * tight;

    // Lookahead coupling: reward if next item fits in post residual (smooth)
    if next_item_size > 0 {
        let fits = (next_item_size as f64) <= pr;
        let smooth = 1.0 / (1.0 + ((next_item_size as f64 - pr) / 10.0).powi(2));
        if fits {
            score -= 20.0 * smooth;
        } else {
            score += 10.0 * (1.0 - smooth);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Prefer fuller bins relative to mean residual (smooth interaction)
    score -= (mean_residual - pr) * 0.3;

    // Slight penalty for many open bins to consolidate
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Harmonic class of post_residual: modulo classes over capacity
    let pr = post_residual;
    let class = pr % 10;
    match class {
        0 => score -= 15.0,          // perfectly reusable slot
        1 | 2 => score += 8.0,       // nearly dead space
        3..=6 => score -= 3.0,       // moderately reusable
        _ => score += 2.0,
    }

    // Integer division thresholds: post_residual divisible by common item sizes
    if pr > 0 {
        for &d in &[10u32, 20, 25, 50] {
            if pr % d == 0 {
                score -= 10.0;
                break;
            }
        }
    }

    // Dead space penalty: residual too small for the smallest plausible item
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // Exact next-item match is excellent
            if pr == next_item_size {
                score -= 30.0;
            } else {
                let gap = (pr - next_item_size) % 10;
                score -= 12.0 - gap as f64;
            }
        } else {
            // Next item can't use this residual; penalize proportionally
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        score += 35.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: must open
        }
        // Early stream: opening bins is cheaper (more future items to fill them)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
    }

    // Prefer bins below mean residual (keep a spread of residual classes)
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Many open bins: consolidate, favor fuller bins
    score += open_bins_count as f64 * 0.5;

    // Fractional capacity coupling: fill ratio squared reward
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fill * fill * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps (< 10% of capacity).
    if post_residual < bin_capacity / 10 {
        score += 12.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Penalize post_residuals that cannot fit the next item but are still non-trivial.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }
    // Reward leaving room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (0.15 + 0.1 * progress);

    // Last-chance bin bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Mild attraction to bins near the mean residual (balanced usage).
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    // New-bin candidate: allow opening a fresh bin only when the fit is poor
    // (large post_residual dead space) or pressure is low.
    if bin_residual == bin_capacity {
        score = 5.0 + (post_residual as f64) * 0.2 - (open_bins_count as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // Next item fits but leaves more dead space: mild penalty proportional to slack
    if next_item_size > 0 && next_item_size < post_residual {
        score += 0.3 * (post_residual - next_item_size) as f64;
    }
    // Next item won't fit here: slight penalty for wasting large residual
    if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 5.0;
    }

    // Prefer bins whose residual is below the mean residual (tight packing)
    score += 0.2 * ((post_residual as f64) - mean_residual).max(0.0);

    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize leaving dead space smaller than the minimum item size
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residual that no typical item (>=1) can use is worse
    // when it is small-but-unusable relative to next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0 + 0.25 * post_residual as f64;
    }

    // Lookahead synergy: if the next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // partial reward for leaving room usable by next item
        score -= 4.0 * (next_item_size as f64 / post_residual as f64);
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly so we prefer existing bins, but allow
    // opening when existing bins would waste a lot of space.
    if bin_residual == bin_capacity {
        score += 8.0;
        // Early in the stream, opening bins is cheaper (future items can fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Global pressure: many open bins with high mean residual -> prefer reusing
    // bins with large residuals; few bins -> consolidation matters.
    if open_bins_count > 0 {
        let pressure = mean_residual / bin_capacity as f64;
        score += 5.0 * pressure * (open_bins_count as f64).ln();
    }

    // Prefer bins whose residual is larger than the mean (they are more flexible to keep).
    if (bin_residual as f64) < mean_residual - 1.0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;

    // Base: quadratic penalty on wasted residual, weighted by stream progress
    let mut score = pr * (1.0 + 2.0 * progress * pr_norm);

    // Smooth cubic coupling of post-residual with progress
    score += 30.0 * pr_norm.powi(3) * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= 25.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * progress;

    // Penalize residual that cannot fit the lookahead item (dead space), smooth logistic gate
    if next_item_size > 0 {
        let gap = (next_norm - pr_norm).max(0.0);
        let gate = 1.0 / (1.0 + (-8.0 * (pr_norm - next_norm)).exp());
        score += 20.0 * gap * gate;
    }

    // Last-chance bin bonus: smooth function of fitting scarcity
    let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
    score -= 15.0 * scarcity * item_norm * (0.5 + progress);

    // Mild penalty for spreading across many open bins, coupled with mean residual
    score += 0.5 * open_bins_count as f64 * (mean_residual / cap).abs();

    // Penalize bins whose residual is far from mean (fragmentation), smooth quadratic
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate: make it moderately attractive only for large items / late stream
    if bin_residual == bin_capacity {
        let openness = 1.0 / (1.0 + (-(open_bins_count as f64 - 3.0)).exp());
        score = 0.6 * cap * (1.0 - progress) * (1.0 - item_norm)
              + 0.4 * cap * openness * (1.0 - item_norm)
              + item_norm * 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but reward "perfect" fits strongly.
    if post_residual == 0 {
        score -= 1000.0; // exact fill — perfect bin closure
    } else if post_residual <= 10 {
        score -= 200.0 - (post_residual as f64) * 10.0;
    }

    // Harmonic class logic: classify post_residual by modulo classes.
    // Items are 1..100; residual classes mod 10 capture "usable zone" structure.
    let pr = post_residual;
    let cls = pr % 10;
    let decile = pr / 10; // integer-division threshold band

    // Dead-space penalty grows super-linearly for residuals in awkward bands.
    // Residuals < 10 are usually unusable (min item size effectively ~1..10).
    if pr < 10 {
        score += (10 - pr) as f64 * 8.0; // near-dead space penalty
    }

    // Modulo coupling: residuals congruent to small values mod 10 pair well
    // with future small items; treat class 0 (multiples of 10) as premium.
    match cls {
        0 => score -= 30.0,                       // round residual: highly reusable
        1 | 2 | 3 => score -= 12.0,               // small remainder: still usable
        8 | 9 => score += 10.0,                   // awkward: just above a decade
        _ => {}
    }

    // Lookahead coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0; // lookahead perfect fit — reserve this bin
        } else if next_item_size <= pr {
            // Harmonic check: can next item land in a nice class after placement?
            let npr = pr - next_item_size;
            if npr % 10 == 0 {
                score -= 40.0;
            }
            if npr < 10 {
                score += 15.0; // would create near-dead space for the next item
            }
            // Fractional capacity coupling: next item as fraction of capacity
            let nf = next_item_size as f64 / bin_capacity as f64;
            let rf = pr as f64 / bin_capacity as f64;
            if nf > 0.5 && rf < 0.5 {
                score += 60.0; // big next item can't use this small residual well
            }
        } else {
            // next item won't fit here; mildly penalize if this is the only fitting bin
            if fitting_bins_count == 1 {
                score += 25.0;
            }
        }
    }

    // Last-chance bonus: if this is the only open bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: empty bin should only win when current bins are poor.
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline cost, adjusted by stream progress and load.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut newbin = 150.0;
        // If mean residual across open bins is small, new bin is attractive.
        newbin -= (100.0 - mean_residual).max(0.0) * 1.2;
        // Early in the stream, be more willing to open bins (build a portfolio).
        newbin -= (1.0 - progress) * 40.0;
        // If many bins are open and fragmented, discourage more bins.
        newbin += open_bins_count as f64 * 2.0;
        // If this item would leave a terrible residual in any existing bin,
        // the raw post_residual score already encodes that; keep newbin calibrated.
        score = score.min(f64::MAX); // safety
        return newbin;
    }

    // Global context: prefer placing into bins when mean residual is high (consolidation).
    score += mean_residual * 0.15;

    // Decile threshold shaping: encourage residuals landing in the 20-40 band
    // (fits a wide range of mid-size items).
    if (20..=40).contains(&decile * 10 + cls as u32) && pr >= 20 {
        score -= 10.0;
    }

    // Slight tie-break noise-free deterministic jitter via harmonic residue.
    score += ((item_size as f64 * 0.37).sin()) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // Gaps below the minimum item size (1..10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Medium dead space (10..=20) is risky too: only items <=20 can use it.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open bins pressure: prefer keeping the number of open bins low,
    // penalize opening new bins proportionally to current open count.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
    } else {
        // Slight reward for using existing bins, scaled by open-bin pressure.
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && (post_residual as u32) == next_item_size {
        score -= 30.0;
    }
    // If next item would leave this bin's residual unusable, penalize mildly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Progression: as the stream advances, tighten dead-space tolerance.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a "tight" bin — using it up is good.
    score -= 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward post_residual matching next_item_size exactly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Perfect match for next item is a jackpot.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving a gap that is too small for anything useful (dead space).
        if post_residual < 10 && post_residual > 0 {
            score += 15.0;
        }
    } else {
        // Last item: prefer tightest fit.
        score += 0.0;
    }

    // Compare post_residual relative to mean residual: prefer bins that end tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when item is large (little waste) or
    // no reasonable open bin exists. Penalize opening new bins early in the stream.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += 20.0 + waste * 0.8;
        // Late in the stream, opening a fresh bin is relatively more acceptable.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
        // If many bins fit the item, opening a new bin is wasteful.
        score += 5.0 * fitting_bins_count as f64;
    }

    // Slight preference for fuller bins (smaller residual before placement).
    score += 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize wasted residual, with a bonus for near-perfect fits.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * (bin_capacity as f64 * 0.6);

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            // Next item cannot fit here; penalize proportionally to the gap.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer fuller bins among many open bins (best-fit pressure).
    score -= (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Global state: when many bins are open relative to progress, tighten selection
    // to avoid bin proliferation; when few bins are open, be more permissive.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_pressure = open_bins_count as f64 / (total_items.max(1) as f64);
    score += open_pressure * 20.0 * (1.0 - progress);

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is an outlier worth consuming; if far above, it may still be valuable.
    let residual_diff = mean_residual - bin_residual as f64;
    score += residual_diff * 0.15;

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the item is large and would leave a fragmented residual.
    if bin_residual == bin_capacity {
        let poor_fit_penalty = if fitting_bins_count == 0 { -15.0 } else { 10.0 };
        let fragmentation = if item_size > 50 { 5.0 } else { 0.0 };
        score += 15.0 + poor_fit_penalty + fragmentation
            - (post_residual as f64 * 0.1);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (low post residual), with non-linear sharpening.
    let mut score = post * (1.0 + 0.8 * norm_post * (1.0 - norm_post));

    // Smooth polynomial coupling with stream progress: tighten packing later in the stream.
    score += 12.0 * norm_post * norm_post * (0.5 + progress);

    // Penalize dead space relative to mean residual across open bins.
    score += 0.15 * (post - mean_residual).abs();

    // Lookahead: reward bins whose post residual can host the next item (smooth kernel).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let slack = (post - nxt) / cap;
        if slack >= 0.0 {
            score -= 6.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 4.0 * slack * slack * cap;
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 - norm_post);
    }

    // Mild penalty for proliferating bins early; smooth in open_bins_count.
    score += 1.5 * (open_bins_count as f64).ln() * (1.0 - progress);

    // New-bin candidate: keep it slightly unattractive unless it beats poor fits.
    if bin_residual == bin_capacity {
        score += 8.0 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: bucket residual space by capacity fractions (integer division).
    let cap_class = post_residual / (bin_capacity / 4); // 0..4 classes
    let item_class = item_size / (bin_capacity / 4);

    // Reward residual classes that pair well with common item classes (modular coupling).
    let harmonic_bonus = ((cap_class as i64) - (item_class as i64)).abs();
    score += harmonic_bonus as f64 * 2.5;

    // Penalize very small dead space creation less if it comes from a large item
    // (tight fit is good): reward near-zero post_residual.
    if post_residual <= (bin_capacity / 10) {
        score -= 15.0;
    }

    // Perfect fit: exact zero residual is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_post = post_residual - next_item_size;
        if next_post <= (bin_capacity / 10) {
            score -= 20.0;
        }
        // Harmonic check: next item's class matches remaining class
        let next_class = next_item_size / (bin_capacity / 4);
        let rem_class = next_post / (bin_capacity / 4);
        if next_class == rem_class {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow here; penalize leaving a wedge that blocks it.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when the
    // item is large relative to capacity (harmonic class >= 2).
    if bin_residual == bin_capacity {
        if item_class >= 2 {
            score -= 5.0;
        } else {
            score += 10.0; // small items should use existing residual space
        }
    }

    // Mean residual coupling: if this bin is far below mean residual, it's a
    // leftover bin; using it balances the pool (moderate reward).
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += dev * 0.2; // prefer bins tighter than average
    }

    // Stream progression: late in the stream, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 15.0;
    }

    // Modular penalty: post_residual congruent to awkward values (mod 10)
    // that rarely match item sizes 10..80.
    let awkward = post_residual % 10;
    if awkward != 0 && post_residual > 0 {
        score += awkward as f64 * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps superlinearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    }
    // Penalize gaps that no plausible future item can use (items >= 1, but
    // gaps far below typical item sizes are dead weight).
    if post_residual > 0 && post_residual < item_size.min(30) {
        score += (post_residual as f64) * 0.8;
    }

    // Reward tight fits (waste-aware): bonus proportional to fill fraction.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_bias = 8.0 + open_bins_count as f64 * 1.5 + progress * 10.0;
    if bin_residual == bin_capacity {
        score += new_bin_bias;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + (next_item_size as f64 / 100.0) * 4.0;
        } else if post_residual > 0 {
            score += 3.0; // gap likely wasted w.r.t. lookahead
        }
    }

    // Prefer bins below mean residual (consolidate waste into few bins).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fit (small post_residual) is good.
    // Normalize post_residual relative to capacity.
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let tightness = 1.0 - post / cap;
    score -= 2.0 * tightness * cap * 0.5; // reward tight fits

    // Perfect fit bonus: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 5 {
        score -= 10.0;
    }

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        // If the next item fits exactly in the post residual: excellent chaining.
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // Next item fits: mild reward proportional to how well it fills.
            let fill_after_next = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - fill_after_next / cap);
        } else {
            // Next item does NOT fit in this bin after placement.
            // Penalize more if the leftover dead space is large and unusable.
            let waste = post as f64;
            if waste < nxt {
                // Dead space that the known next item can't use.
                score += 0.35 * (nxt - waste);
            }
        }
    } else {
        // Last item in stream: just minimize post residual strongly.
        score -= 5.0 * tightness;
    }

    // --- Mean residual coupling ---
    // Prefer bins whose residual is close to (or below) the mean: keeps bin
    // residuals balanced; avoid dumping into the emptiest bin unnecessarily.
    let dev = post - mean_residual;
    score += 0.15 * dev.abs();

    // --- Last-chance bin (only one fitting bin) ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // If this is a real open bin (not the new-bin candidate), strongly
        // prefer using it over opening a new bin.
        if bin_residual != bin_capacity {
            score -= 15.0;
        } else {
            // New-bin candidate when it's the only option: slight penalty
            // so genuine fits elsewhere win, but still usable.
            score += 3.0;
        }
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when the item is large and
        // no open bin offers a decent fit (post_residual small there).
        let frac = item_size as f64 / cap;
        if frac > 0.5 {
            score -= 6.0 * (frac - 0.5);
        } else {
            score += 8.0 * (0.5 - frac);
        }
        // More open bins => more reluctant to open another one.
        score += 1.5 * open_bins_count as f64;
    }

    // --- Stream progression: early on, be conservative with new bins ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Reward near-perfect fills strongly (dead space is the enemy).
    if post_residual < 5 {
        score -= 20.0;
    } else if post_residual < 15 {
        score -= 8.0;
    }

    // Lookahead (k=2): reward if the next item can also fit into the leftover space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 9.0 * (1.0 - 0.5 * progress);
        } else if next_item_size <= bin_residual {
            // This placement strands the next item elsewhere: mild penalty.
            score += 5.0;
        }
    }

    // Last chance: if this is the only bin that can fit the item, prefer it
    // to avoid opening a new bin for a poor fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 14.0;
    }

    // Tightness relative to global mean residual: prefer bins that are
    // already more filled than average (consolidation effect).
    if bin_residual != bin_capacity {
        let tightness = (mean_residual - bin_residual as f64).max(0.0);
        score -= 0.25 * tightness;
    }

    // New-bin candidate handling: penalize opening a new bin, but relax the
    // penalty when the item is large (a fresh bin wastes little) or when
    // several bins fit (so a good alternative exists anyway).
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        score += 22.0 + 9.0 * fitting_bins_count as f64;
        score -= 18.0 * item_frac;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0; // large item now, similar next: fresh bin may serve both
        }
        // Early in the stream, a fresh bin is cheaper insurance.
        score -= 6.0 * (1.0 - progress);
    }

    // Mild preference for bins that leave residuals compatible with common
    // item sizes (avoid tiny unusable slivers).
    if post_residual >= 10 && post_residual <= 30 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post residual, scaled non-linearly by stream progress
    let mut score = pr * (1.0 + 0.5 * progress * (1.0 - norm_pr));

    // Quadratic penalty on large post-residuals early (waste grows), reduced late
    score += 8.0 * (norm_pr * norm_pr) * (1.0 - progress);

    // Reward tight fits: small post residual relative to item size
    let tightness = 1.0 - (pr / (bin_residual.max(1) as f64));
    score -= 6.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bonus: only one fitting bin, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0 * (1.0 + progress);
    }

    // Penalize new-bin candidate unless post residual could host next item
    if bin_residual == bin_capacity {
        let hosts_next = next_item_size > 0 && (next_item_size as f64) <= pr;
        if hosts_next && open_bins_count > 0 {
            score += 3.0;
        }
        if open_bins_count == 0 {
            score -= 10.0;
        }
    }

    // Lookahead coupling: reward leaving space for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = norm_pr - nx;
        if gap.abs() < 0.1 {
            score -= 5.0 * (1.0 - gap.abs() / 0.1);
        } else if gap < 0.0 {
            score += 3.0 * (-gap);
        }
    }

    // Deviation from mean residual: prefer bins near the mean to balance
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev * (1.0 - progress);

    // Smooth cubic progress coupling on item size
    score += 3.0 * norm_item * norm_item * norm_item * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact-fill classes get strong reward.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit, best possible
    } else if pr <= 10 {
        score -= 60.0;
    } else if pr <= 20 {
        score -= 25.0;
    } else if pr <= 50 {
        score -= 8.0;
    }

    // Dead-space penalty: residuals that cannot hold typical small items (<=10)
    if pr > 0 && pr < 10 {
        score += 45.0;
    }

    // Lookahead coupling: reward if the post residual can host next item
    if next_item_size > 0 {
        if (pr as u32) >= next_item_size {
            score -= 15.0;
        } else {
            score += 12.0;
        }
        // harmonic match: post_residual divisible-ish with next item size
        if next_item_size > 0 && pr % next_item_size.max(1) == 0 && pr > 0 {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: neutral-ish, but prefer reusing bins with low residual
    if bin_residual == bin_capacity {
        score += 70.0; // default penalty so new bins lose to decent fits
        // open a new bin if item is large and no tight bin exists
        if item_size as f64 > 0.75 * cap {
            score -= 40.0;
        }
        if next_item_size > 0 && next_item_size as f64 + item_size as f64 > cap {
            score -= 20.0;
        }
    }

    // Tightness reward: bins with small residuals relative to capacity are precious
    let residual_frac = bin_residual as f64 / cap;
    score += 20.0 * residual_frac * residual_frac;

    // Mean residual context: if this bin is tighter than average, favor it
    score -= 5.0 * (mean_residual - bin_residual as f64).max(0.0) / cap;

    // Early stream: be slightly conservative about fragmenting bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - residual_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    } else if post_residual == 0 {
        // Perfect fit is ideal.
        score -= 60.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + next_item_size as f64 * 0.2;
    } else if next_item_size > 0 && post_residual > 0 {
        // Wasted potential relative to lookahead.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; with few, new bins ok.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score += pressure * 0.3 * (1.0 - progress * 0.5);

    // New-bin candidate: only attractive when current bin fit is bad.
    if bin_residual == bin_capacity {
        score += 25.0 - (fitting_bins_count as f64) * 5.0;
        if post_residual as f64 > mean_residual {
            score -= 10.0;
        }
    }

    // Slight preference for tight fits overall.
    score += (bin_residual - item_size) as f64 * 0.05;
    score -= (item_size as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.18;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large post-residuals more aggressively (dead space is superlinear bad).
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Reward tight fits: post_residual near 0 gets a bonus.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }
    // If next item cannot fit in post-residual but could fit elsewhere, mild penalty.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Many open bins: prefer filling existing bins over opening new ones.
    let open_penalty = (open_bins_count as f64).ln().max(0.0) * 8.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open.
        score += 25.0 + open_penalty;
        // Early in the stream, opening bins is cheaper; late in stream, avoid it.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 30.0;
    } else {
        score -= open_penalty * 0.5;
    }

    // Relative fit quality: fraction of bin used by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 50.0;

    // If this bin's residual deviates from mean residual, small coupling term.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Prefer bins with smaller residual overall (best-fit flavor) scaled by stream progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (bin_residual as f64 / bin_capacity as f64) * (20.0 + 40.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Penalize large dead space more as the stream advances
    score += 20.0 * norm_pr * norm_pr * progress;

    // Reward tight fits smoothly: quadratic bonus when post_residual is small
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Last-chance bin bonus (smoothly weighted)
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead coupling: favor bins leaving room for the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = pr - ni;
        if gap >= 0.0 {
            score -= 5.0 * (gap / cap);
        } else {
            score += 4.0 * (-gap / cap);
        }
    }

    // Mean residual interaction: penalize bins far from the mean state
    score += 0.3 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by
    // integer division into deciles of the capacity.
    let decile = post_residual / 10; // 0..=10 for C=100
    match decile {
        0 => score -= 40.0,          // near-perfect fit: tiny dead space
        1 => score -= 25.0,          // excellent fit
        2 => score -= 12.0,          // good fit
        3 | 4 => score -= 4.0,       // moderate fit
        5 | 6 => score += 6.0,       // half-empty: mediocre
        _ => score += 14.0,          // mostly empty: poor use of this bin
    }

    // Modulo arithmetic: leftovers that are "harmonic" with common item
    // sizes (multiples of 5 or 10) are more likely to be filled later.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 10.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Lookahead coupling: if the next item fits exactly into the
    // post-residual (or its harmonic class), strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use the leftover; penalize large leftovers
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid pushing us to open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has huge raw residual,
    // but opening bins is costly when few bins are open relative to
    // stream progress. Penalize the new-bin option adaptively.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_penalty = 60.0 + 40.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        score += new_bin_penalty;
        // but if existing bins would leave terrible dead space, soften
        if post_residual < item_size / 2 {
            score -= 25.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below the
    // mean (tighter bins first, classic best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any plausible item are pure waste.
    // Penalize sharply when post_residual falls into the "dead zone" (0 < post_residual < 10).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to the current bin residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 10.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoiding waste of residual here).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is not chosen unless open bins are poor fits.
        score += 20.0;
        // More pressure with many open bins: prefer reusing existing bins.
        score += open_bins_count as f64 * 2.0;
        // If the next item is large and this item leaves a residual that can host it,
        // opening a new bin is more attractive (chained placements).
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 8.0;
        }
    } else {
        // For existing bins, penalize leaving residual that cannot host the next item.
        if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 && post_residual > 0 {
            score += 6.0;
        }
        // Reward leaving residual that exactly accommodates the lookahead item.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Open-bins pressure: mildly discourage scattering across many bins.
    score += open_bins_count as f64 * 0.5;

    // Mean residual coupling: if this bin's residual is far below the mean, it's a
    // nearly-full bin; prefer filling it to close it out.
    let residual_gap = mean_residual - bin_residual as f64;
    if residual_gap > 0.0 {
        score -= residual_gap * 0.3;
    }

    // Early in the stream, allow slightly more freedom to open bins (exploration);
    // later, tighten reuse pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near match: next item fits with small waste.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 300.0 * (1.0 - slack / 60.0).max(0.0);
    }
    // Next item cannot use the leftover: penalize proportionally to waste.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 40.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Prefer bins tighter than the mean residual (good fill), penalize loose bins.
    score -= (mean_residual - post_residual as f64) * 0.8;

    // Slight preference for using existing bins over opening new ones as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 25.0 + 30.0 * progress;
    }

    // Penalize tiny unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tight = 1.0 - (post_residual as f64 / cap);
    score -= 30.0 * tight * tight;

    // Lookahead: if the next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= post_residual as f64 {
            let slack = (post_residual as f64 - ns) / cap;
            score -= 25.0 * (1.0 - slack);
        } else {
            // Next item won't fit here; penalize leaving large unusable gaps.
            score += 8.0 * (post_residual as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer bins with residuals below the mean residual (consolidate small leftovers).
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    // Time horizon: early in the stream, be more conservative about creating tiny residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 {
        score += 10.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress;
    }

    // Mild penalty when many bins are open; encourage consolidation.
    score += 0.15 * open_bins_count as f64;

    // New-bin candidate: make it moderately unattractive unless residuals are tiny.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;
    // smooth polynomial coupling of post_residual with stream progress
    let coupling = pr * (0.5 + progress * progress);
    score += 0.15 * coupling;
    // reward tight fits (small post_residual) more strongly later in the stream
    score -= (1.0 - pr / cap) * (1.0 + 2.0 * progress);
    // penalize large dead space quadratically
    score += 0.02 * (pr * pr) / cap;
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 5.0;
    }
    // lookahead: reward bins leaving space for the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 1.5;
    } else if next_item_size > 0 {
        score += 0.5 * (next_item_size as f64 - pr).min(20.0);
    }
    // mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies on "useful"
    // residue classes (multiples of small sizes) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        // Reward leftovers that divide evenly into common small item sizes.
        if pr % 10 == 0 { score -= 6.0; }
        else if pr % 5 == 0 { score -= 3.0; }
        // Penalize awkward dead-space classes.
        if pr % 10 >= 7 { score += 4.0; }
        if pr % 4 == 0 { score -= 1.5; }
        // Harmonic potential: number of divisor-friendly classes of pr.
        let mut div_potential = 0u32;
        for s in [10u32, 20, 25, 50].iter() {
            if pr % s == 0 { div_potential += 2; }
            if pr >= *s { div_potential += 1; }
        }
        score -= div_potential as f64 * 0.75;
    } else {
        // Perfect fill: strongly reward.
        score -= 40.0;
    }

    // Lookahead coupling: does the leftover accommodate next_item_size exactly/nicely?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 4.0;
            if slack % 10 == 0 { score -= 3.0; }
            if slack < 10 { score += 5.0; } // creates tiny dead space for item after next
        }
        // Harmonic match: next item divides the leftover exactly.
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 5.0;
        }
    }

    // Integer-division threshold on fill ratio (capacity fractions).
    let fill_frac = (bin_residual as f64) / cap;
    if fill_frac > 0.75 {
        score -= 3.0; // finishing a nearly-full bin is good
    } else if fill_frac < 0.25 && post_residual > 50 {
        score += 3.0; // barely denting a fresh bin wastes its flexibility
    }

    // Last-chance bin: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when current bin would leave a bad class.
    if bin_residual == bin_capacity {
        // Fresh bin baseline; penalize slightly so it's used only for good reason,
        // but reward when the stream is early and mean residual is already fragmented.
        score += 2.0;
        if mean_residual < 20.0 && open_bins_count > 2 {
            score -= 6.0;
        }
        if post_residual % 50 == 0 { score -= 4.0; }
    }

    // Stream progression: later in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64 / cap) * 4.0;

    // Mild penalty for scattering across many open bins.
    score += (open_bins_count as f64).ln() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10 - post_residual) as f64;
    }

    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward using bins that are already partially filled (avoid wasting fresh bins).
    let fill_ratio = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
    score -= 8.0 * fill_ratio;

    // Last-chance bin pressure: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin count pressure: many open bins -> discourage opening new ones,
    // i.e. slightly favor reusing bins when open_bins_count is large.
    score += 1.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    // Penalize leaving a gap just barely larger than the next item (fragmentation risk).
    if next_item_size > 0 && post_residual > next_item_size && (post_residual - next_item_size) < 10 {
        score += 10.0;
    }

    // New-bin candidate: neutral-ish baseline; only chosen if open bins score poorly.
    if bin_residual == bin_capacity {
        score += 20.0;
        // In late stream with many open bins, opening new bins is less attractive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }
    // Near-perfect match: next item fits with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 / (1.0 + slack * 0.15);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item won't fit here; penalize proportionally to wasted potential.
        let miss = (next_item_size - post_residual) as f64;
        score += miss * 0.3;
    }

    // Penalize tiny dead space that is likely unusable (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: only bin that fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when open bins are tight
    // or the fit here is bad relative to mean residual.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - (bin_capacity - item_size) as f64;
        if fitting_bins_count > 0 && mean_gap < 20.0 {
            score += 60.0; // keep using existing bins when they fit reasonably
        }
        score += open_bins_count as f64 * 0.5;
    } else {
        // Reward bins tighter than the mean residual (good space utilization).
        let diff = mean_residual - bin_residual as f64;
        score -= diff * 0.4;
    }

    // Late in the stream, be slightly more conservative about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: fraction of bin consumed by this placement
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 60.0 * fill_frac;

    // Penalize large dead space nonlinearly (small residuals are hard to reuse)
    let dead = post_residual as f64;
    if dead > 0.0 {
        score += dead * dead / 100.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 80.0;
        // extra reward if next item nearly fills what remains
        let next_fit = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 40.0 * next_fit;
    }
    // Penalize if next item would fit residual better than current item did
    if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let size_bonus = (item_size as f64 - 50.0) * 2.0;
        score += 250.0 - size_bonus - 100.0 * progress;
        // opening a bin is fine if item is huge (near capacity)
        if item_size >= 90 {
            score -= 300.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer existing bins
    if open_bins_count > 0 {
        score += (open_bins_count as f64).ln() * 10.0;
        score -= (mean_residual - post_residual as f64).abs() * 0.3;
    }

    // Slight preference to fill bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth non-linear coupling: post_residual weighted by stream progress
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Penalize residuals that are awkward relative to typical item sizes
    let mid_band = ((norm_pr - 0.5) * (norm_pr - 0.5)) * 30.0;
    score -= mid_band * (1.0 - progress);

    // Dead-space penalty: small post_residual with no useful lookahead fit
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = if pr >= nxt { 1.0 } else { 0.0 };
        score -= 8.0 * fits_next * (1.0 - pr / cap);
        score += 6.0 * (1.0 - fits_next) * (pr / cap) * (pr / cap);
    } else {
        score -= 5.0 * norm_pr;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - norm_pr);
    }

    // Prefer bins tighter than the mean residual, smoothly
    score += 3.0 * ((pr - mean_residual) / cap);

    // Slight preference for opening new bins early, using them tightly late
    score += 4.0 * progress * norm_pr * norm_pr * (open_bins_count as f64).sqrt();

    // Tight-fit reward: near-perfect fills
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Residuals divisible by common item sizes (e.g., 10, 20, 25, 50) are
    // more likely to be filled by future items -> reward them.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0f64;
        for m in [10u32, 20, 25, 50].iter() {
            if pr % m == 0 {
                harmony += 6.0;
            }
        }
        // Perfect fit is the best possible outcome.
        if pr == 0 {
            harmony += 40.0;
        }
        score -= harmony;
    } else {
        score -= 40.0;
    }

    // Penalize very small dead space that nothing (min size 10) can use.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly prefer this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size < pr {
            // Next item fits but leaves another residual: modulate by
            // whether that new residual is again harmonically clean.
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 {
                score -= 8.0;
            }
            score += (pr2 as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: prefer keeping it as a fallback; opening a new
    // bin should only win when the current fit is really bad.
    if bin_residual == bin_capacity {
        score += 18.0 + mean_residual * 0.05;
    }

    // Tight fits (large item relative to residual) are desirable.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // Late in the stream, consolidate more aggressively (fewer bins left
    // to amortize).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Spread of residuals: if this bin is far below mean residual, it is
    // an outlier worth filling to rebalance.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum plausible item size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }
    // Gaps that cannot fit the known next item are less attractive when the
    // lookahead item would otherwise be forced elsewhere.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward tight fits (small but usable post_residual in the usable range).
    if post_residual >= 10 {
        score -= 18.0;
    }

    // Perfect fill is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // New-bin candidate: opening a fresh bin is attractive only when existing
    // bins would leave bad dead space or when bin pressure is low.
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: its residual is maximal, so it naturally
        // scores high; discount it when it is genuinely the better option.
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score -= 30.0 + 8.0 * pressure;
        // If the current item fits nowhere else, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // Late in the stream, prefer reusing existing capacity.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Mild penalty for spreading across many open bins when mean residual is
    // still large (consolidation pressure).
    if open_bins_count > 3 && mean_residual > 30.0 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
