        score += 55.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 35.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
    }

    // Slight preference for using already-open bins when many are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Dead-space penalty: superlinear in leftover space, so tight fits are strongly preferred.
    score += 0.08 * (post_residual as f64).powf(1.35);

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 6.0 * progress;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            // Penalize wasting a bin early in the stream when the next item won't chain.
            score += 4.0 * (1.0 - progress);
        }
    }

    // New-bin candidate: give it a moderate handicap so it only wins when
    // all existing fits are poor (large post_residuals) or late in the stream.
    if bin_residual == bin_capacity {
        score += 7.0 + 5.0 * progress;
        // If the next item can also chain into a fresh bin, soften the handicap slightly.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 2.0;
        }
    }

    // Mild global pressure: prefer bins tighter than the mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    // smooth non-linear coupling: post residual value decays with stream progress
    score += norm_pr * norm_pr * (1.0 - t) * 20.0;
    // penalize tiny dead space more as stream advances (smooth cubic)
    score += (norm_pr - 0.5) * (norm_pr - 0.5) * (norm_pr - 0.5) * t * 10.0;
    // last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + t);
    }
    // lookahead: reward leaving room for the next item (smooth gaussian-like)
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 8.0 * (-(gap * gap) / (2.0 * 400.0)).exp();
        } else {
            score += (next_item_size as f64 - pr) * 0.15;
        }
    }
    // mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.05;
    // deviation from mean residual: prefer bins near the mean (balance)
    score += (pr - mean_residual).abs() * 0.1;
    // new-bin candidate: penalize slightly so it only wins when fits are bad
    if bin_residual == bin_capacity {
        score += 5.0 + norm_pr * 10.0 * t;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is "usable" for
    // common small-item classes (multiples of 10) deserve a bonus.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Dead-space penalty: leftovers in (0,10) are almost unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    // Sweet-spot bonus: post_residual in harmonic classes divisible by 10
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight fit reward: item fills >= 80% of the bin's current residual.
    let fill_ratio = item / bin_residual.max(1) as f64;
    if fill_ratio > 0.8 {
        score -= 8.0;
    } else if fill_ratio < 0.3 {
        score += 4.0; // dumping a small item into a big bin wastes it
    }

    // Lookahead coupling: prefer leaving post_residual that can host next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size as u32 {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 3.0;
        } else if post_residual > 0 {
            score += 5.0; // leftover too small for the next item
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource.
    if bin_residual == bin_capacity {
        // Prefer opening a new bin when existing leftovers are fragmented and small.
        let fragmentation = mean_residual / cap;
        if fragmentation < 0.25 {
            score -= 10.0; // open fresh bin rather than squeeze into scraps
        } else {
            score += 15.0; // plenty of room around: reuse open bins
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
        // Penalize new bins proportional to already open bins.
        score += 2.0 * open_bins_count as f64;
    }

    // Mild nudge toward bins tighter than average (best-fit flavor).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit reward
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * 100.0 * 0.2;

    // Open bins pressure: penalize using an existing bin when many are open,
    // to avoid over-fragmenting residuals across bins.
    score += 0.15 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless it is clearly better
    // (i.e., residual waste in existing bins is large).
    if bin_residual == bin_capacity {
        score += 20.0;
        // Allow new bin late in the stream when mean residual is small.
        if mean_residual < 15.0 {
            score -= 25.0;
        }
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Stream progression: early on, be more selective (penalize waste more);
    // later, prioritize closing out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact or near-exact 2-step lookahead match: strongly reward bins whose
    // post_residual will be consumed by the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if diff == 0.0 {
            score -= 1000.0; // perfect 2-chain: fill this bin with two items
        } else if diff <= 5.0 {
            score -= 200.0;
        } else if diff <= 15.0 {
            score -= 40.0;
        } else if post < nxt {
            // next item cannot fit here; small leftover is dead space
            score += (nxt - post) * 2.0;
        }

        // Chain bonus: residual + next item leaves room for typical future items
        let chain_residual = post - nxt;
        if chain_residual >= 0.0 && chain_residual <= 10.0 {
            score -= 60.0;
        }
    }

    // Penalize creating tiny unusable slivers (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }
    // Reward near-perfect fills
    if post_residual == 0 {
        score -= 300.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Relative-to-mean coupling: prefer bins below the mean residual
    // (tighter bins) to consolidate packing.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Early in the stream, be more willing to spread items (score new bins
    // relatively better); later, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize moderately, less so early on.
        score += 20.0 + 120.0 * progress;
    } else {
        // Existing bins get a mild base advantage that grows with progress.
        score -= 10.0 + 30.0 * progress;
    }

    // Too many open bins: discourage opening more, encourage filling existing.
    if open_bins_count > 8 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: perfect fill strongly favored.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let pr = post_residual as f64;
        // Non-linear penalty for large dead space (quadratic-ish).
        score += (pr * pr) / (bin_capacity as f64);
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        if slack_after_next == 0 {
            score -= 400.0;
        } else {
            score -= 150.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        }
    }
    // Penalize if next item would NOT fit here (fragmentation risk),
    // stronger when this bin is nearly the only option.
    if next_item_size > post_residual {
        score += 30.0 + 0.5 * next_item_size as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // global residual state is poor (open bins are nearly full) or many bins exist.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // New bin gets a baseline penalty so existing bins win by default,
        // reduced when bins are crowded and full.
        let mut nb = 200.0;
        nb -= 180.0 * avg_fill;
        nb -= 50.0 * progress;
        nb += 5.0 * open_bins_count as f64;
        score += nb.max(20.0);
    }

    // Mild global pressure: when mean residual is low, prefer reusing bins.
    score -= 0.3 * mean_residual;

    // Slight preference toward consolidating into fewer bins early on.
    score += 0.1 * open_bins_count as f64 * (1.0 - step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with smooth polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Non-linear coupling of post_residual with stream progress:
    // early on, waste is cheap; later, tight fills matter more.
    let coupling = 1.0 + 2.0 * progress * progress;
    score *= coupling;

    // Reward near-perfect fits via smooth tanh-like term on item fraction
    let fill = item_size as f64 / cap;
    score -= 15.0 * fill * fill * fill * (1.0 - norm_pr);

    // Penalize small-but-not-zero dead space (smoothly, no piecewise cutoff)
    score += 10.0 * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: reward leaving room for the next item smoothly
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            let ng = gap / cap;
            score -= 6.0 * ng * (1.0 - ng * ng);
        } else {
            score += 3.0 * (-gap / cap);
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Mild preference for consolidating into existing bins vs new bin:
    // new-bin candidate (residual == capacity) gets a smooth progress-based penalty
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    } else {
        score -= 2.0;
    }

    // Penalize bins far from mean residual (fragmentation indicator)
    score += 1.5 * (pr - mean_residual).abs() / cap;

    // Mild penalty for many open bins
    score += 0.3 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: prefer leftovers that lie in
    // "useful" residue classes likely to absorb small future items.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Class A: perfect fit -> extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Class B: leftover is small enough to be "dead space" (<= 10).
    // Penalize creating tiny unusable slivers, unless it's a near-perfect fit.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    }

    // Class C: leftover is a large usable chunk (>= 50): good harbor for
    // medium items. Reward modulo-friendly classes.
    if post_residual >= 50 {
        score -= 30.0;
    }

    // Harmonic (modulo) analysis of post_residual in units of 10:
    // leftover divisible by 10 aligns with typical item granularities.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    } else if post_residual % 5 == 0 {
        score -= 6.0;
    } else {
        // awkward remainder: mild penalty scaled by awkwardness
        score += (post_residual % 10) as f64;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 90.0;
        } else if next_item_size <= post_residual {
            // next item fits; reward tight chains, penalize wasteful gaps
            let gap = post_residual - next_item_size;
            score -= 25.0;
            if gap <= 10 {
                score -= 25.0; // chain leaves almost nothing behind
            }
        } else {
            // next item cannot use this bin's leftover; penalize proportionally
            score += (next_item_size as f64) * 0.3;
        }
    }

    // Last-chance logic: if this is the only bin that fits, prefer using it
    // over opening a new bin when the fit isn't terrible.
    if fitting_bins_count == 1 {
        score -= 40.0;
        if post_residual <= 20 {
            score -= 20.0; // very tight fit is excellent here
        }
    }

    // New-bin candidate handling: an empty bin has post_residual == bin_capacity.
    // Only open a new bin when existing fits are poor. We make the empty bin
    // attractive when the current fit leaves a big awkward leftover.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = cap * 0.55;
        // Cheaper to open a bin early in the stream (more future items to fill it).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score *= 1.0 - 0.35 * (1.0 - progress);
        // If many bins are open already, opening more dilutes packing; penalize.
        score += open_bins_count as f64 * 1.5;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size >= 60 {
            score -= 15.0;
        }
    } else {
        // Existing bin: mild bonus when mean residual is high (consolidation pressure).
        if mean_residual > cap * 0.5 && post_residual < (mean_residual as u32) {
            score -= 5.0;
        }
        // Tightness reward: fraction of bin consumed by this item.
        let fill = item_size as f64 / cap;
        score -= fill * 20.0;
    }

    // Late-stream tightening: as the stream ends, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for typical items
    // (likely unusable) are heavily penalized.
    if post_residual > 0 {
        let dead_threshold = 20.0f64;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 6.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits relative to residual (small waste ratio).
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 15.0;
    }

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        // Mild reward if next item can still fit in leftover space.
        score -= 5.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leftover that next item cannot use (dead space for lookahead).
        score += 8.0;
    }

    // New-bin candidate: make it moderately attractive only when current bins
    // would leave very poor fits (large dead space).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 45.0 + open_bins_count as f64 * 0.5;
        // If best alternative would leave big dead space, new bin becomes better.
        if post_residual > 0 && (bin_residual - item_size) as f64 >= 0.0 {
            // A fresh bin leaves bin_capacity - item_size residual; compare via
            // mean residual pressure: if mean residual is small (bins nearly full),
            // opening new bin is natural.
            if mean_residual < 15.0 {
                score -= 20.0;
            }
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Slight preference for fuller bins overall (mean residual coupling):
    // bins whose residual is below mean are more "committed", favor them.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for leftover space that cannot host the next item (dead space).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins whose residual exactly or closely matches the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 - 0.15 * slack.min(30.0);
        } else {
            // Dead space: penalize proportionally to how much is wasted.
            let dead = (next_item_size - post_residual) as f64;
            score += 6.0 + 0.25 * dead;
        }
    }

    // Perfect-fit bonus: leaving zero residual is excellent.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than average residual.
    score += 0.10 * ((bin_residual as f64) - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize opening a brand-new bin when reasonable alternatives exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 + 10.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0; // empty bin fits next item too
        }
    }

    // Slight preference for larger items placed earlier in tighter bins.
    score += 0.02 * item_size as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post_residual is good).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
