    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * fit_ratio;
    }

    // Time horizon: late in the stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fit_ratio;

    // New-bin candidate handling: penalize opening a new bin, more so when
    // open bins exist and mean residual is healthy.
    if bin_residual == bin_capacity {
        score += 25.0;
        if open_bins_count > 0 {
            score += 10.0 * (mean_residual / bin_capacity as f64).min(1.0);
        }
        if next_item_size > 0 && next_item_size <= item_size {
            score += 5.0; // small next item could have used an existing bin
        }
        if fitting_bins_count == 1 && item_size >= 70 {
            score -= 20.0; // big item with no real alternative: allow new bin
        }
    } else {
        // Prefer bins whose residual is close to the item (best-fit flavor).
        score += 0.15 * (bin_residual as f64 - item_size as f64);
    }

    // Mildly prefer bins with residual below mean (compact bins fill first).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    score += 30.0 * norm_pr * norm_pr * (0.5 + progress);
    score -= 20.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Dead-space penalty: small post_residual relative to possible next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += 8.0 * ((nxt - pr) / cap);
        } else {
            score -= 6.0 * (1.0 - (pr - nxt) / cap);
        }
    }

    // Last-chance bonus: smooth reward when few fitting bins
    let fit_frac = 1.0 / (fitting_bins_count as f64);
    score -= 15.0 * fit_frac * fit_frac;

    // Mild dispersion penalty vs mean residual
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate handling: prefer it only late in stream or when it's clean
    if bin_residual == bin_capacity {
        score -= 5.0 * progress;
        score += 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity fractions (mod classes)
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;

    // Dead-space penalty grows superlinearly for unusable residuals
    if post_residual < quarter {
        score += 40.0; // tiny dead space is fine, but keep ordering
        score -= 25.0; // net reward for near-perfect fit
    } else if post_residual < third {
        // residual in [25,33): only items >= 25 can use it later
        score += 8.0;
    } else if post_residual < half {
        // residual in [33,50): moderately reusable
        score += 2.0;
    } else {
        // residual >= half: very reusable, reward
        score -= 6.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 60.0;
        } else if slack < quarter {
            score -= 30.0;
        } else {
            score -= 10.0;
        }
    }
    // Penalize if next item does NOT fit this bin's post_residual
    if next_item_size > post_residual && next_item_size > 0 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // New-bin candidate (empty bin): penalize opening new bins unless
    // the fit into this bin would be terrible or few bins fit the item.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score += 55.0;
        // More open bins => mild extra penalty (fragmentation avoidance)
        score += open_bins_count as f64 * 0.5;
        // If many bins fit the item, opening a new bin is wasteful
        if fitting_bins_count > 2 {
            score += 30.0;
        }
        // If only this (nonexistent) fit is tight elsewhere, allow new bin:
        // handled implicitly when open-bin scores are high.
        // Reward opening a new bin when mean residual is high (open bins are full-ish)
        score -= (mean_residual / cap) * 10.0;
    }

    // Prefer filling bins that are already partially loaded (waste-avoidance):
    // reward proportional to used fraction of the bin.
    let used_frac = (bin_capacity - bin_residual) as f64 / cap;
    score -= used_frac * 12.0;

    // Stream progression: early on, be conservative about tight fits;
    // late in the stream, be aggressive (closing bins cleanly matters more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * used_frac;

    // Mean-residual coupling: if this bin's residual is far below mean,
    // it is an outlier worth filling.
    let res_diff = mean_residual - post_residual as f64;
    if res_diff > 0.0 {
        score -= res_diff * 0.15;
    }

    // Modulo harmonic tie-breaker on post_residual classes (small jitter-free bias)
    let class = (post_residual % (bin_capacity / 10).max(1)) as f64;
    score += class * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (1..=10) are almost unusable
    // for future items; penalize them heavily beyond their raw size.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (1.0 + (11 - post_residual) as f64);
    }

    // Perfect fit is ideal: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward post-residuals that can still host a typical future item
    // (>= 10 or >= next_item_size when known).
    let min_useful = if next_item_size > 0 { next_item_size.min(10) } else { 10 };
    if post_residual >= min_useful {
        score -= 15.0;
        // Bonus if the lookahead item itself fits exactly here (k=2 chaining).
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 35.0;
        }
    }

    // Penalize wasting a large residual on a small item when many bins
    // could also fit (prefer keeping big gaps for big items).
    if item_size < 30 && post_residual > 40 {
        score += 12.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    score += (open_bins_count as f64) * 0.8;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 25.0;
        // If this bin is the only fitting option (i.e., no open bin fits),
        // opening is necessary; reduce the penalty.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
        // Late in the stream, prefer closing out existing bins rather than
        // opening new ones with residual capacity around.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.7 && mean_residual > 15.0 {
            score += 30.0;
        }
    }

    // Mild tie-breaker: prefer bins whose residual deviates from the mean
    // (consolidate space into few bins).
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize small dead space (< smallest plausible item)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 60.0 + 0.5 * next_item_size as f64;
        } else {
            // penalize residuals that can't host the next item
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
        // perfect two-item packing: post_residual exactly equals next item
        if post_residual == next_item_size {
            score -= 200.0;
        }
    }

    // Compare against mean residual: prefer bins with residual near mean (balanced packing)
    score += 0.2 * (bin_residual as f64 - mean_residual).abs();

    // Last-chance bin before opening a new bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item fits well
    if bin_residual == bin_capacity {
        let waste = bin_capacity - item_size;
        score += 150.0 + waste as f64;
        // allow opening new bin for large items that leave useful residual
        if item_size >= 50 && waste <= 50 {
            score -= 120.0;
        }
    }

    // Slight preference for tighter bins as stream progresses
    score += 0.1 * (step_index as f64 / total_items.max(1) as f64) * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that no future item can plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable sliver
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; penalize leaving large awkward gaps.
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // Global state coupling: many open bins with high mean residual → consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let consolidation = (mean_residual - post_residual as f64).abs();
    score += 0.4 * consolidation * (1.0 - progress);

    // Prefer bins below mean residual early (balance), above later (fill).
    if (post_residual as f64) < mean_residual {
        score -= 2.0 * progress;
    } else {
        score += 1.5 * (1.0 - progress);
    }

    // New-bin candidate: default penalty so we prefer existing bins,
    // but relax the penalty late in the stream or when many bins are open.
    if is_new_bin {
        let penalty = 20.0 - 10.0 * progress - 0.5 * (open_bins_count as f64).min(10.0);
        score += penalty.max(4.0);
        // Opening a fresh bin is attractive if item is large and fits poorly anywhere.
        if item_size >= 60 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let post_norm = post / cap;
    let next_norm = next_item_size as f64 / cap;

    // Base: penalize wasted space, amplified nonlinearly as stream progresses.
    let mut score = post * (1.0 + 1.5 * progress * post_norm);

    // Smooth polynomial coupling of tightness with progress.
    let tightness = 1.0 - post_norm; // how well the item fills the bin
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Dead-space penalty: residual too small for typical future items.
    let dead = if post_norm > 0.0 && post_norm < next_norm.max(0.01) { (next_norm - post_norm).min(1.0) } else { 0.0 };
    score += 20.0 * dead * dead * (1.0 - progress);

    // Lookahead: reward if next item fits into post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * next_norm * (1.0 + progress);
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Mild pressure toward consolidation when many bins are open.
    score += 2.0 * open_bins_count as f64 * post_norm;

    // New-bin candidate handling: make empty bins attractive only when
    // current fit is poor; otherwise keep them slightly disfavored.
    if bin_residual == bin_capacity {
        let poor_fit = (post - post).max(0.0); // no-op guard
        let _ = poor_fit;
        score = cap * (0.9 + 0.5 * progress) - 10.0 * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: reward post_residuals in "reusable" classes (multiples of 10, 25, 50)
    if post_residual % 50 == 0 {
        score -= 6.0;
    } else if post_residual % 25 == 0 {
        score -= 3.0;
    } else if post_residual % 10 == 0 {
        score -= 1.5;
    }

    // Dead-space class: small odd residuals are hard to fill
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    } else if post_residual < 20 && post_residual % 2 == 1 {
        score += 3.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 10.0;
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 4.0 + (next_item_size as f64) / 10.0;
        } else {
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize slightly unless open bins are congested
    if bin_residual == bin_capacity {
        score += 15.0 - (fitting_bins_count as f64) * 2.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (denser bins)
    if (post_residual as f64) < mean_residual {
        score -= 1.0;
    } else {
        score += 1.0;
    }

    // Late-stream tightness: as stream progresses, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.05;

    // Integer-division threshold: bins whose residual halves into small space are valuable
    if post_residual / 2 <= 15 && post_residual > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: post_residual that is too small to fit a future item
    // (items range 1..100, so gaps < ~10 are nearly unusable; gap < next_item is unusable for lookahead)
    if post_residual > 0 {
        let min_useful = 1u32.max(next_item_size.min(10));
        if post_residual < min_useful {
            score += 40.0 + (min_useful - post_residual) as f64 * 3.0;
        }
        // Next item fits exactly into the post-residual: strong reward
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0 + (post_residual == next_item_size) as i32 as f64 * 10.0;
        }
    } else {
        // Perfect fit: strongly reward closing the bin
        score -= 25.0;
    }

    // Tight fit reward: fraction of bin used by this placement
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 15.0;

    // Open-bin pressure: when many bins are open, discourage spreading (favor filling existing),
    // but when few bins open and fit is poor, opening a new bin is cheap.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 2.5;

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so it only wins when
    // no open bin offers a decent fit; penalty grows with stream progression (late stream
    // favors consolidation since remaining items are few).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 15.0 * progress;
        // But if the item is large relative to mean residual, opening fresh is fine
        if item_size as f64 > mean_residual {
            score -= 18.0;
        }
    }

    // Slight penalty for leaving residual far from mean (fragmentation signal)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Small lookahead coupling: if next item cannot fit in this bin's residual but could
    // fit a fresh bin, nudge toward new bin for large items
    if next_item_size > post_residual as u32 % (bin_capacity + 1) && post_residual > 0 {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item exactly.
    if next_item_size > 0 && next_item_size <= post_residual {
        // Perfect chain fit: post_residual equals next item size -> residual becomes 0 next step.
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        score -= 60.0 / (1.0 + gap);
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize proportionally to wasted space.
        score += 0.5 * next_item_size as f64;
    }

    // Compare against mean residual: prefer bins tighter than average (best-fit style).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Penalize creating unusable dead space (< smallest possible item).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it less attractive unless it enables a perfect lookahead chain.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && (bin_capacity as u64 - item_size as u64) >= next_item_size as u64 {
            let gap = (bin_capacity - item_size) as f64 - next_item_size as f64;
            score -= 50.0 / (1.0 + gap);
        } else {
            score += 25.0;
        }
    }

    // Late in the stream, tighten packing (prefer filling existing bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tight = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tight).powi(3);

    // Penalize dead space that cannot fit the next item (lookahead-aware waste).
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        } else {
            // Reward leaving space that can host the next item.
            score -= 0.3 * next_item_size as f64 * (1.0 - tight);
        }
    }

    // Last-chance bonus: only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize opening new bins when plenty of open bins exist with slack.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let slack = mean_residual - item_size as f64;
        score += 15.0 + 10.0 * progress.max(0.0);
        if slack > 0.0 {
            score += slack.min(40.0);
        }
        // Opening a new bin is fine when item is large and next item pairs well.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Mild preference for filling bins with larger residual (reduce bin count pressure).
    score -= 0.05 * open_bins_count as f64 * (1.0 - tight);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let is_new_bin = (bin_residual == bin_capacity) as f64;

    // Base: minimize leftover, with non-linear (quadratic/cubic) shaping
    let mut score = pr + 18.0 * norm_pr * norm_pr * cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let coupling = pr * (0.5 + 1.5 * progress * progress) * (1.0 - norm_pr);
    score += 6.0 * coupling;

    // Late in the stream, tighten more aggressively (smooth ramp)
    score += 10.0 * norm_pr * progress * progress;

    // Penalize opening a new bin when alternatives exist (smooth in fitting count)
    let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
    score += is_new_bin * (25.0 + 20.0 * scarcity + 15.0 * progress);

    // Reward near-perfect fills smoothly
    score -= 14.0 * (1.0 - norm_pr).powi(6);

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        let fits_next = (post_residual >= next_item_size) as f64;
        let snug = 1.0 - ((post_residual - next_item_size) as f64 / cap).abs();
        score -= fits_next * (8.0 + 10.0 * snug * snug);
    }

    // Mild penalty for bins far below mean residual (keeps spread balanced)
    score += 0.05 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues divisible by common
    // item sizes (5, 10, 20, 25, 50) are more reusable than awkward ones.
    let pr = post_residual;
    let mut harmony: f64 = 0.0;
    if pr == 0 {
        harmony -= 40.0; // perfect fit: ideal
    } else {
        if pr % 50 == 0 { harmony -= 14.0; }
        else if pr % 25 == 0 { harmony -= 10.0; }
        else if pr % 20 == 0 { harmony -= 8.0; }
        else if pr % 10 == 0 { harmony -= 5.0; }
        else if pr % 5 == 0 { harmony -= 2.0; }
        // penalize dead space that is too small for typical items
        if pr < 10 { harmony += 30.0 + (10 - pr) as f64 * 4.0; }
        else if pr < 20 { harmony += 6.0; }
    }
    score += harmony;

    // Reward tight fits (small post_residual relative to capacity)
    score -= 25.0 * (1.0 - (post_residual as f64 / cap)).min(1.0).max(0.0) * (1.0 - post_residual as f64 / cap);

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; slight penalty for leaving odd residue
            score += 4.0;
        }
    }

    // New-bin candidate handling: only open a new bin when existing bins
    // would create very small, unusable residues or the stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fit = mean_residual / open_bins_count.max(1) as f64;
        // default mild penalty so real bins win ties
        let mut nb = 18.0;
        if item_size as f64 > mean_residual * 0.9 { nb -= 25.0; }
        if progress < 0.15 { nb -= 5.0; }
        if avg_fit < item_size as f64 { nb -= 10.0; }
        score += nb;
    }

    // Mild preference for fuller bins when many bins are open
    score -= 0.05 * open_bins_count as f64 * (1.0 - post_residual as f64 / cap);

    // Small stream-progress modulation: tighten criteria later in stream
    score += (step_index as f64 / total_items.max(1) as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score += 15.0; // nearly-dead space still bad
    }

    // Reward bins whose residual can still host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0; // creating a gap that cannot fit next item
        }
    }

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: prefer consolidation when many bins are open.
    score += 0.4 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Late in the stream, tighten up: favor fuller bins even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 12.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New empty bin: penalize unless current residuals are all poor fits.
    if bin_residual == bin_capacity {
        score += 25.0;
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
        if mean_residual > 0.0 && mean_residual < item_size as f64 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly or
    // nearly matches the next item size (chained perfect fits).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // Next item fits here afterward: reward tight chains.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
            if gap < 1.0 {
                score -= 40.0; // exact 2-item chain completion
            }
        } else {
            // Dead space the next item cannot use: penalize proportionally.
            score += 0.5 * gap;
        }
    } else {
        // Last item: prefer minimal waste directly.
        score += 0.2 * post_residual as f64;
    }

    // Relative-to-mean residual: prefer bins tighter than average
    // (best-fit flavor), penalize bins looser than average.
    let res = post_residual as f64;
    score += 0.3 * (res - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless post fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when the item
    // is large relative to capacity or all fits are poor.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // Penalize opening a new bin for small items / good existing fits.
        score += 20.0 + 40.0 * (1.0 - tightness);
        if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 2.0 {
            score -= 35.0; // fresh bin enables a perfect 2-chain
        }
    }

    // Late-stream urgency: consolidate more aggressively as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - res / bin_capacity as f64);

    // Slight preference for bins among many open bins to reduce bin count.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual (non-linear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 14.0;
            // Extra reward if next item then leaves a very tight residual.
            let chain_post = post_residual - next_item_size;
            score -= 8.0 * (1.0 - chain_post as f64 / bin_capacity as f64);
        } else if post_residual > 0 && next_item_size > post_residual {
            // Dead space likely: penalize proportionally to unusable gap.
            score += 4.0 * (post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize bins far from the mean residual (avoid fragmenting the pool unevenly).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Prefer fuller bins as the stream progresses (early: keep flexibility).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: empty bin should only win when no open bin
    // fits well or the current item is large relative to capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so open bins with decent fits win.
        score += 30.0;
        // Large items: opening a fresh bin is more attractive.
        let size_frac = item_size as f64 / bin_capacity as f64;
        score -= 35.0 * size_frac * size_frac;
        // Late in the stream with many open bins, avoid spreading waste.
        if open_bins_count > 3 {
            score += 3.0 * (open_bins_count as f64).ln();
        }
        // If next item is large too, a fresh bin gives more future room.
        if next_item_size >= item_size && next_item_size > 0 {
            score -= 10.0;
        }
    } else {
        // Open bins get a mild structural bonus for already being invested.
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) * 40.0
                 - norm_pr * progress * 30.0;
    score += coupling;

    // Penalize dead space more strongly late in the stream (smooth polynomial)
    score += (norm_pr * norm_pr) * (progress * progress) * 25.0;

    // Reward tight fits smoothly
    let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
    score -= (1.0 - tightness * tightness) * 12.0;

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead: favor leaving space for next item (smooth interaction)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += (gap / cap) * 15.0 * (0.5 + progress);
    }

    // Mild penalty when many bins are open
    score += open_bins_count as f64 * 0.3 * progress;

    // New-bin candidate: penalize slightly unless residual is large
    if bin_residual == bin_capacity {
        score += 8.0 - norm_pr * 0.0 + (1.0 - progress) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residue modulo capacity fractions.
    let cap = bin_capacity as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Reward tight fits: harmonic class of post_residual near zero is good.
    let mod_class = post_residual % quarter;
    score -= (quarter - mod_class) as f64 * 0.35;

    // Penalize dead space in the "unusable" band (1..eighth): small leftovers rarely filled.
    if post_residual > 0 && post_residual < eighth {
        score += 45.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Lookahead coupling: if next item exactly fills the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward scaled by how much slack remains after both
            let after2 = post_residual - next_item_size;
            score -= 25.0 - (after2 as f64) * 0.2;
        } else {
            // next item cannot use this bin's residual: penalize large residuals
            score += (post_residual as f64 - mean_residual).abs() * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let mean_fit_gap = (mean_residual - item_size as f64).abs();
        if fitting_bins_count == 0 {
            score -= 200.0; // must open new bin
        } else if mean_fit_gap > 30.0 || post_residual > 0 && post_residual < eighth {
            score -= 40.0;
        } else {
            score += 55.0; // keep using open bins when they fit reasonably
        }
    }

    // Stream progression: late in stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / cap);

    // Slight preference for bins with residuals in harmonic multiples of 10.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // smallest plausible future item are pure waste -> heavy penalty.
    if post_residual > 0 {
        let dead_threshold = 12u32;
        if post_residual <= dead_threshold {
            score += 60.0 * (1.0 + (dead_threshold - post_residual) as f64 / dead_threshold as f64);
        } else if post_residual < 20 {
            score += 25.0;
        }
        // Perfect fit bonus
        if post_residual == 0 {
            score -= 100.0;
        }
        // Reward residuals that can still hold the lookahead item (k=2 lookahead)
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0 + 0.2 * next_item_size as f64;
        } else if next_item_size > 0 && post_residual > 0 {
            // residual becomes dead relative to the known next item
            score += 10.0;
        }
    } else {
        score -= 100.0;
    }

    // Tight-fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if fill_ratio > 0.7 {
        score -= 20.0 * (fill_ratio - 0.7) / 0.3;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into existing
    // bins rather than spreading; make new bins less attractive.
    let pressure = (open_bins_count as f64).ln() + 1.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly above average residual so that any
        // reasonable existing fit wins; only becomes attractive when existing
        // residuals are tiny compared to the item (poor fits everywhere).
        score += 30.0 + 8.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open
        } else if fitting_bins_count == 1 {
            // last-chance bin: strongly prefer it over opening a new bin
            score += 120.0;
        }
    } else if fitting_bins_count == 1 {
        // This is the only bin that fits: use it to avoid a new bin
        score -= 40.0;
    }

    // Prefer bins whose residual is close to the item (minimal waste)
    let waste = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * waste;

    // Mild stream-progression coupling: late in the stream, be greedier about
    // closing bins (avoid leaving many half-empty bins at the end).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (mean_residual / bin_capacity as f64);

    // Prefer bins below mean residual (consolidate emptier bins first)
    score += 0.5 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress factor: later in the stream, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            // Perfect chain: this bin will be exactly filled by the next item.
            score -= 60.0 + 40.0 * progress;
        } else if diff > 0 {
            // Post residual can still host the next item: mild reward scaled by tightness.
            let tight = 1.0 - (diff as f64 / bin_capacity as f64);
            score -= 25.0 * tight * tight;
        } else {
            // Next item cannot fit here: dead space penalty, stronger late in stream.
            let dead = (-diff) as f64;
            score += dead * (0.4 + 0.8 * progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && post_residual <= bin_capacity {
        score -= 45.0;
    }

    // Penalize bins whose residual deviates far below the mean residual (fragmented bins).
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += 0.35 * dev;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 && next_item_size <= item_size { 0.0 } else { 1.0 };
        score += 8.0 + 6.0 * open_bins_count as f64 * pressure * (1.0 - progress);
    }

    // Small nudge toward tighter fits overall.
    score += 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively for large items.
    let frac_used = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * frac_used * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize dead space that is too small for typical future items.
    let t = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - t);
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly, but allow opening when existing residuals are poor.
    if bin_residual == bin_capacity {
        let poor_fit = if bin_residual >= item_size { 0.0 } else { 0.0 };
        let _ = poor_fit;
        let mean_gap = (mean_residual - item_size as f64).abs();
        score += 30.0 - 0.5 * mean_gap - 10.0 * t;
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // Prefer new bin when item is large and no bin has a good fit.
        if item_size as f64 > 0.6 * bin_capacity as f64 && mean_residual < item_size as f64 {
            score -= 20.0;
        }
    }

    // Encourage balancing residuals toward the mean early on.
    score += 0.1 * (bin_residual as f64 - mean_residual).abs() * (1.0 - t);

    // Slight preference for filling fuller bins as stream progresses.
    score += 5.0 * t * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Core: post-residual with smooth polynomial shaping (favor tight fits)
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Non-linear coupling with stream progress: later in stream -> tolerate less waste
    score += post * (0.6 * progress + 0.4 * progress * progress);

    // Dead-space penalty: residual that is small but nonzero is unusable dead space
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * (1.0 + 2.0 * progress);
    }

    // Lookahead coupling: reward residual that can still host the next item smoothly
    if next_item_size > 0 {
        let fits_next = (norm_post - norm_next).max(0.0);
        score -= 6.0 * (1.0 - (fits_next / (1.0 + fits_next)).powi(2));
        // penalty if residual is just barely below next item (near-miss waste)
        let gap = norm_next - norm_post;
        if gap > 0.0 && gap < 0.15 {
            score += 8.0 * (0.15 - gap) / 0.15;
        }
    }

    // Last-chance bonus: only fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild diversity term: prefer bins deviating from mean residual (balance)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 3.0 * dev * dev.abs();

    // New-bin candidate: smooth penalty growing with number of open bins
    if bin_residual == bin_capacity {
        score += 4.0 + 0.5 * (open_bins_count as f64).sqrt() + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues mod 10 classify dead space.
    let r = post_residual % 10;
    // Waste penalty grows when post residual is small but unusable for typical items.
    if post_residual > 0 {
        let class_penalty = match r {
            0 => -2.0,           // perfectly classed residual, attractive
            1 | 2 | 3 => 3.0,    // tiny slivers -> dead space
            4 | 5 | 6 => 1.0,    // marginal slivers
            _ => -0.5,           // 7..9 usable-ish chunks
        };
        score += class_penalty;
    } else {
        // Perfect fill is ideal.
        score -= 15.0;
    }

    // If the next item fits exactly into the post residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= (10.0 - gap as f64).max(0.0);
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Post residual cannot host the lookahead: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it unattractive unless current bins are very full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Attractive only when mean residual of open bins is too small for future items.
        let scarcity = (20.0 - mean_residual).max(0.0);
        score = 100.0 - scarcity * 2.0 - progress * 5.0;
        // If this is the last fitting option, allow opening a new bin.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Slight preference for fuller bins (smaller residual) beyond linear term.
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fullness * 5.0;

    // Tie-break noise-free harmonic jitter on bin residual class.
    let class = bin_residual / 10;
    score -= (class % 3) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit the
    // smallest plausible item (<= 10) are pure waste; penalize hard.
    if post_residual < 10 {
        score += 100.0;
    }

    // Penalize residuals that cannot accommodate the lookahead item,
    // but only if the lookahead is real and reasonably sized.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Reward tight fits (small post_residual) with a super-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 30.0;

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += open_bins_count as f64 * 8.0 + 25.0;
        // If this is the only fitting bin, strongly prefer using it over a new bin.
        if fitting_bins_count == 1 {
            score += 200.0;
        }
    } else if fitting_bins_count == 1 {
        // Last chance before a new bin: reward using this bin.
        score -= 40.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // (they are the "fuller" bins, keeping emptier bins flexible).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Slight stream-progression bias: later in the stream, consolidate more
    // aggressively (avoid leaving many half-empty bins at the end).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer small post-residual (tight fit).
    score += (post_residual as f64) * 0.5;

    // 2-step lookahead: reward when next item fits the post-residual exactly or well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
            if slack == 0.0 {
                score -= 20.0; // perfect chaining
            }
        } else {
            // next item cannot use leftover: penalize dead space proportionally
            score += 10.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 30.0;
        if post_residual as f64 > mean_residual {
            score += 10.0;
        }
    }

    // Late-stream consolidation: favor existing bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Penalize dead space: residual too small for typical future items (1..100)
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // next item won't fit here after placement; slight penalty
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Global state: many open bins -> prefer filling existing ones over opening new
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.8;
    score -= progress * 10.0;

    // Mean residual coupling: if this bin's residual is far below mean, it's a good filler
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let dev = (bin_res_f - mean_residual) / mean_residual;
        score += dev * 12.0;
    }

    // New-bin candidate: empty bin should only win when nothing decent fits.
    // Penalize opening a new bin unless the item is large relative to capacity
    // and no tight fit is available.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 55.0 - large_item * 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
    }

    // Mild preference for bins with moderate residual left (avoid fragmenting large residuals)
    if bin_residual > 70 && post_residual > 30 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize post residual, with non-linear (quadratic/cubic) shaping
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth coupling: post residual valued differently depending on stream progress.
    // Early on, larger residuals are more reusable; late, prefer tight fits.
    score += pr * (1.0 - progress) * 0.5;
    score -= pr * progress * 0.3;

    // Non-linear interaction between post residual and mean residual:
    // if this bin's post residual is below mean, it's a tighter fit -> reward.
    let tightness = (mean_residual - pr) / cap;
    score -= tightness * tightness * 50.0;

    // Last-chance bonus: smooth function of fitting_bins_count
    let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
    score -= scarcity * scarcity * 8.0;

    // Lookahead coupling: if next item fits exactly in post residual, reward smoothly.
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        let fit_quality = 1.0 / (1.0 + diff * diff / (cap * cap));
        score -= fit_quality * 6.0 * (1.0 + progress);
    }

    // Mild penalty for many open bins (encourage consolidation), smooth in count
    score += (open_bins_count as f64).powi(2) * 0.01;

    // Slight preference for fuller fills as stream progresses
    score -= (item_size as f64 / cap) * (1.0 + 3.0 * progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by capacity fraction bands.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f;

    // Integer-division threshold classes on post_residual (harmonic residue classes mod 10).
    let post_class = post_residual % 10;
    score -= (post_class as f64) * 0.15; // mild reward for residues that leave "companion" gaps

    // Dead-space penalty: residuals too small for typical items (below min size 1..100, use ~15 as dead zone)
    if post_residual < 15 && post_residual > 0 {
        score += 30.0;
    }

    // Perfect fit reward via integer division classes
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Fractional capacity coupling: prefer filling bins to > 50% used
    if frac < 0.2 {
        score += 12.0; // creates large residual -> deprioritize unless it's the only option
    } else if frac < 0.5 {
        score += 4.0;
    } else {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 40.0;
        } else {
            score -= 10.0 - (slack as f64) * 0.05;
        }
    } else if next_item_size > post_residual && post_residual < next_item_size.min(15) {
        score += 8.0; // residual useless for the next item
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make opening a new bin costly unless current bin is very full
    if bin_residual == bin_capacity {
        // New bin baseline: slightly worse than a decent fit, better than a bad one
        score = cap_f * 0.5;
        // Late in stream, packing into existing bins is even more valuable
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
        // If many bins already open and mean residual is large, opening new bins is wasteful
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
    }

    // Mild pressure toward tighter bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Gap threshold: gaps below ~20 are hard to reuse for typical items.
    let dead_threshold = 18.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Non-linear penalty on post_residual: waste grows superlinearly
    // for large-but-awkward residuals (e.g. 25..45 hard to fill).
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / bin_capacity as f64;

    // Perfect fit bonus: residual near zero is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let prf = post_residual as f64;
        if next <= prf {
            // next item fits: reward tight coupling
            score -= 15.0 * (1.0 - (prf - next) / bin_capacity as f64);
            if (prf - next) <= 5.0 {
                score -= 20.0;
            }
        } else {
            // next item won't fit here: slight penalty if gap becomes dead
            if prf < dead_threshold {
                score += 10.0;
            }
        }
    }

    // Open-bin pressure: discourage opening new bins when many are open
    // with slack; encourage using existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_pressure = open_bins_count as f64 / (10.0 + 20.0 * progress);
    score += 6.0 * open_pressure;

    // Mean-residual coupling: if this bin's residual is far above mean,
    // it's a good candidate to consume (reduce fragmentation).
    let res_diff = bin_residual as f64 - mean_residual;
    score -= 0.4 * res_diff;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost that
    // grows with open_bins_count, so it's chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score += 25.0 + 4.0 * open_bins_count as f64;
        // But if current fit would leave large dead space, new bin is better
        if (post_residual as f64) < dead_threshold && bin_residual != bin_capacity {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: next item exactly fills the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Ideal: bin becomes exactly full after the next item.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits: mild reward scaled by how snugly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - slack.min(25.0); // snug fit rewarded, loose fit less so
        } else {
            // Next item cannot fit: post residual risks becoming dead space.
            // Penalize more when the leftover is small (unusable) relative to capacity.
            let dead = post_residual as f64;
            let dead_ratio = dead / bin_capacity as f64;
            score += dead * 0.5 + (1.0 - dead_ratio) * 15.0;
        }
    } else {
        // Last item: prefer minimal leftover.
        score += 0.0;
    }

    // Reward tight packing relative to mean residual of open bins.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.3;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it attractive only when the current item fits
    // poorly everywhere. An empty bin has high post_residual, so add a
    // fixed opening cost that the bonuses above must overcome.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if the next item is large and would pair well with a fresh bin,
        // soften the cost slightly.
        if next_item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Dead-space penalty for tiny unusable leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: reward if the next item fits exactly into the post residual (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            // mild reward proportional to how well the next item would fill leftover
            let chain_fill = next_item_size as f64 / post_residual as f64;
            score -= 8.0 * chain_fill;
        } else {
            // next item won't fit here: leftover likely becomes dead space
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate logic: penalize opening a new bin when good fits exist elsewhere.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If many open bins have large residuals, discourage adding another.
        score += 0.5 * open_bins_count as f64;
        // If mean residual across open bins is small, a new bin is more attractive.
        score -= mean_residual * 0.3;
    } else {
        // Prefer bins with residuals close to the item (waste-avoidance shaping).
        let tightness = 1.0 - (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score -= 6.0 * tightness;
        // Mild preference to balance load across bins: bins below mean residual are slightly favored.
        score += 0.2 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);
    }

    // Late-stream urgency: near the end, avoid opening bins and pack tightly.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if progress > 0.85 {
            score += 8.0 * (progress - 0.85) * 6.67 * (bin_residual == bin_capacity) as i32 as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream, prefer tight fits less aggressively (explore);
    // late in the stream, strongly penalize wasted residual.
    let progress_weight = progress * progress; // smooth ramp
    score += 30.0 * progress_weight * norm_pr * norm_pr; // quadratic dead-space penalty grows with progress
    score -= 12.0 * (1.0 - progress) * norm_pr * (1.0 - norm_pr); // reward mid-range residual early

    // Smooth cubic interaction: exact fits (norm_pr near 0) get a progress-coupled bonus.
    score -= 20.0 * progress_weight * (1.0 - norm_pr).powi(3);

    // Coupling with mean residual: avoid bins far from the fleet mean (fragmentation).
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: if next item exactly fits the post residual, big reward (smooth, not piecewise).
    let look_fit = (next_item_size as f64 - pr).abs() / cap;
    score -= 18.0 * (-look_fit * 8.0).exp() * (0.5 + progress);

    // Mild penalty for opening a new bin when many bins are open late in the stream.
    score += 3.0 * progress * (open_bins_count as f64).sqrt() * (bin_residual == bin_capacity) as i32 as f64;

    // Slight preference for fuller bins overall.
    score -= 0.1 * (item_size as f64 / cap) * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity divided into 5 classes.
    let class = (post_residual * 5) / bin_capacity; // 0..=4
    let class_bonus = match class {
        0 => -40.0,                       // near-perfect fill
        1 => -18.0,
        2 => 0.0,
        3 => 10.0,
        _ => 22.0,                        // large dead space
    };
    score += class_bonus;

    // Exact fill reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic class of next item: does post_residual land in a residue
    // class compatible with the lookahead item?
    if next_item_size > 0 {
        let next_class = (next_item_size * 5) / bin_capacity;
        if post_residual >= next_item_size {
            // Reward leaving room for the next item, scaled by its class
            score -= 12.0 + (next_class as f64) * 4.0;
            // Extra reward if next item exactly consumes post_residual
            if post_residual == next_item_size {
                score -= 35.0;
            }
        } else {
            // Post residual unusable by lookahead -> penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New empty bin candidate: penalize moderately so it's chosen only
    // when open bins have bad fits.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Early in the stream, opening bins is cheap; late, prefer filling
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
    }

    // Prefer bins tighter than the mean residual (good fits)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Modulo harmonic: residues divisible by 10 are "clean" dead space
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Integer-division threshold: post_residual in [1,9] is worst dead space
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(10) {
        score += 60.0; // dead space that likely can never be used
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit, zero waste
    } else if post_residual <= 20 {
        score += 15.0; // risky small gap
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: discourage proliferation of bins when alternatives exist.
    if bin_residual != bin_capacity {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    } else {
        // New-bin candidate: only attractive when nothing fits well.
        let poor_fit_everywhere = fitting_bins_count == 0
            || (mean_residual < item_size as f64 * 0.6);
        if poor_fit_everywhere {
            score -= 55.0;
        } else {
            score += 45.0; // prefer existing bins over opening new ones
        }
    }

    // Lookahead: if next item could use the post residual, reward leaving it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0; // exact match for lookahead
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            score += 8.0; // next item won't fit in leftover
        }
    }

    // Late in the stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - fill_ratio);

    // Mild alignment with mean residual: prefer bins close to the average state.
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post-residual, reward strongly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // next item fits: mild reward proportional to tightness
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here: penalize leftover dead space
            score += 0.5 * post_residual as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin leaves large waste
    if bin_residual == bin_capacity {
        score += 60.0;
        // allow new bin when item is large and no bin fits well
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 30.0;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items as f64;
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post-residual).
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += tight * 30.0;

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 50.0;
    } else if post_residual <= 20 {
        score -= 15.0;
    }

    // Penalize dead space that no future item (min size 1) could waste badly:
    // penalize very small unusable leftovers less, penalize mid-range gaps more.
    if post_residual >= 1 && post_residual < 10 {
        score += 5.0; // near-dead space
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 40.0;
            // Bonus for chaining: next item leaves small gap too.
            let next_gap = post_residual - next_item_size;
            if next_gap < 10 {
                score -= 20.0;
            }
        } else {
            // Next item won't fit here after placement; mildly penalize
            // wasting a large bin on a small item.
            score += 10.0;
            if post_residual < next_item_size && post_residual < 10 {
                score -= 5.0; // but killing the bin entirely is fine
            }
        }
    }

    // Prefer filling fuller bins first (best-fit flavor) relative to mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    // Time horizon: early in stream, be more open to opening new bins (explore);
    // later, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bias = 1.0 - progress;
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: penalize it, more so late in the stream,
        // less so early (exploration).
        score += 60.0 + 120.0 * progress;
        // If many open bins already, discourage new bins.
        score += open_bins_count as f64 * 3.0 * (1.0 - new_bin_bias);
        // But if current bin fit is terrible and lookahead is big, allow new bin.
        if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
            score -= 30.0;
        }
    }

    // Many open bins with slack: encourage consolidation.
    if open_bins_count > 4 {
        score -= (open_bins_count as f64 - 4.0) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: penalize leftover space, with non-linear (quadratic/cubic) shaping
    let mut score = post * (1.0 + norm_post * norm_post);

    // Smooth coupling with stream progress: waste matters more later in the stream
    score *= 1.0 + 0.5 * progress * (1.0 - norm_post);

    // Tight fits are strongly favored: smooth reward near zero residual
    let tightness = 1.0 - norm_post;
    score -= 6.0 * tightness * tightness * tightness;

    // Penalize bins far below mean residual (fragmented bins) via smooth coupling
    let mean_gap = (mean_residual - post) / cap;
    score += 1.5 * mean_gap * mean_gap;

    // Last-chance bin bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Lookahead: reward if next item fits into post_residual (smooth falloff)
    if next_item_size > 0 {
        let fits_next = (post_residual as f64 - next_item_size as f64) / cap;
        if fits_next >= 0.0 {
            score -= 3.0 * (1.0 - fits_next);
        } else {
            score += 2.0 * (-fits_next);
        }
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * norm_post;

    // New-bin candidate: smooth default score, only chosen if nothing fits well
    if bin_residual == bin_capacity {
        score = 55.0 + 10.0 * progress - 0.02 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 classes capture "nice" residuals
    // that pair well with common item sizes.
    let pr = post_residual;
    let class_bonus: f64 = match pr {
        0 => -40.0,
        1..=9 => 8.0,
        10..=19 => -12.0,
        20..=29 => -6.0,
        30..=39 => 0.0,
        40..=49 => 2.0,
        50..=59 => -2.0,
        60..=69 => 4.0,
        70..=79 => 6.0,
        _ => 10.0,
    };
    score += class_bonus;

    // Integer-division thresholds: residual exactly divisible by 10 is a good slot.
    if pr % 10 == 0 {
        score -= 6.0;
    }
    if pr % 20 == 0 {
        score -= 4.0;
    }

    // Capacity fraction coupling: prefer filling bins past half capacity.
    let fill_frac = (bin_residual as f64) / cap;
    if fill_frac > 0.5 {
        score -= 10.0 * (fill_frac - 0.5);
    }

    // Lookahead: if next item fits the post residual exactly, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            score -= 5.0 * (pr as f64 - next_item_size as f64) / cap;
        } else {
            // next item cannot use this residual: dead-space penalty scales with residual
            score += 0.05 * pr as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless current
    // open bins are nearly full / crowded.
    if bin_residual == bin_capacity {
        score += 30.0;
        if open_bins_count == 0 {
            score -= 60.0; // must open a bin
        } else if mean_residual < 15.0 {
            score -= 20.0; // existing bins are nearly full, opening is fine
        }
    }

    // Late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (1.0 - (pr as f64) / cap);

    // Mild penalty proportional to residual to break ties toward tighter bins.
    score += 0.02 * pr as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps (<10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps too small for the smallest plausible next item are moderate dead space.
    if post_residual > 0 && post_residual < 25 {
        score += 12.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (the empty-bin candidate has bin_residual == bin_capacity, so this
    // penalty applies mainly to it via residual coupling below).
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 4.0;
    if bin_residual == bin_capacity {
        score += open_pressure + 8.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            score -= 6.0;
        } else {
            score += 8.0;
        }
    }

    // Prefer bins whose residual is already below average (tighter bins close faster).
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.3;
    }

    // Mild stream-progression pressure to consolidate early.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward an exact match between
    // post_residual and the next item's size (perfect packing in two steps).
    let pr = post_residual as f64;
    let ni = next_item_size as f64;

    if next_item_size > 0 {
        let diff = (pr - ni).abs();
        // Exact match: huge reward.
        if diff < 0.5 {
            score -= 40.0;
        } else if ni <= pr {
            // Next item fits in the residual: reward proportional to tightness.
            let fill = ni / pr.max(1.0);
            score -= 25.0 * fill;
            // Penalize leftover dead space after the hypothetical next placement.
            let leftover = pr - ni;
            if leftover > 0.0 {
                score += 0.15 * leftover;
            }
        } else {
            // Next item does NOT fit here: penalize, scaled by how badly it misses.
            score += 0.35 * diff;
        }
    } else {
        // Last item in stream: just prefer minimal post residual.
        score += 0.0;
    }

    // Relative-to-mean-residual term: prefer bins whose post residual sits
    // below the mean (concentrating waste into few bins).
    score += 0.25 * (pr - mean_residual);

    // Last-chance bonus: if this is the only bin that fits the item, strongly
    // favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make an empty bin attractive only when
    // open bins are badly fragmented (high mean residual) or item is large.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let openness = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        // Base penalty so new bins are not opened frivolously.
        score += 18.0;
        // But relax the penalty when existing bins are fragmented or stream is early.
        score -= 20.0 * fragmentation * openness;
        // Large items benefit from a fresh bin more.
        score -= 0.1 * item_size as f64;
        // Late in the stream, prefer closing out open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Slight preference for tighter current fit (smaller residual before placement).
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalize post_residual by capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Penalize leaving dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // small dead space is fine, near-perfect fit
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 * (next_item_size as f64 / 100.0);
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 3.0; // next item won't chain here
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize opening a new bin when many open bins could fit the item.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus scaling with stream progression.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 25.0 + 15.0 * progress;
        if post_residual as f64 > mean_residual {
            score += 5.0;
        }
    } else {
        // Prefer filling bins with above-average residual (reduce fragmentation).
        if (bin_residual as f64) > mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    // Mild penalty for very large residual consumption waste on big items.
    if item_size > bin_capacity / 2 && post_residual < 20 {
        score -= 6.0;
    }

    // Encourage consolidation early, spread late.
    let open_penalty = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * open_penalty * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear penalty on waste
    let mut score = pr as f64;
    score += 12.0 * norm_pr * norm_pr * cap;

    // Polynomial coupling of post_residual with stream progress:
    // early on, waste is cheaper; late, tight packing matters more
    let progress_coupling = (1.0 + 2.5 * progress) * norm_pr * norm_pr * 20.0;
    score += progress_coupling;

    // Smooth interaction: large post_residual is worse when mean residual is small
    let mean_gap = (mean_residual - pr).abs() / cap;
    score += 8.0 * mean_gap * mean_gap * cap;

    // Lookahead: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_quality = 1.0 - (pr - nx) / cap;
            score -= 15.0 * fit_quality * fit_quality;
        } else {
            // next item won't fit here; penalize leaving large residual
            score += 5.0 * norm_pr;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when it's genuinely better.
    // Penalize opening a new bin, more so later in the stream and when many bins are open.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 18.0 + 6.0 * open_pressure + 10.0 * progress;
        // But if item is large relative to capacity and residuals are small, new bin is fine
        let size_ratio = item_size as f64 / cap;
        if size_ratio > 0.6 && mean_residual < size_ratio * cap * 0.5 {
            score -= 22.0;
        }
    }

    // Mild penalty for opening many bins relative to items seen
    score += 0.5 * (open_bins_count as f64) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) heavily rewarded,
    // small dead space (<10) heavily penalized, mid-range dead space mild penalty.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual < 10 {
        score += 300.0; // unusable sliver
    } else {
        // modulo classes: residuals that are multiples of common small item sizes
        // (10, 20, 25) are reusable; odd residuals less so.
        let pr = post_residual;
        if pr % 10 == 0 {
            score -= 40.0;
        } else if pr % 5 == 0 {
            score -= 15.0;
        } else {
            score += 10.0;
        }
        // integer-division threshold: post_residual in [10,25) is a "half-slot"
        if pr / 10 == 1 {
            score += 20.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves its own residual; scale by its class
            let nr = post_residual - next_item_size;
            score -= 50.0 - (nr as f64).min(50.0);
        } else {
            // next item won't fit here: penalize more if this bin becomes a dead-end sliver
            if post_residual < next_item_size && post_residual < 10 {
                score += 100.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is crowded.
    if bin_residual == bin_capacity {
        score += 150.0;
        // early in stream, new bins are cheaper; late in stream, pack tightly
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * (1.0 - progress);
        // if mean residual across open bins is large, opening new bin is wasteful
        score += mean_residual * 2.0;
    }

    // Tightness reward: prefer bins whose residual is closest to item size.
    score -= (bin_residual - item_size) as f64 * 0.5;

    // Slight preference for more-filled bins among many open bins.
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are small but nonzero are
    // the worst outcome (unusable gap). Zero residual is perfect.
    if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    } else if post_residual < 10 {
        score += 25.0; // tiny unusable dead space
    } else if post_residual < 20 {
        score += 10.0; // marginal gap, only fits smallest items
    }

    // Reward bins whose residual tightly matches the item (waste-aware fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 15.0 * (1.0 - tightness).max(0.0);

    // Lookahead: if the next item fits the post-residual, this placement is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize if next item would be stranded by this placement's gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Open-bin pressure: discourage proliferation of many open bins.
    score += 0.6 * open_bins_count as f64;

    // Mild alignment with mean residual: prefer bins near the mean (balanced packing).
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate: penalize slightly so it only wins when open bins are bad.
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Penalize dead space that cannot host the next item.
        let waste = post_residual as f64 - (next_item_size as f64 - post_residual as f64).abs();
        score += 10.0 + (next_item_size - post_residual) as f64 * 0.4;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize opening a new bin when open bins could fit reasonably well.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if the item leaves a residual matching the next item, allow it.
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 35.0;
        }
    }

    // Late-stream consolidation: tighten packing as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if next_item_size > post_residual && next_item_size <= bin_capacity {
            // Next item won't fit here anyway; mild penalty if we leave awkward gap.
            let gap_waste = post_residual as f64;
            score += 0.3 * gap_waste;
        }
    }

    // Prefer bins whose residual is already below average (consolidate waste).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base penalty so open bins are normally preferred.
        score += 25.0;
        // Late in the stream or many open bins: opening fresh bins is more acceptable.
        score -= 10.0 * progress;
        if open_bins_count > 3 {
            score -= 2.0 * (open_bins_count as f64).ln();
        }
        // If no open bin fits tightly, new bin becomes competitive.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size >= 70 {
            score -= 8.0; // big item coming: keep space clean
        }
    }

    // Time-horizon modulation: early on, be pickier about waste (long future).
    let horizon = if total_items > 0 {
        1.0 - step_index as f64 / total_items as f64
    } else {
        0.0
    };
    score += horizon * 0.15 * post_residual as f64;

    // Mild preference to fill more-open bins when many are open (reduce bin count).
    if bin_residual < bin_capacity && open_bins_count > 1 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_r = r / cap;

    // Base: prefer tight fits (low post residual)
    let mut score = r;

    // Smooth non-linear coupling of residual with stream progress:
    // early on, waste tolerance is higher; late, dead space is heavily penalized.
    let tightness = 1.0 + 2.0 * progress * progress;
    score += tightness * norm_r * norm_r * cap * 0.5;

    // Reward near-perfect fits more strongly as stream progresses (smooth cubic term)
    let perfect = 1.0 - (norm_r * std::f64::consts::PI).tanh().abs();
    score -= perfect * cap * (0.2 + 0.6 * progress);

    // Last-chance bin: strong reward, decaying smoothly with progress
    if fitting_bins_count == 1 {
        score -= cap * (1.2 - 0.5 * progress);
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (r - nxt).max(0.0);
        let fit_quality = 1.0 - (fits_next / cap);
        score -= fit_quality * nxt * (0.3 + 0.4 * progress);
        // Penalize if post-residual is just barely too small for next item (dead space)
        if nxt > r && nxt <= r + cap * 0.15 {
            score += nxt * 0.4 * (1.0 + progress);
        }
    }

    // Mild penalty for spreading across many open bins when mean residual is high
    let open_f = open_bins_count as f64;
    score += (open_f / (open_f + 5.0)) * mean_residual * 0.05 * (1.0 - progress);

    // New-bin candidate shaping: empty bin gets moderate score so it wins only
    // when open bins would leave large residuals
    if bin_residual == bin_capacity {
        score = cap * (0.9 - 0.3 * progress) + mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "useful slots"
    // Class A: residual in 0..=10  -> perfect fill, heavily reward
    // Class B: residual in 11..=30 -> usable for small future items
    // Class C: residual in 31..=60 -> moderately usable
    // Class D: residual > 60       -> wasteful (nearly empty bin used poorly)
    let post = post_residual;
    if post == 0 {
        score -= 50.0; // perfect fill
    } else if post <= 10 {
        score -= 25.0;
    } else if post <= 30 {
        score -= 8.0 + (30 - post) as f64 * 0.3;
    } else if post <= 60 {
        score += 2.0;
    } else {
        score += 10.0; // large dead space penalty
    }

    // Harmonic coupling: does post_residual pair well with the lookahead item?
    if next_item_size > 0 {
        if post >= next_item_size && post - next_item_size <= 10 {
            // next item would nearly fill this bin's leftover: strong reward
            score -= 20.0;
        } else if post >= next_item_size {
            // next item fits but leaves arbitrary gap
            score -= 3.0;
        } else {
            // next item cannot use the leftover
            score += (next_item_size - post).min(40) as f64 * 0.15;
        }
        // modulo harmony: leftover divisible into chunks matching next item size
        if next_item_size > 0 && post % next_item_size == 0 && post > 0 {
            score -= 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 30.0;
        // open fewer bins when few exist relative to progress
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
        // but if the item is huge relative to mean residual, a fresh bin is fine
        if item_size as f64 > mean_residual + 20.0 {
            score -= 25.0;
        }
        // avoid opening a new bin when an existing bin would end with tiny residual
        if post > 60 {
            score += 5.0;
        }
    }

    // Mild preference to fill bins with lower residual first (best-fit core)
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Integer-division threshold on post_residual: bins whose leftover is in
    // [1..=capacity/10] are near-perfect; give extra harmonic reward
    let tenth = bin_capacity / 10;
    if post >= 1 && post <= tenth {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A gap below the minimum item size (1..100 unknown, assume small floor 10)
    // is wasted space; the smaller the gap, the worse.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // tiny dead space, almost unusable
        } else if post_residual < 20 {
            score += 15.0; // likely unusable gap
        } else if post_residual < 30 {
            score += 5.0;
        }
    } else {
        // Perfect fit: strong reward
        score -= 30.0;
    }

    // Reward tight fits generally (post_residual already low is good)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness;

    // Open bins pressure: when many bins are open, prefer filling existing ones
    // rather than opening new bins.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins already open,
        // and when this bin would leave large residual anyway.
        score += 20.0 + 5.0 * open_pressure;
        // Slight bonus if opening a new bin gives a better long-term fit
        if post_residual as f64 > mean_residual {
            score += 10.0;
        }
    } else {
        // Reward using existing bins, more so when many are open
        score -= 2.0 * open_pressure;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) == 0 {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // post_residual can't host next item: penalize proportionally
        score += (post_residual as f64 / bin_capacity as f64) * 8.0;
    }

    // Stream progression: early in the stream, be more willing to open new bins
    // (long horizon amortizes); late in the stream, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item fits exactly-ish: strong reward
            score -= (20.0 - gap.min(20.0)) * 8.0;
        } else {
            // next item would not fit here; penalize proportionally to wasted potential
            score += gap * 0.5;
        }
    }

    // Tightness reward: small post_residual is good, but avoid tiny dead space (<10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead-space penalty
    }

    // Prefer bins with larger residual relative to mean (keep tight bins for tight fits)
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are very full
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        if avg_fill > 0.7 {
            score -= 30.0; // existing bins nearly full, opening is fine
        } else {
            score += 40.0; // discourage premature new bin
        }
    }

    // Early in stream: be pickier about residual quality
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (waste minimization).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 80.0;
    }

    // Penalize dead space relative to smallest plausible future item.
    let dead = post_residual as f64;
    score += 0.8 * dead * dead / bin_capacity as f64;

    // Lookahead: bonus if the next item fits into the post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0 + 0.5 * next_item_size as f64;
        }
        // Penalize if post-residual is just below next item (teasing gap).
        else if post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual <= 10 {
            score += 15.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: open a fresh bin when existing residuals are poor.
    if bin_residual == bin_capacity {
        // Base neutral cost of opening a bin.
        score += 40.0;
        // If this bin is the only fitting option, opening is cheap.
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
        // If current bin would leave big waste anyway, opening is attractive.
        if post_residual as f64 > mean_residual * 0.9 {
            score -= 25.0;
        }
        // Late in stream, prefer reusing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * progress;
        // Many open bins: discourage adding more.
        score += 2.0 * open_bins_count as f64;
    } else {
        // Reusing bins: slight bonus scaled by fullness of the bin.
        let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 10.0 * fullness;
    }

    // Prefer bins whose residual is below mean (tighter bins first).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = post / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = post * (1.0 + 0.35 * fit_ratio * fit_ratio) * (1.0 + 0.25 * progress);

    // Smooth coupling: tight fits rewarded more as stream progresses
    let tightness = 1.0 - fit_ratio;
    score -= 12.0 * tightness * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual (smooth quadratic gap)
    let gap = post - mean_residual;
    score += 0.08 * gap * gap / cap;

    // Last-chance bonus (smooth sigmoid-like on fitting_bins_count)
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward leaving room for next item (smooth kernel)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let d = (post - ns) / cap;
        let kernel = (-8.0 * d * d).exp();
        score -= 8.0 * kernel;
        // penalize if next item cannot fit here
        if post < ns {
            score += 5.0 * (1.0 - post / ns.max(1.0));
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space (modulo-10 residue classes).
    let post_class = post_residual % 10;
    // Leftovers in "useless" classes (small nonzero crumbs) are penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    if post_class == 0 {
        // Perfect decade alignment is highly desirable.
        score -= 10.0;
    } else if post_class <= 3 {
        score += 4.0;
    }

    // Integer-division thresholds: how many small items (size 10) still fit.
    let decade_slots = post_residual / 10;
    score -= decade_slots as f64 * 2.0;

    // Lookahead coupling: reward if next item exactly fits the post residual,
    // penalize if next item cannot use the leftover.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
            // Harmonic pairing: leftover class matches next item's class.
            if post_residual % next_item_size == 0 {
                score -= 6.0;
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 30.0; // must open a new bin
        } else if item_size <= 30 {
            // Small items should almost always go into existing bins.
            score += 15.0;
        } else {
            // Big items: opening a fresh bin is reasonable if the best
            // existing fit would leave a bad crumb.
            score += 5.0;
        }
        // As the stream progresses, discourage proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 6.0;
        // Many open bins with slack: prefer filling them.
        score += (open_bins_count as f64) * 0.4;
    }

    // Prefer bins whose residual is below the mean (consolidating fullness).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    // Exact fit is ideal regardless of anything else.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized,
    // mid gaps mildly penalized; perfect fit (0) is maximally rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 10 {
        score += 45.0; // tiny dead space, nearly unusable
    } else if pr <= 20 {
        score += 12.0;
    } else if pr >= 80 {
        score -= 8.0; // large residual stays flexible
    }

    // Reward using bins whose residual tightly matches the item (good fill ratio).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_ratio;

    // Pressure from number of open bins: discourage opening/keeping too many bins,
    // but allow new bin when all open bins would create tiny dead space.
    let pressure = open_bins_count as f64;
    score += 0.35 * pressure;

    // Last-chance bonus: if this is the only fitting bin, prefer it over a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when it avoids dead space later.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fit win by default.
        score += 18.0;
        // If the next item could use a fresh large residual, soften the penalty.
        if next_item_size > 0 && (next_item_size as f64) >= mean_residual * 0.9 {
            score -= 30.0;
        }
        // Early in stream, a fresh bin is cheaper (fewer bins committed).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 && next_item_size == pr {
        score -= 35.0;
    } else if next_item_size > 0 && (next_item_size as u32) > pr {
        // next item cannot use this residual anyway; dead space is locked in
        if pr > 0 && pr < 10 {
            score += 10.0;
        }
    }

    // Mild alignment with mean residual: prefer bins near the average to keep balance.
    score -= 0.1 * (bin_residual as f64 - mean_residual).abs().min(30.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits: small post_residual is desirable dead space.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 45.0; // perfect two-item packing
        } else if diff <= 5 {
            score -= 20.0 + (5 - diff) as f64 * 2.0;
        } else if diff <= 15 {
            score -= (15 - diff) as f64;
        } else {
            // post_residual too large/small vs next item: penalize awkward leftovers
            if (post_residual as i64) < (next_item_size as i64) {
                score += 5.0;
            }
        }
        // If next item can't fit anywhere else, keep this bin viable
        if next_item_size > post_residual && post_residual < 10 {
            score += 8.0;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 30.0;
        if post_residual <= 10 {
            score -= 20.0;
        }
    }

    // New-bin candidate handling: penalize opening a new bin, more so early in the stream
    // and when many bins are already open (amortization).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 + 30.0 * (1.0 - progress) + open_bins_count as f64 * 2.0;
        // But if the item is huge and lookahead suggests a big companion, a fresh bin
        // can be attractive: relax the penalty.
        if item_size >= 60 && next_item_size >= 30 {
            score -= 55.0;
        }
    }

    // Mild penalty for leaving residuals that nothing in a typical range can use.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
