        score -= 80.0;
    } else if post_residual <= 12 {
        score -= 25.0;
    }

    // Penalize dead space relative to capacity.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * frac * 60.0;

    // Last-chance bonus: if this is the only bin that fits, prefer it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0 + 0.5 * next_item_size as f64;
    }
    // If next item is large and would need a nearly empty bin, discourage wasting residual.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 0.15 * (next_item_size - post_residual) as f64;
    }

    // Time horizon: early in stream, more willing to open new bins / spread load.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized late.
        score += 20.0 * progress - 10.0 * (1.0 - progress);
        if post_residual == bin_capacity {
            score += 5.0;
        }
    }

    // Global state: many open bins with large mean residual -> discourage new bins,
    // encourage filling existing ones.
    if open_bins_count > 2 && mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= 0.1 * mean_residual;
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Prefer bins with smaller residual overall (tighter packing).
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr as f64;

    // Smooth non-linear coupling: quadratic dead-space penalty that grows with stream progress
    score += 40.0 * norm_post * norm_post * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= 25.0 * (1.0 - norm_post) * (1.0 - norm_post) * (0.3 + progress);

    // Penalize leaving residuals that no typical item can use (dead space coupling)
    score += 15.0 * norm_post * norm_post * norm_post * (1.0 + 2.0 * progress);

    // Interaction with mean residual: prefer bins close to mean residual to keep balance
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 + progress);
    }

    // Lookahead: penalize if post_residual can't fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            // reward leaving room for the next item, smoothly scaled by fit quality
            let fit_quality = 1.0 - ((pr - nx) / cap);
            score -= 20.0 * fit_quality * (0.5 + progress);
        } else {
            score += 12.0 * (1.0 - pr / nx) * (0.5 + progress);
        }
    }

    // Mild pressure against opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (open_bins_count as f64).sqrt() * (1.0 - progress);
        // but allow new bin if existing residuals are all poor fits
        score -= 15.0 * mean_residual / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well it decomposes into common small sizes
    let pr = post_residual;
    // Reward post-residuals that sit on "harmonic" divisors of capacity (50, 34, 25, 20, 10...)
    let harmonic: [(u32, f64); 7] = [(0, 60.0), (10, 40.0), (20, 30.0), (25, 25.0), (33, 12.0), (50, 20.0), (34, 12.0)];
    for &(h, r) in harmonic.iter() {
        if pr == h { score -= r; }
    }
    // Penalize awkward dead zones: small but unusable remainders
    if pr > 0 && pr < 10 {
        score += 25.0;
    }
    // Modulo-10 banding: multiples of 10 are "harmonic" given size granularity
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 && next_item_size <= pr {
        if pr == next_item_size {
            score -= 45.0;
        } else {
            let slack = (pr - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / cap);
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // next item can't follow here: penalize proportionally
        score += 10.0 * (next_item_size as f64 - pr as f64) / cap;
    }

    // Last-chance bin: strongly prefer filling the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Prefer bins tighter than the mean residual (good fit direction)
    let resid_frac = bin_residual as f64 / cap;
    let mean_frac = mean_residual / cap;
    score += 15.0 * (resid_frac - mean_frac);

    // Fractional tightness: reward small post_residual fraction
    score += 20.0 * (post_residual as f64 / cap);

    // Late in stream: consolidate, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, cheaper early, expensive late
        score = 55.0 + 45.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    } else {
        score -= 10.0 * progress;
    }

    // Integer-division threshold: post_residual in [10,20) is a "half-slot" sweet spot
    if pr >= 10 && pr < 20 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical future items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10 - post_residual) as f64;
    }

    // Reward near-perfect packing.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward: item occupies most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if fill_ratio > 0.8 {
        score -= 15.0 * fill_ratio;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current open bins fit poorly
    // (large dead space would be created) or many bins already open.
    if bin_residual == bin_capacity {
        let dead = (bin_capacity - item_size) as f64;
        if dead > 0.0 && dead < 10.0 {
            score += 100.0; // opening a bin that immediately dead-ends is bad
        }
        if item_size as f64 / bin_capacity as f64 >= 0.9 {
            score -= 50.0; // big item into fresh bin is fine
        }
        score += open_bins_count as f64 * 0.5;
        score -= mean_residual * 0.3; // if open bins have lots of room, avoid new bin
    }

    // Open-bin pressure: mildly discourage scattering across many bins.
    score += open_bins_count as f64 * 0.2;

    // Lookahead: if next item could use the post_residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // residual too small for the known next item
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is highly desirable.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0 + (next_item_size as f64) * 0.5;
        }
        // Penalize dead space the next item cannot use.
        if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size as f64) - (post_residual as f64);
        }
    }

    // Prefer bins with residual below mean (tighter bins) when they fit well.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 40.0;
        // If the next item is large, a fresh bin is more attractive.
        score -= (next_item_size as f64) * 0.1;
    }

    // Late in the stream, be more conservative about dead space.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small to hold typical future items.
    if post_residual < 10 {
        score += 6.0;
    } else if post_residual <= 20 {
        score -= 3.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it hard.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        } else if post_residual > 0 && post_residual < next_item_size {
            // Leaving a gap the next item cannot use: penalize proportionally.
            score += 4.0 * (post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Global pressure: many open bins with high mean residual -> prefer filling existing bins.
    let pressure = mean_residual / bin_capacity as f64;
    if bin_residual < bin_capacity {
        score -= 5.0 * pressure;
    } else {
        // New-bin candidate: penalize opening a bin unless residuals are fragmented.
        score += 14.0 - 10.0 * pressure;
        // Opening a new bin is more attractive early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 6.0 * progress;
    }

    // Mild preference for bins already below mean residual (balance consolidation).
    if (bin_residual as f64) < mean_residual && bin_residual < bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear polynomial shaping.
    let mut score = pr
        + 40.0 * norm_pr * norm_pr
        - 60.0 * norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - progress);

    // Reward near-exact fills more strongly as the stream progresses.
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual of open bins (smooth coupling).
    score += 0.15 * (pr as f64 - mean_residual).abs() * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: reward leaving room for the next item if it fits well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 15.0 * (1.0 - slack * slack);
        } else {
            score += 10.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for spreading across many open bins late in the stream.
    score += 0.02 * open_bins_count as f64 * progress;

    // New-bin candidate: make it moderately attractive only for large items / late stream.
    if bin_residual == bin_capacity {
        score = cap - 0.5 * item_size as f64 + 20.0 * (1.0 - progress) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Modulo classes on post_residual (harmonic buckets of 10 units).
    let post_class = (post_residual % 10) as f64;
    score += post_class * 0.35;

    // Reward near-perfect fits: post_residual in tiny class gets strong subtraction.
    if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 15 {
        score -= 12.0;
    }

    // Penalize large unusable dead space (nothing else of typical size fits).
    if post_residual > 0 && post_residual < 10 {
        score -= 20.0; // perfectly sealed small gap is great
    }
    if post_residual >= 40 {
        score += 8.0 * frac; // wasteful large leftover
    }

    // Integer-division thresholds: how many "standard items" (size 10) could still fit.
    let slots = post_residual / 10;
    score -= slots as f64 * 3.0;

    // Lookahead coupling: if next item fits the post-residual exactly, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 + (post_residual - next_item_size) as f64 * 0.2;
        } else {
            score += 6.0; // next item cannot use this bin's remainder
        }
        // Harmonic match: next item shares modulo class with post residual
        if next_item_size % 10 == post_residual % 10 && next_item_size <= post_residual {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Open a new bin when open bins are fragmented (low mean residual) or late in stream.
        score = 55.0 - 25.0 * (1.0 - pressure) - 15.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 12.0; // big next item: fresh bin is valuable
        }
    }

    // Slight preference for tighter bins overall (lower residual -> lower score already).
    // Progress-based mild consolidation pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - bin_residual) as f64 * 0.05 * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // Dead space = residual too small to be useful for typical items.
        let dead_threshold = 12.0; // below smallest practical item
        if (post_residual as f64) < dead_threshold {
            score += 40.0 + (dead_threshold - post_residual as f64) * 6.0;
        } else {
            // Larger gaps are mildly penalized to prefer tight fits.
            score += (post_residual as f64) * 0.15;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits relative to residual (waste ratio).
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 25.0;
    }

    // Open-bin pressure: discourage scattering across many open bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin (penalize heavily if rejected).
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win
    // when existing bins would leave bad dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // But if the current item nearly fills a fresh bin, it's a good start.
        if item_size >= bin_capacity / 2 {
            score -= 35.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
    }

    // Lookahead coupling: if the next item fits well in the post-residual,
    // reward leaving exactly that much space.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 15.0 - gap.min(15.0);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Residual too small for the next item: mild penalty.
        score += 8.0;
    }

    // Mean-residual context: placing into a bin with residual far below
    // the mean wastes the mean's potential; favor bins near mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward bins whose post-residual can host the next item (2-step lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 40.0 + 0.25 * (post_residual - next_item_size) as f64;
        } else {
            // Penalize dead space that cannot fit the next item, worse when residual is tiny.
            let waste = post_residual as f64;
            score += 0.6 * waste;
            if waste < 10.0 {
                score += 15.0; // unusable sliver
            }
        }
        // If next item fits exactly, big bonus.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    } else {
        // Last item: pure best-fit on residual.
        score -= 10.0;
    }

    // Favor bins tighter than the mean residual (best-fit style).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Discard near-empty usage of an open bin when many bins are open? Prefer filling existing bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize moderately so it's chosen only when open bins fit poorly.
        score += 20.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && item_size == next_item_size {
            score -= 10.0; // pairing identical items in a fresh bin is fine
        }
    }

    // Slight preference to close out bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 14.0 * tightness;

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 22.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward heavily
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // next item won't fit here; slight penalty for wasting space
            score += (post_residual as f64) * 0.15;
        }
    }

    // Prefer filling bins when many bins are open (consolidation pressure)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.6 * (0.5 + progress);

    // Prefer bins with residual below mean residual (fill the emptier-feeling bins)
    let dev = mean_residual - bin_residual as f64;
    score += 0.25 * dev;

    // Discourage opening new bins unless current bin is a poor fit
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline plus penalty scaled by how well open bins could do
        score += 12.0 + (mean_residual * 0.1);
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual

    // Non-linear polynomial coupling: dead-space penalty grows super-linearly,
    // and its strength increases with stream progress (waste matters more later).
    let dead = x * x * (1.0 - x * 0.5);
    score += dead * cap * (0.5 + progress);

    // Reward tight fits with a smooth quadratic bonus
    let tight = (1.0 - x).powi(2);
    score -= tight * cap * (0.4 + 0.3 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: penalize leaving a residual that barely fails next item,
    // reward residuals that can host the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post < n && post > 0.0 {
            score += 6.0 * (1.0 - post / n) * (0.5 + progress);
        } else if post >= n {
            score -= 4.0 * (n / cap) * (1.0 - x);
        }
    }

    // Mild penalty when many bins are open relative to items seen (fragmentation)
    let frag = (open_bins_count as f64 / (step_index.max(1) as f64 + 1.0)).min(1.0);
    score += frag * 3.0 * x;

    // Slight preference for bins below mean residual (consolidate emptier bins)
    score += 0.05 * (mean_residual - post).max(-50.0).min(50.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: dead space that is a small
    // integer fraction of capacity is far more reusable than awkward gaps.
    // Treat capacity as 100; classify post_residual into harmonic bands.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap;

    // Harmonic band rewards: post residual near 0, 1/4, 1/3, 1/2 of capacity
    // leaves room for common item sizes; mid-band gaps (e.g. 30-45) are worst.
    let quarter = (post - 25.0).abs();
    let third = (post - 33.0).abs();
    let half = (post - 50.0).abs();
    let zero = post;

    let best_harmonic = zero.min(quarter).min(third).min(half);
    score += 0.35 * best_harmonic;

    // Penalize the awkward mid-band (post residual 20..45 not near a harmonic).
    if post > 15.0 && post < 48.0 && best_harmonic > 6.0 {
        score += 0.6 * (48.0 - post);
    }

    // --- Integer-division thresholds on next_item_size vs post_residual:
    // does the lookahead item fit exactly / fit at all?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            // Reward exact fits (post_residual % next_item_size == 0)
            let rem = post_residual % next_item_size.max(1);
            if rem == 0 {
                score -= 12.0;
            } else {
                score -= 5.0;
            }
            // Extra reward if the NEXT-NEXT slot (post - nxt) lands on a harmonic
            let after = post - nxt;
            if after >= 0.0 {
                let aq = (after - 25.0).abs().min((after - 50.0).abs()).min(after);
                score += 0.25 * aq;
            }
        } else {
            // Lookahead won't fit here: penalize more when this bin was the
            // only fitting bin (last-chance bin gets sacrificed badly).
            score += 8.0;
            if fitting_bins_count == 1 {
                score -= 20.0; // but strongly prefer using the last-chance bin anyway
            }
        }
    }

    // --- Last-chance logic: strongly prefer the sole fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling: an empty bin has large post_residual;
    // make it attractive only when the item is big or no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 / cap;
        // Opening a new bin is good for large items or late in the stream
        // with many open bins (avoid fragmentation).
        let openness = (open_bins_count as f64 / 10.0).min(3.0);
        score -= 30.0 * big_item + 4.0 * progress + openness;
        // But discourage hoarding new bins when small items could fill gaps.
        if item_size < 30 && mean_residual > 40.0 {
            score += 25.0;
        }
    }

    // --- Modulo arithmetic on post_residual: gaps congruent to 0 mod 10
    // align with typical item granularity; odd/prime-ish gaps are dead.
    let m = post_residual % 10;
    score += match m {
        0 => -4.0,
        5 => -1.5,
        1 | 9 => 1.0,
        _ => 0.5 * m as f64 * 0.2,
    };

    // --- Tightness reward: near-perfect packing.
    if post <= 2 {
        score -= 15.0;
    }

    // Mild tie-break toward bins tighter than the mean (best-fit flavor).
    score += 0.1 * (post - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical future items (1..=20) are unusable dead space; penalize hard.
    if post_residual > 0 && post_residual < 20 {
        score += 40.0 + (20 - post_residual) as f64 * 2.0;
    } else if post_residual == 0 {
        // Perfect fit is ideal: strong reward.
        score -= 60.0;
    } else if post_residual >= 20 && post_residual <= 35 {
        // Moderately tight residual: mild reward for compact packing.
        score -= 5.0;
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 25.0;

    // Open-bins pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening a new bin is cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += pressure * 0.8 * (0.5 + 0.5 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when no open bin offers a
    // good fit (large post_residual elsewhere) or when the next item is large.
    if bin_residual == bin_capacity {
        score = 55.0 + post_residual as f64;
        // If the next item is big, a fresh bin is more valuable.
        score -= next_item_size as f64 * 0.3;
        // Late in the stream, avoid opening bins that will barely be used.
        score += progress * 15.0;
        // If an existing bin gives a near-perfect fit, discourage new bin.
        if post_residual < 10 && bin_residual != bin_capacity {
            score += 100.0;
        }
    }

    // Lookahead coupling: reward leaving residual that can host next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/tight fits
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Penalize dead space that is too small to be useful later
        if post_residual < 10 {
            score += 40.0;
        }
        // Reward small residuals that can still host typical items
        score -= (post_residual as f64).ln().max(0.0) * 5.0;
    }

    // 2-step lookahead: does post_residual match the next item?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: residual is final dead space
            let waste = (post_residual as f64) / bin_capacity as f64;
            score += 25.0 * waste;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 35.0;
        // but if no open bin fits well, opening fresh is attractive
        if next_item_size > 0 && item_size as f64 > mean_residual {
            score -= 45.0;
        }
    }

    // Compare against mean residual: bins tighter than average are better targets
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Late-stream consolidation: close out bins as stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize unusable dead space: post_residual too small to fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 22.0 / (1.0 + slack);
    }
    // Penalize if next item almost fits but not quite (blocks chain placement).
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 && next_item_size - post_residual <= 5 {
        score += 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it moderately attractive only when open bins have large residuals
    // (item would leave big dead space) or when many bins are open.
    if bin_residual == bin_capacity {
        let dead_space = (bin_capacity - item_size - post_residual) as f64; // always 0 here
        let waste_if_used = (bin_capacity - item_size) as f64;
        let avg_waste = (bin_capacity as f64) - mean_residual.min(bin_capacity as f64);
        // Open a new bin when existing residuals are small (poor fits elsewhere).
        let pressure = (mean_residual / bin_capacity as f64) - (item_size as f64 / bin_capacity as f64);
        if pressure < 0.15 {
            score -= 12.0 + dead_space;
        } else {
            score += 10.0 + 0.05 * waste_if_used - 0.02 * avg_waste;
        }
        // Late in the stream, avoid opening extra bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress * progress;
    }

    // Global state: with many open bins, prefer reusing bins with small residual (consolidation).
    if open_bins_count > 3 {
        score += 0.15 * (open_bins_count as f64);
        score -= 0.3 * (bin_capacity as f64 - mean_residual).max(0.0);
    }

    // Mild penalty for placing large items into nearly-full bins when other options exist.
    if item_size > 60 && bin_residual - item_size < 15 && fitting_bins_count > 1 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Base: wasted space, weighted by stream progress (dead space matters more later)
    let mut score = x * (1.0 + progress * progress);

    // Non-linear polynomial coupling of post-residual with progress
    let poly = x * x * (1.0 - x) * (1.0 - x);
    score += 12.0 * poly * (0.5 + progress);

    // Reward tight fits (small post_residual), smoothly scaled by progress
    score -= (1.0 - x) * (1.0 - x) * (2.0 + 3.0 * progress);

    // Lookahead: bonus if next item fits in post-residual (chain packing)
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 3.0 * (next_item_size as f64 / cap) * (1.0 + progress);
    }

    // Last-chance bin: strongly favor to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 + progress);
    }

    // Penalize leaving residuals smaller than typical item sizes (dead space)
    let mean_res_norm = mean_residual / cap;
    score += x * x * mean_res_norm * 4.0;

    // Mild penalty for many open bins, encouraging consolidation
    score += open_bins_count as f64 * 0.02 * x;

    // New-bin candidate: smooth threshold via progress-dependent offset
    if bin_residual == bin_capacity {
        score += 1.0 + 6.0 * progress - 4.0 * (1.0 - x);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: group residuals into capacity/10 classes
    let class = (post_residual / 10) as f64;

    // Perfect-fit rewards: residuals that form classic harmonic pairs
    if post_residual == 0 {
        score -= 100.0; // exact fill
    } else if post_residual <= 10 {
        score -= 40.0; // near-perfect, dead space negligible
    } else if post_residual % 10 == 0 {
        score -= 15.0; // harmonic class boundary residual (friendly to modular items)
    }

    // Penalize residuals that are "awkward" for typical item sizes (mod 10 classes)
    let awkward = match post_residual % 10 {
        1..=3 => 12.0,
        4..=7 => 6.0,
        _ => 0.0,
    };
    score += awkward;

    // Lookahead coupling: if the next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual && post_residual - next_item_size <= 10 {
            score -= 25.0;
        } else if next_item_size > post_residual {
            // next item won't fit here anyway; mildly penalize large leftovers
            score += class * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: prefer opening a fresh bin only when the item
    // is large relative to the bin or existing residuals are all poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Fresh bin baseline: attractive if mean residual across open bins is small
        // (open bins are mostly full) or early in the stream
        let mean_bonus = (mean_residual / bin_capacity as f64) * 40.0;
        score = 50.0 + mean_bonus - progress * 20.0;
        if item_size >= 60 {
            score -= 20.0; // large items like a fresh bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big pair coming, fresh bin useful
        }
    }

    // Mild penalty for very tight bins when many bins open (keep spread)
    if open_bins_count > 8 && post_residual < 5 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps: residuals below the minimum item size are dead space.
    if post_residual < 10 {
        score += 40.0;
    }
    // Penalize residuals that can't fit the next item (lookahead-aware dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward tight fits: post_residual near zero.
    if post_residual == 0 {
        score -= 30.0;
    }
    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }
    // Pressure on number of open bins: discourage spreading items across many bins.
    score += open_bins_count as f64 * 2.0;

    // Slightly favor bins whose residual is already below average (tighter bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive if the item
    // is large and no good fit exists; otherwise penalize it.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 1 {
            score -= 15.0; // no alternative: new bin is fine
        } else {
            score += 15.0; // prefer existing bins when alternatives exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post-residual large enough to fit the next item is good.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Bonus when the leftover is close to the next item (tight chain).
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (-slack / 15.0);
    } else {
        // Dead space too small for the next item: penalize.
        if next_item_size > 0 {
            score += (next_item_size as f64 - post_residual as f64) * 0.4;
        }
    }

    // Penalize creating very small unusable gaps (below min item size 1..100 heuristic).
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    // Relative to mean residual: prefer filling below-average-residual bins.
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when this bin's fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_waste = (bin_residual - item_size) as f64; // equals post_residual for empty bin
        // Attract new bin only if it yields a near-perfect packing (low leftover).
        score = fit_waste * 1.2 - 5.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 40.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 15.0;
        }
    }

    // Mild stream-progression damping: late in the stream, be slightly more conservative
    // about opening bins (favor reusing) — applies to non-new-bin calls via base score.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if !is_new_bin {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) / (bin_capacity as f64).powi(2) * 40.0;

    // Penalize dead space: post residual too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in post residual, strong reward
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New bin candidate: penalize mildly unless current bin would leave bad residue
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bins early or when open bins are fragmented
        let fragmentation = (mean_residual / bin_capacity as f64).max(0.0);
        score = 55.0 + 40.0 * fragmentation - 25.0 * progress;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 10.0;
        }
        if fitting_bins_count == 1 {
            score += 35.0; // discourage abandoning last fitting bin
        }
    }

    // Prefer fuller bins relative to mean residual state
    score += 0.15 * (mean_residual - post_residual as f64);

    // Mild time-dependent tightness pressure
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth non-linear coupling: dead-space penalty grows quadratically as residual shrinks
    let pr_norm = pr / cap;
    score += 40.0 * pr_norm * pr_norm * (1.0 - pr_norm);

    // Stream progress: late in stream, favor tighter fits more aggressively
    score -= (1.0 - t) * (pr / cap) * 12.0;
    score += t * (pr / cap) * 25.0;

    // Last-chance bin: reward strongly to avoid opening new bins unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly unless post_residual is large (good for future items)
    if bin_residual == bin_capacity {
        score += 8.0 - 20.0 * (next_item_size as f64 / cap) * (pr / cap);
    }

    // Lookahead: bonus if next item fits exactly into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 10.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Mean residual divergence: bins far below mean residual are wasted space
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev.abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover can still host
    // "large" items are more valuable. Classify by integer division bands.
    let class = post_residual / 10; // 0..=9 harmonic band
    match class {
        0 => score -= 12.0,            // near-perfect fit, tiny dead space
        1 => score -= 4.0,             // leftover 10-19: usable for small items
        2 => score += 3.0,             // 20-29: awkward gap zone
        3 | 4 => score -= 2.0,         // 30-49: still flexible
        5 => score += 5.0,             // 50-59: half-empty, wasteful
        _ => {}
    }

    // Exact harmonic alignment: leftover divisible by 10 is easier to fill.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: reward when post_residual exactly accommodates
    // the next item (perfect chain), penalize when next item can't fit here.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 2.0;
        } else {
            score += 4.0; // next item forces another bin anyway
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // late in the stream or when the fit here is very poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 - 12.0 * progress;
        if post_residual >= 70 {
            score -= 10.0; // item is large, fresh bin is fine
        }
    }

    // Prefer filling bins that deviate below the mean residual
    // (compact the emptier-looking bins first is wrong; instead reward
    // bins already tighter than average).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1,10] are nearly unusable
    // (min item size is 1, but small gaps rarely match future items).
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0 * (11.0 - post_residual as f64); // dead-space penalty
    }

    // Reward tight fits strongly (post_residual near 0 but not in dead zone handled above).
    if post_residual == 0 {
        score -= 30.0; // perfect fit bonus
    }

    // Penalize moderate waste that blocks useful future capacity.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 15.0 * waste_ratio * waste_ratio;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into
    // existing bins over opening new ones.
    score += 0.4 * open_bins_count as f64 * waste_ratio;

    // New-bin candidate: make it attractive only if current fits are poor.
    if bin_residual == bin_capacity {
        score -= 6.0;
        // If next item is large and this item leaves a big gap, opening a
        // fresh bin preserves ordering flexibility.
        if next_item_size as f64 > post_residual as f64 && post_residual > 0 {
            score -= 8.0;
        }
    }

    // Lookahead: prefer bins whose post_residual can still host next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    } else if next_item_size > 0 {
        score += 3.0;
    }

    // Late in the stream, tighten packing (less future to plan for).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - waste_ratio);

    // Mean residual context: if this bin is far below mean residual, it is
    // a good consolidation target.
    score -= 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual as u32 >= next_item_size {
            // Perfect chaining: post_residual exactly matches next item.
            if post_residual == next_item_size {
                score -= 300.0;
            } else {
                // Reward usable chain, penalize leftover after hypothetical next placement.
                let second_leftover = post_residual as f64 - next_item_size as f64;
                score -= 50.0 - second_leftover * 0.5;
            }
        } else {
            // Post-residual too small for next item: dead-space penalty scaled by tightness.
            let gap = next_item_size as f64 - post_residual as f64;
            score += gap * 0.8;
        }
    } else {
        // Last item: prefer zero waste strongly.
        score -= 50.0;
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless open bins are all poor fits.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Opening a new bin is attractive only if it can chain the next item perfectly.
        if next_item_size > 0 && (bin_capacity as u32 - item_size) >= next_item_size {
            score -= 60.0;
        }
        // More open bins => prefer reusing rather than proliferating.
        score += open_bins_count as f64 * 1.5;
    }

    // Late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) non-linearly.
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    } else {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 20.0 * fit_ratio * fit_ratio;
    }

    // Penalize dead space below the smallest plausible item (assume min item 1..10).
    let dead_threshold = 9u32;
    if post_residual < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual) as f64 * 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits in the post residual, reward; else penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / 100.0);
        } else {
            score += 6.0;
        }
    }

    // New-bin candidate logic: only attractive when current bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins are only chosen when genuinely better.
        score += 30.0;
        // If this bin is the only option or fits are scarce, ease the penalty.
        if fitting_bins_count <= 1 {
            score -= 40.0;
        }
        // Prefer opening new bins early when mean residual is already large.
        if mean_residual > 40.0 {
            score -= 10.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
    }

    // Slight preference for fuller bins when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * (bin_residual - post_residual) as f64 * 0.05;

    // Tie-break toward bins whose residual deviates from mean (consolidate slack).
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear penalty for wasted space, amplified by stream progress.
    let waste = post / cap;
    score += 12.0 * waste * waste * (0.4 + 0.6 * progress);

    // Reward tight fits: cubic interaction of post_residual with progress.
    score -= 8.0 * (1.0 - waste).powi(3) * (0.5 + 0.5 * progress);

    // Lookahead coupling: penalize if the next item cannot use the leftover space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 6.0 * (nxt - post) / cap;
        } else {
            // reward bins whose residue can host the next item snugly
            score -= 4.0 * (1.0 - ((post - nxt) / cap));
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when alternatives exist, more so late in stream.
    if bin_residual == bin_capacity {
        let alt = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        score += (10.0 + 8.0 * progress) / alt.sqrt();
    } else {
        // Slight preference for bins with residuals near the mean (balanced packing).
        let dev = (bin_residual as f64 - mean_residual).abs() / cap;
        score += 3.0 * dev * dev;
    }

    // Mild pressure against accumulating many open bins.
    score += 0.05 * open_bins_count as f64 * waste;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are less reusable; penalize dead space.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Integer-division thresholds on post_residual
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    } else if post_residual < 10 {
        score += 40.0; // tiny dead space, unusable
    } else if post_residual <= 20 {
        score += 12.0;
    }

    // Modulo arithmetic on post_residual: residues near common item sizes
    let m = post_residual % 10;
    if m == 0 {
        score -= 6.0; // residue aligns with decade-sized items
    } else if m >= 7 {
        score += 5.0; // awkward residue
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Favor tighter bins overall relative to mean residual
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.4;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.2;
    }

    // Late in the stream: prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += frac * 10.0 * progress;

    // New-bin candidate: neutral baseline with mild penalty so it's chosen
    // only when open bins look bad.
    if bin_residual == bin_capacity {
        score += 15.0 + 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // A residual gap that is too small to ever be useful is "dead space".
    // Penalize it super-linearly; the smaller the gap, the worse.
    let min_useful = 10.0f64;
    if (post_residual as f64) < min_useful {
        // dead space: gap of size g wastes g but blocks the bin entirely
        score += (min_useful - post_residual as f64) * 12.0;
    } else if post_residual == 0 {
        // perfect fit: reward strongly
        score -= 40.0;
    }

    // Penalize residual that cannot fit the lookahead item (wasted pairing chance)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Reward leaving exactly room for the lookahead item (ideal pairing)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // --- Open-bin pressure ---
    // Many open bins: prefer closing bins out (low post_residual favored more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += pressure * (2.0 + 3.0 * progress);

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin leaves a bad gap
    if bin_residual == bin_capacity {
        // neutral base; add mild penalty so open bins with decent fits win
        score += 5.0 + 0.1 * (post_residual as f64);
        // but if placing here would leave dead space elsewhere anyway,
        // opening fresh is fine: soften penalty when item is large
        if item_size >= 60 {
            score -= 10.0;
        }
    }

    // Tight-fill bonus: prefer bins where the item fills a large fraction
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fit
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - post_residual as f64).abs() < 3.0 {
            score -= 150.0; // next item chains perfectly into leftover
        } else if nxt <= post_residual {
            score -= 40.0 * (1.0 - (post_residual as f64 - nxt) / bin_capacity as f64);
        } else {
            // next item cannot fit: penalize dead space that blocks it
            score += 20.0 * (nxt - post_residual as f64) / 100.0;
        }
        // Bonus if post_residual + item chain leaves nothing for a third slot
        if post_residual as f64 + nxt > bin_capacity as f64 && post_residual <= 10 {
            score += 10.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    let diff = mean_residual - bin_residual as f64;
    score += 0.3 * diff;

    // Penalize creating very small unusable residuals relative to mean
    let pr = post_residual as f64;
    if pr > 0.0 && pr < mean_residual * 0.25 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are tight
    if bin_residual == bin_capacity {
        let tight = mean_residual < 15.0 || fitting_bins_count == 0;
        if tight {
            score -= 30.0;
        } else {
            score += 60.0 + 0.5 * mean_residual;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - pr / bin_capacity as f64);

    // Mild preference for bins with fewer alternatives
    if fitting_bins_count > 3 {
        score += 5.0 * (fitting_bins_count as f64 - 3.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual weighted quadratically).
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 60.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize dead space that cannot fit the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Crowding: with many open bins, prefer consolidating into fuller bins.
    let t = step_index as f64 / (total_items.max(1) as f64);
    let crowd = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += crowd * 2.0 * (0.5 + t);

    // Mean residual coupling: when mean residual is high, prefer bins below mean (fill laggards).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when no good fit exists
    // (large item relative to residuals) or late in stream with many bins open.
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / bin_capacity as f64;
        let mean_fit = mean_residual < item_size as f64;
        if mean_fit && pressure > 0.5 {
            score -= 35.0 * pressure;
        } else {
            score += 20.0 + 30.0 * (1.0 - pressure);
        }
    }

    // Early stream: be conservative, keep residual spread wide; late stream: pack tight.
    score *= 0.8 + 0.4 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly non-linearly coupled with stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Polynomial coupling: dead-space penalty grows superlinearly with progress
    // (late in stream, small residuals are less likely to be usable).
    score += 30.0 * norm_pr * norm_pr * (0.3 + progress);

    // Reward tight fits (small post_residual) more strongly as stream advances.
    score -= 20.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: if next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = pr - nxt;
            score -= 18.0 * (1.0 - slack / cap);
        } else {
            // penalize residuals that leave next item stranded
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Slight preference for bins whose residual deviates from the mean
    // (consolidate space): bins tighter than average get a discount.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev;

    // Discourage opening new bins when plenty of open bins exist and fit is decent.
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: tiny residuals are hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic classes: post_residual divisible by common item sizes (10,20,25,50)
    let classes = [10u32, 20, 25, 50];
    for &c in &classes {
        if post_residual % c == 0 && post_residual > 0 {
            score -= 8.0 * (post_residual as f64 / c as f64).sqrt();
        }
    }

    // Lookahead: does next item fit into post_residual? Reward chain fits.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            // harmonic match: next item exactly fills a class of the residual
            if post_residual % next_item_size.max(1) == 0 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here: penalize leaving awkward gaps
            let gap = post_residual as i64 - next_item_size as i64;
            if gap < 10 && gap >= 0 {
                score += 12.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral-ish baseline so it's chosen only
    // when open bins have bad fits.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + mean_residual * 0.1;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
        if post_residual >= 50 {
            score -= 10.0;
        }
        return score;
    }

    // Prefer tighter bins (small residual) via fractional class scaling.
    let frac = bin_residual as f64 / cap;
    score += frac * frac * 20.0;

    // Stream progression: late in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (cap - pr) * 0.1;

    // Mean residual coupling: if open bins are loose on average, penalize
    // adding to slack; encourage consolidating into tight bins.
    score += (mean_residual - pr) * 0.15;

    // Integer-division threshold on post_residual: buckets of 25.
    let bucket = post_residual / 25;
    score += bucket as f64 * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the smallest plausible
    // future item (<= 10, but interface allows 1..100 so use 1 as floor and
    // penalize the "awkward gap" band hardest).
    let dead_threshold = 10.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 200.0; // unusable sliver: very bad
    }

    // Penalize gaps that nothing in a typical stream can fill (gap < min item)
    // is covered above; also penalize gaps just above small items weakly.
    let pr = post_residual as f64;
    score += 0.05 * pr; // mild preference for tighter fits overall

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost that grows
    // with the number of open bins; only choose it when open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 60.0 + 8.0 * open_bins_count as f64;
        // But if existing bins would leave large dead space, new bin is fine:
        // (the dead-space penalties above already push those up)
        if post_residual as f64 >= 0.0 {
            score -= 0.0;
        }
        // Opening a bin when item is large relative to capacity is safer
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 40.0;
        }
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            score -= 0.5 * next_item_size as f64;
        } else {
            // next item won't fit here; slightly penalize leaving this residual
            score += 0.1 * (next_item_size - post_residual) as f64;
        }
    }

    // Open bins pressure: with many open bins, discourage spreading; with few,
    // allow more freedom.
    score += 0.3 * open_bins_count as f64 * (pr / bin_capacity as f64);

    // Mean residual coupling: prefer bins below mean residual (tighter bins
    // get used first, keeping large residual bins flexible).
    if bin_residual < bin_capacity {
        score -= 0.2 * (mean_residual - pr);
    }

    // Late-stream consolidation: near the end, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 50.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        let exact = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - exact / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item won't fit here: penalize wasted lookahead potential
        score += 15.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Penalize dead space (small unusable residuals)
    let cap = bin_capacity as f64;
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 0.3 * (post_residual as f64).sqrt();
    }

    // Last-chance bonus: only fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only open when nothing decent fits; make empty bin mildly unattractive
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Tightness reward scaled by stream progression
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Lookahead: strongly reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + 0.25 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // Penalize creating a residual that is unusable for the next item
        // but too small to be generally useful (dead space).
        if post_residual < next_item_size && post_residual < 10 {
            score += 25.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Global state: when many bins are open with slack, discourage opening new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty that shrinks as stream progresses.
        score += 12.0 - 8.0 * progress;
        // If the mean residual across open bins is large, opening a new bin is wasteful.
        score += 0.5 * mean_residual;
        // With few open bins and room to spare, new bins are cheap early.
        if open_bins_count <= 2 {
            score -= 10.0;
        }
    } else {
        // Reusing an open bin is generally good; extra reward proportional to fill.
        score -= 0.1 * (bin_capacity - bin_residual) as f64;
    }

    // Late in the stream, avoid leaving tiny unusable fragments.
    if progress > 0.8 && post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64 / cap;
    let fit_ratio = item_size as f64 / bin_residual as f64;

    // Smooth non-linear coupling: tight fits are rewarded increasingly with stream progress
    let tightness = (1.0 - fit_ratio).powi(3);
    score -= (1.0 + 3.0 * progress) * tightness * 30.0;

    // Penalize large dead space quadratically, more so late in the stream
    score += progress * pr * pr * 40.0;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr * cap {
        score -= 6.0 + 10.0 * (1.0 - pr);
    }

    // Penalize opening new bins when many bins are open with slack
    let new_bin = (bin_residual as f64 - cap).abs() < f64::EPSILON;
    if new_bin {
        score += 12.0 + 10.0 * (open_bins_count as f64).ln().max(0.0) - 8.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Residuals in fine-grained classes (divisible by 10) are more reusable.
    let class = post_residual / 10;
    let rem = post_residual % 10;

    // Reward fine-grained residuals (lower rem means cleaner class boundary).
    score -= (10 - rem) as f64 * 0.8;

    // Dead-space penalty: tiny unusable leftovers (class 0..2) are wasteful.
    if class <= 2 {
        score += 25.0 * (2.0 - class as f64);
    }

    // Reward large clean classes (roomy leftovers) mildly.
    score -= class as f64 * 0.5;

    // Lookahead coupling: does the leftover accommodate the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Harmonic match: leftover class divisible into next item size.
            let k = post_residual / next_item_size.max(1);
            score -= 6.0 + (k as f64).min(3.0) * 2.0;
        } else {
            // Near-miss penalty scaled by how far off we are, mod capacity.
            let gap = (next_item_size - post_residual) % bin_capacity;
            score += 4.0 + gap as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only on truly bad fits,
    // but allow it when open bins would leave terrible residuals.
    if bin_residual == bin_capacity {
        score += 8.0;
        if open_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Progress-aware tightening: as stream advances, prefer tighter packs.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64) * progress * 0.3;

    // Mean-residual coupling: avoid bins far from the mean (fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Integer-division threshold on item size: big items prefer tight bins.
    if item_size / 10 >= 6 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Moderate dead space (10..20) is also risky.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalty proportional to open bins: discourage spreading across many bins.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // If next item cannot fit in post_residual but fits elsewhere, mild penalty.
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Early stream: slightly prefer tight packing; late stream: prefer reusing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    // Prefer bins with residual close to mean (balanced packing).
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    // New-bin candidate: penalize slightly so we only open when open bins are bad.
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post residual
    // matches the next item's size (perfect chain placement).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let match_gap = (post_residual as f64 - nxt).abs();
        // Perfect match: next item exactly fills the bin -> big reward.
        if post_residual as f64 == nxt {
            score -= 60.0;
        } else if post_residual as f64 > nxt {
            // Next item fits after this one: reward proportional to tightness.
            score -= 25.0 * (1.0 - match_gap / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize leaving a small unusable gap.
            let gap = post_residual as f64;
            if gap < nxt * 0.5 {
                score += 18.0 * (1.0 - gap / nxt);
            }
        }
    } else {
        // Last item: prefer tightest fill.
        score -= 30.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    score += 0.6 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when item is huge relative
    // to capacity or all existing fits are terrible.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Mild penalty so open bins are preferred, but reward for large items.
        score += 8.0 - 14.0 * fill_ratio;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Penalize tiny dead space that nothing (min size 1) can use later.
    if post_residual > 0 && post_residual < 5 {
        score += 10.0;
    }

    // Late in stream: consolidate, prefer tighter bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize creating dead space that cannot fit a typical future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 10.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, mildly prefer fuller bins (larger item_size relative to residual).
        score += 3.0 * (item_size as f64 / bin_residual as f64);
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.9;
        // More open bins with high mean residual -> opening new bins is less attractive.
        score += open_bins_count as f64 * 0.5;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        // If item fits poorly anywhere (large residual gap), opening a bin is fine.
        let worst_gap = (bin_capacity as f64 - item_size as f64).max(0.0);
        score -= 0.2 * worst_gap;
        // If next item is huge, a fresh bin is valuable.
        if next_item_size >= item_size {
            score -= 8.0;
        }
    } else {
        // Existing bin: penalize bins far from mean residual (outliers) slightly.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post / cap;
    let mut score = post;

    // smooth non-linear coupling of post_residual with stream progress
    let poly = pr * pr * (1.0 - progress) + pr * progress * progress;
    score += poly * cap * 0.5;

    // penalize tight-but-wasteful fits more as stream advances
    score -= (1.0 - pr) * (1.0 - pr) * (1.0 + progress) * 10.0;

    // lookahead: reward leaving room for next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            score -= 8.0 * (1.0 - (nx / post).abs_diff_f64());
        } else {
            score += 6.0;
        }
    }

    // last chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // new-bin candidate: keep it competitive only when fits are poor
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - pr) + 5.0 * progress;
    }

    // mean residual coupling
    score += (mean_residual - post) * 0.05 * (1.0 + open_bins_count as f64).ln();

    score
}

trait AbsDiffF64 { fn abs_diff_f64(&self, other: f64) -> f64; }
impl AbsDiffF64 for f64 { fn abs_diff_f64(&self, other: f64) -> f64 { (self - other).abs() } }

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space penalty: residual too small for typical future items
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - progress);
    }

    // Harmonic class of post_residual mod capacity quarters
    let quarter = bin_capacity / 4;
    match post_residual / quarter {
        0 => score -= 20.0,              // very tight bin, well used
        1 => score += 5.0,               // moderate residual
        2 => score += 12.0,
        _ => {}                          // large residual left, mild penalty via base
    }

    // Lookahead: bonus if next item fits exactly into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 400.0;
        } else if slack < 10 {
            score -= 100.0;
        } else {
            score -= 40.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here; penalize leaving a stranded residual
        score += 30.0 * (post_residual as f64 / 10.0).min(6.0);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Prefer fuller bins relative to mean residual
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    } else {
        score += 10.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count == 0 {
            score -= 500.0; // nothing fits, must open
        } else {
            // discourage opening a new bin unless item is large and current fit poor
            let poor_fit = post_residual > quarter && post_residual < bin_capacity / 2;
            if poor_fit && item_size >= bin_capacity / 2 {
                score -= 80.0;
            } else {
                score += 150.0;
            }
        }
    }

    // Late stream: consolidate, penalize spreading across many bins
    if progress > 0.8 && open_bins_count > 3 {
        score += 5.0 * open_bins_count as f64;
    }

    // Small modular tie-breaker on harmonic class of item
    score += ((item_size % 7) as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Fit tightness relative to residual: reward filling a large fraction of the gap.
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 25.0 * fill_ratio;
    }

    // Pressure from number of open bins: discourage spreading across many bins
    // unless the fit is good; nudge toward consolidation.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity or current bins are nearly full / poor fits.
    if bin_residual == bin_capacity {
        let base = 20.0 + 2.0 * open_bins_count as f64;
        score = base + (bin_capacity - item_size) as f64;
        // Lookahead: if next item is small, leaving residual is fine.
        if next_item_size > 0 && next_item_size <= post_residual.max(0) {
            score -= 10.0;
        }
        // Late in the stream, prefer consolidation into existing bins.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 10.0 * progress;
        }
    }

    // Mean residual coupling: if open bins are generally tight, prefer this bin more.
    score -= 0.3 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    } else if post_residual <= 20 {
        score -= 60.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // this bin is a perfect two-item match — heavily favored.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let next_leftover = post_residual - next_item_size;
            // Reward chains that keep future leftovers small.
            score -= (20.0 - next_leftover.min(20) as f64) * 8.0;
            // Extra bonus if the chain terminates in an exact fit later.
            if post_residual as f64 >= next_item_size as f64 * 2.0 {
                score -= 10.0;
            }
        } else {
            // Next item cannot follow into this bin: penalize proportionally
            // to how much dead space would be stranded.
            let stranded = post_residual as f64;
            score += stranded * 0.5;
        }
    }

    // Relative to mean residual: bins tighter than average are better targets.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item
    // is large and would leave open bins in a bad state.
    if bin_residual == bin_capacity {
        score += 80.0;
        // Opening a new bin is attractive for large items with poor fits elsewhere.
        if item_size >= 60 && post_residual <= 40 {
            score -= 60.0;
        }
        // Late in the stream, avoid proliferation of open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
    }

    // Mild penalty for many open bins already (consolidation pressure).
    score += open_bins_count as f64 * 0.5;

    // Prefer placing larger items into tighter bins.
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling: post_residual weighted by progress
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Non-linear penalty on dead space that grows with stream progress
    score += 6.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits (small post residual) with smooth exponential falloff
    score -= 8.0 * (-(pr_norm) * 3.0).exp() * (1.0 - progress);

    // Interaction: post_residual vs mean residual — prefer bins near/below mean residual
    let mr_norm = mean_residual / cap;
    score += 3.0 * (pr_norm - mr_norm) * (pr_norm - mr_norm) * (1.0 + progress);

    // Penalize opening a new bin when many bins already fit the item
    if bin_residual == bin_capacity {
        let f = fitting_bins_count as f64;
        let openness = open_bins_count as f64;
        score += 2.0 * f * (1.0 + progress) - 1.5 * (openness / (openness + 5.0));
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strong smooth reward
        score -= 5.0 * (1.0 - pr_norm) * (1.0 - progress * 0.5);
    }

    // Lookahead coupling: reward leaving room for next item (smooth)
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let room = pr - ni;
        if room >= 0.0 {
            let room_norm = room / cap;
            score -= 4.0 * (-room_norm * 4.0).exp() * (0.5 + progress);
        } else {
            score += 2.0 * ((-room) / cap) * (1.0 - progress);
        }
    }

    // Mild penalty on very full bins late in stream (dead space avoidance)
    score += 1.5 * pr_norm.powi(3) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).

    // Harmonic class of post_residual: multiples of 10 are "usable" slots
    // for the common item-size grid; odd/dead classes are penalized.
    let dead = (post_residual % 10) as f64;
    score += dead * 1.5;

    // Strong reward if post_residual is exactly 0 or a clean class.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual % 10 == 0 {
        score -= 8.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // heavily reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 12.0;
        score += gap * 0.3;
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; residual becomes dead space.
        score += dead * 1.0 + (post_residual as f64).sqrt() * 2.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 15.0;
        if (post_residual as f64) > 0.6 * bin_capacity as f64 {
            score += 10.0; // wasteful placement in last bin
        }
    }

    // New-bin candidate: penalize opening a new bin generally, but allow it
    // when all open bins would leave large dead space.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 2.0;
        // If current item is large, a fresh bin is fine.
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        // Late in stream, avoid bin proliferation slightly less.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
    }

    // Prefer filling bins below mean residual (balancing).
    if (post_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // Large item into a large residual: fine; large item into tight residual: great.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 10.0;

    // Small absolute residual after placement is always good.
    if post_residual <= 10 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item (1) are
    // already counted via post_residual, but gaps below the typical item scale
    // are effectively dead — penalize them super-linearly.
    let dead_threshold = 20.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Open-bin pressure: with many open bins, discourage opening new ones and
    // encourage filling existing bins; also make new-bin candidate less attractive.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open.
        score += 15.0 + pressure * 2.0;
        // But allow it if no open bin fits well (last-chance logic inverted).
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Last chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Coupling with mean residual: prefer bins whose residual is near the mean
    // (keeps bin states homogeneous, easier future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // If next item cannot fit in post residual but could fit elsewhere, mild penalty.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 5.0;
    }

    // Stream progression: late in the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but strongly avoid tiny dead space (< 10, unusable for min item).
    if post_residual < 10 {
        score += 15.0;
    } else {
        score -= 6.0 / (post_residual as f64).sqrt();
    }

    // Lookahead: reward when next item fits exactly into post_residual (perfect 2-step chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (-slack / 12.0).exp(); // decaying bonus for near-exact match
            if post_residual - next_item_size < 10 {
                score += 5.0; // chain would still leave dead space
            }
        } else {
            // next item cannot follow here: mild penalty proportional to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 4.0 * (1.0 - (-over / 25.0).exp());
        }
    } else {
        // Last item: just close bins as tightly as possible.
        score -= 10.0;
    }

    // Compare against mean residual: filling an above-average-residual bin is good.
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fits are poor.
    if bin_residual == bin_capacity {
        score += 8.0;
        // but if next item is large and current bin residual is small, new bin is attractive
        if next_item_size > 0 && post_residual < next_item_size && post_residual < 20 {
            score -= 20.0;
        }
        if next_item_size == 0 {
            score += 25.0; // never open a new bin for the last item
        }
    }

    // Late in the stream: consolidate harder.
    let progress = step_index as f64 / total_items as f64;
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: reward heavily
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead (k=2): reward if next item also fits after this placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0;
        } else if post_residual > 0 {
            // dead space that cannot host the next item
            score += 20.0;
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize so it only wins when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 25.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin can host the next item too
        }
    }

    // Reward filling bins with larger items (better space economy)
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Penalize tiny unusable fragments (dead space below typical min size)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Time horizon: early in the stream, be more conservative about fragmenting bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 {
        score += (1.0 - progress) * (post_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with progress:
    // late in the stream, small residuals become more valuable (tight packing).
    let pr_norm = pr / cap;
    let coupling = pr_norm * pr_norm * (0.5 + progress) - pr_norm * progress * 0.8;
    score += coupling * cap * 0.6;

    // Penalize dead space that cannot fit a plausible next item (lookahead k=2).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            // unusable residual for the lookahead: penalize quadratically
            score += (nxt - pr) * (nxt - pr) / cap * 2.0;
        } else {
            // reward residuals that exactly accommodate the lookahead (smooth)
            let fit_gap = (pr - nxt) / cap;
            score -= (1.0 - fit_gap * fit_gap) * 3.0;
        }
    } else {
        // last item: strongly prefer tight fit
        score -= (1.0 - pr_norm) * 5.0;
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0 + 4.0 * (1.0 - progress);
    }

    // New empty bin candidate: penalize opening a new bin, unless current
    // residuals are nearly exhausted (smooth relaxation instead of piecewise).
    if bin_residual == bin_capacity {
        let exhaustion = 1.0 - (mean_residual / cap).min(1.0);
        score += 6.0 + 6.0 * (1.0 - exhaustion * exhaustion);
        // mild reward late in stream for fresh bins (consolidation)
        score -= progress * 2.0;
    }

    // Mild preference for bins tighter than the average residual (good fit).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 3.0 - dev * 1.5;

    // Slight penalty for spreading across many open bins early on.
    score += (open_bins_count as f64).ln() * 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals that leave "useful" slots
    // (multiples of common item sizes / capacity fractions).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward perfect fit strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward post_residual that is divisible into harmonic classes
    // (e.g. 10, 20, 25, 50): these align with typical item sizes.
    let harmonic = (post_residual % 10 == 0) as f64 * 8.0
        + (post_residual % 20 == 0) as f64 * 4.0
        + (post_residual % 25 == 0) as f64 * 4.0
        + (post_residual % 50 == 0) as f64 * 6.0;
    score -= harmonic;

    // Penalize tiny dead space (1..=5): unusable slivers.
    if post_residual > 0 && post_residual <= 5 {
        score += 60.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            // reward proportional to how tightly next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / cap).max(0.0);
            // harmonic match between next item and post residual
            if (post_residual % next_item_size.max(1)) == 0 {
                score -= 30.0;
            }
        } else {
            // next item won't fit here; slight penalty for blocking
            score += 15.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: make empty bin attractive only when
    // current bin fit is poor (large post_residual) or few fitting bins.
    if bin_residual == bin_capacity {
        // baseline competitiveness for a fresh bin
        score = 0.5 * cap + 0.3 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // fresh bin good for large follow-up
        }
    }

    // Mild pressure against bin sprawl late in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.02 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Slight preference for tighter fits overall via mean residual coupling.
    score += 0.1 * (pr - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest possible item (size 1) are pure waste; residuals below the
    // typical item floor are nearly unusable. Penalize them quadratically.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 80.0 + (10 - post_residual) as f64 * 6.0; // dead space penalty
    } else if post_residual < 25 {
        score += (25 - post_residual) as f64 * 1.5; // mild penalty for tight gaps
    }

    // Reward tight fits: small post_residual relative to item size.
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= tightness * 15.0;

    // Lookahead: if the next item can fit into the post-residual, this
    // placement chains nicely; reward it. If next item is bigger than
    // post_residual but this bin is the only fitting one, accept anyway.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless post_residual is dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many open bins when
    // residuals are already small; encourage using existing bins early.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + progress * 3.0);

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a good consolidation target.
    let residual_diff = mean_residual - bin_residual as f64;
    if residual_diff > 0.0 {
        score -= residual_diff * 0.5;
    } else {
        score += (-residual_diff) * 0.2;
    }

    // New-bin candidate: only attractive when no open bin offers a decent
    // fit (i.e., current bin would leave dead space) or stream is early.
    if bin_residual == bin_capacity {
        if post_residual < 10 && item_size >= 60 {
            score -= 25.0; // big item alone in fresh bin is fine
        } else {
            score += 30.0; // default: prefer existing bins
        }
        if progress < 0.2 {
            score -= 10.0; // early stream: opening bins is cheap
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
