    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize wasted potential
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Penalize residuals too small to ever fit a future item (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Relative to mean residual: prefer bins with above-average usage
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 250.0 + 200.0 * (1.0 - progress);
        // but if next item is large and current item is small, opening may be OK
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 150.0;
        }
    }

    // Mild penalty for many open bins (encourage consolidation)
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

