    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(3) * 30.0;

    // Penalize dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: reward if next item fits the post-residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // bonus proportional to how well next item nests
            let nest = (post_residual - next_item_size) as f64;
            score -= (1.0 - nest / bin_capacity as f64) * 8.0;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // when many bins fit, prefer the tightest anyway (base handles it), mild penalty
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Time horizon: early in stream, be pickier about loose fits (more items coming).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * fit_ratio * 15.0;

    // Global state: if mean residual is high, spread items; if low, consolidate.
    score += (mean_residual - post_residual as f64) * 0.15;

    // Penalize opening new bins when open bins are already plentiful and roomy.
    if bin_residual == bin_capacity {
        // new-bin candidate: base score is capacity; adjust by global pressure
        score -= (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 10.0; // big item followed by big item: keep fresh bin option alive
        }
        if fitting_bins_count <= 1 && progress > 0.5 {
            score -= 5.0; // late stream: reuse is cheap
        }
    }

    // Mild consolidation bonus for filling bins more than half.
    if bin_residual as f64 <= bin_capacity as f64 * 0.5 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
