    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;
    let norm_item = item / cap;

    // Base: prefer small post residual (tight fit), non-linearly
    let mut score = post * (1.0 + 2.0 * norm_post * norm_post);

    // Smooth interaction: as stream progresses, tighten preference for tight fits
    score *= 1.0 + progress * norm_post;

    // Penalize large dead space quadratically late in the stream
    score += 40.0 * norm_post * norm_post * (0.5 + progress);

    // Reward bins whose residual matches the next item well (lookahead coupling)
    if next_item_size > 0 && post_residual >= next_item_size {
        let nnext = next_item_size as f64 / cap;
        score -= 12.0 * nnext * (1.0 - (nnext - norm_post).abs());
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * (1.0 - norm_post);
    }

    // Mild penalty when many bins are open and residual is far above mean (fragmentation)
    let dev = (post - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Slight preference for using existing bins over opening new ones as stream progresses
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that pair well with common
    // item sizes are rewarded. Class 0 (perfect fit) strongly rewarded.
    let class = post_residual % 10;
    score -= match class {
        0 => 25.0,
        1 | 9 => 3.0,
        2 | 8 => 5.0,
        3 | 7 => 8.0,
        4 | 6 => 12.0,
        _ => 15.0,
    };

    // Post-residual that exactly fits the lookahead item => big bonus.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // leftover after also placing the next item, quantized
        let q = (post_residual - next_item_size) / 10;
        score -= q as f64 * 4.0;
    } else if next_item_size > 0 {
        // next item cannot fit here: penalize small dead space more
        score += 6.0;
    }

    // Integer-division threshold: tiny unusable remainders are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin fit is poor
    // (large post-residual) or the bin is untouched.
    if bin_residual == bin_capacity {
        score -= 12.0 + 0.15 * mean_residual;
    }

    // Prefer filling already-open bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0;
    score += (open_bins_count as f64) * 0.3;

    // Tightness coupling: reward placements leaving small residuals relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: residuals that can never fit even the
    // smallest item (1) are pure waste; residuals below a "usable threshold"
    // are penalized super-linearly.
    let min_item = 1.0f64;
    if post < min_item {
        score += 1000.0; // exact fill is perfect, but guard
    } else if post > 0.0 && post < 10.0 {
        // small dead gap: heavily penalize proportionally to unusability
        score += (10.0 - post) * 6.0;
    }

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // prefer filling existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.5 * (0.5 + progress);

    // New-bin candidate handling: only attractive when the current item
    // would leave a bad gap in every existing bin, or lookahead fits better
    // in a fresh bin.
    if bin_residual == bin_capacity {
        let fresh_bonus = if post_residual == 0 {
            -80.0 // perfect fill in fresh bin
        } else if (next_item_size as f64) <= post && post >= 60.0 {
            -40.0 // fresh bin leaves room for the next item too
        } else if post < 10.0 && fitting_bins_count > 0 {
            30.0 // opening a bin just to make dead space is bad
        } else {
            10.0 // default: mildly discourage new bins
        };
        score += fresh_bonus;
    } else {
        // Existing bin: bonus if post-residual still fits the lookahead item
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 12.0;
        }
        // Penalize leaving a gap that fits neither the next item nor anything useful
        if next_item_size > 0 && post < next_item_size as f64 && post >= 1.0 {
            score += (next_item_size as f64 - post) * 0.8;
        }
    }

    // Mean residual coupling: bins far below mean residual are "ragged";
    // prefer bins whose residual is close to what we are consuming.
    let resid_gap = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += resid_gap * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but punish unusable dead space.
    if post_residual > 0 {
        // dead space penalty grows super-linearly for small residuals
        score += 8.0 / (post_residual as f64).sqrt();
    } else {
        // perfect fill is excellent
        score -= 25.0;
    }

    // ---- 2-step lookahead matching ----
    if next_item_size > 0 && post_residual >= next_item_size {
        // The next item can chain into this bin's leftover: reward proportionally
        // to how snugly the next item matches the post residual.
        let chain_fit = next_item_size as f64 / post_residual as f64;
        score -= 18.0 * chain_fit;

        // Exact chain match is ideal
        if post_residual == next_item_size {
            score -= 30.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: dead space unless residual is tiny.
        if post_residual >= 10 {
            score += 12.0;
        }
    }

    // Compare leftover against mean residual: leaving more than average
    // suggests this bin is being under-filled relative to the fleet.
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.25 * dev;
    } else {
        score += 0.10 * dev; // small reward for being tighter than average
    }

    // ---- Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin ----
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // ---- New empty bin candidate ----
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when:
        //  - no open bin fits (fitting_bins_count == 0), or
        //  - the item is large and would leave an awkward fit elsewhere,
        //  - late in the stream where closing out bins matters.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let new_bin_bonus = if fitting_bins_count == 0 {
            -40.0
        } else {
            // mild attraction when item is big and progress is late
            10.0 - 15.0 * progress - 0.2 * item_size as f64
        };
        score += new_bin_bonus;
        // A fresh bin's residual equals capacity; normalize so it isn't
        // unfairly favored/penalized by the raw post_residual term.
        score -= (post_residual as f64) * 0.9;
        // Empty-bin lookahead: opening a bin now gives full room for the next item
        if next_item_size > 0 && next_item_size >= item_size {
            score += 5.0;
        }
    }

    // Early in stream: slightly favor consolidating into fewer bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 4.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space
    score += 0.6 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: reward residuals that can still host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.25 * next_item_size as f64;
        } else {
            // dead space for the next item: penalize proportionally
            score += 0.35 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // last item: pure tightness matters most
        score -= 8.0;
    }

    // Penalize bins whose residual deviates far below the mean (fragmented bins)
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += 0.15 * dev;
    } else {
        score += 0.05 * dev.abs();
    }

    // Time horizon: early in the stream, be conservative (favor filling existing bins);
    // late in the stream, tightness dominates.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin should only win when open bins are poor fits
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, reduced when many items remain
        score = bin_capacity as f64 + 20.0 - 15.0 * progress;
        if fitting_bins_count > 0 {
            score += 25.0; // discourage opening when some open bin fits
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big-next-item: fresh bin may pay off
        }
    }

    // Mild pressure against bin sprawl
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Stream-progress coupling: later in the stream, penalize wasted residual more strongly
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Interaction: squared post-residual times progress (smooth polynomial coupling)
    score += 12.0 * norm_pr * norm_pr * progress;

    // Last-chance bonus: strongly reward using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Penalize bins far from mean residual (encourage homogenization)
    let dev = (pr - mean_residual).abs() / cap;
    score += 6.0 * dev * dev;

    // Lookahead: if next item fits into the post residual, reward
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let next_fit = next_item_size as f64 / cap;
        score -= 8.0 * next_fit * (1.0 - progress);
    }

    // Mild penalty when many bins are open (prefer consolidation)
    score += 0.4 * open_bins_count as f64 * norm_pr;

    // New-bin candidate handling: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score = 40.0 + 30.0 * progress - 10.0 * (fitting_bins_count == 0) as i32 as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual via integer division into dead-space bands.
    // Band 0: post_residual == 0 (perfect fit) -> strong reward.
    // Band 1..3: small slivers likely unusable -> penalize.
    // Larger bands: residual may still host future items.
    let band = post_residual / 10; // harmonic class width 10
    match band {
        0 => { score -= 60.0; }
        1 => { score += 25.0; }  // 10..19: awkward dead space
        2 => { score += 12.0; }  // 20..29
        3 => { score += 5.0; }   // 30..39
        _ => { score -= 3.0; }   // roomy leftovers are fine
    }

    // Tightness reward: fraction of bin consumed by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Lookahead: does post_residual still fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bonus scaled by how much slack remains for the next item too.
            let combo = (item_size + next_item_size) as f64 / bin_capacity as f64;
            if combo <= 1.0 {
                score -= 15.0 + 10.0 * combo;
            } else {
                score -= 8.0;
            }
        } else {
            // This placement strands the next item: penalize more when post_residual is a tiny sliver.
            score += 10.0 + (10 - band.min(10)) as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many items remain
        // and open bins are already crowded.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 45.0 - 10.0 * progress;
        if open_bins_count == 0 { score -= 50.0; }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        // If current item is large relative to capacity, new bin is attractive.
        if item_size >= 50 { score -= 10.0; }
    }

    // Mild dispersion penalty: prefer bins whose residual deviates from the mean
    // in the direction of tighter packing.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small gaps (dead space): residuals below the minimum item size are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Strongly favor perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when plenty of open bins exist (open-bin pressure).
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * open_bins_count as f64;
        // But allow new bin if item is huge and no open bin fits well.
        if item_size > bin_capacity / 2 && fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Lookahead: if the next item would fit exactly into the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 30.0;
        } else if (post_residual as u32) >= next_item_size && (post_residual as u32) - next_item_size < 10 {
            score -= 10.0;
        }
        // Penalize leaving residual just below the next item (blocking it).
        if (post_residual as u32) < next_item_size && post_residual > 0 {
            score += 10.0;
        }
    }

    // Mild pressure from number of open bins: prefer tighter bins when many are open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Progress-aware tightness: as the stream progresses, prefer tighter fits more strongly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / 10.0);

    // Prefer bins already tighter than the mean residual (fragmentation avoidance).
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post-residual
    // can still host the next item (chained packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: next item exactly fills the remainder.
            let chain_gap = (post_residual - next_item_size) as f64;
            score -= 18.0 + 22.0 * (1.0 - chain_gap / bin_capacity as f64);
        } else {
            // Next item won't chain: penalize proportionally to wasted capacity.
            let waste = next_item_size as f64 - post_residual as f64;
            score += 0.35 * waste;
        }
    } else {
        // Last item: prefer tightest fit.
        score += 0.0;
    }

    // Penalize dead space that is too small for the minimum item size (1),
    // but especially useless slivers relative to mean residual.
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 4.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins are very full
    // (mean residual small) or the item is large relative to typical residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / bin_capacity as f64;
        // Reward new bin when existing bins are tight; penalize otherwise.
        score += 30.0 - 40.0 * pressure - 10.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin chains well with next item
        }
    }

    // Mild preference for spreading load when many bins are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 * ((next_item_size - post_residual) as f64 / 100.0);
        } else if post_residual >= next_item_size + 10 {
            score -= 6.0; // next item still fits comfortably here
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin when several bins already fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64 / (fitting_bins_count.max(1) as f64)).ln();
        score += 10.0 + 15.0 * pressure * (1.0 - progress);
    } else {
        // Prefer bins with residual below the global mean (consolidate waste).
        let dev = mean_residual - bin_residual as f64;
        score -= 0.08 * dev;
    }

    // Mild penalty for leaving very small, hard-to-use slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Core: prefer small post_residual, with non-linear (quartic-ish) dead-space penalty
    let mut score = post + (post / cap).powi(4) * 40.0;

    // Tightness reward: strongly favor near-perfect fits (smooth bell around post ~ 0)
    let tight = (-post / (0.25 * cap)).exp();
    score -= 25.0 * tight;

    // Lookahead: reward if the next item can fit into the post residual (chaining),
    // penalize if post residual is a useless sliver (too small for min-size items but nonzero)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 6.0 * (1.0 - (post - nxt) / cap);
        } else if post > 0.0 {
            // dead space: nothing can follow; penalize more as stream progresses
            score += 8.0 * (0.3 + 0.7 * progress);
        }
    } else if post > 0.0 {
        score += 5.0 * (0.3 + 0.7 * progress);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mean-residual coupling: when open bins are generally full, avoid wasting a roomy bin
    score += 0.05 * (mean_residual - post).abs();

    // New-bin candidate: penalize so we only open a new bin when it's genuinely better
    // (e.g., item much larger than typical residuals) — smooth escape hatch.
    if bin_residual == bin_capacity {
        let escape = ((item_size as f64 / cap).powi(3)) * 30.0;
        score += 20.0 * (1.0 - 0.5 * progress) - escape;
    }

    // Mild preference to keep the number of open bins low early, more freedom later
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-classes w.r.t. small item sizes.
    // Residuals that are "clean" multiples of common small sizes are more reusable.
    let pr = post_residual;
    if pr > 0 {
        let mut harmonic_bonus = 0.0;
        for m in [10u32, 20, 25, 50] {
            let r = pr % m;
            if r == 0 {
                harmonic_bonus += 4.0;
            } else if r <= 2 {
                harmonic_bonus += 2.0;
            } else {
                // penalize residuals just past a harmonic boundary (dead space)
                harmonic_bonus -= (r as f64) * 0.15;
            }
        }
        score -= harmonic_bonus;

        // Integer-division threshold: residual class by halving
        let half = bin_capacity / 2;
        if pr <= half / 2 {
            score += 6.0; // tiny residual: likely dead space
        } else if pr <= half {
            score -= 3.0; // mid residual: still useful
        } else {
            score -= 5.0; // large residual: very flexible
        }
    } else {
        // perfect fit: strong reward
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward heavily
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            score += (next_item_size - pr) as f64 * 0.2;
        }
    }

    // Last-chance bin: penalize opening a new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: prefer opening fresh bins early in the stream or when
    // mean residual of open bins is already fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 5.0 + 10.0 * (1.0 - progress) - fragmentation * 0.1;
        if item_size > bin_capacity / 2 {
            score -= 6.0; // big items like fresh bins
        }
    }

    // Mild pressure against accumulating many open bins with slack
    score += mean_residual * 0.05 / (open_bins_count.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small for typical future items
    // (below the minimum item size threshold) are wasted capacity.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward leaving a gap exactly matching the lookahead item (k=2 lookahead)
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 80.0;
        } else if gap > 0 && gap < 10 {
            score += 40.0; // would strand the next item's fit
        } else if gap < 0 && (-gap) < 10 {
            score += 25.0 * (-gap) as f64;
        }
    }

    // Tightness reward: favor bins where the item fills a large fraction
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Open-bin pressure: when many bins are open, prefer reusing them
    // over opening new ones; when few bins, opening new is cheaper.
    score += (open_bins_count as f64) * 2.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Penalize new-bin candidate slightly when item fits reasonably elsewhere
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.5;
        // but allow new bin if mean residual is very fragmented
        if mean_residual < 8.0 {
            score -= 30.0;
        }
    }

    // Slight preference to keep large residual bins flexible
    score -= bin_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 15.0 - 0.1 * (post_residual - next_item_size) as f64;
        } else {
            // dead space relative to next item
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Penalize large leftover chunks that likely become dead space
    if post_residual > 0 && post_residual < 10 {
        score += 5.0; // tiny unusable sliver
    }

    // Last-chance bin bonus: avoid opening a new bin when only one fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make empty bins mildly attractive only when current fit is bad
    if bin_residual == bin_capacity {
        score += 10.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 5.0;
        }
    }

    // Late-stream consolidation: fewer open bins favored
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0 * open_bins_count as f64 / (open_bins_count.max(1) as f64 + 1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to ever fit typical items.
    if post_residual > 0 && post_residual < item_size.min(50) {
        score += 8.0 * (1.0 - post_residual as f64 / 50.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to waste.
            score += 2.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Global pressure: many open bins relative to progress -> consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 4 && mean_residual > item_size as f64 {
        score -= 3.0 * (mean_residual - item_size as f64) / bin_capacity as f64;
    }

    // Early in stream: encourage spreading (keep residuals flexible).
    if progress < 0.2 && post_residual > 0 {
        score += 2.0 * (1.0 - progress);
    }

    // New empty bin candidate: penalize unless no open bin fits well.
    if bin_residual == bin_capacity {
        let base = 6.0 + 10.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 25.0;
        } else if post_residual < 15 {
            score += base;
        } else {
            score += base * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Polynomial coupling of post-residual with stream progress:
    // early on, tolerate larger residuals; late, punish them quadratically
    let late_penalty = 1.0 + 1.2 * progress * progress;
    score *= late_penalty;

    // Interaction: residual relative to mean residual across open bins
    let rel = if mean_residual > 0.0 { pr / mean_residual } else { 1.0 };
    score += 0.3 * rel * rel;

    // Lookahead coupling: reward leaving room for the next item (smooth kernel)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let slack = (pr - ns).max(0.0);
        let fit_kernel = slack / (slack + 10.0);
        score -= 6.0 * fit_kernel;
        // smooth mismatch penalty if next item nearly exactly fills residual
        let tight = 1.0 - ((pr - ns).abs() / cap);
        score -= 4.0 * tight * tight;
    }

    // Last-chance bin: smooth reward scaled by scarcity
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + 0.5 * progress);
    } else {
        score += 0.5 * (fitting_bins_count as f64).ln();
    }

    // Mild pressure against opening too many bins (new-bin candidate gets residual = cap)
    let new_bin_bias = if bin_residual == bin_capacity {
        5.0 + 4.0 * (open_bins_count as f64).sqrt() + 3.0 * progress
    } else {
        0.0
    };
    score += new_bin_bias;

    // Item-size coupling: big items prefer tight fits (non-linear in item size)
    let isz = item_size as f64;
    score -= 0.02 * (isz / cap) * (1.0 - pr_norm) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left over

    // Penalize dead space quadratically, but give harmonic-class bonuses
    // for residuals that are "reusable" (near common item sizes / divisors).
    score += 0.35 * pr * frac;

    // Harmonic classes of post_residual mod 10 and mod 25:
    // residuals that are multiples of 10 or 25 are more likely reusable later.
    let m10 = post_residual % 10;
    let m25 = post_residual % 25;
    if m10 == 0 {
        score -= 6.0;
    } else if m10 == 5 {
        score -= 2.5;
    } else {
        score += 1.5; // odd/awkward residual is dead space
    }
    if m25 == 0 {
        score -= 5.0;
    }

    // Perfect fit is heavily rewarded
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chain placement).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            let npr = post_residual - next_item_size;
            // harmonic class of the double residual
            if npr % 10 == 0 {
                score -= 8.0;
            }
            score += 0.1 * npr as f64;
        } else {
            // next item won't fit here: residual becomes terminal dead space
            score += 0.15 * pr;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 0.05 * item_size as f64;
    }

    // New-bin candidate: only attractive when open bins have poor fits or the
    // item would leave very awkward residuals everywhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let opening_penalty = 55.0
            - 20.0 * progress
            - 0.10 * mean_residual
            - 8.0 * (open_bins_count as f64).sqrt();
        score = cap + opening_penalty.max(-30.0);
        // a fresh bin is good if item is large (fills it well)
        score -= 0.15 * item_size as f64;
    }

    // Slight preference for fuller bins overall (best-fit flavor)
    score -= 0.05 * (bin_capacity.saturating_sub(bin_residual)) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps super-linearly.
    // A residual that can never hold the smallest item is pure dead space.
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 40.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 6.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        score -= (item_size as f64) * 0.6;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // Candidate new bin: penalize more when many bins are open or late in stream.
        score += 60.0 + 3.0 * open_bins_count as f64 + 50.0 * progress;
        // But if the item barely fits anywhere and next item is large, new bin is safer.
        if next_item_size > 0 && next_item_size > bin_residual {
            score -= 30.0;
        }
    } else {
        // Slight preference for existing bins scaled by open-bin count.
        score -= 1.5 * open_bins_count as f64;
    }

    // Prefer bins with residual close to mean (balanced packing) mildly.
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.15;

    // Lookahead: if the next item exactly fits the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 100.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover: penalize dead space more.
        score += post_residual as f64 * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor exact/tight fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 60.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 5 {
            score -= 150.0;
        } else if post_residual < next_item_size && post_residual >= 10 {
            // next item can't follow here; penalize dead space relative to next size
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
        // bonus if the pair nearly fills the bin
        let pair = item_size as f64 + next_item_size as f64;
        if pair >= bin_capacity as f64 {
            score -= 300.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Penalize creating large unusable gaps
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Mild penalty for very fragmented state (many open bins)
    score += open_bins_count as f64 * 0.5;

    // Early stream: slightly prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // the minimum item size (1..10) is wasted; penalize tiny-but-nonzero waste.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; slight penalty proportional to overshoot
            score += (next_item_size - post_residual).min(30) as f64 * 0.3;
        }
    } else {
        // last item: strongly prefer zero residual
        score += post_residual as f64 * 0.2;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when open bins fit
    // and mean residual is large enough to absorb the item.
    if bin_residual == bin_capacity {
        let mut new_bin_score = 55.0 + open_bins_count as f64 * 2.0;
        if mean_residual >= item_size as f64 {
            new_bin_score += 20.0;
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0; // forced new bin
        }
        // late in stream, prefer consolidating
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += progress * 10.0;
        score += new_bin_score;
    }

    // Mild preference for bins with residual close to mean (balance loads)
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.15;

    // Prefer using larger-residual bins slightly when many bins are open
    score -= bin_residual as f64 * 0.05 * (open_bins_count.min(20) as f64 / 20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits, but with non-linear polynomial shaping
    let base = pr_norm * pr_norm * (1.0 + 2.0 * pr_norm) * cap;

    // Smooth interaction: as stream progresses, penalize large residuals more strongly
    let progress_coupling = 30.0 * progress * pr_norm * pr_norm;

    // Dead-space penalty: residuals too small to be useful later (smoothly curved)
    let dead_zone = 12.0 * (1.0 - pr_norm).powi(6) * pr_norm.powi(2);

    // Last-chance bonus: strongly reward using the only bin that fits
    let last_chance = if fitting_bins_count == 1 { -25.0 - 20.0 * progress } else { 0.0 };

    // Lookahead: reward if next item fits post-residual, penalize otherwise
    let lookahead = if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr as f64 {
            -8.0 * (1.0 - (nxt / pr).min(1.0))
        } else {
            6.0 * ((nxt - pr) / cap)
        }
    } else {
        0.0
    };

    // Slight preference to spread across bins when many are open
    let spread = 2.0 * (open_bins_count as f64).ln() * pr_norm;

    // New-bin candidate handling: mildly favor opening a new bin early, penalize late
    let new_bin_adjust = if bin_residual == bin_capacity {
        10.0 * (1.0 - progress) - 5.0 * progress
    } else {
        0.0
    };

    base + progress_coupling + dead_zone + last_chance + lookahead + spread + new_bin_adjust
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space: post_residual too small for the next item (if any) is likely wasted.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }
    if next_item_size == 0 && post_residual > 0 {
        // End of stream: leftover space is pure waste, but mildly weighted.
        score += post_residual as f64 * 0.2;
    }

    // Harmonic class: residue classes of post_residual modulo 10.
    // Small residues (1..9) are hard to fill; penalize proportionally.
    let r = post_residual % 10;
    if post_residual > 0 {
        score += (9 - r) as f64 * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: make it unattractive unless the fit into open bins is bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 120.0;
        // Attractive only if the item is large relative to capacity
        // (hard to place later) or early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (item_size as f64 / bin_capacity as f64) * 40.0;
        score -= (1.0 - progress) * 15.0;
        // Discourage new bins when many bins are already open and mean residual is high.
        score += (open_bins_count as f64).sqrt() * 5.0 + mean_residual * 0.3;
    }

    // Slight preference for bins with lower residual overall (tighter packing).
    score += (bin_residual as f64 - post_residual as f64) * 0.05;

    // Lookahead synergy: if next item exactly fits the post residual, reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 300.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that can only hold tiny items are wasteful.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage new bins.
    if bin_residual == bin_capacity {
        score += 10.0 + 3.0 * open_bins_count as f64;
        // But allow a new bin if the fit in open bins would be terrible.
        if post_residual as f64 > 0.5 * bin_capacity as f64 {
            score -= 5.0;
        }
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 4.0;
    }

    // Mean residual coupling: bins far below mean residual are less attractive.
    score += 0.1 * (mean_residual - bin_residual as f64);

    // Slight preference to fill older bins as stream progresses.
    score += 0.5 * (bin_capacity - bin_residual) as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly favor bins whose post_residual is tiny.
    if post_residual == 0 {
        score -= 500.0;
    } else {
        // Dead-space penalty grows non-linearly for small unusable residuals.
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += (10.0 - pr) * 6.0; // residual < min item size is dead space
        }
    }

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if (pr - nxt).abs() < 0.5 {
            score -= 300.0; // chain fit: this placement enables a perfect follow-up
        } else if pr >= nxt {
            // next item fits: reward proportionally to how well it uses the leftover
            let fill = nxt / pr;
            score -= 120.0 * fill;
        } else {
            // next item won't fit here: penalize leaving a large awkward gap
            score += 0.05 * (pr - nxt);
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the average residual.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize wasting a nearly-empty fresh bin when other bins could take the item.
    if bin_residual == bin_capacity {
        score += 40.0 + 0.5 * item_size as f64;
        // But allow opening a new bin late in the stream for large items.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size > 60 && progress > 0.5 {
            score -= 55.0;
        }
    }

    // Prefer concentrating load: fewer open bins is better for equal residuals.
    score += 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squash the dead-space penalty for very small post-residuals.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Penalize creating dead space that is too small for typical future items
    // (unusable slivers), but not dead space large enough to still be useful.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // Placing here would strand a residual too small for the next item
            // while another arrangement could have worked: mild penalty.
            score += 6.0;
        }
    } else {
        // Last item in stream: just minimize wasted space aggressively.
        score += tightness * 20.0;
    }

    // Time horizon: early in the stream, be more willing to keep bins flexible
    // (favor larger post-residuals); late in the stream, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * tightness * 15.0;
    score -= progress * (post_residual as f64) * 0.1;

    // Global state: if many bins are open relative to mean residual, prefer
    // consolidating into bins with below-average residual (tighter bins).
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / mean_residual;
        score += (rel - 1.0) * 8.0;
    }

    // New-bin candidate: only attractive when nothing fits well. Make an empty
    // bin moderately unattractive by default so existing bins are used, but
    // let it win when the current bin would leave a bad residual relative to
    // the next item.
    if bin_residual == bin_capacity {
        let base = 35.0 + 0.15 * open_bins_count as f64;
        let lookahead_penalty = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 10.0 };
        score = base + lookahead_penalty + (post_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, non-linearly warped by stream progress.
    let mut score = pr * (1.0 + 0.6 * progress * norm_pr);

    // Smooth polynomial coupling: prefer post-residuals that match typical future need.
    let next_w = if next_item_size > 0 { next_item_size as f64 } else { cap * 0.5 };
    let mismatch = (pr - next_w) / cap;
    score += 8.0 * mismatch * mismatch * (0.5 + progress);

    // Penalize dead space quadratically as stream progresses.
    score += 12.0 * norm_pr * norm_pr * progress;

    // Reward tight fits (small post_residual) with cubic bonus.
    score -= 6.0 * (1.0 - norm_pr).powi(3) * (1.0 - progress);

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Crowding pressure: with many open bins, discourage spreading; favor filling.
    let crowd = open_bins_count as f64 / (1.0 + open_bins_count as f64);
    score += crowd * (mean_residual - pr) * 0.3;

    // New-bin candidate: penalize mildly so it only wins when fits are terrible.
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets (integer division thresholds).
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // 0..1

    // Penalize dead space in low-value harmonic classes.
    // Class 0: post_residual == 0 -> perfect fit, strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Integer division thresholds on post_residual: classes of size 10.
        let class = (post_residual / 10) as f64;
        // Smaller class (less leftover) is better; add quadratic dead-space penalty.
        score += 0.35 * (class as f64) * (class as f64) * 0.1;

        // Items <= 25 are "harmonic fillers": leftover divisible by small item
        // classes is reusable. Reward when next item fits post residual exactly.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0;
            if post_residual % next_item_size == 0 {
                score -= 8.0; // exact modular harmony: next item seals the bin
            }
        } else if next_item_size > 0 {
            // Next item cannot use leftover: leftover likely dead space.
            score += 10.0;
            // Extra penalty if leftover falls in awkward class (1..=9).
            if post_residual < 10 {
                score += 12.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    // and many bins are open (fragmented state).
    if bin_residual == bin_capacity {
        score += 15.0;
        // Allow new bin late in stream or when mean residual is tiny.
        if mean_residual < 8.0 || (total_items > 0 && step_index as f64 / total_items as f64 > 0.85) {
            score -= 20.0;
        }
    }

    // Mild pressure against accumulating many open bins.
    score += 0.05 * open_bins_count as f64;

    // Reward tight fits via capacity-fraction coupling.
    score -= 10.0 * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    // A residual below the smallest possible item (1) is impossible, but very
    // small residuals (< 10) are likely dead space in most streams.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 40.0 * (dead_threshold - post_residual as f64);
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Coupling: dead-space penalty grows as more bins are open (bin pressure).
    let pressure = (open_bins_count as f64).sqrt() * 3.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += pressure;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the gap -> dead space likely.
        score += 12.0;
    }

    // New-bin candidate adjustment: opening a new bin is only attractive when
    // current bins are mostly full / few fitting options exist.
    if bin_residual == bin_capacity {
        score += 5.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits the post residual exactly or well
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 300.0 / (1.0 + gap);
        if gap == 0.0 {
            score -= 500.0; // chain of two perfect fits
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // next item won't fit: penalize dead space proportionally
        let waste = post_residual as f64;
        score += 0.5 * waste;
        // extra penalty if dead space is small and unusable
        if waste < 10.0 {
            score += 50.0;
        }
    }

    // Compare post residual against mean residual: prefer bins left tighter than average
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Last chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when a decent fit exists elsewhere
    if bin_residual == bin_capacity {
        score += 80.0;
        // new bin is fine if lookahead chains well
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0;
        }
    }

    // Late in stream: prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0 * (bin_residual - post_residual) as f64 / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) non-linearly.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) * 0.02;

    // Last chance: strongly favor using this bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when a decent fit exists among open bins.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64;
        let tight_fit = post_residual as f64 <= 5.0;
        if fitting_bins_count >= 1 && !tight_fit {
            score += 15.0 + 2.0 * crowding;
        }
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // dead space for the known next item
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Prefer bins below mean residual (consolidate waste).
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Slight preference for fuller bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - bin_residual) as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post-residual (dead space), scaled by progress
    let mut score = norm_pr * (1.0 + 1.5 * progress) + 0.8 * norm_pr * norm_pr;

    // Smooth non-linear coupling: residual vs stream progress polynomial
    let coupling = norm_pr * (progress * progress) * (1.0 - progress) * 4.0;
    score += coupling;

    // Reward tight fits (small post_residual) more strongly mid-stream
    let tightness = 1.0 - norm_pr;
    score -= 2.0 * tightness * tightness * (1.0 - progress);

    // Penalize when this bin's residual deviates from mean residual (smooth)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.4 * dev * dev.abs();

    // Last-chance bonus: if only this bin fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 3.0;
    } else {
        // mild penalty spread over many fitting bins to prefer consolidation
        score += (fitting_bins_count as f64).ln().max(0.0) * 0.2 * norm_pr;
    }

    // Lookahead: reward if next item fits into post-residual
    if next_item_size > 0 {
        let fits_next = (pr >= next_item_size as f64) as i32 as f64;
        let slack = (pr - next_item_size as f64).max(0.0) / cap;
        score -= 1.2 * fits_next * (1.0 - slack * slack);
    }

    // New-bin candidate: mild preference early, discourage late unless very bad fits
    if bin_residual == bin_capacity {
        score += 0.5 - 1.0 * progress;
        score += 0.3 * open_bins_count as f64 * progress;
    }

    // Open-bin count pressure: encourage filling existing bins when many are open
    score += 0.05 * (open_bins_count as f64).ln() * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are nearly closed; reward tight fits.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // capacity fraction remaining after placement

    // Tight fit reward: strongly favor small post residuals.
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 25.0; // near-perfect, dead space unlikely usable
    } else if post_residual <= 25 {
        score -= 12.0;
    }

    // Dead-space penalty: residues that no future item (min size 1) can
    // efficiently use are penalized via a convex blow-up on tiny fractions.
    if frac > 0.0 && frac < 0.10 {
        score += (0.10 - frac) * 80.0;
    }

    // Harmonic class matching: if the next item fits exactly into the
    // post residual (same residue class modulo the residual itself),
    // reward heavily — this bin chains perfectly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            // reward small chained leftover, harmonic-class style
            let cls = next_post % 10;
            score -= (10 - cls) as f64 * 1.5;
            if next_post == 0 { score -= 20.0; }
        } else {
            // next item cannot use this bin's leftover: penalize large
            // stranded residuals more when stream is late.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += frac * 20.0 * (0.5 + progress);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, using it avoids
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when current residual is very small (bad fit) and many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins mildly; let poor existing fits override it.
        score += 18.0 - 8.0 * progress;
        // If the item is huge relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.8 * cap {
            score -= 10.0;
        }
        // Few open bins: prefer reusing existing capacity.
        if open_bins_count <= 2 {
            score += 10.0;
        }
    }

    // Mild pressure toward bins below the mean residual (keeps balance
    // and closes fuller bins first).
    score -= (mean_residual - post).clamp(-30.0, 30.0) * 0.3;

    // Integer-division threshold: residues in the "half-capacity harmonic"
    // band (post_residual in (cap/2, cap)) are flexible; slight reward.
    if post_residual > bin_capacity / 2 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit reward: item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= (fill_ratio - 0.5) * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If post-residual cannot fit the next item and is small, penalize.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 6.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // and make the new-bin candidate less attractive.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize, scaled by open bins and stream progress.
        score += 30.0 + open_bins_count as f64 * 3.0 + progress * 40.0;
        // But if the item is huge and mean residual is low, opening may be fine.
        if item_size as f64 > mean_residual {
            score -= 20.0;
        }
    } else {
        // Filling existing bins is rewarded more when many bins are open.
        score -= open_bins_count as f64 * 1.5;
    }

    // Mean residual coupling: prefer bins below the mean residual (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: post_residual == next_item_size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // next item could still fit here later; mild penalty for wasted space
            score += gap * 0.3;
        } else {
            // next item won't fit in the leftover; penalize dead space proportionally
            score += gap * 0.6;
        }
    }

    // Prefer bins whose residual is below mean (tight bins), penalize loose bins
    score += (mean_residual - bin_residual as f64) * 0.25;

    // Last-chance bin: if only this bin fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's the only option
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Late in the stream, opening new bins is cheaper than fragmenting
        let penalty = if next_item_size > 0 && next_item_size >= bin_residual {
            -10.0 // lookahead item needs a fresh bin anyway
        } else {
            40.0 + 30.0 * (1.0 - progress)
        };
        score += penalty;
    }

    // Slight preference for filling larger items into bins with small residual
    score += (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual quadratically.
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + 0.2 * next_item_size as f64;
        } else if next_item_size == post_residual {
            score -= 40.0;
        } else {
            // Next item won't fit here; slight penalty if it leaves awkward residue.
            score += 3.0;
        }
    }

    // Prefer bins with below-mean residual (tighter bins get priority).
    score += 0.15 * (bin_residual as f64 - mean_residual).max(0.0);
    score -= 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    // New-bin candidate: only attractive when fit is terrible or few bins fit.
    if bin_residual == bin_capacity {
        let waste = bin_capacity - item_size;
        if waste > 40 && fitting_bins_count > 0 {
            // Opening new bin is fine for small items into fresh bin.
            score -= 5.0;
        } else {
            // Discourage opening new bin when reasonable fits exist.
            score += 25.0 + 0.3 * open_bins_count as f64;
        }
    }

    // Late in stream: consolidate, avoid opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        score += 15.0 * progress;
    }

    // Slight preference for filling larger residual bins when item is big.
    if item_size > bin_capacity / 2 {
        score -= 0.1 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let t = pr / cap; // normalized residual fill
    let p = progress;
    // Early stream: prefer tight fits (low post_residual). Late stream: tolerate larger residuals
    // since consolidation matters more than perfect fits.
    let coupling = t * t * (1.0 - p) * 40.0 - t * p * 25.0 + t * t * t * p * 15.0;
    score += coupling;

    // Reward near-perfect fits, more strongly as the stream progresses.
    let perfect = (t * (1.0 - t) * 4.0).clamp(0.0, 1.0); // peaks at t=0.5
    score -= perfect * (5.0 + 20.0 * p);

    // Lookahead: penalize leaving residual that cannot fit the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (0.5 + 0.5 * p);
        } else {
            // reward leaving room exactly for the next item
            score -= (1.0 - ((pr - nxt) / cap).abs()) * 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mild pressure to use existing bins when many are open.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Penalize bins whose residual deviates far from the mean (fragmentation).
    score += (pr - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that can still host
    // common small items (multiples of 10, 20, 25) are valuable.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Penalize "dead" residuals that are too small for the smallest item (1..100 range, but
    // practically items >= 10 in classic streams): anything below 10 is nearly unusable.
    if post_residual < 10 {
        score += 50.0;
    }

    // Reward residuals that are exact harmonic divisions of capacity
    for &h in &[100u32, 50, 33, 25, 20, 10] {
        if post_residual == h {
            score -= 8.0;
            break;
        }
    }
    // Reward residuals that are multiples of 10 (harmonic grid)
    if post_residual % 10 == 0 {
        score -= 4.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item still fits: mildly reward, more if post_residual - next_item is on grid
        let after_next = post_residual - next_item_size;
        score -= 3.0;
        if after_next % 10 == 0 { score -= 3.0; }
        if after_next == 0 { score -= 10.0; }
    } else if next_item_size > post_residual {
        // next item cannot use this bin's leftover: penalize large leftovers
        score += 0.1 * (post - 10.0).max(0.0);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has large post_residual; only prefer it
    // when no open bin fits (fitting_bins_count == 0) or the fit is terrible.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else {
            // opening a new bin wastes the residual of existing bins; penalize
            score += 12.0 + 0.15 * mean_residual;
        }
    }

    // Prefer tighter fits: small post_residual relative to item size is good (best-fit core),
    // but only when it stays above the dead-space threshold.
    if post_residual >= 10 {
        score -= 0.05 * (item_size as f64);
    }

    // Coupling with mean residual: if this bin's post-residual is far below the mean,
    // we are consolidating bins well.
    score -= 0.05 * (mean_residual - post).max(0.0);

    // Late in the stream, slightly prefer filling existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space strongly (non-linear).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Zero waste is excellent.
    if post_residual == 0 {
        score -= 30.0;
    }
    // If the next item fits the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize leaving a gap that can hold nothing realistic.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 15.0;
    }
    // Pressure from number of open bins: prefer filling existing bins when many are open.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }
    // New empty bin candidate: penalize unless residuals elsewhere are hopeless.
    if bin_residual == bin_capacity {
        score += 40.0;
        // But if the item is large and mean residual is small, opening a new bin is fine.
        if item_size as f64 > mean_residual {
            score -= 45.0;
        }
    }
    // Prefer bins with below-mean residual (tighter fill).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small dead space) non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * fit_ratio * fit_ratio;

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // 2-step lookahead: if the next item fits perfectly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score += gap * 0.3; // mild penalty for leftover after next item
        } else {
            // next item cannot fit here: this residual may become dead space
            score += 8.0;
        }
    }

    // Relative to mean residual: prefer bins with residual above mean (keeps small bins for small items)
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when a reasonable fit exists in an open bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let best_possible = post_residual as f64; // = capacity - item_size
        // new bin is attractive only if no open bin fits, or fit would be very wasteful
        if fitting_bins_count > 0 {
            let waste_threshold = 0.35 * bin_capacity as f64;
            if best_possible < waste_threshold {
                score += 40.0; // discourage new bin for decent fits
            } else {
                score -= 5.0; // allow new bin for very wasteful fits
            }
        } else {
            score -= 20.0; // must open a new bin
        }
    }

    // Late in stream: consolidate, avoid spreading across many bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Penalize dead space that no plausible future item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny slivers are usually wasted
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this bin becomes a chain of two perfect placements.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            let next_leftover = post_residual - next_item_size;
            score -= 60.0 * (1.0 - next_leftover as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here anyway; mild penalty for hoarding space
            score += 15.0;
        }
    }

    // Tightness ratio: prefer bins where the item fills a large fraction.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 50.0 * fill_ratio * fill_ratio;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling: opening a new bin is fine early or when many
    // bins are open and mean residual is small (fragmented state).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        let fragmentation = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let new_bin_bias = 30.0 + 120.0 * fragmentation + 60.0 * (1.0 - progress);
        score += new_bin_bias;
        // Perfect fits elsewhere should always beat a new bin.
        if post_residual == 0 { score -= 500.0; }
    }

    // Global pressure: when many open bins exist, prefer consolidating into
    // bins with below-average residual (tighter bins).
    if open_bins_count > 1 {
        let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 25.0 * rel;
    }

    // Late in the stream, waste matters more; push toward minimal post-residual.
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: f64, fitting_bins_count: usize) -> f64 {
