pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (<10) are almost unusable -> heavy penalty
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward very tight fits (perfect or near-perfect packing)
    if post_residual == 0 {
        score -= 100.0;
    } else if item_size >= bin_residual {
        // should not happen, but guard
        score += 1000.0;
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_residual as f64);
        score -= 40.0 * tightness;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing bins over new ones
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * (open_bins_count as f64).ln().max(0.0);
    score += 5.0 * progress;

    // Prefer bins whose residual deviates from the mean (consolidate fragmentation)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.3 * dev;

    // Lookahead: if next item fits in the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // If next item would leave this bin's gap even more useless, penalize slightly
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 15 {
        score += 20.0;
    }

    // New-bin candidate: empty bin baseline; open a new bin only when existing bins
    // would create bad dead space. Neutral base slightly above good fits.
    if bin_residual == bin_capacity {
        score = 70.0 + 3.0 * (open_bins_count as f64).ln().max(0.0) - 10.0 * progress;
        if fitting_bins_count == 1 {
            // an open bin exists that is the only fit -> never open new bin
            score += 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: bin closes completely
        } else if next_item_size <= post_residual {
            // next item fits; reward proportionally to how well it uses the leftover
            let chain_fill = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 40.0 * chain_fill;
        } else {
            // next item cannot use this bin's leftover: penalize dead space
            let waste = (next_item_size - post_residual) as f64;
            score += 0.25 * waste;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins that are fuller than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // bins are mostly full and the item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fullness = 1.0 - mean_residual / bin_capacity as f64;
        // new bins are attractive only when open bins are quite full
        score += 20.0 + 40.0 * (1.0 - avg_fullness) - 10.0 * progress;
        if item_size >= 60 {
            score -= 15.0; // large items deserve fresh space
        }
        // if next item is large, a fresh bin can host it well
        if next_item_size >= 60 {
            score -= 10.0;
        }
    } else {
        // slight penalty for spreading across many bins
        score += 0.1 * open_bins_count as f64;
    }

    // Penalize very small unusable leftovers (dead space 1..=5)
    if post_residual > 0 && post_residual <= 5 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already low, amplify it.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space (small but non-zero post_residual).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual,
    // strongly reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // If next item would fit in post_residual, mild bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }
    // If next item would NOT fit in post_residual and post_residual is
    // small, the dead space is acceptable (bin is nearly full anyway).
    if next_item_size > 0 && next_item_size > post_residual && post_residual <= 12 {
        score -= 6.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate logic: empty bin should lose unless all open bins
    // are poor fits. Penalize the empty bin mildly by default.
    if bin_residual == bin_capacity {
        // Base penalty so open bins win when they fit reasonably well.
        score += 18.0;
        // But if open bins are all nearly full (high mean residual means
        // lots of free space? No: mean_residual is free space), adjust:
        // small mean_residual => open bins are congested => new bin OK.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (mean_residual / bin_capacity as f64) * 10.0;
        // Late in the stream, prefer consolidating into open bins.
        score += progress * 8.0;
        // If many open bins exist, slight preference to reuse them.
        score += (open_bins_count as f64).ln().max(0.0) * 2.0;
        // If the item is huge relative to residual of typical bins,
        // opening fresh is safer: reward when item is large.
        if item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // Prefer bins with residual already below the mean (fill congested bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap; // normalized post residual

    let mut score = post;

    // Non-linear polynomial coupling of post residual with stream progress
    let poly = pr * pr * (1.0 + progress) + pr * pr * pr * (2.0 * progress);
    score += 40.0 * poly;

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - pr) * (1.0 - pr) * (10.0 + 30.0 * progress);

    // Penalize dead space relative to mean residual (smooth quadratic)
    let dead = (post - mean_residual) / cap;
    score += 15.0 * dead * dead;

    // Last-chance bonus: smooth function of fitting bins count
    if fitting_bins_count <= 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward leaving room for next item (smooth hinge)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = post - n;
        if gap >= 0.0 {
            score -= 12.0 * (1.0 - gap / cap) * (0.5 + progress);
        } else {
            score += 8.0 * (-gap / cap) * (1.0 + progress);
        }
    }

    // Mild penalty for bin proliferation, ramping with progress
    score += (open_bins_count as f64).ln() * (2.0 + 6.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: residuals that are near-useless get penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: residual too small for typical items (<= 10) is wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Perfect fit reward: strong bonus for exact or near-exact fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Harmonic class: classify post_residual by capacity fraction bands (eighths).
    let band = (pr / (cap / 8.0)).floor() as i32; // 0..8
    score -= 6.0 * (band as f64); // prefer leaving larger, more reusable residuals

    // Modulo arithmetic: residuals that are multiples of common item sizes are valuable.
    let mod_penalty = |r: u32| -> f64 {
        let mut pen = 0.0;
        for m in [10u32, 20, 25, 50] {
            if r % m == 0 && r > 0 {
                pen -= 8.0;
            }
        }
        pen
    };
    score += mod_penalty(post_residual);

    // Integer division threshold on next_item_size: does the next item fit this residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits: reward, scaled by how well it nests (harmonic pairing).
            let nest = (next_item_size as f64) / (post_residual as f64);
            score -= 30.0 * nest;
        } else {
            // Next item won't fit: penalize leaving a residual that traps the stream.
            score += 12.0;
        }
        // Harmonic divisibility: post_residual divisible by next item size is excellent.
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 25.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate handling: empty bins should only win when existing residuals are poor.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * mean_residual;
        // Late in the stream, opening new bins is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
    }

    // Mean residual coupling: when open bins are on average full, discourage spreading.
    if mean_residual < (item_size as f64) {
        score += 10.0;
    }

    // Mild preference for tighter bins when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (1..=10) are the worst outcome.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 20.0;
    }

    // Reward perfect and near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // allow opening new bins for large items.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    score += pressure;

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64 / 10.0).min(8.0);
    }

    // Slight preference to fill bins below mean residual (balance toward
    // consolidating residual space).
    score += 0.15 * (mean_residual - post_residual as f64);

    // Progress: late in the stream, be more conservative about opening bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match for next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - slack.min(60.0); // perfect fit for next item => big reward
        if slack == 0.0 {
            score -= 40.0; // exact 2-step match: extremely desirable
        }
    } else if next_item_size > 0 {
        // next item cannot fit here; penalize dead space relative to next item
        score += 15.0 + (next_item_size as f64 - post_residual as f64) * 0.3;
    }

    // Compare post_residual against mean residual: leaving less than mean wastes capacity
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.25;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: penalize unless current bins are very full / poor fits
    if bin_residual == bin_capacity {
        let tight = mean_residual < item_size as f64 * 0.5;
        if tight {
            score -= 20.0; // open new bin when existing residuals are tight
        } else {
            score += 30.0; // discourage wasting a fresh bin
        }
    }

    // Slight preference for fuller bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - post_residual) as f64 * 0.1 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with quadratic waste penalty.
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Reward near-perfect fits strongly.
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item can use the post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 0.5 * next_item_size as f64;
        } else {
            // Dead space for the known next item: penalize proportionally to mismatch.
            score += 0.6 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Global state: penalize placements that leave residuals far from the mean
    // (fragmentation of the bin pool), scaled by how many bins are open.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev * (1.0 + (open_bins_count as f64).ln().max(0.0));

    // Time horizon: early in the stream, be more willing to spread items (open bins),
    // late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty so it only wins when fits are poor.
        score += 30.0;
        // Early stream: opening bins is cheaper; late stream: expensive.
        score += 40.0 * progress;
        // If next item is large, a fresh bin is attractive for future pairing.
        if next_item_size > item_size {
            score -= 0.4 * (next_item_size - item_size) as f64;
        }
        // If no open bin fits well (post_residual of best fit would be big), new bin wins naturally.
    } else {
        // Existing bin: slight reward when bins are few (consolidation), penalty when many.
        score -= 2.0 * (1.0 - progress);
    }

    // Prefer filling larger residuals when item is large (avoid stranding big holes).
    if item_size > bin_capacity / 2 {
        score += 0.1 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = norm_post * (1.0 + 0.8 * progress + 0.6 * p2 + 0.4 * p3);

    let mut score = coupling * 100.0;

    // Reward tight fits (low post residual) with smooth falloff
    let tightness = 1.0 - norm_post;
    score -= 40.0 * tightness * tightness * (1.0 + 0.5 * progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 25.0 * (nxt - post) / cap * (1.0 + progress);
        } else {
            // Reward leaving exactly enough room for the next item
            let match_term = 1.0 - (post - nxt) / cap;
            score -= 15.0 * match_term * match_term;
        }
    }

    // Last-chance bonus: only one fitting bin, avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Mild penalty when bin diverges from mean residual (balance load)
    score += 0.05 * (post - mean_residual).abs();

    // Slight preference for using existing bins as stream progresses
    score -= 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: classify post_residual by integer division into residue bands
    // Classes: 0 (perfect fill), tiny (1..=5), small (6..=15), medium (16..=30), large (>30)
    let class: f64 = if post_residual == 0 {
        -40.0 // perfect fit, strongly favored
    } else if post_residual <= 5 {
        2.0
    } else if post_residual <= 15 {
        6.0
    } else if post_residual <= 30 {
        12.0
    } else {
        18.0
    };
    score += class;

    // Harmonic bonus: post_residual divisible by common item sizes (10, 20, 25, 50)
    // means the leftover can be exactly filled by a future item.
    let harmonic = (post_residual % 10 == 0) as f64 * 4.0
        + (post_residual % 20 == 0) as f64 * 3.0
        + (post_residual % 25 == 0) as f64 * 3.0
        + (post_residual % 50 == 0) as f64 * 2.0;
    score -= harmonic;

    // Lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // partial compatibility, penalize leftover after hypothetical next placement
            let after_next = post_residual - next_item_size;
            score += after_next as f64 * 0.3;
            if after_next % 10 == 0 { score -= 2.0; }
        } else {
            // next item cannot use this residual: penalize proportional to waste
            score += (post_residual as f64 - next_item_size as f64).abs() * 0.05;
        }
    } else {
        // last item: prefer tightest fill
        score -= 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is bad
    if bin_residual == bin_capacity {
        // fresh bin: base cost, discounted when the current bin fit is poor
        score += 15.0;
        if post_residual as f64 > mean_residual {
            score -= 10.0;
        }
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer bins below mean residual (consolidate waste into fewer bins)
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Many open bins: tighten selection pressure
    score += open_bins_count as f64 * 0.02;

    // Small tie-breaker favoring fuller bins
    score += (bin_capacity - bin_residual) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty for unusable dead space: gaps too small for the minimum item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10.0 - post_residual as f64) * 6.0;
    }
    // Moderate penalty for small-ish gaps that few future items can use.
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Perfect-fit lookahead: if the next item exactly consumes the post residual.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 55.0;
    }
    // Penalize if next item cannot fit in the post residual but could elsewhere.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 8.0;
    }

    // Last-chance bonus: only this bin can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is tight.
    let tightness = item_size as f64 / bin_residual as f64;
    score += open_bins_count as f64 * 3.0 * (1.0 - tightness);

    // Mean-residual coupling: prefer bins deviating favorably from the mean.
    score += 0.35 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: fresh bin should only win when no open bin gives a tight fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.75 + open_bins_count as f64 * 2.0;
        // Large items prefer a fresh bin to avoid fragmentation.
        if item_size >= 60 {
            score -= 30.0;
        }
        // If only the new bin fits, it must be chosen.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: strongly reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step chain: bin filled exactly next turn
        } else if post_residual > next_item_size {
            // slack left after the lookahead item would also fit; mildly reward
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - slack * 0.3;
        } else {
            // next item cannot use the post residual: penalize proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Penalize dead space that is too small to ever hold an item (min size ~1..=10 typical floor)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Perfect fit reward (bin closed completely)
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a poor fit.
    if bin_residual == bin_capacity {
        // Opening new bin is only attractive when mean residual across open bins is tight
        // (i.e., existing bins are nearly full) or nothing fits well.
        score += 45.0 - mean_residual * 0.4;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0; // fresh bin guarantees room for lookahead item
        }
    }

    // Compare against mean residual: bins with residual far below mean are scarcer,
    // filling them is more valuable.
    let dev = mean_residual - bin_residual as f64;
    score -= dev * 0.15;

    // Early in the stream, be slightly more conservative about wasting space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * (1.0 - progress);

    // Slight penalty when many bins are open (encourage consolidation)
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: penalize residual that cannot host the next item (dead space),
    // reward residual that exactly or comfortably hosts it.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // dead space relative to lookahead
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        } else if next_item_size == post_residual {
            // chain fit: excellent
            score -= 12.0;
        } else {
            let slack = (post_residual - next_item_size) as f64;
            score += 0.10 * slack;
        }
    }

    // Last-chance bin: strongly prefer filling it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Tightness relative to capacity: prefer bins that end up tight
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 6.0 * tightness * tightness;

    // Prefer bins with residuals below the mean (consolidate large holes),
    // penalize dumping items into already-large-residual bins.
    score += 0.25 * (mean_residual - bin_residual as f64).abs()
        * if (bin_residual as f64) > mean_residual { 1.0 } else { 0.5 };

    // Time horizon: late in the stream, be greedier (minimize post_residual harder);
    // early on, allow spreading to keep flexibility.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    // New-bin candidate: only attractive when it yields a very tight fit
    // (e.g. large item into empty bin) or when no good open bin exists.
    if bin_residual == bin_capacity {
        // baseline penalty for opening a new bin
        score += 15.0;
        // but large items justify a fresh bin (avoid fragmenting open bins)
        if item_size >= 60 {
            score -= 20.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && item_size + next_item_size >= 90 {
            score -= 10.0; // planned two-item packing in fresh bin
        }
    }

    // Many open bins: discourage opening yet another one
    score += 0.4 * open_bins_count as f64 * if bin_residual == bin_capacity { 1.0 } else { 0.0 };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (low post-residual), with non-linear shaping.
    let mut score = pr;

    // Smooth polynomial coupling of post-residual with stream progress:
    // early on, larger residuals are tolerated; late in the stream, punish waste harder.
    let waste_penalty = pr_norm * pr_norm * (0.5 + 2.0 * progress) * cap * 0.5;
    score += waste_penalty;

    // Non-linear reward for filling a bin nearly completely, amplified as stream progresses.
    let fill = 1.0 - pr_norm;
    score -= fill * fill * fill * (10.0 + 30.0 * progress);

    // Penalize dead space that cannot fit the lookahead item (smooth coupling).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).max(0.0) / cap;
        score += gap * gap * nxt * (0.5 + progress);
        // Reward leaving exactly enough room for the next item.
        let fit_next = if pr >= nxt { 1.0 - (pr - nxt) / cap } else { 0.0 };
        score -= fit_next * fit_next * 8.0 * (1.0 - progress);
    }

    // Last-chance bonus: smooth reward when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - pr_norm * pr_norm);
    } else {
        // Mild penalty when many bins compete, favoring consolidation.
        score += (fitting_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Prefer bins below mean residual slightly (balance load), non-linearly.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 5.0 * (1.0 - progress);

    // New-bin candidate: make empty-bin score depend on stream state.
    if bin_residual == bin_capacity {
        // Early: opening bins is fine; late: discourage unless item is huge relative to residuals.
        let size_frac = item_size as f64 / cap;
        let residual_pressure = mean_residual / cap;
        score = cap * (0.9 - 0.4 * progress)
            - size_frac * size_frac * 40.0 * progress
            + residual_pressure * 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residue modulo 10
    let residue_class = post_residual % 10;

    // Penalize residuals in awkward classes (dead space that few item sizes can use)
    match residue_class {
        0 => { score -= 12.0; }               // perfectly divisible residual is excellent
        1 | 2 | 3 => { score += 6.0; }        // tiny slivers are near-useless
        4 | 5 | 6 => { score += 1.0; }        // medium slivers, mildly bad
        7 | 8 | 9 => { score += 3.0; }        // awkward but sometimes fillable
        _ => {}
    }

    // Integer-division threshold on post_residual: reward residuals that can host
    // a "harmonic" chunk (multiples of 25 or 50)
    if post_residual >= 50 {
        score -= 8.0;
    } else if post_residual >= 25 {
        score -= 3.0;
    } else if post_residual > 0 {
        score += 4.0;
    }

    // Lookahead coupling: does the next item fit exactly or harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;                    // perfect follow-up fit
        } else if next_item_size <= post_residual {
            let diff = post_residual - next_item_size;
            if diff % 10 == 0 {
                score -= 6.0;                 // harmonic alignment with next item
            } else {
                score += (diff % 10) as f64;  // penalize non-aligned leftover
            }
        } else {
            score += 5.0;                     // next item won't fit here
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Penalize opening new bins mildly; more when many bins already open
        score += 18.0 + open_bins_count as f64 * 0.8 - fragmentation * 0.5 - progress * 5.0;
        // If next item is large, a fresh bin is more attractive
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Tight fit reward: small post_residual relative to item means efficient packing
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 6.0;

    // Mean residual coupling: prefer bins below mean residual (denser bins)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item are worthless — penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize "awkward" gaps unlikely to fit a typical next item.
    if post_residual > 0 {
        if (next_item_size > 0 && post_residual < next_item_size) || next_item_size == 0 {
            score += 12.0;
        }
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 8.0 * fill_ratio;
    }

    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (0.5 + progress);

    // Mean residual coupling: prefer bins whose residual is below average
    // (already partially filled), to keep large residuals available.
    if bin_residual as f64 > mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_util = next_item_size as f64 / post_residual as f64;
        score -= 10.0 * gap_util;
    }

    // New-bin candidate: opening a new bin is only attractive when current
    // fits are poor. Base cost plus scaling with number of open bins.
    if bin_residual == bin_capacity {
        score += 45.0 + 2.0 * open_bins_count as f64;
        // But if the next item is large and current residual barely fits
        // the current item, a fresh bin keeps flexibility.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 + 0.5 * next_item_size as f64;
        // Exact match of post_residual to next item is ideal
        if post_residual == next_item_size {
            score -= 120.0;
        }
    } else if next_item_size > 0 {
        // Penalize dead space that next item cannot use
        score += 0.6 * post_residual as f64;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        score += 150.0;
        // But allow new bin if it would create a chain with next item
        if next_item_size > 0 && bin_capacity - item_size >= next_item_size {
            score -= 100.0;
        }
    }

    // Late in stream: consolidate, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 100.0 * progress;
    } else {
        score -= 50.0 * progress;
    }

    // Mild penalty on many open bins to encourage closing them out
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 30.0;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: if next item fits in the post residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // Placing here would destroy room for the next item.
            score += 15.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Prefer bins below mean residual (keep residuals balanced).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Slight preference for opening new bins early in the stream vs. late.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New bin candidate: cheap early, expensive late.
        score -= (1.0 - progress) * 20.0;
        // But if existing fit is very tight, don't open a new bin.
        if fitting_bins_count > 0 && post_residual < 5 {
            score += 50.0;
        }
    }

    // Many open bins: encourage consolidation into existing bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;
    // Smooth polynomial coupling: post_residual penalized more as stream progresses
    let pr = post_residual as f64;
    let norm = pr / bin_capacity as f64;
    score += progress * pr * norm * 2.0;
    // Reward tight fits smoothly
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * fit_ratio * 10.0;
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * progress;
    }
    // Penalize bins far from mean residual (fragmentation)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev * dev / bin_capacity as f64;
    // Lookahead: favor bins leaving room for next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.02 * gap * (1.0 - progress);
    }
    // New bin candidate: prefer opening new bins for large items or late stream
    if bin_residual == bin_capacity {
        score += 5.0 - 30.0 * progress;
        if item_size > bin_capacity / 2 { score -= 10.0; }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let remainder_class = post_residual % (bin_capacity / 10).max(1); // class of size 10
    let half_class = post_residual % (bin_capacity / 2).max(1);

    // Dead space penalty: residuals that can't hold typical small items
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // unusable sliver
    }

    // Reward residuals that are multiples of 10 (harmonic with item granularity)
    if remainder_class == 0 && post_residual > 0 {
        score -= 15.0;
    }
    if half_class == 0 {
        score -= 10.0;
    }

    // Lookahead coupling: does post_residual fit the next item harmonically?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 20.0;
            if slack % (bin_capacity / 10).max(1) == 0 {
                score -= 10.0;
            }
            if slack == 0 {
                score -= 60.0; // chain perfect fit
            }
        } else {
            score += 25.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // prefer new bin when item is large relative to mean residual
        let poor_fit = (item_size as f64) > mean_residual * 0.9;
        if poor_fit && open_bins_count > 2 {
            score -= 30.0 * progress;
        } else {
            score += 45.0;
        }
    }

    // Prefer tighter (fuller) bins: penalize bins with residual far above item size
    let waste = (bin_residual - item_size) as f64;
    score += 0.3 * (waste - pr).abs() * 0.0; // neutralized coupling
    score += 0.05 * (open_bins_count as f64);

    // Integer division threshold on post_residual: bucketize
    let bucket = post_residual / (bin_capacity / 4).max(1);
    score += bucket as f64 * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space harshly (post_residual in (0, 10))
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Reward zero residual (perfect fit)
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead-space penalty: small gaps that next item cannot use
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Open bins pressure: favor filling existing bins when many are open
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize bins far below mean residual (fragmented usage) mildly
    score += (mean_residual - bin_residual as f64) * 0.1;

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 50.0;
        } else {
            score += 35.0 + mean_residual * 0.2;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits (low dead space)
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 5 {
        score -= 25.0;
    }

    // 2-step lookahead: strongly reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + diff);

        // Exact chain match: item then next item perfectly fills the bin
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving a sliver that no future item (min size 1..) can use well
        if post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 15.0;
        }
    } else {
        // Last item: just minimize waste
        score -= 10.0;
    }

    // Relative to mean residual: prefer bins tighter than average (best-fit style)
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no good fit exists among open bins.
    // Penalize opening a new bin, more so when many bins are open and mean residual is large.
    if bin_residual == bin_capacity {
        score += 45.0 + 3.0 * open_bins_count as f64 + mean_residual * 0.3;
        // But if lookahead would be wasted on a poor existing fit, ease new-bin penalty
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Early in the stream, allow slightly more freedom to open bins (build diverse residuals)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a non-linear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(3) * 40.0;

    // Penalize dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves more waste — mild reward scaled by snugness
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 15.0 * snug;
        } else {
            // next item won't fit here — penalize proportionally to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += over.min(30.0) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Many open bins: encourage consolidation (prefer bins with low residual).
    let mean_gap = (bin_residual as f64 - mean_residual).abs();
    score += mean_gap * 0.15 * (open_bins_count as f64).ln().max(1.0) * 0.3;

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); later, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 8.0; // early: penalize use of open bins slightly
    score -= progress * 10.0;        // late: reward use of open bins

    // New-bin candidate handling: an empty bin gets a baseline score that
    // beats only very poor fits.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.55 + (1.0 - progress) * 5.0;
        // If no other bin fits or the item is large, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post-residual (tight fit), with quadratic sharpening.
    let mut score = post + 40.0 * norm_post * norm_post;

    // Smooth non-linear coupling of residual with stream progress:
    // late in the stream, dead space is more costly, so penalize large residuals more.
    let progress_coupling = norm_post * (1.0 + 2.0 * progress * progress);
    score += 30.0 * progress_coupling;

    // Reward tight fits relative to mean residual: if this bin's post-residual is
    // well below the mean, subtract a smooth bonus.
    let mean_term = (mean_residual - post) / cap;
    score -= 20.0 * mean_term / (1.0 + (-3.0 * mean_term).exp());

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin; smooth via logistic on fitting_bins_count.
    let last_chance = (fitting_bins_count as f64 - 1.0).max(0.0);
    score -= 25.0 / (1.0 + last_chance);

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if next item is larger than post-residual, mild penalty for wasting space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post - nxt) / cap;
        score += 15.0 * diff.abs() * (1.0 - (diff.abs() * 5.0).min(1.0));
        if nxt <= post {
            score -= 10.0 * (1.0 - diff.abs() * 4.0).max(0.0);
        }
    }

    // Mild penalty when many bins are open relative to progress (encourage consolidation).
    let open_norm = open_bins_count as f64 / (total_items.max(1) as f64);
    score += 10.0 * open_norm * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals near multiples of
    // common item sizes are more reusable. Penalize residuals in "dead"
    // classes (small non-reusable remainders).
    let dead_zone = 10u32; // smallest item size; residual < 10 is dead space
    if post_residual < dead_zone {
        score += 40.0 * (dead_zone - post_residual) as f64;
    }

    // Modulo-class reusability: check if post_residual is divisible into
    // plausible chunks (harmonic classes of 10, 20, 25, 50).
    let classes: [u32; 4] = [10, 20, 25, 50];
    let mut best_fit_gap = u32::MAX;
    for &c in classes.iter() {
        let r = post_residual % c;
        if r < best_fit_gap {
            best_fit_gap = r;
        }
    }
    score += 0.8 * best_fit_gap as f64;

    // Perfect harmonic residual gets a strong reward.
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // heavily reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let rem2 = post_residual - next_item_size;
            score -= 8.0;
            if rem2 < dead_zone {
                score += 12.0; // would create dead space after next item
            }
        } else {
            score += 3.0; // next item can't follow here
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; prefer it only
    // when existing bins would waste a lot. Penalize slightly so tight fits win.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.1 * open_bins_count as f64;
    }

    // Progress-aware tightening: late in the stream, be more conservative
    // with residual waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    // Deviation from mean residual: bins far below mean are "tight" fits — good.
    let dev = mean_residual - post_residual as f64;
    score -= 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    if post_residual > 0 {
        if post_residual < 10 {
            // Tiny unusable gap: heavy penalty (dead space).
            score += 45.0;
        } else if post_residual < 25 {
            // Likely only fits the smallest items: moderate penalty.
            score += 18.0;
        } else {
            // Usable residual: reward proportionally.
            score -= (post_residual as f64) * 0.35;
        }
    } else {
        // Perfect fill: massive reward.
        score -= 120.0;
    }

    // Tightness reward: fraction of bin filled by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Next-item lookahead: bonus if the leftover gap can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 12.0; // gap too small for next item: penalize
        }
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into them
    // over opening new ones; penalize the new-bin candidate harder.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty plus pressure.
        score += 25.0 + pressure * 10.0;
        // Allow new bin only when item is huge and nothing else fits well.
        if item_size >= 80 && fitting_bins_count == 0 {
            score -= 80.0;
        }
    } else {
        // Existing bin: slight reward proportional to pressure (favor reuse).
        score -= pressure * 2.0;
    }

    // Mid-stream: slightly prefer keeping residuals near mean (balance).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64 - mean_residual).abs() * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits
    score -= 0.5 * item_size as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post residual exactly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain: two items fill bin
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how much it consumes
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * fill;
        } else {
            // next item does NOT fit this bin's remainder: penalize dead space
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Compare post_residual against mean residual: discourage leaving more slack than average
    score += 0.25 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it over new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Penalize opening a new bin when good open bins exist
    if bin_residual == bin_capacity {
        score += 5.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 3.0; // new bin less attractive if lookahead also large
        }
    }

    // Late in stream: consolidate, avoid leaving many open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 {
        score += 0.1 * open_bins_count as f64;
    }

    // Slight penalty for very small unusable remainders
    if post_residual > 0 && post_residual < 10 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large leftover dead space nonlinearly.
    if post_residual > 0 {
        let pr = post_residual as f64;
        score += (pr / 10.0).powi(2) * 0.35;
    }

    // Reward tight fits (small waste relative to item).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    let waste_ratio = post_residual as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0 * (1.0 - waste_ratio);

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Penalize blocking the next item's only viable fit.
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0);
    }

    // Global state: many open bins with large mean residual -> consolidate.
    if mean_residual > 40.0 && open_bins_count > 4 {
        score -= 0.15 * (mean_residual - 40.0);
    }

    // Time horizon: early in stream, be more willing to open fresh bins;
    // late in stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: prefer early, penalize late.
        score -= 15.0 * (1.0 - progress);
        score += 18.0 * progress;
        // If current bin fits perfectly, never open a new one.
        if post_residual == 0 {
            score += 50.0;
        }
    } else {
        score -= 6.0 * progress;
    }

    // Small post-residuals are nearly perfect fills; give a bonus.
    if post_residual <= 5 && post_residual > 0 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) - norm_pr * progress * 0.5;
    score += 40.0 * poly;
    // penalize residual that is too small to fit the lookahead item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += 25.0 * (ns - pr) / cap + 10.0 * progress;
        } else {
            score -= 8.0 * (1.0 - (pr - ns) / cap) * (1.0 - progress);
        }
    }
    // reward using a bin that is the last chance to fit the item
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }
    // penalize opening new bins when many bins are already open and mean residual is high
    let mean_norm = mean_residual / cap;
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - mean_norm) * (1.0 - progress) + 5.0 * (open_bins_count as f64).ln();
    } else {
        score -= 6.0 * mean_norm * (1.0 - progress);
    }
    // smooth dead-space penalty: quadratic in small residuals
    if pr < 10.0 {
        score -= (10.0 - pr) * (10.0 - pr) * 0.3;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo 10 and modulo 25
    let r10 = post_residual % 10;
    let r25 = post_residual % 25;
    // Dead-space classes: residuals that are tiny but nonzero are the worst
    let tiny = (1..=9).contains(&post_residual);
    if tiny {
        score += 60.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 45.0; // perfect closure
    }

    // Penalize residuals in awkward harmonic bands (not multiples of common item sizes)
    let friendly = (post_residual % 10 == 0) || (post_residual % 20 == 0) || (post_residual % 25 == 0) || (post_residual % 50 == 0);
    if !friendly && post_residual > 0 {
        score += 12.0 + 0.4 * r10 as f64 + 0.2 * r25 as f64;
    }

    // Lookahead: reward if the next item fits exactly or harmonically into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let exact = post_residual == next_item_size;
        let harmonic = (post_residual % next_item_size.max(1)) == 0;
        if exact {
            score -= 40.0;
        } else if harmonic {
            score -= 18.0;
        } else {
            score -= 6.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item won't fit here: mild penalty proportional to mismatch
        score += 4.0 + 0.1 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive only if no open bin fits well
        let poor_fits = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // Base cost of a new bin: its full emptiness, discounted when stream is early
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 95.0 + 20.0 * progress - 25.0 * poor_fits;
        // If current item leaves a friendly residual pattern in this new bin, slight discount
        if friendly && item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Prefer bins whose residual is below average (tighter packing)
    score += 0.15 * (mean_residual - post_residual as f64);

    // Slight preference to fill larger residual bins when many bins are open
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    // A gap is "dead" if it cannot fit even the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Penalize gaps that cannot fit the lookahead item (k=2) when that item
    // would otherwise be stranded.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 18.0;
    }

    // Perfect or near-perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward gaps that exactly accommodate the next item (chain fit).
    if next_item_size > 0 && post_residual == next_item_size as u32 {
        score -= 30.0;
    }

    // Open-bins pressure: mild penalty scaled by number of open bins,
    // discourages spreading items across too many bins.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless dead-space penalty dominates).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    // Opening a new bin is fine for large items but wasteful for small ones.
    if bin_residual == bin_capacity {
        // Penalize new bins when the stream is early/mid and open bins exist,
        // but relax late in the stream (compaction matters less).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 12.0 * (1.0 - progress) + (open_bins_count as f64) * 2.0;
        // Small items into a fresh bin waste capacity.
        if item_size < 30 {
            score += 30.0;
        }
    }

    // Prefer bins tighter than the mean (best-fit bias beyond raw residual).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step lookahead match: post_residual == next_item_size is perfect
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near match: next item fits tightly into the post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 50.0 * tightness;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot use this residual: penalize proportionally to waste
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Penalize small unusable residuals (dead space)
    if post_residual < 10 {
        score += 200.0;
    } else if post_residual < 20 {
        score += 50.0;
    }

    // Reward tight fits relative to the bin's original residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Discourage opening a new bin when decent open bins exist
    if bin_residual == bin_capacity {
        let mean_fit_penalty = (mean_residual - item_size as f64).abs();
        score += 100.0 + 2.0 * mean_fit_penalty + 0.5 * open_bins_count as f64;
    }

    // Mild pressure toward consolidation as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Prefer bins whose residual deviates favorably from mean (larger residual = more usable)
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to item size, the better.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 40.0;
        if post_residual == 0 {
            score -= 20.0;
        }
    }

    // Lookahead coupling: if the next item fits in the post residual, reward it.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 15.0;
        } else if (bin_residual as u32) >= (item_size + next_item_size) {
            // Both items fit here — very desirable.
            score -= 25.0;
        } else {
            // Next item won't fit after placement; mild penalty proportional to waste.
            score += 5.0 * (1.0 - fit_ratio);
        }
    }

    // Global state: when many bins are open with large mean residual,
    // prefer consolidating into existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins have slack or early in stream.
        score += 20.0 + 30.0 * (mean_residual / bin_capacity as f64) + 15.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    } else {
        // Prefer bins whose residual is close to the mean (balance load) slightly.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Mild time-horizon scaling: later in the stream, be greedier about tight fits.
    score *= 1.0 - 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post_residual, with smooth non-linear shaping
    let mut score = post + 30.0 * norm_post * norm_post;

    // Polynomial coupling of post_residual with stream progress:
    // early on, large leftover space is fine; late, it becomes dead weight.
    let progress_coupling = norm_post * (1.0 - norm_post) * (2.0 * progress - 1.0);
    score += 40.0 * progress_coupling * (norm_post - 0.5);

    // Smooth reward when this bin is the last fitting option
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - norm_post * norm_post);
    }

    // Smooth penalty for spreading across many open bins vs mean residual
    let mean_term = (mean_residual - post) / cap;
    score += 8.0 * mean_term * (1.0 + progress);

    // Lookahead: reward if next item can use the post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (post - nxt).max(0.0);
        let match_bonus = if post >= nxt { 1.0 - (post - nxt) / cap } else { 0.0 };
        score -= 15.0 * match_bonus * (fits_next / cap.max(1.0) + 0.5);
    } else {
        // last item: strongly minimize waste
        score += 10.0 * norm_post;
    }

    // Mild pressure toward consolidation when many bins are open
    score += (open_bins_count as f64).ln() * norm_post * 3.0;

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        let large_item_bonus = item_size as f64 / cap;
        score += 20.0 - 25.0 * large_item_bonus * large_item_bonus;
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual modulo capacity fractions
    let pr = post_residual;
    // Residuals that are unusable dead space (too small for any plausible item) are penalized
    if pr > 0 && pr < 10 {
        score += 60.0;
    }
    // Modulo-10 classes: residual divisible by 10 is more reusable
    if pr % 10 == 0 {
        score -= 15.0;
    } else {
        score += (pr % 10) as f64 * 1.5;
    }
    // Integer division thresholds: quarter/half/full capacity zones
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if pr >= half {
        score -= 20.0; // roomy bin remains useful
    } else if pr >= quarter {
        score -= 5.0;
    } else if pr > 0 {
        score += 10.0; // cramped leftover
    }

    // Lookahead: does the next item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 25.0; // chain placement possible
            // exact chain: post_residual equals next item size
            if next_item_size == pr {
                score -= 30.0;
            }
        } else {
            // dead space relative to the known next item
            score += (next_item_size - pr) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: make it moderately attractive only when current bin would be badly fragmented
    if bin_residual == bin_capacity {
        // base neutral value; open new bin when existing bins are congested
        score = cap * 0.5 - (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size > post_residual && item_size > half {
            score -= 30.0; // big item with big next item: fresh bin sensible
        }
    }

    // Slight preference to fill fuller bins (small residual) early in stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.2;

    // Prefer bins below mean residual (filling emptier bins less) -> penalize bins with residual above mean
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (< 10, min item size) are wasted.
    if post_residual < 10 {
        score += 0.0; // gap fully dead anyway; post_residual already small
    } else if post_residual <= 20 {
        // Small residual likely unusable by future items: heavy penalty.
        score += 30.0;
    } else if post_residual <= 35 {
        score += 12.0;
    } else {
        // Larger residuals stay flexible: mild reward.
        score -= 8.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if fill_ratio > 0.7 {
        score -= 15.0 * fill_ratio;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage proliferating bins; but for the new-bin
    // candidate (empty residual == capacity) this pressure is neutralized so
    // it competes fairly only on fit quality.
    if bin_residual != bin_capacity {
        score += (open_bins_count as f64) * 0.5;
        // Prefer bins below mean residual (more filled bins).
        score += (mean_residual - bin_residual as f64) * 0.2;
    } else {
        // New-bin candidate: penalize mildly so it only wins when fits are bad.
        score += 10.0;
        // If lookahead item is large, opening a fresh bin is more attractive.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Late-stream consolidation: as the stream progresses, prefer filling
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    // Lookahead synergy: if next item fits exactly into post_residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this residual: if residual is small, it's dead space.
        if post_residual < next_item_size && post_residual < 25 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if the next item fits into post_residual,
    // this bin is doubly valuable — reward it strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let perfect_chain = (post_residual == next_item_size) as i32 as f64;
        score -= 25.0 + 10.0 * perfect_chain;
    } else if next_item_size > 0 {
        // Penalize leaving residual that next item cannot use (dead space risk),
        // scaled by how close the next item is to fitting.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.15 * gap.min(30.0);
    }

    // Penalize if post_residual is a "hard" residual (small, unlikely to be reused).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer the one whose residual deviates
        // favorably from the mean (keep mean residual usable).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Compare against opening a new bin: a new bin would have residual = capacity.
    // If post_residual is much worse than what a fresh bin would offer relative
    // to the next item, penalize slightly so new-bin opening is competitive
    // only for genuinely poor fits.
    if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_capacity {
        let waste = (next_item_size - post_residual) as f64;
        if waste > 20.0 {
            score += 0.3 * (waste - 20.0);
        }
    }

    // Late in the stream, be slightly more conservative with residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * progress * (post_residual as f64) / 100.0;

    // Mild penalty for spreading across too many open bins.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Dead-space penalty: residuals below the smallest item are unusable
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: penalize if next item can't use the leftover space
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits the leftover: reward tight packing that chains
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 12.0 - 0.15 * chain_waste;
        } else {
            // leftover is dead for the next item: penalize proportionally
            score += 0.3 * (post_residual as f64 - (post_residual as f64 - next_item_size as f64).max(0.0));
            score += 6.0;
        }
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Prefer new bin when current bin fits are poor (large post_residual)
        // or when many bins are open (spread load), less so early on
        let poor_alternatives = (post_residual as f64) > 30.0;
        if poor_alternatives {
            score -= 8.0 + 10.0 * progress;
        } else {
            score += 25.0 - 10.0 * progress;
        }
        // If this is the only option (no open bin fits), fitting_bins_count
        // counts open fitting bins; for the empty bin this is 0 or reflects others.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Global state coupling: when mean residual is high, favor bins that
    // reduce dispersion (place into below-average-residual bins)
    let diff = mean_residual - bin_residual as f64;
    score += 0.10 * diff;

    // Mild preference for filling more-full bins as stream progresses
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 8.0 * fill_ratio * (0.5 + 0.5 * step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // non-linear coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) * 40.0
                 - norm_pr * progress * 25.0
                 + (norm_pr - 0.5) * (norm_pr - 0.5) * 15.0;
    score += coupling;
    // penalize tight fits that leave dead space, more so early in stream
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 * (1.0 - progress);
    }
    // reward near-perfect fills
    if post_residual == 0 {
        score -= 30.0;
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 18.0;
    }
    // lookahead: reward leaving room for next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 10.0 * (1.0 - (pr - ni) / cap);
        } else {
            score += 8.0;
        }
    }
    // discourage spreading across too many open bins late in stream
    score += (open_bins_count as f64 / (mean_residual + 1.0)) * progress * 3.0;
    // new-bin candidate: mild penalty so it only wins when fits are bad
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post-residual: classify dead space by capacity fractions
    let frac = post_residual as f64 / cap;
    let class: u32 = (post_residual * 4) / bin_capacity; // 0..3 quarter classes
    match class {
        0 => score -= 18.0,           // near-perfect fit
        1 => score += 6.0,            // awkward quarter-left zone
        2 => score += 2.0,            // half-ish residual still reusable
        _ => score -= 4.0,            // large residual remains flexible
    }

    // Integer-division harmonic classes on post_residual modulo common item sizes
    let mod10 = post_residual % 10;
    if mod10 == 0 { score -= 5.0; }          // residue aligns with decimal item grid
    else if mod10 <= 2 { score += 3.0; }     // tiny unusable sliver
    if post_residual % 20 == 0 { score -= 3.0; }

    // Lookahead: does next item fit exactly into the post-residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 8.0 + 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use this residual; penalize small residuals more
            if frac < 0.25 { score += 10.0; }
            score += 4.0;
        }
    }

    // Last-chance bin before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when no open bin fits or residuals are poor
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 30.0;
        } else {
            score += 15.0 + mean_residual * 0.2;
        }
    }

    // Prefer filling bins with small residuals relative to the fleet mean
    score += 0.15 * (mean_residual - post_residual as f64);

    // Late in stream: consolidate, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    } else {
        score += 10.0 * progress;
    }

    // Mild penalty for too many open bins
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful later
    // are heavily penalized. Define a "useful gap" threshold relative to the
    // smallest plausible item (1..100 range => small items can be tiny, but
    // dead space below ~ item_size/2 wastes capacity).
    let dead_threshold = (item_size as f64 * 0.35).max(3.0);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    // Perfect fit: extreme reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual as f64 <= dead_threshold * 0.5 {
        score -= 8.0; // near-perfect fit still attractive
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // next item won't fit here: the gap becomes fully dead unless
            // another small item arrives later; penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, tolerate opening a new one slightly more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.8 * (0.5 + progress);

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a "ragged" bin; using it up is good (reduces fragmentation).
    let resid_f = bin_residual as f64;
    if resid_f + 0.5 < mean_residual {
        score -= (mean_residual - resid_f) * 0.5;
    } else {
        score += (resid_f - mean_residual) * 0.3;
    }

    // New-bin candidate handling: an empty bin should only win when the item
    // is large (would leave a big awkward gap elsewhere) or fits are scarce.
    if bin_residual == bin_capacity {
        let large_item_bonus = if item_size > bin_capacity / 2 { 12.0 } else { 0.0 };
        score += 18.0 - large_item_bonus
            + (fitting_bins_count as f64) * 3.0
            - progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are good: reward small post_residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // 2-step lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // smaller slack after next item is better
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leaving awkward large-ish residue
            let waste = post_residual as f64;
            if waste < next_item_size as f64 {
                score += 8.0 * (1.0 - waste / bin_capacity as f64);
            }
        }
    }

    // Compare against mean residual: prefer bins with above-average residual consumed.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last chance bin: avoid opening a new bin if this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when open bins can reasonably absorb the item.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 10.0; // big item coming; keep fresh bins fresh
        }
    }

    // Late in stream: consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: squared post-residual penalizes wasted space super-linearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 20.0;

    // Last chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead: reward bins whose post-residual can still hold the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 4.0; // dead space relative to next item
        }
        // Perfect pairing: item + next item exactly fill this bin.
        if item_size + next_item_size == bin_residual {
            score -= 12.0;
        }
    } else {
        // Last item in stream: minimize waste aggressively.
        score -= 10.0;
    }

    // Time horizon: early on, be willing to open bins / spread load; late, pack tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    // Prefer bins below mean residual (denser bins) mildly.
    score += (mean_residual - bin_residual as f64) * 0.05;

    // New-bin candidate logic: empty bin only attractive when current bin fit is poor
    // or residual is small and next item is large.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > bin_capacity as f64 * 0.35;
        let next_big = next_item_size > 0 && next_item_size >= bin_capacity - item_size;
        if poor_fit || next_big {
            score -= 8.0;
        } else {
            score += 10.0; // discourage opening new bins unnecessarily
        }
        // Late in stream, avoid opening new bins unless truly needed.
        score += progress * 6.0;
    }

    // Slight preference for fuller bins when many bins are open (consolidation).
    score += (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 / bin_capacity as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = base;

    // Smooth non-linear coupling: quadratic in normalized residual
    let norm_pr = pr / cap;
    score += 20.0 * norm_pr * norm_pr;

    // Stream progress interaction: later in stream, penalize large residuals more
    score += 15.0 * progress * norm_pr * norm_pr;
    score -= 10.0 * progress * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Tight fit reward (cubic smooth)
    let fit_tightness = 1.0 - norm_pr;
    score -= 8.0 * fit_tightness * fit_tightness * fit_tightness;

    // Last-chance bonus: this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead: if next item fits into post_residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size as f64 / cap));
    }

    // Mean residual deviation coupling (smooth)
    score += 3.0 * ((mean_residual - pr) / cap).abs();

    // Penalize opening new bins mildly, more so early in the stream
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // classes (multiples of small common sizes) are preferred.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Dead-space penalty grows superlinearly for awkward residuals.
    // Residuals in [1..=9] are near-useless (items are >= 1 but rarely tiny).
    if pr > 0 && pr < 10 {
        score += 40.0 * (10.0 - prf);
    }

    // Harmonic classes: reward residuals divisible by common item granularities.
    let mut harmony = 0.0f64;
    for &m in &[10u32, 20, 25, 50] {
        if pr % m == 0 && pr > 0 {
            harmony += 15.0;
        }
    }
    score -= harmony;

    // Perfect fit: strongly reward zero residual.
    if pr == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this is a chain placement — big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size < pr {
            // Next item fits but leaves another residual; mild reward scaled
            // by how "harmonic" the double residual is.
            let r2 = pr - next_item_size;
            if r2 % 10 == 0 {
                score -= 10.0;
            }
            score += 0.2 * r2 as f64;
        } else {
            // Next item cannot use this bin's leftover: penalize leftover.
            score += 0.3 * prf;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // current bins have large residuals (fragmented state) or few bins fit.
    if bin_residual == bin_capacity {
        // Base cost of a new bin: its full capacity as wasted potential.
        score = cap * 0.9;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a bin anyway
        } else {
            // If existing bins are fragmented (low mean residual spread),
            // opening fresh is more acceptable.
            score -= (mean_residual / cap) * 30.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Mild preference for tighter existing bins when many fit.
    if fitting_bins_count > 2 {
        score += 0.1 * (bin_residual as f64 - mean_residual);
    }

    // Waste fraction penalty: residual relative to capacity.
    score += 0.5 * (prf / cap) * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 {
        let unusable = post_residual < 10; // smallest possible item is 10 (but sizes 1..100, use small threshold)
        if unusable {
            score += 40.0;
        }
        // Non-linear penalty on residual that is small relative to capacity
        let r = post_residual as f64 / bin_capacity as f64;
        if r > 0.0 && r < 0.25 {
            score += (0.25 - r) * 120.0;
        }
    } else {
        // Perfect fit: strong reward
        score -= 50.0;
    }

    // Reward exact match of post_residual to the next item (lookahead chaining)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0; // bin remains useful for the next item
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the current item
    // would leave a large, awkward gap in an existing bin, or few bins are open.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; pressure from open bin count
        score = bin_capacity as f64 * 0.9;
        if open_bins_count > 3 {
            score -= 10.0;
        }
        // Don't open a new bin if the item fits nearly perfectly somewhere
        let waste = bin_capacity - item_size;
        if waste <= 10 {
            score += 60.0; // strongly discourage new bin when a near-perfect fit exists elsewhere
        }
    }

    // Open-bin pressure: many open bins -> favor consolidating into existing bins
    score += open_bins_count as f64 * 1.5;

    // Favor bins whose residual is below the mean (tighter bins used first)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Late in stream: prefer closing out bins (small post residual)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual exactly
    // or nearly matches the next item's size (perfect chain).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        // Exact match is a jackpot.
        if gap == 0.0 {
            score -= 60.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize dead space in this bin.
        score += 0.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Penalize residuals that are too small to ever be useful (dead space).
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Compare against mean residual: bins tighter than average are good targets.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when the item is large and no open bin
    // fits well; otherwise keep existing bins busy.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 20.0 * (1.0 - progress);
        if item_size >= 50 {
            score -= 25.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize large dead space relative to capacity, especially small residuals left over.
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // tiny unusable slivers are fine only if they finish a bin
    } else if post_residual >= 10 {
        // dead space penalty grows if it's too small for typical future items
        score += (10 - post_residual.min(10)) as f64 * 0.3;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 3.0; // breaks the chain
        }
        // Perfect two-item packing: post_residual exactly matches next item
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when current bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins are opened only when necessary.
        score += 20.0 + open_bins_count as f64 * 0.5;
        // If many bins already fit the item, discourage a new bin further.
        if fitting_bins_count > 0 {
            score += fitting_bins_count as f64 * 4.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // If next item is large, a fresh bin may be valuable.
        if next_item_size >= item_size && next_item_size > 0 {
            score -= 5.0;
        }
    } else {
        // Prefer bins with residual above mean (keeps balance) mildly.
        let dev = bin_residual as f64 - mean_residual;
        score += dev * 0.05;
    }

    // Slight preference for bins that are already quite full.
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 4.0 * fullness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: post residual, with smooth non-linear polynomial coupling to stream progress
    let poly = x * x * (1.0 - progress) + x * x * x * progress;
    let mut score = pr * (0.6 + 0.8 * poly);

    // Reward tight fits, more strongly late in the stream
    let tightness = 1.0 - x;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize when post residual is small but nonzero (dead space), smooth cubic term
    if x > 0.0 {
        let dead = (0.15 - x).max(0.0) / 0.15;
        score += 20.0 * dead * dead * dead * (1.0 + progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + 0.5 * progress);
    }

    // Lookahead: reward if next item fits the post residual (smooth affinity)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fits = ((x - nx).max(0.0)) / x.max(1e-6);
        score -= 10.0 * (1.0 - fits) * (x - nx).max(0.0) * cap / 50.0;
        // Penalize leaving residual that almost-but-not-quite fits next item
        let gap = (x - nx).max(0.0);
        let near_miss = (gap.max(1e-6) / cap).min(1.0);
        score += 15.0 * near_miss * (1.0 - near_miss) * 4.0 * (1.0 - progress);
    }

    // New-bin candidate calibration: mildly discourage opening new bins when decent fits exist
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins whose residual deviates from mean toward tightness
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 4.0 * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), scaled by capacity fraction.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 40.0 * tightness * tightness;

    // Harmonic class: reward when post_residual falls into "usable" classes
    // (divisible into chunks of common small sizes). Class = post_residual mod 10.
    let pr = post_residual;
    let class = pr % 10;
    let class_bonus: f64 = match class {
        0 => 18.0, // perfectly divisible residual
        5 => 12.0, // halves
        2 | 4 | 6 | 8 => 7.0, // even residuals
        _ => -6.0, // odd residuals are dead-space prone
    };
    score -= class_bonus;

    // Integer-division threshold: residuals that can host a mid-size item are valuable.
    if pr >= 50 { score -= 10.0; }
    else if pr >= 30 { score -= 5.0; }
    else if pr >= 10 { score -= 1.0; }
    else if pr > 0 { score += 8.0; } // tiny slivers: penalize creating them

    // Exact fit is ideal.
    if post_residual == 0 { score -= 60.0; }

    // Lookahead coupling: if next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 55.0;
        } else if next_item_size < pr {
            // harmonic compatibility: next item leaves a class-0 residual again
            if (pr - next_item_size) % 10 == 0 { score -= 9.0; }
            score -= 4.0 * (1.0 - ((pr - next_item_size) as f64) / cap);
        } else {
            // next item won't fit here; mild penalty for blocking the chain
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should only win when all
    // open fits are bad (high post_residual waste) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_pressure = ((mean_residual - (bin_capacity - item_size) as f64).max(0.0)) / cap;
        // New bin is attractive if mean residual is low (open bins are full-ish)
        // or few bins are open; penalize otherwise so existing fits win.
        score = 30.0 - 45.0 * waste_pressure - 20.0 * (1.0 - progress) + (open_bins_count as f64).sqrt() * 2.0;
        if item_size > 70 {
            // big items: opening a fresh bin is often best
            score -= 12.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 8.0; // fresh bin can chain the next item
        }
    }

    // Mild preference to consolidate into fewer bins when many are open.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * (1.0 - tightness);

    // Small tie-break toward bins with residual close to item size (best-fit core).
    score += ((bin_residual - item_size) as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest possible item (1)
    // are pure waste; residuals below ~15 are nearly unusable given typical sizes.
    if post_residual == 0 {
        score -= 40.0; // perfect fit: strongly reward
    } else if post_residual < 10 {
        score += 30.0; // tiny unusable gap: strong penalty
    } else if post_residual < 20 {
        score += 12.0; // marginal gap
    }

    // Tightness reward: favor bins where the item fills a large fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: with many open bins, prefer packing into existing bins
    // rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only bin that fits, use it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement;
    // if next item would be blocked by a small gap, penalize.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
            score += 8.0; // this placement blocks a feasible next placement
        }
    }

    // New-bin candidate handling: an empty bin has large residual; make it moderately
    // attractive only when existing bins would leave very small dead space.
    if bin_residual == bin_capacity {
        score = (post_residual as f64) + 15.0 + 0.2 * open_bins_count as f64;
        if post_residual < 10 && post_residual > 0 {
            score -= 10.0; // opening a new bin beats creating an unusable gap
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Reward close matches above next item size (still usable).
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize dead space that cannot host the next item.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Perfect fill is always excellent.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize creating tiny unusable slivers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Prefer bins with residual below mean (tight bins get emptied first).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, unless item is huge
    // relative to capacity (poor fits everywhere) or late in stream.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 - 30.0 * fill_ratio - 15.0 * progress;
        // If next item is large, a fresh bin gives flexibility.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // Mild preference for fewer open bins overall.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer minimal leftover space (tight fit).
    let mut score = post_residual as f64;

    // Fraction of the stream consumed (dynamic time horizon).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Dead-space penalty: leftovers that no plausible item can use.
    // Items range 1..100, so residual < 1 is perfectly packed; residual in
    // low teens is nearly dead. Penalize super-linearly for tiny residuals.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 1.5;
    }

    // Lookahead (k=2): reward bins whose post-residual can host the next item,
    // i.e. chain two items into the same bin. Stronger reward early on when
    // consolidation matters most.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_reward = 12.0 + 8.0 * (1.0 - progress);
        score -= chain_reward;
    } else if next_item_size > 0 && next_item_size > 0 && post_residual < next_item_size {
        // This bin becomes very unattractive for the next item; slight penalty.
        score += 4.0 * progress;
    }

    // Perfect-fit bonus: filling a bin exactly is always excellent.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is truly awful.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
        // If the resulting residual would be dead space anyway, soften bonus.
        if post_residual > 0 && post_residual < 10 {
            score += 8.0;
        }
    }

    // Crowd control: with many open bins, encourage filling existing ones
    // rather than spreading; with few bins, new bins are cheap.
    let crowd = (open_bins_count as f64).ln().max(0.0);
    score -= 2.0 * crowd * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global balance: prefer bins whose residual deviates favorably from the
    // mean residual — filling below-average-residual bins keeps the bin set
    // homogeneous and future-feasible.
    score += 0.5 * (mean_residual - post_residual as f64).abs().signum()
        * (mean_residual - post_residual as f64);

    // New-bin candidate handling: an empty bin gets a neutral-ish score.
    // It should win only when the best existing fit is poor (large
    // post_residual or wasted big residual). Bias it slightly upward so
    // decent fits in open bins win, but it stays competitive for bad fits.
    if bin_residual == bin_capacity {
        score += 10.0;
        // Late in the stream, opening fresh bins is less attractive; prefer
        // consolidating into whatever fits.
        score += 20.0 * progress;
        // But if the current item is large relative to capacity, a fresh bin
        // preserves flexibility for the lookahead item.
        if next_item_size > 0 && item_size >= 50 {
            score -= 6.0;
        }
    }

    // Prefer placing into bins with larger residuals when fits are otherwise
    // similar (consume the "easiest" space first, keep tight bins coherent).
    score -= 0.05 * (bin_residual as f64 - item_size as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer small post_residual, with a mildly convex (quadratic) penalty
    let mut score = post + 0.9 * (post / cap) * post;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early in the stream, tolerate larger leftovers (bins can be reused later);
    // late in the stream, tighten the fit aggressively.
    let progress_coupling = (0.5 + 0.5 * progress) * (post / cap) * (1.0 - (post / cap));
    score += 30.0 * progress_coupling;

    // Dead-space penalty: residuals too small for typical future items are wasted,
    // scaled smoothly by how small the residual is relative to next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let unusable = ((nxt - post) / cap).max(0.0);
        score += 12.0 * unusable * (0.4 + 0.6 * progress);
    }

    // Reward tight fits (small waste) with a smooth saturating term
    let fit_quality = 1.0 - (post / cap);
    score -= 8.0 * fit_quality * fit_quality;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Prefer bins already below mean residual (consolidating emptier bins)
    score += 0.05 * (post - mean_residual);

    // New-bin candidate: make it attractive only when current bins fit poorly;
    // an empty bin has post_residual == cap, so base score is naturally high,
    // but add a smooth discount that grows with progress and open-bin pressure.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln().max(0.0);
        score -= 10.0 + 20.0 * progress + 3.0 * pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit: prefer tight packing.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * 20.0;

    // Harmonic class of the item: which capacity fraction band it occupies.
    let item_class = (item_size * 4) / bin_capacity; // 0..3 integer division class
    let post_class = (post_residual * 4) / bin_capacity;

    // Reward when post_residual lands in a "usable" harmonic class:
    // residuals that can still host mid-size items (>= 1/4 of capacity).
    if post_residual >= bin_capacity / 4 {
        score -= 8.0;
    } else if post_residual >= bin_capacity / 8 {
        score -= 3.0;
    } else if post_residual > 0 {
        // Dead space: small unusable residue is penalized, worse the smaller.
        score += (bin_capacity / 8 - post_residual) as f64 * 0.7;
    }

    // Modulo-based coupling: item class + post class alignment bonus.
    if (item_class + post_class) % 2 == 0 {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let nxt_frac = next_item_size as f64 / bin_capacity as f64;
            score -= 6.0 + nxt_frac * 10.0;
            // Reward if post_residual after this placement also matches next item's class
            let nxt_class = (next_item_size * 4) / bin_capacity;
            if nxt_class == post_class {
                score -= 5.0;
            }
        } else {
            // Next item won't fit here: penalize slightly, less if many bins open.
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is really terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + (post_residual as f64).sqrt();
    }

    // New-bin candidate handling: opening a fresh bin is attractive early in the
    // stream or when current bins are mostly full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / bin_capacity as f64;
        // Cheap to open early or when open bins are crowded.
        score -= 12.0 * (1.0 - progress) + 10.0 * (1.0 - pressure.min(1.0));
        // But discourage hoarding many open bins when the item is small.
        if item_size <= bin_capacity / 4 {
            score += 6.0;
        }
        // If the item is large, a fresh bin is often good.
        if item_size > bin_capacity / 2 {
            score -= 5.0;
        }
    }

    // Mild preference to fill bins that are already more loaded.
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Slight penalty for very large dead space relative to next item class.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward residual that can still fit a typical future item.
    if post_residual >= 10 {
        score -= 8.0;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize leaving a gap just barely smaller than the next item (dead space).
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // New-bin candidate handling: only attractive when open bins are very full or none fit well.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap < 6.0 {
            score -= 40.0; // open bins would be left nearly full; new bin is fine
        } else {
            score += 45.0 + mean_residual * 0.4; // discourage wasting open capacity
        }
        score += step_index as f64 / total_items.max(1) as f64 * 5.0;
    }

    // Mild preference for filling fuller bins (tighter fits).
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward if next item fits exactly or well in the leftover.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0; // chain of perfect fits
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // prefer leftovers that still accommodate the next item
            score -= 120.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // dead space relative to next item: penalize proportionally
            let waste = (next_item_size - post_residual) as f64;
            score += 1.5 * waste;
        }
    }

    // Small unusable residue (below minimum plausible item) is dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += 0.5 * (bin_residual as f64 - mean_residual).max(0.0);

    // New-bin candidate: only attractive when existing bins are poor fits
    // (large item, few fitting bins, or next item pairs poorly).
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 && post_residual >= next_item_size { 1.0 } else { 0.0 };
        score += 60.0
            + 2.0 * item_size as f64
            + 50.0 * (fitting_bins_count as f64).recip()
            - 40.0 * pressure;
    }

    // Mild preference for consolidating into fewer bins early in the stream.
    score += 0.5 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual more than linearly.
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 18.0 * chain_quality;
    } else if next_item_size > 0 {
        // Next item won't chain here: slight penalty proportional to dead space risk.
        score += 4.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: only one bin can fit the item -> prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Crowding: many open bins with slack -> prefer filling existing bins.
    if open_bins_count > 1 {
        let crowding = (open_bins_count as f64).ln() / (1.0 + total_items as f64).ln();
        score -= 12.0 * crowding * (1.0 - pr / bin_capacity as f64);
    }

    // Time horizon: early in the stream, keep bins flexible (mild penalty for tiny residuals);
    // late in the stream, squeeze tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if pr > 0.0 && pr < 10.0 {
        score += (1.0 - progress) * 15.0; // dead space worse early
    }

    // Global residual context: if this bin is much tighter than average, favor it.
    score -= 0.15 * (mean_residual - pr);

    // New-bin candidate: discourage opening a new bin unless item is large and fits poorly elsewhere.
    if bin_residual == bin_capacity {
        let large = item_size as f64 / bin_capacity as f64;
        let poor_fit_elsewhere = fitting_bins_count == 0 as usize || (fitting_bins_count == 1 && mean_residual > 40.0);
        score += if poor_fit_elsewhere && large > 0.5 {
            -10.0
        } else {
            45.0 + 20.0 * (1.0 - large)
        };
    }

    // Small nudge toward bins whose residual is close to item size (best-fit flavor).
    score += 0.05 * ((bin_residual - item_size) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: penalize large post residual, weighted more as stream progresses
    let mut score = pr * (0.5 + 1.5 * progress * progress);

    // Smooth polynomial coupling: reward tight fits (small x) increasingly late
    let coupling = (1.0 - x) * (1.0 - x) * (1.0 + progress);
    score -= 20.0 * coupling;

    // Penalize residual that is small but unusable (dead space) via cubic term
    score += 10.0 * x * x * (1.0 - x) * (1.0 + 2.0 * progress);

    // Last-chance bonus: strongly prefer this bin if it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            let fit_quality = 1.0 - ((pr - ni) / cap).abs();
            score -= 8.0 * fit_quality * (0.5 + progress);
        } else {
            score += 5.0 * progress;
        }
    }

    // Mild penalty for spreading across many open bins relative to mean residual
    score += 0.05 * (open_bins_count as f64) * ((pr - mean_residual).abs() / cap);

    // New-bin candidate: neutralize its natural advantage/disadvantage smoothly
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions
    let cap_q = bin_capacity / 10; // 10 units quantum
    let pr = post_residual as i64;
    let cls = pr % (cap_q as i64);

    // Dead-space penalty for small unusable remainders
    if pr > 0 && pr < 10 {
        score += 40.0; // worst: tiny sliver
    } else if pr < 20 {
        score += 12.0;
    }

    // Reward post_residuals that are multiples of common size classes (10,20,25,50)
    if pr % 50 == 0 && pr > 0 { score -= 30.0; }
    else if pr % 25 == 0 && pr > 0 { score -= 18.0; }
    else if cls == 0 && pr > 0 { score -= 10.0; }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0;
        } else if post_residual > next_item_size {
            let nxt = next_item_size as f64;
            let slack = (post_residual - next_item_size) as f64;
            if slack < 10.0 { score -= 25.0; }
            // harmonic match: next item leaves a clean class
            if (post_residual as i64 - next_item_size as i64) % (cap_q as i64) == 0 {
                score -= 15.0;
            }
            score -= 5.0 * (nxt / 10.0);
        } else {
            // next item cannot fit here regardless; slight penalty for wasting capacity
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is poor
    if bin_residual == bin_capacity {
        score += 55.0 + (open_bins_count as f64) * 2.0;
        // but if the item is large relative to capacity, new bin is fine
        if item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
    }

    // Mild preference for tighter bins (small residual before placement)
    score += (bin_residual as f64) * 0.05;

    // Progression-aware dead-space aversion: later in stream, waste hurts more
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.3;

    // Divergence from mean residual: prefer bins near the mean (balanced packing)
    score += ((post_residual as f64) - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum item size of 1, or practically unusable)
    // are heavily penalized. Treat gaps < 10 as near-dead space.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Reward near-perfect fits (waste-free packing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Coupling: dead space is worse when many bins are already open
    // (fragmentation across the fleet compounds).
    let open_pressure = open_bins_count as f64;
    score += 0.6 * open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that fits, using it avoids
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): only attractive when the item would
    // leave a large usable residual and current bins are fragmented.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; offset when open bins have
        // poor mean residual (fragmented) and the item is large.
        let fragmentation = mean_residual / bin_capacity as f64;
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 55.0 - 45.0 * fragmentation * large_item * 2.0;
        // Lookahead: if the next item fits into the residual left here,
        // opening a fresh bin is more attractive.
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 12.0;
        }
    }

    // Prefer filling bins whose residual closely matches the item (tightness).
    let tightness = 1.0 - (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 5.0 * tightness;

    // Late in the stream, consolidation matters more: penalize spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size exactly
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 400.0;
        } else if gap <= 10.0 {
            score -= 200.0 - gap * 10.0;
        } else {
            score += gap * 0.3;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space that next item cannot use: penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Penalize large post_residual waste relative to mean residual
    let pr = post_residual as f64;
    if pr > mean_residual * 1.5 {
        score += (pr - mean_residual * 1.5) * 0.5;
    } else if pr < mean_residual * 0.5 && pr > 0.0 {
        score -= (mean_residual * 0.5 - pr) * 0.5;
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it over a new bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: make it unattractive unless existing fits are poor
    if bin_residual == bin_capacity {
        score += 120.0 + (open_bins_count as f64) * 2.0;
    }

    // Early stream: encourage tighter packing discipline
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small to hold typical future items.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for wasting capacity.
            score += 6.0;
        }
    }

    // Last-chance bonus: only this bin can fit the item; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // fits are poor or open bins are already fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_penalty = 55.0 - 20.0 * progress;
        // If mean residual is large (fragmented space), opening new bin is less bad.
        let fragmentation = mean_residual / bin_capacity as f64;
        score += new_bin_penalty * (1.0 - 0.5 * fragmentation);
        // Discourage new bins when the item is small relative to capacity.
        score += 0.4 * item_size as f64;
    }

    // Mild penalty for spreading across many open bins when mean residual is low.
    if open_bins_count > 0 {
        let mean_frac = mean_residual / bin_capacity as f64;
        if mean_frac < 0.15 && bin_residual != bin_capacity {
            score += 5.0;
        }
    }

    // Prefer filling bins with larger residual when late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: quadratic waste penalty (dead space grows quadratically bad)
    let mut score = x * x * cap;

    // Smooth non-linear coupling with stream progress:
    // early on, prefer tight fits less aggressively (keep bins flexible);
    // later, squeeze hard.
    let tightness = (1.0 - x).powi(2);
    score -= (0.5 + 2.0 * progress) * tightness * cap * 0.5;

    // Interaction: post residual vs mean residual — favor bins whose
    // remaining space aligns with the fleet average (keeps residuals uniform).
    let dev = (pr - mean_residual) / cap;
    score += (1.0 + progress) * dev.abs() * cap * 0.3;

    // Lookahead coupling: reward if next item fits the post residual,
    // smooth sigmoid-like bonus.
    if next_item_size > 0 {
        let fits_next = (pr - next_item_size as f64).max(0.0) / cap;
        score -= (1.0 - progress) * fits_next * cap * 0.8;
        // penalize near-miss: next item almost fitting wastes potential
        let gap = next_item_size as f64 - pr;
        if gap > 0.0 && gap < cap * 0.2 {
            score += (gap / (cap * 0.2)) * (1.0 - progress) * cap * 0.4;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= cap * (1.0 + progress);
    }

    // New-bin candidate: penalize opening a bin, scaled by how much
    // slack it would carry; relax penalty as stream ends.
    if bin_residual == bin_capacity {
        score += cap * (2.0 - progress) + pr * 0.5;
    }

    // Mild congestion term: many open bins -> prefer consolidation.
    score += (open_bins_count as f64).ln().max(0.0) * x * cap * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 define "usable" slots
    let pr = post_residual as i64;
    let r = pr % 10;
    let q = pr / 10;

    // Reward post-residuals that form good harmonic classes (multiples of 10/20)
    score -= 3.0 * (10 - r) as f64 * 0.0; // placeholder no-op keeps structure clear
    score -= match r {
        0 => 12.0,          // perfect slot class
        1..=5 => 4.0 - r as f64,
        _ => -(r as f64 - 5.0) * 0.8, // odd classes penalized
    };

    // Depth of the slot: how many 10-blocks remain (integer division threshold)
    score -= q as f64 * 0.5;

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect harmonic match: next item exactly fills remaining slot
            if next_item_size as i64 == pr {
                score -= 25.0;
            } else {
                let nr = (pr - next_item_size as i64) % 10;
                score -= 6.0 - nr as f64 * 0.6;
            }
        } else {
            // Next item won't fit here: bin becomes dead space
            score += 4.0 + (next_item_size as i64 - pr) as f64 * 0.05;
        }
    }

    // Last-chance bin before opening a new one: strong reward
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_open = if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 { 1.0 } else { 0.0 };
        // Base penalty so new bins are avoided unless open bins are badly fragmented
        score += 20.0 - 18.0 * bad_open - 5.0 * (mean_residual / bin_capacity as f64).min(1.0) - 3.0 * progress;
        if open_bins_count == 0 { score -= 30.0; }
    }

    // Prefer tightly packed bins relative to fleet mean residual
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    // Waste penalty scaled by how much of capacity is stranded
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    if waste_frac < 0.10 {
        score -= 8.0 * (0.10 - waste_frac) * 10.0; // near-full bins rewarded
    } else {
        score += waste_frac * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Moderate gaps that only fit tiny items get a milder penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize wasting a large residual on a small item (poor space utilization).
    if post_residual as f64 > 0.6 * bin_residual as f64 && item_size < 40 {
        score += 12.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: prefer bins whose post residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // New-bin candidate: only attractive when open bins would create dead space.
    if bin_residual == bin_capacity {
        let dead_space_pressure = (0..1)
            .map(|_| 0.0)
            .sum::<f64>()
            + if fitting_bins_count <= 1 { 0.0 } else { 25.0 };
        score += dead_space_pressure;
        score -= 5.0; // slight base preference for fresh capacity
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, penalize dead space relative to capacity.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * dead * dead;

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit: this placement creates a likely-dead residual.
        score += 4.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin bonus: avoid wasting the only fitting bin on a bad fit,
    // but strongly prefer it on a good fit.
    if fitting_bins_count == 1 {
        if post_residual as f64 <= mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64) / (1.0 + mean_residual / bin_capacity as f64);
        score += 10.0 + 2.0 * open_bins_count as f64 - 3.0 * crowded;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0;
        }
    }

    // Slight stream-phase modulation: pack harder early, allow new bins late.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * phase * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: squaring amplifies tightness advantage.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 12.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize leaving dead space that nothing typical can use
    // (post_residual too small relative to smallest plausible item).
    if post_residual < 10 {
        score += 8.0;
    } else if post_residual < 20 {
        score += 4.0;
    }

    // Lookahead synergy: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            // next item still fits: mild reward proportional to leftover after next
            score -= 3.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            // next item won't fit here: slight penalty proportional to gap
            score += 1.5 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 * (item_size as f64 / bin_residual as f64);
    }

    // Prefer filling already-open bins when many are open (bin-count control).
    score += 0.15 * open_bins_count as f64 * (item_size as f64 / bin_capacity as f64);

    // Global dispersion: if mean residual is high, prefer bins below mean
    // (balance toward filling smaller-residual bins first).
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    // Time horizon: early in the stream, be conservative (favor good fits);
    // late in the stream, close out bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with a non-linear penalty on large leftovers.
    let mut score = pr as f64;
    score += 40.0 * norm_pr * norm_pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, small dead space matters more (waste becomes permanent).
    let coupling = (1.0 - progress) * (1.0 - progress);
    score += 30.0 * norm_pr * progress * (2.0 - progress);

    // Lookahead: reward if next item fits into post_residual (smooth soft-max style).
    let ns = next_item_size as f64;
    if ns > 0.0 {
        let fits = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        let gap = (ns / cap - norm_pr).abs();
        score -= 25.0 * fits * (1.0 - gap * gap).max(0.0);
        // Penalize leaving space that neither fits next item nor is tiny.
        score += 10.0 * (1.0 - fits) * norm_pr;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0 * coupling;
    }

    // Many open bins with high mean residual: discourage adding to scattered space.
    let scatter = (mean_residual / cap - norm_pr).abs();
    score += 8.0 * scatter * (open_bins_count as f64).sqrt() / (10.0 + open_bins_count as f64);

    // New-bin candidate: penalize opening a new bin mildly, more early in the stream
    // and when other bins fit; allow it late when post_residual would be tiny anyway.
    if bin_residual == bin_capacity {
        let openness = 1.0 / (1.0 + (fitting_bins_count as f64));
        score += 15.0 + 45.0 * (1.0 - progress) * openness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space quality classes
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: near-perfect fit (tiny residual) -> strong reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Class B: residual in "dead zone" — too small for typical items (10..80 range,
    // but interface says 1..100; penalize residuals below the minimum useful size)
    let min_item = 1u32;
    if post_residual < min_item.max(1) {
        score -= 50.0;
    }

    // Integer-division thresholds on post_residual (harmonic bands of 20)
    let band = post_residual / 20;
    match band {
        0 => score -= 15.0,             // 0..19: tight fit band
        1 => score += 5.0,              // 20..39: moderate
        2 => score += 12.0,             // 40..59: large leftover
        _ => score += 20.0,             // 60+: very loose
    }

    // Modulo arithmetic on post_residual: residuals divisible by common item
    // sizes (10/20/25/50) are reusable -> reward
    if post_residual > 0 {
        let mut reusable = false;
        for m in [10u32, 20, 25, 50] {
            if post_residual % m == 0 {
                reusable = true;
            }
        }
        if reusable {
            score -= 12.0;
        }
        // Penalize odd residuals (harder to fill exactly)
        if post_residual % 2 == 1 {
            score += 3.0;
        }
    }

    // Lookahead coupling: reward bins whose residual exactly fits the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size as f64) / cap);
        } else {
            score += 10.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Many fitting bins: mild penalty to prefer tightest (already via post_residual),
    // but discourage spreading across many open bins
    if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0).min(5.0);
    }

    // New-bin candidate: make it attractive only when no good fit exists.
    // Baseline: slightly worse than a perfect fit, better than a loose one.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.55 + 10.0 * progress;
        // If item is large, opening fresh is safer
        if item_size >= 50 {
            score -= 8.0;
        }
        // If only one fitting bin and it's this new bin, keep it competitive
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Progression: later in stream, be slightly greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - pr / cap);

    // Mean residual coupling: if open bins are already loose, prefer tight placements
    score += 0.05 * (mean_residual - pr).clamp(-50.0, 50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size are pure waste.
    // Penalize post_residuals in the "unusable" band (0 < gap < 10) heavily,
    // and mildly penalize gaps that only the smallest items could use.
    let gap = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - gap / 10.0);
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward near-perfect fits (exact closure is ideal).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 12.0;
        // But if the resulting gap is dead space, soften the discount.
        if post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading; with few open bins, consolidation is naturally fine.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Lookahead: if the next item fits the post-residual exactly or well,
    // this bin is a great host — reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 25.0;
        } else if slack < 10 {
            score -= 10.0;
        }
    }
    // If next item cannot use the leftover, the gap is likely dead — penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Deviation from mean residual: prefer bins whose residual after placement
    // stays near the fleet mean (balanced packing).
    score += 0.3 * (gap - mean_residual).abs();

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Only attractive when the item is large and existing fits would leave bad gaps.
    if bin_residual == bin_capacity {
        let base = 25.0 + 0.5 * item_size as f64;
        // Late in the stream, be more conservative about opening bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = base + 20.0 * progress;
        // If no open bin fits at all, opening a new bin is necessary — make it cheap.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits exactly in post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect pairing
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            let deficit = (next_item_size - post_residual) as f64;
            score += 10.0 + 0.5 * deficit; // next item won't fit here
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Penalize very small dead space unless next item uses it (unusable sliver).
    if post_residual > 0 && next_item_size > 0 && post_residual < 10 && post_residual != next_item_size {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize slightly so we only open when fits are poor,
    // but relax late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 15.0 * progress;
    }

    // Mild bonus for high fill ratio.
    score -= 0.2 * (item_size as f64 / bin_capacity as f64) * 100.0 / open_bins_count.max(1) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: lower post_residual is already favored via base score.
    // Amplify tightness with a non-linear term.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0; // bin stays useful for the lookahead item
        } else {
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // When many bins fit the item, prefer the fullest bin (best-fit coupling).
    if fitting_bins_count > 1 {
        score += 3.0 * (1.0 - (bin_residual as f64 / bin_capacity as f64));
    }

    // Global pressure: many open bins with small mean residual -> prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 2 && mean_residual < item_size as f64 * 1.5 {
        score -= 8.0 * (1.0 - progress);
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit_everywhere = fitting_bins_count == 0
            || (mean_residual < item_size as f64 * 0.6 && open_bins_count > 0);
        if poor_fit_everywhere {
            score -= 30.0;
        } else {
            score += 20.0; // discourage opening new bins when existing ones suffice
        }
    }

    // Mild early-stream exploration: prefer larger residuals early, tighter later.
    score += 4.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let r = bin_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / c; // normalized post residual
    let mut score = pr as f64;

    // Smooth non-linear coupling of post residual with stream progress:
    // early on, prefer tight fills (low post residual); late, tolerate slack.
    let progress_weight = 0.5 + 2.0 * t * t;
    score += progress_weight * (x * x) * c * 0.6;

    // Cubic penalty for very small residuals (dead space) with smooth ramp.
    score += (1.0 - x).powi(3) * c * 0.35;

    // Lookahead coupling: reward residual that can host next item, smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / c;
        let fit = (x - nx).max(0.0);
        score -= 8.0 * (1.0 - (fit * 3.0).min(1.0)) * nx;
        score += 4.0 * (1.0 - x).max(0.0) * (nx / (nx + 0.2));
    }

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: penalize mildly so we only open when fits are poor.
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (1.0 - t);
    }

    // Mean residual coupling: spread slack evenly via smooth term.
    score += 0.15 * (pr as f64 - mean_residual).abs();

    // Slight preference for bins with more open competition (consolidation).
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: very low post_residual is excellent.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 10 {
        score -= 18.0;
    }

    // Harmonic class of post_residual modulo capacity fractions.
    let cap = bin_capacity as f64;
    let quarter = (bin_capacity / 4) as u32;
    let eighth = (bin_capacity / 8) as u32;
    let cls = post_residual / eighth; // 0..=8 harmonic class
    match cls {
        0 => score -= 12.0,          // near-full bin: great
        1 => score -= 4.0,
        2 => score += 3.0,           // ~1/4 left: dead-space risk
        3 => score += 6.0,
        4 => score += 2.0,           // half-full: reusable
        5 => score -= 1.0,
        6 => score -= 2.0,
        _ => score -= 3.0,           // mostly empty: flexible
    }

    // Pairing lookahead: does post_residual pair with next item?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect follow-up
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else if post_residual > 0 && post_residual < 10 && next_item_size > post_residual {
            score += 8.0; // stranded sliver
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate logic: only attractive when current bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fits = if post_residual == bin_capacity {
            // For the new-bin call, judge by how many bins fit and mean residual.
            (fitting_bins_count as f64) * 10.0 + mean_residual * 0.3
        } else { 0.0 };
        score += 20.0 + poor_fits - progress * 10.0;
        if open_bins_count == 0 { score -= 100.0; }
    }

    // Mild pressure to consolidate: fewer open bins -> prefer filling them.
    score -= (open_bins_count.min(20) as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item (>=1) can use
    // are pure waste; small gaps below the minimum item size are unusable.
    if post_residual == 0 {
        score -= 60.0; // perfect fill is heavily rewarded
    } else if post_residual < 10 {
        // tiny dead space: strongly penalize (unusable in practice)
        score += 40.0;
    } else {
        // usable gap: mild reward proportional to how well a next item fits
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0; // lookahead: next item fits here
        }
        // penalize gaps that are "almost full but not quite" (hard to reuse)
        score += (post_residual as f64 / bin_capacity as f64) * 5.0;
    }

    // Exact-fit coupling with lookahead: item leaves room exactly for next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's necessary.
    if bin_residual == bin_capacity {
        score += 45.0 + 2.0 * open_bins_count as f64;
        // opening a new bin is more attractive late in the stream when
        // open bins are fragmented (mean residual low)
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones tightly
    score += 0.05 * open_bins_count as f64;

    // Prefer bins whose residual is close to the item (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Slight preference for using bins with residual below mean (consolidate)
    if (bin_residual as f64) < mean_residual && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect-ish fits (small post_residual) more aggressively.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        let match_quality = 1.0 - gap / bin_capacity as f64;
        score -= 20.0 * match_quality * match_quality;
    } else if next_item_size > 0 {
        // Next item cannot use this leftover: penalize dead space.
        score += 6.0;
    }

    // Coupling with mean residual: prefer bins whose post_residual deviates favorably.
    score -= 0.05 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Penalize opening a new bin when decent existing fits exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 4.0 + 3.0 * (1.0 - progress);
        if fitting_bins_count > 0 && post_residual > 20 {
            score += 6.0;
        }
    }

    // Slight preference to fill nearly-full bins to close them out.
    if post_residual < 10 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 6.0 * fit_ratio * fit_ratio;

    // Penalize creating dead space that the lookahead item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }
    // Reward leaving exactly enough room (or a snug remainder) for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 4.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Perfect-fill bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Crowding pressure: when many bins are open, prefer reusing existing ones.
    let t = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * t);

    // Prefer bins whose residual deviates below the mean (more "spent" bins).
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // New-bin candidate: penalize unless current bins are badly fragmented
    // (mean residual too small relative to item) or nothing else fits well.
    if bin_residual == bin_capacity {
        let base = bin_capacity as f64 + 20.0;
        let desperation = if mean_residual < item_size as f64 {
            0.0
        } else {
            (mean_residual - item_size as f64) / bin_capacity as f64
        };
        score = base - 18.0 * desperation - (1.0 - t) * 5.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits; must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let fit_ratio = pr / cap; // 0 = perfect fit, 1 = empty bin

    // Core: quadratic penalty on leftover, scaled by stream progress (late items -> tighter packing)
    let mut score = pr * (1.0 + 2.5 * progress) + 40.0 * fit_ratio * fit_ratio * (0.5 + progress);

    // Reward bins whose leftover is small relative to mean residual (good consolidation)
    score -= 12.0 * (1.0 - fit_ratio) * (mean_residual / cap).tanh();

    // Last-chance bonus: strongly prefer the only bin that fits
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Lookahead: if next item can use the post-residual, reward; else penalize dead space
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - pr / (pr + nxt)) * (1.0 - fit_ratio);
        } else {
            score += 6.0 * (1.0 - pr / cap);
        }
    }

    // Penalize spreading across many open bins mildly
    score += 1.5 * (open_bins_count as f64).ln().max(0.0) * fit_ratio;

    // New-bin candidate: acceptable early or when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_residual;
    if is_new_bin {
        let best_open = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        score = 25.0 + 60.0 * progress - 20.0 * best_open * (mean_residual / cap).tanh();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residue classes modulo 10
    // classify "dead space" quality. Residuals that are multiples of 10
    // (and especially of 25/50) are more reusable by typical item sizes.
    let r = post_residual;
    let cls = r % 10;
    let cls_penalty: f64 = match cls {
        0 => -6.0,           // perfectly reusable class
        5 => -2.0,           // half-class, decent
        1 | 9 => 4.0,        // nearly-dead slivers
        2 | 8 => 2.0,
        3 | 7 => 1.0,
        _ => 3.0,            // 4 | 6
    };
    score += cls_penalty;

    // Integer-division thresholds: big reusable chunks (>= 50, >= 25) rewarded
    if r >= 50 {
        score -= 8.0;
    } else if r >= 25 {
        score -= 3.0;
    } else if r > 0 {
        score += 5.0; // tiny pocket of dead space
    }

    // Coupling with lookahead: if the next item fits exactly into post_residual,
    // strongly reward (harmonic match).
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 15.0;
        } else if next_item_size <= r {
            // partial fit quality via integer division ratio
            let k = r / next_item_size.max(1);
            score -= match k {
                0 => 0.0,
                1 => 4.0,
                _ => 6.0,
            };
            // modulo mismatch penalty: leftover after next item is an ugly class
            let nr = r - next_item_size;
            if nr % 10 != 0 {
                score += 2.0;
            }
        } else {
            // next item cannot use this residual: mild penalty scaled by gap
            score += ((next_item_size - r) as f64).min(10.0) * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // NEW-BIN CANDIDATE handling: empty bin gets baseline cost of a fresh bin,
    // discounted when many bins are open (consolidation pressure) or late in stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_cost = 18.0;
        new_bin_cost -= (open_bins_count as f64).min(10.0) * 0.8;
        new_bin_cost -= progress * 4.0;
        // if item nearly fills a fresh bin, opening is attractive
        if item_size >= bin_capacity * 3 / 4 {
            new_bin_cost -= 8.0;
        }
        score += new_bin_cost.max(2.0);
    } else {
        // Prefer bins whose residual is closest to item (tight fit) via fraction of capacity
        let fill = item_size as f64 / bin_capacity as f64;
        score -= fill * 5.0;
        // prefer bins below mean residual (denser bins get emptied first)
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        } else {
            score += 1.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if no plausible future item (min size ~1, but realistically
    // small gaps below ~15 rarely get filled) can use it well.
    let dead_threshold = 15.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= tightness * 25.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: penalize spreading across many open bins,
    // but soften when few bins can fit the item (last-chance bin).
    let pressure = open_bins_count as f64 * 1.5;
    if fitting_bins_count <= 1 {
        score -= pressure * 0.8;
    } else {
        score += pressure;
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use leftover; penalize proportionally.
        score += (next_item_size as f64 - post_residual as f64) * 0.3;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // from the mean (using a below-mean residual bin consolidates space).
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.2;

    // New-bin candidate handling: opening a new bin is only attractive when
    // current bin would leave a bad gap and few fitting bins exist.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score = bin_capacity as f64 * 0.9;
        // Attractive if existing fits are poor (large post_residuals elsewhere
        // implied via mean_residual) or this is a last-chance situation.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        if mean_residual < 20.0 {
            score -= 15.0;
        }
        // Early in stream, slightly prefer opening bins (room to maneuver).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect lookahead match (small gap).
    else if next_item_size > 0 && post_residual > next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 45.0 * (-gap / 8.0).exp();
    }

    // Reward tight fits generally (small dead space).
    score -= 20.0 * (-(post_residual as f64) / 15.0).exp();

    // Penalize residuals that are too small for any plausible future item (min size 1..10).
    if post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    }

    // Compare post_residual against mean residual: avoid making bin much emptier than average.
    score += 0.5 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Many open bins: prefer filling existing bins over opening new ones.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: penalize unless current bin fit would be very poor
    // (i.e., a new empty bin is attractive when post_residual is large dead space).
    if bin_residual == bin_capacity {
        // Opening a fresh bin has a fixed cost, but is good if the best existing
        // fit would leave a big awkward residual. Base cost:
        score = 55.0;
        // If lookahead exactly matches a fresh bin's residual after placing item
        // (bin_capacity - item_size == next_item_size), opening is great.
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 70.0;
        }
        // Late in stream, avoid opening new bins.
        score += 40.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1), used as a dynamic time horizon.
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Tightness of fit: reward near-perfect fills.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // small scraps are nearly worthless, so filling is fine
    } else if post_residual >= 10 {
        // Larger leftovers are more valuable; penalize squandering them on a loose fit.
        score += 0.35 * (post_residual as f64 - 10.0) * (1.0 - fit_ratio);
    }

    // Lookahead coupling: if the next item fits in the post residual, this bin
    // remains useful -> keep it flexible; if not, prefer dumping the item here.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 4.0 * (1.0 - progress); // flexibility worth more early
        } else {
            score -= 3.0 * progress; // late in stream, burn tight bins now
        }
    } else {
        // Last item: prefer the bin that ends most full.
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Compare against global mean residual: bins already below mean residual
    // are "valuable" leftovers; filling them loosely is costlier.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // New-bin candidate: make it attractive only when current fits are poor
    // or few bins fit the item; otherwise a new empty bin should be penalized.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative, must open
        } else {
            score += 12.0 + 8.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        }
    }

    // Mild pressure against spreading across many bins late in the stream.
    score += 0.4 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let sz = item_size as f64;

    // Base: scaled post residual (waste after placement)
    let mut score = pr / cap * 60.0;

    // Non-linear quadratic waste penalty: dead space hurts super-linearly
    score += 0.9 * (pr / cap).powi(2) * 40.0;

    // Smooth cubic coupling of waste with stream progress:
    // late in the stream, tolerate waste less (bins already committed)
    let late = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += late * pr * 0.35;

    // Reward tight fits: fill fraction of the bin
    let fill = (bin_residual - post_residual) as f64 / res.max(1.0);
    score -= fill * fill * 25.0;

    // Lookahead: strongly reward leaving exactly enough room for next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt).abs();
        score -= (1.0 - diff / cap).powi(3) * 30.0;
        // penalize post residual that fits nothing (dead space) given lookahead
        if pr < nxt {
            score += (nxt - pr) * 0.25;
        }
    } else {
        // last item: only waste matters
        score -= 10.0 * fill;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else {
        // many alternatives: mildly penalize using a bin others could also use
        score += (fitting_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // New-bin candidate logic: empty bin should only win when open bins fit poorly
    if bin_residual == bin_capacity {
        // competitive baseline: slightly above a perfect fit on an open bin
        score = 12.0 + late * 8.0;
        // discourage new bins when existing residuals are already fragmented
        score += (mean_residual / cap) * 10.0;
        // discourage when several bins can fit
        score += (fitting_bins_count as f64) * 4.0;
        // small items shouldn't start new bins
        score += (cap - sz) * 0.05;
    }

    // Coupling with mean residual: prefer bins whose residual is near the mean
    // (keeps the pool homogeneous, easier future packing)
    let dev = (res - mean_residual).abs();
    score += (dev / cap).powi(2) * 15.0;

    // Slight preference for more-filled bins (lower residual) overall
    score += res * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "useful" modular classes.
    // Residuals divisible by 10 or small enough to likely be filled are good.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
        // Modulo-10 harmonic classes: 0 best, then 5, then odd small values.
        let m = pr % 10;
        let class_bonus = match m {
            0 => 18.0,
            5 => 12.0,
            2 | 8 => 6.0,
            _ => 0.0,
        };
        score -= class_bonus;

        // Small residuals are nearly dead space unless exactly consumed later.
        if pr < 10 {
            score += 8.0; // tiny sliver penalty
        }
        // Integer division thresholds: residual that could fit common next sizes.
        if next_item_size > 0 {
            if next_item_size <= pr {
                // Lookahead fit quality: how tightly the next item fits after this placement.
                let post2 = pr - next_item_size;
                score -= 10.0 + (post2 as f64) * 0.4;
                if post2 == 0 {
                    score -= 15.0; // two-item perfect fill
                }
                // Harmonic class of the pair fill
                if post2 % 10 == 0 {
                    score -= 4.0;
                }
            } else {
                // Next item won't fit in this bin after placement: mild penalty,
                // stronger if this bin was the only option.
                score += 3.0;
            }
        }
    }

    // Fractional fill of the bin: reward high utilization.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize spreading across many open bins; encourage consolidation.
    score += (open_bins_count as f64) * 0.5 * (mean_residual / bin_capacity as f64);

    // New-bin candidate: only attractive when current bin fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin, discounted when item is large.
        score = 55.0 - 0.3 * (item_size as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 6.0; // pairing potential in a fresh bin
        }
    }

    // Slight time decay: late in stream, prefer closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0 * (10.0 - post_residual as f64);
    } else if post_residual >= 10 && post_residual < 20 {
        score += 50.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Perfect / near-perfect fits get strong rewards.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Lookahead coupling: penalize leftovers that cannot host the next item
    // if the leftover is small anyway; reward leftovers that can host it.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual > 0 {
            score -= 2.0 * next_item_size as f64;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 1.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Open-bin pressure: discourage proliferating bins unless the fit is great.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure from open bins.
        score += 60.0 + 15.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);
        // But opening a fresh bin is fine if item is large (little choice anyway).
        score -= 0.5 * item_size as f64;
    } else {
        score -= 10.0; // mild preference for reusing open bins
        // Favor bins whose residual deviates positively when mean residual is low.
        score -= 0.3 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: perfect match of leftover with next item is ideal.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-step chain
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= (20.0 * slack / (bin_capacity as f64)).min(15.0);
            // penalize if leftover after next item would be tiny-but-nonzero
            if slack < 8.0 {
                score += (8.0 - slack) * 2.5;
            }
        } else {
            // next item cannot fit in leftover: leftover is dead space
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.8;
        }
    }

    // Reward tight fits relative to mean residual of open bins.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr) * 0.5;
    } else {
        score += (pr - mean_residual) * 0.25;
    }

    // Last chance: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer filling nearly-full bins; penalize waste of large residuals.
    let fill = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= fill * 10.0;

    // Early in stream, opening new bins is cheap; later, conserve bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty grows with progress and open bins.
        score += 15.0 + 25.0 * progress + 2.0 * open_bins_count as f64;
        // Acceptable if current fits are all terrible (high residual elsewhere).
        if pr >= mean_residual {
            score -= 10.0;
        }
    }

    // Slight penalty for leaving residuals too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space that can never fit a typical future item.
    if post_residual > 0 && post_residual < 10 {
        score -= 40.0; // perfect closure bonus
    } else if post_residual < item_size.min(30) {
        score += 15.0; // awkward sliver
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual >= next_item_size {
            score -= 20.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 10.0 + 0.2 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let mean_fit_gap = (mean_residual - item_size as f64).abs();
        score = 45.0 + mean_fit_gap * 0.5 + open_bins_count as f64 * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Time horizon: early in stream, be slightly conservative (keep bins open for flexibility).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Global pressure: many open bins with large mean residual -> prefer consolidating.
    if mean_residual > item_size as f64 * 1.5 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: f64, fitting_bins_count: usize) -> f64 {
    let _ = post_residual;
    let post_res = (bin_residual - item_size) as f64;
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let norm_post = post_res / cap;

    // Base: minimize leftover space, with non-linear penalty on mid-range residuals
    let mut score = post_res;

    // Smooth polynomial coupling: penalize "awkward" residuals more as stream progresses
    let awkward = norm_post * (1.0 - norm_post); // peaks at norm_post = 0.5
    score += 40.0 * awkward * awkward * (0.5 + progress);

    // Reward tight fits (small post_residual) with super-linear discount
    score -= 30.0 * (1.0 - norm_post).powi(4);

    // Lookahead: reward leaving space for the next item (smooth gaussian-like affinity)
    if next_item_size > 0 {
        let gap = (post_res - next_item_size as f64).abs();
        let affinity = (-(gap / 30.0).powi(2)).exp();
        score -= 25.0 * affinity * (1.0 - progress * 0.5);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - progress);
    }

    // Slight penalty when many bins are open and residual is large (fragmentation)
    let frag = norm_post * (open_bins_count as f64).ln_1p();
    score += 5.0 * frag * progress;

    // New-bin candidate: make empty bins mildly unattractive unless residual situation is bad
    if bin_residual == bin_capacity {
        score += 20.0 - 15.0 * progress + mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 create "dead space classes".
    // Residue 0 is perfect packing; large residue near class boundary is waste.
    let residue = post_residual % 10;
    score += match residue {
        0 => -8.0,
        1 | 9 => 4.0,
        2 | 8 => 2.5,
        3 | 7 => 1.0,
        _ => 0.0,
    };

    // Integer-division thresholds: post_residual in [1..10] is nearly dead space.
    if post_residual > 0 && post_residual <= 10 {
        score += 15.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= 6.0 - ((post_residual - next_item_size) as f64) * 0.15;
        } else {
            // Next item cannot use this residual: penalize large leftover.
            score += (next_item_size.min(post_residual + 1) as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Capacity fraction tiers: perfect / near-perfect fills.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac == 0.0 {
        score -= 30.0;
    } else if frac < 0.05 {
        score -= 10.0;
    } else if frac > 0.5 {
        score += 5.0;
    }

    // Prefer bins tighter than the mean residual across open bins.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 0.4 + (step_index as f64 / (total_items.max(1) as f64)) * 5.0;
        score = 60.0 + pressure;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item (<= 10) are pure waste; punish them quadratically.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    } else if post_residual < 25 {
        // Semi-dead zone: only useful for tiny future items.
        score += (25 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits: post_residual small relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // If this bin can also fit the next item, reward keeping that option alive.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; mild penalty scaled by how badly it misses.
        score += ((next_item_size - post_residual) as f64).min(20.0) * 0.4;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones;
    // penalize new-bin candidate (bin_residual == bin_capacity) more.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    } else {
        // Using existing bins reduces open-bin sprawl.
        score -= 0.5 * open_bins_count as f64;
    }

    // Prefer bins whose residual is already near the mean (keeps residuals uniform).
    score += 0.3 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (post_residual small relative to item size)
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let tightness = post_residual as f64 / bin_residual as f64;
        score -= (1.0 - tightness) * 50.0;
    }

    // 2-step lookahead: if the next item fits into post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 120.0;
        // extra reward if the next item exactly fills the remaining space
        if post_residual == next_item_size {
            score -= 200.0;
        }
    } else if next_item_size > 0 {
        // penalize leaving residue that the next item cannot use
        let waste = if post_residual < next_item_size {
            post_residual as f64
        } else {
            0.0
        };
        score += waste * 0.5;
    }

    // Penalize creating dead space below the minimum plausible item size
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Compare residual against the mean residual of open bins
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        // base penalty so we prefer existing bins unless they fit poorly
        score += 80.0;
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        // late in the stream, opening fresh bins is fine (no lookahead pressure)
        if next_item_size == 0 {
            score -= 100.0;
        }
    }

    // Slight preference to fill earlier-opened bins when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * 5.0;

    // Stream progression: tighten criteria as we approach the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to the item, the better.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 2.5 * fill_ratio * (bin_capacity as f64 - post_residual as f64);

    // Penalize dead space that the lookahead item cannot use.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // This bin becomes unusable for the next item: penalize proportionally.
            score += 0.6 * post_residual as f64 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        } else {
            // Post-residual can host the next item: strong reward.
            score -= 3.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: prefer tightest fit overall.
        score -= 1.5 * fill_ratio;
    }

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0 + 0.05 * open_bins_count as f64;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are large (poor fits everywhere) or many bins fit.
    if bin_residual == bin_capacity {
        let mean_fit = mean_residual / bin_capacity as f64;
        // Penalize new bins early / when mean residual is small (good fits exist).
        score += 8.0 * (1.0 - mean_fit) + 0.3 * open_bins_count as f64;
        // Reward opening a new bin late in the stream when item is large.
        score -= 2.0 * fill_ratio * (step_index as f64 / total_items.max(1) as f64);
        // If many bins can fit the item, keep the item in an existing bin.
        if fitting_bins_count > 2 {
            score += 3.0;
        }
    } else {
        // Prefer bins whose residual is close to item_size (best-fit flavor).
        let slack = (bin_residual - item_size) as f64;
        score += 0.15 * slack * slack / bin_capacity as f64;
        // Slight preference for bins below mean residual (consolidating fuller bins).
        if (bin_residual as f64) < mean_residual {
            score -= 0.8;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling: waste penalized more as stream progresses
    let norm_waste = pr / cap;
    let coupling = norm_waste * norm_waste * (1.0 + progress);
    score += 30.0 * coupling;

    // Reward tight fits (small post_residual relative to item)
    let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
    score += 20.0 * tightness * tightness;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: penalize if next item cannot use the post_residual (dead space)
    if next_item_size > 0 {
        if (next_item_size as u32) > post_residual {
            score += 12.0 * (next_item_size as f64 - pr).min(cap) / cap;
        } else {
            // reward bins whose leftover can host the next item
            score -= 10.0 * (1.0 - ((pr - next_item_size as f64) / cap));
        }
    }

    // Mild preference for bins below mean residual (consolidate waste)
    score += 5.0 * ((pr - mean_residual) / cap).tanh();

    // New-bin candidate: penalize unless current residuals are heavily fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        score = if fragmentation > 0.5 {
            score - 15.0 * (fragmentation - 0.5)
        } else {
            score + 35.0 * (0.5 - fragmentation)
        };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity split into harmonic bands.
    // Residuals in the lowest band (tight fits) are heavily rewarded.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f;

    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else {
        // Integer-division harmonic classes on post_residual.
        let class = post_residual / (bin_capacity / 4).max(1); // 0..=4
        score += class as f64 * 8.0;

        // Dead-space penalty: residual too small for the smallest plausible item.
        if post_residual < 10 {
            score += 12.0;
        }
        // Large leftover (>50% of capacity) is wasteful unless a new bin is better.
        if frac > 0.5 {
            score += 15.0 * frac;
        }

        // Lookahead coupling: reward if next item fits the post-residual exactly-ish.
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                let slack = (post_residual - next_item_size) as f64;
                score -= 20.0 - slack.min(20.0);
                if post_residual == next_item_size {
                    score -= 25.0; // chained perfect fit
                }
            } else {
                // Next item won't fit here: mild penalty proportional to overshoot.
                score += ((next_item_size - post_residual) as f64) * 0.3;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when this bin would leave a bad class.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: slightly worse than a decent fit,
        // better than a wasteful one.
        let bad_fit = frac > 0.5 || (next_item_size > 0 && post_residual > 0 && next_item_size > post_residual);
        score = if bad_fit { 5.0 } else { 90.0 + post_f };
        // As stream progresses and many bins are open, discourage proliferation mildly.
        score += open_bins_count as f64 * 0.5;
    }

    // Mild pressure to consolidate when many bins are open.
    score -= mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // smallest plausible item (1..=10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight fit reward: the smaller the item is relative to the gap, the better.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 15.0;

    // Lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + next_item_size as f64 * 0.2;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap too small for the next item -> mild dead-space penalty.
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many open bins.
    score += open_bins_count as f64 * 0.8;

    // Prefer bins with residuals close to the mean (balanced packing).
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    // New-bin candidate: baseline slightly above a decent fit, but attractive
    // when all fits would create heavy dead space (handled via penalties above).
    if bin_residual == bin_capacity {
        score = 55.0 + step_index as f64 / (total_items.max(1) as f64) * 10.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, with slight superlinear penalty on waste.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // 2-step lookahead: reward exact/near match of next item into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain fill
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 45.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item doesn't fit here: penalize proportional to leftover gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap.min(60.0);
        }
    }

    // Relative to mean residual: bins tighter than average are more valuable.
    let tightness = mean_residual - bin_residual as f64;
    score += 0.8 * tightness.max(-50.0);

    // Last-chance bin: strong reward to use it, avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize creating very small unusable residuals (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // New-bin candidate: neutral-ish baseline, slightly higher when many bins open
    // and this bin's residual is close to mean (i.e., nothing special about it).
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 12.0 + 0.6 * mean_residual
            - (if next_item_size > 0 { (next_item_size as f64).min(60.0) } else { 0.0 }) * 0.15;
    }

    // Late in stream: consolidate harder, discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    // Slight penalty when many bins already open (encourage packing into existing).
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Exact or near-exact fill is a jackpot.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            score -= 25.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here: slight penalty for leaving a large awkward gap.
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
        if post_residual < 20 {
            score -= 30.0;
        }
    }

    // New-bin candidate handling: opening a new bin is penalized, but less so
    // when existing bins would leave large dead space or when many bins are open.
    if bin_residual == bin_capacity {
        score += 120.0;
        // If the item is large relative to capacity, a fresh bin is more acceptable.
        score -= 0.5 * item_size as f64;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
        // Many open bins: discourage yet another one.
        score += 3.0 * open_bins_count as f64;
        // If no open bin leaves a decent post-fit, allow new bin.
        if mean_residual > 0.0 && (item_size as f64) > mean_residual {
            score -= 60.0;
        }
    }

    // Global residual balancing: prefer bins whose residual is below the mean
    // (i.e., fuller bins), keeping emptier bins flexible for future items.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Mild time-dependent pressure to close out bins as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer minimal post_residual, with non-linear (quadratic) coupling
    let mut score = pr + (pr * pr) / cap;

    // Normalize post_residual against mean residual of open bins: penalize
    // bins whose leftover will deviate strongly from the fleet average
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev.abs();

    // Stream progress coupling: as the stream advances, waste becomes more
    // costly (fewer chances to fill gaps later), so scale penalty smoothly
    let urgency = 1.0 + 3.0 * progress * progress;
    score *= urgency;

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 6.0 * snug * (1.0 + progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin for a mediocre fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 5.0 * progress;
    }

    // New-bin candidate: mildly penalize when good fits exist among open
    // bins, but allow opening when open bins would waste much space
    if bin_residual == bin_capacity {
        let waste_if_open = pr; // = capacity - item_size
        score = cap - item_size as f64;
        // discourage new bin unless existing fits would leave big waste
        let min_existing_waste = if fitting_bins_count > 0 { mean_residual } else { cap };
        if min_existing_waste < waste_if_open as f64 * 0.6 {
            score += 25.0 * (1.0 - progress);
        }
        score -= 2.0 * progress; // late stream: opening fresh bins is fine
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover belongs to a
    // "reusable" residue class (multiples of 10, and small leftovers that
    // still admit mid-size items) are rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class A: post_residual divisible by 10 -> clean harmonic slot.
    if post_residual % 10 == 0 {
        score -= 12.0;
    }
    // Class B: post_residual divisible by 5 (half-class, slightly weaker).
    else if post_residual % 5 == 0 {
        score -= 6.0;
    }
    // Class C: dead space — leftover too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Integer-division thresholds on post_residual: which lookahead classes fit?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Lookahead item fits here: strong reward, scaled by how "tight"
            // the future fit is (small slack after the pair = good packing).
            let pair_slack = post_residual - next_item_size;
            score -= 18.0 + (pair_slack.min(30) as f64) * 0.3;
            // Harmonic bonus: next item's residue class matches capacity grid.
            if next_item_size % 10 == 0 { score -= 6.0; }
        } else {
            // Lookahead cannot use this bin's leftover; penalize proportionally
            // to the wasted fraction, with a modulo-10 harmonic penalty.
            let miss = (next_item_size - post_residual) as f64;
            score += 4.0 + miss * 0.15;
            if next_item_size % 10 != 0 { score += 3.0; }
        }
    }

    // Capacity-fraction coupling: favor placements where item_size lands on
    // capacity fractions (1/4, 1/2, 3/4 of C) — classic harmonic anchors.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarter = 3 * quarter;
    if item_size == quarter || item_size == half || item_size == three_quarter {
        score -= 5.0;
    }

    // Perfect fit dominates everything.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < 10 {
        score -= 15.0; // accept the small dead space rather than open a bin
    }

    // Late in the stream, consolidate: prefer existing bins over new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early (fresh space), penalized later.
        score = cap - 8.0 * (1.0 - progress) + 10.0 * progress;
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 5.0; // big lookahead item: fresh bin is safer
        }
    } else {
        // Slight global pressure toward bins with above-mean free space.
        score -= (post - mean_residual) * 0.05;
    }

    // Mild tie-breaker noise via deterministic hash-like mixing of residuals.
    let mix = ((post_residual as i64).wrapping_mul(2654435761)
        .wrapping_add((item_size as i64).wrapping_mul(40503))
        .wrapping_add(step_index as i64)) & 0x7;
    score += mix as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are unusable.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        score -= 60.0; // perfect packing: fully consumed or near-consumed bin
    } else if post_residual <= 20 {
        // small gap: likely dead space, but slightly less catastrophic
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Reward exact-ish fits relative to capacity
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 30.0;

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no existing bin fits well (last-chance pressure) or bins are very full.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            // last chance bin: prefer it over a new bin unless fit is terrible
            score += 25.0;
        } else {
            score += 55.0 + (open_bins_count as f64) * 2.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward leaving useful space
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.8;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Open-bin pressure: discourage scattering across many bins
    score += (open_bins_count as f64) * 0.5;

    // Prefer bins with residual below mean (consolidate emptier space elsewhere)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Mild progression term: later in stream, be greedier about tight fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= tightness * 20.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: strongly favor bins whose post_residual is tiny.
    if post_residual <= 2 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // 2-step lookahead: reward when the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            // Next item fits: penalize leftover slack after the hypothetical pairing.
            let after_next = post_residual - next_item_size;
            score -= 20.0;
            score += after_next as f64 * 0.6;
        } else {
            // Next item does not fit here: penalize large unmatchable slack.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.25;
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving less slack than average is good (tighter packing).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using the only bin that can fit the item
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize wasting a nearly-empty bin's utility; discourage opening a new bin
    // when a good fit exists in an open bin.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty so it only wins when open bins are poor.
        score += 15.0;
        // Early in the stream, opening bins is cheap; later, prefer filling open ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > 50 {
            score -= 10.0;
        }
    } else {
        // Reward using bins that are already substantially filled.
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill_ratio * 10.0;
    }

    // Mild penalty for having many open bins (encourage consolidation).
    score += open_bins_count as f64 * 0.05;

    // Dead-space penalty: post_residual that no typical item (>=1) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0; // tiny unusable slivers are wasteful unless lookahead matched
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    score -= (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Penalize wasted large residuals relative to mean residual across bins.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.35;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // Lookahead coupling: if the next item can fit into the post_residual,
    // reward this placement; otherwise penalize creating a residual that
    // wastes the next item's potential.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let snug = (post_residual - next_item_size) as f64;
            score -= 12.0 - (snug / bin_capacity as f64) * 20.0;
        } else {
            score += 4.0;
        }
    }

    // New-bin candidate handling: opening a bin is penalized, but less so
    // when the item is large relative to capacity or many bins are open.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        score += 18.0 - item_frac * 22.0;
        if open_bins_count > 6 {
            score -= (open_bins_count as f64 - 6.0) * 1.5;
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0;
        }
    }

    // Time-horizon modulation: early in the stream, be more conservative
    // with tight fits (keep flexibility); late, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (post_residual as f64 / bin_capacity as f64) * 15.0;

    // Mild penalty for leaving many open bins around.
    score += open_bins_count as f64 * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let prog_sq = progress * progress;

    // Tightness: fraction of bin filled by this item
    let fill = item_size as f64 / cap;
    let post_frac = post_residual as f64 / cap;

    // Reward tight fits (low post_residual) more strongly as stream progresses
    let tight_reward = (1.0 - post_frac) * (1.0 + prog_sq * 2.0);
    score -= 4.0 * tight_reward * fill;

    // Penalize dead space: post_residual that cannot hold typical future items
    let dead = (post_frac - 0.1).max(0.0);
    score += 3.0 * dead * dead * (1.0 + prog_sq);

    // Lookahead coupling: if next item fits in post_residual, reward leaving that gap
    if next_item_size > 0 && next_item_size as f64 <= post_residual as f64 {
        let gap_quality = 1.0 - ((post_residual as f64 - next_item_size as f64) / cap);
        score -= 2.5 * gap_quality * (1.0 + progress);
    } else if next_item_size > 0 {
        // Penalize leaving a gap that next item cannot use
        score += 1.5 * post_frac * (0.5 + prog_sq);
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate: make it less attractive unless open bins are all poor fits
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / cap * 10.0);
        score += 6.0 + congestion * (0.5 + progress);
        // If mean residual is large, opening a new bin is wasteful
        score += mean_residual * 0.05;
    }

    // Mild preference for bins already below mean residual (consolidation)
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= 0.3 * diff.max(0.0) / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual classes that are hard to fill
    // (small but nonzero leftovers) are penalized; perfect fits rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    if post_residual == 0 {
        score -= 40.0; // perfect fit
    } else if post_residual < 10 {
        score += 25.0; // tiny dead space, unusable
    } else {
        // integer-division thresholds: residual bucket classes
        let bucket = post_residual / 10; // 1..=10
        score += (bucket as f64) * 1.5;
        // modulo arithmetic: residuals near multiples of 25 pair well with mid items
        let m = post_residual % 25;
        if m == 0 { score -= 6.0; }
        else if m < 5 { score += 4.0; }
        // capacity fraction classes
        let frac = pr / cap;
        if frac > 0.5 { score -= 5.0; } // still roomy bin, good target
        else if frac < 0.1 { score += 8.0; }
    }

    // Lookahead: favor leaving room for the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // exact harmonic match: next item fills residual perfectly
            if post_residual == next_item_size { score -= 15.0; }
            // modulo class: post_residual % next_item_size small => future fits stack
            let r = post_residual % next_item_size;
            score -= (5.0 - (r as f64).min(5.0)) * 0.8;
        } else {
            // next item won't fit here; penalize proportionally to wasted gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        // base penalty so open bins are preferred unless they score badly
        score += 20.0;
        if fitting_bins_count == 0 { score -= 100.0; }
        // late in stream, prefer closing out open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
    }

    // spread awareness: when many bins open, tighten packing
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;
    score += (mean_residual - pr) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A residual is "dead" if it is too small for the smallest plausible item (1..100 range,
    // assume min item ~10). Penalize post_residual in the dead zone super-linearly.
    let dead_threshold = 10.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0 + 15.0;
    }
    // Perfect fit bonus: exact fill.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Non-linear reward for tight fits (small but usable residuals are fine).
    let pr = post_residual as f64;
    score += (pr * pr) / (bin_capacity as f64);

    // Open bins pressure: with many open bins, discourage opening new ones
    // and favor filling existing ones.
    let bin_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // Candidate is a brand-new bin: penalize proportionally to open bins count.
        score += bin_pressure * 5.0;
        // But if no open bin fits well, new bin may be OK: soften when fitting bins are scarce.
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly reward using it rather than opening a new bin.
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0;
    } else if next_item_size > 0 && pr > 0.0 && (next_item_size as u32) > post_residual {
        // Next item won't fit here anyway; mild penalty for leaving awkward gap.
        score += 3.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // (filling bins with large residuals first keeps small residuals usable).
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Stream progression: late in stream, be more aggressive about closing bins tightly.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += pr * progress * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward residuals that exactly fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff < 1.0 {
            score -= 400.0;
        } else {
            score -= 150.0 / (1.0 + diff);
        }
        // Penalize post_residual that is too small to hold the next item (dead space risk)
        if (post_residual as u32) < next_item_size && post_residual > 0 {
            score += 0.5 * (nxt - post_residual as f64);
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Penalize opening a new empty bin unless current fit is terrible
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        score += 60.0 + 80.0 * (1.0 - fit_quality);
    }

    // Late-stream consolidation pressure
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits with a non-linear term (small residuals are precious).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * tightness * tightness;

    // Lookahead: if the next item also fits in the post-residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if the pair nearly fills the bin (perfect 2-item packing).
        let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
        if pair_fill > 0.9 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space that cannot serve the next item: penalize proportionally.
        let dead = post_residual as f64 / next_item_size.max(1) as f64;
        score += 3.0 * dead.min(1.0);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count > 0 {
            mean_residual / bin_capacity as f64
        } else {
            0.0
        };
        // Default mild penalty; reduced when open bins have large residuals (poor fits anyway).
        score += 15.0 - 10.0 * pressure.min(1.0);
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
    }

    // Global balance: prefer bins whose residual is far from the mean residual
    // (keeps a diverse residual portfolio for future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer filling bins when many are open (bin-count control).
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Small late-stream urgency: near the end, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear coupling: residual penalty shaped by stream progress
    let shape = 1.0 + 2.0 * progress * (1.0 - progress) * 4.0;
    score += shape * norm_pr * norm_pr * 30.0;

    // Smooth polynomial interaction between post_residual and progress
    let poly = norm_pr * (1.0 - norm_pr);
    score -= poly * (20.0 + 40.0 * progress);

    // Tight fits favored, scaled by progress
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 15.0 * (0.5 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize opening bins early, more later if open bins exist
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress * (open_bins_count as f64).sqrt();
    }

    // Mean residual drift term
    score += (mean_residual - pr) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common
    // item-size classes (multiples of 10/20/25) are more reusable.
    let r = post_residual;
    if r > 0 {
        let harmonic_bonus = if r % 10 == 0 {
            18.0
        } else if r % 25 == 0 {
            12.0
        } else if r % 20 == 0 {
            10.0
        } else if r % 5 == 0 {
            6.0
        } else {
            0.0
        };
        score -= harmonic_bonus;

        // Dead-space penalty: tiny non-harmonic residuals are wasted space.
        if r < 10 && r % 5 != 0 {
            score += 30.0;
        }
    } else {
        // Perfect fit: heavily reward closing the bin exactly.
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // this placement is excellent (chained fit).
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 45.0;
        } else if next_item_size <= r {
            let slack = (r - next_item_size) as f64;
            // Reward if the leftover after the next item is again harmonic.
            let nr = slack as u32;
            if nr % 10 == 0 {
                score -= 15.0;
            } else if nr % 5 == 0 {
                score -= 7.0;
            }
            score += slack * 0.15;
        } else {
            // Next item cannot use the residual; residual likely dead.
            score += 10.0;
            // But if residual is a multiple of 10, other future items may use it.
            if r % 10 == 0 {
                score -= 5.0;
            }
        }
    }

    // Last-chance logic: this bin is the only one that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Prefer new bin only when existing fits are poor (large post_residual
        // relative to capacity) or when few bins are open early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let waste = (post_residual as f64 / bin_capacity as f64) * 40.0;
        score += waste;
        // Slight bias against opening new bins when many bins already open.
        score += (open_bins_count as f64).sqrt() * 2.0;
        // Late in the stream, consolidating into open bins matters more.
        score += progress * 8.0;
        // If next item is small, a fresh bin can absorb two items: mild bonus.
        if next_item_size > 0 && next_item_size * 2 <= bin_capacity {
            score -= 6.0;
        }
    }

    // Mild pull toward bins whose residual is close to the mean (balance).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 5.0;

    // Integer-division threshold: reward post_residual in the "sweet spot"
    // [20, 50] where most item sizes (10..80 truncated) still fit.
    if r >= 20 && r <= 50 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, 12) are "unusable" gaps
    // (items are >= 1, but small gaps waste capacity almost surely).
    if post_residual > 0 && post_residual < 12 {
        score += 40.0 + 3.0 * (12.0 - post_residual as f64);
    }

    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward bins whose residual is close to item_size (tight fit),
    // penalize loose fits leaving large slack relative to item size.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 25.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += 1.5 * open_bins_count as f64 * (1.0 - tightness.clamp(0.0, 1.0));

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, but relax the penalty
    // when the current item would leave a large awkward residual in all bins
    // or when the next item is large and a fresh bin is more useful.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 20.0;
        if post_residual >= 12 {
            new_bin_penalty -= 8.0;
        }
        if next_item_size > 0 && next_item_size as f64 >= mean_residual {
            new_bin_penalty -= 12.0;
        }
        if fitting_bins_count == 0 {
            new_bin_penalty = 0.0;
        }
        score += new_bin_penalty;
    }

    // Lookahead: if next item exactly matches this bin's post_residual,
    // strongly favor placing here (chain packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }

    // Mild preference to fill older bins early in the stream.
    score += 5.0 * (1.0 - step_index as f64 / total_items.max(1) as f64) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly matches the next item size (chained perfect fit).
    if next_item_size > 0 && post_residual > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if gap == 0 {
            score -= 400.0;
        } else if gap <= 5 {
            score -= 40.0;
        } else {
            score += gap as f64 * 0.5;
        }
    }

    // Compare post_residual against the mean residual across open bins:
    // leaving less residual than average is good (tight packing).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin when the item fits reasonably well elsewhere.
    if bin_residual == bin_capacity {
        score += 120.0;
        // But if the item nearly fills a fresh bin, opening may be fine.
        if post_residual <= 10 {
            score -= 150.0;
        }
        // Late in the stream, prefer closing out existing bins.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 50.0;
        }
    }

    // Penalize large dead space that nothing (>=10) can ever use.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose post-residual is small.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Exact-fill bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Penalize leaving dead space that no plausible item can fill.
    // Items are >= 1; residual below the smallest next-item is partially wasted,
    // but small residuals (< ~10) are nearly dead weight.
    let dead = if post_residual > 0 && post_residual < 10 { (10 - post_residual) as f64 } else { 0.0 };
    score += 1.5 * dead;

    // Lookahead coupling: reward residuals that can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0;
            // Extra reward when post-residual is a snug host for the next item.
            let snug = (post_residual - next_item_size) as f64;
            score -= 2.0 * (-snug / 15.0).exp();
        } else {
            // Post-residual too small for next item: mild penalty scaled by how close it is.
            score += 1.0 + (next_item_size - post_residual) as f64 / 50.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a new bin is expensive when many bins
    // are already open; encourage consolidation early, allow fresh bins when
    // open bins have large mean residual (fragmented state).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 12.0
            + 3.0 * (open_bins_count as f64).ln()
            - 5.0 * fragmentation / bin_capacity as f64
            - 4.0 * progress;
        // If no existing bin fits, opening is inevitable: soften the penalty.
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
    } else {
        // Slight preference for bins with residual far below mean (denser bins).
        let density = (bin_residual as f64 - mean_residual).max(0.0);
        score += 0.05 * density;
    }

    // Mild late-stream consolidation: toward the end, prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Tight fit reward: quadratic coupling of post_residual with progress.
    let tight = 1.0 - (post_residual as f64 / cap);
    score -= 20.0 * tight * tight * (0.5 + progress);

    // Penalize leaving residuals that are hard to fill (large dead space mid-range).
    let pr = post_residual as f64;
    score += 0.15 * (pr / cap) * (1.0 - (pr / cap)) * (1.0 + progress);

    // Lookahead: reward residuals that can hold the next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 8.0 * (n / cap) * (1.0 - progress);
        } else {
            score += 6.0 * (1.0 - n / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Late in the stream, prefer consolidating into fewer bins.
    score += 0.5 * (open_bins_count as f64) * progress * (pr / cap);

    // Prefer bins whose residual is below the mean residual (denser bins).
    score += 0.1 * (mean_residual - bin_residual as f64).max(-cap) * progress;

    // Mild penalty for opening a new bin when other bins could fit.
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact quarter classes of capacity.
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter; // 0..4
    match class {
        0 => score -= 30.0,                       // near-perfect fit
        1 => score -= 12.0,                       // good fit
        2 => score += 0.0,                        // neutral
        3 => score += 10.0,                       // poor fit, lots of dead space
        _ => score += 5.0,                        // empty-ish bin
    }

    // Exact modulo harmony: post_residual divisible by common item granularities
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 5 == 0 { score -= 2.0; }
    } else {
        score -= 25.0; // bin perfectly closed
    }

    // Lookahead coupling: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            // harmonic bonus if next item also lands on a class boundary
            if (post_residual - next_item_size) % 10 == 0 { score -= 5.0; }
        } else {
            // next item won't fit here; penalize wasting capacity on stranded space
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 8.0 * waste;
        }
    } else {
        // last item: closing bins is free bonus
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: prefer reuse unless fit is terrible
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // opening a new bin: baseline cost grows with number of open bins
        score = 55.0 + open_bins_count as f64;
        // late in the stream, prefer consolidation into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // if only few bins fit the item, opening new is less attractive
        score += 10.0 * (fitting_bins_count as f64).min(3.0);
    } else {
        // tightness ratio reward: smaller relative leftover is better
        score += 5.0 * (post_residual as f64 / bin_residual.max(1) as f64);
        // mild penalty for spreading across many open bins when mean residual is large
        if post_residual as f64 > mean_residual {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize gaps that no plausible future item (min size 1..100) could use well:
    // gaps just above a "typical" small item are dead space.
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open bins pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize unless current bin fit is bad.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if placing here would leave a dead gap elsewhere... prefer new bin
        // when the item fits badly in every open bin.
        if post_residual >= 50 {
            score -= 20.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Tightness coupling: reward filling bins deeply.
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Mean residual deviation: prefer bins whose residual is below mean (denser bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base penalty on wasted residual (dead space), super-linear.
    let pr = post_residual as f64;
    score += 0.35 * pr * pr / bin_capacity as f64;

    // 2-step lookahead: reward exact match of post_residual to next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        if gap < 1.0 {
            score -= 60.0; // perfect chain: next item exactly fills this bin
        } else if nxt <= pr {
            // next item fits here: reward tightness of the two-step packing
            score -= 30.0 * (nxt / (pr + 1.0)) - 0.15 * gap;
        } else {
            // next item cannot use the leftover: penalize unusable remainder
            score += 0.25 * (nxt - pr).min(pr);
        }
    }

    // Compare against mean residual: prefer bins whose post_residual diverges
    // from mean toward small values (consolidating space).
    score += 0.20 * (pr - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only when no open bin gives a tight fit.
    if bin_residual == bin_capacity {
        let tight_available = fitting_bins_count > 0 && (bin_residual - item_size) < 15;
        if tight_available {
            score += 45.0; // an open bin fits tightly; don't open a new one
        } else {
            score -= 10.0; // poor fits everywhere; fresh bin is reasonable
        }
    }

    // Late in the stream, prefer closing bins tightly (fewer wasted openings).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional waste: residual that is too small for the minimum item (1) is pure loss,
    // but with sizes >=1 everything can eventually fit; penalize tight leftovers mildly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Lookahead coupling: reward a post_residual that exactly (or nearly) fits the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if post_residual >= next_item_size {
            // next item fits here: reward closeness to perfect pairing
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit: penalize dead space proportional to gap
            score += 0.5 * gap;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is fine early, costly late or when many bins are open.
        score += 25.0 + 40.0 * progress + 1.5 * open_bins_count as f64;
        // But if no open bin fits well (this call happens alongside fitting bins),
        // keep it competitive: the base score (post_residual == capacity) is high anyway.
    } else {
        // Prefer bins whose residual is close to the item (good fit).
        let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= 15.0 * fit_ratio;
    }

    // Global state coupling: if mean residual across open bins is high, we have slack;
    // encourage filling bins with large residuals, discourage when slack is low.
    let slack = mean_residual / bin_capacity as f64;
    score += 10.0 * (slack - post_residual as f64 / bin_capacity as f64);

    // Mild time decay: as the stream progresses, favor compact packing (low post residual).
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fills (quadratic growth in post_residual).
    // Late: dead space is costlier, so apply a super-linear penalty.
    let mut score = pr / cap;
    let quad = (pr / cap) * (pr / cap);
    score += quad * (1.0 + 2.0 * progress);

    // Perfect fit reward (post_residual near zero)
    score -= 3.0 * (1.0 - pr / cap).powi(6);

    // Penalize residuals that are too small to ever fit future items
    // (dead space): residual below typical minimum item size
    let dead = (1.0 - pr / cap).powi(3);
    score += 2.0 * dead * (1.0 - progress);

    // Last chance bin: strongly reward using it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 5.0;
    }

    // Lookahead: reward if next item fits into the resulting post_residual
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr as f64 >= ni {
            // smooth reward, stronger the tighter next item fits
            score -= 1.5 * (1.0 - (pr - ni) / cap);
        } else {
            // next item won't fit here; mild penalty proportional to wasted potential
            score += 0.5 * (ni - pr) / cap;
        }
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize outliers mildly via smooth coupling
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 0.3 * dev * dev;

    // Slight preference for consolidating into fewer bins when many are open
    score += 0.05 * open_bins_count as f64 / (1.0 + progress);

    // New-bin candidate: make it unattractive unless it's genuinely better
    // (empty bin has pr == cap, quad term handles most of it; add explicit offset)
    if bin_residual == bin_capacity {
        score += 1.0 + 0.5 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction slot does it fall in?
    // Residuals in (0,10] are "dead" space; (10,25] can host small items; etc.
    let dead = if post_residual == 0 { 0.0 } else if post_residual <= 10 { 60.0 } else if post_residual <= 25 { 20.0 } else if post_residual <= 50 { 5.0 } else { 0.0 };
    score += dead;

    // Lookahead harmony: does the next item fit into the post residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        // Reward tight pairings more when the leftover after the pair is small
        let pair_left = post_residual - next_item_size;
        score -= 25.0 + 15.0 * (pair_left as f64 / cap);
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // Next item fits the bin but not after this placement: mild penalty
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin generally, scaled by how many bins could fit
        let mut penalty = 30.0 + 5.0 * open_bins_count as f64;
        // If the item would leave a large residual in an existing bin anyway,
        // opening fresh is less bad
        if fitting_bins_count == 0 {
            penalty = -10.0;
        } else if post_residual <= 10 {
            penalty -= 20.0;
        }
        score += penalty;
    } else {
        // Tight fit reward: item fills most of the residual
        let fill = item_size as f64 / bin_residual as f64;
        score -= 20.0 * fill * fill;

        // Reward exact closure
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is near the mean (keeps balance),
    // unless it's the new bin
    if !is_new_bin {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.1 * dev;
    }

    // Stream progression: early on, be conservative about tight fits (keep flexibility);
    // late in the stream, prioritize closing bins aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - fill_gate(post_residual, cap));

    score
}

#[inline]
fn fill_gate(post_residual: u32, cap: f64) -> f64 {
    // Harmonic gate: 1 when residual is a "useful" class, 0 when dead
    if post_residual == 0 { 1.0 } else if post_residual as f64 <= 0.1 * cap { 0.0 } else { 0.5 }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item
    // (items are 1..100, but small gaps are only usable by tiny items).
    let min_useful = next_item_size.min(10).max(1) as f64;
    if (post_residual as f64) < min_useful {
        // Completely dead gap: heavy penalty, worse the bigger the wasted chunk.
        score += 40.0 + 0.5 * post_residual as f64;
    } else if (post_residual as u32) < next_item_size && next_item_size > 0 {
        // Gap can't hold the lookahead item: moderately undesirable.
        score += 12.0;
    } else if next_item_size > 0 && post_residual == next_item_size {
        // Perfect fit for the lookahead item: strong reward.
        score -= 25.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 8.0 * tightness;

    // Penalize leaving exactly awkward mid-range gaps (e.g. 1..9) extra hard
    // since few items are that small.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading out; a new empty bin should lose unless fit is bad.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // If this is the last bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make the empty bin unattractive unless existing bins
    // would create severe dead space.
    if bin_residual == bin_capacity {
        score += 35.0 + 2.0 * open_bins_count as f64;
        // But if all open bins would leave dead space, allow opening a new bin.
        let all_bad = fitting_bins_count == 0
            || (mean_residual - item_size as f64) < 0.0;
        if all_bad {
            score -= 60.0;
        }
    }

    // Mild alignment with mean residual: prefer bins whose residual is below
    // average (they are the "fuller" bins, keep emptier bins flexible).
    if bin_residual as f64 > mean_residual {
        score += 3.0;
    } else {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64;

    // 2-step lookahead: reward when next item exactly fills the remaining space
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.8;
        // Perfect chain: post_residual == next_item_size -> strong reward
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Next item slightly smaller than residual: still good chain
        if next_item_size <= post_residual && gap <= 10.0 {
            score -= 8.0;
        }
        // Next item cannot use residual at all: dead space penalty scaled by dead space
        if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Relative to mean residual: bins with residual far below mean are "tight" -> prefer filling them
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when good fitting bins exist
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if no open bin fits well (post_residual large elsewhere), new bin is fine
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Late in stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Penalize leaving large unusable fragments
    if post_residual < 10 {
        score -= 5.0; // near-perfect fill is excellent
    } else if post_residual < 20 {
        score -= 2.0;
    }

    // Slight penalty for many open bins (encourage consolidation)
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-perfect fits nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Dead-space penalty: residual too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist; keep flexibility.
        score += 1.5 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Lookahead coupling: if the next item fits the post-residual, reward;
    // if next item is large and this bin would be badly fragmented, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            score += 2.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Global state: prefer filling bins when many bins are open (consolidation).
    score -= (open_bins_count as f64).ln() * 1.2;

    // Mean-residual coupling: bins far below mean residual are good candidates
    // to drain; bins above mean are worth preserving for future large items.
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 5.0 * dev;

    // Time horizon: early in stream, favor keeping residuals balanced;
    // late in stream, prioritize closing bins out aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * tightness;

    // New-bin candidate: only attractive when current item is large relative
    // to capacity or no good open fit exists.
    if bin_residual == bin_capacity {
        let large = (item_size as f64) / (bin_capacity as f64);
        score += 4.0 + 10.0 * (1.0 - large);
        if fitting_bins_count <= 1 {
            score -= 18.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post residual (tight fits).
    let mut score = pr;

    // Non-linear reward for very tight fits (quadratic coupling with progress):
    // tightness quality q in [0,1], 1 = perfect fit.
    let q = 1.0 - pr / cap;
    let tightness_reward = q * q * (1.0 + 2.0 * progress) * 0.35 * cap;
    score -= tightness_reward;

    // Smooth penalty for mid-range dead space that is hard to fill later:
    // penalize residuals near ~half capacity most (hard-to-reuse zone),
    // modeled as a smooth bump: 4*x*(1-x) peaks at x=0.5.
    let x = pr / cap;
    let dead_zone = 4.0 * x * (1.0 - x);
    score += dead_zone * 0.12 * cap * (0.5 + 0.5 * progress);

    // Lookahead coupling: if next item fits exactly into post_residual,
    // reward this placement smoothly (sigmoid-like on gap).
    if next_item_size > 0 {
        let gap = (pr as i64 - next_item_size as i64).abs() as f64;
        let match_bonus = (-gap / 8.0).exp() * 0.25 * cap;
        score -= match_bonus;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin (smooth in fitting_bins_count).
    if fitting_bins_count >= 1 {
        let last_chance = 1.0 / fitting_bins_count as f64;
        score -= last_chance * 0.30 * cap;
    }

    // New-bin candidate handling: residual == capacity. Mildly penalize opening
    // new bins when existing bins exist and mean residual is healthy, but relax
    // as stream progresses (late items may warrant fresh bins).
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 0.20 * cap + open_pressure * 2.0 * (1.0 - progress) - progress * 0.05 * cap;
        // If no open bin could fit (fitting_bins_count==0 means only new bin call), drop penalty.
        if fitting_bins_count == 0 {
            score -= 0.25 * cap;
        }
    }

    // Mean residual coupling: bins far below mean residual are "lonely" —
    // prefer filling them to consolidate open bins.
    let deviation = (pr - mean_residual) / cap;
    score += deviation * 0.10 * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize leftover space into coarse buckets.
    // Small post-residuals are good; large ones waste capacity.
    let post = post_residual as f64;
    let class = (post / 10.0).floor(); // integer division-like threshold on post_residual
    score += class * class * 0.35;     // quadratic penalty on coarse waste class

    // Perfect fit bonus (harmonic closure: residual becomes exactly zero)
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tiny unusable residue is slightly worse than a mid-range residue that can
    // still host a small future item (1..=10). Penalize dead space < 10.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: does the leftover exactly host the next item?
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 >= nx {
            score -= 6.0 + 4.0 * (nx / cap); // prefer bins that also fit next item
            // Harmonic exactness: leftover equals next item size -> ideal chain
            if post_residual as u32 == next_item_size {
                score -= 10.0;
            }
        } else {
            score += 3.0; // this bin becomes dead after placement
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly,
        // i.e. the best existing post-residual would be large. We don't know the
        // best alternative directly, so use mean_residual as proxy for crowding.
        // Base cost of a fresh bin:
        score = cap - item_size as f64; // waste = capacity - item in fresh bin
        score += 20.0;                 // fixed opening cost
        // If many bins are open and mean residual is small, opening is wasteful.
        score += open_bins_count as f64 * 1.5;
        if mean_residual >= item_size as f64 + 5.0 {
            score += 30.0; // some bins likely have room; avoid new bin
        }
        // Large items relative to capacity fit poorly anywhere; allow new bin.
        if item_size as f64 > 0.6 * cap {
            score -= 25.0;
        }
        // Early stream: opening bins is cheap and useful for future flexibility.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        return score;
    }

    // Prefer bins whose residual is close to item size (tight fit, Best-Fit flavor)
    let tightness = (bin_residual as f64 - item_size as f64) / cap;
    score += 5.0 * tightness * tightness * cap / 10.0;

    // Mild preference for bins with below-average residual (fill crowded bins first)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold any item (1..=100 range)
    // are pure waste; the smaller the dead gap, the harsher the penalty.
    let dead_limit = 10u32;
    if post_residual > 0 && post_residual < dead_limit {
        score += (dead_limit - post_residual) as f64 * 6.0; // up to +54 for a 1-unit sliver
    }

    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize residuals that cannot fit the lookahead item (creates stranded space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }
    // Reward residuals that can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 25.0;

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize the new-bin candidate which has bin_residual == bin_capacity).
    let pressure = (open_bins_count as f64).sqrt() * 3.0;
    if bin_residual == bin_capacity {
        score += pressure + 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (keeps residuals balanced and reusable).
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Early in the stream, allow slightly more freedom; later, be stricter on waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a non-linear push
    // toward near-perfect packing.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);

    // 2-step lookahead: strongly reward when the next item exactly fills the
    // remaining space of this bin.
    if next_item_size > 0 {
        let post_f = post_residual as f64;
        let next_f = next_item_size as f64;
        if next_f <= post_f {
            let gap = post_f - next_f;
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 30.0; // perfect 2-chain: this bin will be closed next step
            }
        } else {
            // Next item cannot fit here: post_residual is likely dead space,
            // penalize proportionally to how far off it is.
            score += 4.0 * (next_f - post_f) / bin_capacity as f64;
        }
    }

    // Compare post_residual against mean residual across open bins: leaving
    // below-average residual is good (bin was efficiently used).
    if mean_residual > 0.0 {
        let diff = post_residual as f64 - mean_residual;
        score += 0.6 * diff;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // heavily favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin gets a moderate penalty so we
    // only open a new bin when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 18.0;
        // Early in the stream, opening bins is cheaper (more future items to
        // fill them); relax the penalty as the stream progresses.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 10.0 * progress;
        }
    }

    // Slight preference to keep the number of open bins manageable.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (dead-space minimization).
    let cap = bin_capacity as f64;
    let fit_tightness = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * fit_tightness * fit_tightness * fit_tightness;

    // Penalize residuals that become "dead" (too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits into post-residual exactly well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain fill
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score += 0.35 * slack; // mild penalty for leftover slack after next item
        } else {
            score += 8.0; // next item can't use this bin's leftover
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when existing bins fit, scaled by how many fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count > 0 {
            score += 15.0 + 6.0 * (fitting_bins_count as f64);
        } else {
            score -= 10.0; // must open new bin anyway
        }
    } else {
        // Reward packing into already-open bins, more so early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 5.0 * (1.0 - progress);
    }

    // Prefer bins whose residual deviates from the mean (consolidate fullness).
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 0.15 * dev;
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.4 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, compactness matters more (tight packing preferred).
    let compactness = post / cap;
    score += (compactness * compactness) * (1.0 + 3.0 * progress) * 30.0;

    // Penalize poor fits (item barely fits) — wasted space risk.
    score += 20.0 * fit_ratio * fit_ratio;

    // Reward near-perfect fills strongly.
    if post == 0 {
        score -= 60.0;
    } else if post <= 10 {
        score -= 25.0 * (1.0 + progress);
    }

    // Dead-space penalty: residual too small for typical future items.
    let dead = (post - 10.0).max(0.0).min(10.0);
    score -= dead * 0.5; // mild reward for residual in 10..20 usable band
    if post > 0 && post < 10 {
        score += 15.0; // unusable sliver
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, bonus.
    if next_item_size > 0 {
        let nd = (post - next_item_size as f64).abs();
        if next_item_size as f64 <= post {
            score -= 15.0 * (1.0 - nd / cap);
        } else {
            score += 5.0 * (1.0 - post / cap);
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (denser bins).
    score += (mean_residual - post) * 0.3;

    // New-bin candidate handling: empty bin (residual == capacity).
    // Opening a new bin is costly; only attractive if all existing fits are bad
    // (large fit_ratio) or many bins already open.
    if bin_residual == bin_capacity {
        score += 55.0 - 25.0 * fit_ratio + open_bins_count as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: post_residual in low harmonic classes is very desirable.
    if post_residual == 0 {
        score -= 200.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 100.0;
    } else if post_residual <= 10 {
        score -= 50.0;
    } else if post_residual <= 20 {
        score -= 20.0;
    }

    // Harmonic class logic: penalize residuals in "dead zones" that few item
    // sizes can fill. Classes based on integer division of post_residual.
    let cls = post_residual / 10; // class 0..10
    let class_penalty: [f64; 11] = [0.0, 0.0, 5.0, 10.0, 25.0, 35.0, 40.0, 45.0, 50.0, 55.0, 60.0];
    score += class_penalty[cls as usize];

    // Lookahead coupling: if next item fits the post_residual exactly or well,
    // reward this placement (chain packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit_gap = post_residual - next_item_size;
        if next_fit_gap == 0 {
            score -= 60.0;
        } else if next_fit_gap <= 10 {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this residual: penalize proportionally.
        score += (next_item_size as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins have poor residuals relative to the item.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 70.0;
        if fitting_bins_count == 0 {
            score -= 150.0; // no alternative, must open
        } else if fitting_bins_count == 1 {
            score += 0.0; // last-chance bin will usually win anyway
        } else {
            // More fitting bins -> prefer using one of them.
            score += (fitting_bins_count as f64) * 8.0;
        }
        // If mean residual is large and could hold item, discourage new bin.
        if mean_residual >= item_size as f64 {
            score += 40.0;
        }
        // Early in stream, opening bins is cheaper (future flexibility).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
    }

    // Mild preference to spread load when many bins open (balance residuals).
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post residual, but penalize "dead" gaps that
    // are too small to be useful for typical future items.
    let dead_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Perfect / near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    }

    // Reward filling a bin that is the only option (avoid opening new bins).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Pressure: with many open bins, strongly prefer consolidating.
    let open_pressure = (open_bins_count as f64).powf(1.3) * 0.8;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // If the next item fits exactly in the post residual, reward keeping it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // Penalize leaving a gap the next item cannot use.
    if next_item_size > post_residual && post_residual > 0 && bin_residual != bin_capacity {
        score += 10.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how fragmented open bins are.
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let mut new_bin_score = 55.0 - fragmentation * 30.0;
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0; // must open a bin
        }
        // Early in stream, opening bins is cheaper; late, consolidate harder.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score += progress * 25.0;
        score += new_bin_score;
    } else {
        // Existing bin: slight bonus for using well-worn bins.
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        }
    }

    // Slight preference for bins whose residual is close to item size (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space nonlinearly, worse for small residuals.
        let pr = post_residual as f64;
        score += 30.0 / pr.sqrt();
    }

    // 2-step lookahead: if the next item fits exactly into post_residual,
    // this placement creates a perfect chain.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            let leftover = (post_residual - next_item_size) as f64;
            score -= 120.0 - 2.0 * leftover;
        } else {
            // Next item cannot follow into this bin: penalize wasted potential.
            score += 40.0;
        }
    }

    // Relative to mean residual: prefer bins whose post_residual stays
    // near the mean (balanced packing) unless it's a tight fit.
    let pr = post_residual as f64;
    let dev = (pr - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        score += 50.0 + 2.0 * openness;
        // Allow opening a new bin when current item is large and next is large too
        if next_item_size >= item_size {
            score -= 30.0;
        }
    }

    // Late in the stream, prefer tightening existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize small post-residuals that are still "wasted" (dead space below min item size 1..100 -> below 10 is dead).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0; // hard to fill
    }

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 14.0;
        // Extra reward if next item nearly fills the remaining space.
        let next_fit = next_item_size as f64 / post_residual as f64;
        score -= 10.0 * next_fit;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // Next item won't fit here; mildly penalize leaving awkward gap.
        score += 3.0;
    }

    // Time horizon: early in the stream, be more selective (penalize loose fits);
    // late in the stream, prefer packing into existing bins to avoid new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 4.0 * (bin_residual as f64 / bin_capacity as f64);
    score -= progress * 6.0 * (bin_residual != bin_capacity) as u32 as f64;

    // Global state: many open bins -> discourage opening yet another bin.
    score += 2.5 * (open_bins_count as f64).ln().max(0.0) * (bin_residual == bin_capacity) as u32 as f64;

    // Mean residual coupling: if this bin's residual is far below mean, it's an outlier bin; prefer consolidating into low-residual bins.
    let dev = mean_residual - bin_residual as f64;
    score += 0.08 * dev;

    // New-bin candidate baseline: empty bin should be chosen only when fits are bad.
    if bin_residual == bin_capacity {
        score += 22.0 + 0.5 * fitting_bins_count as f64;
        // But if next item is large and current item small, opening a fresh bin may be wise.
        if next_item_size >= item_size + 20 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling: penalize residual quadratically, modulated by progress
    score += 0.9 * (pr / cap) * (pr / cap) * cap * (0.4 + 0.6 * progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    let tightness = 1.0 - (pr / cap);
    score -= 12.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 6.0 * (1.0 - pr / cap);
        } else {
            score += 4.0 * (next_item_size as f64 - pr) / cap;
        }
    }

    // Dead-space penalty for very small unusable residuals
    if pr > 0.0 && pr < 10.0 {
        score += 8.0 * (1.0 - pr / 10.0);
    }

    // Mild preference for bins below mean residual (concentrate filling)
    score -= 0.05 * (mean_residual - pr);

    // New-bin candidate: keep neutral baseline, slightly penalized early, relaxed late
    if bin_residual == bin_capacity {
        score += 3.0 * (1.0 - progress) - 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space value depends on which
    // "next item class" it can still host. Items are 1..100, so classify
    // residual by integer division thresholds (harmonic buckets).
    let class = post_residual / 10; // 0..=10 harmonic bucket
    match class {
        0 => { score -= 40.0; }              // tiny residual: nearly perfect packing, great
        1 => { score -= 25.0; }              // 10..19 still hosts small items
        2 | 3 => { score -= 10.0; }          // 20..39 mid usefulness
        4 | 5 => { score += 5.0; }           // 40..59 awkward zone
        6 | 7 => { score += 15.0; }          // 60..79 large dead space
        _ => { score += 30.0; }              // 80+: huge waste, prefer new bin
    }

    // Coupling with lookahead item: reward residual that exactly hosts next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate penalty when decent fits exist
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0
            && open_bins_count > 0
            && mean_residual >= item_size as f64 * 0.8;
        if good_fit_exists {
            score += 60.0;
        } else {
            score -= 20.0;
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 30.0;
    }

    // Mild pressure to prefer tighter bins when many are open
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item (<= 10) are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Perfect fit is maximally attractive.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward residuals that can still accommodate the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Residual becomes dead space relative to the next item.
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage proliferation of bins when mean residual
    // is already low (bins nearly full), encourage consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * 2.0 * (1.0 - progress * 0.5);
    if bin_residual < bin_capacity {
        score -= pressure.min(10.0);
    }

    // New-bin candidate: only attractive if no open bin has a decent fit
    // (i.e., mean residual suggests open bins are nearly exhausted).
    if bin_residual == bin_capacity {
        let open_avg = mean_residual;
        score = 60.0 - open_avg * 0.5;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: new bin is fine
        }
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 10.0; // big items coming: fresh bin valuable
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step lookahead match: next item exactly fills the residual.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Reward near-matches where next item fits with small leftover.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let leftover_after_next = post_residual - next_item_size;
        score -= 30.0 - (leftover_after_next as f64).min(30.0);
    }
    // Penalize creating dead space smaller than the minimum plausible item (1..=100 range):
    // residual that is too small to be useful.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable gap
    }

    // Relative-to-mean coupling: bins with residual already below mean are "tighter";
    // prefer packing into tighter bins (classic best-fit pressure).
    let mean_gap = mean_residual - post_residual as f64;
    score -= mean_gap * 0.5;

    // Last-chance bin: strongly favor using the only bin that fits to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no good fit
    // exists (item barely fits anywhere) or the stream is early. Base cost for a new bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight_fit = (item_size as f64 / bin_capacity as f64) > 0.9;
        score += 45.0; // default cost of opening a new bin
        if tight_fit || (next_item_size > 0 && next_item_size >= post_residual) {
            score -= 30.0; // worth it when fit is poor elsewhere
        }
        if progress < 0.05 {
            score -= 10.0; // early stream: fresh bins cheap
        }
        score -= open_bins_count as f64 * 0.5;
    }

    // Mild preference for filling bins more completely relative to capacity.
    score += (1.0 - (item_size as f64 / bin_residual.max(1) as f64)) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: quadratic bonus for small post-residual.
    let tightness = (post_residual as f64) / cap;
    score -= 18.0 * (1.0 - tightness * tightness);

    // Penalize residuals that are too small to fit any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: strongly reward bins that leave room for the next item exactly,
    // penalize bins that block a well-fitting next placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let gap = post_residual as f64 - nxt;
            score -= 12.0 * (1.0 - gap / cap).max(0.0);
        } else if post_residual > 0 {
            score += 6.0 * (1.0 - post_residual as f64 / nxt);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual > 0 && post_residual < 5 {
            score += 30.0;
        }
    }

    // Global state: when many bins are open with large mean residual,
    // discourage opening new bins; encourage filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let openness = open_bins_count as f64 / (total_items.max(1) as f64).sqrt().max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: cost grows with open bins, mean residual, and early progress.
        score += 10.0 + 6.0 * openness + 0.15 * mean_residual + 15.0 * (1.0 - progress);
        // Opening a new bin is fine if the item is large and would leave little dead space.
        score -= 0.2 * (item_size as f64);
    } else {
        // Reward using existing bins when they are collectively underfilled.
        score -= 4.0 * (mean_residual / cap).max(0.0) * (1.0 - progress);
    }

    // Mild penalty for near-full bins to preserve flexibility unless very late.
    let fill = 1.0 - (bin_residual as f64) / cap;
    score += 5.0 * fill * fill * (1.0 - progress);

    // Small exploration noise-free deterministic tie-breaker.
    score -= 0.001 * ((bin_residual as f64) * 0.618).sin();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post-residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Stream progress coupling: early on, waste tolerance is high; later, demand tightness
    let tightness = 0.5 + 2.0 * progress * progress;
    score *= tightness;

    // Dead-space penalty: residuals too small to be useful are doubly bad
    let dead_threshold = 10.0;
    if pr < dead_threshold {
        score += (dead_threshold - pr) * 3.0;
    }

    // Lookahead: reward if next item fits the post-residual, penalize near-misses
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            score -= 2.0 + 1.5 * (1.0 - (pr - ni) / cap);
        } else {
            score += 1.0 + (ni - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate: penalize mildly by default, more when many bins already open
    if bin_residual == bin_capacity {
        score = cap * (1.0 + 0.02 * open_bins_count as f64);
        // Allow opening a new bin when current open bins are badly fragmented
        if mean_residual < item_size as f64 * 0.9 {
            score -= 8.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates below the mean (tighter)
    score += 0.3 * (mean_residual - pr).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity fractions
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f; // fraction of capacity left after placement

    // Dead-space penalty for unusable slivers (below smallest item size 10)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Harmonic class reward: post_residual that is a "nice" fraction of capacity
    // (near 0, 1/4, 1/2, 3/4 of capacity) is more reusable by future items.
    let harmonic_targets = [0.0f64, 0.25, 0.5, 0.75, 1.0];
    let mut best_h = 1.0f64;
    for t in harmonic_targets.iter() {
        let d = (frac - t).abs();
        if d < best_h { best_h = d; }
    }
    score -= 18.0 * (1.0 - best_h * 4.0).max(0.0);

    // Integer division classes on post_residual (buckets of 10)
    let bucket = post_residual / 10;
    score -= (bucket % 2) as f64 * 4.0; // odd buckets slightly favored (diversity)

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let tight = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - tight / cap_f).max(0.0);
        } else {
            // next item does not fit here: mild penalty proportional to overflow
            score += ((next_item_size - post_residual) as f64).min(20.0) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer filling bins with small residuals when many bins are open
    score -= (bin_residual as f64 / cap_f) * (open_bins_count as f64).min(10.0) * 2.0;

    // Coupling with mean residual: placing into a bin below mean residual
    // balances the pool of open bins.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    // Opening new bin keeps a full-capacity residual; make it attractive only
    // when item fits poorly in existing bins (large post_residual waste).
    if bin_residual == bin_capacity {
        let waste_elsewhere = post_f; // not meaningful here; use item size class
        let item_class = (item_size % 20) as f64;
        score = cap_f - item_size as f64 - 10.0 + item_class * 0.3;
        // Discourage new bin early in stream or when few bins open
        if open_bins_count < 3 {
            score += 25.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score += 15.0; // large item coming: better to pair with existing bins
        }
        let _ = waste_elsewhere;
    }

    // Slight progression-aware tightening: later in stream, be greedier
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A residual is "dead" if it is smaller than the minimum plausible item size.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < 10 {
        // Tiny unusable sliver: heavy penalty proportional to how wasted the bin is.
        score += 40.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual > 0 && post_residual < item_size && post_residual < 30 {
        // Gap too small for typical items of this stream: moderate penalty.
        score += 12.0 + (30 - post_residual) as f64 * 0.8;
    }

    // Reward residuals that can still hold the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + (post_residual as f64 - next_item_size as f64).min(20.0) * 0.3;
        } else {
            // Post-residual cannot host the next item: penalize, worse if next item is large.
            score += 3.0 + next_item_size as f64 * 0.05;
        }
    }

    // Tightness reward: prefer bins where the item fills a large fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // Open-bin pressure: when many bins are open, discourage opening new bins
    // (the new-bin candidate has bin_residual == bin_capacity and gets penalized),
    // while encouraging consolidation into existing bins.
    if bin_residual == bin_capacity {
        // New-bin candidate.
        let pressure = open_bins_count as f64;
        score += 15.0 + pressure * 2.5;
        // Opening a bin is acceptable early in the stream or when few bins fit the item.
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
    } else {
        // Existing-bin candidate: reward being one of few fitting options (last chance).
        if fitting_bins_count == 1 {
            score -= 25.0;
        } else if fitting_bins_count == 2 {
            score -= 8.0;
        }
        // Slight preference for bins with residuals close to the item (waste minimization).
        score += (bin_residual - item_size) as f64 * 0.15;
    }

    // Mild coupling with mean residual: prefer bins deviating favorably from the mean
    // (using a tighter-than-average bin keeps looser bins flexible).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect/near-perfect fits aggressively.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Tightness bonus: smaller post_residual relative to capacity is better.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 40.0 * tightness * tightness;

        // 2-step lookahead: reward bins whose post_residual matches the next item.
        if next_item_size > 0 {
            let diff = post_residual as i64 - next_item_size as i64;
            if diff == 0 {
                // Next item exactly fills this bin afterwards: superb chain.
                score -= 300.0;
            } else if diff > 0 {
                // Next item fits with some slack; penalize proportional slack.
                let d = diff as f64;
                score -= 120.0 * (1.0 - d / bin_capacity as f64).powi(2);
            } else {
                // Next item does not fit: mild penalty scaled by mismatch.
                let d = (-diff) as f64;
                score += (d / bin_capacity as f64) * 30.0;
            }
        }

        // Penalize dead space: residuals too small for the minimum item size.
        let min_item = 1u32;
        if post_residual < min_item {
            score += 500.0;
        } else if post_residual < 10 {
            score += 60.0 * (10.0 - post_residual as f64);
        }

        // Compare against mean residual: prefer bins already below-average residual
        // (consolidating fullness) rather than spreading across emptier bins.
        let dev = post_residual as f64 - mean_residual;
        score += 0.5 * dev;

        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 200.0;
        }

        // Many open bins: encourage consolidation into fuller bins.
        if open_bins_count > 4 {
            score += 0.3 * (open_bins_count as f64 - 4.0) * (post_residual as f64 / bin_capacity as f64);
        }

        // Late in the stream: push toward closing bins tightly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: neutral-ish baseline so it is chosen only when
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 150.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core fit quality: strongly reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Reward exact/near-exact fills heavily.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Penalize dead space that no future item (min size 1) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // awkward sliver
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this placement sets up a perfect chain.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score -= 18.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            // next item can't use this bin's leftover but could use residual elsewhere;
            // mild penalty if we waste a large residual on a poor fit.
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; penalize it unless
    // all alternatives are poor fits.
    if bin_residual == bin_capacity {
        let mut penalty = 55.0 + 2.0 * open_bins_count as f64;
        // Early in the stream, opening bins is more acceptable (building a pool).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        penalty *= (1.0 - 0.5 * progress);
        // If next item is large, a fresh bin gives flexibility.
        if next_item_size >= 60 {
            penalty -= 15.0;
        }
        // If no open bin fits well (item barely fits nothing), reduce penalty.
        if fitting_bins_count == 0 {
            penalty -= 40.0;
        }
        score += penalty;
    } else {
        // Using an existing bin: slight reward scaled by how full the pool is,
        // to discourage bin proliferation.
        score -= 5.0;
        if (bin_residual - item_size) as f64 <= mean_residual {
            score -= 4.0; // better-than-average space usage
        }
    }

    // Global balance: prefer bins whose resulting residual is close to the mean
    // residual, keeping residuals homogeneous and mergeable.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Mild time-horizon modulation: late in the stream, prioritize consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with non-linear emphasis on tight fits.
    let mut score = pr;
    score += 40.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward exact / near-exact fits via smooth decay of slack.
    let tightness = 1.0 - pr_norm;
    score -= 25.0 * tightness * tightness * tightness;

    // Late in the stream, avoid spreading across many bins: penalize low fill.
    score += 15.0 * progress * pr_norm * pr_norm;

    // If this bin is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = (pr - nxt).max(0.0);
        let fits = if pr >= nxt { 1.0 } else { 0.0 };
        score -= 20.0 * fits * (1.0 - fit_next / cap);
        // Penalize leaving residual just below next item size (dead zone).
        let gap = nxt - pr;
        if gap > 0.0 && gap <= 10.0 {
            score += 10.0 * (1.0 - gap / 10.0);
        }
    }

    // New-bin candidate: mild penalty so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * progress;
    } else {
        // Slight preference for bins below mean residual (balance fills).
        score += (mean_residual - bin_residual as f64) * 0.05;
    }

    // Smooth coupling: interaction of progress with tightness.
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect / near-perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 400.0;
    }

    // Harmonic class logic: item size classes by capacity fractions
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;

    // Large items (size > C/2): prefer bins where they leave small class-compatible residue
    if item_size > half {
        if post_residual <= quarter {
            score -= 150.0; // residue in smallest harmonic class, easy to fill later
        } else if post_residual < third {
            score -= 60.0;
        }
    }

    // Dead-space penalty: residue that no plausible item can fill
    if post_residual > 0 && post_residual < 10 {
        score += 250.0; // tiny unusable gap (min item size 10 in classic regime)
    }

    // Modulo-arithmetic coupling between post_residual and next_item_size
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // next item fills this bin exactly
        } else if next_item_size < post_residual {
            score -= 30.0; // next item can still go here
            let rem = post_residual - next_item_size;
            if rem <= 5 {
                score -= 40.0; // near-exact double fill
            }
        } else {
            score += 80.0; // next item won't fit here: deprioritize
        }
        // Harmonic alignment: next item is a complement in modular residue classes
        if (post_residual + next_item_size) % 10 == 0 && next_item_size <= post_residual {
            score -= 45.0;
        }
    }

    // Integer-division thresholds on post_residual
    let class = post_residual / 10; // decade class of residual
    score += (class as f64) * 12.0; // prefer smaller residual decade classes

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: opening a bin is fine early, costly when many bins open
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64;
        score = 120.0 + pressure * 8.0 - progress * 40.0;
        // Don't open a new bin when the current one fits well
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 150.0;
        }
        if fitting_bins_count == 1 {
            score += 300.0; // never prefer a new bin if it's the only fitting one
        }
    }

    // Mild preference to balance residuals across open bins
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
