        new_bin_penalty += 4.0 * progress;
        // If mean residual of open bins is small (bins are full), opening
        // a new bin is more acceptable.
        new_bin_penalty += (mean_residual / bin_capacity as f64) * 6.0;
        // Perfect-fit bonus: if the item exactly fills a fresh bin.
        if item_size == bin_capacity {
