            // reward bins whose residual matches the lookahead item closely
            let gap = (pr - next_item_size as f64).abs();
            score -= 18.0 * tightness * (1.0 - gap / cap);
        } else {
            // penalize residual that is too small to be useful
            score += 10.0 * tightness;
        }
    }

    // Reward near-perfect fits smoothly
    score -= 25.0 * (1.0 - norm_pr).powi(6);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Prefer bins below mean residual (consolidating emptiness) with smooth term
    score += 0.15 * (pr - mean_residual);

    // New-bin candidate: mildly favored early, discouraged late unless residual is tiny
    if bin_residual == bin_capacity {
        let bias = 8.0 - 14.0 * progress;
        score += bias + 6.0 * (1.0 - (open_bins_count as f64 / (open_bins_count as f64 + 3.0)));
    }

    // Mild penalty for many open bins (encourage consolidation)
    score += 0.4 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: dead space quality ---
    // Residuals are graded by capacity fractions; tiny unusable slivers are penalized hard.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let class = (post / cap * 10.0).floor(); // 0..10 harmonic class of remaining space

    // Dead-space penalty: superlinear in how small the leftover is.
    if post < 10.0 {
        score += 60.0 * (10.0 - post); // nearly full bin: excellent, keep reward
    } else {
        // Penalize awkward leftover classes (1..4 => 10-40 space, hard to fill)
        let awkward = if post < 40.0 { 1.5 } else { 0.0 };
        score += awkward * (40.0 - post).max(0.0) * 0.5;
    }

    // --- Lookahead coupling: does next item fit the leftover? ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            // Reward exact/compact future fit (harmonic match)
            let slack = post - nxt;
            score -= 25.0 * (1.0 - slack / cap).max(0.0);
            // Extra reward if next item fills leftover almost exactly
            if slack < 5.0 { score -= 20.0; }
        } else {
            // Next item won't fit here: penalize proportionally to overflow
            score += 0.4 * (nxt - post);
        }
    } else {
        // Last item: prefer tightest fit overall
        score -= 10.0;
    }

    // --- Last-chance bin: avoid opening a new bin if this is the only fitting one ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is fine early, or when few bins fit the item,
        // or when this bin would leave a very awkward residual elsewhere anyway.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let scarcity = (fitting_bins_count as f64).recip();
        score = cap - post + 30.0 * progress - 20.0 * scarcity;
        if next_item_size > 0 && (next_item_size as f64) <= post {
            score += 25.0; // a fresh bin is great for the next item too, but open bins get edge
        }
    }

    // --- Mild preference to fill bins with large residual gaps (balance open bins) ---
    score += 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    // --- Modulo/harmonic tiebreak on post_residual classes ---
    let m = post_residual % 25;
    score += match m { 0 => -3.0, 1..=5 => 1.0, 6..=15 => 2.5, _ => 0.5 };

    // Small urgency term: many open bins -> prefer packing into existing ones
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 15.0;
    } else if post_residual == 0 {
        // Perfect fit is highly desirable.
        score -= 80.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score += 10.0 * tightness;
    }

    // Open bins pressure: penalize adding to bins when many are open,
    // encouraging consolidation; but reward using last-chance bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64) * 2.0;
        // If next item is large, opening a fresh bin may be good.
        if next_item_size > 60 {
            score -= 20.0;
        }
    }

    // Lookahead: if post_residual can fit the next item, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space relative to the known next item.
        score += 8.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Mild pressure against spreading across many bins.
    score += (open_bins_count as f64) * 0.5;

    // Slight time-based adaptation: early in stream, be less picky.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but penalize creating
    // dead space below the minimum item size (1..100 range => tiny residuals
    // under ~10 are near-useless).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space penalty
    }

    // 2-step lookahead: strongly reward leaving exactly the next item's size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + diff);
        if post_residual == next_item_size {
            score -= 30.0; // perfect 2-chain match
        } else if post_residual < next_item_size {
            // residual can't host next item: mild penalty scaled by gap
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Relative to mean residual: prefer filling bins with above-average space
    // (keep small-residual bins for small items).
    let mr = mean_residual.max(1.0);
    if (post_residual as f64) > mr {
        score -= (post_residual as f64 - mr) * 0.2;
    } else {
        score += (mr - post_residual as f64) * 0.2;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: discourage opening a new bin when a decent fit exists;
    // encourage it when item is large and residuals are fragmented.
    if bin_residual == bin_capacity {
        score += 45.0;
        if item_size > 60 && fitting_bins_count == 0 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0; // new bin can host a pair
        }
    }

    // Late in the stream: consolidate aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Reward small dead space nonlinearly
        let frac = post_residual as f64 / bin_capacity as f64;
        score += frac * frac * 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 120.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist; prefer tightest fit anyway
        score += 5.0;
    }

    // Lookahead: reward if next item fits into the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0; // chain perfect fit
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item nests
            let nest = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 40.0 + 60.0 * nest;
        } else {
            // next item won't fit here: slight penalty for leaving awkward gap
            score += 10.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> discourage
    // spreading, favor filling existing bins
    if !is_new_bin {
        score -= mean_residual * 0.3;
        score -= (open_bins_count as f64) * 2.0;
    } else {
        // Opening a new bin: penalize more when many bins are already open
        // or when mean residual is high (existing bins have room to consolidate)
        score += (open_bins_count as f64) * 8.0 + mean_residual * 0.8;
        // Early in the stream, opening bins is cheaper (future items can fill them)
        score -= (1.0 - progress) * 30.0;
        // Don't open a new bin for tiny items
        if item_size < bin_capacity / 4 {
            score += 60.0;
        }
    }

    // Time horizon: late in stream, prioritize closing out bins tightly
    score += progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;
    // smooth non-linear coupling of residual with stream progress
    let pr_norm = pr / cap;
    let prog2 = progress * progress;
    score += 8.0 * pr_norm * prog2 * cap * 0.1;
    // penalize large residuals late in stream (dead space unlikely to be filled)
    score += 3.0 * pr_norm * pr_norm * (0.5 + progress);
    // reward tight fits
    score -= 6.0 * (1.0 - pr_norm) * (1.0 - pr_norm);
    // lookahead coupling: reward residual that can host next item smoothly
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let fit_next = (pr - ni).max(0.0);
        let exact = if pr as u32 == next_item_size { 1.0 } else { 0.0 };
        score -= 10.0 * exact;
        score += 0.5 * (fit_next / cap);
        // penalize leaving residual just below next item (awkward gap)
        if ni > pr {
            score += 2.0 * ((ni - pr) / cap);
        }
    }
    // last-chance bin: strong reward to use it rather than open new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 - progress);
        score -= 5.0;
    }
    // new-bin candidate: penalize opening unless residual of this bin is hopeless
    if bin_residual == bin_capacity {
        let hopeless = pr_norm; // == 1.0 for empty candidate
        let spread = (mean_residual / cap - pr_norm).abs();
        score += 4.0 + 6.0 * (1.0 - progress) - 4.0 * spread;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }
    // mild pressure against bin proliferation
    score += 0.15 * open_bins_count as f64 * progress;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post_residual
    score -= 30.0 * ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(3);

    // Harmonic class of post_residual: penalize dead space in awkward classes
    let cap = bin_capacity;
    let class = post_residual % 10;
    if class == 1 || class == 2 {
        score += 8.0; // nearly-unusable slivers
    } else if post_residual < 10 {
        score -= 25.0; // bin effectively closed, great
    }

    // Lookahead coupling: reward post_residual that fits next item exactly-ish
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 / (1.0 + slack);
        } else {
            // next item cannot fit here; penalize large leftover less if bin nearly full
            score += 5.0 * (post_residual as f64 / cap as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is poor
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.5 * cap as f64;
        score += if poor_fit { 45.0 } else { 25.0 };
        // early stream: opening bins is cheap-ish; late stream: prefer consolidation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    }

    // Prefer bins with below-mean residual (consolidate emptier space usage)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Slight preference for fewer open bins
    score += 0.05 * open_bins_count as f64;

    // Item-size harmonic class: big items should go into emptiest bins
    if item_size > cap / 2 {
        score += 0.2 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward residuals that can still host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.2 * (post_residual - next_item_size) as f64;
        } else {
            score += 20.0; // dead space for the lookahead item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing bins are poor fits.
    if bin_residual == bin_capacity {
        score += 55.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
        // If item is large, new bin is attractive.
        if item_size > bin_capacity / 2 {
            score -= 25.0;
        }
    }

    // Open-bin pressure: prefer filling bins when many are open.
    score += 0.15 * open_bins_count as f64;

    // Prefer bins with residual far from mean (consolidate waste).
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    // Slight preference for tight fits relative to item size.
    score += 0.2 * (post_residual as f64 / (item_size as f64 + 1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.16;
    score
