pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (small dead space is exponentially valuable).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Penalize creating residuals that no plausible item can use (dead space).
    // Items are >= 1, but typical useful chunks are larger; penalize mid-range waste less
    // than large unusable gaps relative to item size.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * waste_ratio * 40.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward this placement (chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to how much we fragment.
            score += 3.0;
        }
    }

    // Prefer filling bins that are already mostly full (low residual) to consolidate.
    let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= fill * 8.0;

    // Time horizon: late in the stream, be more conservative — favor tight fits,
    // avoid opening bins (new-bin candidate gets a penalty that grows over time).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of opening a bin, modulated by how poorly
        // existing bins would fit and by the global mean residual.
        let mut open_cost = 55.0 + 30.0 * progress;
        // If many bins are open with lots of residual capacity, opening is worse.
        open_cost += (open_bins_count as f64).sqrt() * 4.0;
        open_cost += (mean_residual / bin_capacity as f64).max(0.0) * 10.0;
        // If the current item is large relative to capacity, a fresh bin is more attractive.
        open_cost -= (item_size as f64 / bin_capacity as f64) * 15.0;
        score += open_cost;
    } else {
        // Open bin: mild reward for using existing capacity grows with progress.
        score -= 5.0 + 10.0 * progress;
    }

    // Global balance: penalize bins whose residual deviates far below mean residual
    // (they are "odd" fragments) mildly, encouraging uniform residual structure.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += dev.abs() * 5.0;

    // Small deterministic tie-breaker based on residual parity structure.
    score += (post_residual % 7) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // later in the stream, tight fits (small post_residual) are rewarded more strongly.
    let tightness = 1.0 - norm_pr; // 0 = perfect fit, 1 = empty-ish bin
    score -= (1.0 - tightness * tightness) * (30.0 + 70.0 * progress * progress);

    // Penalize post_residual that wastes space relative to the next item's needs.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score += gap * gap / cap * (1.0 + progress);
        // Reward when next item fits exactly in the resulting residual.
        if nxt <= pr {
            score -= 15.0 * (1.0 - gap / cap) * (1.0 + progress);
        } else {
            score += 10.0 * (1.0 - pr / nxt.max(1.0));
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 + progress);
    }

    // Penalize divergence from the mean residual across open bins (balance pressure).
    score += (mean_residual - pr).abs() * 0.25 * (1.0 - progress);

    // Mild penalty for accumulating many open bins with large residuals.
    score += norm_pr * (open_bins_count as f64).ln().max(0.0) * 5.0;

    // New-bin candidate: prefer opening a new bin only for large items late in stream
    // when existing residuals are small; otherwise make it unattractive.
    if bin_residual == bin_capacity {
        score += 25.0 + 60.0 * (1.0 - progress) + 0.5 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes w.r.t. common item sizes
    let pr = post_residual;
    // Reward residuals that are "perfect" (zero or in a reusable harmonic class)
    if pr == 0 {
        score -= 60.0;
    } else {
        // Penalize dead space in awkward classes (pr < 10 unusable since min item 1)
        if pr < 10 {
            score += (10 - pr) as f64 * 2.0;
        }
        // Harmonic divisibility: reward residuals divisible by small item classes
        let harmony = if pr % 10 == 0 { 8.0 }
            else if pr % 5 == 0 { 5.0 }
            else if pr % 3 == 0 { 3.0 }
            else if pr % 2 == 0 { 1.5 }
            else { 0.0 };
        score -= harmony;

        // Fraction-of-capacity thresholds on post_residual
        let frac = pr as f64 / bin_capacity as f64;
        if frac < 0.05 {
            score += 12.0; // nearly full, fine
        } else if frac < 0.15 {
            score -= 6.0;  // tight but reusable
        } else if frac < 0.35 {
            score += 2.0;
        } else {
            score -= 4.0 * (1.0 - frac); // large residual is flexible
        }
    }

    // Lookahead coupling: if next item fits post_residual, big reward
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 25.0 + (pr - next_item_size) as f64 * 0.3;
            // exact match is golden
            if next_item_size == pr {
                score -= 30.0;
            }
        } else {
            // next item cannot follow here: mild penalty scaled by gap
            score += ((next_item_size - pr) as f64).min(40.0) * 0.4;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }
    // Many fitting bins: prefer the tightest (post_residual already encodes this),
    // but add small penalty to avoid scattering across many bins
    if fitting_bins_count > 3 {
        score += 1.5;
    }

    // New-bin candidate handling: only prefer opening a new bin when current
    // placements would create bad dead space and stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New bin baseline: neutral-ish, worse than good fits, better than terrible ones
        score = 55.0 + 20.0 * progress - (open_bins_count as f64) * 0.5;
        // If item is huge, a fresh bin wastes less
        if item_size > bin_capacity * 3 / 4 {
            score -= 15.0;
        }
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's a good squeeze
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f) * 0.15;
    } else {
        score += (res_f - mean_residual) * 0.05;
    }

    // Mild preference to fill older/bins in dense regimes
    score -= (open_bins_count.min(20) as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are tiny but nonzero are
    // "unusable" dead space (likely nothing fits), penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 25 {
        // Moderately small gaps are risky too.
        score += 12.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits in the post residual,
    // this placement is doubly valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
        // Extra reward for tight chain fits (little slack left for the next item).
        let chain_slack = post_residual - next_item_size;
        if chain_slack < 10 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // This bin becomes dead after placement if the gap can't hold the next item.
        score += 6.0;
    }

    // Open-bins pressure: many open bins -> prefer consolidation into existing bins,
    // penalize spreading residual capacity thin.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 2.5 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: attractive only when existing bins would waste badly.
    if bin_residual == bin_capacity {
        // Base neutrality: its raw post_residual (large) already ranks it poorly;
        // give a mild bonus so it wins only when open bins score worse.
        score -= 5.0;
        // Early in the stream, opening bins is cheap.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
        // If many bins are already open, discourage further sprawl.
        score += pressure * 3.0;
    }

    // Mild alignment with mean residual: bins far below mean residual are
    // "ragged" — prefer bins whose residual is close to mean (uniform filling).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post-residual exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize when next item cannot follow into this bin
        score += 10.0;
    }

    // Prefer bins whose residual is tight relative to mean residual
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin bonus: avoid wasting the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless current bins are nearly full
    if bin_residual == bin_capacity {
        let avg_load = 1.0 - mean_residual / bin_capacity as f64;
        score += 40.0 * avg_load;
    }

    // Discourage large dead space that nothing (min size ~1..10) can use
    if post_residual < 10 && post_residual > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tight-fit preference: squared dead-space penalty (relative to capacity)
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / cap;

    // Strong reward for near-perfect fits (wasting nothing)
    if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 10 {
        score -= 5.0;
    }

    // Lookahead: if the next item fits into the resulting residual, this bin
    // remains productive; reward it. If next item cannot use the residual,
    // the leftover is likely dead space; penalize proportionally.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            score -= 8.0 + 0.10 * nx;
        } else {
            let unusable = pr - if pr > nx { nx } else { pr };
            score += 0.15 * unusable;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current open bins are crowded (mean residual low) relative to item size.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap;
        if fitting_bins_count > 0 {
            // Penalize new bin unless existing bins fit poorly
            score += 15.0 + 25.0 * crowding;
            // If no bin leaves a good residual, ease the penalty
            let best_possible = if mean_residual > item_size as f64 { item_size as f64 } else { mean_residual };
            if (mean_residual - item_size as f64) > 0.5 * cap {
                score -= 10.0;
            }
            let _ = best_possible;
        } else {
            // Must open a bin: mild reward scaled by stream progress
            score -= 5.0;
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    }

    // Fragmentation guard: avoid leaving residuals that no plausible item
    // (min size 1, typical >= 10) can use, when the bin can't take the next item.
    if next_item_size > 0 && (next_item_size as u32) > post_residual && post_residual > 0 {
        score += 0.5;
    }

    // Mild preference to spread load when many bins are open (keeps options alive)
    if bin_residual < bin_capacity && open_bins_count > 1 {
        score += 0.02 * (open_bins_count as f64).ln().max(0.0) * (pr / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fits (small post_residual) matter more.
    let tightness = (post / cap).powi(2);
    score += (0.5 + 2.0 * progress) * tightness * cap;

    // Reward placements that leave room for the lookahead item (smooth coupling).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_lookahead = (post - nxt).abs();
        let look_norm = nxt / cap;
        score -= (1.0 - look_norm) * (fit_lookahead / cap).powi(2) * 20.0 * (1.0 - progress);
        // Penalize if lookahead cannot fit at all (dead-end residual).
        if post < nxt {
            score += 15.0 * (1.0 - progress) * (1.0 + look_norm);
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize mildly early, allow late when residuals are fragmented.
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap).clamp(0.0, 1.0);
        score += 10.0 - 8.0 * frag - 10.0 * progress;
    } else {
        // Prefer bins below mean residual (consolidating emptier bins).
        score -= 0.1 * (mean_residual - (bin_residual as f64));
    }

    // Mild penalty for many open bins to discourage fragmentation.
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes (usable by small future items) are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity left after placement
    let frac = pr / cap;

    // Dead-space penalty: residuals below 10 are nearly unusable (items >= 1,
    // but tiny slivers waste capacity). Strong quadratic penalty.
    if post_residual < 10 {
        score += 60.0 + (10.0 - pr) * 8.0;
    } else if post_residual <= 30 {
        // Sweet spot: small but still fillable by typical items.
        score -= 25.0 * (1.0 - frac);
    } else {
        // Larger residuals: mildly penalize proportional waste unless it can
        // pair with the lookahead item.
        score += 0.5 * frac * frac * 20.0;
    }

    // Lookahead coupling: reward when next item fits exactly in the class
    // of post_residual (modulo-10 harmonic bands).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let band = post_residual % 10;
            let nband = next_item_size % 10;
            // Perfect harmonic match of residue classes: strong reward.
            if band == nband {
                score -= 18.0;
            }
            // Exact fit of the next item: big reward.
            if next_item_size == post_residual {
                score -= 30.0;
            } else {
                let after2 = post_residual - next_item_size;
                if after2 < 10 {
                    score += 10.0; // would create dead sliver
                } else {
                    score -= 12.0; // chain fit keeps bin productive
                }
            }
        } else {
            // Next item cannot use this bin's leftover: slight penalty
            // proportional to how far off it is, softened in late stream.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 6.0 * (1.0 - progress);
        }
    } else {
        // Last item: any residual is pure waste; minimize it hard.
        score += 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin for a mediocre fit.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate (empty bin): penalize opening new bins when the
    // stream is young and open bins can absorb the item; allow it late or
    // when many bins are open (load spreading for future flexibility).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = (open_bins_count as f64 / (mean_residual.max(1.0) / cap + 1.0)) * 0.05;
        score += 20.0 * (1.0 - progress) + crowding;
        // Large items are fine to start fresh bins with.
        if item_size >= 50 {
            score -= 15.0;
        }
    }

    // Slight preference for tighter existing bins (smaller residual before
    // placement) to keep fragmentation concentrated.
    score += (bin_residual as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0) + 15.0;
    }
    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = 1.0 - (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 10.0 * tightness;

    // Open-bin pressure: penalize spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // New-bin candidate: only attractive when no open bin fits or this is a last-chance fit.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else {
            score += 25.0 + 5.0 * (open_bins_count as f64).sqrt();
        }
    }

    // Last-chance bin before opening a new one: reward using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item barely misses, penalize slightly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < next_item_size + 10 {
        score += 6.0;
    }

    // Mean residual coupling: prefer bins below mean residual (use up fuller bins first).
    score -= 3.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    // Stream progression: early on, be more willing to open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 20.0;

    // 2-step lookahead: reward when post_residual can host next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // next item fits exactly into the leftover: strong reward
            let slack = post_residual as f64 - nxt;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // leftover too small for next item: penalize dead space, more if tiny
            let dead = post_residual as f64 / bin_capacity as f64;
            if post_residual < 10 {
                score += 15.0 * (1.0 - dead);
            }
        }
    }

    // Relative to mean residual: prefer bins with residual below mean (tighter bins)
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize slightly unless current bin is a bad fit
    if bin_residual == bin_capacity {
        score += 12.0;
        // Opening a new bin is attractive if item is large and fits poorly anywhere
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 10.0;
        }
    }

    // Early stream: be less greedy about tight fits, keep bins flexible
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: prefer consolidating into existing ones
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post_residual is good, but amplify).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize leaving small unusable dead space (chunks that nothing can fill).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits in the post residual, reward; else penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
        } else if next_item_size <= bin_residual {
            // next item fits this bin but not after placing current item:
            // mild penalty for blocking it.
            score += 8.0;
        }
        // Prefer bins where post residual is far from next item size (flexibility).
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score += 0.15 * gap;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // options are poor or we are early with few bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let desperation = (fitting_bins_count == 0) as i32 as f64;
        let poor_options = (fitting_bins_count == 1 && post_residual > 20) as i32 as f64;
        let early_bonus = if progress < 0.3 && open_bins_count < 4 { -10.0 } else { 0.0 };
        score += 45.0 - 60.0 * desperation - 25.0 * poor_options + early_bonus
                 + 20.0 * (mean_residual / bin_capacity as f64);
    } else {
        // Slight preference for bins with larger residual among open bins
        // (use fullest bins first to consolidate).
        score -= 0.2 * bin_residual as f64;
    }

    // Time-horizon modulation: late in the stream, prioritize compactness.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early in the stream, prefer tight fills (small post_residual);
    // later, larger residuals become less reusable, penalize quadratically.
    let tightness = (norm_pr * (1.0 - progress)) - (norm_pr * norm_pr * progress);
    score += 40.0 * tightness;

    // Non-linear penalty on dead space that can't fit the lookahead item
    if next_item_size > 0 && (post_residual as u64) < (next_item_size as u64) {
        let waste = (next_item_size as f64 - pr).max(0.0);
        score += waste * (0.5 + progress);
    } else if next_item_size > 0 && (next_item_size as f64) >= pr * 0.5 {
        // reward leaving space that the next item can plausibly use
        score -= 6.0 * (pr - (next_item_size as f64 - pr)).max(0.0) / cap * 10.0;
    }

    // Last-chance bin bonus: if this is the only fitting bin, favor it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize relative to how badly current bins fit
    if bin_residual == bin_capacity {
        let mean_fit_gap = (mean_residual - item_size as f64).max(0.0);
        score = cap * (0.9 + 0.5 * progress) - 10.0 * mean_fit_gap / cap * 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild entropy term: prefer bins deviating from mean residual early (diversification)
    score += 0.3 * (pr - mean_residual) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 and mod 25
    let r10 = post_residual % 10;
    let r25 = post_residual % 25;

    // Penalize "dead" residuals that few future item sizes can use
    // small nonzero residues (<10) are nearly unusable
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    if r10 == 0 && post_residual > 0 {
        score -= 12.0; // multiples of 10 are highly reusable
    }
    if r25 == 0 {
        score -= 8.0;
    }
    if r10 == 5 {
        score -= 3.0; // half-decade residuals moderately usable
    }
    if r10 == 1 || r10 == 9 {
        score += 6.0;
    }

    // Fractional fill level classes (integer division of capacity)
    let fill_quarter = (bin_capacity - post_residual) / (bin_capacity / 4);
    match fill_quarter {
        0 => score += 5.0,   // barely used bin: prefer to keep it flexible? mild penalty
        3 => score -= 10.0,  // nearly full: good to close it out
        _ => {}
    }

    // Lookahead coupling: does next item fit harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact harmonic match rewards
            if post_residual % next_item_size == 0 {
                score -= 15.0;
            } else {
                score -= 5.0;
            }
            let left_after_next = post_residual - next_item_size;
            if left_after_next % 10 == 0 {
                score -= 7.0;
            }
            if left_after_next < 10 && left_after_next > 0 {
                score += 10.0;
            }
        } else {
            // next item won't fit here regardless; slight penalty for trapping
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly
    if bin_residual == bin_capacity {
        let pressure = if open_bins_count == 0 {
            -100.0
        } else {
            let mr = mean_residual.max(0.0);
            // open new bin when mean residual is small relative to item
            (item_size as f64 - mr).clamp(0.0, 100.0) * 1.5 - 30.0
        };
        score += pressure;
    }

    // Stream progression: later in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.3;

    // Tie-break toward lowest waste, slight noise-free deterministic nudge
    score += (post_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold the smallest item (1)
    // are worthless; residuals in the "awkward" band (1..=item_size floor)
    // are partially wasted. Penalize small-but-nonzero gaps superlinearly.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if post_residual < 10 {
            // Tiny unusable gap: strong penalty
            score += (10.0 - pr) * 3.0;
        } else {
            // Larger gaps: mild superlinear penalty to prefer tight fits
            score += (pr / bin_capacity as f64).powf(1.5) * 40.0;
        }
    } else {
        // Perfect fill: big reward
        score -= 60.0;
    }

    // Reward bins whose residual after placement can still host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap blocks the known next item
        score += 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones;
    // the new-bin candidate (residual == capacity) gets penalized via its high
    // base score, but add explicit pressure so tight existing fits win.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins already open
        score += 15.0 + (open_bins_count as f64) * 2.0;
        // But if no open bin fits well (large gap would be created elsewhere),
        // opening fresh is fine — soften when mean residual is large.
        score -= (mean_residual / bin_capacity as f64) * 10.0;
    }

    // Late in the stream, prefer closing bins tightly (less future value in
    // keeping residual flexible).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect match with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // ideal: next item fills this bin exactly
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack.min(20.0); // next item still fits, mild reward
        } else {
            // next item won't fit here; penalize small dead space
            let gap = (next_item_size - post_residual) as f64;
            if post_residual > 0 && post_residual < 10 {
                score += 25.0; // tiny unusable dead space
            } else {
                score += gap * 0.15;
            }
        }
    }

    // Tight fit reward relative to capacity
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 15.0;

    // Relative to mean residual: prefer bins that are already fuller than average
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it moderately attractive only when current bins fit poorly
    if bin_residual == bin_capacity {
        score += 8.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin pairs well with large upcoming item
        }
    }

    // Late in stream: consolidate, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    } else {
        score += progress * 10.0;
    }

    // Prefer spreading across many open bins when they are numerous
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * tightness;

    // Penalize dead space: post_residual too small to hold the smallest possible item (1).
    if post_residual == 0 {
        score -= 25.0; // perfect fit is excellent
    } else if post_residual < 10 {
        score += 4.0; // tiny dead space is mildly wasteful
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count >= 2 {
        // With alternatives, prefer the bin where the item leaves the most useful space,
        // but still favor existing bins slightly over opening new ones.
        score -= 6.0;
    }

    // Lookahead (k=2): if the next item can fit in the post_residual, reward this placement
    // (keeps chains going). If next item would NOT fit but post_residual is large,
    // penalize creating stranded capacity.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / 100.0);
        } else {
            // stranded space that the next item cannot use
            let stranded = post_residual as f64;
            score += 0.15 * stranded;
            // extra penalty if the stranded space could have held the next item
            // had we placed the current item elsewhere
            if next_item_size <= bin_residual && post_residual > 0 {
                score += 8.0;
            }
        }
    }

    // Global state coupling: when many bins are open with large mean residual,
    // encourage consolidation into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).sqrt();
    score -= 5.0 * consolidation;

    // Time horizon: early in the stream, be more willing to open new bins (explore);
    // late in the stream, squeeze into existing bins aggressively.
    score += 10.0 * (1.0 - progress) * (1.0 - progress);

    // New-bin candidate: an empty bin has full residual. It should win only when
    // existing bins offer bad fits. Give it a baseline penalty so it is chosen
    // only when its score (post_residual = capacity - item) beats tight existing options.
    if bin_residual == bin_capacity {
        score += 14.0;
        // Exception: large items fit well in a fresh bin and leave little waste.
        if item_size >= 60 {
            score -= 20.0;
        }
        // Exception: if no open bin can fit the item, new bin is the only option.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual (tight fit), with smooth non-linear shaping.
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // late in the stream, tight fits matter more (dead space is costlier).
    let progress_coupling = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += norm_pr * norm_pr * cap * (0.3 + 0.7 * progress_coupling);

    // Reward scarce fitting opportunities (last-chance bin), smoothly.
    if fitting_bins_count > 0 {
        let scarcity = 1.0 / fitting_bins_count as f64;
        score -= 12.0 * scarcity * (1.0 + progress);
    }

    // Penalize bins whose residual deviates strongly from the mean residual
    // (smooth quadratic deviation coupling).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Lookahead: reward leaving space for the next item, smoothly quadratic.
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 6.0 * (1.0 - (gap / cap).min(1.0));
        } else {
            score += 4.0 * (-gap / cap);
        }
    }

    // Mild penalty for proliferation of open bins, modulated by progress.
    score += open_bins_count as f64 * 0.15 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals that are multiples of
    // common item sizes (10..80 stream) or small remainders are more reusable.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Reward residuals that divide cleanly into capacity fractions
    // (harmonic classes: 100, 50, 25, 20, 10, 5).
    let harmonic: [u32; 6] = [100, 50, 25, 20, 10, 5];
    for (i, &h) in harmonic.iter().enumerate() {
        if pr > 0 && pr % h == 0 {
            score -= (6.0 - i as f64) * 4.0;
            break;
        }
    }

    // Penalize awkward dead space: residuals in (0, 10) are nearly unusable
    // for the smallest items.
    if pr > 0 && pr < 10 {
        score += 30.0;
    }

    // Integer-division threshold: post_residual / next_item_size tells how
    // many of the lookahead item fit exactly. Reward perfect packing of the
    // lookahead item.
    if next_item_size > 0 && pr >= next_item_size {
        let fits = pr / next_item_size;
        let rem = pr % next_item_size;
        if rem == 0 {
            score -= 12.0 + fits as f64 * 3.0;
        } else if rem < 10 {
            score += 8.0; // leaves tiny unusable remainder after lookahead
        } else {
            score -= 4.0; // leftover still usable
        }
    }

    // Lookahead coupling: if the lookahead item exactly fills this bin after
    // placing the current one, strongly reward.
    if next_item_size > 0 && pr == next_item_size {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only fitting bin, penalize opening a
    // new bin instead by discounting this bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: empty bin should only win when the current item is
    // large and residuals elsewhere are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual / cap - 0.5).abs();
        let base = cap * 0.55 + item_size as f64 * 0.3;
        let bonus = if item_size >= 60 { 20.0 } else { 0.0 }
            + fragmentation * 25.0
            + progress * 10.0
            + (open_bins_count as f64).sqrt() * 2.0;
        score = base + bonus - score * 0.0;
    }

    // Mild tie-breaking toward tighter bins relative to mean residual.
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical items are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward placements that leave enough room for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            score += 10.0;
        }
    }

    // Last chance: strongly favor using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins; opening new bins becomes more costly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.05 + 0.1 * progress);
    if bin_residual == bin_capacity {
        // Candidate new bin: penalize proportionally to open-bin pressure.
        score += 25.0 + pressure * 10.0;
    } else {
        score -= pressure;
    }

    // Prefer bins whose residual deviates favorably from the mean
    // (filling the emptiest usable bin keeps tight bins for tight items).
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        if bin_residual as f64 > mean_residual {
            score -= 0.3 * dev;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect match between post_residual and next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_quality = 1.0 - ((post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        score -= 25.0 * match_quality;
    } else if next_item_size > 0 {
        // Penalize residuals that leave next item unable to fit here.
        score += 8.0;
    }

    // Penalize small dead space that likely becomes unusable (waste).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Penalize opening a new bin when open bins exist and fit is decent.
    if bin_residual == bin_capacity && open_bins_count > 0 && post_residual < bin_capacity as f64 as u32 {
        score += 20.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Late in stream, favor compacting into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base preference for tight fits: reward small post_residual non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Strongly penalize opening a new bin by default.
    if is_new_bin {
        let mut new_bin_penalty = 60.0;
        // Late in the stream, avoid proliferating bins even more.
        new_bin_penalty += 40.0 * progress;
        // If this is the only fitting bin scenario (last chance), opening a new
        // bin is relatively more acceptable.
        if fitting_bins_count <= 1 {
            new_bin_penalty -= 30.0;
        }
        // Large items leave little room elsewhere; a fresh bin may be fine.
        if item_size > bin_capacity / 2 {
            new_bin_penalty -= 15.0;
        }
        // If open bins are generally full (low mean residual), new bin is natural.
        new_bin_penalty -= (mean_residual / bin_capacity as f64) * 20.0;
        score += new_bin_penalty;
    } else {
        // Reward using an existing bin, especially when few bins fit the item.
        score -= 8.0;
        if fitting_bins_count == 1 {
            score -= 25.0; // last-chance bin: strongly prefer it
        } else {
            score -= 2.0 * (fitting_bins_count as f64).ln().max(0.0);
        }
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            // Next item still fits here: mild reward proportional to slack usage.
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item would not fit: penalize leaving awkward small gaps.
            let gap = post_residual as f64;
            if gap > 0.0 && gap < 10.0 {
                score += 12.0;
            }
        }
    }

    // Global state coupling: when many bins are open with large mean residual,
    // encourage consolidating into existing bins rather than spreading.
    if !is_new_bin && mean_residual > bin_capacity as f64 * 0.5 {
        score -= 5.0;
    }

    // Time horizon: early on, be a bit more exploratory (mild new-bin tolerance
    // already handled); late, tighten everything toward exact fits.
    score += 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let base = pr * (1.0 + 0.5 * progress * progress);

    // Penalize large post_residual more as stream progresses (dead space becomes costlier)
    let dead_space_penalty = (norm_pr * norm_pr) * cap * (0.3 + 0.7 * progress);

    // Reward tight fits: small post_residual gets a smooth bonus
    let tight_fit_bonus = -((1.0 - norm_pr).powi(3)) * cap * 0.4;

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    let last_chance = if fitting_bins_count == 1 { -30.0 * (1.0 - norm_pr) } else { 0.0 };

    // Lookahead: if next item fits in post_residual, reward this placement
    let lookahead = if next_item_size > 0 && (next_item_size as f64) <= pr {
        -8.0 * (1.0 - next_item_size as f64 / cap)
    } else if next_item_size > 0 {
        4.0
    } else {
        0.0
    };

    // Slight preference for consolidating into fewer bins early on
    let consolidation = -2.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (1.0 - progress);

    // Deviation from mean residual: prefer bins near the mean to keep balance
    let balance = ((pr - mean_residual) / cap).powi(2) * 10.0;

    base + dead_space_penalty + tight_fit_bonus + last_chance + lookahead + consolidation + balance
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space classes modulo capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize post_residual that is "unusable" for typical small items (1..=100, common small sizes <= 20)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny dead space is worthless
    }

    // Harmonic class reward: post_residual divisible by common item classes (10/20/25/50)
    let classes: [u32; 4] = [10, 20, 25, 50];
    for (i, c) in classes.iter().enumerate() {
        if post_residual % c == 0 && post_residual > 0 {
            score -= 4.0 * (4 - i) as f64; // finer divisibility rewarded more
        }
    }

    // Fraction-of-capacity class of residual
    let frac = bin_residual as f64 / cap;
    if frac >= 0.5 {
        score -= 6.0; // prefer filling bins with large remaining space
    } else if frac < 0.2 {
        score += 5.0;
    }

    // Lookahead coupling: if next item fits into post_residual, strong reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
        // extra reward if next item exactly fills post_residual (perfect harmonic pair)
        if next_item_size == post_residual {
            score -= 15.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; mild penalty proportional to wasted potential
        score += 3.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins fit poorly
    if bin_residual == bin_capacity {
        // opening a new bin: baseline cost, reduced if many bins open (consolidation pressure)
        score = 45.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 8.0;
        }
    }

    // Late-stream consolidation: prefer tighter fits as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (pr / cap) * 10.0;

    // Prefer bins below mean residual (balance residual distribution)
    score += (pr - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to fit the smallest
    // plausible future item are nearly worthless — punish them hard.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 1000.0; // exact fit, actually great — undo base term
        score -= post_residual as f64;
        score -= 50.0; // reward perfect closure strongly
    } else if post_residual < 10 {
        // gap too small for typical items: dead space
        score += (10 - post_residual) as f64 * 6.0;
    } else if post_residual < 25 {
        // moderately awkward gap
        score += (25 - post_residual) as f64 * 2.0;
    }

    // Reward tight fits (small post_residual relative to what was consumed).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage proliferation of bins when existing ones suffice.
    if bin_residual != bin_capacity {
        score -= open_bins_count as f64 * 1.5;
    } else {
        // New-bin candidate: only attractive when current bins are crowded
        // or the item leaves a clean residual for a likely follow-up item.
        score += open_bins_count as f64 * 2.0;
        score += mean_residual * 0.5;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // new bin can host the next item too
        }
    }

    // Lookahead: reward residuals that still admit the next item.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0; // blocks the known next item
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    } else {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Penalize dead space the next item cannot use.
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: minimize post residual aggressively.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: penalize unless current bin would leave bad waste.
    if bin_residual == bin_capacity {
        let waste = if next_item_size > 0 && post_residual < next_item_size {
            1.0
        } else {
            0.0
        };
        score += 55.0 + 10.0 * open_bins_count as f64 * waste;
    }

    // Mild preference for bins below mean residual (keeps large bins available).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Late in stream: consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post_residual nonlinearly.
    score += 0.08 * (post_residual as f64).powf(1.35);

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Dead space penalty: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: does the next item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain potential: reward proportional to how well next item also packs.
            score -= 10.0 + 0.05 * (post_residual - next_item_size) as f64;
        } else {
            // Post-residual unusable by next item -> mild penalty scaled by gap.
            score += 0.06 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer any bin, especially tightest.
        score -= 8.0;
    }

    // Global state: many open bins -> favor filling existing bins (consolidation).
    let pressure = open_bins_count as f64 / 8.0;
    if bin_residual < bin_capacity {
        score -= 3.0 * pressure;
    }

    // Mean-residual coupling: if this bin is below mean residual (tighter than average),
    // prefer it when the stream is late; earlier, keep looser bins flexible.
    let t = step_index as f64 / (total_items.max(1) as f64);
    let dev = mean_residual - bin_residual as f64;
    score += dev * (0.5 - t) * 0.3 - dev * t * 0.2;

    // New-bin candidate logic: opening a new bin is attractive early or when
    // item fits poorly everywhere; discourage new bins when a decent fit exists.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 0.55 * bin_capacity as f64;
        let early = t < 0.25;
        if poor_fit || early || open_bins_count == 0 {
            score -= 18.0 + 10.0 * pressure * (1.0 - t);
        } else {
            score += 10.0 + 15.0 * (1.0 - t);
        }
    }

    // Small structural bonus for using bins with residual close to item size.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste_ratio * waste_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = post * (1.0 + 0.8 * progress) - 2.0 * norm_post * norm_post * cap * (1.0 - progress);

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - norm_post;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that cannot fit the smallest plausible item (<=10)
    if post_residual < 10 && post_residual > 0 {
        score += 25.0 * (1.0 - progress);
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: reward residual that can still host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            score += 4.0 * nxt / cap;
        }
    }

    // Mild penalty for scattering across many open bins late in the stream
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 + 3.0 * progress);

    // New-bin candidate: keep it competitive only when open bins are badly fragmented
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap - 0.5).max(0.0);
        score += 20.0 - 25.0 * frag * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual lies in "dead zones"
    // (very small, unusable slivers) should be penalized heavily.
    let pr = post_residual;
    if pr > 0 {
        // Dead space: residual too small for the smallest plausible item (<= 10)
        if pr < 10 {
            score += 60.0;
        }
        // Modulo-classes: residuals near multiples of common item sizes (10, 20, 25, 50)
        // are "harmonic" and reusable; reward them.
        let harmonic = (pr % 10 == 0) as f64 * 12.0
            + (pr % 25 == 0) as f64 * 10.0
            + (pr % 50 == 0) as f64 * 8.0
            + (pr % 20 == 0) as f64 * 6.0;
        score -= harmonic;

        // Integer-division threshold: residual >= 50 keeps a half-capacity slot alive
        if pr >= 50 {
            score -= 15.0;
        } else if pr >= 30 {
            score -= 7.0;
        } else if pr >= 15 {
            score -= 2.0;
        }
    } else {
        // Perfect fit is ideal
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual
    // harmonic class, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= pr {
        let gap = pr - next_item_size;
        if gap < 10 {
            score -= 25.0;
        } else if pr % 10 == 0 && next_item_size % 10 == 0 {
            score -= 10.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > pr {
        // Next item cannot use this residual -> dead-space risk
        score += (next_item_size - pr) as f64 * 0.3;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate (fresh empty bin): penalize unless it enables a
    // harmonic packing of the next item or current bins are very full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fullness = 1.0 - mean_residual / (bin_capacity as f64 * open_bins_count.max(1) as f64);
        // Prefer new bin when existing bins are congested; penalize otherwise
        score += 35.0 - 45.0 * fullness - 10.0 * progress;
        if next_item_size >= 50 {
            score -= 15.0; // big next item pairs well in a fresh bin with current one
        }
    }

    // Mild tie-break toward tighter bins relative to mean residual
    score -= (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small, unusable leftover gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0; // mildly awkward zone
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (next_item_size as f64 / 10.0);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that the known next item cannot use: extra penalty.
        score += 10.0;
    }

    // Open-bin pressure: with many open bins, prefer packing into existing ones
    // (the new-bin candidate has post_residual = capacity - item, typically large,
    // so we must add pressure that scales with open_bins_count to discourage sprawl).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + 3.0 * progress);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless dead-space penalty already dominates).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild preference for bins below mean residual (keeps residuals balanced,
    // leaving larger gaps consolidated in fewer bins).
    score += ((post_residual as f64) - mean_residual).abs() * 0.15;

    // Penalize the fresh-bin candidate when item is small relative to capacity,
    // since it wastes most of a new bin.
    if bin_residual == bin_capacity {
        score += (bin_capacity - item_size) as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    // Strong reward for perfect 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        // Exact match bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving residual that next item can never fit into nicely
        if next_item_size > post_residual && post_residual > 0 {
            score += 6.0;
        }
    }

    // Penalize dead space that is unusably small relative to typical item sizes
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor.
    // Empty bin has residual == capacity; make it unattractive unless it enables a perfect pair.
    if bin_residual == bin_capacity {
        let mut penalty = 30.0 + open_bins_count as f64 * 4.0;
        // But if the next item would perfectly fill the new bin after this one, soften
        if next_item_size > 0 && (bin_capacity as i64 - item_size as i64 - next_item_size as i64) == 0 {
            penalty -= 35.0;
        }
        score += penalty;
    }

    // Prefer bins with residual below mean (filling tighter bins first)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Late in the stream: consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more aggressively than linear.
    let tight_fit = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 12.0 * tight_fit * tight_fit;

    // Penalize dead space: residuals too small for typical future items are wasted.
    if post_residual < 10 {
        score += 30.0;
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / 100.0);
        } else {
            // Next item won't fit here; penalize leaving awkward gaps.
            score += 4.0 * (1.0 - post_residual as f64 / 100.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Time-horizon scaling: early in the stream, be conservative (favor new bins
    // for large items to keep flexibility); later, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * tight_fit;

    // Global pressure: many open bins -> prefer filling existing ones.
    let pressure = (open_bins_count as f64).ln() / (1.0 + (bin_capacity as f64).ln());
    score -= 5.0 * pressure * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: if this bin's residual deviates below the mean,
    // it's a "small" bin — using it up balances the pool.
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let urgency = if fitting_bins_count == 0 { -20.0 } else { 8.0 + 10.0 * (1.0 - progress) };
        score += urgency;
        // A new bin is fine if the item is large (little flexibility lost).
        if item_size >= 60 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual [0,1]

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fits (penalize large post_residual quadratically).
    // Late: post_residual less costly, prefer using existing bins.
    let early = (1.0 - progress).powi(2);
    let late = progress.powi(2);
    score += 30.0 * early * norm_pr * norm_pr;
    score -= 20.0 * late * norm_pr * (1.0 - norm_pr);

    // Penalize dead space that cannot fit the next item (smooth cubic coupling).
    let nxt = next_item_size as f64 / cap;
    let unusable = (norm_pr - nxt).max(0.0);
    score += 15.0 * unusable * unusable * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize slightly unless residual is very large relative to mean.
    if bin_residual == bin_capacity {
        score += 10.0 + 25.0 * (mean_residual / cap) * (1.0 - progress);
    }

    // Mild reward when bin residual is close to mean residual (balance load).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Coupling with item size: big items in big-residual bins (smooth interaction).
    let isz = item_size as f64 / cap;
    score -= 10.0 * isz * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well does leftover space decompose
    // into capacity-fraction buckets (mod 25 / mod 10 structure)?
    let pr = post_residual;
    let quarter = pr / 25;           // 0..4 harmonic class on quarter-capacity grid
    let decile = pr % 10;            // fine-grained leftover class

    // Reward post_residuals that land exactly on "harmonic" boundaries
    // (0, 25, 50, 75): these are ideal targets for typical item sizes.
    if pr == 0 {
        score -= 60.0;               // perfect fit
    } else if pr % 25 == 0 {
        score -= 25.0;
    } else if pr % 10 == 0 {
        score -= 8.0;
    } else {
        // Penalize awkward leftovers: dead space under smallest item (1)
        // scaled by how far off the nearest multiple of 10 it is.
        score += (decile.min(10 - decile) as f64) * 1.5;
    }

    // Quarter-class coupling: leftovers in the 1..=24 class are only usable
    // by small items; penalize proportionally to how much capacity is wasted.
    score += quarter as f64 * 3.0;

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            let nxt_left = pr - next_item_size;
            if nxt_left % 25 == 0 || nxt_left % 10 == 0 {
                score -= 12.0;
            } else {
                score += 4.0;
            }
        } else {
            // next item cannot fit here; leftover becomes dead space
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a decent harmonic fit.
    if bin_residual == bin_capacity {
        score += 70.0;
        if fitting_bins_count <= 1 {
            score -= 65.0;
        }
    }

    // Prefer tight bins (low residual before placement) slightly.
    score += (bin_residual as f64) * 0.05;

    // Late in the stream, consolidate: penalize spreading across many bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 2 {
        score += (open_bins_count as f64) * 0.3 * (0.5 + 0.5 * progress);
    }

    // Mean residual alignment: bins far from the mean residual are less
    // predictable; mild penalty for deviation.
    score += ((bin_residual as f64) - mean_residual).abs() * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in [1..=15] is nearly unusable
    // dead space (min item size is small, but small gaps rarely match).
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual <= 15 {
        score += 40.0 * (1.0 - pr / 15.0) + 10.0; // worst for tiny gaps
    } else if post_residual > 15 && post_residual <= 30 {
        score += 8.0; // moderately risky gap
    } else if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    }

    // Tight fit reward: item consumes most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, allow opening a new bin for a clean fit.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 6.0 * pressure * (1.0 - progress);

    // New-bin candidate handling: empty bin has high raw residual; make it
    // attractive only when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        let next_fits = next_item_size as f64 <= bin_capacity as f64;
        score -= 5.0;
        if next_fits && fitting_bins_count == 1 {
            score -= 20.0; // poor fit everywhere -> open fresh bin
        }
        score += 0.5 * mean_residual; // prefer new bin when mean residual is large/fragmented
    }

    // Lookahead: if next item fits exactly into the post_residual, reward it.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) == 0 {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual && post_residual > 0 {
        score -= 10.0; // next item can still use the gap
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 12.0; // gap will be wasted for the known next item
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item exactly matches post_residual
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 800.0;
        } else if (post_residual as u32) >= next_item_size {
            // next item fits into the leftover: mild reward proportional to tightness
            score -= 200.0 * (1.0 - diff as f64 / bin_capacity as f64);
        } else {
            // leftover too small for next item: penalize dead space
            score += 50.0 + 0.5 * post_residual as f64;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize slightly so we only open new bins when open bins are truly bad
    if bin_residual == bin_capacity {
        score += 250.0;
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tightness;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits perfectly in the post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves a gap; mild penalty proportional to gap
            let gap = post_residual - next_item_size;
            score += 0.25 * gap as f64;
        } else {
            // next item won't fit here; penalize bins whose residual becomes dead space
            if post_residual < 10 {
                score -= 5.0; // tiny dead space is fine
            } else {
                score += 4.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Reward filling bins with small residuals (avoid spreading across many bins).
    let rel_fit = item_size as f64 / bin_residual as f64;
    score -= 10.0 * rel_fit;

    // Global state: many open bins with large mean residual -> prefer consolidating
    // into existing bins rather than opening new ones.
    if bin_residual < bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score -= 6.0 * pressure;
    } else {
        // New-bin candidate: penalize opening new bins when open bins have slack.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let slack = mean_residual - item_size as f64;
        if slack > 0.0 {
            score += 3.0 + 8.0 * (slack / bin_capacity as f64) * (1.0 - progress);
        }
        // Late in the stream, new bins are less costly to open early... keep mild penalty.
        score += 2.0 * (1.0 - progress);
    }

    // Nonlinear coupling: penalize creating residuals in awkward mid-range (11..=30)
    // that are hard to fill later.
    if post_residual >= 11 && post_residual <= 30 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual (tight fit)
    let mut score = pr;

    // Smooth non-linear penalty for medium dead space (quartic bump)
    score += 12.0 * pr_norm * (1.0 - pr_norm) * (pr_norm - 0.5).abs();

    // Stream-progress coupling: later in stream, penalize waste more strongly
    score += 20.0 * pr_norm * pr_norm * progress;

    // Lookahead: reward leaving room for the next item (smooth kernel)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = pr - nxt;
        if diff >= 0.0 {
            let closeness = 1.0 - diff / cap;
            score -= 15.0 * closeness * closeness;
        } else {
            score += 8.0 * (-diff / cap);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer bins with residuals near the mean (balance preservation)
    score += 3.0 * ((pr - mean_residual) / cap).abs();

    // Mild penalty for too many open bins
    score += 0.5 * open_bins_count as f64 * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into capacity-fraction buckets.
    // Classes: 0 (perfect), 1 (tiny, <10), 2 (small, <25), 3 (medium, <50), 4 (large).
    let cls = if post_residual == 0 { 0 }
        else if post_residual < 10 { 1 }
        else if post_residual < 25 { 2 }
        else if post_residual < 50 { 3 }
        else { 4 };
    score += match cls { 0 => -40.0, 1 => 15.0, 2 => 8.0, 3 => 0.0, _ => 12.0 };

    // Integer-division threshold: leftover divisible into coarse capacity fractions is reusable.
    let q = post_residual / 10; // decile class 0..10
    score -= (q as f64) * 2.5;  // larger coarse leftover is more reusable

    // Lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 60.0; // perfect chaining
        } else {
            score -= 25.0 - (slack as f64).min(30.0) * 0.5;
        }
    } else if next_item_size > 0 {
        // next item cannot use this leftover: penalize proportional to wasted potential
        score += (next_item_size as f64).min(post_residual as f64 + 20.0) * 0.15;
    }

    // Last chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        score += 55.0; // default penalty for opening a new bin
        // early in stream, cheap to open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * (1.0 - progress);
        // if current item is large relative to capacity, new bin is fine
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Prefer filling bins that are already tight relative to mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Modulo coupling: post_residual congruent to small multiples of 10 is attractive.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the worst outcome.
    // A residual below the minimum item size (1..100 interface => min 1,
    // but typical items are >=10) is "dead" unless exactly 0.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 + (dead_threshold - post_residual) as f64 * 3.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward placements that still allow the lookahead item to fit.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + next_item_size as f64 * 0.15;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // creates a stranded gap for the next item
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading to new bins;
    // make the empty-bin candidate less attractive when bins are already numerous.
    if bin_residual == bin_capacity {
        // New bin candidate: base cost plus pressure from open bins and stream progress.
        score += 15.0 + open_bins_count as f64 * 2.5
            + (step_index as f64 / (total_items.max(1) as f64)) * 20.0;
        // If existing bins fit poorly, opening new is relatively better:
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    } else {
        // Existing bin: mild reward for consolidating into fuller bins.
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
        // Penalize bins far below mean residual (wasteful spread) slightly.
        if (bin_residual as f64) > mean_residual + 20.0 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with slight non-linearity
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 15.0 / (1.0 + diff); // strong reward for perfect next-item match
        // Penalize leaving residual that is neither small nor matching next item
        if post_residual > 0 && post_residual < next_item_size {
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // Last item: only tightness matters
        score -= 5.0;
    }

    // Relative to mean residual: prefer bins already below-mean residual (consolidating)
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well
    if bin_residual == bin_capacity {
        let good_fit_exists = next_item_size > 0
            && post_residual <= next_item_size
            && (post_residual as i64 - next_item_size as i64).abs() <= 5;
        if good_fit_exists {
            score += 100.0; // don't open a new bin when lookahead fits well
        } else {
            score += 25.0; // modest penalty: prefer existing bins by default
        }
        // Late in stream, opening new bins is less harmful
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
    }

    // Slight preference to fill bins among many open bins (reduce fragmentation)
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness * 2.0).max(0.0);

    // Penalize dead space that no plausible future item can fill.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // tiny slivers are fine (near-perfect fill)
    } else if post_residual >= 10 && post_residual < 20 {
        score += 2.0; // awkward gap zone
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here anyway; mild penalty proportional to leftover
            score += (post_residual as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when existing bins are crowded
    // or mean residual is low (nothing useful to pack into).
    if bin_residual == bin_capacity {
        let pressure = (mean_residual < item_size as f64 * 1.2) as f64;
        let crowded = (open_bins_count as f64).ln().max(1.0);
        score += 15.0;               // base cost of opening a new bin
        score -= pressure * 30.0;    // worth it if open bins can't help
        score -= (open_bins_count == 0) as i32 as f64 * 100.0;
        let _ = crowded;
    } else {
        // Prefer fuller bins: reward low bin_residual relative to capacity.
        let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 12.0 * fill;
    }

    // Time horizon: early in the stream, be more conservative with new bins
    // (long future to exploit them); late, prefer closing bins tightly.
    let t = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - t); // cheaper to open bins early
    } else {
        score += 5.0 * t * (post_residual as f64 / bin_capacity as f64);
    }

    // Mean-residual global coupling: if this bin is much fuller than average, prefer it.
    score -= (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let it = item_size as f64;
    let nx = next_item_size as f64;

    // Base: post-residual with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling of residual waste with stream progress:
    // early on, tolerate slack; late, penalize dead space more strongly
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Perfect / near-perfect fit reward via smooth saturation term
    let fit_bonus = (norm_pr * 8.0).exp().ln_1p() * 20.0;
    score -= fit_bonus;

    // Reward when post-residual matches the next item (smooth gaussian-like term)
    if nx > 0.0 {
        let diff = (pr - nx) / cap;
        score -= 25.0 * (-40.0 * diff * diff).exp();
    }

    // Last-chance bin: strongly favor using it (smooth ramp via fitting_bins_count)
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Penalize bins far below the mean residual (poor consolidation) via smooth term
    let mean_gap = (mean_residual - pr) / cap;
    score += 10.0 * mean_gap * mean_gap;

    // Mild penalty for spreading across many open bins, smoothed by progress
    score += (open_bins_count as f64).ln_1p() * 2.0 * (1.0 - progress);

    // Slight preference for keeping new-bin option alive early
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - progress) - 10.0 * progress * (norm_pr - (1.0 - it / cap)).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: quantize dead space into capacity fractions ---
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap;

    // Exact-fit reward: post_residual in a "harmonic residue class" that small items can reuse.
    // Classes: multiples of 10 and 20 are highly reusable for typical item sizes.
    let harmonic_10 = post_residual % 10 == 0;
    let harmonic_20 = post_residual % 20 == 0;
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if harmonic_20 {
        score -= 18.0;
    } else if harmonic_10 {
        score -= 10.0;
    } else {
        // Penalize dead space in awkward classes: distance to nearest multiple of 10
        let dist = (post_residual as i64 % 10).min(10 - (post_residual as i64 % 10)) as f64;
        score += 2.5 * dist;
    }

    // Nonlinear waste penalty: dead space squared, scaled by fill fraction
    score += (post_frac * post_frac) * 25.0;

    // --- Lookahead coupling: can next_item_size fit into post_residual? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward keeping room for the next item; stronger if next fits exactly into a class
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0;
            score -= 0.3 * (20.0 - slack.min(20.0));
            if (post_residual % next_item_size.max(1)) == 0 {
                score -= 8.0; // next item divides residual exactly -> harmonic match
            }
        } else {
            // Next item won't fit here: penalize proportionally to how close it was (near-miss dead space)
            let miss = (next_item_size - post_residual) as f64;
            score += 0.25 * miss.min(30.0);
        }
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0; // strongly prefer using the only bin that fits before opening a new one
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: base cost plus pressure from open bins and mean residual
        score = cap - 5.0;
        score += 2.0 * (open_bins_count as f64).sqrt();
        // If mean residual across open bins is large, discourage opening a new bin
        score += 0.15 * mean_residual;
        // Early in stream, opening bins is fine; late in stream, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If a perfectly harmonic placement exists elsewhere, new bin loses appeal
        if harmonic_10 || post_residual == 0 { score += 15.0; }
    }

    // --- Mild tie-break toward tighter bins (small bin_residual) ---
    score += 0.05 * (bin_residual as f64 - item_size as f64).max(0.0);

    // --- Open bins pressure: with many open bins, favor filling existing ones ---
    if open_bins_count > 4 {
        score -= 0.5 * (open_bins_count as f64 - 4.0).min(6.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps below the minimum item size (1..10) are pure waste: heavy penalty.
    if post_residual >= 1 && post_residual < 10 {
        score += 60.0 - post_residual as f64 * 3.0;
    }
    // Small-but-usable gaps (10..20) are risky: moderate penalty, unless they
    // exactly fit the lookahead item.
    else if post_residual < 20 {
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0; // gap is perfectly usable by next item
        } else {
            score += 15.0;
        }
    }

    // Reward tight fits (small post_residual relative to bin).
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // --- Lookahead coupling ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.1 * next_item_size as f64;
        } else {
            // This bin becomes dead after placement; penalize proportionally.
            score += 0.15 * post_residual as f64;
        }
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive only if no open bin fits well
        // or the item is large and fits nothing tightly.
        let pressure = open_bins_count as f64 * 4.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin anyway
        } else if fitting_bins_count == 1 {
            // last-chance bin: strongly prefer using it over opening new
            score += 120.0;
        } else {
            // prefer existing bins slightly; new bin cost grows with count
            score += 40.0 + pressure * 0.5;
        }
    }

    // --- Last-chance pressure on existing bins ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // --- Open-bin pressure: discourage spreading when many bins are open ---
    score += 0.05 * open_bins_count as f64;

    // Prefer bins whose residual is close to the mean residual (harmony).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight stream-progression modulation: later, be more conservative
    // (favor filling existing bins harder).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: reward bins where post_residual matches next_item_size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 == next {
            score -= 500.0; // perfect 2-step chain
        } else if post_residual >= next_item_size {
            let diff = (post_residual as f64 - next).abs();
            if diff <= 10.0 {
                score -= 150.0 - diff * 8.0; // close chain match
            }
            // penalize large leftover that next item cannot use
            if next > post_residual as f64 {
                score += 30.0; // next item won't fit here anyway
            }
        } else {
            score += 50.0; // dead space relative to lookahead
        }
    }

    // Compare residual against mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad.
    if bin_residual == bin_capacity {
        score += 60.0;
        // If lookahead item equals remaining capacity chain potential, allow new bin
        if next_item_size >= 90 {
            score -= 40.0;
        }
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, penalize large leftover.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 18.0 * tightness * tightness;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose leftover can host the next item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 * (next_item_size as f64 / 100.0);
        } else {
            // leftover too small for next item: penalize proportionally to waste
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // When many fitting bins exist, prefer the emptiest-fitting (best fit handled by tightness),
    // but add mild penalty proportional to crowding to spread load.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Time horizon: early in stream, be conservative (favor new bins less); late in stream,
    // squeeze into existing bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 12.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global residual state: if mean residual across open bins is high, prefer filling
    // the emptier bins (reward deviation below mean).
    score += 4.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    // Penalize opening new bins when open bins can fit, scaled by how full this bin already is.
    if bin_residual == bin_capacity {
        // new-bin candidate: prefer it only if post_residual would be small (big items)
        score -= 8.0 * (item_size as f64 / bin_capacity as f64);
        score += 10.0 * (1.0 - progress);
    } else {
        score -= 3.0; // slight preference for existing bins
    }

    // Dead-space avoidance: leftover that nothing can use (very small but nonzero).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual (tight fit), non-linearly
    let mut score = pr as f64 * (1.0 + 0.8 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space matters more (less future to fix it)
    let progress_coupling = 1.0 + 1.5 * progress * progress + 2.0 * progress * norm_pr;
    score *= progress_coupling;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0 + 40.0 * progress;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if (post_residual as u64) >= next_item_size as u64 {
            score -= 12.0 + 10.0 * (next_item_size as f64 / cap);
        } else {
            // penalize leaving residual too small for next item
            score += 6.0 * (1.0 - norm_pr);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate handling: penalize opening a new bin, more so early
    // and when existing bins fit well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 60.0 + 30.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && item_size as f64 + next_item_size as f64 <= cap {
            // new bin can host both current and next item: soften penalty
            score -= 35.0;
        }
    }

    // Mean residual context: if this bin is far below mean residual, it's
    // relatively full already — favor using it
    score -= 0.5 * (mean_residual - pr) * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into residue classes of capacity.
    let class = post_residual % (bin_capacity / 4).max(1);
    // Dead space: residuals too small for typical future items are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit
    }

    // Penalize large wasted residuals quadratically but reward harmonic alignment.
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;
    score -= 8.0 * (class as f64 / (bin_capacity / 4) as f64);

    // Tight fit reward: item fills most of the bin.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            score += 5.0; // next item won't fit here anyway
        }
    }

    // New-bin candidate: only attractive when current bin fit is bad or bin nearly full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_fit = (item_size as f64 / bin_capacity as f64) < 0.5 && mean_residual > 30.0;
        if bad_fit && open_bins_count > 0 {
            score -= 15.0 + 10.0 * progress;
        } else {
            score += 50.0; // discourage opening new bins when fits exist
        }
    }

    // Mean residual coupling: prefer bins below mean residual (denser bins).
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Harmonic modulo threshold: post_residual divisible by common item sizes is reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual >= 20 && post_residual <= 40 && post_residual % 5 == 0 {
        score -= 4.0; // sweet-spot residuals matching typical item sizes
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are almost worthless.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // pure dead space
        } else if post_residual < 20 {
            score += 22.0; // barely usable for the smallest items
        } else if post_residual < 35 {
            score += 9.0;
        }
    } else {
        score -= 30.0; // perfect fill: strongly reward exact closure
    }

    // Reward good fits: small post_residual relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading; with few bins, opening a new one is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * (6.0 + 8.0 * progress);

    // Prefer bins whose residual is already below the mean (consolidate slack).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.15 * dev;

    // Lookahead: if the next item fits exactly into the post_residual,
    // strongly favor this placement (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual - next_item_size < 10 {
            score -= 18.0;
        } else {
            score -= 6.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // post_residual can't host the next item: mild penalty unless it's tiny.
        score += 5.0;
    }

    // New-bin candidate calibration: an empty bin has zero dead-space risk but
    // incurs full open-bin cost; make it competitive only when fits are poor.
    if bin_residual == bin_capacity {
        score += 18.0 + 3.0 * (open_bins_count.min(20) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins where post_residual matches next item size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.8 * gap;
        // Perfect 2-step chain: item fills bin, next item fills remainder
        if post_residual as u32 == next_item_size {
            score -= 300.0;
        }
        // If next item can't fit anywhere else, keep this bin tight instead
        if next_item_size > post_residual {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize large dead space relative to mean residual (fragmentation)
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.6 * dev;
    } else {
        score += 0.2 * dev; // slightly reward below-average residual
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize wasting a nearly-full bin on a small item
    if item_size < post_residual / 3 && post_residual > 0 {
        score += 40.0;
    }

    // Mild preference to fill existing bins rather than open new ones
    score -= 5.0 * open_bins_count as f64;

    // Slight urgency late in stream to consolidate
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (100.0 - post_residual as f64) / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual already lowers score,
    // add extra reward when post_residual is very small (near-perfect fit).
    if post_residual <= 5 {
        score -= 8.0;
    } else if post_residual <= 15 {
        score -= 3.0;
    }

    // Lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chain fit: subtract proportional to how snugly next item fits
            score -= 6.0 + 0.05 * (post_residual as f64 - next_item_size as f64).min(40.0);
        } else if post_residual >= next_item_size / 2 {
            // partial promise: mild reward
            score -= 1.5;
        } else {
            // post_residual likely dead space relative to lookahead: mild penalty
            score += 0.03 * post_residual as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid wasting capacity).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive only if the item is large (poor
        // candidates for sharing) or no other bin fits well.
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        if large_item {
            score -= 5.0;
        } else if fitting_bins_count <= 1 {
            // no real alternative
            score -= 4.0;
        } else {
            // penalize opening new bins for small items when alternatives exist
            score += 12.0 + 0.2 * item_size as f64;
        }
    }

    // Global state coupling: many open bins with high mean residual ->
    // prefer consolidating into existing bins (penalize new bins implicitly,
    // reward this bin if its residual is below mean, i.e. it's already tight).
    if open_bins_count > 0 {
        let spread = mean_residual - bin_residual as f64;
        if spread > 0.0 {
            score -= 0.04 * spread; // tighter-than-average bin is a good host
        } else {
            score += 0.02 * (-spread); // looser-than-average bin: mild penalty
        }
    }

    // Time horizon: late in the stream, waste matters more; early on,
    // keep flexibility (slightly prefer leaving room).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * progress; // amplify differences late in stream

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = (1.0 - progress) * norm_pr * norm_pr * cap + progress * norm_pr * cap;
    score = score * 0.5 + coupling;

    // Penalize large post-residual more aggressively late in the stream
    score += norm_pr * norm_pr * cap * (0.5 + progress);

    // Reward tight fits (small post residual) with smooth term
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * item_size as f64 * 0.3;

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: if next item fits in post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= (1.0 - slack / cap) * 20.0;
    } else if next_item_size > 0 {
        score += (next_item_size as f64 - pr) * 0.15;
    }

    // Penalize bins whose residual is far below mean residual (wasteful bins)
    score += (mean_residual - pr).abs() * 0.05;

    // Mild pressure against hoarding many open bins early
    score += open_bins_count as f64 * 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well it aligns with common item sizes (multiples of 10, and 1..100 generally)
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Penalize post_residuals that are "dead zones": small but nonzero, hard to fill.
    // Class by integer division thresholds.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual < 10 {
        score += 45.0; // dead space < smallest typical item
    } else if post_residual < 25 {
        score += 15.0;
    } else if post_residual < 50 {
        score += 5.0;
    }

    // Modulo coupling: post_residual divisible by 10 leaves reusable chunks
    let m10 = post_residual % 10;
    score -= (10 - m10) as f64 * 0.6; // reward near-multiples of 10

    // Lookahead: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
            // extra reward if next item exactly matches a harmonic class of the residual
            if post_residual % next_item_size.max(1) == 0 {
                score -= 12.0;
            }
        } else {
            // next item won't fit here; penalize slightly more if residual is small
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: prefer reusing open bins early; allow new bins
    // when existing residuals are fragmented (high mean residual spread).
    if bin_residual == bin_capacity {
        // new bin: score = full capacity baseline, adjusted by stream progress & open bins
        score = cap;
        score -= (step_index as f64 / (total_items.max(1) as f64)) * 10.0;
        if open_bins_count > 0 {
            score += 8.0;
        }
        // if mean residual across open bins is small (fragmented), opening new bin is attractive
        score -= mean_residual * 0.15;
    } else {
        // existing bin: tie score to mean residual alignment
        score += (mean_residual - pr) * 0.1;
    }

    // Progress-based tightening: later in the stream, waste matters more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += pr * 0.35 * progress;

    // Mild penalty for very tight fits that leave awkward remainders (residual % item small but nonzero)
    if item_size > 0 && post_residual > 0 && post_residual % item_size != 0 && post_residual < item_size * 2 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // minimum item are pure waste; penalize them quadratically.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // perfect fill, strongly favored
    } else if post_residual <= 10 {
        // small gap likely unusable: dead-space penalty
        score += (11.0 - post_residual as f64) * (11.0 - post_residual as f64) * 2.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
        score -= tightness * 8.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // current bin would leave a large awkward gap OR no open bin fits well.
    if bin_residual == bin_capacity {
        // mild baseline preference for reusing bins; new bin starts neutral
        score += 5.0 + (open_bins_count as f64) * 0.5;
        // if lookahead item is large, a fresh bin is valuable
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Open-bin pressure: many open bins -> consolidate into existing bins.
    score += (open_bins_count as f64) * 0.3;

    // Mean residual coupling: if mean residual across bins is high, prefer
    // placements that consume more space (lower post_residual).
    score += (mean_residual - post_residual as f64).max(0.0) * 0.2;

    // Lookahead synergy: if next item fits exactly into post_residual,
    // strongly reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
    } else if next_item_size > post_residual {
        // next item can't use the leftover; leftover is dead space
        score += (post_residual as f64) * 0.5;
    }

    // Slight early-stream tolerance for spreading (more info later).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills the post residual (2-step lookahead match).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Partial lookahead match: reward proportionally to how well next item fits.
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        score -= 25.0 * fit_ratio;
    } else if next_item_size > post_residual {
        // Next item cannot use this residual: penalize proportionally to wasted potential.
        score += 10.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // Reward bins tighter than the mean residual (good compacting), penalize looser ones.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Penalize creating large dead space that nothing (between 1 and post_residual) can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Mild preference for opening a new bin early when many bins are open and residual is large.
    if bin_residual == bin_capacity {
        score -= 5.0;
    }

    // Slight progression-aware tightening: later in the stream, prefer tighter fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item nearly fills the residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Perfect fit gets a large bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item also fits in the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
        // Extra reward if next item fills it almost exactly afterwards.
        let after_next = post_residual - next_item_size;
        if after_next < 10 {
            score -= 12.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalize creating dead space the known next item cannot use.
        let waste = post_residual as f64 / (next_item_size as f64);
        if waste < 0.5 {
            score += 10.0 * (1.0 - waste);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin, but allow it when
    // existing fits are poor (large post_residual) or late in the stream with
    // many open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit_pressure = (post_residual as f64) / (bin_capacity as f64);
        score += 25.0
            + 40.0 * (1.0 - poor_fit_pressure)
            - 15.0 * progress
            - 2.0 * (open_bins_count as f64).ln().max(0.0);
        // If the next item is large and this new bin would leave a big residual,
        // opening a fresh bin is more attractive (it preserves flexibility).
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0;
        }
    }

    // Global residual state: if mean residual across open bins is high, prefer
    // consolidating into existing space (penalize new bins implicitly by
    // rewarding use of bins below the mean residual).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 3.0;
        }
    }

    // Time-horizon coupling: early in the stream, be conservative (avoid
    // fragmenting bins); late in the stream, exploit tight fits more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    // Small penalty for leaving residuals that are awkwardly small (dead space
    // below the minimum plausible item size).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Base: penalize post_residual quadratically (dead space is bad, superlinearly).
    let pr = post_residual as f64;
    let mut score = pr + 0.9 * (pr * pr) / cap;

    // Tight-fit reward: smooth coupling of fit quality with stream progress.
    let fit_ratio = 1.0 - pr / cap;
    score -= 25.0 * fit_ratio * fit_ratio * (0.5 + progress);

    // Reward using bins with large residual (consolidate space).
    let br = bin_residual as f64;
    score -= 6.0 * (br / cap) * (br / cap);

    // Lookahead: if next item fits the post residual, bonus; else mild penalty.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 12.0 * (1.0 - pr - nx) / cap * (1.0 + progress);
        } else {
            score += 4.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize relative to open bins count and mean residual.
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64 + 0.5 * mean_residual;
        // Late in stream, opening a new bin is cheaper than fragmenting.
        score -= 15.0 * progress * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 buckets.
    // Small post_residual = tight fit = reward; large = dead space = penalize.
    let pr = post_residual as f64;
    let class = (post_residual % 10) as f64;
    score += 0.35 * (class / 9.0); // within-class dead space penalty

    // Perfect fit reward (harmonic zero class).
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 12.0;
    } else if post_residual <= 30 {
        score += 6.0;
    } else {
        score += 14.0;
    }

    // Lookahead: does next item fit into the post-residual (harmonic chaining)?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain bonus scaled by how snugly next item fits.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 25.0 + 15.0 * snug;
        } else {
            // Next item won't chain here; slight penalty proportional to overshoot class.
            let over = (next_item_size - post_residual) % 10;
            score += 3.0 + 0.4 * over as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill_frac * (open_bins_count.min(20) as f64 / 20.0);

    // Early stream: be slightly greedy toward tight fits; late stream: consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * fill_frac * progress;
    score += 5.0 * (1.0 - progress) * (pr / bin_capacity as f64);

    // New-bin candidate: only attractive when current item badly fits everywhere.
    if bin_residual == bin_capacity {
        let bad_fit = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let large_item = item_size as f64 / bin_capacity as f64;
        score = 60.0 - 50.0 * bad_fit - 20.0 * large_item * progress;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score += 10.0; // empty bin can't chain next item either
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1)
    // are dead space; anything below a "usable gap" threshold is heavily penalized.
    let min_item = 1u32;
    if post_residual < min_item && post_residual > 0 {
        score += 1000.0; // pure dead space
    }
    // Small gaps that likely cannot host future items (typical sizes 10..80,
    // unknown distribution so be conservative): penalize gaps < 10 strongly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Medium gaps (< 25) are semi-risky: mild penalty proportional to gap smallness.
    if post_residual >= 10 && post_residual < 25 {
        score += 8.0 * (25.0 - post_residual as f64);
    }

    // Reward tight fits (exact fill is ideal).
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: penalize spreading across many bins; encourage filling
    // existing bins when the count grows.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins whose residual is below the mean (consolidate fullness).
    score += ((bin_residual as f64) - mean_residual) * 0.3;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.35 };
        // Baseline new-bin score anchored to mean residual; opening a fresh bin
        // should lose only against bins leaving large dead space.
        score = bin_capacity as f64 * 0.9 * desperation + open_bins_count as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect 2-step match: post_residual == next_item_size exactly
            if post_residual == next_item_size {
                score -= 45.0;
            } else {
                score -= 12.0;
                // Penalize leftover after the 2-step chain
                let after_next = post_residual - next_item_size;
                if after_next < 10 {
                    score += (10 - after_next) as f64 * 0.6;
                }
            }
        } else {
            // Next item cannot chain into this bin: penalize wasted pairing potential
            score += 8.0;
        }
    } else {
        // Last item: only final residual matters
        score -= 5.0;
    }

    // Relative-to-mean coupling: bins tighter than mean are better targets
    let rel = post_residual as f64 - mean_residual;
    score += rel * 0.35;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when good fits exist elsewhere
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tightness = 1.0 - (item_size as f64 / bin_capacity as f64);
        score += 25.0 + 20.0 * progress * tightness;
        // But allow new bin if it would create a perfect 2-step chain and few bins fit
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 2 {
            score -= 40.0;
        }
    }

    // Dead-space penalty: residuals below minimum item size are wasted
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.0;
    }

    // Mild preference to consolidate when many bins are open
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot fit even the smallest item
    if post_residual < 10 {
        score -= 15.0; // small dead space is fine (bin nearly full)
    } else if post_residual < item_size {
        // residual too small for a repeat item: potential waste
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // when multiple bins fit, favor the fullest one (best-fit behavior)
        score -= (bin_residual as f64 / bin_capacity as f64) * 12.0;
    }

    // Lookahead: reward bins whose post-residual can hold the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.4;
        }
    }

    // Global pressure: many open bins -> prefer filling existing ones
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score -= pressure.min(20.0) * 1.5;

    // Mean-residual coupling: if average residual is large, avoid wasting space here
    score += (mean_residual - post_residual as f64).abs() * 0.3;

    // New-bin candidate handling: empty bin gets a time-varying bias.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early on, opening bins is cheap; later, avoid proliferating bins
        let new_bin_penalty = 20.0 + 60.0 * progress;
        score += new_bin_penalty;
        // But if no open bin fits well, allow a new bin
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Dynamic time horizon: near end of stream, prioritize compacting residual space
    let horizon = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * horizon * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted residual, with progress-dependent curvature
    let mut score = pr * (1.0 + 0.9 * progress * progress);

    // Smooth non-linear coupling: quadratic residual term modulated by progress
    score += 30.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Lookahead: favor bins whose post_residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 18.0 * (1.0 - slack * slack);
        } else {
            let gap = (nxt - pr) / cap;
            score += 15.0 * gap * gap;
        }
    } else {
        // Last item: minimize residual directly
        score += 20.0 * norm_pr;
    }

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 - norm_pr);
    }

    // Mild crowding penalty to encourage bin consolidation
    score += 0.8 * open_bins_count as f64 * (0.3 + progress);

    // Pull toward mean residual to balance bin usage smoothly
    score += 0.15 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "large-waste" classes (mod 20 buckets) are penalized; tight fits rewarded.
    let cap_frac = post_residual as f64 / bin_capacity as f64;

    // Reward small post_residual non-linearly (best-fit core with sharpening).
    score -= 30.0 * (1.0 - cap_frac).powf(3.0);

    // Modulo-class penalty: leftover in (0,10] is nearly dead space for items >=10,
    // but with 1..100 items small leftovers can still be useful; scale by class.
    let class = post_residual % 20;
    let class_penalty = match class {
        0 => -8.0,                      // perfectly reusable chunk
        1..=5 => 6.0,                   // nearly dead
        6..=12 => 2.0,                  // marginal
        13..=19 => -2.0,                // decent chunk
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division threshold on post_residual: can it host the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin remains chainable: reward proportional to chaining slack.
            score -= 10.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
        } else {
            // Bin becomes dead after this placement; penalize unless residual ~0.
            score += 12.0 * (post_residual as f64 / 20.0).min(1.5);
        }
        // Perfect pair: item + next exactly fills the bin.
        if item_size + next_item_size == bin_residual {
            score -= 25.0;
        }
    } else {
        // Last item: strongly prefer filling bins as tightly as possible.
        score -= 20.0 * (1.0 - cap_frac);
    }

    // Last-chance bin: if only this bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: neutral baseline, opened only when open bins score poorly.
    if bin_residual == bin_capacity {
        score = 55.0
            - 10.0 * (item_size as f64 / bin_capacity as f64)
            + (open_bins_count as f64).powf(0.5);
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0; // fresh bin can host the pair cleanly
        }
        if fitting_bins_count <= 1 {
            score += 20.0; // don't abandon the only usable bin
        }
    }

    // Late-stream pressure: consolidate as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - cap_frac);

    // Mild preference for bins below mean residual (balance residual mass).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: small non-zero post_residuals are the worst outcome.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable tiny gap (items >= 1, but tiny gaps waste capacity)
        } else if post_residual < 25 {
            score += 25.0; // hard-to-fill gap
        } else if post_residual < 50 {
            score += 8.0;
        }
    } else {
        score -= 40.0; // perfect fit: strongly reward
    }

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when open bins have poor fits.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
        // If next item could combine with current item in a fresh bin, encourage opening.
        if next_item_size > 0 && (next_item_size as f64 + item_size as f64) <= bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Pressure from many open bins: prefer consolidating into existing bins.
    score += 0.8 * open_bins_count as f64;

    // Prefer bins whose residual deviates from the mean residual (targeted packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.15 * dev;

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here anyway; small post_residual less harmful
        score += 0.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // next_item_size is worse (next item likely can't use it).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bin can also host the next item: strong reward.
            score -= 12.0 + 0.25 * (post_residual - next_item_size) as f64;
        } else {
            // Dead space penalty: unusable by the lookahead item.
            score += 0.6 * (next_item_size - post_residual) as f64;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Compare residual against mean residual: prefer filling bins that are
    // already low (below mean) to compact occupancy.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild penalty for opening a brand-new bin when many bins are open.
    if bin_residual == bin_capacity {
        score += 6.0 + 0.4 * open_bins_count as f64;
    }

    // Late in the stream, compactness matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual near zero is ideal).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use this residual; mild penalty proportional to waste.
            score += 5.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: prefer consolidating into existing bins (avoid bin sprawl).
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64);
    score += 15.0 * pressure;

    // If this bin's residual is far from the mean residual, slight penalty
    // (prefer bins whose residual matches the typical leftover profile).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: early in the stream, be more willing to open new bins
    // (better long-run packing); late in the stream, squeeze existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Brand-new empty bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin unless current item leaves a large,
        // reusable residual or few bins exist.
        score += 20.0;
        if item_size >= 50 && post_residual >= item_size {
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits, must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Base: prefer small post-residual, with non-linear (quadratic) shaping.
    let mut score = pr + 18.0 * norm_post * norm_post * cap;

    // Smooth coupling of post-residual with stream progress:
    // late in the stream, tighten the penalty on leftover space.
    let late = progress * progress;
    score += 40.0 * late * norm_post * norm_post * cap;

    // Reward tight fits (small post_residual relative to item size) more strongly as stream advances.
    let tightness = item_size as f64 / (item_size as f64 + pr + 1.0);
    score -= 25.0 * tightness * (0.5 + progress);

    // Penalize bins far below mean residual only mildly; smooth cubic coupling with progress.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev * dev.signum() * (1.0 + progress);

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - norm_post);
    }

    // Lookahead: if next item can use the post-residual, reward this bin.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_ratio = nx / pr.max(1.0);
            score -= 20.0 * fit_ratio * (1.0 - progress * 0.5);
        } else {
            // dead space for the known next item: penalize smoothly.
            score += 10.0 * ((nx - pr) / cap) * (0.5 + progress);
        }
    }

    // Slight preference for consolidating into fewer bins when many are open.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: items come in sizes 1..=100,
    // so classify post_residual by divisibility classes (mod 10 / mod 20),
    // which capture "usable" leftover sizes for common item sizes.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Reward residuals that are multiples of 10 (harmonic anchors).
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    }
    if pr % 20 == 0 && pr > 0 {
        score -= 4.0;
    }
    // Perfect closure: exact fit leaves nothing wasted.
    if pr == 0 {
        score -= 25.0;
    }

    // Penalize dead space: residuals too small for the smallest plausible item.
    if pr > 0 && pr < 10 {
        score += 12.0;
    }
    // Integer-division thresholds on post_residual: unusable slivers.
    let sliver_class = pr / 5; // coarse class of leftover
    if sliver_class <= 1 && pr > 0 {
        score += 8.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Reward leaving room for the known next item, scaled by tightness.
            let tight = (pr as f64 - next_item_size as f64) / cap;
            score -= 10.0 * (1.0 - tight);
            // Extra harmonic bonus if next item lands on a multiple-of-10 class.
            if (pr - next_item_size) % 10 == 0 {
                score -= 3.0;
            }
        } else {
            // Next item won't fit here: penalize proportionally to overshoot class.
            let overshoot = next_item_size - pr;
            score += (overshoot / 10) as f64 * 2.5;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the fit here is bad.
    if bin_residual == bin_capacity {
        // Fresh bin baseline: neutral-ish, penalize if current fit is decent.
        score += 5.0 + mean_residual * 0.05;
        if post_residual >= 20 {
            score += 10.0; // discourage wasting a new bin on good fits
        }
    } else {
        // Favor tighter fits among open bins (small post_residual relative to capacity).
        score -= 10.0 * (1.0 - post_residual as f64 / cap);
    }

    // Stream progression: later in stream, be more conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 8.0 * progress;
    }

    // Many open bins with high mean residual: encourage consolidating into existing bins.
    if open_bins_count > 3 && mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual > 0 && post_residual < 5 {
        score += 40.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that next item cannot use.
        score += 10.0;
    }

    // Last-chance fitting: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new bins; new-bin candidate gets penalized.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure.
        score += 30.0 + 2.0 * pressure;
    } else {
        score -= 1.5 * pressure;
    }

    // Progress-aware tightness: later in the stream, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.3;

    // Prefer bins below mean residual (balancing residual distribution).
    score += 0.2 * ((post_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // bonus proportional to how snugly the next item fits in leftover
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 60.0 * snug;
        } else {
            // leftover too small for next item: penalize dead space, worse near mean residual
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
            if (post_residual as f64) < mean_residual {
                score += 20.0;
            }
        }
    } else {
        // last item: prefer tightest fill overall
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else {
        score += 5.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: only attractive when open bins would leave large waste
    if bin_residual == bin_capacity {
        let waste_if_open = post_residual as f64;
        let best_alt_waste = mean_residual - item_size as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 200.0; // an existing bin with lookahead fit beats a fresh bin
        }
        if waste_if_open > best_alt_waste.max(0.0) + 15.0 {
            score -= 30.0; // fresh bin wastes less than alternatives
        } else {
            score += 50.0; // prefer filling existing bins
        }
    }

    // Slight preference for fuller bins relative to mean residual
    score += 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // Early in stream: be a bit more willing to open bins for good structure
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 40.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: penalize if the next item could fit in the post residual,
    // since wasting that space now is costly; reward if it won't fit anyway.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score += 0.6 * (next_item_size as f64) * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else {
            score -= 0.3 * (post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Dead-space penalty: very small post residual is good unless it's exactly 0-ish
    // fragmented slivers; small but nonzero residuals are less useful.
    if post_residual > 0 && post_residual < 10 {
        score += 4.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Prefer bins whose residual is close to the item (tight fit) beyond raw post residual.
    score += 0.2 * ((bin_residual as f64 - item_size as f64).abs());

    // Global state: when many bins are open with large mean residual, discourage
    // opening new bins (penalize the empty-bin candidate implicitly via tightness term).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, modulated by how fragmented current bins are.
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score = bin_capacity as f64 - 10.0 * fragmentation * (1.0 - progress) + 20.0 * progress;
        if fitting_bins_count == 1 {
            score += 60.0; // never open new bin when a last-chance fit exists
        }
    }

    // Mild time-decay of lookahead value: early on, be greedy; later, consolidate.
    score -= (1.0 - progress) * 0.1 * (bin_capacity - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = (bin_residual == bin_capacity) as f64;

    // Base: prefer small post-residual (tight fit), non-linearly scaled.
    let mut score = 40.0 * (pr / cap).powf(1.6);

    // Smooth coupling of tightness with stream progress: late in the stream,
    // dead space becomes more costly (fewer chances to fill it).
    score += 30.0 * (pr / cap) * progress * (1.0 - progress * 0.5);

    // Reward filling a bin nearly completely, stronger as stream advances.
    let fill = 1.0 - pr / cap;
    score -= 25.0 * fill.powf(3.0) * (0.5 + progress);

    // Penalize opening a new bin unless the fit is good; the penalty grows
    // smoothly with how many open bins could already fit the item.
    let fit_ratio = if fitting_bins_count > 0 { 1.0 / fitting_bins_count as f64 } else { 1.0 };
    score += is_new_bin * (15.0 + 20.0 * fit_ratio + 10.0 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && is_new_bin < 0.5 {
        score -= 12.0 + 8.0 * progress;
    }

    // Lookahead: if next item fits exactly into the resulting residual, reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs() / cap;
        score -= 10.0 * (1.0 - gap.min(1.0)).powf(2.0);
        // Penalize leaving residual just below next item (blocking).
        if pr < nxt && pr > 0.0 {
            score += 8.0 * (pr / nxt) * (1.0 - progress * 0.5);
        }
    }

    // Mild dispersion penalty: prefer bins whose residual is near the mean
    // (keeps residuals homogeneous, easier to combine later).
    score += 0.05 * ((pr - mean_residual) / cap).abs();

    // Slight preference for bins with more residual when few bins are open.
    score += 3.0 * (pr / cap) * (1.0 / (1.0 + open_bins_count as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but penalize tiny unusable slivers harshly.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Harmonic class of post_residual: dead-space classes modulo small integers.
    // Slivers of 1..=5 are nearly dead; class them as worst.
    let dead = if post_residual > 0 && post_residual <= 5 { 1.0 } else { 0.0 };
    score += dead * 40.0;

    // Perfect fit (post_residual == 0) is ideal — strong reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Modulo-class coupling: residuals that are multiples of common item
    // granularities (10/20/25) are more reusable by future items.
    let reusable = ((post_residual % 10 == 0) as i32
        + (post_residual % 20 == 0) as i32
        + (post_residual % 25 == 0) as i32) as f64;
    score -= reusable * 6.0;

    // Odd residuals (not divisible by 2) tend to be less reusable.
    if post_residual % 2 == 1 && post_residual > 0 {
        score += 3.0;
    }

    // Integer-division threshold: residuals in [1, 9] are the "dead band"
    // for typical item sizes (>= 10 originally), penalize by band depth.
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 2.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 25.0;
        if post_residual == 0 { score -= 20.0; }
    }

    // Lookahead: reward if next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            // residual left after next hypothetical placement
            let post2 = post_residual - next_item_size;
            if post2 <= 5 { score += 8.0; } else { score -= 5.0; }
        } else {
            // next item cannot use this residual: residual is more likely dead
            score += 6.0;
        }
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no open bin fits well (tight fits win otherwise).
    if bin_residual == bin_capacity {
        // Mild penalty so tight existing fits are preferred...
        score += 10.0;
        // ...but if the item is large relative to capacity, opening fresh
        // avoids fragmentation.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 15.0;
        }
        // Few open bins -> keep consolidation pressure low.
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Progress-aware pressure: early in the stream, tolerate more open bins
    // (keep residuals spread); late in the stream, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 8.0;

    // Deviation from mean residual: prefer bins whose residual is close to
    // the mean (balanced packing), slightly.
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    // Tie-break preference for fuller bins among equals.
    score -= (bin_residual as f64 / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead-space pressure scales with how many bins are already open.
    let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    if post_residual > 0 && post_residual < 20 {
        score += 40.0 * open_pressure;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate: only attractive when it enables a good future fit
    // or when open bins would leave large dead space.
    if bin_residual == bin_capacity {
        // Slight bias against opening new bins early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 5.0;
        }
    }

    // Prefer bins with below-average residual (tighter packing).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0; // perfect 2-chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize wasted post_residual that could have held it
            let miss = (next_item_size - post_residual) as f64;
            score += 0.5 * miss;
        }
    } else {
        // last item: just minimize post_residual strongly
        score += 20.0 * tightness;
    }

    // Compare residual against mean residual across open bins
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 1.0 {
            score -= 15.0 * (1.0 - rel); // tighter than average: good
        } else {
            score += 10.0 * (rel - 1.0); // looser than average: bad
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many open bins: prefer consolidating into existing bins
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: penalize unless current bin fit is poor
    if bin_residual == bin_capacity {
        let threshold = 30.0 + 40.0 * (step_index as f64 / total_items.max(1) as f64);
        if post_residual as f64 > threshold {
            score -= 20.0; // opening fresh bin is fine when existing fits are bad
        } else {
            score += 60.0; // otherwise strongly prefer existing bins
        }
    }

    // Early stream: be slightly more open to new bins (build good structure)
    if (step_index as f64) < 0.1 * total_items.max(1) as f64 && bin_residual == bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect or near-perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 300.0;
    }

    // Reward tight fits relative to item size
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 20.0 / (1.0 + tightness);

    // Last chance bin: strongly favor using it, else bin's space is stranded
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 250.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves more fragmentation; mild reward scaled by fit quality
            let nxt_fit = (post_residual - next_item_size) as f64;
            score -= 40.0 / (1.0 + nxt_fit);
        } else {
            // next item won't fit here: penalize leaving awkward residuals the next item can't use
            if post_residual > 0 && post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 0.3;
            }
        }
    }

    // New-bin candidate handling: penalize opening a new bin unless existing fits are poor
    if bin_residual == bin_capacity {
        let mut new_bin_score = post_residual as f64 + 60.0;
        // If many bins fit the item, opening a new bin is wasteful
        if fitting_bins_count > 0 {
            new_bin_score += 40.0 * (fitting_bins_count as f64).min(5.0);
        }
        // Late in stream with tight open bins, new bin more acceptable
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score -= 30.0 * progress;
        // If mean residual of open bins is small (bins nearly full), new bin is fine
        if mean_residual < item_size as f64 * 1.2 {
            new_bin_score -= 50.0;
        }
        score = new_bin_score;
    } else {
        // Prefer bins with smaller residual generally (best-fit flavor), modulated by global state
        score += (mean_residual - bin_residual as f64) * 0.15;
        // Slight preference to fill bins that have been open a while (many bins open => consolidate)
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize post_residual non-linearly (quadratic waste growth)
    let mut score = pr * (1.0 + norm_pr);

    // Smooth coupling: late in stream, waste is costlier
    score += 20.0 * norm_pr * norm_pr * progress;

    // Reward tight fits via smooth saturating term on post_residual
    score -= 8.0 * (1.0 - (norm_pr * 4.0).min(1.0)) * (1.0 - progress);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: bonus if next item fits the post-residual smoothly
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64 <= pr) as i32 as f64;
        let snug = 1.0 - ((next_item_size as f64 - pr).abs() / cap);
        score -= 10.0 * fits_next * snug.max(0.0);
        // Penalize residual that neither fits next item well nor is tiny
        score += 5.0 * (1.0 - fits_next) * norm_pr;
    }

    // Prefer bins below mean residual slightly (balance avoidance of many near-empty bins)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: baseline so it loses unless open bins are poor
    if bin_residual == bin_capacity {
        score += 25.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftover divisible by common item
    // sizes (10, 20, 25, 50) is more reusable than arbitrary dead space.
    let r = post_residual;
    if r > 0 {
        let mut reusable = false;
        for d in [10u32, 20, 25, 50] {
            if r % d == 0 { reusable = true; }
        }
        if reusable { score -= 6.0; } else { score += 4.0; }
    } else {
        // Perfect fit is ideal
        score -= 20.0;
    }

    // Dead-space penalty grows for very small unusable leftovers
    if r > 0 && r < 10 {
        score += 8.0;
    }

    // Harmonic class of item size: large items (half capacity or more)
    // prefer tight bins; small items prefer bins whose residual keeps
    // harmonic classes alive.
    let half = bin_capacity / 2;
    if item_size >= half {
        score -= (item_size - half) as f64 * 0.15;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 15.0;
        } else if next_item_size < r {
            score -= 2.0;
        } else {
            // next item cannot fit here; slight penalty
            score += 1.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // Prefer filling bins when many bins are open (consolidation)
    if bin_residual < bin_capacity {
        score -= mean_residual * 0.05;
    }

    // New-bin candidate: penalize mildly so it only wins when fits are bad,
    // but more attractive early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 3.0 - 2.0 * progress;
    }

    // Integer-division threshold: residual buckets by quarter capacity
    let quarter = bin_capacity / 4;
    if r >= quarter && r < 2 * quarter {
        score -= 1.5;
    } else if r >= 2 * quarter && r < 3 * quarter {
        score -= 2.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps
    if post_residual > 0 && post_residual < 10 {
        score += 1000.0;
    }
    // Penalize post_residual that cannot fit even the smallest future item (1..100)
    if post_residual > 0 && post_residual < 20 {
        score += 50.0;
    }

    // Reward tight fits
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Open-bin pressure: discourage spreading across many bins unless fit is tight
    score += open_bins_count as f64 * 0.5;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    } else if next_item_size > 0 && next_item_size > bin_residual {
        score += 3.0;
    }

    // Mean-residual coupling: prefer bins with residual near/below mean (avoid hoarding space)
    score += ((bin_residual as f64) - mean_residual).abs() * 0.2;

    // New-bin candidate: mild penalty so we prefer existing bins unless fit is poor
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: minimize post_residual (tight fit preferred)
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Aggressive 2-step lookahead: reward if next item exactly fits post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt).abs();
        if pr >= nxt {
            // next item fits perfectly -> strong reward
            score -= (40.0 * (1.0 - diff / cap)).max(0.0);
        } else {
            // next item does not fit: penalize leaving a gap close to but below next size
            score += 8.0 * (1.0 - (nxt - pr) / cap);
        }
    }

    // Penalize dead space far from mean residual (fragmentation)
    score += 0.5 * (pr - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current bin fit is terrible
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * (it / cap);
    }

    // Late in stream: prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (pr / cap);

    // Prefer bins with larger residual consumed relative to capacity
    score -= 10.0 * (1.0 - bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit — reward small post_residual.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual as f64; // 0..1, higher = tighter

    // Reward tight fits nonlinearly.
    score -= fit_ratio * fit_ratio * 30.0;

    // Penalize dead space: small post_residual that cannot fit typical items is fine,
    // but mid-range waste is bad. Penalize post_residual in the "awkward" zone (1..~10)
    // lightly, and large post_residual handled by base term already.
    if post > 0.0 && post < 8.0 {
        score -= 6.0; // near-perfect fill
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic: an empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; shrinks late in the stream (little to lose).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_cost = 20.0 * (1.0 - 0.5 * progress);
        // If many open bins and none fits tightly, new bin more attractive.
        if mean_residual < item_size as f64 {
            new_bin_cost -= 10.0;
        }
        // If next item is large, a fresh bin is valuable for it.
        if next_item_size as f64 > 0.6 * cap {
            new_bin_cost -= 8.0;
        }
        score += new_bin_cost;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward strongly.
    if next_item_size > 0 && (post_residual as u64) == (next_item_size as u64) {
        score -= 18.0;
    } else if next_item_size > 0 && (next_item_size as u64) <= (post_residual as u64) {
        // Next item fits: mild reward proportional to how much of post_residual it uses.
        let use_ratio = next_item_size as f64 / post.max(1.0);
        score -= 8.0 * use_ratio;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item does NOT fit here: penalize leaving residual that tempts but fails.
        score += 5.0;
    }

    // Global state: many open bins with high mean residual -> encourage consolidation
    // into existing bins (penalize spreading).
    if open_bins_count > 2 {
        let consolidation = (mean_residual / cap).min(1.0);
        score += consolidation * 6.0 * (open_bins_count as f64).ln().max(1.0) * 0.5;
    }

    // Prefer filling bins with large residuals when item is large (avoid fragmenting).
    if item_size as f64 > 0.6 * cap && bin_residual >= item_size {
        score -= 5.0 * (bin_residual as f64 / cap);
    }

    // Small early-stream tiebreaker: keep scores distinct.
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post residual, with non-linear sharpening
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Polynomial coupling of post_residual with stream progress:
    // early on tolerate slack (favor tightness less), later tighten aggressively.
    let progress_coupling = pr_norm * (1.0 - progress) * progress * 4.0;
    score += 30.0 * progress_coupling;

    // Penalty if post residual becomes dead space that next item cannot use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (1.0 + 0.3 * progress);
        } else {
            // reward leaving room exactly for the next item
            let waste = pr - nxt;
            score -= 8.0 * (1.0 - (waste / cap)).max(0.0) * (1.0 - progress);
        }
    } else {
        // last item: strongly prefer filling bins as tightly as possible
        score += 0.0 * pr_norm;
        score -= 10.0 * (1.0 - pr_norm);
    }

    // Last-chance bonus: if this is the only fitting bin, discourage opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - pr_norm);
    }

    // Mild preference to keep bins balanced relative to mean residual
    score += 2.0 * (pr - mean_residual).abs() / cap;

    // Discard almost-empty residual space waste (dead space penalty, smooth)
    score += 12.0 * pr_norm * pr_norm * pr_norm * progress;

    // Slight penalty for new bin when many bins already open and progress is high
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: capacity split into 10 classes of 10 units
    let res_class = post_residual / 10;
    let res_phase = post_residual % 10;

    // Reward residuals that form "harmonic" sizes (multiples of 10 or 25):
    // these are more likely reusable by future items.
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 {
        score -= 4.0;
    }
    // Penalize odd phase (off-class dead space)
    score += (res_phase as f64) * 0.35;

    // Non-linear penalty on small but nonzero residuals (dead space zone)
    if post_residual > 0 && post_residual <= 9 {
        score += (10 - post_residual) as f64 * 1.5;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: does next item fit harmonically into the post residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 8.0 - (gap as f64) * 0.25;
        // extra reward if next item exactly closes the bin
        if gap == 0 {
            score -= 12.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit here: mild penalty proportional to overflow class
        let overflow = (next_item_size - post_residual) / 10;
        score += overflow as f64 * 0.8;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral-ish base, but prefer new bin
    // when open bins are crowded and mean residual is small.
    if bin_residual == bin_capacity {
        score = 25.0 + (mean_residual as f64) * 0.5;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0; // fresh bin still fits the future
        }
        if fitting_bins_count == 1 {
            score += 20.0; // don't open a new bin when this is the last chance
        }
    }

    // Progress: tighten packing later in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.15;

    // Slight preference for bins below mean residual (keeps spread tight)
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= 8.0 * (1.0 - post_residual as f64 / item_size as f64);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: favor bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 0.5;

    // Last-chance bin: strongly prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 1.5 + (mean_residual / bin_capacity as f64) * 20.0;
        score += 35.0 - pressure.min(35.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-match lookahead: reward post_residual == next_item_size strongly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 30.0;
        } else if post_residual as i64 >= next_item_size as i64 {
            // Next item fits exactly-ish here: reward closeness.
            score -= 20.0 / (1.0 + diff);
        } else {
            // Next item won't fit in leftover: penalize dead space.
            score += diff * 0.5;
        }
    }

    // Penalize post_residual too small to ever be useful (below min item size 1..100 heuristic floor).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Compare residual against mean residual: prefer filling tighter-than-average bins.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strong reward to use it and avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Late in stream: consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    // Slight preference for fewer open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Reward tight fits (low post residual) more strongly as stream progresses.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * (0.5 + progress);

    // Penalize dead space: post residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual > 0 && post_residual < 25 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin, less so when
    // existing residuals are large (poor fits available) or item is big.
    if is_new_bin {
        let mean_r = mean_residual;
        let big_item = item_size as f64 / bin_capacity as f64;
        let mut penalty = 20.0;
        penalty -= 15.0 * (mean_r / bin_capacity as f64); // crowded bins -> new bin ok
        penalty -= 10.0 * big_item;                        // big items justify new bins
        if next_item_size > 0 && (next_item_size as f64) > mean_r {
            penalty -= 5.0; // lookahead won't fit existing bins either
        }
        if open_bins_count == 0 {
            penalty = 0.0;
        }
        score += penalty.max(0.0);
    }

    // Lookahead synergy: if next item fits exactly into post_residual, reward.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 20.0;
        } else if next_item_size as f64 <= post_residual as f64 {
            score -= 6.0;
        }
    }

    // Mild preference for filling bins with larger residual when many bins open.
    score -= 0.02 * (bin_residual as f64 - mean_residual);

    // Encourage consolidation late in the stream (avoid leaving many open bins).
    score += 0.5 * open_bins_count as f64 * (1.0 - progress) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.5 * progress) - 2.0 * (x * (1.0 - x)) * cap * (1.0 - progress);

    // Reward tight fits more strongly as the stream progresses
    score -= (1.0 - x) * (1.0 - x) * cap * (0.5 + 0.5 * progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nx = (post_residual as f64 - next_item_size as f64).max(0.0) / cap;
        score += nx * cap * (0.3 + 0.4 * progress);
        if post_residual < next_item_size {
            score += next_item_size as f64 * 0.2;
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 5.0 + 10.0 * progress;
    }

    // Mild penalty for scattering across many open bins relative to mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual - pr).abs() / cap;

    // New-bin candidate: keep it attractive only when existing residuals are poor
    if bin_residual == bin_capacity {
        score += 3.0 * (1.0 - progress) + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that form "usable" pairings
    // (e.g., multiples of 10 and small remainders) are less penalized.
    let pr = post_residual;
    let cap = bin_capacity as f64;
    let frac = pr as f64 / cap;

    // Penalize dead space quadratically, but reward "perfect" harmonic classes.
    score += 0.6 * frac * frac * cap;

    // Modulo classes: post_residual divisible by common size residues is reusable.
    let m = pr % 10;
    if m == 0 {
        score -= 8.0; // exact decade residual: highly reusable
    } else if m <= 5 {
        score -= 2.0;
    } else {
        score += 4.0; // awkward remainder 6..9
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0; // perfect chain
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            score += 6.0; // next item cannot chain here
        }
    }

    // Last-chance bonus: only bin that fits -> strong incentive to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bins attractive only when
    // item is large or open bins are very full.
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64) / cap;
        score = cap as f64 * 0.35 - 12.0 * pressure
            - 2.0 * (open_bins_count as f64).ln().max(0.0)
            - (step_index as f64 / (total_items as f64).max(1.0)) * 5.0;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score += 10.0; // prefer filling open bins when a pair exists
        }
    }

    // Mild preference to fill fuller bins (smaller residual already favored).
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (1..=15) are nearly unusable
    // for future items (sizes >= 1, typically >= 10), so penalize them hard.
    if post_residual > 0 && post_residual <= 15 {
        score += 60.0 - 3.0 * post_residual as f64;
    }
    // Medium gaps (16..=25) are moderately risky.
    if post_residual > 15 && post_residual <= 25 {
        score += 15.0 - 0.5 * post_residual as f64;
    }

    // Reward tight fits: small positive post_residual is only good if it is
    // large enough to be reusable; near-zero leftovers are wasted capacity.
    if post_residual == 0 {
        score -= 25.0; // perfect fit is ideal
    }

    // Dead-space avoidance relative to the next item: if the leftover cannot
    // hold the lookahead item, the gap is likely to be wasted.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + 0.15 * (next_item_size - post_residual) as f64;
    }
    // If leftover can hold the lookahead item, reward the bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.1 * (post_residual as f64);
    }

    // Open-bin pressure: penalize using bins when many are open, to encourage
    // consolidation; but a new empty bin should have a mild baseline cost so
    // it is only chosen when fits are poor.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost that grows with open bins count,
        // making opening new bins less attractive when consolidation is possible.
        score = 100.0 + 2.0 * open_bins_count as f64;
        // Still allow opening a new bin late in the stream if pressure is low.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
        // If the next item is large and current bin residual is small elsewhere,
        // opening a fresh bin is less painful.
        if next_item_size >= 70 {
            score -= 15.0;
        }
    } else {
        // Using an existing bin reduces pressure slightly as bins accumulate.
        score -= (open_bins_count as f64).min(10.0) * 0.5;
    }

    // Slight preference for bins whose residual deviates favorably from mean:
    // prefer filling below-average-residual bins (tighter bins first).
    if bin_residual != bin_capacity {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly (or nearly) matches the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain match: big reward.
        if post_residual == next_item_size {
            score -= 40.0;
        } else if (post_residual as u32) >= next_item_size {
            // Next item still fits after this placement: mild reward scaled by tightness.
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item would NOT fit: penalize wasted potential, worse when gap small.
            score += 8.0 * (1.0 - (next_item_size as f64 - post_residual as f64) / bin_capacity as f64);
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Penalize very small dead space that nothing (min size 1..) can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }
    // Perfect closure bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it attractive only when current fit is poor
    // (large post_residual means bad fit in an open bin).
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64;
        if next_item_size > 0 && item_size < next_item_size {
            score -= 5.0; // fresh bin can chain next item too
        }
        if fitting_bins_count <= 1 {
            score -= 25.0; // no good alternative: opening fresh bin is fine
        }
    }

    // Late-stream consolidation: prefer reusing existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more strongly than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            // Post-residual becomes dead space relative to the next item.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 8.0 * fill_ratio * (open_bins_count as f64).ln().max(1.0);

    // Global residual balance: penalize bins far below mean residual
    // (they waste the average usable space), mildly.
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    // Time horizon: early in the stream, be more willing to open new bins
    // (cheap now, flexible later); late in the stream, consolidate hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: cheap early, expensive late.
        score += 20.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0 * (1.0 - progress); // fresh bin pairs well with big next item early
        }
    } else {
        score -= 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / bin_capacity as f64;
    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) - norm_pr * progress * progress;
    score += 40.0 * poly;
    // Penalize unusable dead space more as stream progresses
    let dead_threshold = 0.5 * (1.0 - progress) + 0.2;
    if norm_pr < dead_threshold {
        score += 12.0 * (dead_threshold - norm_pr) * (1.0 + progress);
    }
    // Reward tight fits smoothly (quadratic in item size fraction)
    let fit_frac = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fit_frac * fit_frac;
    // Lookahead: reward leaving space for the next item (smooth coupling)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0) / bin_capacity as f64;
        score -= 10.0 * gap * (1.0 - gap);
    }
    // Last-chance bonus when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - progress);
    }
    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * progress;
    // Mean residual coupling: prefer bins deviating favorably from mean
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= 5.0 * dev * (1.0 - progress);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "usable" slots
    // (large enough to host typical small items), penalize dead zones.
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else if post_residual < 10 {
        score += 25.0; // dead space: too small for anything (min item size 10)
    } else {
        // classify residual by divisibility into harmonic slots
        let mut div_bonus = 0.0;
        for &d in &[10u32, 20, 25, 50] {
            if post_residual % d == 0 {
                div_bonus += 6.0;
            }
        }
        score -= div_bonus;
        // small usable residual is good
        score -= (post_residual as f64 / bin_capacity as f64) * 10.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 + slack * 0.3;
        // exact harmonic match
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here anyway; slight penalty for wasting capacity
        score += 5.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Prefer tighter bins: penalize bins with residual far above item size
    let waste = (bin_residual - item_size) as f64;
    score += waste * waste / (bin_capacity as f64 * 4.0);

    // New-bin candidate: only attractive when existing bins fit poorly
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count == 0 { 0.0 } else {
            (mean_residual - item_size as f64).abs()
        };
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin can host the next item too
        }
        score += 12.0 - poor_fit * 0.5; // baseline cost of a new bin
        if open_bins_count == 0 {
            score -= 50.0; // must open
        }
    }

    // Stream progression: early on, be more willing to open bins / spread load
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 4.0 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
