pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post residual,
    // reward heavily (chain of perfect fits).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: mild reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space for the next item: penalize small unusable leftovers.
            score += 40.0;
        }
    }

    // Penalize leaving tiny unusable gaps (below min item size 1..=100 range,
    // anything very small is likely dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 0.5 * (mean_residual - residual_f);
    } else {
        score += 0.3 * (residual_f - mean_residual);
    }

    // Late in the stream, be more conservative: avoid opening new bins,
    // favor filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when
        // open bins exist that could still absorb future items.
        score += 30.0 + 120.0 * progress + 5.0 * open_bins_count as f64;
    } else {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: waste ratio penalty
    let tight = item_size as f64 / bin_residual.max(1) as f64;
    score -= tight * 30.0;

    // Penalize leaving dead space that can't hold typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: only one bin fits, prefer it strongly
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item won't fit here; slight penalty for fragmenting
            score += (post_residual as f64) * 0.15;
        }
    }

    // Prefer fuller bins over spread: compare residual to mean residual
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Prefer bins with low residual (fill nearly-full bins first)
    score += bin_residual as f64 * 0.3;

    // Time horizon: early on, allow more exploration of new bins
    let progress = step_index as f64 / total_items.max(1) as f64;

    // New-bin candidate logic: opening a new bin is attractive when item is
    // large and current bins would be fragmented, or when many bins open
    if bin_residual == bin_capacity {
        let waste_if_open = (bin_capacity - item_size) as f64;
        let mut new_bin_score = waste_if_open * 0.6;
        // Late in stream: opening new bins is fine (there's time to fill them)
        new_bin_score -= progress * 20.0;
        // If this bin is the only fitting option among open bins, discourage new bin
        if fitting_bins_count == 0 {
            new_bin_score -= 30.0;
        }
        // Large items pack better in fresh bins early
        if item_size > bin_capacity / 2 {
            new_bin_score -= 15.0;
        }
        score = score.min(new_bin_score);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: post residual, mildly convex in normalized fill
    let mut score = pr * (1.0 + 0.35 * fit_norm * fit_norm);

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, penalize residual more strongly (compact now)
    let prog_coupling = 1.0 + 0.9 * progress * (1.0 - progress * 0.5);
    score *= prog_coupling;

    // Dead-space penalty: residual too small to ever fit another item
    let dead = (10.0 - pr).max(0.0) / 10.0;
    score += dead * 25.0;

    // Last-chance bonus: only this bin fits -> reward strongly
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        // scarcity: fewer fitting bins -> slight reward
        score -= 4.0 / fitting_bins_count as f64;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 20.0 * (1.0 - slack * slack);
    } else if next_item_size > 0 && (next_item_size as f64) > pr {
        // next item won't fit here; penalize wasting this bin's space
        score += 8.0 * ((next_item_size as f64) - pr) / cap;
    }

    // Relative fill reward: prefer bins where item fills most of residual
    score -= 15.0 * (item_size as f64 / bin_residual.max(1) as f64);

    // Prefer using bins whose residual is close to item size (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64) / cap;
    score += 10.0 * tightness * tightness;

    // Mild penalty for spreading across many open bins early
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    // Prefer bins near mean residual (balance residuals smoothly)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small dead space classes are usable by small items
    let cls = post_residual / 10; // 0..10 harmonic classes
    match cls {
        0 => score -= 60.0,               // residual <= 9: nearly perfect
        1 => score -= 25.0,               // 10..19: fits small items
        2 => score -= 10.0,               // 20..29
        3 => score -= 4.0,
        4 | 5 => score -= 0.0,
        6 | 7 => score += 8.0,            // large dead space penalty
        _ => score += 18.0,
    }

    // Reward leaving a residual that exactly accommodates the next item (lookahead chaining)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // dead space relative to lookahead
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate: only attractive when it enables a tight future pairing
    if bin_residual == bin_capacity {
        // penalize opening new bins generally
        score += 40.0;
        if next_item_size > 0 && next_item_size >= 70 {
            score -= 50.0; // big lookahead item justifies a fresh bin
        }
        if post_residual == 0 {
            score -= 500.0; // exact full utilization
        }
        // open fewer bins when existing bins are already roomy
        if mean_residual > item_size as f64 * 1.5 {
            score += 30.0;
        }
    }

    // Prefer filling bins that are already relatively empty (consolidate)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (bin_residual as f64 - mean_residual) * 0.15;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: any leftover gap below the minimum item size
    // is unusable dead space -> heavy penalty proportional to its size.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Moderately small leftovers are risky too (future items 1..100 unknown).
    if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 150.0;
    }
