    // last fitting one (forces future new bin anyway).
    if next_item_size > post_residual && fitting_bins_count == 1 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor
    // filling existing bins, mildly favor consolidation via low residual.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (2.0 + 6.0 * progress);

    // Deviation from mean residual: prefer bins tighter than average.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // New empty bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 120.0
            + (open_bins_count as f64) * 3.0
            - (item_size as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
