    // Late in the stream, small residuals are more acceptable (less future demand);
    // early on, keep bins roomy.
    let roominess = 0.5 + 0.5 * (1.0 - progress);
    score -= roominess * (pr as f64).ln().max(0.0) * 8.0;

    // Interaction: post_residual vs next item size — reward residual close to next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = ((pr - nxt) / cap).abs();
        score += gap * gap * 30.0 * (1.0 - progress * 0.5);
        // Perfect lookahead fit bonus.
        if (pr - nxt).abs() <= 1.0 {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening new bins.
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * progress;
    }

    // Many open bins: penalize spreading into high-residual bins lightly.
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 3.0;

    // Mean residual coupling: bins deviating far below mean residual are "tight" —
    // reward filling them further (smooth sigmoid-ish term).
    let dev = (mean_residual - bin_residual as f64) / cap;
    score += dev * dev * 10.0 - dev * 5.0;

    // Penalize large dead space smoothly via cubic term.
    score += norm_pr * norm_pr * norm_pr * cap * 0.5;

    // New-bin candidate: keep it competitive only when item fits poorly everywhere.
    if bin_residual == bin_capacity {
        score += 6.0 - 8.0 * progress + 0.15 * (item_size as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls on "useful" residue classes
    // (multiples of 10, or small enough to be plausibly filled) are favored.
    let pr = post_residual;
    let residue_class = (pr % 10) as f64;
    if pr > 0 {
        // penalize awkward leftovers: residue 1..9 off a multiple of 10 is dead-ish space
        score += residue_class * 0.6;
        // class of pr via integer division thresholds
        if pr <= 10 {
            score -= 12.0; // near-perfect closure
        } else if pr <= 20 {
            score -= 6.0;
        } else if pr <= 50 {
            score -= 2.0;
        } else {
            score += (pr as f64 - 50.0) * 0.15; // large leftover = wasted capacity
        }
    } else {
        score -= 25.0; // exact fill is ideal
    }

    // Coupling with lookahead: if the next item fits the post residual, big reward.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (ni - pr as f64).abs() <= 2.0 {
            score -= 15.0; // next item closes this bin exactly
        } else if ni <= pr as f64 {
            score -= (pr as f64 - ni).min(20.0) * 0.4; // next item fits, leftover shrinks
        } else {
            score += 4.0; // next item won't fit here
        }
        // harmonic class match: next item same decade class as post residual
        if next_item_size % 10 == pr % 10 && next_item_size <= pr {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new one.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // many bins fit: mild penalty for hoarding this particular one
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // New-bin candidate logic: opening a bin is only good when no open bin gives a tight fit.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = cap * 0.75;
        // if the current item leaves a big hole, opening is fine (score stays moderate)
        if post_residual as f64 <= cap * 0.25 {
            score -= 10.0; // item nearly fills a fresh bin: good
        }
        // late in the stream, avoid proliferation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
        // if many open bins and mean residual is large, prefer reusing
        score += (open_bins_count as f64).sqrt() * 2.0 + (mean_residual / cap) * 15.0;
        // last-chance override: if only one open bin fits, never open
        if fitting_bins_count == 1 {
            score += 40.0;
        }
    } else {
        // prefer fuller bins (best-fit bias beyond raw post_residual)
        score -= (bin_residual as f64 / cap) * 5.0;
        // slight bonus for bins tighter than the mean residual (above-average fullness)
        if (bin_residual as f64) < mean_residual {
            score -= 2.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..100 range)
    // are wasted space; penalize them heavily.
    if post_residual < 1 {
        score += 1000.0;
    } else if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score -= 25.0 * (1.0 - tightness.min(1.0));

    // Prefer using bins that are already open: pressure grows with open bin count.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is fine early, or when no open bin fits well,
        // or when this item would leave a dead gap elsewhere.
        let pressure = open_bins_count as f64 * 4.0;
        score += pressure;
        if post_residual >= 10 {
            score -= 15.0; // a fresh bin keeps usable space
        }
    } else {
        score -= 20.0; // reuse existing bins
        // Last-chance bin: strongly prefer it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // Lookahead: if next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as i64) >= (next_item_size as i64) {
        score -= 18.0;
    }
    // If next item would exactly fill the post residual, extra reward (perfect pair).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 22.0;
    }

    // Mild global pressure: as stream progresses, discourage wasteful small gaps.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual < 10 {
        score += 40.0 * progress;
    }

    // Deviation from mean residual: prefer bins with below-average residual
    // (fill the emptiest-feeling bins first keeps many bins usable).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: zero post residual is ideal.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + diff);
        if post_residual == next_item_size {
            score -= 300.0; // chain: next item exactly fills this bin
        }
        // Penalize leaving dead space the next item cannot use.
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average residual.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize mildly, but allow it when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 25.0; // fresh bin can chain large items
        }
    }

    // Late-stream tightening: waste matters more as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * post_residual as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 24.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // unusable sliver
    }

    // Last-chance bonus: only this bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item won't fit here; mildly penalize hogging space it could have used elsewhere
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.08 * overflow;
        }
    } else {
        // Last item in stream: just minimize waste.
        score += 0.0;
    }

    // Global state: many open bins with high mean residual -> prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = mean_residual / (bin_capacity as f64);
    score -= 6.0 * consolidation * (open_bins_count as f64).sqrt();

    // New-bin candidate handling: empty bin should only win when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress; // later in stream, more reluctant to open bins
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open
        }
    }

    // Slight preference for filling bins that are already partially used when few bins open.
    if open_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    let mut score = pr as f64;

    // Smooth non-linear coupling: quadratic + cubic shaping of wasted space
    let waste = x * x * (1.0 - x);
    score += 40.0 * waste * (0.5 + progress);

    // Penalize post-residuals that are small but nonzero (dead space)
    let dead = (1.0 - x) * (1.0 - x);
    score += 15.0 * dead * (1.0 - progress);

    // Reward tight fits (small post residual)
    score -= 12.0 * (-pr / 8.0).exp();

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: favor bins whose post residual fits the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 6.0 * (1.0 - (next_item_size as f64 / cap));
    }

    // New-bin candidate handling: prefer existing bins unless new bin gives clean fit
    if bin_residual == bin_capacity {
        score += 8.0 - 10.0 * progress;
    }

    // Mild preference for filling bins with lower residual than average
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Crowd penalty: many open bins -> prefer consolidating
    score += 0.5 * open_bins_count as f64 * (1.0 - progress) * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: post_residual bucketed by integer division thresholds
    let class = post_residual / 10; // 0..=10 classes
    // Reward small post_residual (tight fit), strongest for class 0-1
    score -= match class {
        0 => 30.0,
        1 => 20.0,
        2 => 12.0,
        3 => 6.0,
        _ => 0.0,
    };

    // Modulo arithmetic: perfect fits when residual is divisible by common item sizes
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual % 10 == 0 {
        score -= 8.0; // residual usable by typical rounded sizes
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: penalize if next item cannot use post_residual
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 10.0 + (next_item_size - post_residual) as f64 * 0.2;
        } else {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        }
    }

    // Last-chance bonus: only fitting bin -> strong reward to avoid new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly unless current bins are nearly full / crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 - open_bins_count as f64 * 2.0 - mean_residual * 0.1 - progress * 5.0;
    }

    // Prefer using bins with lower residual relative to mean (fill emptier bins less)
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    let dead_zone = 12.0;
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 8.0; // tiny gaps penalized hard
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to bin residual
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 10.0;

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 3.0 + progress * 15.0;
    }

    // Lookahead: if next item fits in this bin's post residual, reward placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    }
    // If next item would be stranded by a small gap, penalize
    if next_item_size > post_residual && post_residual > 0 && post_residual < 12 {
        score += 10.0;
    }

    // Mild preference for bins with residuals below mean (consolidate large gaps)
    score += (post_residual as f64 - mean_residual).max(-20.0).min(20.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space relative to the smallest plausible item (1..100 unknown dist).
    let dead = post_residual as f64;
    score += 0.35 * dead * dead / bin_capacity as f64;

    // 2-step lookahead: strongly reward exact or near match of next item into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-chain
        } else if next_item_size <= post_residual {
            // reward proportional to how tightly the next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow: penalize more as wasted chain opportunity grows
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.5 * overflow;
        }
    } else {
        // last item: just prefer tightest fit
        score += 0.0;
    }

    // Relative to mean residual: prefer filling below-average-residual bins (tightly packed).
    let mr = mean_residual.max(0.0);
    if (bin_residual as f64) < mr {
        score -= 6.0;
    } else {
        score += 0.05 * ((bin_residual as f64) - mr);
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge or
    // current bin would leave a very large awkward gap.
    if bin_residual == bin_capacity && bin_capacity > 0 {
        let waste = (bin_residual - item_size) as f64;
        // Opening is attractive only if the leftover gap is unusably large
        // (bigger than ~ half capacity) or next item is tiny relative to gap.
        let gap_penalty = if waste > bin_capacity as f64 * 0.5 { -25.0 } else { 15.0 };
        score += gap_penalty;
        score += 0.1 * open_bins_count as f64; // mild preference to reuse open bins
    }

    // Slight stream-phase adaptation: early on, be conservative (keep bins flexible);
    // later, pack aggressively.
    let phase = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * phase * (1.0 - dead / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) nonlinearly.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Penalize dead space that no future item (>=1) can ever use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: bonus if the next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / 100.0);
        } else {
            score += 8.0;
        }
    } else {
        // Last item: prefer filling bins as completely as possible.
        score += 30.0 * (post_residual as f64) / (bin_capacity as f64);
    }

    // Last-chance bin: strong penalty for rejecting it (would open a new bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: discourage opening a new bin unless current
    // residuals are globally poor or the item is huge.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        let global_health = mean_residual / (bin_capacity as f64);
        let pressure = (open_bins_count as f64).ln() + 1.0;
        let big_item = item_size as f64 / (bin_capacity as f64);
        score += 55.0
            + 40.0 * global_health
            - 45.0 * big_item * (0.5 + 0.5 * progress)
            - 6.0 * pressure;
    } else {
        // Mild bonus for using existing bins as stream matures.
        score -= 5.0 * progress;
    }

    // Prefer bins with residual far from mean (keeps diversity of gaps).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Small tie-breaker favoring fuller bins.
    score += 0.02 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Reward tight fits with smooth non-linear coupling
    score -= (fit_ratio * fit_ratio) * cap * (0.5 + 0.5 * progress);

    // Penalize dead space non-linearly, stronger late in stream
    score += norm_pr * norm_pr * cap * (0.3 + 0.7 * progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0 + 18.0 * progress;
    }

    // Reward bins below mean residual (consolidate emptier bins)
    score -= 0.4 * (mean_residual - pr) * (0.5 + 0.5 * progress);

    // Lookahead: favor residual that can host next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (1.0 - ((pr - nx) / cap).abs()) * (0.4 + 0.6 * (1.0 - progress));
        } else {
            score += 6.0 * (nx - pr) / cap * (1.0 - progress);
        }
    }

    // New-bin candidate: prefer opening new bins early, penalize later
    if bin_residual == bin_capacity {
        score += 5.0 + 25.0 * progress * progress;
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Best-fit core: reward tight fits, penalize dead space.
    let tightness = 1.0 - (post_residual as f64) / cap_f;
    score -= 30.0 * tightness;

    // Harmonic class of the post residual: quarter classes.
    // Residuals in [0,25) are nearly dead space -> penalize harder.
    let quarter = (post_residual / 25).min(3);
    match quarter {
        0 => score += 18.0,                       // tiny leftover, wasted bin
        1 => score -= 6.0,                        // 25..50 still usable for small items
        2 => score -= 10.0,                       // 50..75 half-open, valuable
        _ => score -= 14.0,                       // large residual, flexible
    }

    // Modulo-10 class coupling: if leftover exactly matches next item size or
    // shares its decade, this bin chains perfectly with the lookahead item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect lookahead fill
        } else if post_residual > next_item_size {
            let gap = post_residual - next_item_size;
            // harmonic penalty on the chained leftover, mod 10 classes
            let m = gap % 10;
            score -= 12.0 - (m as f64) * 0.8;
        } else {
            // next item cannot follow into this bin's leftover: mild penalty,
            // stronger when the bin is nearly full anyway (harmless)
            let frac = (post_residual as f64) / cap_f;
            score += 8.0 * (1.0 - frac);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate handling: brand-new empty bin should only win when
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, modulated by stream progress and load.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 + 20.0 * progress;
        // If many open bins already, slightly prefer consolidation into them.
        score += (open_bins_count as f64).min(20.0) * 0.5;
        // If mean residual is large, opening new bins is wasteful.
        score += mean_residual.max(0.0) * 0.3;
    } else {
        // Reward using existing bins proportionally to how loaded they are.
        let load = 1.0 - (bin_residual as f64) / cap_f;
        score -= 10.0 * load;
        // Slight bonus for keeping open bin count from exploding.
        score -= (open_bins_count as f64).min(15.0) * 0.3;
    }

    // Integer-division threshold on post_residual: exact decade slots.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0; // clean decade leftover is reusable
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward bins whose residual tightly matches the item (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 30.0 * tightness;

    // Last chance: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover gap -> penalize.
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += 0.8 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins with residuals near the mean (balanced usage).
    score += 0.5 * ((bin_residual as f64 - mean_residual).abs());

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 20.0 + 1.5 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_quality = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - match_quality / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item won't fit here: penalize wasted space
        score += 8.0;
    }

    // Tight fits are valuable: reward small post_residual
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 6.0 * tightness * tightness;

    // Compare against mean residual: prefer filling below-average-residual bins
    score -= 0.5 * (mean_residual - bin_residual as f64).max(0.0);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Penalize opening a new bin when a decent fit exists
    if bin_residual == bin_capacity {
        score += 20.0 + (1.0 - item_size as f64 / bin_capacity as f64) * 10.0;
    }

    // Dead-space penalty: post_residual too small for any realistic item
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Late in stream, be greedier about tight packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * tightness * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chain: post residual exactly matches next item.
            let tightness = (post_residual as f64 - next_item_size as f64).abs();
            score -= 30.0 + 20.0 * (1.0 - tightness / bin_capacity as f64);
        } else {
            // Next item cannot use leftover space: penalize proportionally.
            let waste = (post_residual as f64 - next_item_size as f64).min(post_residual as f64);
            score += 0.5 * waste;
        }
    } else {
        // Last item: prefer tightest fit only.
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible (huge dead space).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        if fit_ratio > 0.5 {
            score -= 25.0 + 25.0 * fit_ratio;
        } else {
            score -= 5.0;
        }
    }

    // Prefer bins with small residual relative to the mean (dense bins first),
    // but keep some diversity when many bins are open.
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.3 * residual_gap;

    // Time-horizon modulation: early in the stream, be more willing to open new bins
    // (keep flexibility); late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let consolidation = 15.0 * progress;
    score -= consolidation;

    // Penalize leaving very small unusable slivers (dead space) unless it's the end.
    if post_residual > 0 && post_residual < 10 && next_item_size > 0 {
        score += 12.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Mild preference for reusing bins over opening new ones as bins accumulate.
    if bin_residual == bin_capacity {
        // Candidate new bin: base cost grows with number of open bins and progress.
        score += 8.0 + 0.5 * open_bins_count as f64 + 20.0 * progress;
        // But if the current item is large and no open bin fits well, new bin is fine.
        if item_size as f64 / bin_capacity as f64 > 0.8 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Tight fits are strongly rewarded, especially late in the stream.
    let tight = 1.0 - pr / cap;
    score -= 18.0 * tight.powi(3) * (1.0 + 2.0 * progress);

    // Penalize residuals that are too small to be useful later (dead space),
    // with a smooth valley around residuals that can fit mid-size items.
    let dead = (pr / cap - 0.25).powi(2);
    score += 14.0 * dead * (1.0 - 0.5 * progress);

    // If this is the last fitting bin, encourage using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Lookahead: reward residual that can host the next item.
    if next_item_size > 0 {
        if (pr as u32) >= next_item_size {
            score -= 6.0 * (1.0 + progress);
        } else {
            score += 4.0 * (1.0 - progress);
        }
    }

    // Mild preference for balancing residuals against the mean when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * 0.05 * (pr - mean_residual);

    // Slight bias toward reusing open bins over opening new ones.
    if bin_residual == bin_capacity {
        score += 3.0 + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band does it fall in?
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 10.0).floor() as i64; // 0..=9 decile of residual space

    // Reward placements landing in "harmonic" residual classes that pair well
    // with common item sizes (multiples of 10 and their halves).
    let harmonic_bonus: f64 = match class {
        0 => 40.0,           // near-perfect fit, best possible
        1 => 25.0,           // leaves room for small items (10..=20)
        2 => 10.0,           // decent
        3 | 7 => -8.0,       // awkward dead zones (31..40, 71..80)
        4 => 5.0,            // pairs with ~40 items
        5 => 12.0,           // half-full, very reusable
        6 => -4.0,           // mediocre
        8 => 2.0,
        _ => 0.0,
    };
    score -= harmonic_bonus;

    // Integer-division threshold on post_residual: does a size-class item fit?
    // Class sizes: 1..=100 items; check if next item exactly fits a division band.
    if next_item_size > 0 && next_item_size <= post_residual {
        // Lookahead fits: reward, more if the fit is tight (harmonic pairing).
        let tightness = (post_residual - next_item_size) as f64;
        score -= 30.0 - tightness * 0.4;
    } else if next_item_size > post_residual {
        // Next item won't fit here; penalize mildly so bins that chain are favored.
        score += 6.0;
    }

    // Modulo arithmetic: reward when post_residual shares residue class with
    // typical item granularity (mod 10 == 0 means clean splits).
    let mod_res = post_residual % 10;
    if mod_res == 0 {
        score -= 8.0;
    } else if mod_res >= 5 {
        score += mod_res as f64 * 0.3;
    } else {
        score += mod_res as f64 * 0.6;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // current placement would leave a large, unusable residual.
    if bin_residual == bin_capacity {
        // Cost of a fresh bin; acceptable only if existing bins would waste space.
        let waste_if_placed = post_residual as f64;
        let open_pressure = (open_bins_count as f64).max(1.0);
        score = 55.0 + waste_if_placed * 0.5 - open_pressure * 2.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A new bin guarantees room for the next item too.
            score -= 10.0;
        }
    }

    // Mean residual coupling: if this bin's residual deviates favorably from
    // the mean (smaller residual = tighter packing), reward it.
    let dev = mean_residual - post_residual as f64;
    score -= dev * 0.25;

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Slight penalty for proliferating bins.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever hold
    // another item (min size 1, but practically < ~15) are toxic. Apply a
    // steep superlinear penalty in the "dead zone".
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 15 {
        let dead = (15.0 - pr) / 15.0; // 0..1, closer to 1 for tinier gaps
        score += 60.0 * dead * dead;
    }
    // Perfect or near-perfect fills get a strong reward.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Tightness reward: fraction of the bin consumed by this placement.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 15.0 * tightness;

    // Prefer bins whose residual is close to the item (snug fit).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * gap;

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward heavily; if it nearly fits, mild penalty for blocking it.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as f64 - nx).abs() < 1.0 {
            score -= 30.0;
        } else if nx > pr {
            let overflow = (nx - pr) / 100.0;
            score += 10.0 * overflow;
        }
    }

    // Open-bin pressure: keep the fleet of open bins compact so items have
    // more placement options; discourage spreading across many bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).powf(1.2) * (1.0 + 0.5 * progress) * 0.5;

    // If this bin is the last chance before opening a new bin, favor using it
    // (avoid bin proliferation) unless the dead-space penalty already dominates.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): mildly discourage
    // opening a new bin when open bins can fit the item, scaled by how many
    // alternatives exist and how wasteful the placement would be.
    if bin_residual == bin_capacity {
        let alt = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        score += 8.0 + 3.0 * alt;
        // But if this item is huge relative to mean residual across open bins,
        // a fresh bin may be the cleanest home: relax the penalty.
        if item_size as f64 > mean_residual {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Fractional waste relative to capacity: small post_residual => big reward.
        let tightness = (post_residual as f64) / (bin_capacity as f64);
        score -= 60.0 * (1.0 - tightness) * (1.0 - tightness);

        // Aggressive 2-step lookahead: reward bins whose residual after placement
        // matches the next item size (chained packing).
        if next_item_size > 0 {
            let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
            if gap == 0.0 {
                score -= 120.0; // next item exactly fills this bin afterwards
            } else {
                score -= 40.0 * (-gap / 20.0).exp();
            }
            // Penalize if next item cannot fit into post_residual but almost could
            // (dead space trap), unless the gap is large enough to stay useful.
            if (post_residual as u32) < next_item_size && (next_item_size - post_residual) <= 15 {
                score += 25.0;
            }
        }
    }

    // Relative-to-mean coupling: bins with residual below mean are precious; prefer
    // filling those (drives toward compact bins).
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 10.0 * (mean_residual - resid_f) / bin_capacity as f64;
    } else {
        score += 5.0 * (resid_f - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate handling: make an empty bin attractive only when the item
    // is large relative to capacity (poor fit likely elsewhere) or late in stream
    // with many open bins (spread load).
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64) / (bin_capacity as f64);
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let pressure = (open_bins_count as f64) / (open_bins_count as f64 + 4.0);
        let incentive = 90.0 * large_item * (0.4 + 0.6 * pressure) + 30.0 * progress * pressure;
        score -= incentive;
        // But never open a new bin if a perfect chain exists elsewhere: keep base
        // score high enough via post_residual == capacity (large raw score).
    }

    // Mild penalty for opening new bins early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strongly reward near-perfect fits (small post_residual).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 60.0 * (-post_residual as f64 / 8.0).exp();
    }

    // Lookahead: if next item can chain into this bin's post_residual, reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let chain_waste = post_residual - next_item_size;
            score -= 25.0 - 0.4 * chain_waste as f64;
        } else {
            // Dead space the next item cannot use: penalize proportionally.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin should win only when fits elsewhere are bad.
    if bin_residual == bin_capacity {
        // Base penalty so that any decent fit beats opening a new bin.
        score += 30.0;
        // Early in stream: be generous opening bins (builds a diverse residual pool).
        score -= 25.0 * (1.0 - t) * (1.0 - t);
        // Many open bins with slack: opening new bins is cheap.
        score -= (open_bins_count as f64).ln().max(0.0) * 5.0;
        // Large mean residual across open bins: prefer using existing space.
        score += 0.10 * mean_residual;
        // If the item is large, a fresh bin is attractive.
        score -= 0.05 * item_size as f64;
    } else {
        // Prefer bins whose residual is close to the item (tight packing).
        score += 0.05 * (bin_residual - item_size) as f64;
        // Slight preference for bins below mean residual (balance load).
        score += 0.03 * (bin_residual as f64 - mean_residual);
    }

    // Late in stream: tighten packing, avoid opening new bins.
    score += 10.0 * t * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let coupling = pr_norm * pr_norm * (0.5 + progress) - pr_norm * (1.0 - progress) * 0.5;
    score += 20.0 * coupling;

    // Penalize tight fits less as stream progresses (pack tightly later).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness * tightness * (0.5 + progress);

    // Reward using the last fitting bin (avoid opening a new bin).
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 {
        score += 3.0;
    }

    // Discourage spreading across too many open bins with large mean residual.
    score += 0.3 * open_bins_count as f64 * (mean_residual / bin_capacity as f64 - pr_norm).abs();

    // New-bin candidate: mildly penalize opening a new bin early, less later.
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit core: reward tight fits strongly.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += tight * 20.0;

    // Harmonic class of the residual: residuals that are "useful" multiples
    // for common item sizes should be penalized less.
    let pr = post_residual;
    // Class 1: residual divisible into halves/quarters of capacity (harmonic slots)
    let harmonic = (pr % 25 == 0) as i32 + (pr % 20 == 0) as i32 + (pr % 50 == 0) as i32;
    score -= harmonic as f64 * 6.0;

    // Dead-space penalty: residual below smallest plausible item (harmonic floor)
    if pr > 0 && pr < 10 {
        score += 40.0;
    }
    // Integer-division threshold: residual that can't hold 2 small items is fragile
    if pr >= 10 && pr / 10 < 2 {
        score += 12.0;
    }

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits: big reward, scaled by how snugly
            score -= 10.0 + 8.0 * (next_item_size as f64 / pr.max(1) as f64);
            // harmonic bonus: next item leaves a harmonic residual again
            if (pr - next_item_size) % 25 == 0 || (pr - next_item_size) % 20 == 0 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here: mild penalty unless this bin becomes near-full
            if pr >= 10 {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): accept only if no open bin fits well,
    // i.e. penalize the fresh bin by current fragmentation pressure.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 30.0 + 5.0 * open_bins_count as f64 };
        score += pressure;
        // early in the stream, opening bins is cheap; later it is not
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // if next item is large, a fresh bin is more attractive
        if next_item_size > 60 {
            score -= 8.0;
        }
    }

    // Mean-residual balancing: prefer bins whose residual deviates from the mean
    // in a way that reduces variance (place into fuller bins).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, strong reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual >= 1 && post_residual <= 10 {
        score += 40.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Moderate gaps (11..=20) mildly penalized — hard for future items (>=10) to reuse well.
    if post_residual >= 11 && post_residual <= 20 {
        score += 6.0;
    }

    // Reward tight fits relative to item size.
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack.min(25.0);
    }
    // If next item cannot fit this residual, slight penalty (dead end for lookahead).
    if next_item_size > post_residual && next_item_size > 0 {
        score += 4.0;
    }

    // Open-bin pressure: discourage spreading across many bins when mean residual is low.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if existing bins would leave bad gaps
        // or there are no fitting bins. Otherwise penalize opening new bins.
        if fitting_bins_count > 0 && post_residual >= 0 {
            let pressure = open_bins_count as f64 * 2.0 + mean_residual * 0.5;
            score += 30.0 + pressure;
        } else {
            score -= 10.0;
        }
    } else {
        // Using an existing bin reduces open-bin growth: reward, scaled by pressure.
        score -= 3.0 + open_bins_count as f64 * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it over new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Late in the stream, tighten placements to avoid leftover fragmentation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight fits rewarded
    if post == 0 {
        score -= 30.0;
    } else if post <= 5 {
        score -= 15.0;
    } else if post <= 10 {
        score -= 8.0;
    }

    // 2-step lookahead: reward when next item exactly matches post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        if nxt <= post {
            score -= 12.0 * (1.0 - diff / cap);
            if diff < 1.0 { score -= 10.0; }
        } else {
            // next item won't fit here; mild penalty proportional to overshoot
            score += 4.0 * (nxt - post) / cap;
        }
    }

    // Compare post_residual to mean residual across open bins
    score += 0.5 * (post - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless current bin fit is poor
    if bin_residual == bin_capacity {
        let waste_ratio = post / cap;
        score += 18.0 * (1.0 - waste_ratio);
        if fitting_bins_count > 0 {
            score += 5.0;
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * progress;
    }

    // Penalize many open bins lightly to encourage consolidation
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 14.0 * fit_ratio;

    // Penalize dead space that is too small for typical future items (below half of smallest plausible chunk).
    if post_residual > 0 && post_residual < bin_capacity / 10 {
        score += 12.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 0.05 * next_item_size as f64;
    }
    // Penalize leaving a residual that just barely fails the next item (wasted opportunity).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Time horizon: early in the stream, encourage spreading across bins (keep residuals balanced);
    // later, prefer consolidation into fewer bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let balance_term = (bin_residual as f64 - mean_residual).abs();
    score += (1.0 - progress) * 0.08 * balance_term;
    score -= progress * 0.05 * bin_residual as f64;

    // Congestion: when many bins are open, discourage opening extra capacity wastefully.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when few bins are open or item is small.
        let small_item_penalty = 0.4 * item_size as f64;
        score += 18.0 + open_bins_count as f64 * 1.5 - small_item_penalty;
        // But if no open bin fits well (fit_ratio low), opening a new bin is more acceptable.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Mild global pressure: many open bins with high mean residual -> favor tight packing.
    score += 0.02 * open_bins_count as f64 * (mean_residual - post_residual as f64).abs().min(50.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual
    let pr = post_residual as f64 / cap;
    let ir = item_size as f64 / cap;

    // Non-linear coupling: penalize large post-residuals more as stream progresses
    score += 8.0 * pr * pr * (0.5 + progress);

    // Reward tight fits (small post_residual relative to item)
    let tightness = (item_size as f64) / (bin_residual as f64 + 1.0);
    score -= 12.0 * tightness * tightness * (1.0 - progress);

    // Penalize dead space that no plausible future item (10..80) can use
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // perfect seal
    } else if post_residual > 80 {
        score += 3.0 * (post_residual as f64 - 80.0) / cap;
    }

    // Lookahead coupling: favor leaving room for the next item
    if next_item_size > 0 && (post_residual as u64) >= next_item_size as u64 {
        let fit_next = next_item_size as f64 / cap;
        score -= 6.0 * fit_next * (1.0 - pr);
    } else if next_item_size > 0 {
        score += 2.0 * (1.0 - pr);
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 5.0 * progress;
    }

    // New-bin candidate: penalize proportionally to how well existing bins could absorb the item,
    // and to how many bins are already open (bin proliferation cost grows sub-linearly).
    if bin_residual == bin_capacity {
        let proliferation = (open_bins_count as f64).ln() + 1.0;
        score += 6.0 + 2.0 * proliferation + 10.0 * ir * (1.0 - progress);
        // Small items justify new bins less
        score += 4.0 * (1.0 - ir);
    }

    // Mild mean-residual balancing: prefer bins deviating from mean (consolidation)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score -= 2.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: quantize dead space into octiles of capacity ---
    let octile = (post_residual * 8 / bin_capacity.max(1)) as f64; // 0..=8 class
    // Reward leaving residuals in "useful" harmonic classes (small enough to be fillable later)
    // Classes 0..3 (<= ~37 residual) are highly reusable; large classes are dead-space prone.
    score -= 6.0 * (4.0 - octile.min(4.0)); // up to -24 for near-perfect fits

    // --- Lookahead coupling: does the next item fit in the resulting residual? ---
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            // Next item fits: reward proportionally to how snugly it will fit afterwards
            let post2 = post_residual as f64 - nx;
            score -= 10.0 * (1.0 - post2 / cap);
        } else {
            // Next item won't fit: penalize wasted residual that will strand this bin
            let waste = post_residual as f64;
            score += 0.35 * waste * (nx / cap);
        }
        // Perfect harmonic pairing: next item exactly consumes the residual
        if next_item_size == post_residual {
            score -= 15.0;
        }
    }

    // --- Last-chance bin: strongly prefer using the only bin that fits ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin wastes the mean residual of all open bins.
        // Penalize proportionally to accumulated open capacity, but relax early in the stream
        // and when open bins are already fragmented (high mean residual).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / cap; // 0..1 average waste per open bin
        let mut new_bin_penalty = mean_residual * 0.6 + 8.0 * (1.0 - progress);
        // If open bins are badly fragmented, opening a fresh bin is less harmful
        new_bin_penalty -= 12.0 * fragmentation * fragmentation;
        // A new bin is acceptable if the item is huge (little would remain anywhere anyway)
        new_bin_penalty -= 5.0 * (item_size as f64 / cap);
        score += new_bin_penalty.max(-10.0);
    }

    // --- Modulo arithmetic on post_residual: residuals that are multiples of common
    //     small item sizes (10, 20, 25, 50) are more likely to be exactly filled later ---
    let pr = post_residual;
    if pr > 0 && pr < bin_capacity {
        if pr % 10 == 0 { score -= 3.0; }
        if pr % 25 == 0 { score -= 2.0; }
        if pr % 50 == 0 { score -= 2.0; }
        // Odd, prime-ish residuals are dead space
        if pr % 2 == 1 && pr % 5 != 0 { score += 1.5; }
    }

    // --- Integer-division threshold: residual below the minimum item size is pure dead space ---
    if post_residual < 10 && post_residual > 0 {
        score += 10.0; // stranded sliver
    }

    // Mild preference to keep bin count low: filling existing bins is favored
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "unusable" if it is smaller than the smallest plausible item
    // (we conservatively use a fraction of capacity as a threshold).
    let dead_threshold = bin_capacity as f64 * 0.15;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        // The smaller the dead gap, the worse it is: penalize inversely.
        let waste = dead_threshold - post_residual as f64;
        score += waste * 4.0;
    }

    // Perfect fit bonus: strongly reward near-zero post_residual.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Penalize leaving large gaps only when they don't match the lookahead item.
    if next_item_size > 0 {
        if (post_residual as i64 - next_item_size as i64).abs() <= 3 {
            // post_residual exactly fits the next item: big reward.
            score -= 30.0;
        } else if post_residual < next_item_size {
            // gap too small for the lookahead item: mild penalty.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Open-bins pressure: discourage opening/spreading into many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // (best-fit for large items in fresh bins) and many bins are already open.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 15.0 - large_item * 20.0 + (open_bins_count as f64).sqrt() * 2.0;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a tight bin; prefer filling tight bins.
    let tightness = mean_residual - bin_residual as f64;
    score += tightness * 0.5;

    // Slight preference for filling bins early in the stream (keep fresh bins
    // available for later large items).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact/tight fits: low post_residual is good.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.6;

    // 2-step lookahead: if the next item fits into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let lookahead_fit = (post_residual - next_item_size) as f64;
        score -= 18.0 - 0.15 * lookahead_fit; // prefer next item also fitting snugly
    } else if next_item_size > 0 {
        // Next item won't fit: penalize proportionally to wasted lookahead opportunity,
        // but less harsh if post_residual is tiny (dead space is small anyway).
        let waste = (post_residual as f64).min(next_item_size as f64);
        score += 0.5 * waste;
    }

    // Compare residual against mean residual of open bins:
    // bins with residual below mean are "scarce space" bins — prefer filling them.
    let resid = post_residual as f64;
    if resid < mean_residual {
        score -= 0.4 * (mean_residual - resid);
    } else {
        score += 0.2 * (resid - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: discourage opening a new bin unless the item is large
    // relative to capacity or open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 1.0);
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 30.0 - 20.0 * big_item - 10.0 * crowding;
    }

    // Slight progression term: later in stream, be more conservative about waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress * resid / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space: residuals too small to be useful later.
    if post_residual > 0 {
        let useless = (post_residual as f64) / (bin_capacity as f64);
        if post_residual < 10 {
            score += 40.0 * (1.0 - useless);
        } else {
            score += 5.0 * useless;
        }
    }

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item won't fit here; mild penalty for wasting residual.
            score += 8.0;
        }
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    let pressure = mean_residual / (bin_capacity as f64);
    let open_f = open_bins_count as f64;
    score -= 10.0 * pressure * (1.0 + open_f / 20.0);

    // Time horizon: early in stream, be more willing to open new bins (keep flexibility);
    // late in stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when open bins are few.
        score += 20.0 * progress + 3.0 * (open_f.max(1.0)).ln();
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 10.0; // pairing similar items in a fresh bin is fine
        }
    } else {
        score -= 10.0 * progress;
    }

    // Mild preference for bins whose residual is close to item_size (best-fit flavor).
    let gap = (bin_residual - item_size) as f64;
    score += 0.15 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let post_norm = post / cap;
    let fit = item_size as f64 / cap;

    // Base: tight fit preferred (low post_residual), with mild non-linear shaping.
    let mut score = post * (1.0 + 0.8 * post_norm * post_norm);

    // Stream-progress coupling: later in the stream, reward tightness more aggressively.
    score += 12.0 * progress * post_norm * post_norm * cap * 0.05;

    // Reward bins whose post-residual matches the next item (lookahead synergy).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post - nxt) / cap;
        score -= 6.0 * (-diff * diff * 40.0).exp();
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 5.0;
    }

    // Penalize waste relative to the mean residual across open bins (smooth coupling).
    score += 0.05 * (post - mean_residual).abs();

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * fit;
    }

    // New-bin candidate (empty bin): only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let openness = 1.0 / (1.0 + 0.15 * open_bins_count as f64);
        score = cap as f64 * (0.9 + 0.3 * progress) - 8.0 * scarcity * openness;
    }

    // Small smooth diversity bonus: prefer bins deviating from mean when tight.
    score -= 0.02 * (mean_residual - post) * (1.0 - post_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes of post_residual: residuals divisible by common item sizes
    // (or by capacity fractions) are more reusable, so reward them.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0;
        for m in [10u32, 20, 25, 50, 100] {
            if pr % m == 0 {
                harmony += 6.0;
            }
        }
        // divisibility by the lookahead item makes a perfect follow-up fit
        if next_item_size > 0 && pr % next_item_size == 0 {
            harmony += 15.0;
        }
        score -= harmony;
    } else {
        // perfect closure of a bin is excellent
        score -= 25.0;
    }

    // Integer-division threshold classes on post_residual:
    // classify dead space into usability bands.
    let dead_class = pr / 20; // 0..=5 bands
    score += dead_class as f64 * 4.0;

    // Lookahead coupling: if the next item fits exactly or nearly in post_residual,
    // strongly reward this bin.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = pr - next_item_size;
        score -= (30.0 - slack.min(30) as f64) * 0.8;
    }
    // If next item cannot fit in this residual but fits in a fresh bin, mild penalty
    if next_item_size > pr && next_item_size > 0 {
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + (bin_capacity - post_residual) as f64 * 0.1;
    }

    // New-bin candidate: make opening a new bin moderately costly so we prefer
    // reusing bins, but allow it when residuals are all fragmented (high mean
    // residual spread vs item size).
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // if open bins are mostly full (low mean residual), opening is fine
        score = 45.0 - 30.0 * (1.0 - pressure) + open_bins_count as f64 * 0.5;
        // late in the stream, prefer closing out bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 5.0; // fresh bin always fits next item: slight bonus
        }
    }

    // Small tie-breaker favoring fuller bins (smaller residual) among equals.
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let dead = if post_residual < 10 {
            // gap too small for any plausible item -> dead space
            (10 - post_residual) as f64 * 12.0
        } else {
            0.0
        };
        score += dead;
    }

    // Tight fits are rewarded strongly (wasted-space minimization).
    let tightness = (item_size as f64) / (bin_residual as f64);
    score -= 30.0 * tightness;

    // If next item fits exactly into post_residual, big reward (perfect chaining).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    } else if next_item_size > 0 {
        // next item cannot use the leftover gap: mild penalty scaled by gap size
        score += 0.15 * (post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: penalize using a bin when many are open, to encourage
    // consolidation; but reward filling near-empty bins instead of new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (1.0 - 0.5 * progress);

    // New-bin candidate handling: only prefer a fresh bin if all open fits are bad.
    if bin_residual == bin_capacity {
        // neutral-ish baseline; slight penalty so existing decent fits win
        score += 15.0;
        // but if no open bin can fit, this must be attractive
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer bins whose residual is below mean (denser bins), keep mean spread small.
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via post_residual (already the seed).

    // Strong reward when the residual left behind can host the next item (2-step lookahead match).
    if next_item_size > 0 {
        if post_residual == 0 {
            // Perfect closure of this bin is excellent.
            score -= 60.0;
        } else if next_item_size == post_residual {
            // Exact chain match: ideal 2-step lookahead.
            score -= 90.0;
        } else if next_item_size < post_residual {
            // Next item fits, penalize leftover slack proportionally.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - 0.3 * slack;
        } else {
            // Next item cannot use the residual: dead-space risk.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.4 * waste;
        }
    }

    // Penalize residuals that become unusable for typical items (very small leftover).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative-to-mean residual: leaving less than the mean residual is good (compact packing).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource; only prefer it when
    // the item fits poorly anywhere else (large post_residual waste elsewhere is caught above).
    if bin_residual == bin_capacity {
        // Neutral-ish base for a fresh bin; make it attractive only when it closes tightly later.
        score += 15.0;
        if item_size == bin_capacity {
            score -= 100.0; // full utilization of a new bin
        }
        // If many bins are open, discourage spreading unless needed.
        score += 0.5 * open_bins_count as f64;
    }

    // Slight late-stream tightening: as the stream progresses, favor closing bins fully.
    let progress = step_index as f64 / total_items as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (dead space minimization).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= (1.0 - tightness * tightness) * 30.0;

    // Penalize residuals that are too small to hold typical future items
    // (items can be as small as 1..=100, so any residual > 0 is usable,
    // but small residuals relative to mean demand waste capacity).
    if post_residual > 0 {
        let usable = if post_residual as f64 >= mean_residual { 1.0 } else { post_residual as f64 / mean_residual.max(1.0) };
        score -= usable * 8.0;
    } else {
        // Perfect fill: huge reward.
        score -= 50.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if post-residual is a snug host for next item.
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
            score -= 6.0;
        }
    } else if next_item_size > 0 {
        // Penalize leaving a residual that cannot host the next item.
        score += 5.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins would leave large unusable waste.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin grows with stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 + 15.0 * progress;

        // If many bins are open with plenty of residual space, discourage new bins.
        if mean_residual > item_size as f64 * 1.5 && open_bins_count > 2 {
            score += 10.0;
        }
        // If the item is large and would leave a tiny residual in any bin anyway,
        // a fresh bin may be fine — mild discount.
        if item_size as f64 > bin_capacity as f64 * 0.7 {
            score -= 8.0;
        }
    } else {
        // Mild preference for bins that are already partially filled (consolidation).
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill * 4.0;
    }

    // Crowd penalty: when many bins are open, favor consolidation into fewer bins.
    if open_bins_count > 4 && !is_new_bin {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // waste matters more as the stream matures.
    let norm_pr = pr / cap;
    let coupling = norm_pr * norm_pr * (0.5 + 1.5 * progress) * cap * 0.5;
    score += coupling;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * cap * 0.3;

    // Lookahead: reward bins where the next item also fits (smooth quadratic).
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = pr - next_item_size as f64;
        score -= (1.0 - slack / cap) * cap * 0.25 * (0.5 + progress);
    }

    // Last-chance bonus: penalize alternatives when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= cap * 0.4;
    }

    // New-bin candidate: mildly penalize so it only wins when fits are bad;
    // penalty decays as stream progresses (consolidation early, spread late).
    if bin_residual == bin_capacity {
        score += cap * (0.6 - 0.3 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "usable" classes (large enough chunks) are favored; tiny unusable
    // slivers are penalized.
    let class = post_residual / 10; // 0..=10 harmonic classes
    match class {
        0 => score -= 6.0,          // near-perfect fit, minimal dead space
        1 => score -= 3.0,
        2 => score -= 1.5,
        3 | 4 => score += 1.0,      // awkward mid slivers
        5 | 6 => score += 2.5,
        _ => {}                     // large residual: neutral, still roomy
    }

    // Exact-fit harmonic: post_residual divisible structure rewards
    // residuals that are multiples of common item sizes (10/20/25/50).
    if post_residual > 0 {
        let m = post_residual % 50 == 0 || post_residual % 25 == 0 || post_residual % 20 == 0 || post_residual % 10 == 0;
        if m { score -= 2.0; }
    } else {
        score -= 8.0; // perfect fill
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 10.0;
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.05;
        } else {
            score += 1.0; // next item cannot follow here
        }
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the current item
    // is large relative to capacity or existing bins are quite full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight = mean_residual < item_size as f64 * 1.2;
        if item_size > 60 || (tight && open_bins_count > 0) {
            score -= 3.0 + 2.0 * progress;
        } else {
            score += 12.0; // keep using open bins
        }
    }

    // Mild pressure toward bins below mean residual (balance loads).
    score += ((bin_residual as f64 - mean_residual) * 0.03).max(-2.0).min(2.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A gap is "dead" if it's too small for the smallest plausible item (1..=100),
    // but practically, gaps below ~10 are almost always wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Open-bins pressure: discourage spreading across many bins when few needed.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && next_item_size > bin_residual {
        // Next item won't fit here anyway; slight reward for using residual now.
        score -= 4.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates usefully
    // from the mean — placing into a below-average-residual bin consolidates.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Slight preference for tighter bins overall.
    score += (bin_capacity - bin_residual) as f64 * -0.05;

    // New-bin candidate: make empty bins attractive only when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, offset if current fits are dead-spacey.
        score += 25.0;
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
        if post_residual == 0 {
            score -= 0.0; // placing into empty bin leaves post_residual = C - item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: residual fully consumed
    if post_residual == 0 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward when the next item exactly fills the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0; // chain a perfect second placement
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how little slack remains after both
            let after_two = post_residual as f64 - next_item_size as f64;
            score -= 20.0 - after_two * 0.25;
        } else {
            // next item would NOT fit here: penalize creating tight dead space
            let gap = next_item_size as f64 - post_residual as f64;
            score += gap * 0.6;
        }
    }

    // Penalize large dead space relative to mean residual across open bins
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.35;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Slight preference for filling existing bins early vs late in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Make new-bin candidates less attractive unless nothing fits well
    if bin_residual == bin_capacity {
        score += 40.0;
        // but allow new bin if lookahead suggests a clean two-item split
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize dead space that cannot fit the next item (lookahead coupling)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.3 * post_residual as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward leaving room exactly usable by next item
        score -= 6.0;
    }

    // Tightness reward: smaller waste relative to capacity
    score += 0.15 * (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Crowding: with many open bins, avoid spreading; with few, new bin cheaper
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening new bins unless item is large relative
        // to mean residual or late in stream
        score += 40.0 - 25.0 * progress - 0.1 * (item_size as f64);
        if item_size as f64 > mean_residual + 20.0 {
            score -= 20.0;
        }
        if open_bins_count > 10 {
            score += 10.0;
        }
    }

    // Mean residual coupling: prefer bins deviating below mean (tight bins first)
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Late stream: consolidate aggressively
    if progress > 0.8 {
        score -= 0.2 * (bin_capacity - post_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Core: quadratic penalty on wasted space, modulated by stream progress
    let mut score = pr * (1.0 + 0.8 * pr_norm) + 30.0 * progress * pr_norm * pr_norm;

    // Prefer tight fits: reward small post_residual non-linearly
    score -= 40.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * progress;

    // Dead-space danger: residual too small for typical future items
    if pr > 0.0 && pr < 10.0 {
        score += 25.0 * (10.0 - pr) / 10.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward strongly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 20.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 8.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Mild dispersion penalty: avoid bins far from the mean residual
    score += 0.15 * (pr - mean_residual).abs();

    // New-bin candidate: make it moderately attractive only when stream is early
    // or when current bin would leave a large awkward residual
    if bin_residual == bin_capacity {
        let awkward = pr_norm > 0.6;
        score = if awkward { 5.0 + 20.0 * progress } else { 60.0 + 40.0 * progress };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is "usable"
    // for typical item sizes get a strong bonus (subtracted score).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill is ideal
    } else if pr >= 1 && pr <= 10 {
        score += 25.0; // tiny dead space is nearly unusable
    } else if pr <= 20 {
        score += 8.0; // small dead space, marginal
    } else if pr <= 40 {
        score -= 6.0; // can host small items
    } else {
        score -= 14.0; // large residual remains valuable
    }

    // Modulo structure: residuals that are multiples of common size
    // classes (10/20/25) tile better with future items.
    let harmonic_bonus = if pr % 10 == 0 {
        12.0
    } else if pr % 5 == 0 {
        6.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly prefer this bin (chained perfect packing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 18.0 - 0.4 * slack;
        } else {
            // next item cannot follow here; penalize proportionally
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.5 * item_size as f64;
    }

    // New-bin candidate: prefer opening a fresh bin only when the item
    // is large and existing residuals are small.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = mean_residual / cap; // high = open bins are roomy
        score = 40.0 + 30.0 * pressure - 10.0 * progress
            - 0.4 * item_size as f64
            + if next_item_size > 0 && next_item_size > post_residual { 8.0 } else { 0.0 };
    }

    // Mild penalty when this bin is an outlier vs mean residual
    // (keeps bin population balanced, avoids fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 80.0; // perfect fit reward
    }

    // Reward tight fits (small waste relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64 + 1.0);
    score -= 30.0 * tightness;

    // Open-bin pressure: discourage scattering across many bins.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive if
    // the item fits poorly everywhere else (large residual waste avoided)
    // or the stream is early and consolidation is cheap.
    if bin_residual == bin_capacity {
        let waste_here = bin_capacity as f64 - item_size as f64;
        let waste_elsewhere = mean_residual - item_size as f64;
        if waste_elsewhere < waste_here {
            score += 120.0; // existing bins fit better; keep item there
        }
        // Mild early-stream penalty so consolidation is preferred initially.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * (1.0 - progress);
    }

    // Lookahead: if next item would fit the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 30.0; // dead space next item cannot use
    }

    score
}

