pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Base: prefer minimal post_residual (tight fit), scaled non-linearly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score = pr * (1.0 + pr / (2.0 * cap));

    // Dead-space penalty: post_residual too small to ever fit a future item
    // (future items >= 1, but small slivers are statistically wasteful).
    if post_residual < 10 {
        score += 25.0 + 2.0 * (10 - post_residual) as f64;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post_residual as f64 >= ni {
            // Next item fits here: reward proportionally to how well it would nest.
            let nest_waste = pr - ni;
            score -= 12.0 - 0.15 * nest_waste;
        } else {
            // Next item cannot follow into this bin: mild penalty for tight fills
            // that strand the residual, stronger when residual is mid-range.
            score += 0.08 * pr;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0 + 0.5 * item_size as f64;
    }

    // Many open bins: encourage consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = (open_bins_count as f64).ln().max(0.0);
    if !is_new_bin {
        score -= 1.5 * consolidation * (0.3 + 0.7 * progress);
    } else {
        // Opening a new bin: penalize more when many bins are already open
        // and mean residual is high (existing capacity is being wasted).
        score += 6.0 + 0.4 * consolidation + 0.25 * (mean_residual - pr).max(0.0);
        // Early stream: opening bins is cheap; late stream: prefer filling.
        score += 10.0 * (1.0 - progress);
    }

    // Global residual balance: prefer bins whose residual is above the mean
    // (drain fuller bins first, keep small residuals for small items).
    if !is_new_bin {
        let diff = (bin_residual as f64) - mean_residual;
        score -= 0.05 * diff;
    }

    // Reward using large items to fill large residuals (pairing big with big).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill_ratio * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_norm = pr / cap; // 0..1 residual fraction after placement

    // Base: prefer small post-residual, with non-linear penalty on wasted space.
    let mut score = pr;

    // Quadratic/cubic waste coupling: dead space is increasingly bad.
    score += 30.0 * fit_norm * fit_norm * (1.0 - 0.5 * progress);

    // Smooth interaction: reward tight fits more as stream progresses.
    score -= (1.0 - fit_norm).powi(3) * (20.0 + 30.0 * progress);

    // Lookahead coupling: smooth reward if next item can use the post-residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let usable = (pr - nxt).max(0.0) / cap;
        score -= 15.0 * (1.0 - (pr / nxt.max(1.0))).abs().min(1.0) * (1.0 - usable);
    }

    // Mean-residual alignment: prefer bins near the mean (smooth Gaussian-ish).
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Last-chance bin: strong smooth reward to use it rather than open a new one.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - fit_norm * fit_norm);
    }

    // New-bin candidate: penalize smoothly, more so early when open bins exist.
    let is_new = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new {
        score += 40.0 + 20.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64).ln() * fit_norm * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: bins whose leftover falls into
    // "small residue" classes (<=10, or <=20) are valuable; large leftovers
    // in awkward classes (e.g. 21..=40) are dead space unless reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 45.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    } else if post_residual <= 20 {
        score -= 12.0;
    } else if post_residual <= 30 {
        score -= 4.0;
    }

    // Harmonic / modulo structure on post_residual: residues that are common
    // item-size complements (multiples of 5 and 10) are easier to fill later.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    } else if post_residual % 2 == 1 {
        score += 2.0; // odd residues pair poorly with typical even-ish sizes
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let leftover2 = post_residual - next_item_size;
            if leftover2 <= 10 {
                score -= 20.0;
            } else if leftover2 <= 20 {
                score -= 8.0;
            } else {
                score += 3.0; // leaves a large awkward second leftover
            }
        } else {
            // next item cannot follow here; residual must serve future items
            score += (pr / 25.0).min(8.0);
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else {
            (mean_residual - pr).abs()
        };
        // Opening a new bin is good when existing residuals are small/awkward.
        score += 15.0 - 0.35 * mean_residual.min(60.0) - pressure * 0.1;
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer filling bins with below-average residual (consolidate emptier bins).
    if bin_residual < bin_capacity {
        score += 0.15 * (mean_residual - pr);
    }

    // Mild penalty for proliferating bins when a fit exists.
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0;
    }

    // Non-linear dead-space shaping: small unusable gaps are worse than large ones.
    let pr = post_residual as f64;
    if pr > 0.0 && pr <= 20.0 {
        score += (20.0 - pr) * (20.0 - pr) * 0.35;
    }

    // Reward tight fits (small post_residual relative to item).
    if item_size > 0 {
        let fill = item_size as f64 / bin_residual.max(1) as f64;
        score -= fill * 18.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when the item barely fits nowhere well
    // or when open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let mean_fill_pressure = mean_residual / bin_capacity as f64;
        // Penalize opening a new bin when existing bins have room.
        score += 70.0 + mean_fill_pressure * 0.0;
        // But discount if no good fit exists: few fitting bins and large mean residual mismatch.
        if fitting_bins_count <= 1 {
            score -= 55.0;
        }
        // Lookahead: if next item would pair with this item in a fresh bin, mild discount.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 25.0;
        }
        // Late in stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    score += open_bins_count as f64 * 0.6;

    // Prefer bins whose residual is close to the mean (balance load).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Lookahead synergy: reward leaving exactly enough room for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Perfect match for the next item is highly desirable.
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            // Penalize proximity mismatch, scaled by how large the next item is.
            score += diff * (0.4 + next_item_size as f64 / 200.0);
        }
        // If the next item fits in the post residual, mild reward for keeping viability.
        if post_residual >= next_item_size && post_residual != next_item_size {
            score -= 8.0;
        }
        // If the next item would NOT fit, penalize creating such dead space
        // proportionally to how small the dead space is (unusable slivers).
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    } else {
        // Last item: prefer tightest fit.
        score -= 20.0;
    }

    // Relative to mean residual: bins already "tight" are precious; penalize
    // consuming space from bins below the mean residual.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += (mean_residual - pr) * 0.5;
    } else {
        score -= (pr - mean_residual) * 0.2;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when no open bin is a good fit.
    if bin_residual == bin_capacity {
        let good_fit = next_item_size > 0 && post_residual == next_item_size;
        if open_bins_count == 0 {
            score -= 30.0; // must open a bin
        } else if fitting_bins_count == 0 {
            score -= 25.0; // no alternative
        } else if good_fit {
            score -= 35.0; // fresh bin guarantees the 2-step match
        } else {
            // Prefer existing bins generally; make new bin slightly unattractive,
            // but soften as stream progresses (less future to amortize).
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 15.0 * (1.0 - 0.5 * progress);
        }
    }

    // Mild reward for keeping many open bins' residuals balanced.
    score += (open_bins_count as f64).ln().max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 15 {
        score -= 25.0;
    }

    // Penalize dead space relative to capacity (nonlinear).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_frac * waste_frac;

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 8.0; // leftover likely wasted for next item
        }
        // If this bin is the only one that fits now AND next item also fits here, doubly reward.
        if fitting_bins_count == 1 && post_residual >= next_item_size {
            score -= 40.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New empty bin candidate: penalize unless few bins fit or item is huge.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / fitting_bins_count as f64 };
        let big_item = item_size as f64 / bin_capacity as f64;
        let need = pressure + big_item;
        score += 90.0 - 70.0 * need;
        // Early in stream, opening bins is cheap and gives flexibility.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * (1.0 - progress);
        // Few open bins -> opening is fine.
        if open_bins_count < 3 {
            score -= 20.0;
        }
    }

    // Global balance: prefer bins whose residual deviates from mean to consolidate.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild preference for fuller bins late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // Tie-break noise-free deterministic jitter by index parity.
    if step_index % 2 == 0 { score -= 0.01; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let prn = pr / bin_capacity as f64;
    let poly = prn * prn * (1.0 + progress) - prn * progress * progress;
    score += poly * 12.0;

    // Reward tight fits, more strongly later in the stream
    let tight = 1.0 - prn;
    score -= tight * tight * (10.0 + 30.0 * progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 && post_residual > 0 {
        let nx = next_item_size as f64;
        if (post_residual as f64) < nx {
            score += (nx - post_residual as f64) * (0.5 + progress);
        } else {
            score -= 2.0;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0 + 10.0 * progress;
    }

    // Mild penalty when many bins are open
    score += open_bins_count as f64 * 0.05;

    // Smooth preference toward bins near the mean residual
    let dev = pr - mean_residual;
    score += dev * dev * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that fall into
    // "reusable" classes (multiples of common small item sizes).
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit, best possible outcome
    } else if pr % 10 == 0 {
        -25.0 + (pr as f64) * 0.08
    } else if pr % 5 == 0 {
        -12.0 + (pr as f64) * 0.10
    } else {
        8.0 + (pr as f64) * 0.15 // awkward residual class
    };
    score += class_bonus;

    // Integer-division threshold: small leftovers are dead space unless exact.
    if pr > 0 && pr < 10 {
        score += 18.0;
    }

    // Lookahead coupling: reward leaving room for the next item exactly.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (pr as f64) >= n {
            let slack = pr as f64 - n;
            if slack as u32 % 5 == 0 {
                score -= 14.0;
            } else {
                score -= 6.0;
            }
            score += slack * 0.05;
        } else {
            score += 10.0; // next item cannot use this bin's leftover
        }
    }

    // Last-chance bin: strongly favor using the sole fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening new bins when open bins fit reasonably well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 * 0.4 + progress * 10.0;
        score += 25.0 + pressure;
        if item_size as f64 > mean_residual {
            score -= 10.0; // item doesn't fit open bins anyway
        }
    }

    // Mild preference for tighter bins overall.
    score += (mean_residual - bin_residual as f64).abs() * 0.02;
    score -= (bin_capacity - bin_residual) as f64 * 0.05; // fuller bins preferred

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold the smallest
    // plausible future item (sizes >= 1, but small gaps < 10 are nearly dead)
    // are strongly penalized.
    let dead_threshold = 9u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 12.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    }

    // Reward tight fits: small post_residual relative to bin capacity.
    score -= (bin_capacity - post_residual) as f64 * 0.15;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < dead_threshold {
            score -= 35.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this residual: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.4;
    }

    // Pressure against proliferating open bins: penalize placements that leave
    // large residuals in bins when many bins are already open.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 8.0;

    // New-bin candidate: only attractive when no open bin has a decent fit
    // (i.e., mean residual is small relative to item) or late in the stream.
    if bin_residual == bin_capacity {
        let base = 85.0;
        let desperation = (item_size as f64 / mean_residual.max(1.0)).min(3.0);
        score = base - desperation * 20.0 - (fitting_bins_count == 0) as i32 as f64 * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: tight fit reward (small post_residual is good)
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Aggressive 2-step lookahead: reward when next item exactly matches post_residual
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.8;
        if post_residual == next_item_size {
            score -= 25.0; // perfect chaining: next item fills this bin exactly
        } else if post_residual > next_item_size {
            score -= 5.0; // next item still fits here
        } else {
            // next item won't fit: penalize large dead space left behind
            score += (post_residual as f64) * 0.3;
        }
    } else {
        // last item: minimize post_residual aggressively
        score += (post_residual as f64) * 0.5;
    }

    // Compare post_residual against mean residual: leaving near-mean residual keeps flexibility
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += mean_gap * 0.2;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins exist with decent fit
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus penalty scaled by stream progress
        score += 20.0 + (step_index as f64 / total_items.max(1) as f64) * 10.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // fresh bin may suit a large upcoming item pair
        }
        if fitting_bins_count > 0 && post_residual as f64 > mean_residual {
            score += 5.0;
        }
    }

    // Slight preference for filling bins with less residual before placement (compactness)
    score += (bin_residual as f64) * 0.05;

    // Late-stream urgency: consolidate more strongly near the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot hold the next item (lookahead waste).
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            score += 6.0 * (next_item_size - post_residual) as f64;
        } else {
            // Reward residuals that still fit the next item.
            score -= 3.0;
        }
        // Perfect chain: residual exactly fits next item.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many fitting bins: prefer the fullest (small residual) — already via post_residual,
    // but add pressure when many bins compete.
    if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Penalize placing into bins far below mean residual (poor consolidation),
    // reward bins at or above mean residual (they are already well-filled).
    if post_residual as f64 > mean_residual + 0.5 {
        score += 0.05 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.05 * (mean_residual - post_residual as f64);
    }

    // Time horizon: early in stream, be frugal with open bins (favor consolidation);
    // late in stream, less concern about bin count, favor any reasonable fit.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * (1.0 - progress) * tightness;

    // Many open bins: discourage opening new bins / spreading items.
    if open_bins_count > 4 {
        score += 0.3 * open_bins_count as f64 * (1.0 - tightness);
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 25.0 + 10.0 * desperation + (1.0 - progress) * 8.0;
        // If next item is huge, a fresh bin's large residual is valuable.
        if next_item_size > bin_capacity / 2 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Smooth polynomial coupling of waste with stream progress:
    // later in the stream, dead space is penalized more aggressively.
    let norm_waste = pr / cap;
    score += (norm_waste * norm_waste) * cap * (0.5 + progress);
    score += (norm_waste * norm_waste * norm_waste) * cap * progress * 2.0;

    // Reward perfect/near-perfect fits smoothly (continuous coupling).
    let fit_quality = 1.0 - (pr / cap);
    score -= fit_quality * fit_quality * item_size as f64 * (1.0 + progress);

    // Lookahead: reward leaving room for the next item (smooth kernel).
    if next_item_size > 0 {
        let gap = (pr as i64 - next_item_size as i64) as f64;
        let kernel = (-gap.abs() / (cap * 0.25)).exp();
        score -= 8.0 * kernel * (1.0 + progress);
        // penalize leaving a sliver that next item can't use
        if next_item_size as f64 > pr {
            score += 4.0 * (1.0 - progress);
        }
    }

    // Last chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Favor bins tighter than the mean residual (best-fit flavor), smooth.
    score += (pr - mean_residual).abs() * 0.05;

    // New-bin candidate: make it attractive only when existing fits are poor.
    if bin_residual == bin_capacity {
        let penalty = 25.0 * (1.0 - progress);
        score += penalty;
        // if item is large relative to capacity, opening fresh is fine
        score -= 0.15 * item_size as f64;
    }

    // Mild preference to spread load when many bins open (balance residuals).
    score += (open_bins_count as f64).ln() * 0.3 * norm_waste;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes mod capacity fractions
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let eighth = bin_capacity / 8;

    // Penalize dead space by class: residuals in awkward ranges are hard to fill later
    let r = post_residual;
    if r == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if r < eighth {
        score -= 20.0; // tiny leftover is nearly dead but cheap
    } else if r <= quarter {
        score += 8.0; // small awkward class
    } else if r <= half {
        score += 4.0; // medium class still usable
    } else {
        score -= 5.0; // large residual means item was small; bin stays flexible
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 80.0;
        } else if next_item_size <= r {
            let slack = r - next_item_size;
            score -= 30.0 * (1.0 - slack as f64 / bin_capacity as f64);
            // harmonic bonus if next item lands in a good class
            if slack <= quarter {
                score -= 10.0;
            }
        } else {
            // next item cannot use leftover; penalize proportionally to wasted potential
            score += (next_item_size - r) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // among multiple candidates, prefer tighter fits (already via post_residual)
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Prefer filling bins when many are open (reduce fragmentation)
    score -= open_bins_count as f64 * 0.5;

    // New-bin candidate: penalize opening a new bin unless item is large and no good fit exists
    if bin_residual == bin_capacity {
        score += 55.0;
        if item_size >= half {
            score -= 25.0; // large items pair well with a fresh bin
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 30.0; // fresh bin can host current + next item
        }
    }

    // Mild stream-progression pressure: pack tighter later in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    // Reward exact division classes (harmonic alignment with capacity)
    if r > 0 && bin_capacity % r == 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    }

    // Reward tight fits (small waste relative to item size).
    score -= (item_size as f64) * (bin_capacity as f64 - post_residual as f64) / (bin_capacity as f64) * 0.3;

    // Pressure from number of open bins: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // dead space relative to lookahead
    }

    // Prefer bins whose residual is below mean residual (tighter bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad.
    if bin_residual == bin_capacity {
        score += 45.0;
    }

    // Late-stream consolidation: as stream progresses, favor existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Base tightness: prefer bins that become nearly full.
    score += 0.5 * (1.0 - post / cap) * 20.0;

    // 2-step lookahead: reward when next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = post - nxt;
            score -= 30.0 * (1.0 - slack / cap); // perfect chain bonus
        } else {
            // next item cannot follow: penalize proportionally to wasted chain potential
            score += 10.0 * (nxt - post) / cap;
        }
        // coupling with mean residual: is this bin's post-residual near the stream's typical need?
        let gap = (post - mean_residual).abs();
        score += 0.15 * gap;
    } else {
        // last item: just fill tightest
        score += 0.0;
    }

    // Last-chance bin: strong penalty to skip it (avoid opening a new bin needlessly).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly unless current bin would leave a large dead zone.
    if bin_residual == bin_capacity {
        let dead = if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 { 0.0 } else { 5.0 };
        score += 15.0 - dead;
    }

    // Late-stream consolidation: favor existing bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    // Prefer bins whose residual is far from item_size (avoid near-miss fits) mildly.
    let miss = (bin_residual as f64 - item_size as f64) / cap;
    score += 3.0 * miss;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual), nonlinearly.
    let tight = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tight * tight;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: residual too small for any plausible item (min size 1, but
    // typical items larger) is wasted. Penalize residuals that next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward leaving exactly enough room for the next item (chaining).
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item can't fit in leftover: dead space penalty scaled by waste.
            let dead = post_residual as f64;
            score += 0.5 * dead + 10.0;
            // Extra penalty if next item would have fit in current residual (we broke a chain).
            if bin_residual >= next_item_size && post_residual < next_item_size {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate (empty bin): make it less attractive unless open bins are crowded.
    if bin_residual == bin_capacity {
        score += 55.0;
        // If mean residual across open bins is large, opening new bins is wasteful.
        score += 0.6 * mean_residual;
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // But if next item is huge and this item is small, a fresh bin may be fine.
        if next_item_size > 70 && item_size < 30 {
            score -= 40.0;
        }
    }

    // Prefer filling bins with larger residuals among equally tight options (consolidation).
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // Many open bins: encourage closing them out (prefer bins closer to full).
    score += 0.3 * open_bins_count as f64 * tight;

    // Early stream: allow moderate looseness to keep flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 0.85 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Non-linear polynomial coupling: waste penalty grows super-linearly,
    // modulated by stream progress (late stream punishes slack more).
    let poly = x * x * (1.0 - x) + x * x * x;
    score += 60.0 * poly * (0.5 + progress);

    // Reward tight fits (post_residual near zero) smoothly.
    score -= 25.0 * (1.0 - x).powi(6) * (0.6 + 0.4 * progress);

    // Lookahead: if next item fits into the post residual, reward; else penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let snug = 1.0 - ((pr - nx) / cap);
            score -= 15.0 * snug * snug;
        } else {
            score += 12.0 * ((nx - pr) / cap);
        }
    }

    // Last chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: mildly penalize opening a bin early, less so late
    // or when existing bins are crowded (mean residual low).
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64).ln() + 1.0;
        score += 8.0 * crowding * (1.0 - progress) - 5.0 * (mean_residual / cap);
    }

    // Slight preference for bins with residual close to mean (balance load).
    score += 0.05 * ((bin_residual as f64 - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into residue classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit reward: post residual exactly divisible into useful harmonic classes.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 300.0;
    } else if post_residual % 25 == 0 {
        score -= 120.0; // leaves room for a quarter-capacity class item
    } else if post_residual % 10 == 0 {
        score -= 60.0;
    }

    // Fractional capacity coupling: how much of the bin remains as a fraction.
    let frac = pr / cap;
    score += 40.0 * frac * frac; // penalize large leftover quadratically

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= 0.5 * next_item_size as f64;
        } else {
            // next item cannot fit here; penalize proportionally to wasted potential
            score += 0.3 * (next_item_size as f64 - pr);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin mildly, unless current fit is terrible.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.25 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin anyway
        }
        if next_item_size > 0 && next_item_size >= item_size && next_item_size <= bin_capacity {
            score -= 20.0;
        }
    }

    // Dead-space threshold: residual too small for typical minimum item (<=10) is fine;
    // residual in awkward mid-range (11..=19) is penalized.
    if post_residual >= 11 && post_residual <= 19 {
        score += 80.0;
    }

    // Stream progression: late in stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (mean_residual - pr).max(0.0) / cap.max(1.0);

    // Prefer bins with below-mean residual (tight packing).
    score += 0.2 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item (min size 1) can use are pure waste;
    // gaps too small for typical items (10..80 range) are near-dead space.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // completely unusable gap
        } else if post_residual < 20 {
            score += 25.0; // only tiny items can fit
        } else if post_residual < 30 {
            score += 10.0;
        }
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Prefer bins whose residual was large but is now well-utilized (tight packing).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0; // next item won't fit here; slight penalty
    }

    // Mean residual coupling: bins deviating below mean residual are already tight; keep them.
    score += 0.05 * (mean_residual - post_residual as f64).max(0.0);

    // New-bin candidate handling: an empty bin is attractive early, costly late.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 + 30.0 * progress; // opening new bins gets progressively worse
        // But if existing bins would leave bad dead space, opening is fine (score already penalized there).
        if post_residual == 0 { score -= 10.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly (or nearly) matches the next item's size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match bonus: post_residual == next_item_size
        let match_bonus = if post_residual == next_item_size {
            40.0
        } else {
            40.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0)
        };
        score -= match_bonus;

        // Penalize creating residuals too small for the next item
        // (dead space), but only mildly if the gap is tiny.
        if post_residual < next_item_size && post_residual > 0 {
            score += 10.0 * (1.0 - gap / 20.0).max(0.0);
        }
    }

    // Compare post_residual relative to mean residual across open bins:
    // prefer bins that end up closer to the average fill state.
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * mean_gap;

    // Tight fits are good: small post_residual relative to capacity.
    score += 0.05 * post_residual as f64;

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise this item forces a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so as the
    // stream progresses and open bins exist; relax if many bins are open
    // and mean residual is high (fragmentation -> consolidation may fail).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut penalty = 18.0 + 12.0 * progress;
        if mean_residual > 30.0 && open_bins_count > 2 {
            penalty -= 8.0;
        }
        score += penalty;
    }

    // Slight preference for bins with large residual (better packing
    // headroom) when item is small, to avoid wasting big spaces.
    if item_size < 30 {
        score += 0.03 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio discount.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill * fill;

    // Penalize small unusable post-residuals relative to item scale
    // (dead space that no typical item can use).
    if post_residual > 0 {
        let dead = post_residual as f64;
        let usable = if dead >= 10.0 { 0.0 } else { (10.0 - dead) / 10.0 };
        score += 18.0 * usable * usable;
    }

    // Lookahead: if next item fits exactly into the post-residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; mild penalty for wasting space now.
            score += 4.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins with residuals below mean (tighter bins first),
    // keeping looser bins available for future large items.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Late in the stream: consolidate aggressively to close bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // Many open bins: discourage spreading into looser bins; prefer tight ones.
    if open_bins_count > 3 {
        score += 0.3 * ((open_bins_count as f64).ln()) * (bin_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad.
    if bin_residual == bin_capacity {
        score += 22.0;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Opening new bin early is fine when mean residual is already high.
        score -= 6.0 * (mean_residual / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post_residual (tight fits), non-linearly amplified
    let mut score = pr * pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space becomes more costly
    let prog2 = progress * progress;
    score += pr * (0.5 + 2.0 * prog2 + 2.0 * progress);

    // Reward filling bins deeply relative to capacity
    let fill = (bin_residual as f64) / cap;
    score -= (1.0 - fill) * (1.0 - fill) * cap * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - progress);
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // mild preference among many fitting bins toward tighter ones (already via pr)
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead coupling: if next item fits the post_residual exactly-ish, big reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        if gap < 10.0 {
            score -= 25.0 * (1.0 - gap / 10.0);
        } else if nxt <= pr {
            score -= 8.0 * (1.0 - gap / cap);
        } else {
            // next item won't fit here; penalize leaving a large awkward residual
            score += 0.05 * pr * (nxt / cap);
        }
    } else {
        // last item: any placement is fine, prefer tightest
        score += 0.0;
    }

    // Mean residual context: if this bin's residual is far below mean, it's a good squeeze target
    let this_res = pr;
    score -= 0.3 * (mean_residual - this_res);

    // New-bin candidate handling: empty bin gets a mild default; opening a new bin
    // is only preferred when all open bins would leave huge dead space
    if bin_residual == bin_capacity {
        score = cap * 0.6 + 0.1 * (open_bins_count as f64);
        // allow opening a new bin early-ish or when the item is large
        score -= 0.5 * (item_size as f64);
        score -= 30.0 * (1.0 - progress) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: perfect fits (0) and small residues
    // that other items can fill are good; mid-range dead space is bad.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0;
    } else {
        // dead-space penalty grows quadratically with residue fraction
        let frac = pr as f64 / bin_capacity as f64;
        score += 40.0 * frac * frac;

        // Harmonic classes: residues divisible by small numbers (10, 20, 25, 50)
        // are more likely reusable later.
        let reusable = (pr % 10 == 0) as i32 as f64 * 12.0
            + (pr % 25 == 0) as i32 as f64 * 8.0
            + (pr % 50 == 0) as i32 as f64 * 8.0;
        score -= reusable;

        // integer-division thresholds: tiny residues (<=10) are near-dead space
        if pr <= 10 {
            score -= 15.0; // fine, almost full
        } else if pr <= 20 {
            score += 5.0;
        } else if pr >= 60 {
            score += 10.0; // wasteful
        }
    }

    // Lookahead: does next_item_size fit exactly / at all into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 55.0; // perfect chain
        } else if next_item_size <= pr {
            score -= 20.0 * (1.0 - (pr - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot follow here; penalize more when residue is large
            score += 8.0 * (pr as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Prefer filling existing bins over opening new ones, especially early.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let is_new_bin = bin_residual == bin_capacity && bin_residual == item_size;
    if is_new_bin {
        score += 30.0 + 25.0 * (1.0 - progress);
    }

    // Mild preference for bins with below-mean residual (fill emptier bins first
    // keeps tight bins available for small items).
    score += 0.15 * (mean_residual - bin_residual as f64).max(-40.0).min(40.0);

    // Tie-break with harmonic class of item size itself.
    score -= (item_size % 10 == 0) as i32 as f64 * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post-residual exactly, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.25 * (post_residual as f64 - next_item_size as f64).min(20.0);
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 20.0; // dead gap that next item cannot use
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Pressure from number of open bins: discourage spreading into many bins.
    score += 0.6 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins whose residual is close to item need.
    let dev = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate: only attractive when no open bin fits or fits are terrible.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 200.0; // must open
        } else if fitting_bins_count == 1 {
            score += 10.0; // prefer the last-chance existing bin
        } else {
            score += 25.0 + 2.0 * fitting_bins_count as f64; // prefer existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized post-residual penalty
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 30.0;

    // Aggressive 2-step lookahead: if next item fits exactly into post_residual, strongly reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this bin's leftover: penalize wasted residual
            let waste = post_residual as f64;
            score += 0.15 * waste;
        }
    }

    // Compare post_residual relative to mean residual across open bins
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 1.0 {
            score -= 10.0 * (1.0 - rel);
        } else {
            score += 8.0 * (rel - 1.0).min(2.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        } else {
            // penalize opening new bin when open bins could fit
            score += 45.0 + 5.0 * open_bins_count as f64;
        }
    }

    // Slight preference for consolidating into fewer bins early vs late
    let progress = step_index as f64 / total_items.max(1) as f64;
    if !is_new_bin {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tightness * tightness * (item_size as f64);

    // Lookahead: if the next item fits exactly in post_residual, strongly reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Leaving residual that next item can't use is a mild penalty
        score += 2.0;
    }

    // Last chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin when other bins fit,
    // unless all fits are terrible (post_residual very small everywhere).
    if bin_residual == bin_capacity {
        let bad_fits = if fitting_bins_count == 0 {
            0.0
        } else {
            (item_size as f64) // proxy: how much would be wasted anyway
        };
        let waste_threshold = 0.25 * bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else if post_residual as f64 > waste_threshold {
            // Opening a fresh bin is fine if existing fits waste a lot
            score -= 5.0 + bad_fits * 0.1;
        } else {
            score += 30.0; // prefer existing bins when fits are decent
        }
    }

    // Prefer filling bins with larger mean residual (consolidate slack)
    score -= 0.3 * mean_residual;

    // Time horizon: early in stream, be more liberal with new bins (long game);
    // late in stream, squeeze into existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Slight penalty for accumulating many open bins with low residual
    if open_bins_count > 4 && post_residual < 10 {
        score -= 2.0; // finishing off a nearly-full bin is good
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: prefer minimal post residual, with non-linear blow-up for tiny slivers.
    let mut score = post + 0.35 * (post * post) / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, moderate leftovers are fine; late in the stream, dead space hurts more.
    let prog_term = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += 6.0 * (post / cap) * (1.0 - prog_term);
    score += 10.0 * ((post / cap) * (post / cap)) * progress;

    // Lookahead: penalize if the next item cannot fit in the post residual
    // (smooth soft-penalty based on relative overflow).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let overflow = (nxt - post).max(0.0) / cap;
        score += 18.0 * overflow * (1.0 + progress);
        // Reward if next item fits snugly into post residual.
        if nxt <= post {
            let snug = 1.0 - ((post - nxt) / cap);
            score -= 6.0 * snug * snug;
        }
    }

    // Last chance: this is the only bin that fits; strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Many options: mild penalty to keep diversity, scaled by crowding.
        score += 1.5 * ((fitting_bins_count as f64).ln().max(0.0));
    }

    // Prefer bins whose residual is below the mean (tight bins get used first).
    score += 3.0 * ((bin_residual as f64 - mean_residual) / cap);

    // New-bin candidate: residual == capacity. Make it attractive only when
    // item is large (its post residual would be small anyway) or stream is early.
    if bin_residual == bin_capacity {
        let new_bin_bonus = 20.0 * (item / cap) + 8.0 * (1.0 - progress);
        score -= new_bin_bonus;
        // Slight penalty for proliferating bins when many are already open.
        score += 0.4 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual mod capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left after placement

    // Reward near-perfect fits strongly (post residual in small harmonic classes)
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 180.0;
    } else if post_residual <= 20 {
        score -= 90.0;
    }

    // Modulo-10 harmonic classes: penalize residuals that are awkward sizes
    let class = post_residual % 10;
    if class >= 1 && class <= 3 {
        score -= 25.0; // small dead space class is tolerable
    } else if class >= 8 {
        score += 15.0; // nearly-full-of-gaps class
    }

    // Integer division thresholds on post_residual: usable chunk analysis
    // A residual is "reusable" if a typical next item (>=10) fits
    if post_residual >= 10 {
        score -= 40.0;
        // extra reward if it can host two more small items
        if post_residual >= 20 {
            score -= 20.0;
        }
    } else {
        // dead space: unusable chunk
        score += 60.0;
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 70.0; // chain fit: excellent
            // harmonic match: next item exactly fills residual class
            if post_residual - next_item_size <= 5 {
                score -= 60.0;
            }
        } else {
            // next item won't fit here; mild penalty scaled by overshoot
            let over = (next_item_size - post_residual) as f64;
            score += (over / cap).min(1.0) * 30.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate logic: penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin: its full residual is "wasteful" early
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_cost = 200.0;
        // if many bins can fit, prefer reusing one
        if fitting_bins_count > 0 {
            new_bin_cost += 80.0 + 20.0 * (fitting_bins_count as f64).min(5.0);
        }
        // late in stream, opening bins is more acceptable (less future to serve)
        new_bin_cost *= (1.0 - 0.4 * progress);
        // if item is large and current mean residual is small, new bin is fine
        if (item_size as f64) > mean_residual {
            new_bin_cost -= 60.0;
        }
        score += new_bin_cost;
    }

    // Mild preference for bins with residual close to item (tight packing)
    let tightness = (bin_residual - item_size) as f64;
    score += 0.1 * (tightness - pr).abs();

    // Slight preference for bins whose residual diverges from mean (consolidate waste)
    score += 0.05 * ((bin_residual as f64) - mean_residual).abs();

    // Open-bin count pressure: discourage proliferation of open bins early
    score += 2.0 * (open_bins_count as f64).sqrt() * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

