    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear sharpening.
    let mut score = pr + 40.0 * pr_norm * pr_norm;

    // Smooth interaction: as the stream progresses, tighten the tolerance for
    // leftover dead space (late-stage waste is costlier).
    score += 25.0 * progress * pr_norm * (1.0 - pr_norm);

    // Reward using an existing bin, especially when it's the only fitting one.
    let last_chance = if fitting_bins_count == 1 { 1.0 } else { 0.0 };
    score -= 12.0 * last_chance * (1.0 - pr_norm * pr_norm);

    // Penalize opening new bins when plenty of fitting bins exist; the empty-bin
    // candidate has fitting_bins_count counted among fitting bins too, so this
    // smooths pressure toward consolidation.
    score += 3.0 * (open_bins_count as f64).sqrt() * pr_norm;

    // Lookahead: if the next item can fit into the post-residual, reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack_after_next = (pr - nxt) / cap;
            score -= 8.0 * (1.0 - slack_after_next) * (1.0 - progress);
        } else {
            // Smooth penalty proportional to shortfall, stronger early on.
            let shortfall = (nxt - pr) / cap;
            score += 6.0 * shortfall * (1.0 - progress);
        }
    }

    // Mild penalty when this bin's residual deviates from the mean residual,
    // encouraging balanced residual distributions (smooth quadratic coupling).
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Small bonus for placing larger items early (big items are hardest to fit).
    score -= 2.0 * (item_size as f64 / cap) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (small residuals) get strong rewards.
    let cap = bin_capacity as f64;

    // Reward tight fits: quadratic bonus for small post_residual.
    if post_residual <= 10 {
        score -= 60.0 - (post_residual as f64) * 4.0;
    } else if post_residual <= 20 {
        score -= 25.0 - (post_residual as f64) * 0.8;
    }

    // Modulo-classes: residuals divisible by common item sizes are more reusable.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 15.0; // round residual: easy to fill later
        } else if pr % 5 == 0 {
            score -= 7.0;
        }
        // Penalize awkward odd residuals in the "dead zone" (21..35)
        if pr > 20 && pr < 35 && pr % 2 == 1 {
            score += 12.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 80.0;
        } else if next_item_size < pr && pr - next_item_size <= 10 {
            score -= 40.0;
        } else if next_item_size > pr && next_item_size <= bin_residual {
            // next item would fit this bin only if we DON'T place current item here poorly;
            // slight penalty if we'd waste the bin for the next item
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // neutral baseline slightly above good fits
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else if mean_residual < item_size as f64 * 0.9 {
            score -= 25.0; // existing residuals are too tight anyway
        }
    }

    // Progress-aware tightening: late in the stream, prefer consolidating into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual as f64 - post_residual as f64); // reward using more space late

    // Prefer bins whose residual is far from mean (better specialization) mildly.
    score += ((bin_residual as f64) - mean_residual).abs() * 0.05;

    // Penalize leaving residuals in the 31..40 band (hard to fill for items >=10..80 granularity).
    if pr >= 31 && pr <= 40 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are the worst outcome.
    // Treat post_residual < 10 as fully wasted (nothing else can ever fit).
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        // Small gaps are risky: only next items <= post_residual fit.
        score += 25.0;
    } else if post_residual <= 35 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 55.0;
        // Reduce penalty as open bins multiply (bin pressure is low early).
        score -= 4.0 * (open_bins_count as f64).ln().max(0.0);
        // If current item leaves a dead gap in any existing bin, new bin looks better.
        if post_residual < 10 {
            score -= 50.0;
        }
        // If the next item is large, a fresh bin is valuable.
        if next_item_size >= 60 {
            score -= 15.0;
        }
    }

    // Open-bins pressure: penalize spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // Lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize leaving a gap the next item cannot use.
    if next_item_size > post_residual && post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 {
        score -= 10.0 * progress;
    }

    // Mean-residual coupling: if this bin is far below mean residual,
    // it is relatively full; favor finishing it off.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: this bin's post residual exactly fits next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Penalize leftover after the hypothetical next placement.
            let double_left = (post_residual - next_item_size) as f64;
            score += double_left * 0.35;
        } else {
            // Next item cannot follow into this residual; dead space likely.
            score += (next_item_size - post_residual) as f64 * 0.20;
        }
    }

    // Reward tight fits relative to residual (small post_residual is good).
    let tightness = post_residual as f64 / bin_residual.max(1) as f64;
    score -= (1.0 - tightness) * 15.0;

    // Penalize residuals far below mean residual (creating unusable small pockets).
    if (post_residual as f64) < mean_residual {
        score += (mean_residual - post_residual as f64) * 0.30;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        // Prefer reusing bins early; allow new bins when many bins are open and mean residual is low.
        score += 40.0 - pressure * 1.5 + mean_residual * 0.25;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // new bin can host the larger upcoming item too
        }
    }

    // Mild stream-progression bias toward consolidation later in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.10;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward near-perfect fills
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Lookahead coupling: exact match of leftover with next item is gold
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            score -= (next_item_size as f64 / (post_residual as f64 + 1.0)) * 8.0;
        } else {
            // dead space relative to lookahead item
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Favor bins tighter than the fleet average
    score += (mean_residual - bin_residual as f64) * 0.25;

    // Slight reward for placing larger items early (preserve flexibility later)
    score -= (item_size as f64 / bin_capacity as f64) * 10.0 * (1.0 - progress);

    // New empty bin candidate: baseline that good existing fits must beat,
    // but wasteful placements (large post_residual) should not.
    if bin_residual == bin_capacity {
        score = 55.0 + progress * 15.0;
        if fitting_bins_count == 0 {
            score -= 40.0; // no open bin fits: new bin is clearly right
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits via smooth polynomial in post_residual
    let mut score = pr * (1.0 + 0.8 * pr_norm * pr_norm);

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, waste is more costly; early, allow looser fits
    let progress_coupling = (1.0 + 3.0 * progress * progress) * pr_norm * pr_norm * cap;
    score += 0.35 * progress_coupling;

    // Reward filling bins completely (smooth quadratic bonus near zero residual)
    score -= 8.0 * (-pr_norm * 8.0).exp();

    // Penalize bins with residual far from mean (fragmentation smoothing)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev * cap;

    // Last-chance bin: strong smooth reward
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - pr_norm);
    }

    // Lookahead: reward residual that can host next item (smooth kernel)
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let gap = (pr - next_item_size as f64) / cap;
        score -= 6.0 * (-gap * 20.0).exp();
    }

    // Mild penalty for spreading across many open bins late in stream
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common
    // item granularities (e.g. 10, 20, 25) are more reusable later.
    let pr = post_residual;
    let mut reusability_bonus = 0.0;
    if pr > 0 {
        if pr % 10 == 0 { reusability_bonus += 6.0; }
        if pr % 20 == 0 { reusability_bonus += 4.0; }
        if pr % 25 == 0 { reusability_bonus += 4.0; }
        if pr % 50 == 0 { reusability_bonus += 6.0; }
        // Small dead space is bad regardless of class
        if pr < 10 { reusability_bonus -= 12.0; }
    } else {
        // Perfect fit
        reusability_bonus += 25.0;
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (ni as u32) <= pr {
            // next item fits: reward proportionally to how well it fills
            let fill = ni / cap;
            reusability_bonus += 8.0 * fill;
            // exact modulo match with residual class is extra good
            if pr % next_item_size == 0 { reusability_bonus += 5.0; }
        } else {
            // next item cannot use this residual; penalize proportional overshoot
            let over = ((next_item_size - pr) as f64) / cap;
            reusability_bonus -= 6.0 * over;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        reusability_bonus += 15.0;
    }

    // Penalize spreading when many bins are open and mean residual is high:
    // prefer filling bins below mean residual (tighter bins).
    let res_frac = (bin_residual as f64) / cap;
    let mean_frac = mean_residual / cap;
    reusability_bonus -= 10.0 * (res_frac - mean_frac).abs().min(1.0);

    // Mild pressure to consolidate as stream progresses
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    reusability_bonus -= 5.0 * progress * res_frac;

    // New-bin candidate: make it unattractive unless residual is truly dead
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // only attractive if no open bin can take the item without waste,
        // approximated via fitting count and item size
        let waste_penalty = if fitting_bins_count <= 1 && item_size > bin_capacity / 2 { 0.0 } else { 40.0 };
        score += 30.0 + waste_penalty;
    }

    score - reusability_bonus
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (size 1) are fine, but gaps that can't fit the
    // lookahead item (or typical small items) are likely dead space.
    if post_residual > 0 {
        let unusable = (post_residual as f64) < 12.0;
        let lookahead_waste = next_item_size > 0 && post_residual < next_item_size
            && post_residual < 25;
        if unusable || lookahead_waste {
            score += 40.0 + 0.5 * post_residual as f64; // strong penalty for dead gap
        }
    }

    // Reward tight fits (low post_residual relative to item size).
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 15.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and encourage consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.05 + 0.15 * progress);
    if bin_residual == bin_capacity {
        // Candidate is a brand-new empty bin: penalize more as bins accumulate.
        score += 10.0 + pressure;
    } else {
        score -= pressure * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer bins whose residual is below the mean (consolidating fuller bins),
    // leaving large-residual bins for bigger future items.
    score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);
    score -= 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    // Lookahead synergy: if the next item exactly fits the post-residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.1 * (post_residual - next_item_size) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: this bin's post-residual exactly fits the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        if diff == 0.0 {
            score -= 60.0; // exact chain: place here strongly
        } else if diff <= 10.0 {
            score -= 40.0 * (1.0 - diff / 10.0);
        } else {
            // penalize wasted space the next item cannot use
            score += 0.35 * diff;
        }

        // If this bin cannot chain but another fit exists, mild penalty
        if pr < nxt {
            score += 8.0;
        }
    } else {
        // Last item: minimize residual tightly
        score += 0.5 * post_residual as f64;
    }

    // Prefer bins tighter than average residual (good fills)
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin when a decent existing fit exists
    if bin_residual == bin_capacity {
        let base = 30.0;
        let pressure = if next_item_size > 0 {
            (next_item_size as f64 / bin_capacity as f64) * 20.0
        } else {
            0.0
        };
        score += base + pressure - 0.2 * mean_residual;
        // Late in the stream, be more reluctant to open bins
        if total_items > 0 {
            score += 10.0 * (step_index as f64 / total_items as f64);
        }
    }

    // Discard tiny unusable remnants
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize leaving dead space that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let waste = (next_item_size - post_residual) as f64;
        score += 6.0 + 0.25 * waste;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that remain useful for the next item.
        score -= 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a brand-new empty bin when decent fits exist.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 10.0 + 3.0 * (fitting_bins_count as f64) };
        score += pressure + 0.05 * (open_bins_count as f64);
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 * progress;
        // If mean residual across open bins is large, opening a new bin wastes potential.
        score += 0.05 * mean_residual;
    } else {
        // Slight preference for bins whose residual is below average (balance residuals).
        let diff = bin_residual as f64 - mean_residual;
        score += 0.03 * diff;
    }

    // Reward exact fits overwhelmingly.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling: post_residual shaped by stream progress
    let shaping = norm_pr * norm_pr * (0.5 + 0.5 * progress) + norm_pr * (1.0 - progress) * 0.3;
    score += shaping * cap * 0.2;

    // Penalize residuals that cannot fit the lookahead item (smooth quadratic)
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        let gap = (next_item_size as f64 - pr) / cap;
        score += gap * gap * cap * (0.5 + 0.5 * progress);
    }
    // Reward residuals that fit the lookahead item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 2.0 + progress;
    }

    // Last-chance bonus: only one bin fits -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0 + 3.0 * progress;
    }
    // New-bin candidate: penalize mildly so open bins are preferred unless fit is bad
    if bin_residual == bin_capacity {
        score += 3.0 + 2.0 * (1.0 - progress);
    }

    // Coupling with mean residual: penalize bins far from mean waste
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * cap * 0.1;

    // Tight fit reward (quadratic in fill ratio)
    let fill = (bin_residual - post_residual) as f64 / cap;
    score -= fill * fill * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by residue mod 10 and by capacity fraction.
    let residue_class = (post_residual % 10) as f64;
    // Perfect-fit residues (multiples of 10) are highly reusable for common item sizes.
    let harmonic_bonus = if post_residual % 10 == 0 {
        -18.0
    } else {
        residue_class * 0.9 // dead space penalty grows with distance from a harmonic class
    };
    score += harmonic_bonus;

    // Capacity-fraction classes: residual in [0,10) is near-dead, [10,20) tight, etc.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.10 {
        score += 25.0; // nearly unusable residual
    } else if frac < 0.20 {
        score += 8.0;
    } else if frac >= 0.50 {
        score -= 6.0; // still versatile
    }

    // Integer-division threshold: can post_residual host next_item_size?
    if next_item_size > 0 {
        let fits_next = post_residual / next_item_size.max(1);
        if fits_next >= 1 {
            score -= 14.0 + 4.0 * (fits_next.min(3) as f64);
        } else {
            // next item cannot follow here; penalize more if next item is large (harmonic mismatch)
            let mismatch = (post_residual + bin_capacity / 2) as f64;
            score += 6.0 * (1.0 - (next_item_size as f64) / mismatch);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // prefer bins whose residual is tightest relative to mean residual
        score += (mean_residual - post_residual as f64) * 0.5;
    }

    // New-bin candidate handling: only prefer fresh bin early in stream or when many bins open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress + 1.5 * (open_bins_count as f64).ln().max(0.0);
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative
        }
    }

    // Slight preference to consolidate into fewer bins.
    score -= 0.4 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space strongly (non-linear).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 12.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor new bin
    // only when fit is poor.
    let bin_pressure = (open_bins_count as f64) * 0.5;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure, discounted when fit is tight.
        score += 30.0 + bin_pressure - (item_size as f64) * 0.3;
    } else {
        score -= bin_pressure * 0.3;
    }

    // Lookahead: if next item could use the post_residual, reward leaving it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins deviating favorably from the mean.
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Late-stream tightening: as stream progresses, penalize waste more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual == next_item_size is ideal.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (-gap / 10.0).exp();
        // Penalize leftovers that no plausible item (>=1) can use well.
        if post_residual > 0 {
            let waste = 1.0 / (post_residual as f64);
            score += 30.0 * waste;
        }
    } else {
        // Last item: minimize residual directly (already done via base).
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fit_quality = post_residual as f64 / cap;
        // A new empty bin has residual == capacity; make it attractive only if
        // the item leaves a large awkward remainder elsewhere or few bins open.
        score += 60.0 * (1.0 - fit_quality) * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 50.0; // next item needs a fresh bin anyway
        }
    }

    // Prefer bins whose residual is already below the mean (consolidating waste).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: the smaller the waste relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Penalize unusable dead space: residuals below the smallest plausible item
    // are almost certainly wasted, so push away from creating tiny fragments.
    if post_residual > 0 && post_residual < 12 {
        score += 40.0;
    } else if post_residual < 25 {
        score += 8.0;
    }

    // Lookahead coupling: reward if the next item fits exactly into the
    // post-residual (perfect chaining), penalize near-miss chains.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this residual; mild penalty for hogging space
            score += 3.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Time horizon: early in the stream, keep bins flexible (avoid fragmenting);
    // late in the stream, be aggressive about filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 15.0 * (item_size as f64 / bin_capacity as f64);

    // Global state coupling: when many bins are open and mean residual is high,
    // prefer consolidating into existing bins rather than opening new ones.
    if bin_residual != bin_capacity {
        score -= 0.15 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly
    // or the item is large enough that a fresh bin is genuinely useful.
    if bin_residual == bin_capacity {
        let base = 55.0;
        let pressure = if fitting_bins_count == 0 { 0.0 } else {
            (item_size as f64 / bin_capacity as f64) * 30.0
        };
        score = base + pressure - 20.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // fresh bin leaves room for the next item
        }
        if open_bins_count > 0 && mean_residual > item_size as f64 * 1.5 {
            score += 25.0; // existing bins have plenty of room; don't open new
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: f64, fitting_bins_count: usize) -> f64 {
