pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Favor residuals that are "harmonic" with common item sizes (divisible by 10/20)
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    if post_residual % 20 == 0 {
        score -= 6.0;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fit
    }

    // Penalize dead space: residuals below smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Fractional fill coupling
    let fill = 1.0 - pr / cap;
    score -= 10.0 * fill * fill;

    // Next-item lookahead: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // harmonic pairing: next item leaves a nice residual too
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 5.0;
            }
        } else {
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: keep it competitive only when existing fit is bad
    if bin_residual == bin_capacity {
        score += 30.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 20.0;
        }
    }

    // Stream progression: tighten packing later in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (pr / cap);

    // Mean residual alignment: prefer bins near the mean residual (balanced packing)
    score += 0.3 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward filling bins tightly relative to capacity.
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Penalize large post_residual that only a big future item could use.
    if next_item_size > 0 {
        if post_residual > 0 && (post_residual as u32) < next_item_size && (post_residual as u32) >= 10 {
            score += 25.0; // gap too small for the next item: likely dead space
        }
        if post_residual == next_item_size as u32 {
            score -= 20.0; // sets up a perfect fit for the lookahead item
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is tight.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let avg_gap = mean_residual / open_bins_count.max(1) as f64;
        score += 35.0 - avg_gap; // penalize new bin when open bins have room
        if fitting_bins_count <= 1 {
            score -= 50.0; // no good alternative: opening a new bin is fine
        }
    }

    // Mild preference for tighter-than-average fits.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fits (post_residual small).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness * (item_size as f64);

    // Aggressive 2-step lookahead: reward when next item fills this bin's post_residual.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (nr - post_residual as f64).abs() < 2.0 {
            score -= 25.0; // perfect chain: next item exactly fills leftover
        } else if next_item_size <= post_residual {
            // next item fits: penalize leftover slack after chaining
            let chain_left = post_residual as f64 - nr;
            score -= 10.0 * (1.0 - chain_left / bin_capacity as f64);
            score += 0.15 * chain_left; // but large chained leftover is waste
        } else {
            // next item cannot use leftover: penalize dead space
            score += 0.08 * (nr - post_residual as f64).min(60.0);
        }
    }

    // Relative-to-mean-residual term: prefer bins whose residual deviates
    // favorably from the fleet average (below mean => closer to full).
    score += 0.5 * ((post_residual as f64) - mean_residual);

    // Last-chance bin: heavily reward using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer opening a fresh bin only when the item is
    // large and no good fit exists; make empty-bin slightly less attractive
    // otherwise so tight fits win.
    if bin_residual == bin_capacity {
        score += 4.0 + 0.3 * (item_size as f64);
        if next_item_size > 0 && next_item_size <= post_residual - item_size {
            score -= 5.0; // fresh bin useful for lookahead chaining
        }
    }

    // Early stream: be more selective (favor consolidation); late stream: speed consolidation anyway.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: discourage spreading; prefer filling existing bins.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual relative to capacity).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (bin_capacity as f64 * 0.6);

    // Lookahead: if the next item exactly fills post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item uses the leftover
            let use_ratio = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * use_ratio;
        } else {
            // next item can't use leftover: penalize large dead space
            score += 0.1 * (post_residual as f64 - (bin_capacity as f64 - next_item_size as f64)).max(0.0);
        }
    }

    // Penalize opening a new bin when existing bins fit decently.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // worse to open new bin when many alternatives exist
            score += 15.0 + 5.0 * fitting_bins_count as f64;
            // but if all fitting bins would leave big waste, allow new bin sometimes
            let best_possible = (mean_residual - item_size as f64).max(0.0);
            if best_possible > 30.0 {
                score -= 10.0;
            }
        } else {
            score -= 5.0; // no alternative: new bin is fine
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Time horizon: early on, prefer compacting; late, prefer spreading to keep bins usable.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64 - mean_residual) * 0.2;

    // Mild penalty for leaving residuals that are small-but-unusable (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Slight preference for bins already below mean residual (consolidate emptier bins).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: penalize wasted residual, non-linearly (quadratic waste).
    let mut score = post * post / cap;

    // Smooth coupling of waste with stream progress: later in the stream,
    // waste becomes more costly (bins already sunk, prefer tight fits).
    let prog_coupling = 1.0 + 2.0 * progress * progress;
    score *= prog_coupling;

    // Reward leaving residual that can still host the next item (lookahead).
    if nxt > 0.0 {
        let usable = (post - nxt).max(0.0);
        let fit_prob = usable / cap;
        score -= 30.0 * fit_prob * (1.0 - progress * 0.5);
        // Exact-fit lookahead bonus (smooth, non-piecewise).
        let exact = 1.0 - ((post - nxt).abs() / cap);
        score -= 15.0 * exact * exact;
    }

    // Penalize opening/using bins when many alternatives fit (spread waste).
    let fit_norm = fitting_bins_count as f64 / (open_bins_count.max(1) as f64);
    score += 8.0 * (1.0 - fit_norm);

    // Last-chance bin: strongly reward using it (avoids opening a new bin).
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - post / cap);
    }

    // Mild penalty when this bin's residual deviates from mean residual
    // (keeps residual distribution homogeneous, eases future packing).
    let dev = (post - mean_residual).abs() / cap;
    score += 5.0 * dev * dev;

    // Slight preference for filling bins that are already low on space
    // (close them out rather than fragmenting fuller bins).
    score -= 10.0 * (item / cap) * (1.0 - bin_residual as f64 / cap);

    // New-bin candidate: make it mildly unattractive unless waste is huge.
    if bin_residual == bin_capacity {
        score += 20.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits; reward low post_residual strongly (quadratic).
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Harmonic class of post_residual: dead space depends on which capacity fraction band it lands in.
    // Residuals that are "useful" (>= 30, or exact small classes like 0) are favored.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
