        // modulo classes: residuals divisible by 10 pair well with typical item sizes
        if pr % 10 == 0 {
            score -= 8.0;
        }
        // dead zone: residuals 1..=9 are nearly unusable for items >= 10
        if pr < 10 {
            score += 45.0;
        }
        // capacity fraction bands
        let frac = pr as f64 / bin_capacity as f64;
        if frac < 0.2 {
            score += 18.0; // sliver
        } else if frac < 0.4 {
            score += 4.0;
        } else if frac < 0.7 {
            score -= 6.0; // sweet spot: fits medium items
        }
    }

    // Lookahead coupling: does post_residual accommodate next_item_size?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 14.0; // chains nicely
            // harmonic match: next item exactly fills remaining space
            if next_item_size == pr {
                score -= 25.0;
            } else if (pr - next_item_size) < 10 {
                score += 10.0; // chain creates sliver
            }
        } else {
            score += 6.0; // bin useless for next item
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when no good fit exists.
    if bin_residual == bin_capacity {
        // penalize opening a new bin, more when many bins fit the item or mean residual is high
        score += 55.0;
        score -= 1.2 * mean_residual;
        score += 3.0 * fitting_bins_count as f64;
        // early in stream, opening new bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Mild load balancing: prefer bins with residual below mean (denser bins)
    score += 0.08 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
