    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure from number of open bins: discourage opening/spreading when many bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bin count and mean residual.
        score += open_bins_count as f64 * 12.0 + mean_residual * 0.5;
        if next_item_size > 0 && bin_capacity >= next_item_size {
            score -= 5.0; // fresh bin is good for the next item
        }
    } else {
        score -= open_bins_count as f64 * 2.0;
    }

    // Slight late-stream conservatism: keep bins tighter as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near matches with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Perfect lookahead match bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: prefer tightest fit
        score -= 20.0;
    }

    // Relative to mean residual: prefer bins with below-average residual
    // (denser bins), which keeps loose bins for awkward future items.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Penalize large dead space that can't fit typical small items.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // nearly perfect fit
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when a reasonable fit exists among open bins,
    // unless the open-bin fit is very loose.
    if bin_residual == bin_capacity {
        score += 35.0;
        // But allow new bin if best alternative would leave huge waste
        if post_residual as f64 > mean_residual * 0.8 && next_item_size > 0 {
            score -= 45.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (waste-aware best-fit core).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 {
        let usable = (post_residual as f64 / 10.0).floor();
        score -= 1.5 * usable; // residual still useful for future items
    }

    // Lookahead coupling: bonus if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 4.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            score += 2.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when fits are abundant or residual is bloated.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let spread = (mean_residual - post_residual as f64).abs();
        // Penalize new bins more when few bins fit or mean residual is low (fits are good).
        score += 30.0
            + 8.0 * (fitting_bins_count as f64).max(1.0).ln()
            - 20.0 * (mean_residual / bin_capacity as f64)
            - 5.0 * progress
            - 3.0 * spread / bin_capacity as f64;
    }

    // Mild pressure to consolidate into fewer bins over time.
    score += 0.15 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Time-horizon modulation: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer minimal post_residual, with a smooth non-linear emphasis
    // (small residuals get disproportionately favored as the stream progresses).
    let mut score = post * (1.0 + 0.8 * progress * (1.0 - post / cap));

    // Non-linear penalty for leaving awkward dead space (near half-capacity waste).
    let waste = post / cap;
    score += 12.0 * waste * (1.0 - waste) * (waste - 0.5).abs();

    // Lookahead coupling: reward bins whose post_residual fits the next item,
    // penalize when the next item would be stranded.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let tightness = 1.0 - (post - nxt) / cap;
            score -= 6.0 * tightness * tightness;
        } else {
            score += 4.0 * ((nxt - post) / cap);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild penalty scaling with the number of open bins: discourage spreading
    // items across many bins when consolidation is possible.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening a new bin, more so early in the
        // stream and when existing residual capacity is plentiful.
        score += 10.0 + 0.5 * open_bins_count as f64 + (mean_residual / cap) * 8.0 * (1.0 - progress);
    } else {
        score += 0.05 * open_bins_count as f64;
    }

    // Smooth deviation term: bins far from the mean residual are slightly
    // deprioritized, keeping residual distribution coherent.
    score += 0.3 * (post - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: waste quality classes
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;

    // Penalize dead space that is too small to be useful (below min item size 1..100 unknown; use graded penalty)
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual <= 10 {
        score -= 25.0; // near-perfect, almost unusable residue anyway
    } else if post_residual <= 25 {
        score -= 5.0; // small but potentially fillable
    } else {
        // larger residues: penalize proportionally with a convex curve
        score += (post / cap_f) * (post / cap_f) * 40.0;
    }

    // Harmonic class: residue matching common item size bands (multiples of 10, 20, 25, 50)
    let harmonic_bonus = |r: u32| -> f64 {
        if r == 0 { return 30.0; }
        if r % 50 == 0 { return 24.0; }
        if r % 25 == 0 { return 18.0; }
        if r % 20 == 0 { return 15.0; }
        if r % 10 == 0 { return 10.0; }
        0.0
    };
    score -= harmonic_bonus(post_residual);

    // Lookahead coupling: reward residues that can host the next item exactly or well
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack.min(20.0); // reward next item fitting, less when slack large
        } else {
            // next item won't fit here; mild penalty scaled by how far off
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.15;
        }
        // harmonic alignment of next item with residual class
        if next_item_size % 10 == 0 && post_residual % 10 == 0 {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // multiple options: prefer tighter fits; post_residual already encodes that
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // New-bin candidate handling: opening a new bin is a fallback
    if bin_residual == bin_capacity {
        // new bin gets a base cost so it's only chosen when open bins fit poorly
        score += 55.0;
        // but if the item is large and would leave a nice harmonic residue, ease the cost
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
    }

    // Stream progression: late in the stream, avoid opening new bins, squeeze existing ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;
    if bin_residual != bin_capacity {
        score -= progress * 5.0;
    }

    // Mean residual context: if this bin's residual is far below mean, it's a tight fit -> favor
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // Open bins count pressure: many open bins -> prefer consolidating into existing ones
    if open_bins_count > 3 {
        score -= (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual >= 10 && post_residual < 25 {
        // Medium-small gaps: moderate penalty, worse if next item cannot use them.
        let usable = next_item_size > 0 && next_item_size <= post_residual;
        if !usable {
            score += 18.0;
        } else {
            score -= 6.0;
        }
    }

    // Reward leaving room for the lookahead item when it fits exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 25.0 - slack * 1.5;
        }
    }
    // Penalize if next item will NOT fit in this residual (dead end for lookahead).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 10.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer packing into existing ones
    // over the new-bin candidate (which has bin_residual == bin_capacity).
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64) * 2.0;
    } else {
        // New-bin candidate: penalize proportionally to how many bins are open.
        score += (open_bins_count as f64) * 5.0;
        // Early in stream, new bins are cheaper; late, they are expensive.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 20.0;
    }

    // Prefer bins with residual below mean (concentrate filling).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post residual exactly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // Strong reward for near-perfect two-item packing
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 40.0; // perfect 2-item fill
            }
        } else {
            // Next item cannot fit: penalize proportionally to wasted lookahead potential
            let shortfall = (next_item_size - post_residual) as f64;
            score += 0.15 * shortfall;
        }
    }

    // Penalize residuals that are too small to ever be useful (dead space)
    let min_useful = 10.0;
    if (post_residual as f64) < min_useful {
        score += 25.0;
    } else if (post_residual as f64) <= 20.0 {
        score += 8.0;
    }

    // Compare post_residual against mean residual: leaving above-average residual
    // is worse (bin becomes less balanced).
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize opening a new bin when open bins could reasonably fit
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count > 0 && next_item_size > 0 && next_item_size <= post_residual {
            // a new bin is still fine for lookahead pairing
            score -= 5.0;
        }
        // Later in the stream, prefer consolidating into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
    }

    // Mild tie-break: prefer fuller bins (smaller residual) among open bins
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let res = bin_residual as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer minimal post residual, but with diminishing returns
    let mut score = post.sqrt() * 3.0;

    // Penalize dead space relative to smallest plausible future item
    let dead_zone = post - 1.0;
    if dead_zone > 0.0 {
        score += (dead_zone / cap).powi(3) * 40.0;
    }

    // Lookahead: reward if next item fits exactly into post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if post >= nxt {
            // next item fits: strong reward scaled by tightness
            score -= (1.0 - gap / cap) * 25.0;
        } else {
            // next item won't fit: mild penalty for wasting a big residual
            score += (gap / cap) * 6.0;
        }
        // perfect chain: item + next == residual
        if (item + nxt - res).abs() < 0.5 {
            score -= 30.0;
        }
    } else {
        // last item: greedily fill as much as possible
        score -= (item / res.max(1.0)) * 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Crowding: many open bins -> prefer consolidating into fuller bins
    let crowding = (open_bins_count as f64 / (1.0 + total_items as f64 * 0.05)).min(2.0);
    score += crowding * (post / cap) * 8.0;

    // Global residual alignment: prefer bins whose post residual sits near mean residual
    // (keeps residuals homogeneous, improving future pairing)
    let mean_dev = (post - mean_residual).abs();
    score += (mean_dev / cap) * 10.0;

    // Time horizon: early in stream, be picky about tight fits; late, be greedy
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= t * (1.0 - post / cap) * 12.0;
    score += (1.0 - t) * (post / cap) * 5.0;

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let escape_pressure = if fitting_bins_count == 0 { 20.0 } else { 0.0 };
        score += 18.0 - escape_pressure + t * 6.0;
    }

    // Small tie-breaker favoring fuller bins
    score -= (item / res.max(1.0)) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64 / bin_capacity as f64;
    let poly = pr * pr * (0.5 + 1.5 * progress) + pr * (1.0 - progress);
    score += 20.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tight = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * tight * tight * (0.5 + progress);

    // Penalize creating dead space that cannot fit the lookahead item
    if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 && post_residual > 0 {
        score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64) * (0.5 + progress);
    }
    // Reward leaving room for the lookahead item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0 * (0.5 + progress);
    }

    // Mild penalty for spreading across many open bins
    score += 0.3 * open_bins_count as f64 * pr;

    // New-bin candidate: keep it neutral-slightly-high unless current fit is poor
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * (1.0 - tight) * (1.0 - progress);
    }

    // Coupling with mean residual: prefer bins near the mean fill
    let dev = (bin_residual as f64 - mean_residual).abs() / bin_capacity as f64;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap; // 0..1

    // Penalize leftover space in coarse harmonic bands (waste grows superlinearly)
    if post_residual == 0 {
        score -= 60.0; // perfect fit: strongly reward
    } else {
        // harmonic band index: 1/8, 1/4, 1/2, full
        let band = if frac <= 0.125 { 0 }
                   else if frac <= 0.25 { 1 }
                   else if frac <= 0.5 { 2 }
                   else { 3 };
        score += band as f64 * 12.0;

        // Modulo arithmetic on post_residual: leftovers divisible by common item classes
        // (10/20/40/80 style classes) are more reusable
        let pr = post_residual;
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
        if pr % 50 == 0 { score -= 3.0; }
        // dead zone: unusable slivers below typical minimum item size
        if pr < 10 { score += 25.0; }
    }

    // Lookahead coupling: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0; // chain-friendly placement
            // exact harmonic match bonus
            if next_item_size == post_residual { score -= 10.0; }
            if post_residual % next_item_size == 0 && next_item_size > 0 { score -= 4.0; }
        } else {
            score += 5.0; // next item won't reuse this bin
        }
    }

    // Last chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad
    if bin_residual == bin_capacity {
        score += 18.0;
        // early in stream, prefer filling existing bins more
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // if many open bins with high mean residual, discourage new bins
        score += 0.05 * open_bins_count as f64;
        if mean_residual > 0.5 * cap { score += 8.0; }
    }

    // Tight fit reward: residual barely exceeded item
    let tight = (bin_residual as f64 - item_size as f64) / cap;
    score -= 20.0 * (1.0 - tight).max(0.0).min(1.0);

    // Mild preference for bins with lower-than-mean residual (keep big holes open)
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

