        // Coupling with mean residual: prefer bins whose residual tracks the mean,
        // unless lookahead says otherwise.
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 0.3;
    }

    // Last-chance bin: if this is the only fitting bin, force usage to avoid new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 500.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current bin would leave a large, unusable residual and next item is large.
    if bin_residual == bin_capacity {
        // Baseline attractiveness of fresh bin: its post_residual is large.
        // Make it slightly worse than a good chain but better than dead space.
        score += 5.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            // Fresh bin can chain too; keep it competitive but prefer filling existing bins.
            score += 20.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more than linearly.
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 8.0 * tight * tight;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead: if next item fits in post_residual, reward; else penalize large leftover.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 15.0;
        } else {
            let waste = post_residual as f64 / cap;
            score += 10.0 * waste * waste;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when open bins could fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0 + 5.0 * (open_bins_count as f64).sqrt();
        } else {
            score -= 10.0;
        }
        // Early in stream, opening new bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer bins with residual far from mean residual (diversity of leftover sizes).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 2.0 * dev / cap;

    // Prefer using bins with less residual among fitting bins (fill fuller bins first).
    score += 0.05 * bin_residual as f64;

    // Mild penalty for too many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: penalize large post-residual, with non-linear (quadratic/cubic) coupling
    let mut score = pr * (1.0 + 0.8 * prn * prn);

    // Stream-progress coupling: later in the stream, waste matters more (convex growth)
    score += 30.0 * prn * prn * (progress * progress);

    // Dead-space term: post-residual too small for smallest plausible item is dead space
    // smooth sigmoid-like penalty centered around tiny residuals
    let dead = 1.0 - 1.0 / (1.0 + (-pr as f64 / 5.0).exp());
    score += 25.0 * dead;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits the post-residual smoothly
    if next_item_size > 0 {
        let fits_next = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        let tight = 1.0 - (fits_next / cap).min(1.0);
        score -= 15.0 * tight * (1.0 - progress * 0.5);
    }

    // Mild penalty for spreading across many open bins; smooth in open_bins_count
    score += 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins below mean residual slightly (consolidation), smooth term
    score += 5.0 * ((bin_residual as f64 - mean_residual) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how it decomposes modulo common item-size bands
    let pr = post_residual;
    let cap = bin_capacity as f64;
    let fill = 1.0 - (post_residual as f64) / cap;

    // Reward high fill ratio
    score -= 45.0 * fill * fill;

    // Perfect / near-perfect fits
    if pr == 0 {
        score -= 1000.0;
    } else if pr <= 3 {
        score -= 300.0;
    } else if pr <= 10 {
        score -= 60.0;
    }

    // Harmonic classes: residuals in {0, 20, 25, 33, 50} style divisions are reusable
    let classes: [u32; 8] = [1, 2, 4, 5, 10, 20, 25, 50];
    for c in classes.iter() {
        if pr % c == 0 && pr > 0 && pr <= 50 {
            score -= 12.0;
            break;
        }
    }

    // Penalize dead space: residual too small for typical items (1..100 unknown, assume >=10-ish useful)
    if pr > 0 && pr < 10 {
        score += 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size < pr {
            score -= 25.0 * (1.0 - (pr - next_item_size) as f64 / cap);
        } else {
            // next item won't fit here: residual likely wasted
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let crowded = mean_residual < 25.0 && open_bins_count > 0;
        if crowded {
            score -= 30.0;
        } else {
            score += 55.0 + 5.0 * open_bins_count as f64;
        }
    }

    // Prefer bins with residual below mean (tighter bins first)
    score += 0.35 * (bin_residual as f64 - mean_residual);

    // Mild pressure to consolidate as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fill;

    // Modulo threshold on post_residual vs capacity quarters
    let quarter = bin_capacity / 4;
    if pr > 0 && pr % quarter == 0 {
        score -= 18.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize medium dead space less harshly, scaled by how far the stream has progressed.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual >= 10 && post_residual < 25 {
        score += 20.0 + 15.0 * progress;
    }

    // Reward tight fits (post_residual near 0 or exactly usable).
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize placements into bins when many bins are open,
    // encouraging consolidation; but new-bin candidate gets a mild base offset.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64;
    } else {
        score -= 0.3 * open_bins_count as f64;
    }

    // Lookahead coupling: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item almost fits (within small gap), mild reward.
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        score -= 5.0;
    }
    // Penalize if placement leaves a gap that next item cannot use at all
    // while the gap is small (dead space for the near future).
    if next_item_size > post_residual && post_residual > 0 && post_residual < 20 {
        score += 10.0;
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably
    // from the mean (i.e., placing here reduces spread / uses a laggard bin).
    let dev = mean_residual - post_residual as f64;
    score += 0.1 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: bin closes exactly if item + next item fill it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item fits tightly after placement (small leftover chain).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: dead space penalty scaled by tightness now.
        score += 0.5 * post_residual as f64;
    }

    // Penalize creating unusable dead space (< min item size 1..=10).
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Prefer bins with residuals below mean (consolidate space).
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 500.0;
    }

    // New-bin candidate: only attractive when current bin fits poorly.
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 1.0 };
        score += 250.0 - 400.0 * poor_fit;
        if fitting_bins_count <= 1 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 30.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 40.0;
    }

    // Penalize dead space that no future item (min size 1) can use mildly,
    // but items up to 80 mean small residuals are often unusable
    if post_residual > 0 && post_residual < 20 {
        score += 25.0; // likely dead space
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits in post_residual, big bonus
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 35.0 + (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // penalize wasting space next item can't use
            score += 10.0;
        }
        // if next item fits exactly, extra bonus
        if next_item_size == post_residual {
            score -= 30.0;
        }
    }

    // New-bin candidate logic: prefer opening a new bin only when
    // existing fit is bad or item is large
    if bin_residual == bin_capacity {
        let is_poor_fit = post_residual as f64 > mean_residual;
        let late = step_index as f64 / (total_items.max(1) as f64);
        if item_size >= 50 {
            score -= 20.0; // large items fine in fresh bins
        }
        if is_poor_fit {
            score -= 15.0;
        } else {
            score += 40.0; // keep good fits in existing bins
        }
        if open_bins_count == 0 {
            score -= 1000.0; // must open
        }
        // slight preference for consolidating late in stream
        score += late * 10.0;
    }

    // Prefer bins with residuals close to item (best-fit flavor)
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.3;

    // Prefer bins below mean residual (more filled bins) mildly
    score += (bin_residual as f64 - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_norm = post / cap; // 0 = perfect fit

    // Reward tight fits more strongly as the stream progresses (smooth coupling).
    let tightness = (1.0 - fit_norm).powi(3);
    score -= 14.0 * tightness * (0.5 + progress);

    // Penalize dead space non-linearly: residuals that no typical item can use.
    let dead = (fit_norm * fit_norm) * cap;
    score += 0.35 * dead * (1.0 - 0.5 * progress);

    // Lookahead: reward if next item exactly fills post_residual; penalize near-miss waste.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let gap = post - nx;
            let gap_norm = gap / cap;
            score -= 20.0 * (1.0 - gap_norm).powi(2) * (0.6 + 0.4 * progress);
        } else {
            let over = (nx - post) / cap;
            score += 6.0 * over * (1.0 - fit_norm);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0 + 8.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64 * fit_norm;

    // Prefer bins whose residual is far from the mean (deviation coupling).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 2.0 * dev * (1.0 - tightness);

    // New-bin candidate: keep it slightly worse than a decent fit, but competitive
    // when all open fits would leave large dead space.
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * (1.0 - item_size as f64 / cap) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "reusable" the leftover is.
    // Class 0: residual divisible by 10 (aligns with typical item granularity)
    let pr = post_residual as u32;
    let class10 = (pr % 10 == 0) as i32;
    let class5 = (pr % 5 == 0) as i32;
    score -= 6.0 * class10 as f64;
    score -= 2.5 * class5 as f64;

    // Dead-space penalty: tiny unusable leftover
    if pr > 0 && pr < 10 {
        score += 14.0;
    } else if pr == 0 {
        score -= 18.0; // perfect fit
    }

    // Lookahead coupling: does post_residual still fit next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // reward proportional to tightness of that future fit
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 - slack.min(10.0) * 0.5;
            // harmonic bonus if future fit leaves divisible residual again
            let npr = post_residual - next_item_size;
            if npr % 10 == 0 { score -= 4.0; }
        } else {
            score += 5.0; // leftover can't host next item
        }
    } else {
        // last item: prefer tightest packing
        score += 0.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64 - 2.0).min(4.0);
    }

    // New-bin candidate handling: empty bin should only win for large items
    // or when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fill = item_size as f64 / cap;
        // penalize new bin unless item is large; slightly relax late in stream
        score += 26.0 - 18.0 * fill - 6.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Prefer filling bins with small residuals (consolidate)
    let res_frac = bin_residual as f64 / cap;
    score += 3.0 * (1.0 - res_frac);

    // Mild preference to keep mean residual balanced
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: the smaller the post_residual, the better.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Dead-space penalty: residuals too small to be useful later are heavily penalized.
    // Anything in (0, 10] is a "wasted" gap since min item size is 1 but small gaps
    // rarely match future items; treat 1..=9 as dead zone.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.2;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; mildly penalize leaving a bin that will be abandoned.
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening a new one;
    // this makes the new-bin candidate (bin_residual == bin_capacity) less attractive.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 3.0;
        // But if no existing bin fits well (this call happens for the new bin anyway,
        // pressure above handles it). Slight discount late in the stream is unnecessary.
    }

    // Prefer bins whose residual is close to the mean residual (balance load),
    // mildly, to keep a portfolio of usable gaps.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Progress-based mild scaling: early on, be slightly more willing to open bins
    // (keeps options open); later, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact fit (zero waste).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: perfect match with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if post_residual >= next_item_size {
            // Reward when the next item can also fit here.
            let lookahead_waste = (post_residual - next_item_size) as f64;
            score -= 300.0 - lookahead_waste * 0.5;
        } else {
            // Next item cannot follow into this residual; penalize proportionally.
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 0.8;
        }
    }

    // Dead-space penalty: small nonzero residuals are hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Prefer bins with residuals below the mean (tighter bins first),
    // keeping looser bins available for larger future items.
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fits are bad.
    if bin_residual == bin_capacity {
        let base = 120.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += base + progress * 40.0;
        // Discourage new bins when many bins are already open and usable.
        score += open_bins_count as f64 * 5.0;
    }

    // Mild preference to consolidate into fewer open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness * (item_size as f64 / bin_capacity as f64);

    // Penalize dead space: post_residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for wasting capacity.
            score += 2.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins have poor fits or many bins are saturated.
    if bin_residual == bin_capacity {
        let poor_fit_pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let residual_pressure = (mean_residual / bin_capacity as f64).min(1.0);
        let crowding = (open_bins_count as f64 / (open_bins_count as f64 + 4.0)).min(1.0);
        let default_penalty = 30.0 - 25.0 * poor_fit_pressure - 20.0 * residual_pressure - 10.0 * crowding;
        score += default_penalty.max(0.0);
    }

    // Time horizon: early in stream, prefer consolidation; late, tolerate fragmentation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64);
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild bonus for filling bins with large residual imbalance vs mean.
    score += 1.5 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;
    let mut score = pr as f64;
    // smooth non-linear coupling of post_residual with stream progress
    score += 6.0 * norm_post * norm_post * (0.5 + 0.5 * progress);
    score -= 4.0 * (1.0 - norm_post) * (1.0 - norm_post) * (1.0 - progress);
    // penalize dead space relative to mean residual
    let mr = if mean_residual.is_finite() { mean_residual } else { cap };
    score += 0.05 * (pr as f64 - mr) * (pr as f64 - mr) / cap;
    // lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 3.0 * (1.0 - (pr - ni) / cap);
        } else {
            score += 2.0 * (ni - pr) / cap;
        }
    }
    // last-chance bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 5.0;
    }
    // mildly discourage opening new bins early
    if bin_residual == bin_capacity {
        score += 3.0 * (1.0 - progress) + 0.2 * open_bins_count as f64;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (class 0) heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 80.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    } else {
        // Penalize dead space non-linearly; small residuals are reusable by small items.
        let frac = post_residual as f64 / cap;
        score += frac * frac * 120.0;
    }

    // Reward if next item fits exactly into post_residual (chained tight fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 250.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 60.0 * (1.0 - slack as f64 / cap);
        } else {
            // Next item cannot use this residual: penalize proportional waste.
            score += 20.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let base = 60.0 + 0.5 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 400.0; // forced new bin
        } else if post_residual >= 40 {
            score += base; // plenty of good fits exist; discourage new bin
        } else {
            score += base * 0.25;
        }
    }

    // Prefer filling bins with large residuals early (keep small-residual bins flexible).
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Mild stream-position coupling: later in stream, favor tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 25.0 * progress * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0 * (11.0 - post_residual as f64); // tiny gap = wasted capacity
        } else if post_residual < 20 {
            score += 25.0; // still likely dead space for min-size items
        }
    } else {
        score -= 40.0; // perfect fit is ideal
    }

    // Reward tight fits relative to the item size (fill ratio).
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Pressure from number of open bins: prefer consolidating into existing bins
    // when many bins are open; allow spreading when few are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 3.0 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // chain of perfect fits
        } else if next_item_size > post_residual {
            score += 8.0; // next item won't fit here anyway; dead space more likely
        } else if post_residual - next_item_size <= 10 {
            score += 12.0; // would create dead space after next item
        }
    }

    // New-bin candidate handling: only attractive when current bins fit poorly
    // or would leave dead space; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        score += 15.0 + 5.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: new bin is fine
        } else if post_residual >= item_size {
            // an existing bin could take this item twice; discourage new bin mildly
            score -= 5.0;
        }
    }

    // Mild preference for bins with residuals close to the item (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.15;

    // Mean residual coupling: when mean residual is high, prefer using the bin
    // that reduces dispersion (closest residual to item).
    score -= 0.05 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward exact-ish fits (small post_residual) superlinearly.
    let pr = post_residual as f64;
    score += 0.15 * (pr * pr) / bin_capacity as f64;

    // Aggressive 2-step lookahead: strongly reward a perfect chain match
    // (next item exactly fills the post-residual).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt).abs();
        if diff < 0.5 {
            score -= 60.0; // perfect 2-step chain: place here
        } else if diff <= 5.0 {
            score -= 30.0 - 4.0 * diff;
        } else {
            // Penalize leaving residual that no plausible next item can use
            score += 0.25 * diff;
        }
    } else {
        // Last item: residual left is pure waste; minimize it hard.
        score += 0.8 * pr;
    }

    // Relative-to-mean residual: prefer bins that are tighter than average
    // (concentrate filling), penalize bins looser than average.
    let resid = bin_residual as f64;
    score += 0.10 * (resid - mean_residual);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity or no good fit exists. Penalize opening a new bin for small
    // items / early stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let mut new_bin_penalty = 18.0 * fill_ratio + 10.0 * (1.0 - progress);
        // If many open bins could fit, discourage opening a new one.
        if fitting_bins_count > 1 {
            new_bin_penalty += 12.0;
        }
        // If item nearly fills a fresh bin, opening is fine.
        new_bin_penalty -= 20.0 * (fill_ratio - 0.5).max(0.0);
        score += new_bin_penalty.max(-8.0);
    }

    // Mild preference to keep number of open bins low when stream is late.
    score += 0.02 * open_bins_count as f64 * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream completed (dynamic time horizon).
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: strong bonus for small post_residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: penalize leaving residuals that cannot host the next item (dead space),
    // but only mildly early in the stream when flexibility still matters.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            // Dead space: unusable for the next item.
            let dead = post_residual as f64;
            score += 6.0 * (dead / bin_capacity as f64) * (0.5 + 0.5 * t);
        } else {
            // Residual usable by next item: reward, scaled by how snugly next item fits.
            let snug = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 4.0 * snug * (1.0 - t);
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin, softened when many bins are open or stream is late.
        score += 10.0 + 8.0 * (1.0 - t);
        // If no open bin fits besides this candidate, opening is less bad.
        if fitting_bins_count <= 1 {
            score -= 12.0;
        }
        // When mean residual is small (open bins nearly full), new bin is reasonable.
        score -= 0.05 * mean_residual;
    } else {
        // Reusing an existing bin is generally good; slight extra reward late in stream.
        score -= 2.0 + 2.0 * t;
        // Prefer bins with residual close to the item (best-fit flavor).
        score += 0.02 * (bin_residual as f64 - item_size as f64).abs();
    }

    // Mild preference for consolidating when many bins are open.
    score += 0.05 * open_bins_count as f64 * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling: residual penalty grows super-linearly with progress
    let poly = pr_norm * pr_norm * (1.0 + 2.0 * progress) + pr_norm * progress * progress;
    score += 6.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - pr_norm;
    score -= 8.0 * tightness * tightness * (0.5 + progress);

    // Penalize bins far from mean residual (encourage homogeneity)
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - pr_norm);
    }

    // Lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni > pr {
            score += 4.0 * (ni - pr) / cap * (1.0 + progress);
        } else {
            score -= 3.0 * (pr - ni) / cap;
        }
    }

    // Mild penalty for proliferating open bins late in stream
    score += (open_bins_count as f64).ln() * (1.0 + 2.0 * progress);

    // New-bin candidate: neutral-ish baseline, slightly favored early, penalized late
    if bin_residual == bin_capacity {
        score += 2.0 - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // ---- Tight-fit reward: exact fill is perfect ----
    if post_residual == 0 {
        score -= 1000.0;
    }

    // ---- Harmonic class logic on post_residual ----
    // Classify residual into usable classes: items are >=1, but common small
    // items are <=20. A residual that cannot hold a "small" item (say <10)
    // is nearly dead space -> penalize; a residual that is a multiple of
    // likely item sizes (10/20/25/50) is reusable -> reward.
    let pr = post_residual;
    if pr > 0 {
        // Dead-space penalty: residual too small for any plausible item
        if pr < 10 {
            score += 25.0 + (10 - pr) as f64 * 2.0;
        }
        // Harmonic divisibility rewards: residuals divisible by common
        // item denominators can be exactly filled later.
        if pr % 50 == 0 { score -= 18.0; }
        if pr % 25 == 0 { score -= 12.0; }
        if pr % 20 == 0 { score -= 10.0; }
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 5 == 0 { score -= 3.0; }

        // Lookahead coupling: if the next item fits exactly in the
        // post-residual, this is a perfect two-item chain.
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 60.0;
            } else if next_item_size <= pr {
                // Next item fits; reward proportional to resulting tightness.
                let post2 = pr - next_item_size;
                if post2 < 10 { score -= 15.0; }
                score -= 10.0;
            } else {
                // Next item will NOT fit here: this bin becomes dead space
                // for the next step; penalize proportionally to leftover.
                score += (pr.min(next_item_size) as f64) * 0.15;
                if pr < next_item_size && pr < 20 {
                    score += 12.0;
                }
            }
        }
    }

    // ---- Last-chance logic: if this is the only fitting bin, strongly
    // prefer using it over opening a new bin (unless fit is terrible). ----
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
        if post_residual < 10 {
            score -= 10.0; // still better to consume the dead space here
        }
    }
    // If several bins fit, mild bonus for consolidating into fewer bins.
    if fitting_bins_count > 2 && !is_new_bin {
        score -= 2.0;
    }

    // ---- New-bin candidate handling ----
    if is_new_bin {
        // Opening a new bin is expensive; discourage unless the fit in any
        // open bin would leave large unusable residue. Base penalty grows
        // with how many bins already exist (amortize opening cost).
        score += 45.0 + (open_bins_count as f64).sqrt() * 5.0;
        // But if the item is large (>= 50), placing it fresh keeps big
        // residual flexibility in other bins; soften penalty.
        if item_size >= 50 {
            score -= 20.0;
        }
        // If no other bin fits well (this would be last chance anyway),
        // opening new bin is fine.
        if fitting_bins_count == 0 {
            score -= 40.0;
        } else if fitting_bins_count == 1 {
            // Only one open bin fits; if that fit would be very tight
            // (small post-residual handled by that bin's own score), keep
            // new-bin moderately expensive; if the single fit leaves a big
            // awkward residual, allow the new bin.
            score -= 10.0;
        }
        // Lookahead: if next item is large, keep current bins' space free.
        if next_item_size >= 60 {
            score -= 15.0;
        }
    } else {
        // ---- Fragmentation guard for open bins: prefer bins whose current
        // residual was already small (waste little of a big residual). ----
        let waste = bin_residual as f64 - item_size as f64; // == post_residual
        let waste_ratio = waste / bin_capacity as f64;
        score += waste_ratio * 20.0;

        // Prefer filling bins with the smallest residuals among fitting
        // bins (best-fit reinforcement), scaled by stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 5.0;

        // Coupling with mean residual: if this bin's residual is far below
        // the mean, it's the "cramped" bin — good to fill it now.
        let bin_res_f = bin_residual as f64;
        if mean_residual > 0.0 && bin_res_f < mean_residual {
            score -= (mean_residual - bin_res_f) * 0.3;
        } else {
            score += (bin_res_f - mean_residual) * 0.1;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect packing.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Lookahead: if the next item can still fit here, this bin is valuable.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += 8.0; // this bin becomes dead space for the next item
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins,
    // but mildly encourage using existing bins when many are already open.
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64) * 1.5;
    } else {
        // New-bin candidate: penalize opening a bin when open bins exist,
        // scaled by how much residual capacity is being stranded.
        score += (open_bins_count as f64) * 0.8 + mean_residual * 0.1;
    }

    // Progress coupling: as the stream advances, tighten dead-space tolerance.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.15;

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: next item exactly fills the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits too: reward tightness of the pair.
            let pair_waste = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - pair_waste / bin_capacity as f64);
        } else {
            // Next item cannot follow: penalize dead space left behind.
            let dead = next_item_size - post_residual;
            score += dead as f64 * 0.35;
        }

        // If next item fits perfectly in the current residual instead, discourage
        // disturbing that chain (this bin placement would break a 1-step match).
        if bin_residual == next_item_size {
            score += 40.0;
        }
    } else {
        // Last item: just minimize leftover.
        score += 10.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer bins that are tighter than average (fill nearly-full bins first).
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Mild penalty for spreading across too many open bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 0.05;

    // Never favor a new empty bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 15.0 + post_residual as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        } else {
            // Reward residual that exactly accommodates the lookahead item
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 25.0;
            } else {
                score += gap as f64 * 0.15;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize spreading across many open bins
    score += open_bins_count as f64 * 0.5;

    // Encourage filling bins with large residuals when mean residual is high
    if bin_residual as f64 > mean_residual {
        score -= (bin_residual as f64 - mean_residual) * 0.3;
    } else {
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    // Time horizon: early in stream, prefer consolidation; late, prefer any fit
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * tightness;

    // New-bin candidate: slightly penalize so we prefer existing bins unless fit is poor
    if bin_residual == bin_capacity {
        score += 12.0 + 25.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: wasted space after placement, normalized
    let mut score = pr / cap;

    // Smooth non-linear waste penalty: dead space hurts quadratically
    score += (pr / cap).powi(2) * 2.0;

    // Perfect-fit reward (cubic falloff around zero residual)
    score -= (1.0 - pr / cap).powi(3) * 1.5;

    // Stream-progress coupling: early on, prefer tight fits less aggressively
    // (keep bins flexible); later, squeeze hard.
    let tightness = item_size as f64 / cap;
    score += (1.0 - progress) * tightness * (1.0 - tightness) * 0.8;

    // Lookahead coupling: if next item fits into post_residual, reward strongly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fill = nx / cap;
            score -= 1.2 * fill * (1.0 + progress);
        } else {
            // next item won't fit: penalize proportionally to overflow gap
            let gap = (nx - pr) / cap;
            score += 0.6 * gap * gap;
        }
    }

    // Last-chance bonus: only one bin fits, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 0.9;
    }

    // Mean-residual coupling: if this bin is far from mean residual, mild penalty
    let dev = (pr as f64 - mean_residual) / cap;
    score += 0.15 * dev * dev;

    // Many open bins: slight pressure to fill existing bins rather than open new
    score += (open_bins_count as f64).ln().max(0.0) * 0.05 * (pr / cap);

    // New-bin candidate: keep neutral baseline so it wins only when open bins are bad
    if bin_residual == bin_capacity {
        score += 0.3 + 0.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: quantize post_residual into capacity-fraction classes.
    // Items 1..100, capacity 100. Class boundaries at multiples of 25 (quarters).
    let class_size: u32 = bin_capacity / 4;
    let post_class = post_residual / class_size;
    let exact = post_residual % class_size;

    // Reward placements landing exactly on a class boundary (clean partition).
    if exact == 0 && post_residual > 0 {
        score -= 12.0;
    }
    // Penalize very small dead space that nothing (min size 1) can still use well:
    // dead space in (0, 10) is near-waste; in [10, 25) it may still hold a small item.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    } else if post_residual >= 10 && post_residual < class_size {
        score += 6.0;
    }

    // Lookahead coupling: reward if next item fits the post residual exactly
    // or within the same harmonic class.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let nxt_class = next_item_size / class_size;
            // reward when next item's class matches remaining class structure
            score -= 8.0 + (nxt_class as f64) * 2.0;
            // penalize leaving a sliver the next item cannot use
            if post_residual - next_item_size < 10 {
                score += 10.0;
            }
        } else {
            // next item won't fit here; mild penalty unless this is a closing bin
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // with many options, prefer tighter fills (post_residual already does this)
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // are badly fragmented (high mean residual spread) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // base cost of opening a bin, reduced if many open bins are fragmented
        let fragmentation = (mean_residual - (bin_capacity as f64 - item_size as f64)).abs();
        let mut new_bin_score = 45.0 - fragmentation * 0.5 - progress * 15.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            new_bin_score -= 10.0;
        }
        // never open a new bin when a perfect fit exists elsewhere is handled by
        // the -25/-12 bonuses above; ensure empty bin isn't trivially best
        score = new_bin_score.max(5.0);
        return score;
    }

    // Tight-fit reward: near-exhausting a bin is excellent.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Mild global pressure: keep scores comparable across bins.
    score += mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Core: penalize post_residual, with extra harsh penalty for small unusable gaps
    let mut dead_weight = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        // Gap too small for the minimum item: pure dead space
        dead_weight += 50.0;
    } else if post_residual > 0 && post_residual < 20 {
        dead_weight += 15.0;
    }

    // Tight fit reward: residual nearly consumed
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.9 {
        dead_weight -= 20.0;
    } else if fill_ratio > 0.7 {
        dead_weight -= 8.0;
    }

    score += dead_weight;

    // Perfect fit: residual exactly zero
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins have poor fit
    if bin_residual == bin_capacity {
        let mut new_bin_score = 25.0;
        // If open bins have lots of residual, opening new bin is wasteful
        new_bin_score += mean_residual * 0.3;
        // Early stream: allow more bins; late stream: discourage
        let progress = step_index as f64 / total_items as f64;
        new_bin_score *= 1.0 + progress * 1.5;
        // Pressure from many open bins
        new_bin_score += open_bins_count as f64 * 2.0;
        // If next item is large, a fresh bin may be valuable
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            new_bin_score -= 10.0;
        }
        score += new_bin_score;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= 5.0;
        } else {
            // next item cannot use this bin's leftover; slight penalty for leaving gap
            score += post_residual as f64 * 0.05;
        }
    }

    // Open bins pressure: mildly discourage spreading across many bins
    score += open_bins_count as f64 * 0.5;

    // Prefer bins whose residual is close to item size (best-fit core)
    score += (bin_residual as f64 - item_size as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to tightness of the chain.
            let chain_tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 100.0 * chain_tightness;
        } else {
            // Next item will NOT fit here: penalize leaving a residual that is
            // too small for the lookahead item (dead space risk).
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
        }
    }

    // Penalize residual far from mean residual when creating isolated small gaps.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.2 * dev;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: make opening a fresh bin moderately expensive, so it is
    // chosen only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 80.0;
        // If the item fills a new bin substantially, opening is less bad.
        let fill = item_size as f64 / bin_capacity as f64;
        score -= 60.0 * fill;
    }

    // Late in the stream, tighten packing (less tolerance for wasted space).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fit.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness * tightness);

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: reward residuals that can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 12.0 / (1.0 + gap);
        } else {
            // next item won't fit here; slight penalty for wasting capacity
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.8 * (0.5 + progress);

    // Prefer bins with below-mean residual (fill the emptier ones first when tight).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit = tightness > 0.6 || fitting_bins_count == 0;
        if poor_fit {
            score -= 15.0;
        } else {
            score += 35.0; // discourage opening new bin when decent fit exists
        }
    }

    // Time horizon: late in stream, be more aggressive about closing bins tightly.
    score -= 10.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, non-linearly penalized
    let mut score = pr * pr / cap;

    // Smooth polynomial coupling of post-residual with stream progress:
    // early on, tolerate larger leftovers; late, penalize them heavily.
    let prog_poly = 0.5 + 2.5 * progress * progress + 1.5 * progress * progress * progress;
    score += norm_pr * norm_pr * cap * prog_poly;

    // Perfect fit reward, stronger as stream progresses
    if post_residual == 0 {
        score -= 40.0 + 60.0 * progress;
    } else if post_residual < 10 {
        score -= 15.0 + 20.0 * progress;
    }

    // Dead space: residual too small for any plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + 25.0 * progress;
    }

    // Lookahead: reward leaving room for next item, penalize blocking it
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post_residual as f64 >= ni {
            score -= 8.0 + 10.0 * progress;
        } else if bin_residual as f64 >= ni && (post_residual as f64) < ni {
            // this placement blocks a bin that could have held the next item
            score += 6.0 * (1.0 - progress);
        }
    }

    // Last-chance bin bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 18.0 * progress;
    }

    // Slight preference for tighter bins relative to fleet mean
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate: encourage reuse of open bins, more so early on
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress + 5.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Small unusable gaps (1..=9) are the worst outcome: heavily penalize them.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        // Mid-small gaps are still poor but less catastrophic.
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 100.0;
    }

    // Reward tight fits: fraction of the bin consumed by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Penalize wasting a large residual on a small item (bad coupling).
    if item_size < bin_residual / 3 {
        score += 15.0;
    }

    // --- Open-bin pressure ---
    // Many open bins: discourage opening yet another one; encourage consolidation.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; cheaper late in stream
        // when consolidation matters most.
        score += 30.0 + open_pressure * 4.0;
        // A new bin is acceptable if nothing fits well (last-chance logic below).
    } else {
        // Existing bins get a mild reward for being reused.
        score -= 5.0;
        // Last chance bin: strongly prefer using it over opening a new bin.
        if fitting_bins_count == 1 && post_residual <= 9 {
            score -= 70.0;
        }
    }

    // --- Lookahead coupling (k=2) ---
    // Favor bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else if post_residual > 0 {
            // Gap too small for lookahead item: extra dead-space penalty.
            score += 10.0;
        }
    }

    // --- Stream progression ---
    // Late in the stream, consolidation dominates: penalize high mean residual spread.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - post_residual as f64).abs() * 0.5;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near match: next item fits with small slack.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual as f64 - next_item_size as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual as u32 && next_item_size > 0 {
        // Next item cannot follow into this bin: penalize proportionally to wasted fit.
        let gap = (next_item_size - post_residual as u32) as f64;
        score += 15.0 * (gap / bin_capacity as f64).min(1.0);
    }

    // Reward tight fits (low post_residual relative to capacity).
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * tightness;

    // Penalize dead space below the minimum item size (unusable residue).
    let min_item = 1u32;
    if post_residual < min_item.max(0) {
        score += 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are "more full",
    // prefer them; bins above mean are wasteful targets.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // New-bin candidate handling: only attractive when no good fit exists
    // (few fitting bins or large dead-space creation in existing bins).
    if bin_residual == bin_capacity {
        let base = 55.0;
        let scarcity = if fitting_bins_count == 0 { -80.0 } else { (fitting_bins_count as f64).ln() * 12.0 };
        let waste = if next_item_size > 0 && next_item_size <= bin_capacity {
            (bin_capacity as f64 - next_item_size as f64) * 0.3
        } else { 0.0 };
        score = base + scarcity + waste;
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (large fill ratio): subtract up to ~cap/2.
    score -= 45.0 * (fit_ratio * fit_ratio).min(1.0);

    // Penalize small dead space that nothing can use (post_residual < 10).
    if post_residual < 10 {
        score += 18.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; mildly penalize leaving large residual
            score += 5.0 * (post_residual as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many fitting bins: slight penalty to spread load toward emptier bins.
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Global state: prefer bins whose residual is near mean residual (balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Early in stream: encourage keeping bins open/consolidated; late: consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 4.0 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: base score so it's chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score = item_size as f64 * 0.55 + 22.0
            - if next_item_size > 0 && next_item_size >= 50 { 6.0 } else { 0.0 }
            + if fitting_bins_count == 0 { 0.0 } else { 14.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;
    let pn = prn * prn;
    let pn3 = pn * prn;

    // Early: prefer tight fits (low post_residual). Late: waste matters more.
    let w_early = (1.0 - progress) * (1.0 - progress);
    let w_late = progress * progress;

    score += w_early * (pn3 * 40.0) + w_late * (pn * 60.0);

    // Reward near-perfect fits with a smooth quadratic bonus
    let fit = 1.0 - pn;
    score -= fit * fit * 25.0;

    // Lookahead: penalize if post_residual can't fit next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns + 1.0 {
            score += 15.0 + 10.0 * progress;
        } else {
            let gap = (pr - ns) / cap;
            score += gap * gap * 20.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly early, more when open bins are tight-fitting
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
        score += 20.0 + 25.0 * progress + 10.0 * scarcity;
    }

    // Mean residual coupling: prefer bins near mean residual (balanced usage)
    let dev = (pr - mean_residual) / cap;
    score += dev.abs() * 8.0;

    // Mild penalty for many open bins
    score += open_bins_count as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: classify post_residual into residue classes
    // mod 10 and mod 7 to detect "usable" vs "dead" remainders.
    let r10 = post_residual % 10;
    let r7 = post_residual % 7;
    // Leftovers that are multiples of 10 are highly reusable (item sizes 10..80).
    if r10 == 0 {
        score -= 8.0;
    } else if r10 <= 3 {
        score += 2.0; // tiny slivers are near-dead space
    }
    if r7 == 0 {
        score -= 3.0;
    }

    // Integer-division thresholds: leftover >= 40 is a "half bin" class, very valuable.
    let half_class = post_residual / 20; // 0..5 classes
    score -= half_class as f64 * 4.0;

    // Coupling with the lookahead item: reward leftovers that exactly or nearly
    // accommodate next_item_size (harmonic matching).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the current item
    // is large and no tight fit exists elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base = 20.0 + 30.0 * progress;
        score += base;
        // A large item wastes little in a new bin; a small item should go into
        // an existing bin's slack.
        score -= item_size as f64 * 0.2;
        if fitting_bins_count == 0 {
            score -= base; // forced new bin anyway
        }
    }

    // Prefer bins whose residual is already below the mean (consolidating slack).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Slight preference to fill older bins when many are open (bin count control).
    score += open_bins_count as f64 * 0.05;

    // Tight-fit bonus: near-perfect fills are ideal.
    if post_residual <= 2 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (1..=10) are the worst kind of waste.
    if post_residual >= 1 && post_residual <= 10 {
        score += 40.0; // unusable sliver => heavy penalty
    } else if post_residual <= 20 {
        score += 12.0; // near-unusable gap
    } else if post_residual <= 35 {
        score += 4.0; // mildly awkward gap
    } else {
        // Large usable residuals are rewarded: they can absorb future items.
        score -= (post_residual as f64 - 35.0) * 0.35;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score += 25.0; // would create a fresh sliver for the next item
        } else if post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins => prefer filling existing ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score -= pressure * 6.0 + (open_bins_count as f64) * 0.8;

    // Deviation from mean residual: bins far below mean are "almost full",
    // prioritize them to close them out.
    let dev = mean_residual - bin_residual as f64;
    score -= dev * 0.25;

    // Slight mid-stream tightening: as the stream progresses, be pickier.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.15 * progress;

    // New-bin candidate: opening a new bin gets a baseline cost so it only
    // wins when existing bins would create severe dead space.
    if bin_residual == bin_capacity {
        score += 55.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: the less residual left, the better.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Strong reward for exact fill.
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward proportional to how well it uses leftover
            let nxt_fit = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 30.0 * nxt_fit;
        } else {
            // next item won't fit here: penalize leaving dead space it can't use
            score += 15.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Compare post_residual against mean residual across open bins:
    // prefer bins whose remaining space deviates from the mean in a usable way.
    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 {
        // leaving less than average: good, tighten the bin
        score -= 0.5 * dev.abs();
    } else {
        // leaving more than average: mild penalty
        score += 0.25 * dev;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize wasting a mostly-empty bin when many bins are open.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    if fill_frac < 0.35 && open_bins_count > 1 {
        score += 20.0 * (0.35 - fill_frac);
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // item fits badly everywhere else. Base new-bin score is high residual (capacity),
    // so add a dynamic offset depending on stream position and open bins.
    if bin_residual == bin_capacity {
        // Slight discount early (cheap to open bins), growing cost later.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 * progress + 2.0 * open_bins_count as f64;
        // If next item is small, a fresh bin is fine for it.
        if next_item_size > 0 && next_item_size >= 50 {
            score += 10.0;
        }
    } else {
        // Existing bins get a small baseline advantage over opening new bins.
        score -= 5.0;
    }

    // Small tie-breaker favoring tighter bins.
    score += 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as post_residual shrinks (non-linear).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 14.0 * tightness * tightness;

    // Penalize residuals that are too small to hold the smallest plausible item (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily;
    // if post_residual cannot fit next item, penalize mildly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual {
            score += 6.0 + 0.1 * (next_item_size - post_residual) as f64;
        } else {
            score += 0.05 * (post_residual - next_item_size) as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // fits poorly everywhere else (large item relative to mean residual) or when
    // existing bins are nearly full.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fit = (item_size as f64) > mean_residual * 0.85;
        if fitting_bins_count == 0 || poor_fit {
            score -= 18.0 + 8.0 * progress;
        } else {
            // Penalize opening a new bin when decent fits exist.
            score += 15.0 + 0.5 * (bin_capacity - item_size) as f64 * 0.1;
        }
        // Many open bins: discourage spreading further.
        score += 0.4 * open_bins_count as f64;
    }

    // Global state coupling: when mean residual across bins is low, prefer conserving
    // residual capacity in this bin (waste aversion grows).
    score += 0.15 * (post_residual as f64 - mean_residual).abs().powf(1.2);

    // Slight time-dependent exploration bias.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * (progress - 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 + progress) + norm_pr * (1.0 - progress);
    score += 8.0 * poly;

    // Reward tight fits: item fills most of the bin.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fill * fill;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly, more when many bins are open or residuals are large.
    if bin_residual == bin_capacity {
        score += 18.0 + 2.0 * open_bins_count as f64 + mean_residual * 0.15;
    } else {
        // Reward bins that are below mean residual (relatively empty, worth filling).
        score -= 3.0 * (mean_residual - pr).max(0.0) / cap;
    }

    // Lookahead coupling: penalize leaving a residual that only marginally fits the next item,
    // reward leaving a residual that perfectly fits (post_residual == next_item_size).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let diff = pr - nxt;
            score -= 10.0 / (1.0 + diff * 0.2);
            score += 0.05 * diff;
        }
        // Penalize post_residual that is too small to be useful for the next item.
        if pr < nxt && pr > 0.0 {
            score += 4.0 * (1.0 - pr / nxt);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are multiples of
    // common item sizes (or fit into small integer-division classes) are
    // more likely to be filled by future items -> reward them.
    let pr = post_residual;
    if pr > 0 {
        // Perfect harmonic fit: divisible by 10 (common granularity)
        if pr % 10 == 0 {
            score -= 6.0;
        }
        // Semi-harmonic: divisible by 5
        else if pr % 5 == 0 {
            score -= 3.0;
        }
        // Dead-space penalty grows for awkward residuals
        let dead = (pr % 10) as f64;
        score += dead * 0.4;
    } else {
        // Perfect fill
        score -= 15.0;
    }

    // Integer-division threshold classes on post_residual:
    // small residuals (<10) are nearly dead space; large residuals are flexible.
    if pr < 10 {
        score += 8.0;
    } else if pr <= 25 {
        score -= 2.0;
    } else if pr <= 50 {
        score -= 4.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 5.0 - slack * 0.05;
            if (pr - next_item_size) % 10 == 0 {
                score -= 3.0;
            }
        } else {
            // next item cannot use this bin's remainder; mild penalty scaled
            // by how much it overshoots
            score += ((next_item_size - pr) as f64) * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no open bin offers a good harmonic fit (post_residual near 0 or harmonic).
    if bin_residual == bin_capacity {
        // Base cost of a new bin: it's a fresh flexible resource.
        score = (bin_capacity - item_size) as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 4.0;
            if (bin_capacity - item_size - next_item_size) % 10 == 0 {
                score -= 3.0;
            }
        }
        // Late in the stream, avoid spreading across many bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 4.0 + open_bins_count as f64 * 0.5;
    } else {
        // Reward tight fits relative to bin capacity.
        let fill = item_size as f64 / bin_capacity as f64;
        score -= fill * 5.0;

        // Prefer bins with residual below the mean residual (tighter bins).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        } else {
            score += 1.0;
        }

        // Early stream: mild encouragement to consolidate into fewer bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps harder.
    let min_useful = 10u32.min(bin_capacity);
    if post_residual > 0 && post_residual < min_useful {
        score += 60.0; // dead space that almost nothing can fill
    } else if post_residual < 20 {
        score += 12.0; // tight gap, only small items can use it
    } else if post_residual < 35 {
        score += 4.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 8.0; // gap wasted relative to known next demand
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * pressure;

    // Progress-based tightening: late in stream, prefer tight fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.3;

    // Deviation from mean residual: prefer bins whose residual is close to item need
    let fit_gap = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += 0.2 * fit_gap;

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a new bin
        } else if post_residual >= 60 {
            score -= 5.0; // fresh bin leaves large usable space
        } else {
            score += 25.0; // opening a new bin when decent fits exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size well
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        if next_item_size as u32 <= post_residual {
            // next item can follow in this bin: reward tight chaining
            score -= 50.0 - 0.8 * gap;
        } else {
            // next item cannot follow: penalize wasted residual relative to next size
            score += 0.3 * (next_item_size as f64 - post_residual as f64).min(40.0);
        }
    }

    // Penalize residual far below mean residual (poor relative fit)
    score += 0.5 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins fit poorly
    if bin_residual == bin_capacity {
        let base = 120.0;
        let pressure = if fitting_bins_count == 0 { -500.0 } else { 0.0 };
        let lookahead_penalty = if next_item_size > 0 && next_item_size >= item_size * 2 { -60.0 } else { 0.0 };
        score += base + pressure + lookahead_penalty;
    }

    // Mild preference for consolidating fewer bins early in stream
    score += 0.5 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 14.0 * tightness * tightness;

    // Penalize dead space: residuals too small to ever fit a typical item.
    if post_residual > 0 && post_residual < 10 {
        score += 22.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 6.0;
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (post_residual as f64) >= ni {
            score -= 10.0 + 0.15 * ni;
        } else {
            score += 4.0;
        }
        // If next item fits exactly after this placement, big reward.
        if post_residual as u32 == next_item_size {
            score -= 18.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Discourage opening new bins when many bins are already open and mean residual is high.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more late in the stream or when open bins are roomy.
        let roominess = mean_residual / cap;
        score += 18.0 + 20.0 * progress + 30.0 * roominess * (open_bins_count as f64).sqrt();
    } else {
        // Favor bins with residual close to item (best-fit flavor), scaled by progress.
        let gap = (bin_residual as f64 - item_size as f64).abs();
        score += 0.05 * gap;
        // Slight preference for fuller bins as stream progresses.
        score -= 8.0 * progress * (1.0 - bin_residual as f64 / cap);
    }

    // Mild tie-breaker: prefer bins with residual near mean residual (balanced packing).
    score += 0.03 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;

    // Base: penalize large post-residual (wasted space), non-linearly.
    let mut score = pr * (1.0 + 0.5 * pr / cap);

    // Reward tight fits (small post_residual) with a strong smooth discount.
    let tightness = 1.0 - pr / cap;
    score -= 30.0 * tightness * tightness * tightness;

    // Stream-progress coupling: later in the stream, be more tolerant of
    // residual space (fewer future items to serve), so smooth decay of waste penalty.
    score -= 10.0 * progress * (pr / cap);

    // Mean-residual coupling: if open bins are already loose, penalize adding
    // more slack; if bins are tight, reward slack creation slightly.
    let mean_norm = mean_residual / cap;
    score += 8.0 * mean_norm * (pr / cap);

    // Lookahead coupling: if next item fits into post_residual, reward this bin.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it over opening a new one.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // New-bin candidate: opening a bin is expensive; penalize smoothly with
    // progress and existing open-bin count, but relax if item is huge.
    if is_new_bin {
        let item_frac = item_size as f64 / cap;
        score += 20.0 + 15.0 * (1.0 - item_frac) + 5.0 * (open_bins_count as f64).ln() * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small residuals in "dead" zones are penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Dead-space penalty: residuals that cannot host typical items (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Harmonic classes via integer division on post_residual (classes of 10).
    let class = post_residual / 10;
    match class {
        0 => { score += 150.0; }          // 0..9: nearly dead space
        1 => { score += 40.0; }           // 10..19: only tiny items fit
        2 => { score -= 20.0; }           // 20..29: useful small slot
        3 => { score -= 35.0; }           // 30..39
        4 => { score -= 45.0; }           // 40..49
        5 => { score -= 40.0; }           // 50..59
        6 => { score -= 25.0; }           // 60..69
        7 => { score -= 10.0; }           // 70..79
        8 => { score += 10.0; }           // 80..89: mostly empty, wasteful fill
        _ => { score += 0.0; }            // 90..100: near-empty bin
    }

    // Lookahead coupling: reward leaving room exactly for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            let slack = post_residual - next_item_size;
            // Reward when next item fits with little slack left over.
            if slack < 10 {
                score -= 120.0;
            } else {
                score -= (40.0 - (slack as f64).min(40.0)) * 0.5;
            }
        } else {
            // Next item won't fit here: penalize mildly, stronger if residual becomes dead.
            let gap = next_item_size - post_residual;
            if gap <= 10 && post_residual > 0 {
                score += 60.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let base_penalty = 180.0 + 0.5 * (open_bins_count as f64);
        // If current item is large, a fresh bin is more attractive.
        let large_item_bonus = if item_size >= 50 { 60.0 } else { 0.0 };
        // If many bins fit the item, opening new bin is wasteful.
        let crowd_penalty = (fitting_bins_count as f64) * 30.0;
        score += base_penalty + large_item_bonus + crowd_penalty;
    }

    // Progress-based mild regularization: prefer tighter fits early in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (pr * 0.05);

    // Coupling with mean residual: bins far below mean residual are "fresh";
    // filling them early is fine, but avoid dumping into bins near mean (balanced use).
    let dev = mean_residual - pr;
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit is highly rewarded.
        score -= 40.0;
    }

    // Penalize residual that no plausible item can use (dead space).
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Favor bins whose leftover can fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral baseline with slight penalty so it is
    // chosen only when fits in open bins are poor.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    // Prefer tighter bins (smaller bin_residual) when fits are comparable.
    score += (bin_residual as f64) * 0.1;

    // Mild stream-progression adjustment: tighten behavior over time.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0;

    // Mean residual coupling: if open bins are already loose, penalize
    // adding more loose space; if tight, tolerate some slack.
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Exact fit is gold
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 60.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let match_reward = 50.0 / (1.0 + gap * gap * 0.02);
        score -= match_reward;
        // Perfect chain: next item exactly fills the leftover
        if post_residual == next_item_size {
            score -= 80.0;
        }
        // Penalize leaving a residual that no plausible item (1..=100) can pair with well:
        // dead space if post_residual is tiny but nonzero and next item is much larger
        if post_residual < next_item_size && post_residual < 10 {
            score += 25.0;
        }
    } else {
        // Last item: strongly prefer minimal leftover
        score -= 40.0 * tightness;
    }

    // Compare post_residual against current mean residual:
    // leaving a residual near the mean keeps flexibility; extreme residuals are penalized
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Penalize bins with already-small residual (fragmented bins) unless it's a near-perfect fit
    if bin_residual < item_size + 10 && post_residual > 0 {
        score += 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // fits poorly everywhere else. Penalize new bins mildly; escalate penalty when
    // many bins are already open and the stream is early (keep bins consolidated).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 45.0 + 10.0 * open_bins_count as f64 * (1.0 - progress);
        // If lookahead suggests a fresh bin enables a great chain (item + next fill a bin), relax
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover <= 10 {
                new_bin_penalty -= 60.0;
            }
        }
        // Late in the stream, prefer closing bins tightly rather than opening new ones
        if progress > 0.8 {
            new_bin_penalty += 20.0;
        }
        score += new_bin_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small for the smallest possible item
    // (item sizes can be as small as 1), scaled by how unusable it is.
    if post_residual > 0 {
        let waste = 1.0 - (post_residual as f64 / 100.0).min(1.0);
        score += 6.0 * waste;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // this is a perfect pair placement — reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to mismatch.
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 * (gap / 100.0);
        }
    } else {
        // Last item: just minimize leftover, nothing else matters.
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.5 * (bin_residual - item_size) as f64;
    }

    // New-bin candidate handling: an empty bin is attractive when current
    // open bins have large residuals (fragmented state) or many bins are open.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let crowd = (open_bins_count as f64 / (open_bins_count as f64 + 8.0)).sqrt();
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 45.0 * fragmentation * crowd * (0.5 + progress);
        // Late in the stream, prefer reusing existing bins more strongly.
        score += 20.0 * progress;
    } else {
        // Reward using bins whose residual is below the mean (consolidation).
        let diff = mean_residual - bin_residual as f64;
        score += 0.15 * diff;
    }

    // Global pressure: with many open bins, discourage spreading further
    // unless the fit is genuinely good.
    let pressure = (open_bins_count as f64 / (open_bins_count as f64 + 10.0)).ln().max(0.0);
    score += 8.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    // normalized stream progress
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear coupling: post_residual penalized more strongly as stream progresses
    score += 6.0 * progress * norm_pr * norm_pr;

    // Smooth interaction: reward tight fits via post_residual^4 term (small pr -> big discount)
    score -= 40.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 + progress);

    // Dead-space penalty: residuals too small for typical future items
    let dead = (norm_pr * (1.0 - norm_pr)).max(0.0); // peaks mid-range
    score -= 8.0 * dead;

    // Lookahead: if next item fits into post_residual, reward
    if next_item_size > 0 {
        let fits_next = if (post_residual as u32) >= next_item_size { 1.0 } else { 0.0 };
        let tight = 1.0 - ((post_residual as f64 - next_item_size as f64) / cap).abs();
        score -= 12.0 * fits_next * tight * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Spread-aware: prefer bins deviating from mean residual (consolidate fullness)
    let dev = (pr - mean_residual) / cap;
    score -= 4.0 * dev * dev * (1.0 + progress);

    // Mild penalty for proliferation of open bins early
    score += 0.5 * open_bins_count as f64 * (1.0 - progress) * norm_pr;

    // New-bin candidate: penalize opening a new bin unless it beats all fits
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity fractions
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap;

    // Reward tight fits: harmonic classes where post_residual is small
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 100.0;
    } else if post_residual <= 20 {
        score -= 40.0;
    }

    // Penalize "dead zone" residuals: post_residual in [21, 40] is hard to fill
    // with typical items (10..80 range in classic streams)
    let class = post_residual % 10;
    if post_residual >= 21 && post_residual <= 40 {
        score += 30.0 + (class as f64) * 2.0;
    }

    // Harmonic quarter classes of the fill fraction
    let fill = 1.0 - frac;
    if fill >= 0.75 {
        score -= 60.0;
    } else if fill >= 0.5 {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            // reward small leftover gap after hypothetical next placement
            let gap2 = post_residual - next_item_size;
            score -= (10 - (gap2 % 10)) as f64 * 2.0;
        } else {
            // next item cannot fit here; penalize leaving large residual
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: discourage opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        score += 250.0 + mean_residual * 0.5;
        // allow new bin late in stream if many bins open already
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 100.0;
    }

    // Mild preference for fuller bins among many open bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3;
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0) + 25.0;
    } else if post_residual < 20 {
        score += 8.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Lookahead: if next item fits in the post residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Dead-end for the known successor: penalize.
        score += 6.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading.
    score += 0.6 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Slight preference to fill bins below mean residual (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // New empty bin candidate: moderate score so it wins only over poor fits.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.4 * open_bins_count as f64;
        if fitting_bins_count <= 1 {
            score -= 40.0; // no real alternative anyway
        }
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space: residual too small for any future item (min size 1) but nonzero
    if post_residual > 0 {
        // penalize unusable slivers relative to capacity
        let dead = (post_residual as f64) / (bin_capacity as f64);
        score += dead * 40.0;
        if post_residual < 10 {
            score += 30.0; // likely dead space given typical item sizes
        }
