    // 2-step lookahead: exact match of next item into post_residual is gold
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            // reward bins whose leftover can host the next item
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 / (1.0 + slack / 20.0);
        } else {
            // next item cannot fit here: mild penalty scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(80.0);
        }
    }

    // Tight fit reward relative to current residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 60.0;

    // Compare against mean residual: prefer using bins with less room than average
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Discourage opening new bins early in the stream / when many bins already open
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 120.0;
        if open_bins_count == 0 {
            score -= 500.0; // must open first bin
        }
        // allow new bin if no open bin fits well
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // as stream progresses, slightly more willing to open fresh bins
        score -= (step_index as f64 / (total_items as f64).max(1.0)) * 50.0;
    }

    // mild preference to spread load when many bins open
    score += (open_bins_count as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable sliver
    }

    // Lookahead coupling: if next item fits in the post-residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let pair_eff = (item_size + next_item_size) as f64 / bin_capacity as f64;
        score -= 14.0 * pair_eff;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here after placement; mild penalty scaled by gap.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.08 * gap;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Many alternatives: prefer the bin whose residual is closest to item size.
        let waste = (bin_residual - item_size) as f64;
        score += 0.05 * waste;
    }

    // Global state: discourage spreading residual capacity thin when many bins open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.03 * dev * (1.0 + open_bins_count as f64 / 20.0);
    }

    // New-bin candidate handling: opening a bin is cheap early, expensive late.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 - (fitting_bins_count as f64).min(4.0) / 4.0;
        score = bin_capacity as f64
            - 30.0 * scarcity
            - 10.0 * (1.0 - progress)
            + 8.0 * progress * open_bins_count as f64;
        // If lookahead item is large, a fresh bin is attractive.
        if next_item_size >= 60 {
            score -= 6.0;
        }
    }

    // Time-horizon modulation: late in the stream, consolidation matters more.
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual and its non-linear decay with stream progress
    let pr_norm = post_residual as f64 / bin_capacity as f64;
    let tightness = 1.0 - pr_norm;
    let progress_coupling = pr_norm * pr_norm * (1.0 - progress) - pr_norm * progress;
    score += 12.0 * progress_coupling;

    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= 8.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual across open bins
    score += 0.35 * (post_residual as f64 - mean_residual).abs();

    // Lookahead: reward leaving space exactly matching the next item
    if next_item_size > 0 {
        let diff = (post_residual as f64 - next_item_size as f64).abs();
        score -= 10.0 / (1.0 + diff);
        if post_residual == next_item_size {
            score -= 15.0;
        }
        // Penalize post_residual slightly below next item (unusable wedge)
        if post_residual > 0 && (post_residual as u32) < next_item_size {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mild penalty for proliferation of open bins when residual is large
    score += 0.05 * open_bins_count as f64 * pr_norm;

    // New-bin candidate: prefer opening a new bin only when existing fits are loose
    if bin_residual == bin_capacity {
        score = 55.0 + 25.0 * progress - 0.15 * mean_residual;
        if next_item_size > 0 && item_size as f64 + next_item_size as f64 <= bin_capacity as f64 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: best-fit preference for tight packing.
    let frac = post_residual as f64 / cap;
    score += 4.0 * frac * frac;

    // Harmonic classes: reward residuals that lie in a "usable" class.
    // Class boundaries via integer division thresholds on post_residual.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fill
    } else {
        // Class the residual into harmonic slots of capacity fractions.
        let class = pr / 10; // 0..10 harmonic slot
        // Residuals just above common item sizes (10..80) are more reusable.
        let reusable = (pr >= 10 && pr <= 80) as i32;
        score -= 6.0 * reusable as f64 * (1.0 - class as f64 / 10.0);

        // Dead-space penalty: residual too small for any plausible item.
        if pr < 10 {
            score += 12.0;
        }
        // Modulo arithmetic: residuals that are multiples of small item sizes
        // (10, 20, 25, 50) are more likely to be exactly filled later.
        let harmonic = ((pr % 10 == 0) || (pr % 20 == 0) || (pr % 25 == 0) || (pr % 50 == 0)) as i32;
        score -= 5.0 * harmonic as f64;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here; slight penalty if this bin becomes dead.
            if pr < 10 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer opening a new bin only when existing fits are bad.
    if bin_residual == bin_capacity {
        // Neutral baseline with mild aversion, overcome only if open-bin scores are high.
        score += 18.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If many open bins already, new bin dilutes residuals; penalize more.
        score += 2.0 * (open_bins_count as f64).sqrt();
        // If mean residual is large, prefer reusing open bins.
        score += (mean_residual / cap).min(1.0) * 15.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.3 * open_bins_count as f64 * (1.0 - bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (1..=10, too small for any item) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 + (10 - post_residual) as f64 / 10.0);
    }
    // Mid-range gaps (11..=20) are semi-risky: mild penalty that decays.
    if post_residual > 10 && post_residual <= 20 {
        score += 12.0 * (20 - post_residual) as f64 / 10.0;
    }

    // Reward tight fits (small but usable leftovers are fine).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Lookahead: if the next item exactly fills the post-residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits here: slight bonus scaled by how well it fits.
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use this residual: penalize wasted space more.
            score += 6.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (unless dead space is egregious).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mean-residual coupling: when open bins are on average roomy, prefer
    // consolidating into them; when they are tight, tolerate a new bin.
    score -= 0.15 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: an empty bin is attractive only if the
    // item would leave a large, awkward residual elsewhere, or if no
    // decent fit exists. Base cost keeps it from winning by default.
    if bin_residual == bin_capacity {
        score += 18.0;
        if post_residual <= 10 {
            score -= 30.0; // filling a fresh bin almost perfectly is great
        }
        if fitting_bins_count == 0 {
            score -= 50.0; // nothing else fits: new bin is mandatory
        }
    }

    // Mild stream-progression term: early on, slightly prefer opening bins
    // to keep options open; late, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 4.0 - progress * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward near-exact fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 50.0;
    }

    // 2-step lookahead: reward bins where the leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact match with next item is ideal.
            let gap = (post_residual as i64 - next_item_size as i64) as f64;
            score -= 120.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Leftover too small for next item: dead space risk.
            score += 30.0 * (next_item_size as f64 - post_residual as f64) / next_item_size as f64;
        }
    }

    // Relative to mean residual: prefer bins that are tighter than average.
    let r = post_residual as f64;
    if r < mean_residual {
        score -= 0.5 * (mean_residual - r);
    } else {
        score += 0.3 * (r - mean_residual);
    }

    // Last-chance bin: if this is the only fitting bin, penalize wasting it on a bad fit.
    if fitting_bins_count == 1 && post_residual > 20 {
        score += 40.0;
    }

    // New-bin candidate: only open a new bin when no existing bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score += 50.0;
        // But if existing fits are poor (post_residual large) and next item could
        // combine with this leftover, opening fresh is attractive.
        if next_item_size > 0 && post_residual >= item_size + next_item_size {
            score -= 80.0;
        }
    }

    // Late in stream: consolidate, avoid spreading across many bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 0.2 * progress * (open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post_residual (nonlinear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness * tightness;

    // Penalize leaving awkward dead space that few future items can use.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 0.0 } else { post_residual as f64 };
        score += 0.15 * dead;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 / (1.0 + slack);
    } else if next_item_size > 0 {
        // Next item won't fit here; mild penalty proportional to mismatch.
        score += 3.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Many open bins with slack: discourage spreading; few bins: encourage packing here.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.5 * (open_bins_count as f64) * (1.0 - progress) * 0.1;
    score -= (mean_residual - post_residual as f64).abs() * 0.05;

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let avg_fit = mean_residual;
        score += 15.0 + 0.3 * avg_fit;
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative, must open new bin
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr);
    score -= 40.0 * poly * (0.5 + progress);

    // Penalize tight fits that leave awkward residuals as stream progresses
    let tight = 1.0 - (pr / cap).abs();
    score += 10.0 * tight * tight * progress;

    // Reward bins that are nearly full (small post_residual) more strongly later
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 15.0 * (0.3 + 0.7 * progress);

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item could fit into post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 8.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size as f64 - pr).abs() / cap);
    }

    // Prefer bins with below-mean residual (consolidate emptier space usage)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev.abs();

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln() * 0.5;

    // New-bin candidate: neutral baseline tuned against good fits
    if bin_residual == bin_capacity {
        score = 55.0 + 20.0 * progress - 10.0 * poly;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "nice" divisors/multiples
    let pr = post_residual;
    let mut harmony = 0.0;
    if pr == 0 {
        harmony -= 60.0; // perfect fit
    } else {
        // small residuals are dead space
        if pr <= 10 { harmony += 40.0; }
        else if pr <= 20 { harmony += 20.0; }
        // modulo classes: residuals divisible by 10 are more reusable
        if pr % 10 == 0 { harmony -= 15.0; }
        if pr % 25 == 0 { harmony -= 10.0; }
        if pr % 50 == 0 { harmony -= 12.0; }
        // integer-division threshold bands
        let band = pr / 25; // 0..4
        harmony += band as f64 * -3.0; // larger residual generally better
    }
    score += harmony;

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 25.0 + (pr - next_item_size) as f64 * 0.5;
        } else {
            // penalize near-misses: gap 1..=10 is wasted potential
            let gap = next_item_size as i64 - pr as i64;
            if gap > 0 && gap <= 10 {
                score += (11 - gap) as f64 * 4.0;
            }
        }
    } else {
        // last item: prefer exact fills
        score += pr as f64 * 0.3;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize slightly so we only open when open bins are bad
    if bin_residual == bin_capacity {
        score += 45.0 + open_bins_count as f64 * 0.5;
    }

    // Mean residual alignment: prefer bins near the mean (balanced packing)
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    // Late-stream consolidation: tighten threshold as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Gaps that nothing in [1,100] known range can use well later are dead weight.
    if post_residual > 0 && post_residual < item_size {
        score += 15.0;
    }

    // Reward tight fits (low post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness;

    // Open-bin pressure: prefer using existing bins over opening new ones.
    score += 0.05 * open_bins_count as f64;

    // Last-chance bin: strongly favor placing here if it's the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fit is bad.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        // But if post_residual of this new bin perfectly accommodates next item, soften.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 5.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below mean (more filled).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: this bin's leftover exactly fits the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 == nxt {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // leftover can host next item, but reward tightness of that pairing
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // leftover cannot host next item: penalize proportionally to wasted potential
            let miss = (next_item_size - post_residual) as f64;
            score += 0.35 * miss;
        }

        // If this bin is the only one that fits, strongly prefer using it.
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 25.0;
        }
    }

    // Penalize leaving residuals that are small but useless (below min item size ~1 is fine,
    // so instead penalize residuals in an awkward band relative to mean residual).
    let pr = post_residual as f64;
    if pr > 0.0 && pr < mean_residual * 0.5 {
        score += 6.0;
    }
    // Reward residuals close to the mean (keeps bin population balanced)
    score += 0.15 * (pr - mean_residual).abs();

    // New-bin candidate logic: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        // base cost of opening a bin, softened when many bins are already open
        score = cap * 1.2 + 20.0 * pressure - 10.0 * progress;
        if fitting_bins_count == 1 {
            // last-chance bin exists; opening new bin is usually bad
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large post-residual non-linearly (dead space).
    score += 0.02 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Reward tight fits strongly.
    if post_residual < 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize leaving a residual that is awkwardly small for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins with residuals close to the mean (balance load).
    score += 0.3 * ((bin_residual as f64) - mean_residual).abs();

    // Time horizon: early in the stream, be more conservative (keep bins flexible);
    // later, accept worse fits since little remains to gain.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 6.0;

    // Penalize opening new bins, but allow it when the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let base_penalty = 20.0;
        let waste = (bin_capacity - item_size) as f64;
        score = base_penalty + 0.05 * waste - progress * 4.0
            - if fitting_bins_count == 1 { 0.0 } else { 0.0 };
        // If the only fitting bin is this new-bin candidate, it's the natural choice.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // smooth non-linear coupling of post_residual with stream progress
    let coupling = pr_norm * (1.0 - pr_norm) * (progress - 0.5);
    score -= 20.0 * coupling;

    // reward tight fits (fit_ratio near 1)
    score -= 8.0 * fit_ratio * fit_ratio;

    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 3.0 + 2.0 * (next_item_size as f64 / cap);
    }

    // mild penalty for spreading across many bins vs mean residual
    score += 0.02 * (open_bins_count as f64) * (mean_residual - pr).abs() / cap;

    // new-bin candidate should only win when residuals are small
    if bin_residual == bin_capacity {
        score += 10.0 * pr_norm + 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands in "useful" residue classes
    // (small, re-usable leftovers) get rewarded; awkward mid-range dead space gets penalized.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class A: near-perfect fit (post_residual <= 10) -> strong reward.
    if post_residual <= 10 {
        score -= 30.0 + (10 - post_residual) as f64 * 2.0;
    }
    // Class B: post_residual divisible by common small sizes (harmonic divisibility)
    else if post_residual % 10 == 0 {
        score -= 12.0;
    } else if post_residual % 5 == 0 {
        score -= 6.0;
    }

    // Dead zone: post_residual in (20, 40) is the worst leftover band (too big to waste,
    // too small for typical items) -> penalize.
    if post_residual > 20 && post_residual < 40 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            if nxt_post <= 10 {
                score -= 25.0;
            } else {
                score -= 8.0;
            }
        } else {
            // next item won't fit here: leftover becomes dead until later
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: only bin that fits -> reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets baseline penalty so we prefer good
    // existing fits, but reward opening a new bin when existing residuals are fragmented.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 5.0;
        // open a new bin when the item fits poorly everywhere / mean residual is large
        if mean_residual > item_size as f64 * 1.5 && fitting_bins_count > 0 {
            score -= 10.0;
        }
        // early stream: opening bins is cheap and gives future flexibility
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.3 {
            score -= 8.0;
        }
    } else {
        // prefer bins whose residual is close to item (tight fits)
        let tightness = (bin_residual as f64 - item_size as f64) / cap;
        score += tightness * 10.0;
        // prefer bins below mean residual (consolidating emptier bins)
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Harmonic modulo coupling on item_size classes: large items (>50) prefer tight bins.
    if item_size > 50 && post_residual <= 25 {
        score -= 10.0;
    }
    if item_size <= 20 && post_residual >= 60 {
        score += 5.0; // avoid dumping tiny items into big empty bins
    }

    // Mild tie-break favoring fewer open bins overall.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any plausible item are pure waste.
    // Treat residual < ~12 as dead space -> strong penalty proportional to its uselessness.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold {
