    // Reward near-perfect fits (small post_residual relative to bin_residual).
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 15.0;
    }

    // Penalize leaving a gap that can't fit the lookahead item (wasted opportunity),
    // but reward leaving a gap that exactly fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 6.0;
            score += slack as f64 * 0.05;
        } else {
            score += 4.0;
