    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (make the new-bin candidate less attractive by penalizing tight fits less
    // and adding pressure term proportional to open bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure from open bins and mean residual.
        score = bin_capacity as f64 * 0.5 + open_bins_count as f64 * 2.0 + mean_residual * 0.3 + progress * 5.0;
        // A new bin is acceptable if no open bin fits well.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        // Existing bin: mild reward for consolidating when many bins are open.
        score -= open_bins_count as f64 * 0.2;
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // avoiding extreme fragmentation.
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Partial lookahead reward: next item still fits after placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 4.0 * (next_item_size as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit in this residual: penalize proportionally to waste.
        score += 6.0 + 10.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Penalize large unusable dead space (post_residual below typical item sizes).
    if post_residual < 10 {
        score -= 15.0; // near-perfect fit, tiny residual is excellent
    } else if post_residual < 20 {
        score -= 5.0;
    } else if post_residual < 30 {
        // awkward zone: residual too small for most items
        score += 4.0;
    }

    // Prefer bins whose residual is below the mean (tighter bins used first).
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor fits
    // (item barely fits or nothing tight exists). Penalize mildly by default.
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64 / bin_capacity as f64);
        score += 18.0 - 14.0 * tightness;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0; // fresh bin accommodates the lookahead pair well
        }
        // As stream progresses, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 8.0 * progress;
        score += 0.5 * open_bins_count as f64;
    }

    // Small tie-breaker favoring bins with less residual before placement.
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual (perfect fits).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 30.0;
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    } else if post_residual < 10 {
        score -= 20.0; // near-perfect fill
    }

    // Penalize dead space that is too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits into post_residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 + 0.2 * next_item_size as f64;
        } else {
            // Waste: leftover can't host the next item.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap.min(50.0);
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Crowding: when many bins are open, prefer reusing existing bins
    // over opening new ones (consolidation pressure).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.5 * (1.0 - 0.5 * progress);

    // New-bin candidate: penalize opening a fresh bin unless current item
    // is large or mean residual across open bins is genuinely too small.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        let pressure = if mean_gap < 0.0 { -mean_gap } else { 0.0 };
        score += 35.0 - pressure.min(35.0);
        // Late in the stream, slightly more willing to open a new bin
        // (avoid cascading fragmentation into many half-full bins).
        score -= 10.0 * progress;
    }

    // Prefer bins whose residual is below mean (use up the emptiest space first),
    // keeping larger residuals for future larger items.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.1 * dev.min(60.0);
    } else {
        score -= 0.05 * (-dev).min(60.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear dead-space penalty: small residuals are wasted space; quadratic coupling with progress.
    let dead = 1.0 - (pr / cap);
    score += dead * dead * (12.0 + 30.0 * progress) * cap * 0.05;

    // Reward tight fits more strongly as the stream progresses (consolidation pressure).
    score -= (item_size as f64 / cap) * (1.0 + progress) * 8.0;

    // Lookahead: reward if next item fits into post_residual, penalize otherwise (smooth).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fit_gap = (n - pr).max(0.0);
        score += (fit_gap / cap) * (10.0 + 15.0 * progress);
        score -= (pr / cap).min(n / cap) * 6.0; // partial reward when next item nearly fits
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin unless open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap - 0.5).abs();
        let open_pressure = (open_bins_count as f64).ln_1p();
        score += 30.0 + 10.0 * open_pressure - 20.0 * fragmentation * (1.0 + progress);
    } else {
        // Mild bonus for bins whose residual deviates from mean (diversity of residual sizes).
        score -= ((pr - mean_residual).abs() / cap) * 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 (item sizes 1..100 granularity)
    let r = post_residual % 10;
    // Penalize post_residuals that are "dead" classes: too small to host typical items
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else {
        // favor post_residuals in useful harmonic bands
        match r {
            0 => score -= 15.0,           // round residue, easy to fill
            1..=3 => score += 12.0,       // awkward small residue
            4..=7 => score -= 5.0,        // moderately useful
            _ => score += 3.0,
        }
    }

    // Integer-division threshold: residue class by /25 buckets
    let bucket = post_residual / 25;
    score -= (bucket as f64) * 8.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 20.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use this residue: slight penalty scaled by waste
            score += ((next_item_size - post_residual) as f64) * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer fresh bin when existing fits are poor
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 55.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // late in stream with many open bins, prefer consolidation instead
        score += (1.0 - progress) * 25.0 - (open_bins_count as f64).min(10.0) * 2.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // fresh bin can host pair with next item
        }
    }

    // Tight-fit reward: item fills most of the bin
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 10.0;

    // Spread regulation: discourage bins far from mean residual
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    // Slight preference for bins with larger residual when many bins fit item
    if fitting_bins_count > 1 {
        score -= (bin_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Reward tight fits proportionally to fill ratio.
        let fill = item_size as f64 / bin_residual as f64;
        score -= 25.0 * fill * fill;
    }

    // Next-item lookahead: bonus if post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading unless fit is great.
    let pressure = (open_bins_count as f64).ln() * 3.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline near mean residual, penalized by bin pressure.
        score = mean_residual + 5.0 + pressure;
        if post_residual < 10 {
            score += 0.0; // fresh bin has no dead space
        }
        if next_item_size > 0 && bin_capacity >= next_item_size {
            score -= 4.0;
        }
    } else {
        score += pressure;
        // Favor bins whose residual is below mean (consolidating fuller bins).
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        }
    }

    // Slight late-stream tightening: waste matters more as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits heavily.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - 0.3 * slack; // prefer tight chain fits
        } else {
            // Penalize leaving space the next item cannot use
            let waste = (next_item_size - post_residual) as f64;
            score += 0.4 * waste;
        }
    }

    // Relative-to-mean-residual coupling: bins with more room than average
    // are preferred targets (keep tight bins for small items).
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin is penalized unless
    // the current bin would leave a large dead space.
    if bin_residual == bin_capacity {
        score += 120.0;
        // Allow opening a new bin if all existing fits are terrible.
        if post_residual == bin_capacity as u32 - item_size && item_size <= 40 {
            score -= 100.0;
        }
    }

    // Early in the stream, be more willing to open bins for flexibility.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Mild penalty per open bin to discourage bin proliferation.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Strong penalty for opening a brand-new bin when other bins fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Late in stream, prefer closing out open bins rather than spreading.
        let new_bin_penalty = 18.0 + 30.0 * progress;
        // If this bin is the only option, soften the penalty.
        if fitting_bins_count <= 1 {
            score += new_bin_penalty * 0.3;
        } else {
            score += new_bin_penalty;
        }
    } else {
        // Reward using existing bins, especially when few fit.
        if fitting_bins_count == 1 {
            score -= 8.0; // last-chance bin: avoid opening a new bin
        }
        score -= 4.0 * (1.0 - (bin_residual as f64 / bin_capacity as f64));
    }

    // Lookahead: penalize leaving residual that exactly blocks the next item
    // (dead space), reward leaving residual that can host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if pr > 0.0 && pr < nx {
            score += 6.0 * (1.0 - pr / nx); // stranded sliver
        } else if pr >= nx {
            // Reward residuals that can still fit the next item, more so when snug.
            score -= 5.0 * (nx / pr);
        }
    }

    // Global state coupling: when mean residual across open bins is high,
    // discourage adding to the most-loaded bin (spread work); when low, prefer tight packing.
    if open_bins_count > 1 {
        let dev = (mean_residual - bin_residual as f64).abs();
        score += 0.05 * dev;
        if bin_residual as f64 > mean_residual {
            score += 2.0; // penalize dipping into bins with above-average residual
        }
    }

    // Time horizon: early items favor conserving space, late items favor filling bins fully.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, waste is tolerable; late, tight fits matter more.
    let tightness = pr / cap;
    let progress_weight = 0.5 + 2.5 * progress * progress;
    score += progress_weight * tightness * tightness * cap * 0.5;

    // Reward near-perfect fits with a smooth cubic decay.
    let fit_quality = 1.0 - (pr / cap);
    score -= 30.0 * fit_quality * fit_quality * fit_quality;

    // Lookahead coupling: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size as u32) as f64 / cap;
            score -= 12.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            // Penalize leaving a gap the next item cannot use, scaled by gap size.
            let gap = (next_item_size as f64 - pr).max(0.0);
            score += 6.0 * (gap / nxt).min(1.0);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless it prevents a very bad fit elsewhere.
    if bin_residual == bin_capacity {
        let bad_fit_penalty = if fitting_bins_count >= 1 {
            (post_residual as f64).max(0.0)
        } else {
            0.0
        };
        score += 20.0 + bad_fit_penalty;
    }

    // Mild preference for bins whose residual deviates from the mean,
    // encouraging consolidation of similar residuals.
    score += 0.05 * (pr - mean_residual).abs();

    // Smooth open-bin pressure: fewer bins -> slightly favor filling existing ones.
    score -= 2.0 / (1.0 + open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into integer-division buckets.
    // Residuals in (0,10] are "dead" classes; (0,20] are semi-dead, etc.
    let post = post_residual;
    let dead_penalty = if post == 0 {
        -30.0 // perfect fit: strongly reward
    } else if post < 10 {
        25.0 // dead space: nearly unusable
    } else if post < 20 {
        12.0
    } else if post < 35 {
        4.0
    } else {
        0.0
    };
    score += dead_penalty;

    // Modulo-class coupling: if the next item can exactly fill a harmonic class of post_residual,
    // reward this bin (lookahead synergy).
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 20.0; // next item perfectly consumes leftover
        } else if next_item_size <= post && post - next_item_size < 10 {
            score -= 6.0; // next item leaves minimal dead space
        } else if next_item_size > post {
            score += 3.0; // next item cannot use this bin's leftover at all
        }
        // Harmonic bucket match: next_item_size divides post_residual's class
        if post > 0 && next_item_size > 0 && post % next_item_size == 0 && post / next_item_size >= 1 {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using the final fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin should only win when fits are terrible.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: large, but discounted when many bins are open or
        // mean residual across open bins is large (fragmented state).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 55.0;
        new_bin_cost -= 20.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));
        new_bin_cost -= 15.0 * (mean_residual / cap).min(1.0);
        new_bin_cost -= 5.0 * progress; // late in stream, prefer reusing
        // If the item is large relative to capacity, a fresh bin is more attractive.
        new_bin_cost -= 10.0 * (item_size as f64 / cap);
        if next_item_size > 0 && next_item_size as f64 / cap > 0.7 {
            new_bin_cost -= 8.0; // big item coming: keep open bins' small residuals intact
        }
        score = new_bin_cost;
    }

    // Mild tie-break: prefer bins whose residual is close to item_size (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / cap;
    score += 8.0 * tightness;

    // Prefer bins with below-mean residual (concentrate waste in few bins).
    score += 2.0 * ((bin_residual as f64 - mean_residual) / cap).max(-1.0).min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A gap is "dead" if it is too small to hold even the smallest plausible item.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) + 10 {
        score += 60.0; // unusable sliver
    }
    // Medium dead space: gap that cannot fit the next item either
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward perfect or near-perfect fits strongly
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and encourage consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty grows with open bins count
        score += 30.0 + pressure * 2.0;
        // If existing bins fit reasonably well, opening a new bin is wasteful
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    } else {
        // Reward filling existing bins, scaled by how tight the fit is
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= tightness * 10.0;
        // Favor bins with below-mean residual (they are closer to closing)
        if (post_residual as f64) < mean_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for an exact 2-step match: this bin then next item fill it perfectly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        if post_residual == next_item_size {
            score -= 80.0;
        }
        // Penalize residuals too small for the next item (dead space).
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    } else {
        // Last item: prefer tightest fit.
        score = post_residual as f64 * 2.0;
    }

    // Penalize large wasted residual relative to mean residual of open bins.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.3;
    }

    // Reward using a bin when it's the last chance (avoid opening a new bin).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin would leave a very poor fit
    // or no open bin fits well. Penalize opening new bins mildly by default.
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 5 {
            score -= 100.0; // fresh bin perfectly staged for the next item
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing fits, must open
        }
    }

    // Slight late-stream consolidation: prefer denser packing as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity - post_residual) as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to ever be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits in post_residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Extra bonus when the pair nearly fills the bin.
        let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
        score -= 30.0 * pair_fill;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual blocks the next item: mild penalty scaled by wasted space.
        score += 0.4 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: prefer bins whose post-residual stays flexible.
        score += 0.5 * (fitting_bins_count as f64).ln();
    }

    // Prefer bins with residuals below the current mean residual (tighter bins first).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Late in the stream, be more aggressive about closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and few bins are open (early stream or big items benefit from fresh bins).
    if bin_residual == bin_capacity {
        let base_penalty = 30.0 + 20.0 * progress;
        let large_item_bonus = if item_size >= 60 { 25.0 } else { 0.0 };
        let open_count_relief = if open_bins_count == 0 { 60.0 } else if open_bins_count <= 2 { 20.0 } else { 0.0 };
        score += base_penalty - large_item_bonus - open_count_relief;
    }

    // Small global-load balancing term: with many open bins, prefer filling
    // the emptiest-feeling candidates less aggressively.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Core: penalize residual, but weight it non-linearly by stream progress.
    let mut score = pr * (1.0 + 0.8 * t * t);

    // Quadratic dead-space penalty: small residuals that are hard to fill later.
    score += 25.0 * norm_pr * norm_pr;

    // Smooth coupling: reward tight fits more as stream progresses.
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (0.5 + t);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward leaving room for the next item (smooth kernel over gap).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.15 * gap;
        if next_item_size as f64 <= pr {
            score -= 6.0 * (1.0 - (next_item_size as f64 / pr.max(1.0)));
        }
    } else {
        // Last item: strongly prefer filling bins tightly.
        score -= 20.0 * tightness;
    }

    // Last-chance bin: avoid opening new bins when only one bin fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 + t);
    }

    // New-bin candidate: penalize proportionally to open bins and mean residual state.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score = cap * (1.2 + 0.1 * open_pressure) + 5.0 * (mean_residual / cap);
        // Allow new bin late in stream if residuals are fragmented.
        if mean_residual < 30.0 && t > 0.5 {
            score -= 60.0 * t;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo 10 (dead-space classes)
    let r = post_residual % 10;
    if r == 0 {
        score -= 12.0; // perfectly harmonic residual, great class
    } else if r <= 2 {
        score -= 6.0;  // near-harmonic, tiny dead space
    } else if r >= 8 {
        score += 4.0;  // large awkward residue
    } else {
        score += 8.0;  // mid-range dead space (3..7) is worst
    }

    // Integer-division threshold: post_residual relative to next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item can land here; reward proportional to closeness of fit
            let gap = post_residual - next_item_size;
            score -= (10.0 - (gap % 10) as f64) * 0.6;
            if gap == 0 {
                score -= 15.0; // perfect two-item chain
            }
        } else {
            // next item cannot fit here; penalize stranded residual
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor fits
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64 / bin_capacity as f64) * 100.0;
        // opening a new bin is good if item is large or current bins are nearly full
        if item_size >= 50 || mean_residual < item_size as f64 {
            score -= 5.0;
        } else {
            score += 15.0 + tightness * 0.1;
        }
        // penalize opening bins early in the stream
        score += (step_index as f64 / (total_items as f64 + 1.0)) * 10.0;
        score -= open_bins_count as f64 * 0.5;
    }

    // Slight preference for filling fuller bins (small residual before placement)
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (too small for typical items) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 - 3.0 * post_residual as f64;
    } else if post_residual > 10 && post_residual <= 25 {
        score += 12.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Pressure from many open bins: encourage filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.6 + 0.8 * progress);

    // Prefer bins whose residual is close to the item (tight packing).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.3;

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Post-residual too small for next item: mild penalty scaled to gap.
        score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.2;
    }

    // Keep mean residual influence: bins far below mean residual are
    // already "full-ish", prefer them to consolidate.
    score -= (mean_residual - post_residual as f64) * 0.4;

    // New-bin candidate (empty bin): post_residual == capacity - item is
    // large, so base score is already high; add fixed premium so it only
    // wins when open bins are truly poor fits.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    score -= 0.5 * (1.0 - (post_residual as f64) / cap);

    // 2-step lookahead: strongly reward exact match of post_residual with next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 3.0 * (1.0 - gap / cap).max(0.0);
        // Penalize post_residual that is too small for the next item (dead space)
        if (post_residual as i64) < (next_item_size as i64) {
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Last item: pure tightness
        score -= 2.0 * (1.0 - (post_residual as f64) / cap);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Prefer bins with below-mean residual (concentrate waste in few bins)
    if bin_residual != bin_capacity {
        score += 0.2 * ((bin_residual as f64) - mean_residual);
    } else {
        // New-bin candidate: penalize mildly so it only wins when fits are bad
        score += 15.0 + 0.1 * (next_item_size as f64);
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual as f64 - item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit = (item_size as f64) / cap;
    let progress = (step_index as f64) / (total_items.max(1) as f64);

    // Core: prefer tight fits (low post_residual), scaled non-linearly.
    let mut score = post * (1.0 + 0.8 * fit * fit);

    // Penalize leaving dead space that cannot fit a typical future item.
    if post > 0.0 {
        let dead = (post / cap).powf(2.5);
        score += 40.0 * dead;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Crowding: mildly favor bins with more alternatives available to keep flexibility.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Global state: if mean residual is high, prefer filling existing bins.
    let mean_r = mean_residual / cap;
    score -= 10.0 * mean_r * (1.0 - fit);

    // New-bin candidate handling: penalize opening a fresh bin, unless existing
    // fits are poor (high post_residual elsewhere) or few bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let escape = (post_residual as f64 / cap).powi(2); // 1.0 for empty bin
        let pressure = (mean_r * 0.5 + (open_bins_count as f64).ln1p() * 0.1).min(1.5);
        score += 30.0 * escape * (1.0 - 0.4 * pressure);
        // Early stream: opening bins is cheap and useful for future flexibility.
        score -= 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let mut score = pr * (1.0 + progress * pr_norm);

    // Penalize dead space more sharply as stream advances
    score += (pr_norm * pr_norm) * cap * (0.5 + progress);

    // Reward tight fits (small post_residual) with smooth exponential term
    score -= (1.0 - pr_norm).exp() * 20.0;

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: mildly penalize unless current residuals are large
    if bin_residual == bin_capacity {
        score += 25.0 - 20.0 * (mean_residual / cap).tanh();
    }

    // Lookahead coupling: if next item fits the post_residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 * (1.0 - (next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        score += 5.0 * (pr_norm);
    }

    // Slight preference to consolidate when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * pr_norm * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: bins whose residual falls into a
    // "reusable" class (divisible into common item sizes) are favored.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        0.0
    } else if pr % 10 == 0 {
        8.0
    } else if pr % 5 == 0 {
        4.0
    } else {
        -6.0
    };
    score -= class_bonus;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size <= pr {
            // next item fits: reward proportionally to how snugly
            score -= 20.0 * (next_item_size as f64 / pr.max(1) as f64);
            // penalize leaving awkward remainders modulo small sizes
            if (pr - next_item_size) % 10 != 0 && (pr - next_item_size) < 10 {
                score += 15.0;
            }
        } else {
            // next item cannot use this residual: penalize large residuals slightly
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current item is large relative
    // to capacity or all open bins fit poorly.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        let pressure = if open_bins_count == 0 {
            -50.0
        } else {
            let avg_fit = mean_residual / cap;
            (avg_fit - fill).max(0.0) * 40.0
        };
        score = cap - (fill * 60.0) - pressure;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild tightening as stream progresses
    score *= 1.0 + 0.05 * (step_index as f64 / (total_items.max(1) as f64));

    // Prefer keeping mean residual balanced
    score += 0.1 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold = 10.0; // gaps <= 10 are near-unusable for typical items
    if post_residual > 0 && (post_residual as f64) <= dead_threshold {
        score += (dead_threshold + 1.0 - post_residual as f64) * 40.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= tightness * 30.0;
    }

    // Penalize leaving a gap just below the next item (blocks the lookahead item).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }
    // Reward leaving a gap that exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Open-bin pressure: discourage scattering across many open bins unless fit is good.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) as f64;
        // Base cost of opening a new bin; cheaper when many bins already open
        // is NOT desired — opening new bins raises pressure, so keep base cost high.
        score += 90.0 + open_bins_count as f64 * 2.0;
        // But if this would create a perfect slot for the next item, soften slightly.
        if next_item_size > 0 && poor_fit == next_item_size as f64 {
            score -= 20.0;
        }
        // Early in stream, opening bins is cheap-ish to build a pool.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
    }

    // Mild pull toward bins with residual close to the item (best-fit flavor).
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += diff * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact lookahead match: post_residual equals next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            // Partial lookahead utility: leftover still usable next step.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Post-residual smaller than next item: dead space unless tiny.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.6 * dead;
        }
    }

    // Reward tight fits relative to current residual (waste minimization).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fit_ratio;

    // Penalize bins far from mean residual (prefer balanced or extreme-tight bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when item is large and no tight fit exists.
    if bin_residual == bin_capacity {
        let large = item_size as f64 / bin_capacity as f64;
        score += 18.0 - 20.0 * large;
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 6.0;
        }
    }

    // Early in stream: slightly prefer opening bins to build diversity.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 5.0 * (0.2 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale waste nonlinearly (quadratic dead-space penalty).
    let waste = post_residual as f64;
    score += 0.35 * (waste / bin_capacity as f64) * waste;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count >= 2 {
        // Mild penalty when many alternatives exist, to break ties toward tightest fit.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Lookahead: if the next item fits into post_residual, reward this placement (pairing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.25 * next_item_size as f64;
        } else {
            // Penalize creating residuals that are too small for typical next items.
            score += 0.15 * (post_residual as f64).max(0.0);
        }
    } else {
        // Last item in stream: just minimize final waste aggressively.
        score += 0.5 * waste;
    }

    // Prefer filling bins with larger residuals (balance across open bins) when
    // mean residual is high; prefer compact bins when mean residual is low.
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.08 * residual_gap;

    // Early in the stream, be more willing to open new bins (exploration):
    // penalize existing bins slightly so a new bin can win early on.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let exploration = (1.0 - progress).max(0.0);
    score += 6.0 * exploration * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Give it a moderate default so it only wins when open bins are bad fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced late in the stream (consolidation phase).
        score = 55.0 + 40.0 * progress;
        // If the item is large, a fresh bin is often good.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
        // If no open bin fits well, allow the new bin.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let mut score = pr
        + 30.0 * norm_pr * norm_pr * (1.0 + progress)
        + 20.0 * norm_pr * progress * progress;

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 25.0 * (nxt - pr) / cap * (1.0 + progress);
        } else {
            // Reward leaving space exactly usable by next item
            score -= 15.0 * (1.0 - (pr - nxt).abs() / cap) * (1.0 - progress);
        }
    }

    // Reward tight fits (small post residual relative to item)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness * tightness;

    // Last-chance bin bonus: avoid opening new bins late
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (0.5 + progress);
    }

    // New-bin candidate: prefer it only when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        score += 15.0 * (1.0 - fragmentation) - 10.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by capacity fractions (0, 1/4, 1/2, 3/4)
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarter = 3 * quarter;

    // Reward bins whose post_residual lands on "usable" harmonic classes
    // (large residuals are still usable; tiny residuals are dead space).
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual >= three_quarter {
        score -= 25.0; // plenty of room left, still flexible
    } else if post_residual >= half {
        score -= 10.0; // can still host medium items
    } else if post_residual >= quarter {
        score += 5.0; // moderate dead space
    } else {
        score += 20.0; // narrow dead space, likely wasted
    }

    // Modulo arithmetic on post_residual: residuals divisible by common item
    // granularities (e.g. multiples of 10 or 5) are more likely reusable.
    if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 4.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward; if it cannot fit, penalize proportionally.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 15.0 * (gap as f64 / bin_capacity as f64).min(1.0);
            // Harmonic bonus: post_residual after next placement in a good class
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 6.0;
            }
        } else {
            score += 12.0; // next item would be stranded if placed here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item is large relative to capacity or few bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Penalize new bins unless the item is big or the stream is early.
        score += 45.0 - 40.0 * item_frac - 15.0 * (1.0 - progress);
        if pressure > 0.0 && mean_residual < item_size as f64 {
            score -= 20.0; // nothing else fits well anyway
        }
    }

    // Slight preference for tighter existing bins among comparable options.
    score += 0.05 * ((bin_residual as f64) - (mean_residual)).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps below the minimum item size are pure waste.
    // Penalize small unusable gaps quadratically, scaled by fraction of capacity wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Tight fits are rewarded: the smaller the post_residual relative to item, the better.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tightness;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead-space penalty grows as stream progresses (fewer future items to fill gaps).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 15.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += 0.6 * open_bins_count as f64 * (1.0 - tightness);

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves another gap; mild reward proportional to fit quality
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use the gap: penalize if gap is small/unusable
            if post_residual < 10 {
                score += 20.0;
            }
        }
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably from the mean
    // (below mean residual = tighter bin, better consolidation).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate handling: empty bin has neutral base cost plus open-bin pressure,
    // so it only wins when existing bins would create severe dead space.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64;
        // But if no existing bin can fit, opening is mandatory-ish; keep score low.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let perfect = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - perfect / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot use the leftover space: penalize dead space.
        score += 12.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Prefer bins whose residual is already below average (tight bins first).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Last-chance bin bonus: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize leaving tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // New-bin candidate: mildly discourage early in stream, encourage if current
    // fit is very poor (large post_residual relative to capacity).
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 - 15.0 * progress - 10.0 * poor_fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual strongly favored.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical items (below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0 + 0.05 * next_item_size as f64;
        } else {
            // Next item won't fit here; penalize leaving awkward residual.
            let gap = (next_item_size as f64 - post_residual as f64).min(50.0);
            score += 0.08 * gap;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Global state: many open bins with large mean residual -> prefer filling existing bins.
    let residual_gap = mean_residual - bin_residual as f64;
    score += 0.05 * residual_gap.max(-30.0);

    // Slight preference for fuller bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Discourage opening new bins when many bins are already open and fit exists.
    if bin_residual == bin_capacity {
        score += 3.0 + 0.15 * open_bins_count as f64;
        // But allow new bin if item is large and would leave a very tight fit nowhere else.
        if item_size >= bin_capacity * 3 / 4 && fitting_bins_count <= 1 {
            score -= 6.0;
        }
    }

    // Mild penalty for very large residual waste relative to mean.
    if post_residual as f64 > mean_residual + 40.0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = x * (1.0 + 0.6 * progress) - 0.9 * x * x + 0.5 * x * x * x;

    // Reward tight fits, penalize dead space more as stream progresses
    let fit = item_size as f64 / bin_residual as f64;
    score -= 2.0 * fit * (1.0 + progress);

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 1.5;
    }

    // Lookahead: reward residual that can host next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 0.8 * (1.0 - (post_residual - nx) / cap) * (1.0 - progress);
        } else {
            score += 0.5 * (nx - pr) / cap;
        }
    }

    // Mild pressure toward consolidating bins
    score += 0.05 * (open_bins_count as f64 / (1.0 + total_items as f64)) * x;

    // Prefer bins near mean residual (balance)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 0.3 * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 bands reward "clean" residuals
    let class = post_residual % 10;
    score += match class {
        0 => -6.0,
        1..=3 => -1.0,
        4..=6 => 1.5,
        _ => 3.0,
    };

    // Dead space penalty: residuals that no typical item (1..=100) can fill well
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: reward if next item fits into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
        // Extra reward for tight harmonic pair (next item nearly fills remainder)
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 4.0;
        }
    } else if next_item_size > post_residual {
        score += 2.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening fresh bins unless residuals are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // open new bin if existing residuals are small/fragmented or many bins open
        score += 14.0 - 10.0 * fragmentation - 4.0 * progress;
        if open_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Prefer bins tighter than the current mean residual (better packing density)
    let dev = mean_residual - post_residual as f64;
    score += 0.3 * dev;

    // Slight preference for larger items into tighter bins (item/balance coupling)
    score -= (item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 40.0 } else if post_residual < 20 { 18.0 } else { 0.0 };
        score += dead * (post_residual as f64 / 10.0);
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage filling.
    score += (open_bins_count as f64) * 0.8;

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // Next item could have fit current residual but not post: mild penalty.
        score += 6.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity - item_size;
    if is_new_bin {
        score -= 10.0;
        // Penalize opening new bins when existing bins are roomy.
        score += mean_residual * 0.35;
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        if fitting_bins_count > 0 {
            score += 12.0;
        }
    }

    // Mild bonus for placing into bins below mean residual (balancing).
    if bin_residual as f64 > mean_residual && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but with a convex
    // penalty so tiny residuals (dead space) are punished extra.
    let pr = post_residual as f64;
    score += (pr * pr) / (bin_capacity as f64);

    // Aggressive 2-step lookahead: strongly reward exact match between
    // post_residual and next_item_size (perfect 2-item completion).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);

        // If next item fits exactly after this placement, huge bonus.
        if post_residual == next_item_size {
            score -= 15.0;
        }
        // If next item cannot fit into this bin's residual either way,
        // slightly penalize leaving a large unusable gap.
        if post_residual > 0 && (post_residual as u32) < next_item_size && post_residual < 10 {
            score += 20.0;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are
    // "almost full" -> good targets; bins far above mean are wasteful targets
    // unless lookahead matches.
    let mean_gap = mean_residual - pr;
    score += 0.3 * mean_gap;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when
    // the item is large relative to capacity or no good fits exist.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        score = 60.0 - 30.0 * fill;
        if next_item_size > 0 && (bin_capacity as i64 - item_size as i64) == next_item_size as i64 {
            score -= 20.0; // fresh bin supports perfect 2-step packing
        }
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Late-stream pressure: consolidate as the stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic bonus as post_residual approaches zero.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that cannot fit even the smallest future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
        // Exact pairing bonus: item + next item perfectly fills this bin.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: mildly discourage opening new bins when
    // open bins exist and can fit, more so late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * progress;
        if fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    // Global pressure: many open bins with large mean residual -> prefer
    // filling existing bins harder; few bins -> allow spreading.
    if open_bins_count > 2 {
        score += (mean_residual - post_residual as f64).max(0.0) * 0.15;
    }

    // Time horizon: early in stream, be pickier about waste (higher weight
    // on post_residual); late in stream, just close gaps.
    score += post_residual as f64 * 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // smooth non-linear coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 + 3.0 * progress * (1.0 - progress));
    score += 12.0 * coupling;

    // reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 10.0 * tightness * tightness * (0.5 + progress);

    // penalize dead space relative to mean residual
    score += 0.5 * (pr - mean_residual).abs() * (1.0 + progress);

    // last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 6.0 * (nxt / cap) * (1.0 - progress);
        } else {
            score += 4.0 * (1.0 - pr / nxt.max(1.0)) * progress;
        }
    }

    // mild penalty for opening a new bin when many bins are open
    if bin_residual == bin_capacity {
        score += 3.0 + 2.0 * (open_bins_count as f64).sqrt() * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: capacity divided into 10 classes of 10.
    let class = (post_residual / 10) as f64;
    score += class * 0.8;

    // Penalize residuals that are dead space: too small for the smallest item (1..=100 unknown, use 10 as typical floor).
    if post_residual < 10 {
        score += 60.0;
    }

    // Reward near-perfect fits (post_residual in lowest harmonic band).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Next item cannot use this bin: penalize leaving medium residuals.
            score += (post_residual as f64) * 0.25;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: make it unattractive unless current bins would waste heavily.
    if bin_residual == bin_capacity {
        score += 35.0;
        // If nothing fits well elsewhere (few fitting bins), allow opening a new bin.
        if fitting_bins_count <= 1 {
            score -= 50.0;
        }
    }

    // Prefer tightest current residual match: reward small bin_residual relative to item.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    // Mean residual coupling: penalize placing into bins whose residual is far above mean (fragmenting).
    let diff = bin_residual as f64 - mean_residual;
    if diff > 0.0 {
        score += diff * 0.15;
    }

    // Stream progression: later in stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * (bin_capacity - bin_residual) as f64 * 0.05;

    // Integer-division threshold on post_residual: residuals in (10, 20] are awkward.
    if post_residual > 10 && post_residual <= 20 {
        score += 12.0;
    }

    // Harmonic bonus: post_residual divisible by 10 is a "clean" class, slightly favored.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize gaps that are too small to be
    // useful for typical future items (unusable dead zones).
    if post_residual > 0 {
        let dead_threshold = 12.0 + 0.15 * mean_residual;
        if (post_residual as f64) < dead_threshold {
            score += 2.5 * (dead_threshold - post_residual as f64);
        }
    }

    // Reward tight fits (waste ratio).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Penalize excessive open bins -> prefer reusing existing bins.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0;
        } else if next_item_size > post_residual {
            // Next item cannot fit here; slightly penalize leaving a gap
            // that is useless for the known next item.
            score += 0.15 * (post_residual as f64 - (next_item_size as f64 - post_residual as f64).abs());
        } else {
            let rem = post_residual - next_item_size;
            if rem <= 10 {
                score -= 6.0;
            }
        }
    }

    // New-bin candidate: make empty bins moderately attractive only when
    // existing fits are poor; otherwise keep them less preferred.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64;
        if fitting_bins_count >= 1 {
            score += 12.0;
        }
    }

    // Mild pressure against keeping many near-empty bins open.
    if (bin_residual as f64) > mean_residual + 20.0 && bin_residual != bin_capacity {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual).
    score -= 12.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // 2-step lookahead: reward if the next item fits into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
        // Perfect chain: post_residual exactly equals next_item_size.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to how close we are.
        let miss = (next_item_size - post_residual) as f64;
        score += 4.0 * (miss / (bin_capacity as f64));
    }

    // Compare post_residual relative to mean residual: avoid leaving this bin
    // far below the average residual (wasted capacity relative to peers).
    let mean_post = mean_residual - item_size as f64;
    if mean_post > 0.0 {
        score += 0.05 * (post_residual as f64 - mean_post);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize creating tiny unusable dead space (< 10, minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Slight preference for filling existing bins over opening new ones
    // as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: penalize large post-residual quadratically.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Last chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // fit is poor or the next item benefits from a fresh bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(2) as f64);
        let mut penalty = 25.0 + 30.0 * (1.0 - progress);
        // If the next item is large and won't fit with current item anywhere,
        // a fresh bin is more attractive.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            penalty += 10.0;
        }
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            penalty -= 12.0; // fresh bin can host the next item after this one
        }
        // Many open bins with slack: prefer reusing them.
        penalty += 0.8 * open_bins_count as f64;
        if mean_residual > item_size as f64 + next_item_size as f64 {
            penalty += 5.0;
        }
        score += penalty;
    }

    // Lookahead synergy: reward bins whose post-residual accommodates the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that blocks the known next item: penalize.
        score += 6.0;
    }

    // Prefer filling bins with larger residual (consolidate slack) slightly.
    score -= 0.05 * bin_residual as f64;

    // Mild penalty for leaving many near-empty bins around.
    if bin_residual > post_residual && post_residual > (bin_capacity / 2) {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let r = bin_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let x = pr / cap; // normalized post residual

    // Base: penalize wasted space, with non-linear (quadratic/cubic) shaping.
    let mut score = pr as f64 * (1.0 + 0.8 * x * x) - 0.35 * cap * x * x * x;

    // Smooth coupling with stream progress: late in the stream, be stricter
    // about leaving dead space (favor tight fits more strongly).
    let tightness = 0.5 + 0.9 * progress * progress;
    score += tightness * (x * (1.0 - x)) * cap * 0.3;

    // Reward filling bins nearly exactly (smooth bump around x ~ 0).
    score -= 12.0 * (-x * 6.0).exp() * (1.0 - 0.5 * progress);

    // Penalize bins that are much tighter than the mean residual (good fits
    // should be preferred relative to average slack).
    score -= 0.15 * (mean_residual - r);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin, scaled by how well it fits.
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * (1.0 - x);
    }

    // Lookahead coupling: if the next item fits the post-residual, reward
    // this placement; otherwise penalize leaving a nearly-next-sized gap.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr as f64 {
            score -= 5.0 * (1.0 - (n / cap).powi(2));
        } else {
            score += 3.0 * ((n - pr as f64) / cap);
        }
    }

    // Mild penalty for spreading across too many open bins when a tight
    // alternative exists (encourages consolidation early).
    score += 0.02 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Residuals that are exact multiples of common small item sizes (10..=20)
    // are more likely reusable, so reward them (subtract).
    let mut reusability = 0.0f64;
    for k in 10..=20u32 {
        if post_residual % k == 0 {
            reusability += 1.0;
        }
    }
    score -= 2.0 * reusability;

    // Integer-division class of post_residual relative to capacity quarters.
    let quarter = bin_capacity / 4;
    let post_class = post_residual / quarter;
    let bin_class = bin_residual / quarter;
    // Penalize landing in a low class (near-full bin with dead space)
    score += (4 - post_class.min(4)) as f64 * 1.5;

    // Perfect fit: post_residual 0 is ideal.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        // Dead space below the minimum item size is unusable.
        score += 30.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how tight the future fit is.
            let tight = (post_residual - next_item_size) as f64;
            score -= 15.0 - 0.2 * tight;
        } else {
            // Next item cannot use this bin's leftover: mild penalty scaled by waste.
            score += 0.1 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin gets a neutral-ish baseline that
    // rises as the stream progresses and open bins are underutilized.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 45.0 + 25.0 * progress + 0.5 * open_bins_count as f64;
        // If mean residual across open bins is large, opening new bins is wasteful.
        score += 0.3 * mean_residual;
        // But if nothing fits well (huge item), allow new bin.
        if item_size > bin_capacity / 2 && fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Modulo-3 harmonic texture on residual to break ties deterministically.
    score += (post_residual % 3) as f64 * 0.25;

    // Slight preference for bins whose residual class matches the item's class.
    if (bin_residual / quarter) == ((item_size + post_residual) / quarter) {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical future items are wasted.
    // Treat post_residual in (0, 10) as fully dead; taper the penalty up to 30.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0 * (10.0 - post_residual as f64) / 10.0;
        } else if post_residual < 30 {
            score += 12.0 * (30.0 - post_residual as f64) / 20.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Tight-fit reward scaled by how well the item fills the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Last-chance bonus: if this is the only bin that can fit, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: penalize using bins when many are open, to consolidate load
    // and encourage closing bins with small residuals rather than spreading.
    score += 0.6 * open_bins_count as f64;

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is an outlier bin; finishing it off is good (reward), spreading into
    // high-residual bins keeps flexibility.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= 0.3 * dev.min(50.0); // below-mean residual bin: prefer filling it
    } else {
        score += 0.15 * (-dev).min(50.0); // above-mean residual: slight penalty
    }

    // Lookahead: if the next item fits into the post_residual, reward; if post_residual
    // is smaller than next item but nonzero, penalize (creates stranded gap).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Penalize the fresh bin mildly, more so late in stream
    // or when many bins are already open (avoid bin proliferation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
        // But if the item is huge and no open bin can take it well, ease penalty.
        if fitting_bins_count == 0 && item_size > bin_capacity / 2 {
            score -= 22.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for dead space that no plausible item can fill.
    if post_residual < 10 {
        score += 200.0;
    }

    // 2-step lookahead: reward exact / near match of post_residual to next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + gap);
        // Perfect chain: next item exactly fills this bin afterwards.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Avoid leaving a residual slightly too small for the next item (dead space).
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Prefer tight fits relative to bin capacity.
    score += 0.3 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Compare against mean residual: placing into a bin with above-average residual
    // keeps fragmented bins from being created.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    // Early in stream, slightly discourage opening too many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress);
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 30.0;

    // Penalize leaving awkward dead space that few typical items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Next item won't fit here; penalize wasted lookahead-compatible space.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Time horizon: late in the stream, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate scoring.
        score += 35.0 * (1.0 - progress);          // cheaper to open early
        score += open_bins_count as f64 * 2.0;      // discourage bin proliferation
        if mean_residual > item_size as f64 {
            score += 20.0;                          // existing bins still have room
        }
        if fitting_bins_count == 0 {
            score -= 100.0;                         // must open a bin
        }
    } else {
        // Existing bin: mild bonus for keeping mean residual balanced.
        score += (bin_residual as f64 - mean_residual).abs() * 0.1;
        // Late stream: strongly prefer filling existing bins.
        score -= progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;
    let mean_norm = mean_residual / cap;
    let next = next_item_size as f64 / cap;

    let mut score = post;

    // smooth non-linear coupling of post residual with stream progress
    score -= 14.0 * (norm_post * norm_post) * (1.0 - progress);
    score += 10.0 * (norm_post * norm_post * norm_post) * progress;

    // reward tight fits via sigmoid-like term
    let tight = 1.0 - norm_post;
    score -= 8.0 * tight * tight * (1.0 - 0.5 * progress);

    // penalize dead space that next item likely cannot use
    let unusable = if post > 0.0 { (next / post).min(1.0) } else { 1.0 };
    score += 6.0 * (1.0 - unusable) * norm_post * (0.5 + progress);

    // penalize when many alternatives exist; reward last-chance bins
    if fitting_bins_count <= 1 {
        score -= 5.0 * (1.0 + progress);
    } else {
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // interaction with mean residual: favor bins below mean (fills laggards)
    score += 4.0 * (mean_norm - norm_post) * (0.3 + 0.7 * progress);

    // mild penalty for opening new bins as stream matures
    if bin_residual == bin_capacity {
        score += 3.0 + 12.0 * progress * progress - 2.0 * (next * 2.0).min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by
    // integer division into size classes (dead-space bands).
    let post_class = post_residual / 10; // classes 0..=10
    let next_class = if next_item_size > 0 { next_item_size / 10 } else { 0 };

    // Reward if the next item's harmonic class fits into the post residual class
    if next_item_size > 0 && next_item_size <= post_residual {
        // Perfect class match: leftover accommodates next item exactly in its band
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - slack / cap);
        if post_residual == next_item_size {
            score -= 25.0; // perfect chaining: zero future waste
        }
    } else if next_item_size > 0 {
        // Next item cannot use this leftover: penalize proportionally to waste
        score += 6.0 + 0.35 * post_residual as f64;
    }

    // Non-linear penalty on unusable dead space: small post residuals are good,
    // but residuals below the minimum item size (1..10) are near-perfect fills.
    if post_residual < 10 {
        score -= 30.0; // nearly closed bin, excellent
    } else if post_residual <= 20 {
        score -= 8.0;
    } else {
        // dead-space grows superlinearly beyond mid-range leftovers
        let frac = post_residual as f64 / cap;
        score += 20.0 * frac * frac;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate handling: only attractive when open bins are congested
    // (few fitting bins) or mean residual is too small to matter.
    if bin_residual == bin_capacity {
        let congestion = if fitting_bins_count == 0 { 1.0 } else { 1.0 / fitting_bins_count as f64 };
        let mean_useful = mean_residual / cap;
        score = 12.0 + 40.0 * (1.0 - congestion) * (1.0 - mean_useful.clamp(0.0, 1.0));
        // Early in the stream, opening fresh bins is cheap and keeps options open
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Mild preference for fuller bins as the stream matures (consolidation phase)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - post_residual as f64 / cap);

    // Tie-break: harmonic parity of post_residual classes — prefer leftovers
    // in classes that historically chain well (multiples of 10 and 25-ish bands)
    if post_class % 2 == 0 && post_residual > 0 {
        score -= 1.5;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 2.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item (min size 1,
    // but practically unusable below ~10) are heavily penalized.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual) as f64;
    }
    // Perfect fit is the ideal outcome.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize residuals that cannot fit the known next item (lookahead-aware dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bins pressure: discourage opening new bins when many bins are open
    // and this bin's residual is reasonably large.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin penalty grows with number of open bins; also penalize if
        // existing residual space is abundant.
        score += 20.0 + 4.0 * open_bins_count as f64 + 0.3 * mean_residual;
        // Allow new bin if current item leaves a large residual that pairs with lookahead.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
    } else {
        // Mild reward for packing into existing bins as stream progresses.
        score -= 2.0 + 0.5 * (step_index as f64 / total_items.max(1) as f64);
        // Prefer bins whose residual is close to item size (tight fit).
        score += 0.15 * ((bin_residual - item_size) as f64 - post_residual as f64).abs();
    }

    // General preference for low post_residual, nonlinearly weighted.
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // accommodates the next item (perfect chaining).
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            // Perfect 2-item fill: strongly reward.
            score -= 60.0;
        } else if diff > 0 {
            // Next item fits with slack: mild reward proportional to closeness.
            score -= 25.0 * (1.0 - diff as f64 / bin_capacity as f64);
        } else {
            // Next item would not fit: penalize wasted-looking residual,
            // worse when residual is small-but-unusable.
            let unusable = (-diff) as f64;
            score += 15.0 * (1.0 - unusable / bin_capacity as f64);
        }
    }

    // Relative-to-mean coupling: prefer bins that reduce residual dispersion.
    score += 0.6 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a new bin, but relax late in the
    // stream or when many bins are open and mean residual is high.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 35.0;
        if next_item_size > 0 && next_item_size >= item_size {
            // Next item is bigger: fresh bin helps chain large items.
            new_bin_penalty -= 20.0;
        }
        if mean_residual > 40.0 && open_bins_count > 3 {
            new_bin_penalty -= 10.0;
        }
        new_bin_penalty *= 1.0 - 0.3 * progress;
        score += new_bin_penalty;
    }

    // Prefer filling already-open bins over spreading across many.
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward low post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize large dead space beyond next item's size (unusable gap).
    if next_item_size > 0 {
        if post_residual > next_item_size {
            score += 0.35 * (post_residual as f64 - next_item_size as f64);
        } else if post_residual == next_item_size {
            score -= 25.0; // perfect pair with lookahead item
        } else {
            score += 4.0; // item blocks the next item's fit
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate handling: discourage opening a new bin unless
    // current item is large and no decent fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 12.0 + 10.0 * progress;
        if item_size > bin_capacity / 2 {
            score -= 8.0;
        }
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a bin
        }
    }

    // Prefer filling bins that deviate from mean residual toward fullness.
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Mildly discourage scattering across many open bins when item is small.
    if item_size < 30 {
        score += 0.05 * open_bins_count as f64;
    }

    // Time horizon: later in stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, large dead space is more costly (less time to fill it).
    let decay = 1.0 + 1.5 * progress * progress;
    score += 0.35 * pr * pr / cap * decay;

    // Reward near-perfect fits with a smooth quadratic dip.
    let tight = 1.0 - (pr / cap);
    score -= 6.0 * (1.0 - tight * tight) * (1.0 - progress * 0.5);

    // Penalize when this bin is much worse than average fit.
    score += 0.5 * (pr - mean_residual).abs();

    // Lookahead: if next item could use the post residual, reward preserving it.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            score -= 2.0 * (1.0 - (pr - n) / cap) * (1.0 - progress);
        } else {
            score += 1.0 + 0.02 * (n - pr);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 - progress * 0.5);
    }

    // New empty bin candidate: penalize mildly early, more when many bins open,
    // but reward it when the item is large and fit elsewhere would leave big waste.
    if bin_residual == bin_capacity {
        score += 4.0 + 0.5 * open_bins_count as f64;
        score -= 0.15 * item_size as f64 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer small post_residual (tight fit).
    score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Dead-space classes: residuals in (0, 10] are nearly unusable -> heavy penalty.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0;
    }
    // Perfect fit or residual exactly matching common item sizes is gold.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual % 10 == 0 {
        score -= 20.0;
    }

    // Harmonic thresholds: residual in [eighth, quarter) is a "good zone".
    if post_residual >= eighth && post_residual < quarter {
        score -= 10.0;
    } else if post_residual >= quarter && post_residual < 2 * quarter {
        score -= 5.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Reward proportional to how well next item uses the leftover.
            let fill = next_item_size as f64 / (post_residual as f64).max(1.0);
            score -= 30.0 * fill;
            // Penalize leaving a sliver the next item barely misses.
            if next_item_size > post_residual && next_item_size - post_residual <= 5 {
                score += 15.0;
            }
        } else if next_item_size > post_residual && post_residual > 0 && next_item_size - post_residual <= 5 {
            // Near-miss: this bin's leftover is just too small for next item.
            score += 12.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current item is huge relative to
    // typical residuals or no open bin is a good fit. Penalize default opening.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: keep it high unless placement elsewhere is bad.
        score = cap * 0.9;
        // Large items deserve a fresh bin more often.
        if item_size >= 60 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative
        } else if fitting_bins_count == 1 {
            score += 30.0; // an open bin can take it; prefer filling it
        }
        // Late in the stream, consolidate more aggressively.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    }

    // Mild pressure to use bins with small mean residual (consolidation).
    score += 0.05 * mean_residual;

    // Slight preference for bins with many fitting alternatives to stay flexible.
    if fitting_bins_count > 3 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (size 1..=10) are pure waste; penalize them quadratically.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 8.0
            + (dead_threshold - post_residual) as f64 * (dead_threshold - post_residual) as f64 * 4.0;
    } else if post_residual < 20 {
        // Marginal zone: residual barely usable, mild penalty.
        score += (20 - post_residual) as f64 * 1.5;
    } else {
        // Larger usable residuals are mildly rewarded so big gaps stay attractive
        // for future items.
        score -= (post_residual.min(60)) as f64 * 0.15;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly reward this placement (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item cannot use what's left: the residual becomes dead space
            // unless some future item fits; penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when few are open,
    // but encourage using existing bins when many are already open (avoid opening
    // extra bins unnecessarily).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.0 - progress) * 0.4;
    if bin_residual != bin_capacity {
        score -= open_bins_count as f64 * 0.8;
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource; make it
    // attractive only when no open bin offers a good fit (mean residual small
    // relative to item) — otherwise keep existing bins preferred.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 25.0 + open_bins_count as f64 * 1.2;
        // If open bins are mostly too full (mean residual near item size or less),
        // opening new is justified: reduce penalty.
        let tight = mean_residual < item_size as f64 * 1.5;
        if tight {
            score -= 40.0;
        }
        // Late in the stream, avoid opening bins for marginal gains.
        score += progress * 10.0;
    }

    // Mild tightness reward relative to mean residual of open bins.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base fit quality: waste ratio relative to capacity
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Tight fits are excellent
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let gap = if post_residual as i64 - next_item_size as i64 >= 0 {
            (post_residual as i64 - next_item_size as i64) as f64
        } else {
            1000.0 + (next_item_size as i64 - post_residual as i64) as f64
        };
        score += 0.35 * gap;
        if post_residual == next_item_size {
            score -= 45.0; // perfect chain
        } else if gap <= 5.0 {
            score -= 18.0;
        }
        // penalize leaving residuals that are too small to ever be useful
        if post_residual > 0 && post_residual < 10 && gap > 100.0 {
            score += 20.0;
        }
    }

    // Relative to mean residual: prefer using fuller-than-average bins
    score += 0.5 * (mean_residual - bin_residual as f64).max(-50.0);

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: keep it available unless current bin is a great fit
    if bin_residual == bin_capacity {
        score += 55.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 10.0;
        }
    }

    // Late in stream: consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Base: prefer minimal post residual, with non-linear amplification of dead space
    let dead_frac = post / cap;
    score += 30.0 * dead_frac * dead_frac;

    // Reward tight fits strongly (item nearly fills the bin)
    let fit_tightness = 1.0 - (bin_residual as f64 - item) / cap.max(1.0);
    score -= 20.0 * fit_tightness * fit_tightness;

    // Lookahead: if next item fits exactly in post residual, big reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let slack = (post - nxt) / cap;
            score -= 15.0 * (1.0 - slack);
        } else {
            // next item won't fit here; mild penalty proportional to how much it overflows
            let over = (nxt - post) / cap;
            score += 8.0 * over;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many fitting bins: mild penalty to encourage consolidation into fewest bins
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Global state coupling: if mean residual is high, prefer filling existing bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (mean_residual / cap) * (5.0 + 10.0 * progress);

    // Late in stream: be more aggressive about closing bins tightly
    score -= 10.0 * progress * (1.0 - dead_frac);

    // New-bin candidate handling: penalize opening a new bin unless existing fits are bad
    if bin_residual == bin_capacity && item < bin_capacity {
        let new_bin_waste = post / cap;
        score += 18.0 + 40.0 * new_bin_waste;
        // If no existing bin fits, allow opening (fitting_bins_count includes only open bins here)
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Early stream: opening bins is cheaper
        score -= 12.0 * (1.0 - progress);
    }

    // Slight preference for bins with residual close to item (exact matching)
    let diff = (bin_residual as f64 - item).abs();
    score += 0.05 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64 / cap;
    let it = item_size as f64 / cap;

    // Base: minimize post residual (tight packing)
    let mut score = pr * pr * 100.0 + pr * 40.0;

    // Smooth polynomial coupling with stream progress:
    // early on, tolerate loose fits; late, demand tightness
    let tightness = 0.5 + 2.0 * progress * progress;
    score *= tightness;

    // Non-linear interaction: large items penalize wasted space more
    score += (pr * it) * 30.0;

    // Reward using existing bins, especially when scarce
    if bin_residual != bin_capacity {
        let scarcity = 1.0 / (1.0 + open_bins_count as f64);
        score -= 12.0 + 20.0 * scarcity;
    }

    // Last-resort bin gets strong bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr * cap {
        score -= 10.0 + 8.0 * (1.0 - pr);
    } else if next_item_size > 0 {
        // penalize leaving residual that next item nearly-but-not fits
        let near = (pr * cap - next_item_size as f64).abs();
        if near < 10.0 {
            score += 6.0 * (1.0 - near / 10.0);
        }
    }

    // Penalize bins far from mean residual (fragmentation smoothing)
    score += ((bin_residual as f64 - mean_residual) / cap).abs() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: rewards residuals that are "usable"
    // by common item sizes. Classes based on integer division by 10 and 20.
    let post = post_residual;
    let class10 = post % 10;
    let class20 = post % 20;

    // Perfect fit bonus
    if post == 0 {
        score -= 1000.0;
    }
    // Residuals in [1,9] are nearly dead space unless they match small items
    else if post < 10 {
        score += 40.0;
    }
    // Harmonic sweet spots: residual that a typical item (10..80) can fill well
    if post >= 10 && post <= 80 {
        score -= 15.0;
        // Reward residuals aligned to multiples of 10/20 (harmonic classes)
        if class10 == 0 { score -= 8.0; }
        if class20 == 0 { score -= 6.0; }
        // Penalize awkward non-aligned residuals
        else if class10 >= 1 && class10 <= 3 { score += 6.0; }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 120.0;
        } else if next_item_size <= post {
            let nxt_post = post - next_item_size;
            score -= 10.0;
            if nxt_post % 10 == 0 { score -= 10.0; }
            if nxt_post < 10 { score += 15.0; }
        } else {
            // Next item won't fit here; slight penalty proportional to gap
            score += (next_item_size - post) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of the
    // current bin. Penalize new bins unless existing bins are badly fragmented.
    if bin_residual == bin_capacity {
        // Base penalty: waste of a fresh bin
        score += 50.0;
        // If many open bins with high mean residual, opening a new bin is fine
        if open_bins_count > 0 && mean_residual > (item_size as f64) * 1.5 {
            score -= 80.0;
        }
        // Late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
    }

    // Prefer tighter bins (small residual before placement) mildly
    score += (bin_residual as f64) * 0.1;

    // Mild pressure against proliferating bins
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fill
    }

    // Reward tight fits relative to bin capacity.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // Lookahead: reward residuals that can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0; // dead space relative to lookahead
    }

    // Last chance: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage scattering when many bins are open.
    score += 0.6 * open_bins_count as f64;

    // Prefer bins with residual close to the mean (balanced packing),
    // and mildly prefer opening new bins early in the stream.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 - 15.0 * progress; // new bin cost shrinks over time
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else {
        // Dead-space penalty: small post_residual is good, large is bad (quadratic).
        score += (post_residual as f64) * (post_residual as f64) * 0.01;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // Reward proportionally to how well the next item would fill the leftover.
            let fill = nxt / post_residual as f64;
            score -= 50.0 + 100.0 * fill;
        } else {
            // Leftover too small for the next item: penalize as likely dead space.
            score += 30.0;
        }
    }

    // Compare against mean residual across open bins: prefer bins tighter than average.
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        let diff = res - mean_residual;
        score += diff * 0.5;
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 80.0 + mean_residual * 0.2;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Early in the stream, slightly prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post residuals (non-linear).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Penalize dead space that is too small to ever hold a typical item,
    // but only when it cannot pair with the lookahead item.
    let pairs_with_next = next_item_size > 0 && next_item_size <= post_residual;
    if !pairs_with_next && post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward residuals that exactly or closely fit the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Residual after placement too small for next item: mild penalty.
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so when
    // good alternatives exist or the stream is late.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 20.0 + 30.0 * progress;
        if fitting_bins_count > 0 {
            new_bin_penalty += 15.0 * (fitting_bins_count as f64).sqrt();
        }
        // If open bins have plenty of mean residual, prefer using them.
        if mean_residual > item_size as f64 * 1.5 {
            new_bin_penalty += 10.0;
        }
        // Early stream with few bins: opening a bin is cheap (keeps options open).
        if progress < 0.2 && open_bins_count < 3 {
            new_bin_penalty -= 15.0;
        }
        score += new_bin_penalty;
    }

    // Mild pressure toward consolidating into bins with larger residuals
    // (keeps small residual bins from lingering as waste).
    score += 0.05 * (bin_capacity as f64 - bin_residual as f64);

    // Slight global-load coupling: many open bins -> favor filling existing ones.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = 1.0 - pr / cap;

    // Non-linear reward for tight fits, stronger as stream progresses
    let tightness = fit_frac * fit_frac * (1.0 + 40.0 * progress);
    score -= tightness;

    // Penalize small residuals that waste space (non-linear dead-space term)
    let dead = (pr / cap) * (pr / cap) * (30.0 + 60.0 * progress);
    score += dead;

    // New-bin candidate penalty: discourage opening bins when fits exist,
    // unless residual would be very small (near-perfect fill)
    let is_new = (bin_residual == bin_capacity) as f64;
    let new_penalty = is_new * (15.0 + 30.0 * (1.0 - fit_frac) * (1.0 - fit_frac));
    score += new_penalty;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward residual that can still host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (nx / cap) * (1.0 - 0.5 * progress);
        } else {
            score += 5.0 * (1.0 - pr / nx.max(1.0));
        }
    }

    // Mild coupling with mean residual: prefer bins deviating from mean
    score += 0.1 * (mean_residual - pr).abs();

    // Slight crowding penalty to balance open bins
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: perfect fits (0) and small residues are gold.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // exact fill
    } else if pr <= 10 {
        score -= 25.0;
    } else {
        // Penalize residues in "dead zones" that few item sizes can fill.
        // Class boundaries via integer division thresholds.
        let class = pr / 10; // 1..=9
        score += match class {
            1 => 5.0,
            2 => 12.0,
            3 => 18.0,
            4 => 26.0,
            5 => 22.0, // half-full residue is reusable
            6 => 20.0,
            7 => 16.0,
            8 => 10.0,
            _ => 4.0,
        };
    }

    // Modulo coupling: residues divisible by common item sizes (10,20,25,50) are reusable.
    if pr % 10 == 0 { score -= 8.0; }
    if pr % 25 == 0 { score -= 6.0; }
    if pr % 50 == 0 { score -= 6.0; }

    // Lookahead: reward if next item fits the post residual exactly or well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap);
        } else {
            score += 6.0; // next item won't fit here; slight penalty
        }
        // Harmonic class of next item: big items prefer large residues.
        if next_item_size > 60 && pr < next_item_size as u32 {
            score += 8.0;
        }
        let _ = nxt;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current fit is terrible.
    if bin_residual == bin_capacity {
        let fit_quality = post / cap; // = 1 - item/cap
        score = 40.0 + 30.0 * fit_quality;
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing big items with fresh bins
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64 * (post / cap);

    // Progress-aware tightening: later in stream, prefer tighter fills.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post / cap) * 10.0;

    // Nudge toward bins near mean residual (balance exploitation).
    score += 0.1 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Exact fit is the gold standard: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        // Tiny nonzero gap is likely unusable dead space: heavy penalty.
        score += 45.0 - (post_residual as f64) * 2.0;
    } else if post_residual < 20 {
        // Moderately small gap: mild penalty scaled by gap size.
        score += (20 - post_residual) as f64 * 1.5;
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Leftover space can host the next item: reward proportionally.
            score -= 6.0 + (next_item_size as f64) * 0.1;
        } else if post_residual > 0 {
            // Leftover too small for the next item: dead-space risk penalty.
            score += 8.0;
        }
    }

    // --- Open-bins pressure ---
    // Opening a new bin is penalized increasingly with the number of open bins,
    // discouraging bin proliferation when a reasonable fit exists.
    if bin_residual == bin_capacity {
        let pressure = 12.0 + open_bins_count as f64 * 2.5;
        // Large items are acceptable in a fresh bin (hard to place elsewhere).
        let large_item_relief = if item_size >= 60 { 10.0 } else if item_size >= 40 { 4.0 } else { 0.0 };
        // If no open bin fits at all, opening a bin is unavoidable: relieve pressure.
        let no_fit_relief = if fitting_bins_count == 0 { 25.0 } else { 0.0 };
        score += pressure - large_item_relief - no_fit_relief;
    }

    // --- Last-chance bin bonus ---
    // If this is the only open bin that fits the item, strongly prefer using it
    // over wasting it and opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // --- Mild global tie-breaker ---
    // Prefer bins whose residual deviates favorably from the mean residual
    // (i.e., tighter-than-average bins get a small extra nudge).
    score -= 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when post_residual exactly accommodates next item,
    // or when next item fills the remainder perfectly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 500.0;
            }
        } else {
            // leftover too small for next item: penalize dead space
            score += 40.0;
        }
    }

    // Penalize residuals that are small and likely unusable (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    } else if post_residual < 20 {
        score += 20.0;
    }

    // Compare post_residual against mean residual across open bins:
    // prefer bins whose leftover stays near/above the mean (keeps bins usable).
    let pr = post_residual as f64;
    let dev = (pr - mean_residual).abs();
    score += 0.5 * dev;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        score += 300.0;
        if fitting_bins_count <= 1 {
            score -= 350.0;
        }
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 50.0 * (1.0 - progress);
    }

    // Mild penalty for hoarding too many open bins.
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are great: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if the next item can fit into the post-residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 + 0.15 * (post_residual as f64 - next_item_size as f64);
    } else if next_item_size > post_residual {
        // Next item won't fit here afterwards; penalize slightly to prefer bins
        // that keep useful space for the lookahead.
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize bins far from mean residual (fragmentation signal).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (bin_residual < bin_capacity) as i32 as f64;

    // Many open bins: discourage opening yet another bin implicitly via
    // rewarding use of existing bins when open_bins_count is high.
    if bin_residual < bin_capacity {
        score -= 0.02 * open_bins_count as f64;
    } else {
        // New-bin candidate: mild penalty unless residual would be very usable.
        score += 2.0 - 0.03 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - pr / cap;
    // non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = t * t * (3.0 - 2.0 * t); // smoothstep
    score += 4.0 * poly * (pr * pr) / cap;
    score -= 2.0 * poly * fill * fill * cap * 0.05;
    // reward tight fits more strongly as stream advances
    score -= poly * (item_size as f64) * 0.3;
    // penalize leaving residuals that are awkward relative to mean residual
    let diff = pr - mean_residual;
    score += 0.05 * diff * diff / (1.0 + t);
    // lookahead coupling: favor bins whose post residual suits the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (pr - n).abs();
        score -= 0.5 * poly * (1.0 - gap / cap);
        if pr < n { score += 0.3 * poly * (n - pr); }
    }
    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 - poly) + 2.0 * poly;
    }
    // slight penalty for spreading across many bins early
    score += 0.1 * (open_bins_count as f64) * (1.0 - poly);
    // new-bin candidate: discourage unless residual advantage is large
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * poly * fill;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues divisible into nice halves/quarters
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward post-residuals that form harmonic classes: exact halves/quarters of capacity
    let half = cap / 2.0;
    let quarter = cap / 4.0;
    let dist_half = (pr - half).abs();
    let dist_quarter = (pr - quarter).abs();
    let dist_three_quarter = (pr - 3.0 * quarter).abs();
    let harmonic_bonus = (dist_half.min(dist_quarter).min(dist_three_quarter) / cap).exp() - 1.0;
    score -= 8.0 * harmonic_bonus;

    // Penalize dead space: post_residual too small to fit plausible future items
    if pr < 10.0 && pr > 0.0 {
        score += 6.0;
    }

    // Integer division threshold: post_residual classed by 10-size buckets
    let bucket = post_residual / 10;
    if bucket <= 1 {
        score += 3.0; // nearly unusable residue
    } else if bucket >= 8 {
        score -= 2.0; // roomy bin
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 2.0 * ((next_item_size - post_residual) as f64 / cap);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when no good existing fit
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let bad_existing = (mean_residual - item_size as f64).abs() / cap;
        score = cap - 20.0 * pressure + 12.0 * (1.0 - pressure) * (0.5 + bad_existing);
        if next_item_size > item_size && next_item_size > 0 {
            score -= 5.0; // big next item favors fresh bin
        }
    }

    // Mild preference for filling bins tighter as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (cap - pr) * 0.02;

    // Tie-break: prefer bins whose residual is close to item (tight fit)
    score += (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest plausible item (<= 10) are pure waste -> heavy penalty.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual < 35 {
        score += 5.0;
    } else {
        // Larger usable residuals are mildly rewarded (more future utility).
        score -= (post_residual as f64) * 0.15;
    }

    // Reward tight fits: item filling most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // Dead-space coupling: penalize when post_residual cannot host the
    // lookahead item but is too large to ignore (wasted gap).
    if next_item_size > 0 && next_item_size > post_residual {
        score += (next_item_size - post_residual) as f64 * 0.25;
    }

    // Open-bin pressure: discourage spreading across many bins unless the
    // fit is genuinely tight.
    score += (open_bins_count as f64) * 0.6;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin is attractive when no open
    // bin offers a decent fit; make the empty-bin score depend on mean
    // residual so poorly-filled fleets favor opening fresh capacity.
    if bin_residual == bin_capacity {
        score = 55.0 - mean_residual * 0.35 - fill_ratio * 0.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    } else {
        // Compare against mean residual: placing into a bin with less
        // residual than average concentrates waste, penalize slightly.
        if (bin_residual as f64) < mean_residual {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: next item fits snugly (small slack after the lookahead item).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Penalize if the lookahead item cannot fit in the remaining space (dead end risk).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0 + 0.3 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits relative to current mean residual across open bins.
    score -= (post_residual as f64 - mean_residual) * 0.35;

    // Small unusable residuals are bad: penalize very tight leftover space.
    if post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.35 + 0.3 * progress };
        score += 80.0 * pressure + 0.2 * open_bins_count as f64;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 25.0; // room for the lookahead pair in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream [0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Relative tightness of the fit: small post_residual relative to capacity is good.
    let tightness = post_residual as f64 / bin_capacity as f64;

    // Reward tight fits strongly (subtract).
    score -= 40.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize leaving residual that is too small to ever be useful
    // (dead space below the minimum plausible item size ~ 1..100 unknown, use mid anchor).
    if post_residual < 25 {
        score += 18.0 * (25.0 - post_residual as f64) / 25.0;
    }

    // Lookahead coupling: if the next item fits in the post residual, reward heavily.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 25.0 * (1.0 - progress);
            // extra reward if next item exactly consumes residual
            if next_item_size as u32 == post_residual {
                score -= 15.0;
            }
        } else {
            // next item won't fit: mild penalty scaled by how much it overshoots
            let overshoot = (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
            score += 10.0 * overshoot * (1.0 - progress);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate handling: opening a new bin is only attractive when
    // no good fit exists. Base penalty grows with number of open bins.
    if bin_residual == bin_capacity {
        score += 35.0 + 4.0 * open_bins_count as f64;
        // But if this item is huge and would leave a very tight fit elsewhere,
        // the new-bin penalty already stands; if item is small, discourage more.
        if item_size < 40 {
            score += 20.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        score += 25.0 * progress;
    } else {
        // Fitting into an existing bin is generally good; reward modestly.
        score -= 8.0;
    }

    // Prefer filling bins whose residual deviates from the mean (reduce variance):
    // if this bin has less residual than average, it is "harder to fill", use it.
    let dev = bin_residual as f64 - mean_residual;
    if dev < 0.0 {
        score -= 6.0 * (-dev / bin_capacity as f64).min(1.0);
    } else {
        score += 3.0 * (dev / bin_capacity as f64).min(1.0);
    }

    // Many open bins: encourage closing them out by using high-residual bins less
    // and tight bins more (already covered), plus slight global pressure.
    score += 0.5 * open_bins_count as f64 * tightness;

    // Small noise-free tie-breaker: prefer earlier-created bins implicitly via
    // residual ordering; add tiny monotone term on item_size to break ties.
    score += item_size as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize large post-residual, with non-linear shrinkage
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: late in the stream, tolerate residual less
    let prog_term = 1.0 + 0.5 * progress * (1.0 - progress) * 4.0; // peaked mid-stream
    score *= prog_term;

    // Reward tight fits (small post residual) non-linearly
    score -= 12.0 * (-norm_pr * 6.0).exp();

    // Lookahead: reward if next item fits in post residual
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 8.0 * (pr - next_item_size as f64) / cap;
        } else {
            score += 4.0 * (next_item_size as f64 - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to use it rather than open new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Penalize opening a new bin when good fits exist among many open bins
    if bin_residual == bin_capacity {
        score += 6.0 + 0.3 * open_bins_count as f64;
        // New bin more attractive if mean residual across open bins is small
        score -= 0.05 * mean_residual;
    }

    // Mild penalty for many open bins (fragmentation)
    score += 0.02 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize into capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    // Integer-division thresholds on post_residual
    let q = post_residual / 10; // decade class

    // Reward small post_residual, but with harmonic (modular) structure:
    // residuals that are "nice" multiples (usable by common item sizes) are better.
    let harmonic_bonus = match post_residual % 10 {
        0 => 6.0,
        5 => 3.0,
        _ => 0.0,
    };
    score -= harmonic_bonus;

    // Dead-space penalty: tiny residuals are wasted space
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Penalize residuals that no typical item can use: below the smallest item
    if post_residual < 1 {
        score -= 15.0; // perfect fit is excellent
    }

    // Non-linear curvature: prefer residuals in the "sweet spot" where the next
    // item can fit exactly or nearly
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits here: strong reward, scaled by tightness of fit
            let tight = (post_residual - next_item_size) as f64;
            score -= 30.0 - tight * 0.4;
        } else {
            // next item won't fit here: mild penalty proportional to overflow
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    // Recognizable by bin_residual == bin_capacity and post_residual == capacity - item.
    if bin_residual == bin_capacity {
        // Opening new bin leaves (100 - item) residual; judge by how "usable" it is.
        // If existing bins fit the item decently, discourage a new bin.
        if fitting_bins_count > 0 {
            let best_existing = mean_residual.max(0.0);
            // If mean residual across open bins can accommodate item comfortably,
            // opening a new bin is wasteful.
            if best_existing >= item_size as f64 {
                score += 35.0 + 0.5 * open_bins_count as f64;
            } else {
                score += 10.0;
            }
        } else {
            score -= 20.0; // forced: no open bin fits
        }
        // Early in the stream, opening bins is cheaper (more items to come to fill them)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
    }

    // Coupling with mean residual: bins far from the mean residual are less
    // attractive to keep the pool homogeneous
    score += 0.1 * ((post_residual as f64 - mean_residual).abs());

    // Modular class coupling between item size and residual decade
    let item_class = item_size % 20;
    let res_class = post_residual / 20;
    if item_class == 0 && res_class >= 1 {
        score -= 4.0;
    }

    // Slight preference for filling bins that are already heavily loaded
    score -= 0.2 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64 * 10.0;

    // Quantized harmonic tie-breaker on decade class
    score -= (q as f64).sin().abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are pure waste.
    let min_gap = 1u32;
    if post_residual < min_gap && post_residual > 0 {
        score += 1000.0; // tiny sliver gap -> severe penalty
    }

    // Reward exact/near-exact fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Penalize "awkward" gaps: too small for next item, unusable dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 35.0;
    }

    // Reward bins that can still accommodate the lookahead item (chain fits).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are already open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 * (0.8 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; only attractive when open bins fit poorly.
        score += 30.0 + bin_pressure;
        // New bin is good if the item leaves a large, reusable residual and current bins are tight.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 20.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    } else {
        // Fitting into an existing bin: reward spreading load when mean residual is high.
        if (bin_residual as f64) > mean_residual {
            score -= 8.0;
        }
    }

    // Prefer filling fuller bins (best-fit flavor) with a non-linear term.
    score -= (bin_residual as f64 / bin_capacity as f64).powi(3) * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Near match: next item still fits after this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 / (1.0 + slack / 10.0);
    }
    // Penalize creating dead space that next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Compare against mean residual: bins already below mean waste less by filling.
    let mean_gap = mean_residual - post_residual as f64;
    score -= 0.3 * mean_gap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: keep it moderately attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Early in stream, opening bins is cheap; later, discourage sprawl.
        let progress = step_index as f64 / total_items as f64;
        score += 10.0 * progress;
        // If many bins already fit, opening a new one is wasteful.
        score += 3.0 * fitting_bins_count as f64;
    }

    // Tight fits (small post residual) are generally good.
    if post_residual <= 10 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: small post_residual is already the base; add extra bonus
    // when post_residual is very small (near-perfect packing).
    let tight_bonus = 8.0 * (-post_residual as f64 / 12.0).exp();
    score -= tight_bonus;

    // Penalize leaving residuals that are awkward: residuals just above small
    // item sizes are "dead-ish" space. Penalize if post_residual is small but
    // nonzero in a way unlikely to be filled (e.g. 1..=5).
    if post_residual > 0 && post_residual <= 5 {
        score += 6.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves another residual; mild reward scaled by fit quality
            let inner = post_residual - next_item_size;
            score -= 6.0 * (-inner as f64 / 10.0).exp();
        } else {
            // Next item cannot use this residual; penalize proportionally to wasted space
            let gap = next_item_size - post_residual;
            score += 0.15 * gap as f64;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized, more so when many bins are open
        // (consolidation pressure) and early in the stream.
        score += 25.0 + 2.0 * open_bins_count as f64 + 10.0 * (1.0 - progress);
        // But if no open bin fits well (post_residual here equals capacity - item),
        // this penalty competes naturally with bad fits elsewhere.
        // Slight relief if mean residual across open bins is tiny (all nearly full).
        if mean_residual < item_size as f64 {
            score -= 12.0;
        }
    } else {
        // Favor bins with residual below the mean residual (better consolidation),
        // i.e. bins that are more filled than average.
        let fill_gap = mean_residual - bin_residual as f64;
        score -= 0.3 * fill_gap;
    }

    // Mild global pressure: as the stream progresses, prefer filling existing
    // bins tighter (reduce fragmentation).
    score += 4.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let r = post_residual as f64 / bin_capacity as f64;
    let norm_mean = mean_residual / bin_capacity as f64;

    // Smooth non-linear coupling: quadratic waste penalty modulated by stream progress
    score += 12.0 * r * r * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 8.0 * (1.0 - r) * (1.0 - r) * progress;

    // Penalize bins whose residual deviates from the mean residual (fragmentation)
    score += 3.0 * (r - norm_mean) * (r - norm_mean);

    // Dead-space penalty: residual too small to be useful for typical items
    let uselessness = (1.0 - r / 0.2).max(0.0).min(1.0);
    score += 15.0 * uselessness * uselessness;

    // Last-chance bin bonus: only fitting bin left
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // Lookahead: favor residual that could host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 >= nx {
            score -= 5.0 * (1.0 - ((post_residual as f64 - nx) / bin_capacity as f64));
        } else {
            score += 4.0;
        }
    }

    // Mild new-bin aversion growing with open bins (encourage consolidation early)
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    // Favor larger residual bins when item is large (fit feasibility smoothing)
    score -= 2.0 * (item_size as f64 / 100.0) * r;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: quantize dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Penalize residuals in "unusable" classes (too small for typical items 1..100
    // relative to unknown distribution -> use granularity thresholds).
    let class = (post_residual / 10).min(10);
    score += match class {
        0 => -50.0,                       // residual < 10 : nearly perfect
        1 => -20.0,                       // small but flexible
        2 | 3 => 0.0,                     // mid classes: neutral
        4 | 5 | 6 => 15.0,                // awkward dead space band
        _ => 30.0,                        // large residual: wasteful unless needed
    };
    // Fine-grain harmonic modulation via modulo structure.
    score += ((post_residual % 10) as f64) * 0.5;
    score -= (frac * 0.0) + (1.0 - frac) * 5.0;

    // Lookahead coupling: reward residuals that can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            score -= 40.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; residual becomes dead weight for the horizon.
            score += 25.0;
        }
    } else {
        // Last item: just minimize leftover.
        score += post_residual as f64 * 2.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.6 + 60.0;
        if fitting_bins_count == 0 {
            score -= 500.0; // must open
        } else if next_item_size > 0 && post_residual >= next_item_size {
            // Fresh bin can host the next item too: attractive.
            score -= 120.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
    }

    // Mild pressure against bin proliferation.
    score += open_bins_count as f64 * 0.3;

    // Mean-residual context: if this bin is far below mean residual, it's a tighter fit -> reward.
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item (1..=100 interface, but typical items >= 10)
    // are pure waste. Penalize gaps below the "usable threshold" heavily.
    let usable_threshold = 10u32;
    if post_residual > 0 && post_residual < usable_threshold {
        score += 60.0 * (usable_threshold - post_residual) as f64;
    }

    // Perfect fit is the ideal outcome.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Small post_residual relative to capacity is good: reward tight fits
    // nonlinearly (quadratic reward).
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly into the post_residual,
    // this placement sets up a perfect follow-up — reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_tight = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - next_tight / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use this gap: mild penalty proportional to waste
        score += 0.3 * post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins when the
    // mean residual is already low (bins are nearly full).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if mean_residual < item_size as f64 {
        score += 8.0 * open_bins_count as f64 * (0.5 + progress);
    }

    // New-bin candidate (bin_residual == bin_capacity): only attractive
    // when current bin fits are poor. Penalize opening new bins normally.
    if bin_residual == bin_capacity {
        score += 12.0 + 3.0 * open_bins_count as f64;
        // But if no open bin fits well (post_residual here is capacity-item),
        // the +12 can be beaten by a bad-fit open bin only if that bin's
        // dead-space penalty is worse; add escape hatch for large items.
        if item_size >= 60 {
            score -= 10.0;
        }
    }

    // Mild reward for using bins below mean residual (consolidating space).
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness;

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        // Perfect 2-step lookahead match: post_residual exactly fits next item
        let gap = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // Next item can follow; reward closeness of the match
            score -= 6.0 * (1.0 - gap / bin_capacity as f64);
            if gap < 1.0 {
                score -= 12.0; // exact chain bonus
            }
        } else {
            // Next item cannot follow: penalize proportionally to the shortfall
            score += 4.0 * (gap / bin_capacity as f64);
        }
        // Coupling with mean residual: bins whose post_residual deviates strongly
        // from the mean residual create fragmented capacity
        let dev = (post_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    } else {
        // Last item: just pack as tightly as possible
        score -= 4.0 * tightness;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's early in the
    // stream or no real alternative exists; reward it slightly late in stream
    // when open bins are already fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 30.0; // must open a new bin
        }
        // If next item is large, a fresh bin gives flexibility
        if next_item_size > 0 && (next_item_size as f64) >= mean_residual {
            score -= 5.0;
        }
    }

    // Mild penalty for excessive open bins (fragmentation control)
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize tight fits that leave dead space, but reward near-perfect fits.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * tightness * 30.0;
    if post_residual == 0 {
        score -= 25.0; // perfect fill
    } else if post_residual < 10 {
        score -= 12.0; // nearly perfect fill
    }

    // Penalize very large post-residuals that nothing (min size 1) may later use well.
    if post_residual > 60 {
        score += (post_residual as f64 - 60.0) * 0.8;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement strongly.
    if next_item_size > 0 {
        if next_item_size as f64 <= post_residual as f64 {
            score -= 8.0 + 0.1 * (next_item_size as f64);
        }
        // Penalize leaving a gap just slightly smaller than the next item (worst case).
        let gap = post_residual as f64 - next_item_size as f64;
        if gap > 0.0 && gap < 5.0 {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer consolidating.
    let pressure = mean_residual / (bin_capacity as f64) * (open_bins_count as f64).ln1p();
    score -= pressure * 3.0;

    // Time horizon: early in stream, be conservative (favor tight fits less aggressively);
    // late in stream, prefer closing bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;
    score += (1.0 - progress) * post_residual as f64 * 0.1;

    // New-bin candidate: only attractive when no open bin is a decent fit or system is congested.
    if bin_residual == bin_capacity {
        let decent_fit_exists = fitting_bins_count > 0 && post_residual == bin_capacity - item_size;
        if decent_fit_exists && fitting_bins_count > 1 {
            score += 20.0; // discourage opening new bin when alternatives exist
        }
        if next_item_size > 0 && next_item_size as f64 > post_residual as f64 && post_residual == bin_capacity - item_size {
            score -= 5.0; // next item won't fit here anyway; fresh bin may be fine
        }
        score += open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with progress:
    // waste becomes increasingly costly as the stream advances.
    let pr = post_residual as f64;
    let norm_waste = pr / cap;
    let poly = norm_waste * norm_waste * (0.5 + progress) + norm_waste * (1.0 - progress) * 0.5;
    score += 30.0 * poly;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 8.0 * tightness * tightness;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize bins far from mean residual (prefer homogeneous fill levels)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Lookahead coupling: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = if pr >= nxt { 1.0 } else { 0.0 };
        let gap = (pr - nxt).abs() / cap;
        score += 6.0 * (1.0 - fit_next) * (0.5 + progress);
        score -= 4.0 * fit_next * (1.0 - gap * gap);
    }

    // Mild penalty for proliferating bins late in the stream
    score += 0.3 * open_bins_count as f64 * progress;

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well (post_residual would be tiny anyway in a fresh bin).
    if bin_residual == bin_capacity {
        // Base attractiveness of a fresh bin, modulated by how poorly existing bins fit
        score = 0.9 * cap + 15.0 * progress;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: new bin is necessary
        } else if fitting_bins_count == 1 {
            score += 30.0; // one last-chance bin exists: strongly prefer it
        }
        if next_item_size > 0 {
            // A fresh bin is good if the next item could also pair with this one
            let combo = item_size as f64 + next_item_size as f64;
            if combo <= cap {
                score -= 10.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 or in "usable" harmonic classes.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
        // Harmonic class of post_residual: how well it pairs with common item sizes.
        // Items in [1,100]; classes via integer division thresholds.
        let class = pr / 10; // 0..=10
        match class {
            0 => score -= 12.0,            // 1..9: small dead space
            1 => score -= 4.0,             // 10..19: usable by smallest items
            2 => score -= 6.0,             // 20..29: commonly fillable
            3 => score += 3.0,             // 30..39: awkward
            4 => score -= 8.0,             // 40..49: good pairing zone
            5 => score -= 2.0,
            6 => score += 2.0,
            7 => score -= 5.0,
            8 => score += 4.0,
            9 => score -= 3.0,
            _ => {}                         // near-full bin residual
        }
        // Modulo coupling: residual divisible by common item sizes is more reusable.
        if pr % 10 == 0 { score -= 5.0; }
        else if pr % 20 == 0 { score -= 3.0; }
        if pr % 25 == 0 { score -= 2.0; }
    }

    // Lookahead: if the next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / 50.0).max(0.0);
        } else {
            // Next item cannot follow in this bin; penalize slightly if it would
            // have fit better elsewhere — mild penalty proportional to overflow.
            let over = (next_item_size - pr) as f64;
            score += 0.05 * over.min(30.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: default mild penalty; opened only when open bins score badly.
    if bin_residual == bin_capacity {
        score = 100.0 + 0.1 * open_bins_count as f64;
        // If many bins are open with fragmented residuals, opening fresh is cheaper.
        if mean_residual < 25.0 && open_bins_count > 2 {
            score -= 15.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 5.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Tie-break toward bins with residual above the item (avoid near-miss placements).
    if bin_residual < item_size {
        score += 1000.0; // should never be selected (infeasible guard)
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to ever be useful are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 50.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Penalize gaps that can't fit the known next item (wasted for lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Reward tight fits relative to item size.
    score -= 30.0 * (item_size as f64 / bin_capacity as f64);

    // Pressure on number of open bins: prefer filling existing bins when many are open.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Align with mean residual: prefer bins below mean residual (tighter bins).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., this empty bin scores low when item barely fits elsewhere).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, offset when many bins are open
        // and current fits are poor (large post_residual elsewhere).
        score = 60.0 + 1.5 * open_bins_count as f64 - 0.2 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0; // new bin can host the pair
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via post_residual (already the archetype anchor).

    // Strong 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if nxt == post {
            score -= 60.0; // perfect chain: next item exactly fills this bin
        } else if nxt <= post {
            // next item fits: reward proportional to how snug the pair is
            let snug = 1.0 - ((post - nxt) / bin_capacity as f64);
            score -= 20.0 * snug;
        } else {
            // next item won't fit here: penalize leaving awkward gaps
            let gap = (post / nxt).min(1.0);
            score += 15.0 * (1.0 - gap);
        }
    }

    // Penalize post_residual in the "dead zone": too small for typical items
    // (sizes 1..100 unknown, so use a soft barrier around small residuals).
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 12.0 {
        score += (12.0 - pr) * 3.0; // unusable sliver penalty
    }

    // Relative-to-mean coupling: bins with residual far below mean are tighter;
    // prefer filling tighter bins (waste less), penalize dumping into loose bins.
    score -= 0.5 * (mean_residual - pr);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // current item barely fits any open bin or residuals are all large.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Default cost of a fresh bin.
        score += 35.0;
        // But if open bins are all loose (mean residual high) and few fit,
        // a new bin becomes competitive.
        if mean_residual < 40.0 {
            score += 25.0; // open bins are tight-ish; keep new bin expensive
        }
        if next_item_size > 0 && (next_item_size as f64) < pr - 1.0 {
            // fresh bin can host the next item well: soften cost
            score -= 10.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Mild preference for consolidating when many bins are open.
    score += 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 1.8 * tightness * tightness * bin_capacity as f64;

    // Penalize dead space that no future item could plausibly use.
    if post_residual > 0 {
        let min_item = 1u32;
        if post_residual < min_item {
            score += 50.0;
        }
        // Wasted fraction penalty: residual too small relative to capacity.
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 12.0 * waste * waste;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item exactly fits the post residual,
    // reward heavily; if next item cannot fit, mild penalty.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            score += 3.0;
        }
    }

    // Prefer bins whose residual is near the mean (balanced packing),
    // except when few bins are open.
    if open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    }

    // Early in stream: encourage opening/using bins conservatively;
    // late in stream: be more greedy about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * tightness;

    // New-bin candidate: only attractive when current bin residuals are poor
    // (high mean residual means open bins are fragmented).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        score = bin_capacity as f64 - 20.0 * fragmentation - 8.0 * progress;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Don't open a new bin early unless many bins are open.
        score += 5.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: prefer small post_residual (tight fit), with non-linear sharpening.
    let mut score = pr * (1.0 + 2.0 * pr_norm * pr_norm);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on tolerate slack; late in stream punish leftover space harder.
    let coupling = pr_norm * (1.0 - progress) * (1.0 - progress);
    score += 40.0 * coupling * pr_norm;

    // Non-linear term coupling item_size and progress: reward filling bins
    // with large items as stream advances.
    let item_frac = item_size as f64 / cap;
    score -= 15.0 * item_frac * item_frac * (0.5 + progress);

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let chain = next_item_size as f64 / cap;
        score -= 12.0 * chain * (1.0 - pr_norm * pr_norm);
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        // post_residual becomes dead space relative to next item; penalize smoothly.
        let waste = ((next_item_size as f64 - pr) / cap).max(0.0);
        score += 25.0 * waste * waste * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral early, increasingly discouraged
    // as stream progresses (encourage closing out open bins).
    if bin_residual == bin_capacity {
        score = cap + 20.0 * progress + 0.5 * open_bins_count as f64;
        // But if no open bin fits well, allow new bin smoothly.
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else {
            // discourage abandoning open bins unless fit is terrible
            let fit_quality = (bin_residual - item_size.min(bin_residual)) as f64 / cap;
            score += 30.0 * (1.0 - fit_quality);
        }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // Distance from mean residual: prefer bins whose residual is near mean
    // to keep balance, via smooth quadratic term.
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction buckets.
    let cap = bin_capacity as f64;
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;

    // Perfect fits are heavenly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Dead-space harmonic classes: residuals in (5, quarter] are mostly unusable
    // since items are >= 1 but small residuals waste capacity.
    if post_residual > 5 && post_residual <= quarter {
        score += 40.0;
    }

    // Residuals in (quarter, third] are semi-dead.
    if post_residual > quarter && post_residual <= third {
        score += 15.0;
    }

    // Residuals in (third, half] can host mid-size items: mildly good.
    if post_residual > third && post_residual <= half {
        score -= 10.0;
    }

    // Modulo classes on post_residual: multiples of 10 pair well with
    // item sizes in the classic 10..80 regime.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 10 != 0 && post_residual < quarter {
        score += 6.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement (chain fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            let next_post = post_residual - next_item_size;
            if next_post <= 5 {
                score -= 60.0;
            } else if next_post <= quarter {
                score += 10.0;
            }
        } else {
            // Next item won't fit here: penalize leaving large slack only
            // mildly; prefer bins where the current item leaves usable space.
            if post_residual > half {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: an empty bin is attractive when the item is
    // large and would leave a fragmented residual in existing bins, or when
    // open bins are already crowded (low mean residual).
    if bin_residual == bin_capacity {
        // Base reservation: opening a bin costs something so we don't always open.
        score += 30.0;
        // Large item leaves little room anyway; fresh bin keeps big residual intact.
        if item_size >= half {
            score -= 35.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0;
        }
        // Crowded system: mean residual low means existing bins are tight.
        if mean_residual < (item_size as f64) * 1.2 {
            score -= 50.0;
        }
        if fitting_bins_count == 0 {
            score -= 500.0; // must open anyway
        }
    } else {
        // Reward using existing bins when they fit well.
        let fit_quality = 1.0 - (post_residual as f64) / cap;
        score -= 25.0 * fit_quality;
        // Penalize opening pressure when many bins are open but empty-ish.
        if mean_residual > 0.7 * cap && open_bins_count > 2 {
            score -= 10.0;
        }
    }

    // Mild stream-position term: early on, be slightly conservative with fills.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item (<= 10) are unusable; punish them hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        // Small gap that only tiny items could use: strong penalty.
        score += 25.0 + (20 - post_residual) as f64 * 2.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 40.0;

    // Reward using bins whose residual is close to the item (good match).
    let waste = (bin_residual as f64 - item_size as f64).abs();
    score -= (bin_capacity as f64 - waste) * 0.15;

    // Open-bin pressure: with many open bins, prefer consolidating
    // into existing bins rather than spreading.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive
    // when the item is large and fits poorly everywhere else.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 35.0 + open_bins_count as f64 * 2.0;
        // Large items justify a fresh bin more.
        score -= fill_ratio * 50.0;
        // If other bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    // Lookahead coupling: if the next item could use this bin's
    // post_residual, reward leaving a compatible gap.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            score -= 10.0 - (post_residual - next_item_size) as f64 * 0.2;
        }
    }

    // Mean-residual coupling: bins already below the mean residual are
    // "dying"; prefer filling them to close them out.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Slight late-stream tightening: as the stream progresses, waste
    // matters relatively more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: minimize waste, but weight it by how "usable" the leftover is.
    // Small leftovers (< 10, below min item size) are dead space -> heavy penalty.
    if post_residual < 10 {
        score += 40.0;
    }

    // Aggressive 2-step lookahead: reward exact/near match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 60.0; // perfect chain: next item exactly fills this bin
        } else {
            // proximity bonus decaying quadratically
            let d = diff as f64;
            score -= (60.0 / (1.0 + d * d * 0.05)) - 0.0;
            // penalize leftover that cannot host next item
            if post_residual < next_item_size {
                score += 0.35 * (next_item_size - post_residual) as f64;
            }
        }
        // If next item would leave this bin nearly empty anyway, prefer big bins
        if next_item_size >= post_residual {
            score += 5.0;
        }
    }

    // Compare against mean residual: bins with residual below mean are scarcer space;
    // filling them is good (their remaining space is more likely wasted).
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        if res < mean_residual {
            score -= 0.5 * (mean_residual - res);
        } else {
            score += 0.3 * (res - mean_residual);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Early in stream: be picky (prefer tight fits, allow opening bins);
    // late in stream: consolidate, avoid opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress; // late items: favor existing bins overall

    // New-bin candidate handling: an empty bin has post_residual == capacity - item_size.
    // Penalize opening a new bin mildly unless it enables a great lookahead chain.
    if bin_residual == bin_capacity {
        score += 18.0;
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 2 {
            score -= 40.0; // opening fresh bin sets up perfect next placement
        }
    }

    // Mild penalty proportional to number of open bins to discourage sprawl.
    score += 0.15 * open_bins_count as f64;

    // Reward very tight fits (item nearly fills bin).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post residuals.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that cannot fit the average next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 + (next_item_size - post_residual) as f64 * 0.5;
        } else {
            // Reward residual that can still host the lookahead item.
            score -= 4.0;
        }
        // Perfect two-item packing: post residual exactly fits next item.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when the item is large relative
    // to capacity or all open bins are nearly full.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fill_pressure = mean_residual / bin_capacity as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Opening a new bin costs: prefer it only if existing bins are fragmented.
        score += 25.0 - 20.0 * fill_pressure + 15.0 * item_frac;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: must open new bin
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 8.0; // fresh bin with dead space is bad
        }
    } else {
        // Prefer fuller bins (waste less future capacity).
        let used_frac = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 10.0 * used_frac;
    }

    // Spread load late in the stream; consolidate early.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    // Tie-break: distance of post residual from awkward small values (11..30).
    if post_residual > 0 && post_residual < 31 {
        score += 6.0 * (1.0 - post_residual as f64 / 30.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = prn * prn * (1.0 - progress) + prn * progress * progress;
    score += 40.0 * coupling;

    // Tight fit reward, modulated smoothly by progress
    let tight = (item_size as f64 / bin_residual as f64).powi(3);
    score -= 30.0 * tight * (0.5 + progress);

    // Penalize dead space that no plausible next item can use
    if next_item_size > 0 && post_residual > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 5.0 * (gap / cap).powi(2);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64 * prn;

    // Deviation from mean residual: prefer bins that keep residuals balanced
    score += 0.2 * (pr - mean_residual).abs();

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - tight);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10] is unusable dead space
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit is highly desirable
        score -= 80.0;
    }

    // Penalize leaving gaps that cannot fit typical future items (min size 1..10 band)
    if post_residual > 0 && post_residual < item_size {
        score += 8.0;
    }

    // Lookahead coupling: if next item fits into the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // dead space relative to the known next item
        score += 15.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading into new bins
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins are already open
        score += 20.0 + 3.0 * open_bins_count as f64;
        // But if no open bin fits well, opening may be justified
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Favor filling existing bins more when many are open
        score -= (open_bins_count as f64) * 0.5;
    }

    // Mean residual coupling: placing into a bin far above mean residual balances load
    if bin_residual as f64 > mean_residual && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Stream progression: late in the stream, tighten up and avoid waste
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) with a non-linear penalty.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
            // Perfect chaining bonus
            if slack == 0.0 {
                score -= 30.0;
            }
        } else {
            // Next item won't fit here: penalize residual that is close-but-too-small (dead space)
            let gap = (next_item_size - post_residual) as f64;
            score += 0.6 * gap.min(50.0);
        }
    }

    // Reward leaving residual near mean_residual (keeps bin pool homogeneous / pairable)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize spreading across many open bins slightly; encourage consolidation
    score += 0.05 * open_bins_count as f64;

    // Late in stream: be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;

    // New-bin candidate: only attractive when current fit is terrible
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 / bin_capacity as f64;
        score = 60.0 + 80.0 * bad_fit;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Reward small post-residual relative to capacity (tight packing)
        let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 40.0 * tight * tight;

        // Lookahead: reward if next item fits into the post residual (chain packing)
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                score -= 60.0;
                // Bonus if next item nearly fills residual again
                let fill = next_item_size as f64 / post_residual as f64;
                score -= 30.0 * fill * fill;
            } else {
                // Penalize leaving dead space next item cannot use
                score += 15.0;
            }
        } else {
            // Last item: strongly prefer filling an existing bin
            score -= 200.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Penalize new-bin candidate (empty bin) unless nothing sensible fits
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut penalty = 120.0;
        // Early in stream: opening bins is fine; late: avoid bin proliferation
        penalty *= 1.0 - 0.5 * progress;
        // If item is large relative to capacity, new bin is more acceptable
        penalty -= 50.0 * (item_size as f64 / bin_capacity as f64);
        // If many bins already open, discourage another one
        penalty += 5.0 * (open_bins_count as f64).sqrt();
        score += penalty.max(0.0);
    }

    // Prefer bins with residual close to the item (best-fit flavor)
    let waste = (bin_residual - item_size) as f64;
    score += 0.5 * (waste - mean_residual).abs();

    // Prefer bins whose residual is below the mean (use up nearly-full bins)
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // Mild pressure to use existing bins when many are open
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let is_new_bin = (bin_residual == bin_capacity) as f64;

    // Base: quadratic waste coupling with stream progress
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling: waste tolerance shrinks as stream progresses
    let tightness = 1.0 + progress * progress * 2.0;
    score *= tightness;

    // Reward near-perfect fits with a smooth residual valley
    score -= 6.0 * (-norm_pr * 6.0).exp();

    // Penalize dead space that likely can't fit future items
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let unusable = (nxt - pr).max(0.0) / cap;
        score += 4.0 * unusable * unusable * cap;
        // Reward bins that can also hold the lookahead item
        score -= 2.0 * (pr >= nxt) as i32 as f64;
    }

    // Last-chance bin bonus (smooth in fitting count)
    let last_chance = 1.0 / fitting_bins_count as f64;
    score -= 3.0 * last_chance;

    // Mild preference to keep bin count low early, fill existing bins later
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Divergence from mean residual: prefer balanced fills smoothly
    score += 0.3 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: penalize opening a bin unless item is large relative to capacity
    let fill_ratio = item_size as f64 / cap;
    score += is_new_bin * (cap * (0.55 - 0.5 * fill_ratio).max(0.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = (bin_capacity / 4) as f64;
    let half = (bin_capacity / 2) as f64;
    let three_quarter = (3 * bin_capacity / 4) as f64;

    // Reward tight fits: small post_residual gets a strong discount
    if pr <= quarter {
        score -= 40.0 * (1.0 - pr / quarter.max(1.0));
    } else if pr <= half {
        score -= 12.0 * (1.0 - (pr - quarter) / quarter.max(1.0));
    }

    // Penalize "awkward" residues: post_residual in (30..=60) is hard to fill later
    if post_residual > 25 && post_residual < 60 {
        score += 8.0;
    }

    // Modulo arithmetic: residues divisible by 10 are more reusable (items often multiples of 10)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Integer-division thresholds on next_item_size: does lookahead item fit the residue?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chaining: lookahead exactly fills remaining space
            if next_item_size == post_residual {
                score -= 25.0;
            } else {
                score -= 8.0;
            }
        } else {
            // Lookahead won't fit here: penalize proportionally to wasted opportunity
            score += 4.0 + 0.1 * (next_item_size - post_residual) as f64;
        }
        // Harmonic class of next_item_size relative to capacity fractions
        let ni = next_item_size as f64;
        if ni > three_quarter {
            score -= 3.0; // big next item: prefer keeping many small bins? actually keep residue usable
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        // New empty bin baseline: score = capacity; adjust based on item size class
        let it = item_size as f64;
        if it > half {
            score -= 10.0; // big items fine in fresh bins
        } else if it <= quarter {
            score += 15.0; // small items should go into existing residue
        }
        // Early in stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    } else {
        // Existing bin: mild bonus for keeping bin count low
        score -= 2.0;
        // Prefer bins with residual below mean (consolidate fuller bins)
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Penalize many open bins slightly to encourage consolidation
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty: residuals too small for the smallest
    // possible item are wasted forever.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // perfect fit bonus via huge penalty avoided
    }
    if post_residual > 0 && post_residual < next_item_size.max(min_item) {
        // Gap unusable by the lookahead item -> likely dead space
        score += 12.0;
    }
    // Penalize small-but-nonzero gaps more aggressively (non-linear)
    if post_residual > 0 && post_residual <= 10 {
        score += (11 - post_residual) as f64 * 2.5;
    }

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 8.0;

    // Reward perfect fit strongly
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins when
    // alternatives exist; encourage filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.15 + 0.35 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward this placement heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    // Mean residual alignment: prefer bins whose residual is near the mean
    // (keeps a balanced portfolio of bin gaps).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // New-bin candidate: only attractive when no open bin fits well
    // (bin_residual == bin_capacity). Make it mildly costly by default.
    if bin_residual == bin_capacity {
        score += 3.0 + open_bins_count as f64 * 0.5;
        // But if the item is large and fits a fresh bin perfectly aligned
        // with lookahead, allow it.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 1.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: exact fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: strongly favor bins whose post_residual
    // exactly matches the next item size (chains two perfect placements).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        score -= 120.0 * (1.0 - diff / cap).max(0.0);
        if diff == 0.0 {
            score -= 300.0;
        }
        // Penalize leaving residual that the next item cannot use at all.
        if post_residual > 0 && post_residual < next_item_size {
            score += 60.0 * (1.0 - post_residual as f64 / nxt.max(1.0));
        }
    }

    // Compare against mean residual across open bins: prefer bins whose
    // remaining space after placement is below average (consolidating waste).
    score -= 40.0 * (mean_residual - post_residual as f64) / cap;

    // Relative tightness of this fit.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 50.0 * fit_ratio;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins
    // would create large unusable dead space.
    if bin_residual == bin_capacity {
        score += 150.0 + open_bins_count as f64 * 5.0;
        // If item is huge relative to capacity, a fresh bin is more acceptable.
        score -= 100.0 * (item_size as f64 / cap);
    }

    // Slight early-stream preference to keep several bins open for flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * (1.0 - progress) * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post-residual relative to item size).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness * item_size as f64;

    // Penalize dead space that is too small to ever be useful (below min item size 1..100 range).
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) * 10 {
        score += 15.0;
    }
    // General dead-space penalty: unusable gap relative to typical item scale.
    if post_residual > 0 {
        score += 0.35 * (post_residual as f64).ln() * (post_residual as f64);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 12.0 / (1.0 + slack as f64);
        } else {
            // Next item cannot fit here; slight penalty proportional to overshoot.
            let over = next_item_size - post_residual;
            score += 0.08 * over as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate handling: prefer existing bins unless this bin is nearly full
    // or the fit is terrible.
    if bin_residual == bin_capacity {
        // Empty new bin: baseline score is item_size; add a mild bias so existing
        // decent fits win, but poor fits (large post_residual on existing bins) lose.
        score += 5.0 + 0.05 * open_bins_count as f64;
        // Late in the stream, opening fresh bins is fine (many future items to fill).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * progress;
    }

    // Global state: if mean residual across open bins is high, we have slack;
    // prefer bins whose post_residual stays near mean (avoid fragmentation spread).
    if open_bins_count > 0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    }

    // Many open bins: discourage adding more bins / encourage consolidation.
    score += 0.4 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in stream, keep residuals large (flexibility); later,
    // pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.3 * post_residual as f64;
    score -= progress * 0.5 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Core: minimize wasted space, with a non-linear (quadratic) penalty on residual.
    let mut score = pr + 0.35 * (pr * pr) / cap;

    // Reward near-perfect fits smoothly (small residual => discount).
    let tightness = 1.0 - pr / cap;
    score -= 12.0 * tightness * tightness * tightness;

    // Lookahead coupling: favor residuals that can still host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack_fit = 1.0 - (pr - nx) / cap;
            score -= 6.0 * slack_fit * slack_fit;
        } else {
            // Residual too small for the next item: penalize proportionally.
            score += 4.0 * (nx - pr) / cap * (1.0 + progress);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Stream-progress coupling: early on, be slightly willing to spread items
    // (smooth polynomial in progress); late in the stream, pack tightly.
    let prog2 = progress * progress;
    score += (1.0 - prog2) * 0.15 * (pr / cap) * cap * 0.1;
    score -= prog2 * 8.0 * (1.0 - pr / cap);

    // Prefer bins with residuals below the mean residual (denser bins).
    let dev = (pr as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev.abs();

    // Slight penalty for proliferating bins when many are open.
    score += 0.02 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual buckets via integer division
    let class = post_residual / 10; // 0..=10 harmonic class
    // Penalize mid-range residuals (dead space), reward extremes
    match class {
        0 => score -= 25.0,                    // perfect fit
        1 => score -= 15.0,                    // near-perfect
        2 | 3 => score -= 5.0,                 // good
        4 | 5 | 6 => score += 8.0,             // dead zone
        _ => {}                                // large residual: fine
    }

    // Modulo arithmetic: residual divisible by small sizes is reusable
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 5 == 0 { score -= 3.0; }
        if post_residual % 25 == 0 { score -= 4.0; }
        if post_residual % 3 == 0 { score -= 1.5; }
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // reward chains, especially exact or tight fits
            let slack = post_residual - next_item_size;
            score -= 10.0 + (slack as f64).min(20.0) * -0.3;
            if slack == 0 { score -= 15.0; }
        } else if next_item_size <= bin_residual && post_residual > 0 {
            // next item fits bin now but would not after this placement
            score += 6.0;
        }
        // harmonic class match between leftover and next item
        let nc = next_item_size / 10;
        if nc == class && class > 0 { score -= 4.0; }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0);
    }

    // New-bin candidate: only attractive when current fit is bad
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        score = 60.0 + fit_quality * 40.0
            - (mean_residual - post_residual as f64).abs() * 0.1;
        if fitting_bins_count == 0 { score -= 50.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size { score -= 10.0; }
    }

    // Tightness reward: fraction of bin filled
    score -= (item_size as f64 / bin_capacity as f64) * 12.0;

    // Late-stream consolidation: prefer closing bins tightly as stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 && post_residual < 20 { score -= 8.0 * progress; }

    // Mean residual alignment: prefer bins below mean residual (tighter bins)
    score += (mean_residual - post_residual as f64) * 0.15;

    // Mild preference against spreading across too many open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }

    // Perfect fit is extremely attractive.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Reward placements that leave room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0; // gap dead relative to lookahead
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin when decent fits exist,
    // unless all open bins would leave dead space.
    if bin_residual == bin_capacity {
        score += 90.0;
        score += open_bins_count as f64 * 2.0;
        if post_residual < 10 && item_size >= 10 {
            // even a fresh bin creates dead space with this item? no, fresh bin
            // residual is large; keep base penalty.
        }
    }

    // Open-bin pressure: mild preference to consolidate into fewer bins.
    score += open_bins_count as f64 * 0.5;

    // Deviation from mean residual: prefer bins with residual close to item need.
    let dev = (bin_residual as f64 - item_size as f64) - (mean_residual - item_size as f64);
    score += 0.3 * dev.abs();

    // Slight preference for tighter bins (best-fit flavor) late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (bin_residual as f64 - item_size as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect 2-chain
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportional to how tight the 2-chain is
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize dead space relative to mean residual
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
        }
    }

    // Penalize post_residual that is small but unusable (below min item size 1..100 heuristic: below 10)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Relative to mean residual: prefer bins whose residual deviates favorably
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so open bins with good fits win,
    // but allow opening when post_residual is very small (waste avoidance)
    if bin_residual == bin_capacity {
        score += 10.0;
        if post_residual < 20 {
            score -= 30.0; // new bin better than leaving tiny dead space
        }
    }

    // Late in stream: consolidate, prefer filling existing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear boost.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize dead space: residuals too small to hold typical future items.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 25 {
        score += 10.0;
    }

    // Lookahead: reward bins whose post_residual fits the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 / (1.0 + slack);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0).min(5.0);
    }

    // Global state: if many open bins with large mean residual, prefer
    // consolidating into bins below average residual (fill emptier bins less,
    // keep tight bins for tight items).
    if open_bins_count > 0 {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev;
    }

    // Time horizon: early in the stream, be more willing to spread items
    // (penalize opening bins less); late in stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * (1.0 - fit_ratio);

    // New-bin candidate handling: only attractive when current bins fit poorly
    // or none exist; make empty bin moderately unattractive otherwise.
    if bin_residual == bin_capacity {
        score += 18.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin pairs well with upcoming large item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress in [0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // tight fits (small post_residual) are increasingly valuable as stream progresses.
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let tightness = (1.0 - pr_norm) * (1.0 - pr_norm); // in [0,1], 1 = perfect fit
    score -= tightness * (1.0 + 2.0 * prog2 + 4.0 * prog3) * 20.0;

    // Penalize medium dead space more than extremes (smooth bump around half-capacity)
    let bump = 4.0 * pr_norm * (1.0 - pr_norm); // peaks at pr_norm = 0.5
    score += bump * (10.0 + 15.0 * progress) * (pr_norm * cap / 25.0);

    // Lookahead: reward if next item fits the post residual (chain packing)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            score -= (1.0 - slack / cap) * (8.0 + 12.0 * prog2);
        } else {
            // penalize residuals that cannot host the lookahead item
            score += (nxt - pr) / cap * 6.0;
        }
    }

    // New-bin candidate: penalize opening a new bin, more so when other bins fit,
    // and less so late in the stream when consolidation matters.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (1.0 + fitting_bins_count as f64) };
        let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 30.0 + 25.0 * open_pressure * (1.0 - prog3) - 20.0 * scarcity * (1.0 - progress);
        // allow new bin late in stream to avoid fragmenting
        score -= 15.0 * prog3;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 10.0 * progress;
    }

    // Mild preference toward bins deviating from mean residual (reduce variance)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score -= dev * 3.0 * (1.0 - prog2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Harmonic classes of post_residual: perfect fit, near-perfect, dead zones
    let class: f64 = match post_residual {
        0 => -400.0,                       // perfect closure: strongly favored
        1..=4 => -120.0 + post_residual as f64 * 15.0, // tiny dead space, nearly as good
        5..=9 => 60.0 + post_residual as f64 * 8.0,    // classic unusable sliver
        10..=19 => 25.0 + post_residual as f64 * 2.0,  // medium: may fit small future item
        _ => post_residual as f64,                     // large residual: keep base cost
    };
    score += class;

    // Lookahead chaining: does the next item fit into the resulting residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item slots in: reward proportional to how snugly
            let snug = (post_residual - next_item_size) as f64;
            score -= 90.0 - snug * 3.0;
        } else if post_residual < next_item_size && post_residual <= 9 {
            // residual too small for next item anyway: sliver penalty softened
            score -= 40.0;
        }
    }

    // Last-chance bin: using it avoids opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 150.0;
    }

    // New-bin candidate logic
    if is_new_bin {
        if fitting_bins_count <= 1 {
            // no open bin can take the item: opening is mandatory -> neutral
            score -= 10.0;
        } else {
            // other bins fit: opening a new bin wastes capacity unless item is huge
            let waste = bin_capacity as f64 - item_size as f64;
            let big_item_bonus = if item_size >= 70 { 250.0 } else { 0.0 };
            score += 500.0 + waste * 4.0 - big_item_bonus;
        }
    }

    // Slight preference for filling fuller bins as stream matures
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 20.0 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // Mild penalty when this bin is already far below average fullness
    score += ((mean_residual - post_residual as f64).abs()) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever fit a realistic
    // future item (items >= 1, but small gaps are rarely reusable) are heavily penalized.
    if post_residual > 0 {
        let dead_threshold = 10.0_f64.min(post_residual as f64);
        let deadness = 1.0 - (post_residual as f64 / 50.0).min(1.0);
        score += deadness * 30.0 * (dead_threshold / 10.0);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward residual that can still host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 12.0; // creates a gap that blocks the next item
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // and discourage opening new ones (new bin has bin_residual == bin_capacity, so
    // its base score is high; add extra penalty scaled by open bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.15 * (0.5 + progress);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Deviation from mean residual: prefer bins whose residual is already tight.
    score += ((bin_residual as f64 - mean_residual) / 10.0).clamp(-5.0, 5.0);

    // Slight preference for tighter fits overall.
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of next item into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // perfect 2-item packing
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - slack * 0.35; // good lookahead fit, penalize leftover
        } else {
            // next item can't fit here; penalize wasted space proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.25;
        }
    }

    // Tight fit reward relative to mean residual
    let post_f = post_residual as f64;
    if post_residual == 0 {
        score -= 60.0; // perfectly closed bin
    } else {
        let tightness = 1.0 - post_f / bin_capacity as f64;
        score -= tightness * 12.0;
        if post_f < mean_residual {
            score -= (mean_residual - post_f) * 0.30; // below-average leftover is good
        } else {
            score += (post_f - mean_residual) * 0.20;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate penalty: discourage opening new bins unless this is a big item
    if bin_residual == bin_capacity {
        score += 15.0 + 0.15 * item_size as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big item starting a fresh bin may be fine
        }
    }

    // Late-stream consolidation: prefer closing bins tightly as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0 * (1.0 - post_f / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * tightness * tightness;

    // Strongly reward near-perfect fills.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize dead space that no future item (min size 1..~10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0; // awkward sliver
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement is excellent; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use the leftover: leftover is more likely dead
            score += 3.0 + 0.05 * (post_residual as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Many open bins with high mean residual: prefer consolidating into bins
    // whose residual is below mean (tighter bins), discourage spreading.
    if open_bins_count > 1 {
        let diff = mean_residual - bin_residual as f64;
        score += 0.15 * diff; // bins tighter than average get lower score
    }

    // New-bin candidate handling: opening a new bin wastes the residual of all
    // open bins. Make it attractive only when it creates a flexible large
    // residual and existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 18.0;
        // Early in the stream, new bins are cheaper (more future items to fill).
        score -= 12.0 * (1.0 - progress);
        // If many bins are open with large mean residual, discourage new bin.
        score += 0.10 * mean_residual;
        // If no open bin fits (fitting_bins_count == 0 excludes this candidate,
        // but if it's the sole option via low competition), allow it.
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
    }

    // Mild time-horizon shaping: late in the stream, favor filling existing
    // bins aggressively (waste less overall).
    score -= 4.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Tight fits rewarded: quadratic decay of residual
    let tight = (post_residual as f64 / bin_capacity as f64).powi(3);
    score += tight * 30.0;

    // Smooth non-linear coupling of post_residual with stream progress
    score += (post_residual as f64 * progress * (1.0 - progress) * 4.0) * 0.5;

    // Last-chance bin: strongly reward using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize slightly unless post_residual would be perfect
    if bin_residual == bin_capacity {
        score += 10.0 - 20.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 40.0;
        } else if gap < 0 {
            score += 5.0;
        }
    }

    // Prefer filling bins with larger mean residual less (spread items)
    score -= (mean_residual - post_residual as f64).abs() * 0.1;

    // Mild penalty for many open bins to encourage reuse
    score += open_bins_count as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 and modulo 7
    let r10 = post_residual % 10;
    let r7 = post_residual % 7;
    // Dead-space classes: residuals that are awkward to fill (small but nonzero)
    if post_residual > 0 && post_residual <= 9 {
        score += 12.0 * (10 - post_residual) as f64; // tiny unusable slivers
    }
    // Reward residuals in "harmonic" classes divisible by common item sizes
    if post_residual % 10 == 0 { score -= 3.0; }
    if post_residual % 20 == 0 { score -= 4.0; }
    if post_residual % 25 == 0 { score -= 3.0; }
    if post_residual % 50 == 0 { score -= 5.0; }
    // Penalize odd/prime-ish awkward residues
    if r10 == 1 || r10 == 3 || r10 == 7 { score += 2.0; }
    if r7 == 0 && post_residual > 0 { score -= 1.0; }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect harmonic match: next item exactly fills remainder
            if next_item_size == post_residual { score -= 15.0; }
            else { score -= 6.0 + 4.0 * (next_item_size as f64 / cap); }
            // Bonus if post_residual - next leaves a clean class
            let npr = post_residual - next_item_size;
            if npr % 10 == 0 { score -= 3.0; }
        } else {
            // Next item can't use this residual; penalize proportional to wasted potential
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: mildly penalize opening new bins unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 8.0 + 0.05 * open_bins_count as f64;
        // But if item is huge relative to capacity, opening fresh is fine
        if item_size as f64 > 0.7 * cap { score -= 6.0; }
    }

    // Prefer tight fills: reward small post_residual relative to capacity
    score -= 5.0 * (1.0 - post_residual as f64 / cap);

    // Progress term: later in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * (bin_residual as f64 - post_residual as f64) / cap;

    // Mean residual alignment: prefer bins whose residual is near the mean (balanced packing)
    score += 0.15 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small to be
    // usable by future items (typical item range 1..100, so gaps below ~10 are
    // nearly always dead space).
    let dead_threshold: f64 = 10.0;
    let pr = post_residual as f64;
    if pr > 0.0 && pr <= dead_threshold {
        score += (dead_threshold - pr) * 3.0; // small unusable gap => heavy penalty
    }

    // Reward near-perfect fits (post residual close to zero but usable).
    if pr == 0 {
        score -= 40.0;
    } else if pr <= 5.0 {
        score -= 15.0;
    }

    // Fit-tightness: prefer bins where the item fills a large fraction of residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 10.0;

    // Open-bin pressure: when many bins are open, discourage opening/spreading;
    // when few bins are open, prefer consolidation into existing bins.
    let obp = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to how many bins are open,
        // but relax penalty if no existing bin fits well (post_residual large).
        score += 25.0 + obp * 2.5;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    } else {
        // Reward using existing bins, more so when many are open.
        score -= 5.0 + obp * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (pr - ni).abs() < 0.5 {
            score -= 20.0;
        } else if pr >= ni && pr - ni <= dead_threshold {
            score += (pr - ni) * 1.5; // sets up a dead gap for next item
        }
    }

    // Stream progression: early on, be more willing to open bins (spread risk);
    // later, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    } else {
        score -= progress * 5.0;
    }

    // Mean residual alignment: prefer bins whose residual is close to the mean
    // (keeps bin states homogeneous, easier to pack future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual is already favored by the base term.

    // Aggressive 2-step lookahead: if the next item exactly fills the post-residual,
    // this is a perfect chaining opportunity -> strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 60.0; // next item perfectly fills this bin afterwards
        } else {
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // Next item cannot use leftover space: penalize dead space proportionally.
        score += 6.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Penalize leaving residuals that are too small to ever be useful
    // (items are 1..100, small fragments are dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // current fit is poor. Give the empty bin a mild penalty so it is chosen
    // only when open bins leave large unusable residuals.
    if bin_residual == bin_capacity {
        score += 20.0;
        // If many bins are open with slack, discourage opening yet another bin.
        score += 2.0 * open_bins_count as f64;
    }

    // Contextual term: compare bin residual against mean residual across open bins.
    // Prefer bins with below-average residual (tighter bins get used first),
    // keeping looser bins available for future large items.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Slight preference early in the stream to pack tightly (build good structure),
    // relax later to avoid fragmentation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose residual is nearly consumed.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 3.0 * tight * tight * (item_size as f64);

    // Penalize dead space that is too small to be useful for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 2.5;
        } else if post_residual > 0 {
            score += 1.5;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fit = (item_size as f64) / (bin_capacity as f64) < 0.5;
        let mut penalty = 12.0;
        if fitting_bins_count == 0 {
            penalty = -4.0; // no open bin fits: opening is necessary
        } else if poor_fit && progress > 0.3 {
            penalty = 2.0; // late stream, small item: a fresh bin may be fine
        }
        if open_bins_count > 40 {
            penalty += 4.0; // avoid bin proliferation
        }
        score += penalty;
    }

    // Mild pressure toward consolidating into bins below mean residual (balancing).
    if (bin_residual as f64) < mean_residual && bin_residual < bin_capacity {
        score -= 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Tight fits rewarded: quadratic bonus shrinking post-residual influence
    let tightness = 1.0 - post / cap;
    score -= 6.0 * tightness * tightness;

    // Non-linear coupling: prefer small post-residual as stream progresses
    score += 4.0 * (post / cap) * (1.0 - progress) * (post / cap);

    // Dead-space penalty for medium residuals that are hard to fill
    let dead = (post / cap - 0.5).abs();
    score += 5.0 * dead * dead * (0.5 + progress);

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 3.0 + 2.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize mildly early, allow late when open bins are full-ish
    if bin_residual == bin_capacity {
        score = cap + 10.0 - 12.0 * progress - 0.5 * mean_residual / cap;
        if post < item_size as f64 { score += 5.0; }
    }

    // Mild preference to fill bins with larger residual when many bins open
    score += 0.05 * (open_bins_count as f64) * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit classes are golden, small dead space is penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: perfect fit (post_residual == 0) -> huge reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Class B: residual too small for the smallest possible item -> dead space penalty
        if post_residual < 10 {
            score += 500.0;
        }
        // Class C: residual divisible into nice modular classes (multiples of 10)
        if post_residual % 10 == 0 {
            score -= 20.0;
        }
        // Class D: integer-division thresholds on post_residual
        match post_residual / 10 {
            0 => score += 40.0,          // 1..9: nearly dead
            1 => score -= 5.0,           // 10..19: fits small items
            2 | 3 => score -= 10.0,      // 20..39: useful mid band
            4 | 5 => score -= 15.0,      // 40..59: good band
            _ => score -= 5.0,           // large residual: fine but wasteful
        }
    }

    // Coupling with lookahead item: reward if next item exactly fills the post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // next item fits; reward proportionally to how well it packs
            score -= 30.0 * (next_item_size as f64 / pr.max(1.0));
        } else {
            // next item cannot use this residual: mild penalty scaled by wasted fraction
            score += 15.0 * ((next_item_size - post_residual) as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 60.0;
        // but if no open bin fits well, allow it
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Prefer filling bins with low mean residual (compact the packing)
    score -= 0.5 * (mean_residual - pr);

    // Late in the stream, tighten packing: reward tight fits more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (cap - pr) * 0.3;

    // Mild penalty per open bin to encourage consolidation
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: harshly penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 20.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 15.0;

    // Open-bin pressure: penalize adding to bins when many are open,
    // favoring consolidation into fewer bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        score += 6.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean
    // (i.e. filling fuller bins first keeps emptier bins flexible).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // no open bin offers a decent fit. Give it a moderate base penalty,
    // softened slightly when many bins are open (fragmentation relief).
    if bin_residual == bin_capacity {
        score = 40.0 + open_bins_count as f64 * 0.5;
        if post_residual > 0 && post_residual < 10 {
            score += 0.0; // empty bin has no dead space issue
        }
        // If the only alternative is a terrible fit, allow new bin to win.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Stream progression: late in the stream, be slightly more conservative
    // about dead space since fewer items remain to fill gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin completely.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: does the next item fit into the leftover space?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item can chain into this bin: big reward, scaled by how snugly it fits.
            let slack_after_next = post_residual - next_item_size;
            score -= 150.0 + (slack_after_next as f64).min(50.0);
        } else {
            // Next item cannot use this leftover: penalize dead space, worse for large leftovers.
            score += 0.5 * post_residual as f64;
        }
    }

    // Prefer bins whose residual is already below the mean residual (tighter bins).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin early in the stream; allow it more later when open bins are fragmented.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 120.0 - 60.0 * progress + 5.0 * open_bins_count as f64;
        // Still allow new bin if item is huge relative to typical residuals.
        if item_size as f64 > mean_residual {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit reward: post_residual exactly matches the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Lookahead: penalize leaving residue that the next item cannot use (dead space).
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            let dead = post_residual as f64;
            score += dead * (0.5 + 0.5 * progress);
        }
        // If the next item fits in the residue, mildly reward keeping a useful gap.
        if post_residual >= next_item_size {
            score -= 5.0;
        }
    } else {
        // Last item: minimize waste directly.
        score += 0.0;
    }

    // Last-chance bin: strongly prefer placing in the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when open bins exist, scaled by stream progress.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = if mean_residual > 0.0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        score += 25.0 + 50.0 * (1.0 - pressure) + 30.0 * (1.0 - progress);
        // If no existing bin fits, opening a new bin is necessary: soften penalty.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Reward bins with residual close to mean (consolidate average fill).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= (10.0 / (1.0 + dev)) * (1.0 - progress);
    }

    // Slight preference for filling bins with less residual (tighter fits).
    score += (bin_residual as f64 - post_residual as f64) * 0.05;

    // Tie-breaker: prefer lower post residual non-linearly.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post_residual, with smooth non-linear emphasis
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Stream progress coupling: tighten fit preference as stream advances
    score += 6.0 * progress * norm_post * norm_post * cap;

    // Dead-space penalty: residual too small to ever fit another item (items >= 1)
    if post_residual == 0 {
        score -= 12.0; // perfect fill reward
    } else if post_residual < 10 {
        score += 4.0 * (1.0 - post as f64 / 10.0); // near-unusable sliver
    }

    // Lookahead coupling: reward if next item fits snugly in post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 10.0 * snug * snug;
    } else if next_item_size > 0 {
        // next item won't fit here: mild penalty scaled by wasted potential
        score += 3.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's genuinely better
    if bin_residual == bin_capacity {
        let avg_pressure = mean_residual / cap;
        score += 8.0 + 10.0 * avg_pressure + 4.0 * progress;
        // allow new bin if no existing bin fits well (large item, few fitting bins)
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Mild penalty for bin sprawl: encourage consolidation across open bins
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Mean-residual alignment: prefer bins whose post residual stays near mean
    let dev = (post - mean_residual).abs() / cap;
    score += 2.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional fill of the bin after placement
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 40.0 * fill_frac * fill_frac;

    // Harmonic class of post_residual: tiny dead space classes are good
    let cls = post_residual % 10;
    score -= match cls {
        0 => 6.0,
        1 | 2 => 3.0,
        9 | 8 => 1.5,
        _ => 0.0,
    };

    // Penalize dead space that no typical item (1..100) can use efficiently
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // near-perfect fit
    } else if post_residual >= 10 && post_residual <= 80 {
        // usable by future items: mild penalty proportional to waste
        score += 0.05 * post_residual as f64;
    } else {
        // dead space zone (81..99): big penalty
        score += 15.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward strongly
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // harmonic match: next item leaves another small residual
        let next_post = post_residual - next_item_size;
        if next_post % 10 == 0 {
            score -= 5.0;
        }
        if next_post < 10 {
            score -= 4.0;
        }
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // next item fits the bin now but not after this placement: slight penalty
        score += 3.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a bin, discounted early in stream
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 55.0 - 10.0 * progress;
        // attractive if current item is large (poor fit candidates) or many bins already open
        if item_size > bin_capacity / 2 {
            score -= 8.0;
        }
        if open_bins_count as f64 > mean_residual {
            score -= 4.0;
        }
    } else {
        // favor bins whose residual is close to item (tight fits)
        let gap = bin_residual - item_size;
        score += 0.1 * gap as f64;
        // prefer bins below mean residual (consolidate emptier bins? keep fuller ones)
        if (bin_residual as f64) > mean_residual {
            score += 2.0;
        }
    }

    // Slight exploration term via integer division threshold on post_residual
    score += (post_residual / 25) as f64 * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Reward perfect fills strongly.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Prefer bins whose residual was already small (tight fit).
    score += (bin_residual as f64) * 0.15;

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // Penalize if post residual is nonzero but too small for next item (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // New-bin candidate: keep it neutral-ish; only open new bin if existing fits are bad.
    if bin_residual == bin_capacity {
        score += 40.0 + mean_residual * 0.3;
    }

    // Mild stream progression scaling.
    score *= 1.0 + 0.1 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight fit reward: minimize post_residual non-linearly
    score += (post / capacity) * (post / capacity) * 20.0;

    // 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - diff / capacity);
    } else if next_item_size > 0 {
        // next item cannot fit here; slight penalty scaled by gap
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.15;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize near-empty residual waste (dead space) but less than mid-range
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Context: relative to mean residual across open bins
    if mean_residual > 0.0 {
        score += 0.05 * (post - mean_residual);
    }

    // Early stream: be more conservative (favor filling existing bins)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress;

    // New-bin candidate: neutralize its perfect-fit advantage unless item is large
    if bin_residual == bin_capacity {
        score += 12.0 - 0.1 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize large leftover dead space non-linearly.
    let dead = post_residual as f64;
    score += 0.35 * (dead * dead) / bin_capacity as f64;

    // Lookahead: if the next item fits the post-residual exactly-ish, reward this placement.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) == 0 {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0;
    } else if next_item_size > post_residual {
        score += 2.0; // next item can't use this leftover
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist
    // or when many bins are already open and mean residual is large.
    if bin_residual == bin_capacity {
        score += 25.0;
        if fitting_bins_count > 0 {
            score += 10.0 * (fitting_bins_count as f64).min(5.0);
        }
        if mean_residual > item_size as f64 {
            score += 5.0;
        }
        // Late in the stream, opening new bins is relatively cheaper to evaluate
        // but still wasteful; scale slightly with progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 5.0 * progress;
    }

    // Mild penalty for spreading across too many open bins when residuals are small.
    if open_bins_count > 4 && bin_residual < item_size * 2 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Core: normalized wasted space, non-linearly amplified with stream progress
    let x = post / cap;
    let mut score = 100.0 * x.powf(1.5 + 2.0 * progress);

    // Smooth coupling: quadratic interaction of post_residual with progress
    score += 30.0 * x * x * (0.5 + progress);

    // Penalize residual near half-capacity (dead zones), smooth bump
    let bump = (x - 0.5) / 0.25;
    score += 8.0 * (-bump * bump).exp() * (1.0 - progress);

    // Lookahead: reward residual that can host the next item, penalize just-miss
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        if gap >= 0.0 {
            score -= 12.0 * (1.0 - gap / cap) * (0.5 + progress);
        } else {
            score += 6.0 * ((-gap) / cap).powf(1.2);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - x);
    }

    // New-bin candidate: prefer it only when open bins are badly fragmented
    let is_new = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new {
        let fragmentation = (mean_residual / cap).powf(2.0);
        score = 60.0 + 40.0 * fragmentation - 20.0 * progress
            - 15.0 * (fitting_bins_count as f64).recip();
    } else {
        // Mild bonus for using bins with residuals far from mean (diversity)
        let dev = ((bin_residual as f64 - mean_residual) / cap).abs();
        score -= 3.0 * dev * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact fit classes are golden
    let pr = post_residual;
    if pr == 0 {
        score -= 200.0; // perfect fit
    } else if pr <= 5 {
        score -= 60.0; // near-perfect dead space
    } else if pr >= 90 {
        score -= 40.0; // near-empty bin, still very usable
    } else {
        // modulo-10 harmonic class: residuals divisible by 10 align with
        // typical item sizes, making them more reusable
        if pr % 10 == 0 {
            score -= 25.0;
        }
        // integer-division thresholds: small buckets are poor hosts
        let bucket = pr / 10;
        score -= (bucket as f64) * 4.0;
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 30.0; // chain placement possible
            let slack = (pr - next_item_size) as f64;
            if slack % 10 == 0 { score -= 10.0; }
        } else {
            score += 12.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Penalize spreading when many bins are open and this fit is loose
    let waste = post_residual as f64 / cap_f;
    if waste > 0.5 {
        score += 15.0 * (waste - 0.5);
    }

    // Early in stream: prefer tight packing to build good residual structure
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 8.0 * waste;

    // Mean residual attraction: prefer bins near the mean residual (balanced)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let base = 30.0 + 0.3 * open_bins_count as f64;
        score += base;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small unusable gaps (1..=9) are toxic.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }

    // Reward leaving a gap exactly matching the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    }
    // Penalize leaving a gap that cannot fit the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward using bins that are already fairly full (tight packing pressure).
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Open-bin pressure: with many open bins, discourage spreading into new space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 3.0 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Alignment with mean residual: prefer bins near the mean to keep residuals uniform.
    score += 0.5 * ((post_residual as f64 - mean_residual).abs());

    // New-bin candidate: neutral baseline, only chosen if all open bins score badly.
    if bin_residual == bin_capacity {
        score += 150.0 + 5.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size && next_item_size + item_size <= bin_capacity {
            score -= 40.0; // fresh bin can host current + next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_gap = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - match_gap / bin_capacity as f64);
    }

    // Penalize post_residuals that are small but nonzero (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Penalize opening a new bin when decent fits exist, more so late in stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(6) * 25.0;

    // Perfect fit gets a large bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + (next_item_size as f64 / 100.0) * 6.0;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate logic: prefer opening a new bin only when existing fits are poor
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = 30.0;
        // Cheaper to open a new bin early in the stream when many items remain
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
        // More expensive when many bins already open (spread waste)
        score += open_bins_count as f64 * 0.8;
        // Cheaper if the mean residual across open bins is small (they're nearly full)
        score -= mean_residual * 0.15;
        // Expensive if this bin would be the only option anyway
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
    } else {
        // Slight penalty for using bins that deviate from mean residual state
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // Mild time-dependent exploration term
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= ((step_index as f64 * 0.7).sin() + 1.0) * 1.5 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;

    let mut score = pr;

    // Tight-fit reward: strongly favor small post_residual (non-linear)
    let tight = (pr / cap).powi(3);
    score += 6.0 * tight * (1.0 + progress);

    // Reward leaving residuals that can host the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = ((pr - ni) / cap).powi(2);
            score -= 8.0 * (1.0 - slack);
        } else {
            // post-residual too small for next item: dead-space penalty
            score += 4.0 * (pr / cap) * (1.0 - progress);
        }
    }

    // Penalize opening a new bin when alternatives exist (smooth in fitting count)
    if is_new_bin {
        let alt = (fitting_bins_count as f64).max(1.0);
        score += 15.0 / alt + 10.0 * (1.0 - progress);
        // new-bin residual is large; discourage unless item is large
        score += 0.05 * (cap - item_size as f64);
    } else {
        // mild reward for using existing bins, stronger late in stream
        score -= 3.0 * (1.0 - pr / cap) * (0.5 + progress);
    }

    // Penalize bins whose residual deviates far from mean (fragmentation)
    let dev = (pr - mean_residual).abs() / cap;
    score += 2.0 * dev * dev * (1.0 + progress);

    // Slight pressure to consolidate when many bins are open
    score += 0.02 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: reward tight fits (small post_residual), with quadratic waste penalty.
    let waste = post_residual as f64;
    score += 0.02 * waste * waste / cap;

    // Harmonic class of post_residual: dead space in (0,10) is nearly unusable
    // since item sizes are >=1 but typically larger; penalize tiny slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }
    // Modulo classes: residuals that are multiples of 10 are "harmonic" slots
    // (common item sizes land on them); reward divisible-by-10 residuals.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }
    // Quarter-capacity harmony: residual expressible as exact quarter of capacity.
    if post_residual as f64 == cap * 0.25 || post_residual as f64 == cap * 0.5 || post_residual as f64 == cap * 0.75 {
        score -= 2.0;
    }

    // Lookahead coupling: if the next item fits the post_residual exactly,
    // strongly favor this bin (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 10.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves another sliver: mild penalty scaled by
            // how close it is to a perfect fill.
            let after2 = post_residual - next_item_size;
            score += (after2 as f64) * 0.15;
            if after2 < 10 { score += 3.0; }
        } else {
            // next item will not fit here: slight reward for keeping space
            // flexible (residual stays large-ish).
            score -= (post_residual as f64) * 0.02;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has large raw score already
    // (post_residual == capacity). Penalize opening a new bin unless the item
    // is large or all existing fits are bad.
    if bin_residual == bin_capacity {
        // Opening cost grows with number of already open bins.
        score += 25.0 + 3.0 * open_bins_count as f64;
        // Large items are better placed fresh (avoid fragmenting an old bin).
        if item_size >= 50 {
            score -= 18.0;
        }
        // Late in the stream, avoid accumulating many open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Mild preference for fuller bins relative to fleet mean residual.
    score -= 0.05 * (mean_residual - bin_residual as f64);

    // Integer-division threshold: bins whose residual can hold exactly
    // capacity/post_residual items of size >= 10 are more useful.
    let useful_units = post_residual / 10;
    score -= useful_units as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Medium dead space (12..25) is often unusable too.
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score -= 40.0 / (1.0 + fit_ratio);

    // Lookahead: if next item fits into post_residual, strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0;
    }
    // Penalize if next item would be blocked by this placement.
    if next_item_size > post_residual && next_item_size > bin_residual {
        score += 10.0;
    }

    // Open-bin pressure: discourage spreading across too many bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + 3.0 * progress);

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Prefer bins below mean residual (concentrate free space).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: mild penalty so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;

    // Base: prefer small post_residual (tight packing)
    let mut score = post;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Near match: next item still fits in the leftover
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / cap);
    }
    // Next item will NOT fit in the leftover: penalize proportionally
    else if next_item_size > 0 {
        score += 15.0 * (nxt / cap);
    }

    // Reward bins with residual below mean (denser bins) — keep them tight
    let mean_gap = mean_residual - post;
    score += 0.3 * mean_gap;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin gives a good fit.
    // Penalize opening a new bin generally; discount penalty late in the stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let good_fit_exists = next_item_size > 0 && post_residual == next_item_size;
        let _ = good_fit_exists;
        score += 25.0 + 20.0 * (1.0 - progress);
        // A fresh bin gives perfect flexibility for the next item too
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0;
        }
        // If many bins are open, mildly discourage adding more
        score += (open_bins_count as f64).sqrt() * 1.5;
    }

    // Small bonus for filling bins nearly completely
    score -= 10.0 * (1.0 - post / cap) * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits in the post residual (chain packing),
    // penalize if this placement nearly blocks a plausible next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 5.0;
        } else if post_residual > 0 && next_item_size > post_residual && post_residual < 10 {
            score += 3.0; // tiny dead space unlikely to be usable later
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is generally costly,
    // but attractive when all open bins would leave large unusable leftovers
    // or when the open-bin pool is already large and fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Penalize opening new bin early; soften late in the stream.
        score += 15.0 * (1.0 - 0.5 * progress);
        // If existing bins fit poorly (big mean residual mismatch), new bin is fine.
        score -= 0.05 * fragmentation;
        // Many open bins: prefer consolidating rather than opening more.
        score += 0.5 * open_bins_count as f64;
        // If item is large relative to capacity, new bin keeps big items together.
        if item_size * 2 >= bin_capacity {
            score -= 8.0;
        }
    } else {
        // Mild reward for keeping bins balanced vs mean residual.
        score += 0.02 * (bin_residual as f64 - mean_residual).abs();
    }

    // Slight preference for filling emptier bins when many are open.
    if bin_residual != bin_capacity {
        score -= 0.01 * (bin_capacity as f64 - bin_residual as f64) * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let prn = pr / capacity; // normalized post residual in [0,1]
    let t = progress;
    // Smooth interaction: waste penalized more as stream progresses
    let coupling = prn * prn * (1.0 + 2.0 * t) - prn * t * (1.0 - t);
    score += 40.0 * coupling;

    // Reward tight fits smoothly (small post_residual gets extra discount)
    score -= 30.0 * (1.0 - prn) * (1.0 - prn) * (1.0 - 0.5 * t);

    // Penalize bins that are outliers vs mean residual (smooth quadratic)
    let dev = (bin_residual as f64 - mean_residual) / capacity;
    score += 10.0 * dev * dev;

    // Last-chance bin discount (smooth, based on fitting bins count)
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        score -= 5.0 / fitting_bins_count as f64;
    }

    // Lookahead: favor bins whose leftover can fit the next item (smooth bonus)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let fit_quality = 1.0 - ((pr - nxt) / capacity);
            score -= 12.0 * fit_quality * (1.0 - t);
        } else {
            score += 6.0 * (1.0 - pr / nxt.max(1.0)) * (1.0 - t);
        }
    }

    // Mild pressure against proliferating bins late in the stream
    score += 0.5 * (open_bins_count as f64).ln() * (0.5 + t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual modulo capacity quarters
    let q = bin_capacity / 4;
    let class = post_residual % q; // 0..q harmonic position
    // Reward residuals that are near-zero (perfect fit) or near q (fits a small item)
    if class == 0 {
        score -= 40.0; // perfect partition point
    } else if class >= q - 10 {
        score -= 15.0; // leaves room for a small item
    } else {
        score += class as f64 * 0.8; // penalize awkward mid-class dead space
    }

    // Integer-division threshold on post_residual: does it fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Lookahead chains nicely; stronger reward the tighter the chain
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - slack * 0.5;
        } else {
            // Next item won't fit here: penalize proportional to wasted potential
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Capacity fraction coupling: bins that are nearly full are good to fill
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * fill_frac * 30.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && post_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when open bins are congested
    if bin_residual == bin_capacity {
        let congestion = mean_residual / bin_capacity as f64;
        if congestion < 0.35 {
            score -= 20.0;
        } else {
            score += 25.0 + open_bins_count as f64;
        }
    }

    // Late in the stream, prefer consolidating into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible item (1..=100 range, but small gaps < ~15 are
    // almost never reusable) are heavily penalized.
    let dead_threshold = 15.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Extra penalty for "nearly full" bins left with unusable crumbs.
    if post_residual > 0 && post_residual < 5 {
        score += 25.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving a gap that can fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; a new empty bin should be less
    // attractive when open_bins_count is already high.
    if bin_residual == bin_capacity {
        score += 20.0 + (open_bins_count as f64) * 3.0;
    } else {
        score -= (open_bins_count as f64).min(10.0) * 1.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer bins whose residual is below the mean (tighter packing).
    score += ((bin_residual as f64) - mean_residual) * 0.4;

    // Mild progression term: late in the stream, be more conservative about
    // opening bins (dead space matters more when few items remain).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * tightness * tightness;

    // 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        if post_residual >= next_item_size {
            // Next item fits exactly in the leftover: excellent chain placement.
            score -= 45.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit in leftover: penalize wasted chain opportunity,
            // scaled by how close it was (near-miss hurts more).
            let near_miss = 1.0 - gap / (bin_capacity as f64);
            score += 25.0 * near_miss.max(0.0);
        }
        // Bonus if post_residual can hold next item AND next item is large (hard to place).
        if post_residual >= next_item_size && next_item_size > bin_capacity / 3 {
            score -= 15.0;
        }
    } else {
        // Last item: just pack tight, no future considerations.
        score -= 10.0;
    }

    // Compare against mean residual of open bins: prefer bins with less residual
    // than average (i.e., already well-filled bins).
    score += 0.35 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful unless the current
    // fit is terrible or the item barely fits nowhere well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // More open bins already => slightly more reluctant to open another.
        score += 2.0 * open_bins_count as f64;
        // If item is large relative to capacity, a fresh bin is more acceptable.
        score -= 0.4 * item_size as f64;
        // If next item is also large, a fresh bin gives flexibility.
        if next_item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        // Early in the stream, opening bins is cheaper (more items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * (1.0 - progress);
    }

    // Mild penalty for very large item in a nearly-empty existing bin
    // (keep big residual bins flexible for large future items).
    if bin_residual != bin_capacity && item_size as f64 > 0.7 * bin_capacity as f64 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: relative waste term
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_ratio * waste_ratio;

    // Penalize dead space that can't hold typical items
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 40 {
        score += 4.0; // moderately usable
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            score -= 10.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty proportional to mismatch
            score += 5.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Time horizon: early in stream, be conservative (prefer filling existing bins);
    // late in stream, tightness matters more than new bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global state: many open bins -> discourage opening new ones (score new-bin candidate higher)
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
        // but if no open bin fits well, allow new bin
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // if mean residual across open bins is large, opening new bin is wasteful
        score += 0.5 * mean_residual;
    }

    // Prefer bins with residual close to item (best-fit flavor)
    let fit_gap = (bin_residual - item_size) as f64;
    score += 0.1 * fit_gap;

    // Slight preference for bins below mean residual (balance load)
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream, tolerate larger residuals; late, tighten aggressively.
    let pn = post / cap; // normalized post residual in [0,1]
    let w = 0.6 + 1.8 * progress * progress; // progress-scaled weight
    score += w * cap * pn * pn;

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness * (1.0 - pn);

    // Penalize dead space that cannot fit the next item (smooth coupling).
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - post).max(0.0) / cap;
        score += 20.0 * gap * gap * (0.5 + progress);
        // Bonus if post residual exactly accommodates next item.
        if post_residual == next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: prefer opening a new bin only if existing bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fit = pn - (item_size as f64 / cap); // residual left if item placed in fresh bin
        score = cap * (0.35 + 0.5 * progress) + 10.0 * poor_fit * poor_fit * cap;
        // Discourage excessive bin proliferation early.
        score += 2.0 * open_bins_count as f64 * (1.0 - progress);
        // If many bins fit, opening new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 25.0;
        }
    }

    // Mild alignment with mean residual: prefer bins whose resulting residual
    // matches fleet average (smooths future packing options).
    let dev = (post - mean_residual) / cap;
    score += 4.0 * dev * dev * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: quadratic in wasted space
    let waste = post_residual as f64;
    score += 0.02 * waste * waste;

    // Harmonic class of post_residual: residuals in small modulo classes are more reusable
    let pr = post_residual;
    if pr > 0 {
        // residuals divisible by common item sizes (10,20,25,50) are attractive
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 25 == 0 { score -= 6.0; }
        if pr % 50 == 0 { score -= 4.0; }
        // very small dead space (< smallest plausible item) is nearly dead
        if pr < 10 {
            score += 25.0 * (10 - pr) as f64;
        }
    }

    // Lookahead: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // reward: next item can also go here -> chaining
            let leftover2 = pr - next_item_size;
            score -= 10.0 + 0.1 * leftover2 as f64;
            if leftover2 == 0 { score -= 15.0; }
        } else {
            // penalize blocking the next item
            score += 0.5 * (next_item_size - pr) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer filling bins among many open bins (bin consolidation)
    score += 0.5 * open_bins_count as f64;

    // Pull toward mean residual: avoid outliers creating fragmented space
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // New-bin candidate handling: only open a new bin when current fits are bad
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 40.0;
        // late in stream, opening new bins is fine since stream continues
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
        // if next item is large and current bin residual small, new bin attractive
        if next_item_size > 0 && next_item_size > bin_residual {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a future item (min size 1, but practically tiny gaps < 12)
    // are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 12 {
        score += 40.0 + (12 - post_residual) as f64 * 3.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward bins whose residual tightly matches the item (low waste fraction).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * 20.0;

    // If a future item can exactly use the leftover, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 12 {
            score -= 25.0 - gap as f64;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // leftover too small for the next item: mild dead-space penalty
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new bins (penalize the new-bin candidate).
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 4.0;
        // But if mean residual across open bins is low (bins nearly full),
        // opening a new bin is more acceptable.
        score -= mean_residual * 0.3;
        // Late in the stream, prefer consolidation into open bins.
        score += (step_index as f64 / total_items.max(1) as f64) * 10.0;
    }

    // Mild preference for bins with residual close to the mean (balance).
    score -= (mean_residual - bin_residual as f64).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= (post_residual as f64 * 1.5) * (1.0 / (1.0 + gap / 10.0));
        // bonus if next item fits exactly in the post residual
        if post_residual == next_item_size {
            score -= 200.0;
        } else if post_residual >= next_item_size {
            // next item can still fit: mild bonus proportional to tightness
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot fit: penalize dead space creation
            score += 15.0 + gap * 0.5;
        }
    }

    // Penalize large post_residual relative to mean residual (wasteful fit)
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 40.0 };
        let tight_next = if next_item_size > 0 && next_item_size >= item_size { 20.0 } else { 0.0 };
        score += 25.0 + pressure + tight_next;
        // late in the stream, prefer compacting into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
    }

    // Slight preference for tighter fits overall
    score -= (bin_capacity - post_residual) as f64 * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is good, non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no future item can plausibly fill.
    // Assume typical item ~ (bin_capacity / 4); residuals below ~10 are near-waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no
    // open bin fits well, or the stream is early and we can afford slack.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty so an existing decent fit usually wins.
        score += 18.0;
        // Early in the stream, allow more bin openings (spread risk).
        score -= 20.0 * (1.0 - progress);
        // If many bins fit, opening a new one is wasteful.
        score += 3.0 * (fitting_bins_count as f64).min(6.0);
        // If the mean residual of open bins is small, open bins are tight;
        // a fresh bin becomes more attractive.
        score -= (mean_residual / bin_capacity as f64).max(0.0) * 15.0;
        // Lookahead: if next item is large, a fresh bin gives flexibility.
        if next_item_size > 0 && (next_item_size as f64) > 0.6 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Lookahead coupling: if the next item exactly fills this bin's post-residual,
    // strongly reward this placement (perfect chaining).
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // Next item fits here too: mild reward proportional to fill.
            score -= 5.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use the leftover: penalize large leftovers.
            score += 4.0 * (next_item_size as f64 / post_residual as f64 - 1.0).min(3.0);
        }
    }

    // Many open bins: prefer consolidating into existing bins to reduce spread.
    score += 0.4 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Late in the stream, be more conservative: prefer tight existing fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover residual with a non-linear (quadratic) term.
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Coupling with stream progress: later in the stream, residual waste matters more.
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Lookahead: reward bins whose post-residual matches the next item size well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let fit_gap = (pr - nxt) / cap;
            score -= 25.0 * (1.0 - 2.0 * fit_gap).max(0.0);
        } else {
            // Post-residual too small for the next item: mild penalty scaled by waste.
            score += 10.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: strongly favor the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Smoothly penalize divergence from the mean residual (keep residuals balanced).
    score += 0.5 * (pr - mean_residual).abs();

    // Slight penalty for spreading across many open bins.
    score += 0.5 * open_bins_count as f64;

    // Discourage opening a new bin when good existing fits exist.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 20.0 + 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class: reward post_residuals that are "perfect" residual classes
    // (multiples of common item sizes 10..80 granularity).
    let pr = post_residual as u32;
    let mut class_bonus = 0.0f64;
    for &m in &[10u32, 20, 25, 50] {
        if pr % m == 0 && pr > 0 {
            class_bonus += 8.0 * (m as f64 / 10.0);
        }
    }
    score -= class_bonus;

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let leftover = pr - next_item_size;
            // penalize awkward leftovers that no typical item fits
            if leftover < 10 {
                score += 12.0;
            } else {
                score -= 5.0 * (leftover as f64 / 80.0);
            }
        } else {
            // next item cannot use this residual: dead space penalty scaled
            score += 6.0 * (pr as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Fractional capacity coupling: prefer filling bin to high fraction.
    let fill = (bin_capacity - post_residual) as f64 / cap;
    score -= 20.0 * fill * fill;

    // Penalize opening a new bin when decent fits exist.
    if bin_residual == bin_capacity {
        score += 25.0;
        if mean_residual > 30.0 {
            score += 0.3 * mean_residual;
        }
        // early stream: allow new bins more freely
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Tight-fit reward: item nearly fills the bin.
    if pr <= 5 && pr > 0 {
        score -= 25.0;
    }

    // Modulo threshold: post_residual in awkward zone (just below smallest item)
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Mean residual pressure: if this bin is far below mean residual, it's a good dump
    let dev = mean_residual - post_residual as f64;
    score += 0.1 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps quadratically.
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.10);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64).powi(2) * 3.0;
    }

    // Reward tight fits (low post_residual relative to item).
    if item_size > 0 {
        score -= (item_size as f64 / bin_residual.max(1) as f64) * 15.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: penalize placements that keep many bins open
    // unless the fit is very tight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.0 + progress) * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual gap,
    // this placement chains nicely; otherwise the gap is likely dead.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // New-bin candidate: attractive when the current fit is loose
    // (large post_residual) or when few bins are open.
    if bin_residual == bin_capacity {
        let loose = post_residual as f64 / bin_capacity as f64;
        score -= 30.0 * loose;
        if open_bins_count == 0 {
            score -= 50.0;
        }
        // Discard dead-space penalty for a fresh empty bin.
        score += dead_threshold * dead_threshold * 3.0 * 0.0;
    }

    // Slight preference for bins below mean residual (balance load).
    score += (post_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.8 * lookahead_gap;
        // Perfect chain fit bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // If the next item cannot fit anywhere else, this chain matters more
        if post_residual < next_item_size {
            score += 10.0; // dead space relative to lookahead
        }
    } else {
        // Last item: waste minimization is everything
        score += 15.0 * post_residual as f64;
    }

    // Prefer tight fits relative to bin capacity
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // Compare against mean residual across open bins: keep balance but reward below-average waste
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Early in stream: be more willing to open fresh bins for large items
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive when item is large or late in stream
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 30.0;
        score -= 5.0 + large_item_bonus + 10.0 * progress;
        // Penalize new bin if a good fit exists elsewhere
        if next_item_size > 0 && post_residual == bin_capacity - item_size {
            // post_residual of empty bin equals capacity - item; compare to lookahead
            if (post_residual as i64 - next_item_size as i64).abs() <= 5 {
                score -= 10.0;
            }
        }
    }

    // Many open bins: discourage spreading, favor consolidation
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post-residual, especially exact/near-exact fits.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for any future item (min size 1, but typical >=10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits into post_residual, this placement is great.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // this bin would have served the next item; slight penalty
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor fits.
    if bin_residual == bin_capacity {
        // penalize opening new bins when mean residual could still host items well
        let waste = (mean_residual - item_size as f64).abs();
        score += 20.0;
        score -= waste;
        // late in stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // many open bins: discourage more
        score += 1.5 * open_bins_count as f64;
    }

    // Mild preference for filling fuller bins among equals
    score -= 0.05 * (bin_residual as f64);

    // Encourage closing out bins with small residuals to reduce open-bin clutter
    if post_residual < 15 && post_residual > 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Smooth non-linear coupling: waste of post_residual is penalized more
    // as the stream progresses (later placements should be tighter).
    let pr = post_residual as f64 / bin_capacity as f64;
    let tightness = pr * pr * (0.5 + progress);
    score += 40.0 * tightness;

    // Reward near-perfect fits with a smooth quadratic bonus.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Lookahead coupling: penalize if next item fits poorly into post_residual
    // (smooth interaction instead of piecewise cutoff).
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        let norm_gap = gap / bin_capacity as f64;
        score += 15.0 * norm_gap * (1.0 - norm_gap) * (0.5 + 0.5 * progress);
    }

    // Last-chance bin: strongly reward using it (avoid opening new bin).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (1.0 - 0.5 * progress);
    }

    // New-bin candidate: mildly penalize early, allow later when open bins are fragmented.
    let fragmentation = (mean_residual - post_residual as f64).abs() / bin_capacity as f64;
    score += 8.0 * (1.0 - progress) * (1.0 - fragmentation.min(1.0));

    // Mild penalty proportional to number of open bins (encourage consolidation).
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space classes modulo 10
    let pr = post_residual as i64;
    let class = pr % 10;
    // Penalize awkward residual classes (small leftovers that nothing fits)
    if pr > 0 && pr < 10 {
        score += 12.0; // dead space below min item size
    } else if class == 0 {
        score -= 6.0; // perfectly harmonic residual
    } else if class >= 7 {
        score -= 2.0; // near-harmonic
    } else {
        score += 3.0; // awkward mid-class
    }

    // Integer-division thresholds: does post_residual admit next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // reward leaving room for the lookahead item
            let slack = post_residual - next_item_size;
            score -= (slack as f64) * 0.35;
            // bonus if residual is an exact multiple of next item size
            if slack % (next_item_size as i64) == 0 {
                score -= 4.0;
            }
        } else {
            // post_residual cannot host next item: penalize proportionally
            score += 8.0 + (next_item_size as f64 - post_residual as f64) * 0.2;
        }
    }

    // Capacity fractions: prefer tight fits relative to capacity
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * 15.0;

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 25.0 * (1.0 - pressure);
        if open_bins_count == 0 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
    }

    // Stream progression: tighten packing as stream advances
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= fill * progress * 5.0;

    // Mean residual coupling: prefer bins near the mean residual (balance)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    let pr = post_residual as f64;
    if post_residual > 0 {
        // gaps that can't fit even the smallest plausible item are dead space
        let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.1);
        if pr <= dead_threshold {
            score += 60.0 * (dead_threshold - pr + 1.0);
        } else {
            // convex penalty on wasted space (superlinear in residual)
            score += 0.02 * pr * pr / bin_capacity as f64;
        }
    }

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here: mildly penalize leaving a gap that may strand
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, use it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should only win when open bins
    // would create bad dead space or fit is poor.
    if bin_residual == bin_capacity {
        // base cost of consuming fresh capacity
        score = (bin_capacity - item_size) as f64;
        score += 0.5 * open_bins_count as f64; // slight preference to reuse open bins
        // but if open bins are crowded (mean residual small), a new bin is attractive
        score -= (mean_residual - 20.0).max(0.0) * 0.3;
        // if item is large relative to mean residual, new bin helps
        if (item_size as f64) > mean_residual {
            score -= 20.0;
        }
        // no lookahead benefit lost: new bin leaves room for next item
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 10.0;
        }
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins
    score += 0.15 * open_bins_count as f64 * (1.0 - tightness.min(1.0));

    // Stream progression: later in stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: massive reward
    if post_residual == 0 {
