        return score;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_gap = (post_residual - next_item_size) as f64;
        score -= 60.0 - lookahead_gap * 0.4;
