    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize dead space more when leftover is small
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Penalize small unusable residuals (dead space) non-linearly
    if post_residual < 10 {
        score += 80.0;
    } else if post_residual < 20 {
        score += 30.0;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving less than average residual is good (compact packing)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Discourage opening new bins when many bins are open with room
    if bin_residual == bin_capacity {
        score += 50.0 + open_bins_count as f64 * 5.0;
        // If nothing fits well elsewhere, new bin becomes acceptable
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
    }

    // Slight preference for balancing residuals late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 - mean_residual).abs() * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual non-linearly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    } else if post_residual <= 20 {
        score -= 4.0;
    } else {
        // Penalize large dead space quadratically.
        score += (post_residual as f64 - 20.0) * (post_residual as f64 - 20.0) * 0.02;
    }

    // Lookahead coupling: if the next item fits into the post_residual,
    // reward this placement; otherwise penalize blocking the lookahead.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Global state: many open bins with high mean residual -> prefer filling
    // existing bins rather than opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open bins are underutilized.
        score += 15.0 + open_bins_count as f64 * 2.0 + mean_residual * 0.1;
        // Early in the stream, opening a bin is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 25.0;
        // If no open bin fits well, new bin is more attractive.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else {
        // Prefer bins whose residual deviates favorably from the mean
        // (filling the emptier bins balances residuals).
        let dev = bin_residual as f64 - mean_residual;
        score += dev * 0.05;
        // More open bins -> stronger pressure to consolidate.
        score -= open_bins_count as f64 * 0.5;
    }

    // Mild time-horizon effect: late in stream, avoid creating any residual.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += post_residual as f64 * progress * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let is_new_bin = (bin_residual == bin_capacity) as f64;

    // Base: quadratic waste coupling, modulated by stream progress
    let mut score = pr * (1.0 + 1.5 * norm_pr * (1.0 + progress));

    // Smooth non-linear interaction: residual vs mean residual of open bins
    let mean_gap = (mean_residual - pr) / cap;
    score += 8.0 * mean_gap * mean_gap * (0.5 + progress);

    // Lookahead: reward residual that can host the next item (smooth kernel)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit = if pr >= nx { 1.0 - (pr - nx) / cap } else { 0.0 };
        let nx_norm = nx / cap;
        score -= 12.0 * fit * nx_norm * (1.0 - progress * 0.5);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && is_new_bin < 0.5 {
        score -= 15.0 * (0.4 + 0.6 * progress);
    }

    // Penalize opening new bins, softly increasing with progress and open count
    score += is_new_bin * (10.0 + 0.3 * open_bins_count as f64 + 20.0 * progress);

    // Mild bonus for nearly-full bins (tight packing)
    score -= 6.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - is_new_bin);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 and 12
    let res = post_residual % 10;
    let res12 = post_residual % 12;

    // Penalize dead space in awkward residue classes
    if post_residual > 0 {
        score += 8.0 * (res as f64 / 10.0);
        score += 4.0 * (res12 as f64 / 12.0);
    } else {
        score -= 15.0; // perfect fill reward
    }

    // Integer division thresholds on post_residual
    let q = post_residual / 25; // 0..4 quarters
    score += q as f64 * 2.5;

    // Coupling with next item: reward residuals that can host the lookahead item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
            // harmonic bonus if next item exactly fits a harmonic class
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // residual too small for lookahead: penalize proportionally
            score += 7.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Capacity fraction of the filled portion
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill_frac * fill_frac;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let base = 45.0 + 10.0 * (open_bins_count as f64).ln1p();
        // Open a new bin only if all existing fits are poor (large post_residual)
        let poor_fit = if post_residual as f64 > mean_residual { 1.0 } else { 0.0 };
        score = base - 12.0 * poor_fit + (item_size as f64 / bin_capacity as f64) * 5.0;
        if next_item_size > 0 && next_item_size > bin_residual {
            score -= 8.0; // fresh bin guarantees room for lookahead
        }
    }

    // Late-stream tightening: prefer tight fits as stream progresses
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Deter wasteful many-bin states
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "unusable" if it is smaller than the smallest plausible item (1)
    // or too small to be attractive for the next item.
    let dead_zone: f64 = 12.0;
    if (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 3.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward when post_residual can still host the lookahead item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0;
            let gap = post_residual - next_item_size;
            if gap < dead_zone {
                score += gap as f64 * 1.5;
            }
        } else {
            // Bin cannot host next item: mild penalty unless it's a near-perfect fit now.
            score += 3.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling existing ones.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 2.0;
    if bin_residual != bin_capacity {
        score -= pressure;
    } else {
        // New bin candidate: penalize opening unless current bins are quite full.
        score += pressure + 6.0;
        if (mean_residual - item_size as f64) < dead_zone {
            score -= 10.0; // existing bins are nearly dead -> opening is fine
        }
    }

    // Prefer bins whose residual is close to the item (tight fit).
    score += ((bin_residual - item_size) as f64).abs() * 0.2;

    // Late-stream consolidation: as stream progresses, favor tightening.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact fit: post_residual == 0
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // perfect chaining: next item exactly fits
        } else if post_residual >= next_item_size {
            score -= 2.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
        } else {
            // dead space the next item cannot use — penalize proportionally
            score += 0.5 * (post_residual as f64) * (1.0 - next_item_size as f64 / post_residual.max(1) as f64);
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when decent existing fits exist
    if bin_residual == bin_capacity {
        let new_bin_penalty = if fitting_bins_count == 0 {
            0.0 // no alternative, must open
        } else {
            // opening a new bin wastes the residual of an existing bin
            150.0 + 0.5 * bin_residual as f64
        };
        score += new_bin_penalty;
        // opening a new bin is more attractive early when we can chain the next item
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 1.0 * (next_item_size as f64 / bin_capacity as f64) * 100.0;
        }
    }

    // Late in the stream: prefer tighter packing, avoid leaving many open bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 0.2 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Small tie-break: prefer larger item relative to residual (denser fill)
    score -= 0.1 * (item_size as f64 / bin_residual.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space quadratically, scaled by capacity.
    let dead = post_residual as f64;
    score += (dead * dead) / (bin_capacity as f64);

    // Lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving awkward leftover.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist, to encourage spreading.
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Time horizon: early in the stream, be conservative (favor tighter fits);
    // later, allow new bins more readily when residuals are fragmented.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * fit_ratio;

    // Global state coupling: if mean residual is high relative to item, prefer
    // consuming from fat bins; if mean residual is low, penalize wasting this bin.
    let mean_ratio = mean_residual / bin_capacity as f64;
    score += 10.0 * mean_ratio * (1.0 - fit_ratio);

    // New-bin candidate handling: empty bin gets baseline cost that shrinks
    // if item is large or existing bins are nearly full.
    if bin_residual == bin_capacity {
        let base = 20.0
            - 0.15 * item_size as f64
            - 5.0 * mean_ratio
            - 3.0 * progress;
        score = base + item_size as f64;
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a new bin
        }
    }

    // Small tie-breaker on open bins count to prefer consolidating into fewer bins.
    score -= 0.05 * open_bins_count as f64 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr;

    // Smooth non-linear coupling: dead space penalized super-linearly,
    // with penalty intensifying as the stream progresses.
    let dead = pr_norm * pr_norm;
    score += 12.0 * dead * (0.5 + progress) * cap;

    // Reward tight fits (small post_residual) more strongly later in stream.
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * 8.0 * (0.3 + 0.7 * progress);

    // Last-chance bonus: strongly prefer the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer bins whose residual deviates below the mean (consolidating space).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * (1.0 - progress);

    // Lookahead: if next item fits in post_residual, reward; else penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 5.0 * (1.0 - pr_norm) * (0.4 + 0.6 * progress);
        } else {
            score += 4.0 * (nx - pr) / cap;
        }
    }

    // Mild penalty for spreading across many open bins early on.
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    // Bias toward opening new bins early (cheap now, useful later).
    if bin_residual == bin_capacity {
        score += 10.0 * progress - 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic-class reward: residual that is a "clean" fraction of capacity
    // (multiples of 25, 20, 10) is more reusable by future items.
    let clean_classes: [u32; 4] = [0, 25, 50, 20];
    for c in clean_classes.iter() {
        if post_residual % 100 == *c && post_residual > 0 {
            score -= 6.0;
        }
    }
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item (1..100)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    // Residual that cannot pair with the lookahead item is less useful
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }
    // Reward residual that exactly accommodates the next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    // Integer-division thresholds on post_residual
    match post_residual / 25 {
        0 => score += 4.0,   // tiny leftovers are poor
        1 => score -= 2.0,   // 25..49: moderately reusable
        2 => score -= 4.0,   // 50..74: good
        _ => score -= 6.0,   // large residual: best
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: prefer open bins unless residual is badly fragmented
    if bin_residual == bin_capacity {
        score += 30.0;
        // Opening a new bin is attractive when open bins are mostly full
        if mean_residual < 20.0 {
            score -= 25.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Stream progression: late in the stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64).abs() * 0.5;
    score += progress * 2.0;

    // Coupling with mean residual: bins far from the mean are penalized slightly
    score += ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that cannot fit the smallest plausible item (1) is impossible here,
    // but tiny residuals relative to typical item sizes create dead space.
    let min_item = 1.0f64;
    if post_residual > 0 {
        // Penalize residuals too small to be useful for future items.
        // Use a soft threshold: residuals below ~20 are likely dead space.
        let dead_threshold = 20.0f64;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 3.0;
        }
        // Perfect fit bonus: strongly reward near-zero post residual.
        if post_residual <= 2 {
            score -= 15.0;
        }
    } else {
        // Exact fill is ideal.
        score -= 25.0;
    }

    // Reward placements where the leftover can host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            // Leftover cannot fit next item: mild dead-space penalty.
            score += (post_residual as f64) * 0.3;
        }
    }

    // Open-bin pressure: when many bins are open, prefer compacting into
    // existing bins (penalize opening new ones implicitly via new-bin call
    // receiving a penalty tied to open_bins_count).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins pressure.
        score += 12.0 + pressure * 2.0;
    } else {
        // Slight reward for using existing bins when pressure is high.
        score -= pressure.min(6.0) * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below mean
    // (tighter bins) to keep loose bins available for larger items.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res).min(15.0) * 0.4;
    } else {
        score += (res - mean_residual).min(15.0) * 0.2;
    }

    // Mild tie-break: prefer bins with smaller original residual (tighter fit).
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can also absorb the next item: strong reward proportional to reuse.
            score -= 0.6 * next_item_size as f64;
            // Extra reward if next item fills the bin almost exactly after this placement.
            let two_step_gap = post_residual - next_item_size;
            score -= 0.3 * (bin_capacity as f64 - (two_step_gap as f64)) * 0.0
                   + 0.25 * (bin_capacity as f64 - two_step_gap as f64 - item_size as f64).max(0.0);
        } else {
            // Next item cannot follow into this bin: penalize proportionally to the leftover gap.
            let gap = next_item_size - post_residual;
            score += 0.35 * gap as f64;
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving below-average residual wastes capacity elsewhere; leaving above-average is fine.
    score += 0.4 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // With multiple options, prefer tighter fits more aggressively.
        score += 0.15 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: empty bin gets a mild handicap so we only open
    // a new bin when no open bin offers a decent fit, but keep it viable when
    // open bins would fragment badly.
    if bin_residual == bin_capacity {
        score += 18.0;
        // If no other bin fits, opening a new bin is the right move.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // If the next item is large relative to capacity, opening a fresh bin now
        // preserves flexibility for it.
        if next_item_size > 0 && next_item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Late in the stream, consolidate more aggressively (fewer bins preferred).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual already does this, but amplify superfit.
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    } else if post_residual < 10 {
        score -= 15.0; // near-perfect fill (dead space below min item size)
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits, but leaves more fragmentation: mild penalty proportional to leftover
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here: penalize bins that would strand space
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits the item, prefer it heavily
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    // Penalize it so it's only chosen when no reasonable fit exists, but relax
    // the penalty late in the stream or when open bins are highly fragmented.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = (mean_residual - post_residual as f64).abs() / bin_capacity as f64;
        score += 60.0 - 30.0 * progress - 20.0 * fragmentation;
    }

    // Prefer bins whose residual is close to the mean (avoid creating outliers),
    // scaled mildly to not dominate tight-fit rewards.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for consolidating into fewer bins when many are open.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: quadratic decay of penalty as post_residual shrinks
    let fit_ratio = post / cap;
    score -= 12.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio) * item_size as f64 / cap;

    // Penalize dead space that can't fit the next item (lookahead coupling)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 6.0 * (nxt - post) / cap * (0.5 + progress);
        } else {
            score -= 3.0 * (1.0 - (post - nxt) / cap) * 0.25;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0 + 10.0 * progress;
    }

    // Many open bins: prefer filling existing ones over opening new
    if bin_residual != bin_capacity {
        score -= 1.5 * (open_bins_count as f64).ln().max(0.0);
    } else {
        // New-bin candidate: penalize mildly unless residuals are all poor
        score += 4.0 + 6.0 * (mean_residual / cap).min(1.0) * (1.0 - progress);
    }

    // Smooth stream-progress coupling: later in stream, favor compactness more
    score += post * (0.2 + 0.5 * progress * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: penalize dead space in "awkward" classes
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_frac = pr / cap; // fraction of capacity wasted

    // Non-linear waste penalty: quadratic growth of small residuals
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Modulo classes on post_residual (harmonic buckets of 10)
    let bucket = post_residual / 10;
    score -= match bucket {
        0 => 8.0,          // tiny residual, near-perfect fit
        1 => 2.0,
        2 => 0.0,
        3 => -1.0,
        4 => -2.0,
        _ => -3.0,         // large residual keeps bin useful
    };

    // Reward filling bins nearly exactly
    if post_residual == 0 {
        score -= 25.0;
    }

    // Harmonic coupling with next item: does post_residual accommodate it?
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            // leaving room for the next item is good, but only mildly
            score -= 4.0;
            // integer-division threshold: how many times next item fits
            let fits = post_residual / next_item_size.max(1);
            score -= fits.min(3) as f64 * 2.0;
        } else {
            // dead space relative to next item
            let gap = next_item_size - post_residual;
            score += gap as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening new bins unless current bin is bad
    if bin_residual == bin_capacity {
        score += 12.0 + (open_bins_count as f64) * 0.5;
        // but if the item is huge relative to mean residual, new bin is attractive
        let mean_r = mean_residual;
        if mean_r > 0.0 && (item_size as f64) > mean_r + 5.0 {
            score -= 10.0;
        }
    }

    // Progress-based pressure: late in stream, prefer tight packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (100.0 - pr) * 0.02;

    // Coupling with mean residual: prefer bins below mean (tighter bins)
    score += (mean_residual - pr) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // plausible future item (min item size 1, but practically small gaps)
    // become "dead space". Penalize unusable gaps super-linearly.
    let dead_threshold = 10.0_f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 2 {
        score -= 12.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise the item forces a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits into the post residual,
    // reward this placement (chain packing).
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 6.0;
    } else if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
        score += 2.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when no open bin offers a decent fit (large dead-space risk).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let decent_fit_exists = mean_residual >= item_size as f64 * 1.2;
        if decent_fit_exists {
            score += 15.0; // penalize opening a bin when open bins fit well
        } else {
            score -= 5.0; // encourage fresh bin when fits are poor
        }
        // Slight late-stream bias toward consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 4.0;
    }

    // Mean residual alignment: prefer bins whose residual is near the mean
    // (keeps bin states homogeneous, easier future packing).
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins where the residual can host the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // exact chain fit
        } else if post_residual >= next_item_size {
            score -= 2.0 * next_item_size as f64;
        } else {
            // next item won't fit here; penalize wasted residual relative to next item
            let waste = post_residual as f64 / next_item_size as f64;
            score += 5.0 * waste;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a perfect chain
    if bin_residual == bin_capacity {
        score += 150.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 100.0; // opening a new bin for a good pair is fine
        }
    }

    // Early in stream: be slightly more open to new bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * (1.0 - progress);

    // Many open bins: discourage spreading
    score += 1.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream (0..1).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Fractional dead space: waste relative to capacity.
    let dead_frac = post_residual as f64 / bin_capacity as f64;

    // Perfect-fit reward: strongly favor bins that end up (nearly) full.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if dead_frac < 0.1 {
        score -= 50.0;
    }

    // Lookahead coupling: reward if the next item can fit into post_residual
    // (chaining potential), penalize if the leftover is a "dead zone" that
    // no plausible item (1..=100) can use... only truly 0 is unusable, but
    // small leftovers are low-utility.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item chains into this bin: reward proportionally.
            score -= 30.0 + 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else {
            // Leftover too small for the next item: penalize dead space.
            score += 15.0 * dead_frac;
        }
        // Extra reward if next item would EXACTLY fill the remainder.
        if next_item_size == post_residual {
            score -= 150.0;
        }
    }

    // Last-chance logic: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 120.0;
    }

    // Penalize opening a new bin when decent alternatives exist,
    // unless the item is large and would leave a tight fit anyway.
    if is_new_bin {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        // Opening a new bin costs more early in the stream and when many
        // bins are already open with slack.
        score += 80.0 + 40.0 * (1.0 - progress) + 10.0 * pressure;
        // But a large item that wastes little space in a fresh bin is okay.
        score -= 60.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Mild preference for bins whose residual is close to mean residual
    // (keep a balanced portfolio of open bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for tighter bins overall (best-fit flavor).
    score += 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap;
    let fit_ratio = item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr as f64;
    score += (x * x) * cap * (0.35 + 0.65 * progress);
    score -= (x * x * x) * cap * 0.4 * (1.0 - progress);
    score += fit_ratio * 8.0 * (1.0 - progress);

    // Reward tight fits smoothly
    score -= 20.0 * (-x * 6.0).exp();

    // Lookahead coupling: penalize post_residual that cannot host next item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let usable = if x >= nx { 1.0 } else { 0.25 };
        score += (1.0 - usable) * (5.0 + 25.0 * nx * (1.0 - progress));
        score -= usable * 10.0 * x * nx;
    }

    // Scarcity pressure: if few fitting bins, reward using this one
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mild penalty for opening new bins late in the stream
    if bin_residual == bin_capacity {
        score += 3.0 + 12.0 * progress + 0.5 * open_bins_count as f64;
    }

    // Mean-residual alignment term
    score += 0.1 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "reusable"
    // residue classes (large enough for typical future items) are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: leftover too small to be useful for small items (1..=10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic classes: bucket post_residual by integer division thresholds.
    // Class 0: pr in [0,10)  -> nearly full, great
    // Class 1: pr in [10,25) -> fits small items
    // Class 2: pr in [25,50) -> medium utility
    // Class 3: pr in [50,100] -> half-empty, wasteful unless big item
    let class = post_residual / 25;
    score -= match class {
        0 => 30.0,
        1 => 15.0,
        2 => 5.0,
        _ => 0.0,
    };

    // Reward when post_residual exactly accommodates the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 25.0 - slack;
        } else {
            score += slack * 0.1;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Leftover unusable by next item: mild penalty scaled by how much is wasted.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin wastes mean residual elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score = cap * 0.9;
        // If many bins are open with lots of residual space, opening new is bad.
        score += open_bins_count as f64 * 2.0 + mean_residual * 0.5;
        // If no existing bin fits (fitting_bins_count == 0 in that case the
        // new-bin call is the only candidate anyway), allow it.
        if fitting_bins_count == 0 {
            score -= cap; // effectively the only option
        }
        // Early in stream, opening bins is cheap (need spread).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 30.0;
        // Big items (hard to pack later) justify fresh bins.
        if item_size > cap * 0.5 {
            score -= 15.0;
        }
    }

    // Prefer tighter existing fits overall: closeness of item to residual.
    let tightness = (bin_residual - item_size) as f64 / cap;
    score += tightness * 10.0;

    // Mean-residual coupling: placing into a bin with residual far above mean
    // is good (reduces variance of leftovers).
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= dev * 0.2;
    } else {
        score += (-dev) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible item are pure waste — penalize them quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin exactly.
        score -= 30.0;
    } else {
        // Usable residual: mild reward proportional to how well the item fills
        // the bin (tight fit favored over loose fit).
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= fill_ratio * 15.0;
    }

    // Dead space relative to bin capacity: large leftover gaps that no future
    // small item may exploit are mildly penalized.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += dead * dead * 10.0;

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual {
            // Next item won't fit here — this residual becomes dead space
            // for the immediate future; penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.3;
        } else {
            score -= 5.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when few
    // alternatives exist; encourage using the last fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }
    score += open_bins_count as f64 * 0.5;

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already crowded — prefer it to consolidate space.
    score -= (mean_residual - bin_residual as f64) * 0.4;

    // New-bin candidate: penalize opening a new bin unless the current
    // placement would create severe dead space. Baseline cost of a fresh bin.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if all open bins would leave tiny unusable gaps, opening a
        // fresh bin is attractive: relax the penalty.
        if fitting_bins_count > 0 {
            let best_gap_penalty = 35.0; // potential dead-space cost avoided
            if post_residual < 10 || post_residual >= bin_capacity {
                score -= best_gap_penalty;
            }
        }
    }

    // Stream progression: later in the stream, waste matters more (fewer
    // chances to recover), tighten dead-space penalties.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as i64 >= next_item_size as i64 {
            // next item fits after this placement: reward tightness of that fit
            score -= 150.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit: penalize proportionally to the shortfall
            score += 0.5 * gap;
        }
    }

    // Prefer bins tighter than the mean residual (better packing)
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Encourage consolidation when many bins are open
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when item is large or no tight fit exists
    if bin_residual == bin_capacity {
        score += 40.0 + 0.5 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

