    // nor is large enough to be useful later.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as u32 >= next_item_size {
            // next item fits perfectly in the leftover -> strong bonus
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / cap);
        } else {
            // leftover too small for next item: dead-space penalty grows with stream progress
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += (8.0 + 22.0 * progress) * tightness;
