    // Last-chance bin: strongly favor using the only bin that fits, avoid opening new.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate logic: only attractive when existing residuals are bloated
    // or this bin would be a near-perfect host for the current item.
    if bin_residual == bin_capacity {
        let waste = item_size as f64 / cap;
        let avg_bloat = mean_residual / cap;
        // prefer new bin when open bins have lots of residual (fragmented) but
        // penalize opening bins for small items early in the stream
        score += 20.0 * (1.0 - waste) - 15.0 * avg_bloat;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress);
        // large items justify fresh bins
        if item_size >= (bin_capacity * 3 / 5) {
            score -= 12.0;
        }
    } else {
        // Favor bins whose residual is close to item size (minimal waste)
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 20.0 * fit_ratio * fit_ratio;
        // mildly prefer bins below mean residual (consolidate emptier bins)
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
        // discourage spreading across many open bins when few fitting bins exist
        if fitting_bins_count > 1 {
            score += 2.0;
        }
    }

    // Global pressure: with many open bins, keep filling existing ones.
    score += (open_bins_count as f64).sqrt() * 1.5 * tightness;

    // Small deterministic tie-breaker based on residual structure.
    score += (post_residual % 7) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let fit = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = 1.0 + t * (0.6 - 0.9 * t); // smooth bump peaking mid-stream
    score += 12.0 * poly * fit * (1.0 - fit);

    // Penalize large wasted residual late in stream (dead space less likely to be used)
    score += (pr * pr) / cap * (0.3 + 0.7 * t);

    // Reward tight fits (small post_residual) especially when item nearly fills bin
    score -= (cap - pr) * 0.25 * (1.0 + t);

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 8.0 * (next_item_size as f64 / cap) * (1.0 - t * 0.5);
        } else {
            score += 4.0 * (1.0 - pr / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + t);
    }

    // Slight penalty for spreading across many open bins relative to mean residual
    score += (open_bins_count as f64).ln() * (pr - mean_residual).abs() * 0.05;

    // New-bin candidate: prefer it only when no open bin fits well
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let mut score = post_f;

    // Harmonic class of post_residual: residues mod 10 (classic dead-space classes)
    let r10 = post_residual % 10;
    // Small nonzero residues are dead space; exact zero is perfect fit
    score += match r10 {
        0 => -12.0,
        1 | 9 => 6.0,
        2 | 8 => 4.0,
        3 | 7 => 2.5,
        _ => 0.0,
    };

    // Integer-division threshold coupling: how well next_item_size divides into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let k = post_residual / next_item_size;
        let rem = post_residual % next_item_size;
        // Reward bins whose leftover chains with the next item
        score -= 8.0 + 4.0 * (k as f64).min(3.0);
        score -= (rem as f64) * 0.05; // slight preference for tighter chain fits
    } else if next_item_size > post_residual {
        // Next item cannot use this leftover: penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Capacity fraction classes: reward leaving fractions that are "friendly" (multiples of 25)
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else {
        // More competition for this bin -> mild penalty to break ties toward best fit
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // New-bin candidate logic: only prefer a fresh bin when current leftovers are hopeless
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline: opening a bin costs; make it unattractive unless item is huge relative to mean residual
        score = 55.0
            - 0.3 * mean_residual
            + if item_size as f64 > mean_residual + 25.0 { -30.0 } else { 0.0 }
            + if next_item_size > 0 && next_item_size >= item_size { 10.0 } else { 0.0 };
    }

    // Tightness reward: smaller post_residual relative to capacity is better
    score += post_f / cap_f * 10.0;

    // Stream progression: late in stream, prefer consolidating (close bins tightly)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0 * (1.0 - post_f / cap_f);

    // Many open bins: discourage spreading, reward filling existing ones
    if open_bins_count > 4 {
        score += 0.4 * (open_bins_count as f64 - 4.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are worse than large leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    } else if post_residual == 0 {
        score -= 15.0; // perfect fit reward
    }

    // Reward tight fits relative to item size.
    score -= (item_size as f64 / bin_capacity as f64) * 8.0;

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Last chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: prefer opening a new bin only when all open fits are poor.
    if bin_residual == bin_capacity {
        score = 100.0 - (item_size as f64) * 0.3;
        if post_residual < 10 {
            score -= 10.0;
        }
        if fitting_bins_count == 1 {
            score += 30.0; // don't abandon the only fitting bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // lookahead: next item may pair with this one
        }
    } else {
        // Favor bins whose residual stays compatible with the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 4.0;
        }
        // Prefer bins below mean residual (tighter bins first).
        score += (post_residual as f64 - mean_residual) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is good.
    score -= 40.0 * (1.0 - (post_residual as f64) / cap).max(0.0) * (1.0 - (post_residual as f64) / cap).max(0.0);

    // Aggressive 2-step lookahead: strongly reward exact match post_residual == next_item_size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual as i64 - next_item_size as i64) as f64;
        score -= 30.0 * (1.0 - diff / cap).max(0.0);
        // Perfect chain: next item fills bin completely.
        if post_residual == next_item_size {
            score -= 50.0;
        }
    } else if next_item_size > 0 {
        // Penalize leaving residual that next item cannot use (dead space).
        score += 25.0 * (next_item_size as f64 - post_residual as f64) / cap;
    }

    // Relative to mean residual: prefer bins with residual close to item need, avoid wasting large-residual bins on tiny items.
    if mean_residual > 0.0 {
        let rel = (bin_residual as f64 - item_size as f64) / mean_residual;
        score += 5.0 * rel.abs();
    }

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless no decent fit exists.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Still allow new bin if lookahead would chain perfectly into it.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0;
        }
    }

    // Late in stream: prefer closing bins tightly, discourage proliferation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 8.0 * open_bins_count as f64 / (open_bins_count as f64 + 5.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-perfect fits strongly (non-linear).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    if tightness > 0.85 {
        score -= 12.0 * (tightness - 0.85) * 6.67;
    }

    // Dead-space penalty for awkward mid-size leftovers that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 4.0; // small leftovers are near-dead anyway, but finishing a bin is fine
    } else if post_residual >= 10 && post_residual <= 30 {
        score += 6.0 * (1.0 - (post_residual as f64 - 10.0) / 20.0); // awkward zone
    }

    // Lookahead coupling: favor placements that still allow the next item to fit.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0;
            if post_residual >= next_item_size && post_residual < next_item_size + 10 {
                score -= 2.0; // next item fills it almost perfectly
            }
        } else {
            score += 2.5; // next item won't fit here afterwards
        }
    }

    // Last-chance bonus: only fitting bin, avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin unless current bins fit badly.
    if bin_residual == bin_capacity {
        let avg_fit = mean_residual - item_size as f64;
        if avg_fit >= 0.0 {
            score += 20.0 + avg_fit * 0.3; // open bins can still take it decently
        } else {
            score -= 5.0 + (-avg_fit) * 0.2; // poor fits everywhere -> prefer new bin
        }
    }

    // Global state: many open bins with high mean residual -> prefer consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 3 && mean_residual > 30.0 && bin_residual < bin_capacity {
        score -= 2.0 + 3.0 * progress;
    }

    // Time horizon: early on, keep bins flexible (avoid tiny residuals); late, allow packing tight.
    score += (1.0 - progress) * 0.05 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth polynomial coupling: penalize wasted residual more as stream progresses
    let waste = pr / cap;
    score += 8.0 * waste * waste * (0.5 + progress);

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 6.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * progress;
    }

    // Lookahead: penalize leaving residual that neither fits next item well nor is tiny
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            // next item fits: reward residual close to next size (smooth coupling)
            let d = (pr - nx) / cap;
            score -= 4.0 * (1.0 - d * d);
        } else {
            // dead space relative to lookahead: penalize quadratically
            let d = (pr - nx) / cap;
            score += 5.0 * d * d;
        }
    }

    // Prefer filling bins with small mean residual (nearly full bins) slightly more
    score += 0.05 * (mean_residual - pr);

    // Mild penalty for proliferating bins late in stream
    score += 0.02 * open_bins_count as f64 * progress;

    // New-bin candidate: make empty bin less attractive unless residuals are poor
    if bin_residual == bin_capacity {
        score += 3.0 + 4.0 * progress + 0.05 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (harmonic class: post_residual in {0, small})
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Harmonic class of post_residual: residue classes modulo 10.
    // Small residues (1..5) are more likely reusable by small items; large residues are dead-ish.
    let pr_mod = post_residual % 10;
    score -= (5 - pr_mod as i32).abs() as f64 * 2.0;

    // Penalize post_residual that no typical item can use (dead space window)
    // Items are 1..100; a residual < some plausible small item is still usable, but
    // residuals in the "gap" just below common item sizes are wasteful.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0; // tiny sliver, nearly unusable
    }

    // Lookahead: reward if next item fits exactly or well into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let next_left = post_residual - next_item_size;
            score -= 20.0 - next_left as f64 * 0.5;
        } else {
            // next item won't fit here; mild penalty proportional to overflow gap
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    // Opening a new bin is only attractive when the fit here is terrible.
    if bin_residual == bin_capacity {
        // base cost of opening a bin, discounted when many bins already open
        score = cap * 0.9 + open_bins_count as f64;
        // if current item would leave a great residual in a fresh bin, slightly cheaper
        if post_residual <= 10 {
            score -= 20.0;
        }
    } else {
        // Reward filling existing bins proportionally to how full they become
        let fill = (bin_capacity - post_residual) as f64 / cap;
        score -= fill * 30.0;

        // Mild penalty for spreading across too many open bins when mean residual is high
        if (post_residual as f64) > mean_residual {
            score += 3.0;
        }
    }

    // Slight preference to consolidate early in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item (1..=100)
    // are pure waste. Penalize small-but-nonzero gaps hard.
    if post_residual > 0 {
        // A residual below the minimum conceivable item size is dead space.
        if post_residual < 10 {
            score += 40.0 * (10.0 - post_residual as f64);
        }
        // Small residuals that only fit tiny items are nearly dead.
        if post_residual < 25 {
            score += 15.0 * (25.0 - post_residual as f64) / 25.0;
        }
    }

    // Reward tight fits: post_residual near zero is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Fractional fill quality: favor bins where item occupies most of residual.
        let fill = item_size as f64 / bin_residual.max(1) as f64;
        score -= 25.0 * fill;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // bins rather than spreading; with few bins, new bins are cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure penalty.
        score += 20.0 + 12.0 * pressure;
        // If no open bin fits well, new bin becomes attractive: the heuristic
        // still competes via base score; give slight relief when many bins open.
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    } else {
        score -= 8.0 * pressure.min(3.0);
    }

    // Lookahead (k=2): if the next item fits exactly in the post-residual,
    // this placement sets up a perfect chain — reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            if gap < 10.0 {
                score -= 20.0 * (1.0 - gap / 10.0);
            }
        } else {
            // Next item won't fit here; if post_residual is tiny it's dead space,
            // already penalized above; add mild extra penalty.
            if post_residual < next_item_size && post_residual > 0 {
                score += 6.0;
            }
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (i.e., fuller bins) to keep the bin set tight.
    score += 0.3 * (mean_residual - bin_residual as f64).max(-30.0).min(30.0);

    // Mild stream-progression effect: late in the stream, be more conservative
    // about opening bins (less time to amortize them).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact fit / tiny post residual
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // 2-step lookahead: if next item fits perfectly in the post residual, reward heavily
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 150.0 - slack as f64 * 8.0;
            } else {
                // penalize leaving a residual that barely fails to fit next item
                if post_residual < next_item_size + 20 {
                    score += (next_item_size as f64 - post_residual as f64) * 2.0;
                }
            }
        } else {
            // next item cannot fit in leftover: mild penalty scaled by gap
            score += (next_item_size as f64 - post_residual as f64) * 1.5;
        }
    } else {
        // last item: strongly prefer tightest fit
        score -= 50.0;
    }

    // Prefer bins tighter than the mean residual (fill the fullest bins first)
    score += (mean_residual - bin_residual as f64) * 0.8;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is poor
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 30.0;
        if poor_fit {
            score -= 40.0; // allow opening a new bin for large leftovers
        } else {
            score += 120.0; // discourage wasteful new bins on good fits
        }
    }

    // Mild preference to keep number of open bins low as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fraction of capacity filled by this item
    let fill = item_size as f64 / cap;
    let post_frac = post_residual as f64 / cap;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 8.0 * (1.0 - post_frac) * (0.5 + progress);

    // Penalize dead space: post_residual too small to be useful for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward;
    // if next item cannot fit, penalize slightly (wasted pairing opportunity)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size < post_residual {
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            score += 3.0 * (next_item_size - post_residual) as f64 / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Competition pressure: many open bins -> prefer filling existing ones,
    // avoid opening new bins unless current fit is poor
    score += open_bins_count as f64 * 0.5 * post_frac;

    // Mean residual coupling: if this bin's residual is far below mean, it's
    // already fragmented; prefer bins with residual near mean for balance
    let res = bin_residual as f64;
    let dev = (res - mean_residual).abs();
    score += 0.3 * dev;

    // New-bin candidate handling: empty bin gets a moderate baseline cost so it
    // only wins when existing fits are bad (their scores inflated by dead space)
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * progress;
        // If nothing else fits, the last-chance logic doesn't apply to new bin,
        // but a large item justifies a fresh bin
        if fill > 0.5 {
            score -= 8.0;
        }
    }

    // Mild non-linear penalty on very small fill ratios late in the stream
    if fill < 0.2 && progress > 0.5 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer minimal post-residual (tight fit), smoothly normalized.
    let mut score = post / cap;

    // Reward tight fits more strongly as the stream progresses (smooth coupling).
    let tightness = 1.0 - post / cap;
    score -= 0.6 * tightness * (0.5 + progress);

    // Penalize dead space: post_residual smaller than next item but nonzero
    // is wasted; smooth quadratic penalty scaled by progress.
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = (nxt - post).max(0.0) / cap;
        let dead = if post < nxt { post / nxt } else { 0.0 };
        score += 0.35 * gap * (1.0 - dead) * (0.4 + progress);
        // Bonus if this placement leaves room exactly useful for next item.
        let usable = if post >= nxt { post / cap } else { 0.0 };
        score -= 0.25 * usable * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 1.2;
    }

    // New-bin candidate: smooth cost that grows with open bins count and
    // shrinks with progress (late in stream, consolidating is better).
    let is_new = bin_residual == bin_capacity;
    if is_new {
        score += 0.5 + 0.05 * open_bins_count as f64 * (1.0 - progress) - 0.4 * progress;
    } else {
        // Mild preference for bins below mean residual (balance load).
        score += 0.1 * ((post - mean_residual) / cap);
    }

    // Smooth non-linear interaction: post_residual^2 normalized, penalizing
    // large leftovers quadratically but softly.
    score += 0.15 * (post / cap) * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: strongly favor small post_residual (non-linear).
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / bin_capacity as f64;

    // Harmonic class: reward near-perfect fits via modular thresholds on post_residual.
    let cap = bin_capacity as f64;
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual % 10 == 0 {
        score -= 8.0; // residual reusable by common size classes
    }

    // Lookahead: exact match between residual and next item is golden.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            score -= 12.0 * (1.0 - (pr - nx) / cap);
        } else {
            // dead space the next item cannot use
            score += 10.0 + 0.2 * nx;
        }
    } else {
        // last item: waste minimization only
        score += 5.0 * pr / cap;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // few bins fit the item or the current bin would leave a bad residual.
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity - item_size;
    if is_new_bin {
        // Penalize opening new bins generally; the empty-bin residual is large
        // already, so this keeps it from winning against decent fits.
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced: no open bin fits
        } else if fitting_bins_count == 1 {
            // last-chance bin vs new bin: prefer last-chance slightly
            score += 5.0;
        }
        // Late in stream, avoid opening bins for tiny items
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size <= 20 && progress > 0.8 {
            score += 20.0;
        }
    } else {
        // Reward using existing bins, especially when they are the scarce option.
        if fitting_bins_count == 1 {
            score -= 35.0;
        } else if fitting_bins_count == 2 {
            score -= 10.0;
        }
        // Prefer filling bins whose residual is below the mean (tight bins).
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        }
    }

    // Mild penalty for many open bins to discourage sprawl.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (small but nonzero, unlikely to fit future items) are heavily penalized.
    let dead_zone_lo = 0.0f64;
    let dead_zone_hi = 20.0f64;
    if (post_residual as f64) > dead_zone_lo && (post_residual as f64) <= dead_zone_hi {
        // Quadratic ramp inside the dead zone, worst near the top of the zone.
        let t = post_residual as f64 / dead_zone_hi;
        score += 45.0 * t * (2.0 - t);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to bin capacity (small waste fraction).
    score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64) * (item_size as f64 / bin_capacity as f64);

    // Next-item lookahead: if the next item fits exactly in post_residual,
    // strongly favor this placement (chains two items nicely).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // post_residual cannot host next item -> mild penalty scaled by waste.
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize placements that leave large residuals when many
    // bins are already open; encourage consolidating into few bins early.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Prefer bins whose residual is near the mean residual (balanced packing),
    // penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.10 * dev;

    // New-bin candidate: opening a new bin should only win if all open bins fit poorly.
    // Base new-bin score: generous but not free (empty bin residual == capacity).
    if bin_residual == bin_capacity {
        // Cost of a fresh bin grows with number of open bins and stream progress.
        score = 55.0 + 0.35 * open_bins_count as f64 + 20.0 * progress;
        // But if no open bin fits at all (this is the only candidate), it must win.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Late in the stream, opening bins is cheaper than fragmenting.
        if progress > 0.8 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to residual space in typical open bins (poor fits elsewhere).
    if bin_residual == bin_capacity {
        let waste_elsewhere = (mean_residual - item_size as f64).max(0.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 + 0.5 * waste_elsewhere - 20.0 * progress;
        return score;
    }

    // Reward tight fits: low post_residual is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual,
    // penalize near-misses that strand dead space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if diff < 1.0 {
            score -= 25.0; // perfect chain: next item fills this bin exactly
        } else if nxt <= post {
            score -= 12.0 * (1.0 - diff / 100.0); // next item fits reasonably
        } else {
            // next item won't fit here; penalize large stranded residual
            score += 0.15 * (post - 20.0).max(0.0);
        }
    }

    // Compare post_residual against mean residual: leaving less than the mean
    // is good (this bin becomes "closed-like"), leaving more is wasteful.
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.15 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Slight preference for filling bins when many bins are open.
    score -= 0.05 * open_bins_count as f64 * tightness;

    // Penalize leaving residuals that are too small to be useful (< 10).
    if post_residual < 10 {
        score -= 5.0; // bin is effectively closed: good
    } else if post_residual < 20 {
        score += 6.0; // awkward dead space zone
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Penalize leaving residual that is small but unusable (< typical minimum item size 1..100 => dead zone)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward exact-ish fills
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward this placement
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
        } else {
            // next item won't fit here; penalize wasting residual close to next item size
            let gap = (next_item_size - post_residual) as f64;
            if gap < 30.0 {
                score += 6.0 * (1.0 - gap / 30.0);
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Crowding: many open bins -> prefer consolidating into existing bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let crowd = open_bins_count as f64 / (1.0 + mean_residual.max(0.0) / bin_capacity as f64);
    score += 0.8 * crowd * (0.5 + progress);

    // Mean residual coupling: if this bin's residual is far below the mean, its space is scarcer -> use it
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // New-bin candidate handling: opening a new bin is only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        // base cost of a fresh bin, discounted when many bins already open or item is large
        let mut new_bin_cost = 55.0;
        if item_size > 60 {
            new_bin_cost -= 10.0;
        }
        if fitting_bins_count == 0 {
            new_bin_cost -= 40.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && post_residual >= 0 {
            new_bin_cost += 5.0;
        }
        score += new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Normalize residuals
    let cap = bin_capacity as f64;
    let pr_norm = post_residual as f64 / cap;
    let item_norm = item_size as f64 / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap; later, waste is penalized quadratically.
    let waste_weight = 1.0 + 2.5 * progress * progress;
    score += waste_weight * pr_norm * pr_norm * cap * 0.5;

    // Reward tight fits (small post_residual) with smooth saturating term
    let tightness = (1.0 - pr_norm).powi(3);
    score -= 8.0 * tightness * (1.0 + 0.5 * progress);

    // Lookahead: reward if next item fits the post-residual (smooth decay)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            let gap = (post_residual as f64 - nxt) / cap;
            score -= 6.0 * (1.0 - gap).powi(2);
        } else {
            // penalize leaving a residual that barely misses the next item
            let miss = (nxt - post_residual as f64) / cap;
            score += 4.0 * (1.0 - miss.min(1.0)).powi(2);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        // mild penalty to prefer keeping specialized bins open
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: neutral-ish baseline, penalized when good fits exist
    if bin_residual == bin_capacity {
        score += 3.0 + 6.0 * progress - 0.3 * mean_residual / cap;
        // discourage new bin if item is small
        score += 10.0 * (1.0 - item_norm).powi(2);
    }

    // Coupling with mean residual: prefer bins deviating smoothly from mean
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev * dev * (1.0 + progress);

    // Mild bonus for filling bins nearly full as stream ends
    let end_factor = (progress * progress * progress).min(1.0);
    score -= 5.0 * end_factor * (1.0 - pr_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
