    };

    // Dead-space penalty: residual too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 {
        if next_item_size == post_residual {
