        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.8;
        } else {
            // next item won't fit here anyway; penalize wasted residual lightly
            score += (next_item_size - post_residual).min(20) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: prefer reusing open bins unless residual is very tight
    if bin_residual == bin_capacity {
        // empty bin candidate: neutral-ish score = post_residual (100 - item)
        // penalize slightly so tight existing fits win; but keep it competitive vs bad fits
        score += 15.0;
        // if item is large, opening a fresh bin is often good
        if item_size >= bin_capacity / 2 {
            score -= 25.0;
        }
    } else {
        // reuse bonus scaled by stream progression (consolidate early)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Mean residual alignment: prefer bins whose residual is near the mean (balanced closing)
    score += (mean_residual - pr).abs() * 0.15;

    // Penalty when many bins could fit: prefer the tightest anyway (post_residual term handles it)

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

