    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well the leftover aligns with
    // typical item sizes (integer division thresholds on capacity fractions).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward small post_residual strongly (non-linear tightness bonus).
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= bin_capacity / 10 {
        score -= 35.0;
    } else if post_residual <= bin_capacity / 4 {
        score -= 15.0;
    } else if post_residual <= bin_capacity / 2 {
        score -= 5.0;
    } else {
        // Large dead space: penalize extra.
        score += 10.0;
    }

    // Modulo arithmetic: leftover classes that commonly admit another item
    // (residual mod small divisors) are more "usable".
    let usable_class = if post_residual >= 10
        && (post_residual % 10 == 0 || post_residual % 20 == 0 || post_residual % 25 == 0 || post_residual % 50 == 0)
    {
        1.0
    } else {
        0.0
    };
    score -= 8.0 * usable_class;

    // Penalize leftovers that are too small for the minimum plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space trap
    }

    // Lookahead: if the next item fits the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0 + 0.1 * (next_item_size as f64);
        } else {
            // Next item won't fit here; mildly penalize wasting a good bin.
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Make the fresh bin moderately attractive by
    // default but penalize it when good fits exist.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying as stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * 0.75 - 10.0 * progress;
        // If few bins fit the item, opening new is more acceptable.
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
        if fitting_bins_count > 2 {
            score += 20.0;
        }
        // If mean residual across open bins is large, prefer existing bins.
        score += 0.15 * mean_residual;
    } else {
        // Existing bins: slight preference when many open bins (consolidation).
        score -= 2.0 * (open_bins_count.min(10) as f64);
    }

    // Small tie-break toward tighter residual via normalized fraction.
    score += 0.05 * (pr / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item (1..=100)
    // can ever use are pure waste. Penalize small non-zero gaps super-linearly.
    if post_residual > 0 {
        // gap of 1..=9 is unusable for the smallest item -> heavy dead-space penalty
        if post_residual < 10 {
            score += 60.0 + (10 - post_residual) as f64 * 8.0;
        } else if post_residual < 20 {
            score += 20.0 + (20 - post_residual) as f64 * 2.0;
        }
    } else {
        // perfect fill: strong reward
        score -= 50.0;
    }

    // Reward tight fits relative to residual (small waste fraction).
    if bin_residual > 0 {
        let fill_frac = item_size as f64 / bin_residual as f64;
        score -= 25.0 * fill_frac;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins rather than spreading; penalize lightly per open bin.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // (avoids opening a new bin and stranding this one's residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base new-bin score: neutral-ish, scaled by stream progress so late
        // stream we are more willing to open bins for good future packing.
        score = 55.0 + 30.0 * (step_index as f64 / total_items.max(1) as f64);
        // If the next item could combine with this one in a fresh bin, boost appeal.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 15.0;
        }
        // Many open bins with large mean residual -> discourage another bin.
        if mean_residual > 30.0 {
            score += 0.5 * mean_residual;
        }
    } else {
        // Prefer bins whose residual is close to what the next item needs
        // (leave exactly a useful gap for lookahead when possible).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            // gap blocks the lookahead item: penalize proportionally
            score += 10.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward bins whose post_residual matches the next item well
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            // next item fits after this placement: reward tightness of that follow-up fit
            let follow_gap = post_residual as f64 - next;
            score -= 60.0 * (1.0 - follow_gap / bin_capacity as f64);
            if follow_gap == 0.0 {
                score -= 200.0; // exact 2-chain
            }
        } else {
            // leftover too small for next item: penalize dead space relative to next size
            score += 0.5 * (next - post_residual as f64).min(next);
        }
    }

    // Prefer bins tighter than the mean residual (good fits)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Mild penalty when many bins are open already (consolidation pressure)
    score += 0.05 * open_bins_count as f64;

    // Slight preference to keep large residual bins for future large items
    score += 0.1 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 {
        if post_residual > 0 && next_item_size > post_residual {
            score += 25.0; // dead space for lookahead item
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0; // chain placement possible
            let chained_waste = post_residual - next_item_size;
            score += 0.15 * chained_waste as f64;
        }
    } else {
        // Last item: fill as much as possible.
        score -= 20.0 * fit_ratio;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize wasting a nearly-full bin on a small item (poor fit).
    if fit_ratio < 0.35 && bin_residual < bin_capacity {
        score += 15.0 * (0.35 - fit_ratio);
    }

    // New-bin candidate handling: opening a new bin is expensive; only attractive
    // early in the stream or when many bins are open and this is a poor fit elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit_elsewhere = (fitting_bins_count as f64) <= 1.5;
        let crowding = (open_bins_count as f64 / 20.0).min(1.0);
        let new_bin_bonus = 60.0 * (1.0 - progress) + 25.0 * crowding;
        if poor_fit_elsewhere {
            score -= new_bin_bonus;
        } else {
            score += 80.0; // keep using existing bins when they fit reasonably
        }
    }

    // Mild global pressure: when mean residual is large, prefer bins above the mean
    // (consolidate waste); when mean residual is small, prefer bins below the mean.
    if bin_residual < bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.08 * diff;
    }

    // Slight time-dependent tightness: as stream progresses, demand tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Tight fit reward: strongly favor bins whose post-residual is small
    let tightness = (1.0 - pr_norm).powi(3);
    score -= 2.5 * tightness * cap;

    // Non-linear penalty on dead space that is too small to be useful later
    // (quadratic coupling of post_residual with stream progress)
    let dead = pr_norm * (1.0 - pr_norm) * 4.0; // peaks at half-full residual
    score += 12.0 * dead * (0.3 + 0.7 * progress);

    // Lookahead: reward if next item fits exactly into post-residual (perfect chaining)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as f64 >= nxt {
            let slack = (pr as f64 - nxt) / cap;
            score -= 6.0 * (1.0 - slack).powi(2);
        } else {
            // next item cannot use the leftover: mild penalty scaled by leftover size
            score += 3.0 * pr_norm * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 6.0 * progress;
    }

    // New-bin candidate: penalize slightly early, more later (prefer consolidation),
    // but allow opening when existing bins would create large dead space
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
        // if best existing fit would leave big residual, opening is attractive:
        score -= 0.5 * mean_residual * 0.1;
    } else {
        // prefer bins with below-mean residual (better consolidation)
        score += 0.3 * (mean_residual - bin_residual as f64);
    }

    // Mild penalty for proliferating bins
    score += 0.15 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes mod 10
    let pr = post_residual;
    let class = (pr % 10) as f64;
    // Residuals that are "usable" for typical small items (>= 10) get rewarded
    if pr >= 10 {
        score -= 8.0 + 0.3 * (100.0 - class) / 10.0;
    } else {
        // dead space penalty: residual < 10 is nearly unusable
        score += 12.0 + (10 - pr) as f64 * 2.0;
    }

    // Exact-fit harmonic classes: post_residual divisible by 10 is ideal
    if pr % 10 == 0 {
        score -= 15.0;
    } else if pr % 5 == 0 {
        score -= 7.0;
    }

    // Coupling with next item: reward if next item fits post_residual
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 10.0 + (pr - next_item_size) as f64 * 0.2;
        } else {
            score += (next_item_size - pr) as f64 * 0.15;
        }
        // harmonic threshold: next item exactly fills remaining space
        if next_item_size == pr {
            score -= 20.0;
        }
    } else {
        // last item: prefer fullest packing
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Tightness: fraction of bin consumed by this placement
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= fill * 10.0;

    // New-bin candidate: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        score = 55.0
            - 0.5 * (fitting_bins_count as f64)
            + 0.3 * (open_bins_count as f64)
            + 0.4 * mean_residual;
        if next_item_size > item_size {
            score -= 5.0; // big next item: fresh bin may be fine
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for even the smallest plausible item are waste.
    // Items can be as small as 1, so weight waste by how "unusable" the gap is.
    let dead_threshold = 10.0_f64;
    if (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64);
    }

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        score -= 0.5 * (item_size as f64 / (item_size as f64 + post_residual as f64)) * 10.0;
    }

    // Lookahead coupling: if the next item fits perfectly in the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 30.0; // perfect chaining
        } else {
            score -= 15.0 * (1.0 - slack as f64 / post_residual as f64);
        }
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // Next item won't fit here: this residual becomes dead space unless another bin takes it.
        score += 8.0;
    }

    // Open bins pressure: discourage spreading across many bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * open_bins_count as f64 * (0.5 + progress);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are all poor fits.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If many open bins have large residuals, opening new bin is wasteful.
        score += 0.2 * mean_residual;
        // But if few fitting bins exist, new bin is more acceptable.
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + diff * 0.15);
        // Penalize residuals that are large but unusable for the next item.
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // Last item: reward tightest fit only.
        score -= 20.0;
    }

    // Reward residuals below mean (tight packing), penalize above.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins can fit,
    // scaled by stream progress and how many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (post_residual as f64 / bin_capacity as f64) * (1.0 + 0.5 * progress);
        score += 15.0 + 10.0 * (open_bins_count as f64).ln().max(0.0) - 20.0 * pressure;
        // Opening a new bin is fine if it would be well used by the next item.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    score
}
